var e=JSON.parse(`[{"id":"scen-hund-wetterfuehlig","title":"Hundebesitzerin Moni und die Erdbeben-Hündin","subtitle":"Tiere ahnen Katastrophen, geübt mit Neuroplastizität und Konzentration","character":"Moni","avatar":"🐕","context":"Beim Gassigehen im Park triffst du deine Nachbarin Moni. Sie erzählt dir gut gelaunt, ihre Hündin Luna habe sich gestern Abend ganz komisch benommen. In der Nacht darauf gab es hier in der Region ein leichtes Erdbeben, heute früh kam es in den Nachrichten, und für Moni ist klar: Hunde spüren sowas Stunden vorher.","goal":"Bring Moni mit der Aktivierungs-Frage des Überlebensirrtums dazu, selbst nach den vielen Tagen zu fragen, an denen Luna komisch war und nichts passierte, ohne sie oder ihre Hündin vorzuführen.","bereich":"Nachbarschaft","laenge":"kurz","ton":"heiter","bestehenAb":4,"lektion":"Erzählt werden die Treffer, nicht die vielen Abende, an denen der Hund komisch war und nichts geschah. Genau das ist der Überlebensirrtum: Die Fehlalarme sind unsichtbar, die eine passende Geschichte bleibt hängen. Mit der Frage „Wo ist der Friedhof?“ und echter Neugier kann Moni selbst nachzählen, und ihre Luna bleibt dabei trotzdem ihr Schatz.","toolRef":"H.1.5","faktenRef":"B.15","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Moni","speech":"„Stell dir vor, gestern Abend ist Luna total unruhig durch die Wohnung getigert und hat gewinselt. Und was kam heute früh in den Nachrichten? Ein Erdbeben, hier bei uns in der Region! Hunde spüren sowas Stunden vorher, das ist doch bewiesen!“","options":[{"text":"„Moni, das ist doch Zufall. Luna hatte einfach einen schlechten Abend, mehr nicht.“","style":"frontal","reaction":"„Ach, du Besserwisser! Luna ist keine Zufallshündin, ich kenne mein Tier! Ich glaub, dir fehlt einfach der Draht zu Tieren.“ *zieht beleidigt an der Leine*","feedback":"Frontal und ohne Frage: Moni fühlt sich und Luna abgewertet. Die Aktivierungs-Frage des Überlebensirrtums kommt gar nicht erst zum Zug.","score":-2,"nextStepId":"step-fail"},{"text":"„Das klingt echt eindrucksvoll. Wie oft war Luna denn in den letzten Monaten so unruhig? Und wie oft hat es danach gebebt?“","style":"sokratisch","reaction":"„Hm, wie oft... Na ja, sie ist schon öfter mal nervös, bei Gewitter, bei Silvester, manchmal auch ohne Grund. Aber diesmal war es ein Erdbeben!“ *runzelt die Stirn*","feedback":"Stark: Du fragst nach den unsichtbaren Tagen und lässt Moni selbst zählen. Das ist die Aktivierungs-Frage aus „Der Überlebensirrtum“ im Kleinformat, verpackt als echte Neugier.","score":3,"nextStepId":"step-2"},{"text":"„Wahnsinn! Dann sollten wir Luna als Frühwarnsystem einsetzen. Sag mir bitte immer Bescheid, wenn sie winselt, dann packe ich meinen Notfallkoffer.“","style":"humorvoll","reaction":"„Haha, genau! Luna rettet uns alle!“ *strahlt und tätschelt Luna* „Siehst du, mein Mädchen, der Nachbar glaubt an dich!“","feedback":"Nett gemeint, aber du bestärkst den Mythos. Ohne die Frage nach den Fehlalarmen bleibt der Überlebensirrtum unangetastet.","score":-1,"nextStepId":"step-fail"}]},"step-2":{"id":"step-2","speaker":"Moni","speech":"„Na gut, unruhig ist sie öfter. Aber so viele Erdbeben gibt's ja auch nicht, deshalb ist das eine besondere Geschichte! Und alle meine Hundefreundinnen kennen auch so einen Fall. Das kann doch kein Zufall sein!“","options":[{"text":"„Spannende Geschichten! Aber wo sind eigentlich die Abende, an denen der Hund komisch war und nichts passiert ist? Hört man die im Hundepark auch?“","style":"sokratisch","reaction":"„Die...? Hm. Nein, die erzählt ja keiner. 'Luna hat gewinselt und nix ist passiert', das ist keine Geschichte.“ *lacht verlegen* „Oh. Dann kennen wir ja nur die Treffer, oder?“","feedback":"Treffer! Das ist die Aktivierungs-Frage von „Der Überlebensirrtum“, nur freundlicher formuliert: Die Fehlalarme erzählt niemand, deshalb erscheinen die Treffer häufiger, als sie sind. Moni findet es selbst heraus.","score":3,"nextStepId":"step-success"},{"text":"„Das ist der Überlebensirrtum, Moni. Du siehst nur die Erfolge und ignorierst die Misserfolge. Genau wie bei den Bombern im Zweiten Weltkrieg.“","style":"frontal","reaction":"„Bomber? Was haben denn Bomber mit meiner Luna zu tun? Du redest immer so kompliziert, ich will einfach nur spazieren gehen!“","feedback":"Der Begriff stimmt, aber du belehrst im Fachjargon und lieferst das Etikett vor der Einsicht. Moni steigt aus, statt selbst zu denken.","score":0,"nextStepId":"step-struggle"},{"text":"„Wenn alle deine Freundinnen so einen Fall kennen, wird da bestimmt was dran sein. Vielleicht sollte man mal einen Verein gründen.“","style":"humorvoll","reaction":"„Das ist eine tolle Idee! Ich frag gleich mal die Gruppe, ob Luna und die anderen beim nächsten Beben aufpassen!“","feedback":"Du bestätigst das Muster der Hundefreundinnen, ohne zu fragen, wer die stillen Tage mitzählt. So wächst der Mythos mit jeder erzählten Anekdote weiter.","score":-2,"nextStepId":"step-fail"}]},"step-success":{"id":"step-success","speaker":"Moni","speech":"„Du, das lässt mich nicht los. Ich fange mal an, in meinem Handy zu notieren, wann Luna unruhig ist und was dann passiert. Mal sehen, wie das ausgeht. Willst du die Liste nachher sehen?“","options":[{"text":"„Unbedingt, und schreib die ruhigen Abende auch mit, damit wir ein vollständiges Bild bekommen. Ich bin gespannt auf deine Hunde-Statistik!“","style":"sokratisch","reaction":"„Abgemacht! Luna wird wissenschaftlich begleitet.“ *lacht* „Komm, Luna, wir gehen noch eine Runde!“","feedback":"Perfekter Abschluss: Du lädst zum eigenen Nachprüfen ein, Moni behält ihr Gesicht und ihr Bild von Luna, und der Blick fürs Unsichtbare ist geschärft.","score":3}]},"step-struggle":{"id":"step-struggle","speaker":"Moni","speech":"„Ich weiß nicht, ich will eigentlich nur eine nette Geschichte erzählen. Aber jetzt klingt das, als hätte ich was Falsches gesagt...“","options":[{"text":"„Gar nicht, die Geschichte ist nett, und Luna ist eine tolle Hündin. Ich bin nur neugierig geworden, ob sie öfter unruhig ist. Erzähl mir bei Gelegenheit mehr!“","style":"deeskalierend","reaction":"„Na gut. Ich achte mal drauf, versprochen. Und du bringst beim nächsten Mal einen Keks für Luna mit!“","feedback":"Gutes Einlenken: Die Beziehung ist heil, die Neugier bleibt offen. Die Sachfrage nach den stillen Tagen kann Moni in Ruhe selbst weiterverfolgen.","score":2}]},"step-fail":{"id":"step-fail","speaker":"Moni","speech":"„Also ich bleibe dabei: Luna spürt sowas, und das lasse ich mir nicht ausreden!“ *geht mit Luna davon*","options":[{"text":"Ende: Der Mythos hat sich gefestigt, weil niemand nach den Fehlalarmen gefragt hat.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst neugierig fragen, wie oft der Hund unruhig war und nichts passierte, und dann erst über Schlüsse reden.","feedback":"Die Treffer erzählt man, die Fehlalarme nicht. Frag nach dem „Friedhof“ der unspektakulären Tage, statt zu belehren oder zu bestätigen.","score":0}]}},"status":"entwurf","familie":"fehlende-faelle-suchen","fertigkeit":"F2","stufe":1,"kurz":"Erzählt werden die Treffer, nicht die vielen Abende, an denen ein Tier unruhig war und nichts geschah. Weil diese Fehlalarme unsichtbar bleiben, wirkt eine einzelne passende Geschichte wie ein Beweis; erst das Mitzählen aller Abende macht den Vergleich möglich.","prueffrage":"Wie oft war die Hündin unruhig, ohne dass danach etwas geschah, und wer erzählt von solchen Abenden?","quellen":[{"typ":"url","kurz":"Wald, A. (1943/1980): A Reprint of „A Method of Estimating Plane Vulnerability Based on Damage of Survivors“. CNA, CRC 432","oeffentlich":true,"url":"https://cna.org/reports/1980/a-method-of-estimating-plane-vulnerability","abruf":"2026-10-12"},{"typ":"url","kurz":"GFZ Potsdam (2018): The strange behavior of animals before earthquakes (zu Woith, H.; Petersen, G. M.; Hainzl, S.; Dahm, T. (2018): Can Animals Predict Earthquakes? BSSA 108(3A), DOI 10.1785/0120170313)","oeffentlich":true,"url":"https://www.gfz.de/en/press/news/details/the-strange-behavior-of-animals-before-earthquakes/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Mangel, M.; Samaniego, F. J. (1984): Abraham Wald's Work on Aircraft Survivability. JASA 79(386), 259–267","oeffentlich":false,"doi":"10.1080/01621459.1984.10478038"}],"thema":"Natur und Klima"},{"id":"scen-nachbarschaftschat-einbrueche","title":"Der Nachbarschaftschat schlägt Alarm","subtitle":"Verfügbarkeitsheuristik, geübt mit der Deeskalations-Matrix","character":"Gabi, Administratorin des Straßenchats","avatar":"🚨","context":"Du wohnst seit Jahren in einer ruhigen Straße. Gabi, die den Nachbarschaftschat betreut, fängt dich am Gartenzaun ab. Sie ist aufgebracht: In den letzten Wochen sind im Chat mehrere Meldungen über verdächtige Gestalten und einen Einbruch zwei Straßen weiter aufgetaucht. Für sie steht fest: Hier wird ständig eingebrochen.","goal":"Beruhige Gabi durch Deeskalation und bring sie dazu, ihren Eindruck selbst an der tatsächlichen Häufigkeit zu prüfen (Verfügbarkeitsheuristik).","bereich":"Nachbarschaft","laenge":"mittel","ton":"ernst","bestehenAb":6,"lektion":"Was leicht in den Sinn kommt, fühlt sich häufig an: Lebhafte, frische Meldungen, die sich im Chat wiederholen, erzeugen den Eindruck einer Einbruchswelle, auch wenn die Zahlen etwas anderes sagen können (Verfügbarkeitsheuristik). Wer erst Gabis Sorge validiert, Ich-Botschaften nutzt und eine Gemeinsamkeit betont (Deeskalations-Matrix), schafft den Raum, in dem die Frage nach den langweiligen Statistiken überhaupt gehört wird. Ihre Sorge ist verständlich, ihr Eindruck ersetzt aber keine Statistik.","toolRef":"H.2.1","faktenRef":"B.3","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Gabi","speech":"„Das glaubst du nicht! Schon wieder eine Meldung im Chat: ein Mann mit Kapuze, der an Gartentoren gerüttelt hat. Bei uns wird ständig eingebrochen, das sieht doch jeder an den Meldungen! Und alle tun so, als wäre nichts!“","options":[{"text":"„Gabi, das ist doch Panikmache. Ein Kerl mit Kapuze ist noch kein Einbrecher, und von ständigen Einbrüchen kann keine Rede sein. Du regst dich über Kleinigkeiten auf.“","style":"frontal","reaction":"„Kleinigkeiten?! Du nimmst mich gar nicht ernst! Wenn bei dir eingebrochen wird, bin ich die Letzte, die dir hilft!“","feedback":"Das ist ein Frontalangriff auf Gabis Gefühl. Wer Sorge als „Panikmache“ abtut, eskaliert statt zu deeskalieren; die Sachfrage geht im Streit unter.","score":-2,"nextStepId":"step-fail"},{"text":"„Ich höre, wie sehr dich das beunruhigt, und ich finde es gut, dass du dich um die Straße kümmerst. Magst du mir erzählen, was in den letzten Wochen genau gemeldet wurde?“","style":"deeskalierend","reaction":"„*atmet durch* Ja, das ist es eben. Es fängt an, dass man abends gar nicht mehr gern rausgeht. Also... da war der Einbruch in der Lindenstraße, dann die Kapuzengestalten...“","feedback":"Sehr gut: Du validierst das Gefühl, nicht den Inhalt, und lässt Gabi selbst aufzählen. So wird sichtbar, was ihr Eindruck eigentlich speist.","score":3,"nextStepId":"step-2"},{"text":"„Echt jetzt? Dann lass uns sofort Wachdienste organisieren und jeden Abend Streife laufen. Ich schließe heute Nacht gar nicht mehr ab, sondern sitze am Fenster!“","style":"affektiv","reaction":"„Ja! Endlich versteht mich jemand! Ich schreibe gleich in den Chat, dass wir ab jetzt alle aufpassen müssen!“","feedback":"Du übernimmst die Aufregung und heizt sie an. Mitempörung ist keine Deeskalation; die Stimmung kippt, und Gabi sieht sich in ihrem Eindruck bestätigt.","score":-1,"nextStepId":"step-panic"}]},"step-2":{"id":"step-2","speaker":"Gabi","speech":"„Also, der Einbruch in der Lindenstraße, die Nachbarin hat ja alles genau beschrieben, mit der aufgebrochenen Terrassentür und dem Schock. Und dann ständig diese Warnungen im Chat. Wenn das nicht ständig ist, was dann?“","options":[{"text":"„Das war bestimmt ein Schock. Mich interessiert: Sind es wirklich viele verschiedene Einbrüche, oder taucht dieselbe Geschichte im Chat öfter auf?“","style":"sokratisch","reaction":"„*stutzt* Hm. Wenn ich es genau nehme... der Einbruch war ja nur einer. Die Kapuzengestalten haben nur gesehen, dass jemand am Tor stand. Aber es *fühlt* sich so an, als wäre ständig was.“","feedback":"Treffend: Die Frage macht den Mechanismus sichtbar, ohne Gabi zu belehren. Lebhafte, wiederholte Meldungen erhöhen die gefühlte Häufigkeit. Weil du zuerst den Schock anerkennst, bleibt das Gespräch offen.","score":3,"nextStepId":"step-3"},{"text":"„Du hast recht, das ist wirklich eine Häufung. Ich glaube, wir müssen uns alle besser absichern. Ich schaue gleich nach Alarmanlagen, hast du eine Empfehlung?“","style":"ausstieg","reaction":"„Ja, ich kenne da einen Anbieter, der ist sein Geld wert! Siehst du, du siehst es auch! Ich poste die Meldungen gleich noch mal, damit es wirklich jeder mitbekommt.“","feedback":"Du stimmst dem Inhalt zu, um den Frieden zu wahren. Das ist der Kipppunkt der Deeskalation: Gefühle validieren heißt nicht, falschen Eindrücken zuzustimmen. Und die erneute Wiederholung der Meldungen verstärkt den Eindruck einer Welle.","score":-1,"nextStepId":"step-panic"},{"text":"„Du lässt dich von ein paar Meldungen, die im Chat immer wieder auftauchen, verrückt machen. Das nennt man übrigens Verfügbarkeitsheuristik, Gabi: Was dir gerade ständig vor Augen ist, hältst du für häufig.“","style":"frontal","reaction":"„Jetzt kommst du mir mit Fachbegriffen? Ich bin doch nicht blöd! Du hältst dich wohl für was Besseres!“","feedback":"Der Begriff stimmt, aber als Etikett gegen Gabi wirkt er wie eine „Du“-Botschaft und beschämt sie. Wer das Muster benennt, muss es als gemeinsame Beobachtung anbieten.","score":-2,"nextStepId":"step-fail"}]},"step-3":{"id":"step-3","speaker":"Gabi","speech":"„Mag sein, dass es ein bisschen aufgebauscht wirkt. Aber was sagst du dazu, wenn die Zahlen mir trotzdem recht geben? Soll ich das glauben, nur weil du es sagst?“","options":[{"text":"„Nein, glaub mir nicht einfach, ich habe selbst keine Zahlen im Kopf. Wir wollen beide eine sichere Straße. Wollen wir nachsehen, was die Zahlen über die letzten Jahre bei uns sagen?“","style":"sokratisch","reaction":"„*zögert* Das ist eigentlich fair. Ich könnte bei der Polizei nachfragen, ob es für unser Viertel Zahlen gibt. Und ob sich das über die Jahre verändert hat...“","feedback":"Sehr stark: Gemeinsames Ziel statt Lagerdenken, dazu der Blick auf die langfristigen, nüchternen Zahlen zur tatsächlichen Häufigkeit statt auf das Bauchgefühl.","score":3,"nextStepId":"step-4-success"},{"text":"„Ich mache dir einen Vorschlag: Das Thema regt uns beide gerade auf. Lass uns eine Pause machen und morgen in Ruhe weiterreden. Mir ist das Gespräch wichtig, so kommen wir nur nicht weiter.“","style":"ausstieg","reaction":"„Hm, na gut. Eigentlich wollte ich das jetzt klären, aber... meinetwegen, morgen.“","feedback":"Eine strategische Auszeit ist eine saubere Notbremse und schützt das Gespräch. Allerdings hast du die Chance verpasst, Gabi jetzt schon zur Prüfung der Zahlen einzuladen.","score":1,"nextStepId":"step-4-struggle"},{"text":"„Natürlich solltest du mir glauben, ich habe studiert, ich weiß das. Statistiken zeigen längst, dass hier nichts los ist.“","style":"sarkastisch","reaction":"„Ach, Statistiken! Die Statistik hat keinen Einbruch erlebt, die Lindenstraße schon. Du hast keine Ahnung vom echten Leben!“","feedback":"Eine Autoritätsbehauptung ohne Beleg und ohne Zahl. Das ist der Gegenangriff, den die Deeskalations-Matrix vermeiden will; Gabi geht in die Verteidigung.","score":-2,"nextStepId":"step-fail"}]},"step-4-success":{"id":"step-4-success","speaker":"Gabi","speech":"„Weißt du was? Ich frage im Chat, ob jemand die Zahlen zu unserem Viertel kennt, und schreibe der Polizei. Wenn es wirklich weniger ist, als ich dachte, bin ich ehrlich gesagt erleichtert. Kommst du mit, wenn ich dort anrufe?“","options":[{"text":"„Gern, ich komme mit. Und egal, was rauskommt: Aufmerksam bleiben wir trotzdem, dafür ist so ein Chat ja da. Ich bringe auch den Kaffee mit.“","style":"deeskalierend","reaction":"„Abgemacht. Und danke, dass du mich nicht abgebügelt hast. Das hätte ich gerade gar nicht vertragen.“","feedback":"Perfekt: Du hast das Gefühl ernst genommen, Gabis Eindruck mit einer Frage geprüft und die Beziehung gestärkt. Das ist Deeskalation, die den Weg zur Überprüfung öffnet, ohne Aufmerksamkeit abzuwerten.","score":3},{"text":"„Ja gern, und ich gehe davon aus, dass du dich dann bei allen entschuldigst, die du verrückt gemacht hast.“","style":"sarkastisch","reaction":"„*verstummt* Das war jetzt gemein. Dann mach ich es lieber allein.“","feedback":"Ein Seitenhieb zum Schluss kostet den Gewinn. Gabi bleibt ein Mensch mit nachvollziehbaren Gründen; Spott beschädigt die Brücke, die du gebaut hast.","score":-1}]},"step-4-struggle":{"id":"step-4-struggle","speaker":"Gabi","speech":"„Gut, wir sprechen morgen. Aber ich lasse mir nicht ausreden, dass hier was im Argen liegt. Darauf bleibe ich dabei.“","options":[{"text":"„Das musst du auch nicht, Gabi. Wir reden morgen in Ruhe weiter und schauen gemeinsam, was die Zahlen für unser Viertel hergeben.“","style":"deeskalierend","reaction":"„*nickt langsam* Von mir aus. Die Zahlen schaue ich mir an. Bis morgen.“","feedback":"Gut gerettet: Die Pause bleibt ein Versprechen, und die Frage nach den Zahlen steht im Raum. Ohne Druck bleibt die Tür offen.","score":2},{"text":"„Dann bleib dabei, Gabi. Ich wette, nächste Woche hat sich der Chat sowieso wieder beruhigt, und dann reden alle über was anderes.“","style":"humorvoll","reaction":"„Haha, sehr witzig. Mal sehen, wer zuletzt lacht.“","feedback":"Der Witz entschärft ein wenig, aber ohne Aufgabe für die Zeit bis morgen bleibt das Gespräch folgenlos. Die Chance auf eine gemeinsame Prüfung ist verspielt.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Gabi","speech":"„Ich sehe schon, mit dir kann man darüber nicht reden. Ich schreibe es gleich in den Chat: Man muss hier selber für Sicherheit sorgen!“ *geht kopfschüttelnd ins Haus*","options":[{"text":"Ende: Gabi fühlt sich nicht gehört und ist jetzt entschlossener als zuvor. Wer gewinnen will, verliert oft das Gespräch.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst ihr Gefühl ernst nehmen, bevor es um Zahlen und Fachbegriffe geht.","feedback":"Frage dich: Wollte ich Recht haben oder das Gespräch retten? Die Deeskalations-Matrix ordnet die Reihenfolge: erst Gefühl validieren, dann Sachfrage.","score":0}]},"step-panic":{"id":"step-panic","speaker":"Gabi","speech":"„Genau, wir müssen jetzt handeln! Ich rufe sofort eine Versammlung ein und poste alle Meldungen noch mal, damit es jeder sieht!“","options":[{"text":"Ende: Die Aufregung schaukelt sich hoch, und die Wiederholung der Meldungen macht den Eindruck einer Einbruchswelle nur noch stärker.","style":"ausstieg","reaction":"Mitgefühl ja, Mitempörung nein: Wer mitzittert, kann Gabi nicht beruhigen.","feedback":"Je öfter dieselben Meldungen wiederholt werden, desto verfügbarer und wichtiger erscheinen sie. Deeskalation heißt, das Gefühl zu validieren und selbst ruhig zu bleiben.","score":0}]}},"status":"entwurf","familie":"basisrate-beachten","fertigkeit":"F4","stufe":3,"kurz":"Was lebhaft, frisch und oft wiederholt im Kopf ist, fühlt sich häufig an, auch wenn die Zahlen etwas anderes sagen können. Wer die Sorge zuerst ernst nimmt, schafft den Raum, in dem die Frage nach der tatsächlichen Häufigkeit überhaupt gehört wird.","prueffrage":"Wie viele verschiedene Einbrüche stecken hinter den vielen Meldungen im Chat, und wie oft geht es um denselben Vorfall?","quellen":[{"typ":"url","kurz":"PubMed: Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases (Abstract, PMID 17835457)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/17835457/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124"}],"thema":"Zusammenleben"},{"id":"scen-flache-erde-ben","title":"Bens gerader Horizont","subtitle":"Perspektive und Optik, geübt mit Street Epistemology","character":"Ben, Mitschüler","avatar":"🌅","context":"In der Pause hat Ben ein Foto vom letzten Urlaub am Meer herumgezeigt: Der Horizont verläuft darauf kerzengerade wie mit dem Lineal gezogen. Jetzt grinst er und verkündet, das sei der Beweis, dass die Erde flach ist. Du schaust gerade in dein Pausenbrot.","goal":"Bring Ben mit neugierigen Fragen dazu, selbst zu prüfen, wie verlässlich der bloße Augenschein als Methode ist, ohne ihn vor der Klasse bloßzustellen.","bereich":"Schule","laenge":"kurz","ton":"heiter","bestehenAb":4,"lektion":"Sehen ist kein passives Aufzeichnen, sondern Interpretation: Was wir sehen, hängt von Perspektive und den Grenzen unserer Augen und Kameras ab. Mit Street Epistemology greifst du nicht Bens Schlussfolgerung an, sondern fragst nach seiner Methode: Wie sicher bist du, und wie verlässlich ist der Augenschein?","toolRef":"H.2.2","faktenRef":"C.5.2","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Ben","speech":"„Schau dir den Horizont an! Kerzengerade! Wenn die Erde eine Kugel wäre, müsste der doch irgendwie gebogen aussehen. Ich glaube nur, was ich sehe, und ich sehe: flach!“","options":[{"text":"„Ben, das ist kompletter Quatsch. Die Erde ist rund, das weiß jedes Grundschulkind. Wie kann man in der Oberstufe noch so einen Unsinn glauben?“","style":"frontal","reaction":"„Ach, jetzt bin ich also der Dumme? Du plapperst doch bloß nach, was im Schulbuch steht! *verschränkt die Arme*“","feedback":"Frontalangriff: Du greifst die Schlussfolgerung an und Ben persönlich. Er wird defensiv und hört nicht mehr zu. Street Epistemology setzt genau dort an, wo du nicht hinschaust: bei der Methode.","score":-2,"nextStepId":"step-fail"},{"text":"„Spannendes Foto! Darf ich dich was fragen? Wie sicher bist du dir auf einer Skala von 0 bis 100, dass die Erde flach ist, und was ist der Hauptgrund für diese Sicherheit?“","style":"sokratisch","reaction":"„Oh, locker 90! Der Hauptgrund: Ich seh's doch mit eigenen Augen. Da ist keine Kurve, nirgends. Mehr Beweis braucht kein Mensch!“","feedback":"Sehr gut! Du klärst den Grad der Sicherheit und deckst die Methode auf. Ben nennt sie selbst: den eigenen Augenschein.","score":3,"nextStepId":"step-2"},{"text":"„Haha, klar, und die Sonne dreht sich um uns, weil man's ja sieht. Ben, du Genie, wann veröffentlichst du dein Buch?“","style":"sarkastisch","reaction":"„Lach du nur! Ihr habt halt alle Angst, mal selbst hinzuschauen. Schade, dass keiner mit mir ernsthaft redet.“","feedback":"Der Spott mag witzig sein, aber Ben fühlt sich verlacht und in seiner Außenseiterrolle bestätigt. Ein Gespräch über die Methode kommt so nicht zustande.","score":-1,"nextStepId":"step-fail"}]},"step-2":{"id":"step-2","speaker":"Ben","speech":"„Also: Mein Auge zeigt mir einen geraden Horizont, und das Foto zeigt ihn auch. Warum sollte ich dem nicht vertrauen? Augen lügen nicht!“","options":[{"text":"„Die Erde ist riesig, und du siehst nur ein winziges Stück davon. Auf so einem Foto kann man keine Krümmung erkennen. Lies das ruhig nach, Ben.“","style":"frontal","reaction":"„Pff, das kann man sich immer ausdenken. Du hast das doch auch nur irgendwo gelesen. Ich vertraue meinen Augen.“","feedback":"Der Hinweis auf die Größe der Erde geht in die richtige Richtung, aber du lieferst fertige Behauptungen statt Fragen. Für Ben sind das bloß Aussagen anderer. So bewegst du seine Methode nicht.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Spannend, dass du deinen Augen so vertraust. Könnte ein kleines Stück einer riesigen Kugel fürs Auge fast gerade aussehen? Wie könnten wir das testen?“","style":"sokratisch","reaction":"„Hmm... *überlegt* Wie ein Ameisenblick auf einem Fußball? Kann sein, dass es dann flach wirkt. Aber wie testet man das?“","feedback":"Gut! Du bietest eine Alternative an, und zwar als gemeinsame Frage nach einem Test statt als Behauptung. Dahinter steht „Grundlagen der Optik & Perspektive“: Sehen ist kein passives Aufzeichnen, sondern Interpretation. Ben denkt selbst weiter.","score":3,"nextStepId":"step-3-success"},{"text":"„Du hast recht, Ben, Augen sind echt verlässlich. Dann glaub's halt, ich hab keine Lust auf Diskussionen.“","style":"ausstieg","reaction":"„Siehst du! Dann gibst du's ja selbst zu. Ich hab's immer gewusst.“","feedback":"Der Ausstieg ist hier zu früh und missverständlich: Ben hört Zustimmung. „Street Epistemology“ schließt ein Gespräch freundlich ab („Danke, das hat mir geholfen, deine Perspektive besser zu verstehen“), ohne dem Gegenüber recht zu geben.","score":-1,"nextStepId":"step-fail"}]},"step-3-success":{"id":"step-3-success","speaker":"Ben","speech":"„Okay, also vielleicht ist ein Foto vom Strand einfach zu klein, um was zu zeigen. Aber den Beweis für die Kugel muss man ja woanders suchen, oder? Wo würdest du da schauen?“","options":[{"text":"„Gute Frage, die wir uns beide stellen können. Lass uns in der Pause überlegen, welche Beobachtungen oder Messungen die Kugel-Idee wirklich testen würden.“","style":"sokratisch","reaction":"„Abgemacht! Aber nur, wenn du mir danach nicht sagst, dass ich schon immer falsch lag. *grinst*“","feedback":"Mission gelungen! Ben hat selbst begonnen, die Zuverlässigkeit des bloßen Augenscheins zu hinterfragen, ohne sein Gesicht zu verlieren. Ein Anfang, kein Geständnis.","score":3},{"text":"„Ganz einfach, Ben: Ich zeig dir morgen ein paar Artikel, und dann siehst du schwarz auf weiß, dass du falsch lagst. Das ist doch ein fairer Deal, okay?“","style":"frontal","reaction":"„Artikel? Pff, na gut... aber ich glaube sowieso kein Wort davon.“","feedback":"Du nimmst Ben die Entdeckung aus der Hand und machst wieder eine Belehrung daraus. Es bleibt ein Rest an Offenheit, aber der Schwung der gemeinsamen Suche ist weg.","score":1}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Ben","speech":"„Ich weiß nicht... Alle sagen immer, ich soll mehr Quellen lesen, aber irgendwie klingt keiner überzeugend.“","options":[{"text":"„Das kann ich verstehen, es ist anstrengend, wenn alle einem etwas erzählen. Mich würde einfach interessieren, wie du's selbst prüfen würdest. Wollen wir morgen mal gemeinsam überlegen, welche Beobachtung eine flache und eine runde Erde unterscheiden könnte?“","style":"sokratisch","reaction":"„Hm. Okay. Aber ich entscheide, was zählt. *grinst vorsichtig*“","feedback":"Guter Neustart! Du gehst zurück zur Frage nach der Methode und machst Ben zum Mitforscher statt zum Gegner. Die Tür bleibt offen.","score":2}]},"step-fail":{"id":"step-fail","speaker":"Ben","speech":"„Keine Lust mehr auf dieses Thema. Ihr versteht das eh nicht. Ich zeig euch das Foto jetzt nicht mehr.“ *steckt das Handy ein und geht*","options":[{"text":"Ende: Ben fühlte sich nicht ernst genommen und zieht sich zurück. Beim nächsten Mal neugierig nach seiner Methode fragen statt urteilen.","style":"ausstieg","reaction":"Wer das Gegenüber bloßstellt, bekommt keine Gelegenheit mehr, Fragen zu stellen.","feedback":"Frage dich: Wollte ich Recht haben oder wollte ich, dass Ben selbst über seine Methode nachdenkt? Street Epistemology beginnt immer mit Neugier statt mit Urteil.","score":0}]}},"status":"entwurf","familie":"bekannte-ursache-zuerst","fertigkeit":"F1","stufe":2,"kurz":"Sehen ist kein passives Aufzeichnen, sondern Deutung: Was wir sehen, hängt vom Blickwinkel und von den Grenzen unserer Augen und Kameras ab. Statt die Schlussfolgerung anzugreifen, hilft die Frage, wie verlässlich der bloße Augenschein als Methode ist.","prueffrage":"Wie groß ist das Stück Erde auf dem Foto im Vergleich zur ganzen Kugel, und wie deutlich müsste darauf ein Bogen überhaupt zu sehen sein?","quellen":[{"typ":"url","kurz":"Lynch, D. K. (2008): Visually discerning the curvature of the Earth. Applied Optics 47(34), H39–H43 (Abstract, Optica; DOI 10.1364/AO.47.000H39)","oeffentlich":true,"url":"https://opg.optica.org/abstract.cfm?URI=ao-47-34-H39","abruf":"2026-10-12"},{"typ":"doi","kurz":"Meyer, M.; Enders, A.; Klofstad, C.; Stoler, J.; Uscinski, J. (2024): Using an AI-powered „street epistemologist“ chatbot and reflection tasks to diminish conspiracy theory beliefs. HKS Misinformation Review","oeffentlich":true,"doi":"10.37016/mr-2020-164","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Boghossian, P. (2013): A Manual for Creating Atheists. Pitchstone Publishing","oeffentlich":false}],"thema":"Natur und Klima"},{"id":"scen-schule-lerntyp","title":"Frau Brandts Lerntypen","subtitle":"Barnum und Etiketten, geübt mit intellektueller Barmherzigkeit","character":"Frau Brandt, Lehrerin","avatar":"🍎","context":"Beim Elternsprechtag kommt dein Kind zur Sprache. Frau Brandt, die Klassenlehrerin, strahlt: Sie habe einen Lerntyp-Test durchgeführt, die „individuellen Profile“ seien verblüffend treffsicher, und ihr Unterricht werde künftig strikt nach visuellen, auditiven und kinästhetischen Lerntypen getrennt. Sie meint es ehrlich gut, doch die verblüffende Treffsicherheit der Profile könnte eher an ihren allgemeinen Formulierungen liegen als am Test selbst.","goal":"Zeig Frau Brandt, warum Profile wie ihre so überzeugend wirken, und würdige dabei ihr Engagement, ohne sie bloßzustellen.","bereich":"Schule","laenge":"kurz","ton":"heiter","bestehenAb":4,"lektion":"Aussagen, die auf fast jeden passen, wirken persönlich zutreffend, so wie bei Forers Studenten, die ihr identisches Profil im Schnitt mit 4,26 von 5 bewerteten (Barnum-Effekt). Auch die Idee hinter dem Test ist schwach belegt: Eine Übersichtsarbeit (Pashler und Kollegen, 2008) fand reichlich Belege, dass Lernende Vorlieben äußern, aber fast keine dafür, dass auf den Lerntyp zugeschnittener Unterricht das Lernen verbessert. Mit intellektueller Barmherzigkeit würdigst du zuerst das gute Motiv der Lehrerin und prüfst dann gemeinsam, was sie behauptet: Seziert wird die Behauptung, nicht der Mensch.","toolRef":"H.1.3","faktenRef":"B.10","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Frau Brandt","speech":"„Ich habe mit der Klasse einen Lerntyp-Test gemacht, und die Ergebnisse sind verblüffend! Jedes Kind hat sein Profil bekommen, und alle sagten: ‚Genau so bin ich!‘ Dein Kind ist ganz klar der auditive Typ: gesellig, aber manchmal auch zurückgezogen, mit viel ungenutztem Potenzial. Das stimmt doch, oder?“","options":[{"text":"„Ehrlich gesagt ist das Lerntypen-Zeug Esoterik. Dass sich alle darin wiedererkennen, beweist doch nur, dass der Test nichts taugt. Da sollten Sie sich nicht blenden lassen.“","style":"frontal","reaction":"„*versteift sich* Ich unterrichte seit über zwanzig Jahren, und Sie erklären mir, ich lasse mich blenden? Ich gebe mir jeden Tag Mühe für diese Kinder!“","feedback":"Frontalangriff! Die Kritik an der Sache trifft Frau Brandt als Person. Ohne Wertschätzung ihres Engagements macht sie zu, und die Chance auf ein Gespräch ist vertan.","score":-2,"nextStepId":"step-fail"},{"text":"„Das klingt wirklich passend! Dann sollten wir zu Hause wohl nur noch Hörbücher und Erklärvideos ohne Text einsetzen und das Lesen weglassen?“","style":"humorvoll","reaction":"„Ja, genau! Und beim Rechnen sollte es erzählt statt aufgeschrieben werden. Ich freue mich, dass Sie mitziehen!“","feedback":"Du bestätigst das Etikett und verstärkst es sogar. Dein Kind würde so auf eine Schublade festgelegt, und der Barnum-Effekt bleibt unangetastet.","score":-1,"nextStepId":"step-struggle"},{"text":"„Ich sehe, wie viel Mühe Sie sich geben, jedes Kind individuell zu fördern. Das schätze ich sehr. Darf ich nachfragen, woran Sie erkennen, dass die Profile wirklich zu den einzelnen Kindern passen?“","style":"sokratisch","reaction":"„*lächelt* Na, weil sich alle darin wiedererkannt haben! Das war richtig magisch. Eine Schülerin sagte sogar: ‚Das ist ja unheimlich, als würde mich jemand kennen.‘“","feedback":"Sehr gut! Intellektuelle Barmherzigkeit: Du würdigst ihr Motiv und fragst nach ihren Gründen, statt zu widersprechen. Das öffnet die Tür für ein echtes Gespräch.","score":3,"nextStepId":"step-2"}]},"step-2":{"id":"step-2","speaker":"Frau Brandt","speech":"„Also, wenn sich wirklich alle erkannt haben, ist das doch der beste Beweis, dass der Test funktioniert, oder nicht?“","options":[{"text":"„Forer gab allen Studenten denselben Text, und sie bewerteten ihn im Schnitt mit 4,26 von 5. Könnte Wiedererkennen also auch ohne Treffsicherheit entstehen?“","style":"sokratisch","reaction":"„*stutzt* Nein, die Texte waren verschieden... aber, ehrlich gesagt, haben alle Typen ähnlich geklungen: etwas Lob, ein bisschen Selbstzweifel, ungenutztes Potenzial. Moment mal. Das klingt ja fast wie bei diesem Experiment...“","feedback":"Meisterhaft! Du nennst den Befund als Frage, nicht als Urteil. So kommt Frau Brandt selbst auf den Barnum-Effekt, und das wirkt viel stärker als jede Belehrung.","score":3,"nextStepId":"step-success"},{"text":"„Das sagen Sie so, aber Wiedererkennen ist einfach keine Wissenschaft. Wenn Sie sich mit Psychologie auskennen würden, wüssten Sie das.“","style":"sarkastisch","reaction":"„*kühl* Aha. Dann bin ich also unwissend. Ich glaube, wir sollten das Gespräch beenden.“","feedback":"Sarkasmus wertet Frau Brandt ab und verletzt das Prinzip der intellektuellen Barmherzigkeit. Wer sich herabgesetzt fühlt, hört keine Argumente mehr.","score":-2,"nextStepId":"step-fail"},{"text":"„Ich verstehe, dass das überzeugend wirkt. Schauen wir uns ein Profil gemeinsam an? Ich frage mich, ob solche Sätze wie ‚gesellig, aber manchmal zurückgezogen‘ nicht auf fast jeden zutreffen könnten.“","style":"deeskalierend","reaction":"„Hm, ‚gesellig, aber manchmal zurückgezogen‘... das trifft vermutlich wirklich auf viele zu. Aber der Test hat doch gerade bei meinen Kindern so gut gepasst...“","feedback":"Brauchbar: Du weist freundlich auf vage Aussagen hin, wie sie für den Barnum-Effekt typisch sind. Es fehlt noch der Beleg, dass dieses Muster messbar ist, daher bleibt sie unsicher.","score":1,"nextStepId":"step-struggle"}]},"step-struggle":{"id":"step-struggle","speaker":"Frau Brandt","speech":"„Na ja, wir müssen da sicher nicht alles bis ins Letzte zerpflücken. Mir ist wichtig, dass sich die Kinder verstanden fühlen. Das ist doch schon ein Wert an sich.“","options":[{"text":"„Da stimme ich zu, dass Ihnen die Kinder am Herzen liegen. Vielleicht nehmen wir die Profile als Gesprächsanlass und fragen die Kinder selbst, wie sie am liebsten lernen?“","style":"deeskalierend","reaction":"„Das ist eine schöne Idee. Ausprobieren statt festlegen, das gefällt mir. Ich überlege mir, wie wir das einbauen.“","feedback":"Guter Ausstieg: Du würdigst ihr Motiv und lenkst auf eine konstruktive Alternative um. Die Sachfrage bleibt offen, aber die Beziehung ist gesichert.","score":2},{"text":"„Sie haben recht, dann lassen wir es einfach so stehen und sprechen nicht weiter darüber. Hauptsache, die Kinder fühlen sich wohl und sind zufrieden.“","style":"ausstieg","reaction":"„Danke für Ihr Verständnis. Ich freue mich, dass wir an einem Strang ziehen.“","feedback":"Ein bequemer, aber folgenloser Rückzug. Das Etikett bleibt unberührt, und dein Kind wird weiter in eine Schublade gesteckt.","score":0}]},"step-success":{"id":"step-success","speaker":"Frau Brandt","speech":"„Na sowas. Ich war so begeistert von den Rückmeldungen der Kinder, dass ich gar nicht gefragt habe, ob das Profil auch zu jemand anderem gepasst hätte. Was machen wir jetzt mit meinem Konzept?“","options":[{"text":"„Ihre Idee, die Kinder individuell zu sehen, ist wertvoll. Vorlieben haben Kinder durchaus, nur ist bisher kaum belegt, dass getrennter Unterricht nach Lerntyp mehr bringt. Wie wäre es, den Unterricht abwechslungsreich zu gestalten und die Kinder ausprobieren zu lassen, was für sie funktioniert?“","style":"deeskalierend","reaction":"„Das gefällt mir viel besser. Eine Schublade passt eben doch selten. Danke, dass Sie mir das so freundlich gezeigt haben.“","feedback":"Mission gelungen! Du hast ihr gutes Motiv gewürdigt, den Barnum-Effekt sichtbar gemacht, die schwache Beleglage für getrennten Unterricht nach Lerntyp sachlich erwähnt und einen gangbaren Weg angeboten, ohne dass sie ihr Gesicht verlieren musste.","score":3},{"text":"„Am besten lassen Sie den Test einfach weg, Frau Brandt, das ist ohnehin alles Quatsch, und die Kinder sind ohne diese Schubladen deutlich besser dran.“","style":"frontal","reaction":"„Alles Quatsch? So einfach ist das auch wieder nicht. Ich muss darüber nachdenken, aber so reden Sie nicht mit mir.“","feedback":"Schade: Ein Pauschalurteil nach einem guten Gespräch wirft das Erreichte zurück. Barmherzigkeit heißt, auch beim Abschluss die Person zu würdigen, nicht nur die Idee zu verwerfen.","score":-1}]},"step-fail":{"id":"step-fail","speaker":"Frau Brandt","speech":"„Ich glaube, ich habe verstanden, dass Sie das alles für Unsinn halten. Dann machen wir es eben ohne Ihre Zustimmung.“ *packt die Unterlagen zusammen*","options":[{"text":"Ende: Frau Brandt fühlt sich abgewertet und hält an ihrem Konzept fest. Wer die Person trifft, verliert die Sache.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst ihr Engagement würdigen, dann erst nach ihren Gründen fragen.","feedback":"Ohne intellektuelle Barmherzigkeit wird aus einer Sachfrage ein Machtkampf. Das Ziel ist, den Irrtum aufzulösen, nicht die Lehrerin zu besiegen.","score":0}]}},"status":"entwurf","familie":"passt-auf-jeden","fertigkeit":"F2","stufe":3,"kurz":"Aussagen, die auf fast jeden passen, wirken wie ein treffendes Profil (Barnum-Effekt); Wiedererkennen belegt nicht, dass ein Test trifft. Dass Unterricht nach Lerntyp besser wirkt, ist zudem kaum belegt. Erst das Motiv würdigen, dann die Behauptung prüfen, nicht den Menschen.","prueffrage":"Würden sich die Kinder genauso gut wiedererkennen, wenn man ihnen heimlich die Profile anderer Kinder gäbe?","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Forer effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Forer, B. R. (1949): The Fallacy of Personal Validation: A Classroom Demonstration of Gullibility. J. Abnormal and Social Psychology 44(1), 118–123","oeffentlich":false,"doi":"10.1037/h0059240"},{"typ":"url","kurz":"Malpas, J.: Donald Davidson. Stanford Encyclopedia of Philosophy (überarb. 28.04.2023), Abschn. 3.3","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Pashler, H.; McDaniel, M.; Rohrer, D.; Bjork, R. (2008): Learning Styles: Concepts and Evidence. Psychological Science in the Public Interest 9(3), 105–119","oeffentlich":true,"doi":"10.1111/j.1539-6053.2009.01038.x","url":"https://pubmed.ncbi.nlm.nih.gov/26162104/","abruf":"2026-10-13"}],"thema":"Zusammenleben"},{"id":"scen-bewerbung-horoskop","title":"Nina und das Horoskop vor dem Gespräch","subtitle":"Sternzeichen als Entscheidungshilfe, geübt mit kognitiver Entkopplung","character":"Nina, Kollegin","avatar":"♏","context":"Deine Kollegin Nina ist von einer anderen Firma zum Vorstellungsgespräch eingeladen, morgen wäre der Termin. Beim Frühstück las sie ihr Wochenhoroskop: „Vermeide diese Woche wichtige Entscheidungen.“ Jetzt will sie den Termin absagen, obwohl sie den Job eigentlich wollte.","goal":"Hilf Nina, ihre Entscheidung von der Horoskop-Aussage zu entkoppeln, ohne sie bloßzustellen, und lade sie ein, selbst zu prüfen, wie treffsicher so ein Text wirklich ist.","bereich":"Arbeit","laenge":"kurz","ton":"heiter","bestehenAb":6,"lektion":"Ein Horoskop ist so allgemein formuliert, dass sich fast jeder darin wiedererkennt (Barnum-Effekt). Wer den Text nicht als „sein Schicksal“, sondern als Hypothese behandelt, die man prüfen darf, kann ihn ohne Gesichtsverlust zur Seite legen (Kognitive Entkopplung). Die Frage „Wie viele Menschen kenne ich, auf die das nicht zuträfe?“ ist dafür ein freundliches Werkzeug.","toolRef":"H.1.1","faktenRef":"B.10","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Nina","speech":"„Ich hab’s gerade gelesen: ‚Vermeide diese Woche wichtige Entscheidungen.‘ Und morgen ist mein Vorstellungsgespräch! Das kann kein Zufall sein. Ich sag das Ganze lieber ab, Skorpione haben ein Gespür für so was.“","options":[{"text":"„Nina, ernsthaft? Horoskope sind Quatsch für Leute, die gern auf jeden Unsinn hereinfallen. Wegen so etwas einen Job sausen zu lassen, ist ziemlich naiv, und das weißt du auch.“","style":"frontal","reaction":"„Naiv?! Na danke. Ich frag dich nie wieder um Rat. Ich sag das Ding ab, und zwar jetzt.“ *tippt demonstrativ auf ihrem Handy*","feedback":"Frontalangriff: Nina hört „Du bist naiv“ und verteidigt nun ihre Identität statt ihre Entscheidung. Genau diese Kopplung von Person und Überzeugung macht Argumente wirkungslos.","score":-2,"nextStepId":"step-fail"},{"text":"„Ich verstehe, dass dich das verunsichert. Darf ich dich was fragen: Wie viele Leute kennst du, für die der Satz ‚Vermeide diese Woche wichtige Entscheidungen‘ gerade überhaupt nicht passen würde?“","style":"sokratisch","reaction":"„Hm... *überlegt* Ehrlich gesagt, wahrscheinlich nicht viele. Fast jeder hat doch irgendeine Entscheidung vor der Brust. Aber trotzdem...“","feedback":"Treffer! Du nimmst die Verunsicherung ernst und stellst die Aktivierungs-Frage gegen den Barnum-Effekt. Damit wird der Horoskop-Satz zu etwas, das Nina prüfen kann, statt Teil von ihr zu sein. Sie prüft selbst, statt sich verteidigen zu müssen.","score":3,"nextStepId":"step-2"},{"text":"„Ach Nina, du hast recht, Skorpione spüren so was. Sag besser ab, sicher ist sicher. Es gibt ja bestimmt noch andere Jobs, und die Sterne stehen nächste Woche sicher besser.“","style":"humorvoll","reaction":"„Siehst du, du verstehst mich! Ich schreib die Absage gleich. Gut, dass wenigstens du auf die Sterne hörst.“","feedback":"Du bestätigst den Mythos, um nett zu sein. Damit verstärkst du, dass ein vager Satz eine wichtige Lebensentscheidung steuern darf, ohne dass irgendetwas geprüft wurde.","score":-2,"nextStepId":"step-fail"}]},"step-2":{"id":"step-2","speaker":"Nina","speech":"„Aber es hat sich irgendwie so passend angefühlt! Gestern erst hab ich gezweifelt, ob ich den Wechsel wirklich will. Das Horoskop weiß das doch quasi.“","options":[{"text":"„Weißt du, bei Horoskopen geht’s ja nicht ums Wissen, das ist alles Psychologie. Im Grunde ist Astrologie halt Humbug, da muss man gar nicht groß diskutieren. Das steht in jedem Lehrbuch.“","style":"frontal","reaction":"„Pff, du tust, als wäre ich bescheuert, weil ich es gelesen habe. Lass uns das Thema lassen, okay?“ *wendet sich ab*","feedback":"Inhaltlich nicht falsch, aber als Abkanzeln formuliert. Ohne gemeinsame Prüfung bleibt Ninas Gefühl „Das passt genau“ unangetastet und die Tür geht zu.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Das Gefühl des Passens kenne ich. Lass uns testen, ob es am Text oder an uns liegt: Ich lese dir mein Horoskop von gestern vor, und du sagst mir auf einer Skala von 0 bis 5, wie gut es auf dich passt.“","style":"sokratisch","reaction":"„Okay, das klingt nach einem Experiment. Dann los.“ *hört zu* „‚Du hast ein Bedürfnis nach Anerkennung und bist manchmal zu kritisch mit dir selbst...‘ Moment, das passt total auf mich. Dabei ist das gar nicht mein Sternzeichen!“","feedback":"Stark: Statt zu belehren, lässt du Nina Forers Experiment im Kleinen selbst erleben. Ein Text, der für ein fremdes Sternzeichen genauso „passt“, entlarvt sich durch ihre eigene Erfahrung, und sie behält das Gesicht.","score":3,"nextStepId":"step-3-success"},{"text":"„Tja, wenn du unbedingt auf die Sterne hören willst, bitte. Aber wundere dich später nicht, wenn du den Job verpasst, den du eigentlich wolltest. Ich habe dich gewarnt.“","style":"sarkastisch","reaction":"„Wow, danke für den Druck. Jetzt fühle ich mich noch schlechter und weiß erst recht nicht, was ich tun soll.“","feedback":"Sarkasmus macht aus einer Denkfrage eine Schuldfrage. Nina ist jetzt zusätzlich gekränkt und wird sich eher an das Horoskop klammern, weil es sich weniger vorwurfsvoll anfühlt.","score":-1,"nextStepId":"step-fail"}]},"step-3-success":{"id":"step-3-success","speaker":"Nina","speech":"„Okay, das ist ein bisschen peinlich. Der Text passt auf mich, und auf dich, und vermutlich auf meine Oma auch. *lacht* Heißt das, ich kann das Vorstellungsgespräch einfach machen und das Horoskop ignorieren?“","options":[{"text":"„Du kannst deine Entscheidung auf das stützen, was du über den Job weißt: Gehalt, Team, Aufgaben. Das Horoskop war eine Idee, die wir geprüft haben, kein Urteil über dich. Wie wär’s: Wir gehen noch einmal durch, was du von der neuen Stelle willst?“","style":"sokratisch","reaction":"„Ja, genau das brauche ich. Danke, dass du mich nicht ausgelacht hast. Ich schreibe mir mal auf, was mir an dem Job wirklich wichtig ist.“","feedback":"Perfekt abgeschlossen: Du hältst die Idee (Horoskop) von der Person (Nina) getrennt und lenkst auf überprüfbare Gründe. So sieht kognitive Entkopplung in der Praxis aus, ohne dass jemand sein Gesicht verliert.","score":3}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Nina","speech":"„Ich weiß nicht... Vielleicht war das Horoskop ja doch ein Zeichen. Ich muss darüber nachdenken, ich bin gerade echt durcheinander.“","options":[{"text":"„Das ist völlig okay. Schlaf drüber, und wenn du magst, schreib dir heute Abend auf, was für und was gegen den Job spricht, ganz ohne Sterne. Ich bin morgen früh gern dein Sparringspartner, bevor das Gespräch losgeht.“","style":"deeskalierend","reaction":"„Danke. Das klingt fair. Ich mach die Liste, dann sehen wir weiter.“","feedback":"Guter Rückzug: Du lässt Nina ihr Tempo und schlägst einen Schritt vor, der Gründe statt Zeichen sammelt. Die Sachfrage bleibt offen, die Beziehung heil.","score":2}]},"step-fail":{"id":"step-fail","speaker":"Nina","speech":"„Ich hab entschieden. Ich sage ab, die Sterne sind eindeutig.“ *steckt das Handy ein und geht*","options":[{"text":"Ende: Nina hat sich entweder gekränkt zurückgezogen oder wurde in ihrer Überzeugung bestärkt. Der Termin ist abgesagt.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst Ninas Verunsicherung ernst nehmen, dann gemeinsam prüfen.","feedback":"Wer die Überzeugung angreift, trifft die Person. Der Barnum-Effekt wirkt am stärksten, wenn ein Text persönlich zugeschnitten und aus vertrauenswürdiger Quelle wirkt. Entkopplung gelingt nur, wenn Nina ihr Gesicht wahren darf.","score":0}]}},"status":"entwurf","familie":"passt-auf-jeden","fertigkeit":"F2","stufe":2,"kurz":"Ein Horoskop ist so allgemein formuliert, dass sich fast jeder darin wiedererkennt (Barnum-Effekt). Wer den Text als prüfbare Hypothese statt als Schicksal behandelt, kann ihn ohne Gesichtsverlust beiseitelegen und nach eigenen Gründen entscheiden.","prueffrage":"Auf wie viele Menschen im Bekanntenkreis würde der Satz „Vermeide diese Woche wichtige Entscheidungen“ gerade nicht passen?","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Forer effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Forer, B. R. (1949): The Fallacy of Personal Validation. J. Abnormal and Social Psychology 44(1), 118–123","oeffentlich":false,"doi":"10.1037/h0059240"},{"typ":"doi","kurz":"Woods, C. (2012): Rezension zu Stanovich, K. E.: Rationality and the Reflective Mind. Informal Logic 32(3), 373–380","oeffentlich":true,"doi":"10.22329/il.v32i3.3721","seite":"375","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"scen-pharma-lobby-opa","title":"Opa Karls Pharma-Verdacht","subtitle":"„Big Pharma“, geübt mit aktivem Zuhören","character":"Karl, Opa","avatar":"💊","context":"Dein Opa Karl hat beim Sonntagskaffee seine Tabletten für den Blutdruck beiseitegeschoben. Er ist überzeugt: „Big Pharma“ hält Heilmittel zurück, weil sie an Kranken mehr verdienen als an Gesunden. Du merkst, dass hinter dem großen Satz eine konkrete Geschichte steckt.","goal":"Höre zuerst wirklich zu, finde heraus, was hinter Karls Misstrauen steckt, und lenke das Gespräch von „Big Pharma“ als Pauschalfeind auf überprüfbare Einzelfragen.","bereich":"Gesundheit","laenge":"lang","ton":"ernst","bestehenAb":9,"lektion":"Wer pauschal von „Big Pharma“ spricht, hat oft einen wahren Kern im Rücken: Geldinteressen der Industrie sind real und gehören kritisch beobachtet. Aktives Zuhören mit Paraphrasieren, Gefühle benennen und offenen Fragen holt zuerst die Geschichte hinter der Parole ans Licht. Erst auf dieser Grundlage lässt sich zwischen berechtigter Kritik an einem konkreten Missstand und der pauschalen Dämonisierung unterscheiden, die in die Ablehnung lebensrettender Medikamente kippen kann.","toolRef":"H.2.3","faktenRef":"G.2.4","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Opa Karl","speech":"„Die Tabletten nehme ich nicht mehr. Das ist alles Big Pharma! Die halten uns krank, weil an Gesunden nichts zu verdienen ist. Die Heilmittel gibt es längst, die liegen im Tresor!“","options":[{"text":"„Opa, das ist eine Verschwörungstheorie. Wenn du deine Blutdrucktabletten absetzt, riskierst du einen Schlaganfall. Nimm sie bitte wieder!“","style":"frontal","reaction":"„Verschwörungstheorie! Jetzt fängst du auch noch an! Ich bin 78 und habe mehr erlebt als du. Du plapperst nach, was im Fernsehen kommt.“","feedback":"Die Sorge um seine Gesundheit ist berechtigt, aber du etikettierst ihn und sendest nur, statt zu hören. Karl fühlt sich vorgeführt und verteidigt seine Position. Aktives Zuhören fehlt völlig.","score":-2,"nextStepId":"step-fail"},{"text":"„Das klingt, als hättest du richtig die Nase voll. Magst du mir erzählen, was dich so misstrauisch gemacht hat? Ich möchte das gern verstehen.“","style":"deeskalierend","reaction":"„*lehnt sich zurück* Na, immerhin fragt mal einer. ... Das ist schon länger so, weißt du. Aber es fing mit etwas Bestimmtem an.“","feedback":"Sehr gut. Du benennst das Gefühl und stellst eine offene, klärende Frage. So wird aus einer Konfrontation ein Gespräch, und Karl darf seine Geschichte erzählen.","score":3,"nextStepId":"step-2"},{"text":"„Stimmt, Opa, die Pharmakonzerne sind alle gleich. Dann lass die Tabletten halt weg, wir probieren es mal ohne.“","style":"affektiv","reaction":"„Siehst du, einer versteht mich! Ich habe sie auch gleich in den Müll geworfen. Morgen kaufe ich mir diese Kräutertropfen.“","feedback":"Du bestätigst die Pauschalaussage und sendest ein riskantes Signal. Zuhören heißt nicht zustimmen: Du musst den Inhalt nicht bestätigen, um das Gefühl ernst zu nehmen.","score":-2,"nextStepId":"step-fail"}]},"step-2":{"id":"step-2","speaker":"Opa Karl","speech":"„Mein Nachbar Herbert, mit dem ich jeden Donnerstag Skat spiele, bekam ein neues Medikament verschrieben. Der Arzt war so begeistert davon, und dann kam heraus, dass der Hersteller ihm Reisen bezahlt hat. Ist das etwa kein Beweis?“","options":[{"text":"„Wenn ich dich richtig verstehe, stört dich vor allem, dass sich der Arzt von Geld beeinflussen lassen könnte, während Herbert ihm vertraut hat. Stimmt das so?“","style":"sokratisch","reaction":"„Ganz genau! Man vertraut dem Arzt, und dann steckt dahinter ein Geschäft. Das hat mich richtig wütend gemacht.“","feedback":"Sehr gut. Du paraphrasierst und gibst Karl die Chance, zu korrigieren oder zu bestätigen. Er fühlt sich verstanden, und du hast die wahre Wurzel des Misstrauens ans Licht geholt.","score":3,"nextStepId":"step-3"},{"text":"„Ach, Herbert hat eben einen schlechten Arzt erwischt. Das kommt vor, ist aber ein Einzelfall. Das beweist gar nichts über Medikamente oder die Ärzteschaft insgesamt.“","style":"frontal","reaction":"„Einzelfall! Du tust gerade so, als wäre das alles harmlos. Herbert ist mein Freund!“","feedback":"Du wischst seine Erfahrung weg, bevor du sie verstanden hast. Aktives Zuhören bedeutet, erst die Geschichte und das Gefühl dahinter ernst zu nehmen und nicht sofort zu relativieren.","score":-1,"nextStepId":"step-2b-struggle"},{"text":"„Das tut mir leid für Herbert. Das klingt, als hättest du dir große Sorgen gemacht. Was hat dich daran am meisten getroffen?“","style":"deeskalierend","reaction":"„Dass man nicht weiß, wem man trauen kann. Der Arzt war immer ein Mensch, auf den man sich verlassen konnte.“","feedback":"Ordentlich: Du zeigst Mitgefühl und fragst offen nach. Du hättest das Gehörte aber noch in eigenen Worten zurückspiegeln können (Paraphrasieren), um sicherzugehen, dass du es richtig verstanden hast.","score":2,"nextStepId":"step-3"}]},"step-2b-struggle":{"id":"step-2b-struggle","speaker":"Opa Karl","speech":"„Wenn du mir nicht zuhörst, brauchen wir gar nicht weiterzureden. Die sehen die Leute doch nur als Geldquelle!“","options":[{"text":"„Du hast recht, ich bin zu schnell dazwischengegangen. Ich höre dir jetzt zu: Was genau hat sich bei Herbert abgespielt, und was hat dich daran so aufgebracht?“","style":"deeskalierend","reaction":"„*brummt, aber seine Schultern entspannen sich* Na gut. Herbert wurde auf ein neues Mittel eingestellt, und alle vorigen waren auf einmal angeblich nicht mehr gut genug.“","feedback":"Gut repariert. Du gibst deinen Fehler zu und kehrst zum Zuhören zurück. Das entwaffnet Karl und führt ins Gespräch zurück.","score":2,"nextStepId":"step-3"},{"text":"„Opa, du übertreibst. Die Industrie rettet jedes Jahr unzählige Leben, das kannst du doch nicht leugnen.“","style":"frontal","reaction":"„Ach, dann sind alle Skandale nur erfunden? Du verteidigst die. Das Gespräch ist beendet.“","feedback":"Wieder Sachargumente, bevor Karl sich verstanden fühlt. Er dichtet zu. Solange das Gefühl nicht anerkannt ist, kommen Fakten nicht an.","score":-2,"nextStepId":"step-fail"},{"text":"„Opa, ich merke, wir drehen uns im Kreis, und es regt uns beide auf. Lass uns erst einmal einen Tee trinken und später in Ruhe weiterreden.“","style":"ausstieg","reaction":"„*seufzt* Meinetwegen. *nach dem Tee* Aber eins sage ich dir noch ...“","feedback":"Ein sauberer Rückzug schützt die Beziehung, doch der Kern bleibt ungeklärt. Eine Pause kann sinnvoll sein, kostet aber die gute Gesprächsstimmung.","score":0,"nextStepId":"step-3"}]},"step-3":{"id":"step-3","speaker":"Opa Karl","speech":"„Und überhaupt: Die verdienen Milliarden an Kranken. Warum sollten die ein Mittel verkaufen, das heilt? Das ist doch Logik, da braucht man keine Studien!“","options":[{"text":"„Du hast recht, dass Firmen Geld verdienen wollen und Einfluss real ist. Aber meinst du Herberts Arzt und diesen einen Hersteller, oder alle Ärzte und Firmen auf der Welt?“","style":"sokratisch","reaction":"„Hm... Herbert und seinen Arzt meine ich, ja. Aber alle... na, so einfach ist es wohl auch nicht. Es gibt schließlich Ärzte, die sich richtig kümmern.“","feedback":"Treffend. Du erkennst den wahren Kern an und stellst die Aktivierungsfrage aus „Big Pharma“ / „Die Pharmalobby“: konkreter Missstand oder pauschaler Sündenbock? So unterscheidet Karl selbst zwischen berechtigter Kritik und Verallgemeinerung.","score":3,"nextStepId":"step-4"},{"text":"„Opa, das ist der klassische Fehlschluss: Nur weil jemand Geld verdient, muss er nicht automatisch böse sein. Sonst wäre ja jeder Bäcker ein Betrüger.“","style":"frontal","reaction":"„Fehlschluss, Fehlschluss... Ihr jungen Leute habt für alles ein Fremdwort, nur nicht für die Wahrheit.“","feedback":"Inhaltlich nicht falsch, aber das Fachwort wirkt belehrend und schiebt Karl in die Defensive. Die zuvor aufgebaute Gesprächsbasis wird belastet.","score":-1,"nextStepId":"step-4"},{"text":"„Naja, wenn du das so siehst, wird es wohl stimmen. Das mit den Heilmitteln im Tresor kann ich nicht widerlegen, du kennst dich damit sicher besser aus.“","style":"affektiv","reaction":"„Eben! Endlich sagt das mal einer. Die Wahrheit kommt irgendwann ans Licht.“","feedback":"Zuhören ist nicht Nachgeben. Du gibst klein bei, statt behutsam nachzufragen. Karl hört deine Zustimmung und fühlt sich bestätigt.","score":-2,"nextStepId":"step-fail"}]},"step-4":{"id":"step-4","speaker":"Opa Karl","speech":"„Na gut, vielleicht nicht alle. Aber was ist mit meinen Tabletten? Woher soll ich wissen, ob die nicht auch nur Geschäft sind?“","options":[{"text":"„Diese Sorge ist verständlich. Was würde dir helfen, dich bei deinen Tabletten sicherer zu fühlen? Wollen wir deine Hausärztin fragen, warum genau dieses Mittel und was passiert, wenn man es weglässt?“","style":"sokratisch","reaction":"„Hm... das könnte man machen. Vielleicht frage ich sie wirklich einmal ganz offen, ob sie da etwas verdient.“","feedback":"Sehr stark. Du fragst nach seinem Bedürfnis, statt ein Urteil zu fällen, und öffnest den Weg zu einer überprüfbaren Einzelfrage, die ihn selbst ermächtigt.","score":3,"nextStepId":"step-5"},{"text":"„Opa, weißt du was? Das ist deine Entscheidung. Aber setz die Tabletten bitte nicht ab, bevor du mit deiner Ärztin gesprochen hast, ja? Das ist mir wirklich wichtig.“","style":"deeskalierend","reaction":"„Du machst dir Sorgen, das merke ich. In Ordnung, mit meiner Ärztin rede ich zuerst.“","feedback":"Eine ehrliche, warme Bitte, die seine Autonomie respektiert. Es fehlt allerdings noch die Frage, was Karl braucht, um Vertrauen zu fassen.","score":2,"nextStepId":"step-5"},{"text":"„Das weißt du nicht und kannst du auch nicht wissen. Also nimm sie einfach und hör auf zu grübeln, das macht dich nur unnötig nervös. Fragen stellen bringt hier nichts.“","style":"frontal","reaction":"„Einfach nehmen und nicht denken, so läuft das also. Das ist ja gerade das Problem!“","feedback":"Dein Befehl ignoriert sein Bedürfnis nach Sicherheit und Mitbestimmung. Wer sich nicht ernst genommen fühlt, verstärkt sein Misstrauen.","score":-2,"nextStepId":"step-fail"}]},"step-5":{"id":"step-5","speaker":"Opa Karl","speech":"„Weißt du, ich habe einfach Angst, dass ich irgendwann nur noch eine Nummer bin und mir keiner mehr etwas erklärt. Dann will ich wenigstens selbst bestimmen.“","options":[{"text":"„Wenn ich dich richtig verstehe, geht es dir gar nicht um die Tabletten, sondern darum, ernst genommen zu werden und mitentscheiden zu dürfen. Stimmt das so?“","style":"sokratisch","reaction":"„*nickt langsam* Ja, genau das ist es. Danke, dass du mir zuhörst. Ich nehme die Tabletten weiter, aber ich lasse mir alles genau erklären.“","feedback":"Meisterhaft. Du paraphrasierst das eigentliche Bedürfnis hinter dem Misstrauen. Karl fühlt sich verstanden, und der Weg zurück zur Behandlung ist frei, ohne dass er sein Gesicht verlieren musste.","score":3,"nextStepId":"step-success"},{"text":"„Das verstehe ich, Opa. Ich begleite dich zum nächsten Termin und wir stellen deine Fragen gemeinsam. Einverstanden? Du bist dabei nicht allein.“","style":"deeskalierend","reaction":"„Das würdest du tun? Das wäre mir viel wert. Aber die Tabletten lege ich bis dahin erst einmal beiseite.“","feedback":"Eine warme, praktische Geste, aber sie lässt offen, was bis zum Termin mit den Tabletten geschieht. Karl legt sie vorerst beiseite, und das eigenmächtige Absetzen von Blutdruckmitteln kann gefährlich sein. Hier hätte eine klare Bitte gefehlt, sie bis zum Gespräch mit der Ärztin weiter zu nehmen.","score":1,"nextStepId":"step-struggle"},{"text":"„Niemand will dich zur Nummer machen, Opa. Das bildest du dir bloß ein. Die Ärzte haben einfach wenig Zeit, das ist alles, und das hat mit dir nichts zu tun.“","style":"frontal","reaction":"„Einbilden! Du hörst mir nicht zu. Lass mich in Ruhe.“","feedback":"Du sprichst ihm sein Gefühl ab, genau im Moment, in dem er sich geöffnet hat. Das beschädigt das gerade gewachsene Vertrauen.","score":-2,"nextStepId":"step-fail"}]},"step-success":{"id":"step-success","speaker":"Opa Karl","speech":"„Weißt du was? Ich rufe morgen meine Hausärztin an und frage sie ganz offen, warum genau dieses Mittel. Und bis dahin nehme ich die Tabletten wie gewohnt. Magst du mir noch ein Stück Kuchen holen?“","options":[{"text":"„Gern, Opa. Und danke, dass du so offen mit mir gesprochen hast. Ich bringe den Kuchen und höre dir weiter zu, wann immer du willst.“","style":"deeskalierend","reaction":"„*lächelt* Das ist das Schönste, was man sagen kann. Setz dich her, erzähl mir lieber von dir.“","feedback":"Mission gelungen. Aufmerksames Zuhören hat das Misstrauen von der Parole zum Bedürfnis geführt, und Karl entscheidet sich selbst für den vernünftigen Weg.","score":3}]},"step-struggle":{"id":"step-struggle","speaker":"Opa Karl","speech":"„Wir gehen hin, ja. Aber heute muss ich mir das erst einmal in Ruhe durch den Kopf gehen lassen.“","options":[{"text":"„Lass dir Zeit, Opa. Wir sind im Gespräch geblieben, und das ist schon viel. Ich melde mich vor dem Termin noch einmal, einverstanden?“","style":"deeskalierend","reaction":"„*nickt* Das ist in Ordnung. Danke, dass du dich kümmerst.“","feedback":"Ein guter Ausstieg (in Verbindung mit Geduld): Die Beziehung ist intakt, der Weg zur Ärztin offen. Das eigentliche Anliegen ist aber noch nicht gelöst.","score":1}]},"step-fail":{"id":"step-fail","speaker":"Opa Karl","speech":"„Ich sehe schon, mit dir kann man darüber nicht reden. Dann mache ich das eben mit mir selbst aus. Die Tabletten lasse ich weg!“ *steht auf und geht*","options":[{"text":"Ende: Opa Karl fühlte sich nicht gehört und zieht sich auf seine Position zurück. Wer zuerst widerlegt, statt zu verstehen, verliert oft beides: das Gespräch und das Vertrauen.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst zuhören, paraphrasieren und das Gefühl ernst nehmen, bevor es um Inhalte geht.","feedback":"Frage dich: Wollte ich Karl zuhören oder ihn überzeugen? Aktives Zuhören heißt, die Geschichte hinter der Parole zu verstehen, statt sie sofort zu widerlegen.","score":0}]}},"status":"entwurf","familie":"kritik-braucht-adresse","fertigkeit":"F3","stufe":4,"kurz":"Hinter einer Parole wie „Big Pharma“ steckt oft ein wahrer Kern, denn Geldinteressen der Industrie sind real. Wer zuerst zuhört und nach der Geschichte dahinter fragt, kann berechtigte Kritik an einem konkreten Missstand von pauschaler Verdächtigung unterscheiden.","prueffrage":"Welcher konkrete Vorfall steht hinter dem großen Satz über „Big Pharma“, und wie viele Ärzte und Hersteller betrifft er tatsächlich?","quellen":[{"typ":"url","kurz":"Lundh, A.; Lexchin, J.; Mintzes, B.; Schroll, J. B.; Bero, L. (2017): Industry sponsorship and research outcome. Cochrane Database of Systematic Reviews, MR000033 (Zusammenfassung)","oeffentlich":true,"url":"https://www.cochrane.org/MR000033/METHOD_industry-sponsorship-and-research-outcome","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Braun, V.; Burian, R.; Diefenbacher, A. (Hrsg.) (2016): Arzt-Patienten-Gespräche bei stressassoziierten Erkrankungen. Berlin: De Gruyter, Kap. 3","oeffentlich":false}],"thema":"Gesundheit"},{"id":"scen-pilot-gedaechtnistraining","title":"Ayse und das Hirnjogging-App-Abo","subtitle":"Gehirntraining macht klüger, geübt mit Neuroplastizität und Konzentration","character":"Ayse","avatar":"🧩","context":"Deine Kollegin Ayse hat vor drei Monaten ein Jahresabo für eine Gehirntraining-App abgeschlossen und spielt seitdem jeden Morgen zwanzig Minuten. Heute schwärmt sie in der Kaffeeküche, ihr Gehirn werde „von Tag zu Tag fitter“, und möchte, dass du dir auch ein Abo holst.","goal":"Nimm Ayses Wunsch nach geistiger Fitness ernst, höre aktiv zu und lenke das Gespräch mit offenen Fragen darauf, was das Training eigentlich belegt, ohne dass sie sich belehrt fühlt.","bereich":"Ich selbst","laenge":"mittel","ton":"ernst","bestehenAb":6,"lektion":"Neuroplastizität heißt nicht, dass jedes Training das ganze Gehirn verbessert: Das Gehirn wird vor allem in dem besser, was es übt. Wer Wirkung behauptet, sollte nach dem Beleg gefragt werden, nach der Übertragung auf ungeübte Aufgaben und nach der Effektgröße. Auch Behauptungen wie „schützt vor Demenz“ gehen über das Geübte hinaus und verlangen eigene Belege. Mit aktivem Zuhören fühlt sich Ayse ernst genommen und prüft ihre Annahme am Ende selbst.","toolRef":"H.1.5","faktenRef":"A.24","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Ayse","speech":"„Ehrlich, seit ich jeden Morgen meine Gehirn-App spiele, fühle ich mich viel schärfer! Mein Gehirn wird jeden Tag trainiert, das ist wie Muskelaufbau. Du solltest das auch machen, das schützt sogar vor Demenz!“","options":[{"text":"„Ayse, das ist Marketing. Diese Apps wirken nicht, das weiß doch jeder. Du hast schlicht Geld für nichts ausgegeben.“","style":"frontal","reaction":"„Wow, danke. Ich dachte, du freust dich für mich. Dann spiele ich eben allein weiter.“ *wendet sich ab*","feedback":"Frontalangriff: Du wertest ihre Entscheidung ab und behauptest ein Pauschalurteil, das du nicht belegst. Ayse macht dicht, statt nachzudenken.","score":-2,"nextStepId":"step-fail"},{"text":"„Das klingt, als hättest du in den letzten Wochen etwas Besonderes an dir bemerkt. Woran merkst du denn konkret, dass du schärfer bist?“","style":"deeskalierend","reaction":"„Hm, gute Frage. Ich bin in den Spielen echt schneller geworden, und morgens komme ich besser in den Tag.“","feedback":"Aktives Zuhören: Du spiegelst ihre Wahrnehmung und fragst offen nach. So sammelst du, woran sie ihren Eindruck festmacht, ohne etwas zu bestreiten.","score":3,"nextStepId":"step-2"},{"text":"„Oh, super! Schick mir den Link, dann nehme ich auch das Jahresabo. Sag mal, welches Paket hast du denn genommen?“","style":"affektiv","reaction":"„Das Premium-Paket! Ich schicke dir gleich meinen Empfehlungslink, dann kriegen wir beide einen Monat gratis.“","feedback":"Du bestätigst die Behauptung, ohne sie zu prüfen, und gibst die Chance auf ein Gespräch auf. Freundlich, aber ohne jeden Erkenntnisgewinn.","score":-1,"nextStepId":"step-fail-link"}]},"step-2":{"id":"step-2","speaker":"Ayse","speech":"„In den Spielen werde ich einfach immer besser, die Punktzahl steigt jede Woche. Da muss sich doch etwas in meinem Gehirn verändert haben, das ist ja Neuroplastizität!“","options":[{"text":"„Genau, das Gehirn passt sich an das an, was es oft tut, also wirst du in diesen Spielen besser. Spannend ist, ob sich das auch auf andere Dinge überträgt. Wie würdest du das herausfinden?“","style":"sokratisch","reaction":"„Hm. Das ist tatsächlich nicht dasselbe, oder? In der App bin ich besser. Ob ich im Büro fokussierter bin, habe ich nie nachgemessen.“","feedback":"Treffend: Du bestätigst das Richtige an ihrer Idee (Gehirn passt sich an Geübtes an) und stellst die Übertragungsfrage als gemeinsame Denkaufgabe. Sie entdeckt die Lücke selbst.","score":3,"nextStepId":"step-3-success"},{"text":"„Neuroplastizität ist nur ein Fachwort. Das Gehirn kann sich bei Erwachsenen kaum noch verändern, und deine Punktzahl sagt darüber gar nichts, du machst dir da was vor.“","style":"frontal","reaction":"„Ach komm, das stimmt doch gar nicht! Ich habe gelesen, dass das Gehirn sich ständig umbaut. Du redest, als wüsstest du alles besser.“","feedback":"Falsch und provozierend: Auch das erwachsene Gehirn verändert sich durch Erfahrung. Mit einer sachlich falschen Gegenbehauptung verlierst du Ayses Vertrauen.","score":-2,"nextStepId":"step-3-struggle"},{"text":"„Punkte steigen in so einer App ja leicht, ich habe da ein komisches Gefühl. Aber mach ruhig weiter, du musst es wissen, ich halte mich da lieber raus.“","style":"ausstieg","reaction":"„Ein komisches Gefühl? Na toll. Dann halt nicht.“ *schaut genervt auf ihr Handy*","feedback":"Vage Andeutung und dann Rückzug: Du säst Zweifel, ohne zu erklären oder zu fragen. Das wirkt abwertend und lässt Ayse allein.","score":-1,"nextStepId":"step-3-struggle"}]},"step-3-success":{"id":"step-3-success","speaker":"Ayse","speech":"„Wenn ich ehrlich bin, weiß ich gar nicht, ob die App überhaupt etwas für den Alltag bringt. Ich habe einfach den Werbeversprechen geglaubt. Woran würde ich das denn erkennen?“","options":[{"text":"„Gute Frage. Ich würde nachsehen, ob Studien zeigen, dass das Training auch bei Aufgaben hilft, die nicht in der App vorkommen. Wollen wir das heute Abend zusammen nachlesen?“","style":"sokratisch","reaction":"„Ja, gern! Ich will wissen, wofür ich zahle. Ich schaue mir das Abo-Kleingedruckte auch noch mal an.“","feedback":"Stark: Du lieferst das Kriterium (Übertragung auf Ungeübtes, Effektgröße) als gemeinsames Rechercheprojekt, statt ein Urteil zu fällen.","score":3},{"text":"„Nimm dir doch erst mal eine Woche ohne App und achte darauf, ob du dich anders fühlst. Mehr braucht es nicht, dein Gefühl sagt dir schon genug darüber.“","style":"deeskalierend","reaction":"„Eine Woche ohne? Das ist ja fast ein Selbstversuch. Okay, ich probiere es.“","feedback":"Brauchbar, aber schwach: Ein Selbsteindruck ohne Vergleich beweist wenig. Das Subjektive bleibt unkontrolliert, die Frage nach Übertragung und Effektgröße bleibt offen.","score":1},{"text":"„Ach, sei einfach vorsichtig mit solchen Apps, die wollen doch alle nur dein Geld. Ich würde die Finger davon lassen, die Werbung verspricht immer zu viel.“","style":"frontal","reaction":"„Aha, also sind alle Betrüger? Du machst es dir leicht.“","feedback":"Pauschale Abwertung statt Prüfkriterium. Du gibst Ayse nichts an die Hand, womit sie selbst bewerten kann, und lädst sie zur Verteidigung ein.","score":-1}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Ayse","speech":"„Ich weiß nicht, ob ich das glauben soll. Mein Gefühl sagt, dass mir die App guttut. Und jetzt verunsicherst du mich auch noch.“","options":[{"text":"„Dein Gefühl nehme ich ernst. Lass uns zusammen schauen, ob es Belege gibt, dass so ein Training über die Spiele hinaus hilft. Wenn ja, bist du bestätigt.“","style":"deeskalierend","reaction":"„Okay. Wenn es Belege gibt, freue ich mich ja. Dann schauen wir nach.“","feedback":"Guter Neustart: Du würdigst ihr Gefühl, setzt die Prüfung als gemeinsames Projekt auf und lässt beide Ausgänge zu.","score":2},{"text":"„Nein, ganz im Ernst, da bringt dir das nichts. Hör auf damit und spar dir das Geld, es gibt wirklich bessere Wege, das Gedächtnis zu trainieren.“","style":"frontal","reaction":"„Du klingst, als wüsstest du es besser als jeder Entwickler! Lass mich einfach in Ruhe.“","feedback":"Rückfall in die Belehrung: Ohne Beleg und ohne Frage klingt das nach Besserwisserei. Ayse wird sich nur noch fester an ihre App binden.","score":-2},{"text":"„Alles gut, vergiss, was ich gesagt habe. Hauptsache, es macht dir Spaß und du fühlst dich wohl damit. Wollen wir einen Kaffee holen gehen?“","style":"ausstieg","reaction":"„Ja, gern. Danke, dass du es lässt. Kaffee ist eine gute Idee.“","feedback":"Ruhiger Rückzug: Die Beziehung bleibt heil, die Sachfrage bleibt offen. Ein friedlicher Ausstieg, aber ohne Impuls zum Weiterdenken.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Ayse","speech":"„Egal, ich mache meine Morgenrunde in der App weiter. Ich fühle mich gut dabei, und das ist die Hauptsache.“","options":[{"text":"Ende: Das Gespräch ist beendet, bevor die Frage nach dem Beleg überhaupt gestellt wurde.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst zuhören und nachfragen, woran Ayse die Wirkung festmacht.","feedback":"Aktives Zuhören öffnet die Tür für die Prüffrage: Wer erst bestätigt oder abkanzelt, kommt nicht mehr zur Sache.","score":0}]},"step-fail-link":{"id":"step-fail-link","speaker":"Ayse","speech":"„Super, ich schicke dir gleich den Link! Dann trainieren wir beide jeden Morgen, das wird toll.“","options":[{"text":"Ende: Das Gespräch endet freundlich, aber ohne dass die Frage nach dem Beleg gestellt wurde.","style":"ausstieg","reaction":"Beim nächsten Mal erst nachfragen, woran Ayse die Wirkung festmacht, bevor du ein Abo abschließt.","feedback":"Aktives Zuhören heißt auch, nachzufragen statt nur zuzustimmen: Wer sofort mitzieht, prüft den Beleg nie.","score":0}]}},"status":"entwurf","familie":"befund-reichweite","fertigkeit":"F1","stufe":3,"kurz":"Wer in einem Gehirntraining besser wird, ist vor allem in den geübten Aufgaben besser geworden. Ob sich das auf ungeübte Alltagsaufgaben überträgt oder gar vor Demenz schützt, ist eine eigene Behauptung und braucht eigene Belege.","prueffrage":"Woran wird der Fortschritt gemessen, und wurde er je bei Aufgaben außerhalb der App überprüft?","quellen":[{"typ":"url","kurz":"Association for Psychological Science: Simons, D. J. u. a. (2016): Do „Brain-Training“ Programs Work? Psychological Science in the Public Interest 17(3), 103–186 (DOI 10.1177/1529100616661983)","oeffentlich":true,"doi":"10.1177/1529100616661983","url":"https://www.psychologicalscience.org/publications/brain-training.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Federal Trade Commission (05.01.2016): Lumosity to Pay $2 Million to Settle FTC Deceptive Advertising Charges for Its „Brain Training“ Program","oeffentlich":true,"url":"https://www.ftc.gov/news-events/news/press-releases/2016/01/lumosity-pay-2-million-settle-ftc-deceptive-advertising-charges-its-brain-training-program","abruf":"2026-10-12"},{"typ":"doi","kurz":"Owen, A. M. u. a. (2010): Putting brain training to the test. Nature 465(7299), 775–778","oeffentlich":false,"doi":"10.1038/nature09042"}],"thema":"Psychologie"},{"id":"scen-papa-ohne-gurt","title":"Papa fuhr ohne Gurt und lebt noch","subtitle":"Überlebensirrtum, geübt mit intellektueller Barmherzigkeit","character":"Wolfgang, Papa","avatar":"🚗","context":"Dein Vater Wolfgang hilft dir beim Umzug und hat die Autoschlüssel in der Hand. Als du erwähnst, dass du den kleinen Neffen nur mit Kindersitz und Gurt mitnehmen wirst, winkt er lachend ab: Früher sei man auch ohne alles gefahren, und es sei ja nichts passiert.","goal":"Bring Papa dazu, die Frage nach denen zu stellen, die er nicht mehr erzählen hören kann, ohne dass er sich vorgeführt fühlt, und achte dabei auf seine guten Motive.","bereich":"Familie","laenge":"mittel","ton":"heiter","bestehenAb":6,"lektion":"Der Überlebensirrtum entsteht, weil nur die Davongekommenen ihre Geschichte erzählen; die Verunglückten fehlen in der Erinnerung. Mit der Frage „Wo ist der Friedhof?“ lässt sich das aufdecken, am besten mit intellektueller Barmherzigkeit: Du würdigst zuerst Papas gute Absicht (Gelassenheit, Fürsorge, Erfahrung) und stellst dann die Frage nach den unsichtbaren Daten. So wird die Behauptung seziert, nicht der Mensch.","toolRef":"H.1.3","faktenRef":"B.15","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Wolfgang, Papa","speech":"„Ach, jetzt macht ihr wegen dem bisschen Autofahren so ein Theater! Wir sind früher alle ohne Gurt gefahren, mit vier Kindern auf der Rückbank, und schau uns an: Wir leben alle noch! Das ist doch übertriebene Vorsicht heutzutage.“","options":[{"text":"„Papa, das ist ein klassischer Denkfehler. Du bist ein Beispiel für den Überlebensirrtum, und dass du so etwas noch glaubst, wundert mich ehrlich gesagt sehr.“","style":"frontal","reaction":"„Ach so, ich bin also zu blöd, das zu verstehen? Ich fahre seit vierzig Jahren Auto, und mir erklärt jetzt jemand mit Fachwörtern die Welt!“ *verschränkt die Arme*","feedback":"Die Sache stimmt, aber du packst Papa mit einem Etikett in die Schublade. Ohne Barmherzigkeit hört er nur Geringschätzung, nicht das Argument.","score":-2,"nextStepId":"step-fail"},{"text":"„Mir ist klar, dass dir wichtig ist, dass wir uns nicht verrückt machen lassen. Darf ich dich was fragen: Woher kennst du die Geschichten von früher, bei denen es ohne Gurt gut ausging?“","style":"sokratisch","reaction":"„*schmunzelt* Na von uns selbst, von den Nachbarn, vom Onkel Heinz... Die haben das alle überstanden. Wieso fragst du?“","feedback":"Stark! Du erkennst seine gute Absicht an und lenkst mit einer offenen Frage auf die Quelle seiner Geschichten, ohne ihn zu belehren.","score":3,"nextStepId":"step-2"},{"text":"„Da hast du schon recht, Papa, früher ging es ja irgendwie auch. Ich schnalle den Kleinen halt trotzdem an, damit Mama sich keine Sorgen macht und wir Ruhe haben.“","style":"ausstieg","reaction":"„Siehst du, ich sag ja: übertrieben. Aber mach du nur, wenn es dich beruhigt.“ *winkt gönnerhaft ab*","feedback":"Du vermeidest Streit, aber Papas Schluss bleibt unangetastet und gilt sogar als bestätigt. Der Überlebensirrtum wird so nicht berührt.","score":0,"nextStepId":"step-2-wave"}]},"step-2":{"id":"step-2","speaker":"Wolfgang, Papa","speech":"„Na ja, der Heinz ist damals mit dem Auto in den Graben gerutscht, ohne Gurt, und hat sich nur den Arm geprellt. Der erzählt die Geschichte heute noch jedes Mal bei der Familienfeier. Das ist doch der Beweis, dass es nicht so schlimm ist!“","options":[{"text":"„Heinz erzählt die Geschichte, und das ist der Punkt: Wir hören sie, weil er davongekommen ist. Von denen, die es nicht geschafft haben, hören wir nichts mehr.“","style":"sokratisch","reaction":"„*stutzt* Hm. Du meinst, die, bei denen es nicht gut ausging, hört man einfach nicht mehr? ...Stimmt, bei Heinz' Kollegen damals, der Unfall auf der Landstraße... davon hat keiner mehr groß erzählt.“","feedback":"Treffend: Du benennst den Kern von „Der Überlebensirrtum“ (die Toten erzählen keine Geschichten) in Papas eigener Welt. Er kommt selbst auf ein Gegenbeispiel.","score":3,"nextStepId":"step-3"},{"text":"„Papa, das ist reiner Zufall, dass Heinz so glimpflich davongekommen ist. Verlass dich nicht auf so was, das ist unverantwortlich und gefährlich!“","style":"frontal","reaction":"„Unverantwortlich?! Ich habe euch alle heil durchs Leben gebracht! Wer sagt hier, was verantwortlich ist?“","feedback":"Du trittst auf seinen Stolz als fürsorglichen Vater (fordert, seine guten Motive zu sehen). Aus „Unsinn“ wird ein persönlicher Angriff.","score":-1,"nextStepId":"step-struggle"},{"text":"„Komisch: Auf Familienfeiern erzählen immer nur die, die es überlebt haben, oder? Woran liegt das wohl, Papa? Fällt dir da was auf?“","style":"humorvoll","reaction":"„*lacht kurz, dann nachdenklich* Weil die anderen nicht mehr da sind, meinst du? Das ist ein bisschen düster für einen Samstag...“","feedback":"Der Hinweis trifft ins Schwarze, aber die Frage ist etwas verschlungen. Papa ahnt die Richtung, doch du hilfst ihm nicht beim Weg dorthin.","score":1,"nextStepId":"step-3"}]},"step-2-wave":{"id":"step-2-wave","speaker":"Wolfgang, Papa","speech":"„Siehst du. Und ehrlich: Mein Vater hat uns auch nie angeschnallt und ist 90 geworden. Heutzutage wird alles in Watte gepackt.“","options":[{"text":"„Papa, ich mag, wie du deinen Vater ehrst. Aber überleg mal: Wie viele Leute von damals hat man nach so einer Fahrt nicht mehr wiedergesehen?“","style":"sokratisch","reaction":"„*zögert* Na ja, da gab es schon welche, die bei Unfällen... aber das war halt Schicksal. Das wusste man damals.“","feedback":"Gute Wende: Du ehrst seine Loyalität zum Vater und führst auf die Fehlenden hin. Er wird nachdenklich, braucht aber noch einen Schubs.","score":2,"nextStepId":"step-3"},{"text":"„Dein Vater hatte schlicht Glück. Mit so einem Argument kann man bei dem Thema ja jeden Quatsch rechtfertigen, das ist doch kein Beweis.“","style":"sarkastisch","reaction":"„Quatsch?! Mein Vater war ein vernünftiger Mann! Weißt du was, fahr du deine Gurte, und ich fahr meinen Stiefel.“","feedback":"Der Seitenhieb gegen den Vater und seine Argumente löst Abwehr aus. Ohne Barmherzigkeit landet das Gespräch im Streit.","score":-2,"nextStepId":"step-fail"},{"text":"„Stimmt schon, früher war manches entspannter. Komm, lass uns die Kartons einladen, bevor es dunkel wird, und dann trinken wir einen Kaffee.“","style":"ausstieg","reaction":"„Na endlich Vernunft! Pack du die schweren, ich bin ja schon ein alter Mann.“ *zwinkert*","feedback":"Der Frieden bleibt gewahrt, aber das Thema versandet. Der Irrtum bleibt unbesprochen, der Kleine sitzt nächstes Mal mit demselben Spruch im Auto.","score":0,"nextStepId":"step-struggle"}]},"step-3":{"id":"step-3","speaker":"Wolfgang, Papa","speech":"„Na gut, vielleicht hört man von denen weniger. Aber ich will halt auch nicht, dass die Kinder mit lauter Angst aufwachsen. Man muss die Kinder ja auch mal leben lassen.“","options":[{"text":"„Das ist ein guter Punkt, Papa: Du willst den Kleinen Mut und Freiheit mitgeben. Ich denke an die, deren Unfallgeschichten niemand mehr erzählt, und möchte beides geben. Passt das?“","style":"deeskalierend","reaction":"„*lacht leise* Beides also... na gut, du Schlaukopf. Mut und Gurt. Aber nur, weil du mich nicht für dumm verkauft hast.“","feedback":"Vorbildlich: Du würdigst Papas guten Wert, verbindest ihn mit dem Gurt und hältst die Frage nach den Fehlenden im Raum. Der Mensch wird nicht seziert.","score":3,"nextStepId":"step-success"},{"text":"„Mut lernt man nicht ohne Gurt. Wenn du das wirklich glaubst, Papa, hast du den Kern der Sache nicht verstanden, und darüber diskutiere ich nicht länger.“","style":"frontal","reaction":"„Ich hab den Kern nicht verstanden?! Ich habe vier Kinder großgezogen! Ich sage nur: übertreib es nicht.“ *brummt und dreht sich weg*","feedback":"Ein Satz, der trifft, aber den Menschen abwertet („nicht verstanden“). Seine Sorge ums Aufwachsen der Kinder war ein legitimer Wert, und der geht verloren.","score":-1,"nextStepId":"step-struggle"},{"text":"„Genau, und ich schnalle den Kleinen an, Mut hat er auch so genug. Mehr gibt es dazu nicht zu sagen, damit ist das Thema für mich erledigt.“","style":"ausstieg","reaction":"„Wie du meinst. Dann machen wir es halt, wie du willst.“ *zuckt mit den Schultern*","feedback":"Ergebnis stimmt, aber du lässt die Frage nach den Fehlenden und Papas gute Absicht unbesprochen. So bleibt wenig Verständnis hängen.","score":1,"nextStepId":"step-struggle"}]},"step-success":{"id":"step-success","speaker":"Wolfgang, Papa","speech":"„Weißt du, bei Heinz hab ich gar nie gefragt, wie viele andere damals nicht so viel Glück hatten. Wo sind eigentlich die ganzen Geschichten, die keiner erzählt?“","options":[{"text":"„Genau diese Frage ist Gold wert, Papa. Wer nicht mehr erzählt, fehlt in unseren Erinnerungen. Komm, ich fahre, du erzählst mir auf dem Weg die Heinz-Geschichte noch mal, und wir schnallen alle an.“","style":"humorvoll","reaction":"„*grinst* Abgemacht, aber ich erzähle sie diesmal mit dem Gurt. Dann hat Heinz auch mal eine Pointe mehr.“","feedback":"Mission gelungen! Mit Barmherzigkeit und der Frage nach den Fehlenden hat Papa selbst den Überlebensirrtum entdeckt, ohne dass sein Gesicht gelitten hat.","score":3}]},"step-struggle":{"id":"step-struggle","speaker":"Wolfgang, Papa","speech":"„Ich weiß schon, was du sagen willst. Aber das kann doch alles nicht stimmen. Wir haben es doch alle überlebt, das ist halt meine Erfahrung.“","options":[{"text":"„Deine Erfahrung ist echt, Papa, und ich schätze, dass du uns heil durchgebracht hast. Ich hätte nur gern auch die im Blick, von denen man nichts mehr hört. Magst du drüber schlafen?“","style":"deeskalierend","reaction":"„*seufzt* Drüber schlafen kann ich. Und den Kleinen schnall ich halt an, damit du Ruhe hast.“","feedback":"Solider Rückzug: Du würdigst seine Erfahrung und lässt die Frage nach den Fehlenden offen. Nicht überzeugt, aber die Tür bleibt auf.","score":2},{"text":"„Ach Papa, du bist halt stur. Dann fahr eben ohne Gurt, wenn dir das lieber ist, aber wundere dich nicht, wenn ich mir dabei meinen Teil denke und das auch sage.“","style":"sarkastisch","reaction":"„Na bitte, jetzt wirst du auch noch patzig. Ich hab keine Lust mehr auf diese Diskussion.“","feedback":"Das Etikett „stur“ und der Sarkasmus lassen die Sache und die Beziehung auf der Strecke. Barmherzigkeit geht anders.","score":-1}]},"step-fail":{"id":"step-fail","speaker":"Wolfgang, Papa","speech":"„Ich hab keine Lust, mich von dir belehren zu lassen. Wir haben es früher gut gemacht, und fertig. Pack die Kartons, ich fahr dann.“ *greift die Schlüssel und geht*","options":[{"text":"Ende: Papa fühlte sich vorgeführt oder nicht ernst genommen, der Überlebensirrtum bleibt unberührt. Das Beste wäre gewesen, zuerst seine gute Absicht zu sehen und dann zu fragen, wo die Fehlenden sind.","style":"ausstieg","reaction":"Beim nächsten Mal: zuerst anerkennen, was Papa wichtig ist, dann die Frage „Wo ist der Friedhof?“ stellen.","feedback":"Frage dich: Wollte ich Papa belehren oder verstehen? Seziert wird die Behauptung, nicht der Mensch.","score":0}]}},"status":"entwurf","familie":"fehlende-faelle-suchen","fertigkeit":"F2","stufe":2,"kurz":"Von früher erzählen nur die, die davongekommen sind; wer verunglückt ist, fehlt in der Erinnerung (Überlebensirrtum). Viele gut ausgegangene Geschichten zeigen deshalb nicht, dass das Risiko klein war.","prueffrage":"Wer erzählt heute die Geschichten von den Fahrten ohne Gurt, und wer fehlt in dieser Runde?","quellen":[{"typ":"url","kurz":"Wald, A. (1943/1980): A Reprint of „A Method of Estimating Plane Vulnerability Based on Damage of Survivors“. CNA","oeffentlich":true,"url":"https://cna.org/reports/1980/a-method-of-estimating-plane-vulnerability","abruf":"2026-10-12"},{"typ":"doi","kurz":"Mangel, M.; Samaniego, F. J. (1984): Abraham Wald's Work on Aircraft Survivability. JASA 79(386), 259–267","oeffentlich":false,"doi":"10.1080/01621459.1984.10478038"},{"typ":"url","kurz":"Malpas, J.: Donald Davidson. Stanford Encyclopedia of Philosophy (überarb. 28.04.2023), Abschn. 3.3","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"scen-wetter-gestern-heute","title":"Rentner Walters Wetterbeweis","subtitle":"Klima gegen Wetter, geübt mit intellektueller Barmherzigkeit","character":"Walter","avatar":"❄️","context":"Dein Nachbar Walter, Rentner und leidenschaftlicher Hobby-Gärtner, steht nach dem kältesten Januar seit Jahren an der Hecke. Er hält dir seine Frostschäden an den Rosen unter die Nase und verkündet, damit sei der Klimawandel ja wohl erledigt.","goal":"Bring Walter dazu, selbst zwischen Wetter und Klima zu unterscheiden, indem du zuerst seine nachvollziehbare Sorge ernst nimmst und ihn dann mit Fragen statt Vorträgen zum Nachdenken führst.","bereich":"Nachbarschaft","laenge":"mittel","ton":"heiter","bestehenAb":6,"lektion":"Ein kalter Winter ist Wetter, der Hund, der wild über die Wiese läuft. Das Klima ist der Spaziergänger, dessen Richtung sich erst über Jahrzehnte zeigt. Wer wie Walter nachvollziehbare Gründe hat, hört eher zu, wenn du zuerst seine Sorge würdigst und die Behauptung erst danach prüfst.","toolRef":"H.1.3","faktenRef":"C.5.1","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Walter","speech":"„Schau dir das an, meine armen Rosen! Minus zwanzig Grad, alles erfroren! Und im Fernsehen reden sie von Erderwärmung. Ich sag's dir: Wenn das Wärme ist, fress ich meinen Gartenhut!“","options":[{"text":"„Walter, das ist der älteste Denkfehler überhaupt: Du verwechselst Wetter mit Klima. Das lernt man doch in der Schule. Wie kann man da noch so argumentieren?“","style":"frontal","reaction":"„Aha, jetzt bin ich also auch noch ungebildet! Ich habe dreißig Jahre gearbeitet und weiß, was kalt ist. Lass mich in Ruhe mit deinen Schlaumeiereien!“ *wendet sich brummend ab*","feedback":"Der Fachbegriff stimmt, aber der Ton macht aus Walter einen Dummen. Genau das widerspricht dem Prinzip der intellektuellen Barmherzigkeit: Er fühlt sich angegriffen und schaltet auf Abwehr.","score":-2,"nextStepId":"step-fail"},{"text":"„Das ist wirklich bitter, Walter. Man sieht, wie viel Herzblut du in diesen Garten steckst. Erzähl mal: Wie kalt war es denn so über den ganzen Winter?“","style":"deeskalierend","reaction":"„*wird sofort milder* Siehst du, du verstehst das! Zwei Wochen am Stück eisig, nachts bis minus zwanzig. So was hab ich lange nicht erlebt.“","feedback":"Gut! Du erkennst seine nachvollziehbare Sorge an, ohne die Behauptung zu bestätigen. Walter fühlt sich ernst genommen und bleibt im Gespräch.","score":3,"nextStepId":"step-2"},{"text":"„Ach Walter, vielleicht hast du ja recht. Bei dieser Kälte kann man das mit der Erwärmung wirklich kaum glauben.“","style":"ausstieg","reaction":"„Na siehst du! Endlich sagt's mal einer. Die Wissenschaftler sollten mal vor die Tür gehen, dann wüssten sie's besser!“","feedback":"Du vermeidest den Streit, bestätigst aber den Denkfehler. Freundlichkeit ist nicht dasselbe wie Zustimmung: Barmherzigkeit heißt, die Person zu würdigen, nicht ihren Irrtum.","score":-1,"nextStepId":"step-weak"}]},"step-2":{"id":"step-2","speaker":"Walter","speech":"„Genau, zwei Wochen Dauerfrost! Wenn die Erde sich erwärmen würde, dürfte es so was doch gar nicht mehr geben. Das ist doch logisch, oder?“","options":[{"text":"„Wenn du magst: Stell dir vor, du gehst mit deinem Hund über eine große Wiese, der Hund läuft mal vor, mal zurück, mal seitwärts. Woran erkennst du, wohin du selbst unterwegs bist?“","style":"sokratisch","reaction":"„*lacht* Mein Hund Bello? Der rennt kreuz und quer! Ob ich vorwärtsgehe, sehe ich doch an mir, nicht an Bello.“","feedback":"Sehr gut! Die Analogie von Spaziergänger und Hund kommt als Frage statt als Belehrung. Walter entdeckt den Kern selbst, und der Vergleich stammt aus seinem eigenen Alltag.","score":3,"nextStepId":"step-3"},{"text":"„Klima ist der Durchschnitt über dreißig Jahre, Wetter der Zustand an einem Tag. Zwei kalte Wochen ändern an einem Dreißigjahresmittel praktisch nichts.“","style":"frontal","reaction":"„Dreißig Jahre, Durchschnitt, soso... Das klingt mir nach Zahlenspielerei. Ich glaube meinen Augen mehr als irgendwelchen Statistiken.“","feedback":"Inhaltlich richtig, aber als Vortrag abgeliefert. Er hört eine Statistik gegen seine persönliche Erfahrung. Eine Frage oder ein Bild aus seiner Welt hätte mehr bewegt.","score":1,"nextStepId":"step-3-struggle"},{"text":"„Dann schick doch deine erfrorenen Rosen an die Wissenschaftler, Walter. Die haben bestimmt noch nie gemerkt, dass es im Winter kalt ist.“","style":"sarkastisch","reaction":"„Willst du dich über mich lustig machen? Dann red doch mit deinen Klimaleuten, aber nicht mit mir!“","feedback":"Spott richtet sich gegen den Menschen statt gegen die Behauptung. Wer verhöhnt wird, verteidigt seine Position nur noch trotziger.","score":-2,"nextStepId":"step-fail"}]},"step-3":{"id":"step-3","speaker":"Walter","speech":"„Na gut, Bello ist nicht der Maßstab, ich bin es. Aber was hat das jetzt mit dem Klima zu tun? Ist die Kälte dann der Hund?“","options":[{"text":"„Genau, der kalte Januar ist Bello, der gerade zufällig nach hinten rennt. Wohin der Spaziergänger geht, sieht man erst, wenn man lange zuschaut. Wie sähe das in deinem Garten aus?“","style":"sokratisch","reaction":"„Hm... Wenn ich mir meine Gartenbücher ansehe, wann ich im Frühjahr säen konnte... Da müsste man über viele Jahre vergleichen. Ein einzelner Winter sagt da wenig.“","feedback":"Treffer! Wetter ist der kurzfristige, chaotische Zustand, Klima der langfristige Durchschnitt. Walter überträgt den Gedanken selbst auf seine Gartenerfahrung.","score":3,"nextStepId":"step-4"},{"text":"„Du hast es erfasst, Walter! Dann siehst du ja: Der Klimawandel ist bewiesen und du musst deine Meinung einfach ändern, daran führt kein Weg vorbei.“","style":"frontal","reaction":"„Moment, Moment, so schnell lasse ich mich nicht überfahren. Ich habe nur gesagt, dass Bello nicht der Maßstab ist!“","feedback":"Du drängst auf ein Ergebnis, bevor Walter seinen Gedanken zu Ende geführt hat. Wer überrumpelt wird, zieht sich zurück, statt nachzudenken.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Die Kälte ist eben nur das Wetter, Walter. Ist ja nicht schlimm, wenn man das mal verwechselt. Wird schon wieder wärmer, dann sieht die Welt anders aus, versprochen.“","style":"ausstieg","reaction":"„Wird schon wieder wärmer, na eben. Dann ist doch alles in Ordnung, oder?“","feedback":"Du lässt die Frage in der Schwebe, und Walter nimmt daraus 'alles halb so wild' mit. Die Chance, das Konzept zu klären, bleibt ungenutzt.","score":-1,"nextStepId":"step-weak"}]},"step-4":{"id":"step-4","speaker":"Walter","speech":"„Na gut, ein Winter sagt nicht viel. Aber mir fällt noch was ein: Wenn die Erde sich erwärmt, wie kann es dann überhaupt noch solche Kälteeinbrüche geben? Das passt doch nicht zusammen!“","options":[{"text":"„Gute Frage, Walter. Wenn du in deinen Gartenbüchern zählst: Gab es früher mehr oder weniger solcher Frostwochen als heute? Und wie oft hattest du richtige Hitzesommer?“","style":"sokratisch","reaction":"„Hm, Frostwochen wie diese waren früher öfter, glaube ich, und die heißen Sommer häufen sich. Seltener, aber nicht weg. Dann ist mein Frost kein Gegenbeweis, nur ein kalter Hund.“ *schmunzelt*","feedback":"Sehr gut! Deine Frage lässt Walter selbst entdecken: Kälteextreme werden seltener und milder, verschwinden aber nicht. Einzelne Kälteeinbrüche sind Wetter, kein Gegenbeweis.","score":3,"nextStepId":"step-5-success"},{"text":"„Dazu braucht man ein Physikstudium, Walter. Das ist viel komplizierter, als man in zwei Sätzen erklären kann. Vertrau da einfach den Fachleuten.“","style":"ausstieg","reaction":"„Vertrau den Fachleuten! Das sagen sie immer, wenn sie keine Antwort haben. Dann bleibe ich lieber bei meinen Rosen.“","feedback":"Der Verweis auf Autorität statt einer verständlichen Erklärung wirkt ausweichend. Walters Frage war berechtigt und hätte eine Antwort verdient.","score":-1,"nextStepId":"step-weak"},{"text":"„Walter, so ein Einwand ist typisch für Leute, die sich nie mit der Sache beschäftigt haben. Das steht in jedem Lehrbuch.“","style":"frontal","reaction":"„Typisch für Leute wie mich? Na danke. Dann musst du mir ja nichts mehr erklären.“ *stapft verärgert zur Gartentür*","feedback":"Die Frage war sinnvoll und der Ton herablassend. Wer in einem guten Gespräch plötzlich abgestempelt wird, wird nicht klüger, sondern defensiver.","score":-2,"nextStepId":"step-fail"}]},"step-5-success":{"id":"step-5-success","speaker":"Walter","speech":"„Weißt du was, so habe ich das noch nie gesehen. Vielleicht schaue ich mir mal so eine Temperaturkurve über hundert Jahre an. Und jetzt komm, ich zeig dir, welche Rosen den Winter doch überstanden haben!“","options":[{"text":"„Sehr gern, Walter. Bring ruhig die Gartenbücher mit, vielleicht entdecken wir gemeinsam, was sich über die Jahre verändert hat.“","style":"humorvoll","reaction":"„Abgemacht! Aber Bello bleibt draußen, der buddelt mir sonst alles um.“ *lacht*","feedback":"Mission gelungen! Du hast Walter als vernünftigen Menschen behandelt, und er hat den Unterschied zwischen Wetter und Klima selbst erarbeitet.","score":3},{"text":"„Gern, Walter. Aber nur, wenn du jetzt endlich zugibst, dass du vorhin falsch lagst und ich von Anfang an recht hatte.“","style":"frontal","reaction":"„Falsch gelegen... na ja. Jetzt kommt der Triumph, was? Mir ist die Lust auf Rosen vergangen.“","feedback":"Kurz vor dem Ziel verlangst du ein Eingeständnis und setzt Walters Gesicht aufs Spiel. Ein gewonnenes Gespräch muss nicht mit einer Siegerpose enden.","score":0}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Walter","speech":"„Ich weiß nicht, das klingt alles so abgehoben. Statistik hin oder her, ich sehe halt, dass es kalt ist.“","options":[{"text":"„Das verstehe ich, Walter, deine erfrorenen Rosen sind ja real. Schau dir bei Gelegenheit selbst eine lange Temperaturkurve an und sag mir, was du siehst. Jetzt erst mal einen Kaffee?“","style":"deeskalierend","reaction":"„Eine Kurve anschauen kann nicht schaden, ich bin ja nicht stur. Aber ich bleibe skeptisch!“","feedback":"Gute Ausstiegsstrategie: Der Beziehung geht es gut, und Walter bekommt eine Aufgabe, die er selbst prüfen kann. Die Sachfrage bleibt offen, aber nicht verbrannt.","score":2},{"text":"„Wenn du dich der Statistik verweigerst, kann ich dir auch nicht helfen, Walter. Dann bleibt es eben bei deinem Gefühl, ich diskutiere nicht weiter und du bleibst bei deiner Meinung.“","style":"frontal","reaction":"„Dann brauche ich deine Hilfe eben nicht. Schönen Tag noch!“","feedback":"Du beendest das Gespräch mit einem Vorwurf. Walter hat nicht die Statistik verweigert, sondern sich überrumpelt gefühlt.","score":-1}]},"step-weak":{"id":"step-weak","speaker":"Walter","speech":"„Siehst du, wir sind uns ja im Grunde einig. Kalter Winter, keine Erderwärmung, ich wusste es!“","options":[{"text":"„Naja, ganz einig sind wir uns vielleicht nicht, Walter. Aber ich muss los, ein andermal mehr dazu. Schöne Rosen jedenfalls!“","style":"ausstieg","reaction":"„Bis bald, Nachbar! Und lass dir von niemandem was erzählen!“","feedback":"Ende mit Wermutstropfen: Walter geht mit dem Eindruck, ein kalter Winter widerlege den Klimawandel. Der Unterschied zwischen Wetter und Klima blieb ungeklärt.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Walter","speech":"„Ich hab's immer gesagt: Die Klugscheißer von heute haben keine Ahnung vom echten Leben!“ *schlägt das Gartentor zu*","options":[{"text":"Ende: Walter fühlte sich bloßgestellt und ist nun nicht klüger, sondern nur sturer. Seziert wird die Behauptung, nicht der Mensch.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst die Sorge hinter der Behauptung würdigen, dann erst fragen.","feedback":"Barmherzigkeit heißt, Walter als vernünftigen Menschen mit nachvollziehbaren Gründen zu behandeln: Er hat erfrorene Rosen gesehen, und das fühlt sich real an.","score":0}]}},"status":"entwurf","familie":"trend-statt-einzelfall","fertigkeit":"F4","stufe":1,"kurz":"Ein einzelner kalter Winter ist Wetter; ob sich das Klima verändert, zeigt erst der Vergleich über Jahrzehnte. Wer zuerst die nachvollziehbare Sorge des Gegenübers würdigt, findet eher Gehör, wenn danach die Behauptung geprüft wird.","prueffrage":"Über welchen Zeitraum spricht die Erderwärmung, und über welchen Zeitraum sprechen zwei Wochen Frost an Walters Rosen?","quellen":[{"typ":"url","kurz":"Deutscher Wetterdienst: Wetter- und Klimalexikon, „Klima“","oeffentlich":true,"url":"https://www.dwd.de/DE/service/lexikon/begriffe/K/Klima.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Malpas, J.: Donald Davidson. Stanford Encyclopedia of Philosophy (überarb. 28.04.2023), Abschn. 3.3","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"scen-und-was-ist-mit","title":"„Und was ist mit …?“ im Kommentarbereich","subtitle":"Whataboutism, geübt mit dem Management emotionaler Kosten","character":"xX_Dauerkommentator_Xx, anonymer Account","avatar":"💬","context":"Unter einem Beitrag über Homöopathie schreibst du, dass sie keine plausible Wirkung hat. Der anonyme Account xX_Dauerkommentator_Xx antwortet sofort mit einem Gegenvorwurf gegen die Schulmedizin. Er wirkt sehr sicher, rechnet fest damit, dass du verstummst, und kommentiert in Windeseile weiter.","goal":"Trenne die Sachfrage vom Gegenvorwurf, bleibe ruhig und entscheide bewusst, wie viel Energie dir diese Debatte wert ist.","bereich":"Online","laenge":"mittel","ton":"sarkastisch","bestehenAb":6,"lektion":"Ein Gegenvorwurf oder Themenwechsel (Whataboutism, Tu quoque) widerlegt das ursprüngliche Argument nicht: Ob die Schulmedizin Fehler macht, sagt nichts darüber, ob Homöopathie wirkt. Beide Aussagen müssen getrennt geprüft werden. Wer das benennt, kann die Debatte beenden, ohne zu verlieren, und mit dem Management emotionaler Kosten entscheidest du, ob sich weiterer Aufwand lohnt.","toolRef":"H.1.2","faktenRef":"D.1.5","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"xX_Dauerkommentator_Xx","speech":"„Haha, Homöopathie ‚wirkt nicht‘? Und WAS IST MIT den ganzen Nebenwirkungen und Todesfällen der Schulmedizin? Big Pharma will doch nur Geld verdienen! Erst mal vor der eigenen Tür kehren, Meister!“","options":[{"text":"„Typisch Esoterik-Fan: Euch fehlt jede Ahnung von Wissenschaft. Wer so argumentiert, hat sowieso nichts verstanden und braucht auch keine Antwort.“","style":"frontal","reaction":"„Oho, jetzt wird er persönlich! Wer beleidigt, hat verloren, mein Lieber! Screenshot gemacht!“","feedback":"Frontalangriff auf die Person. Der Gegenvorwurf war schon eine Form des Ad Hominem, und du antwortest mit einem weiteren. So lieferst du ihm Munition.","score":-2,"nextStepId":"step-fail"},{"text":"„Dass die Schulmedizin Fehler macht, kann ich nachvollziehen, aber das ist ein anderes Thema. Bleiben wir bitte bei meiner Frage: Welche Belege gibt es dafür, dass Homöopathie wirkt?“","style":"sokratisch","reaction":"„Ach, jetzt lenkst DU ab! Aber gut: Mir hat's geholfen, und meiner Cousine auch. Reicht das etwa nicht?“","feedback":"Sehr gut. Du erkennst den Gegenvorwurf an, trennst ihn von der Sachfrage und kehrst höflich zum Ausgangspunkt zurück (Der Anker & die Trennung, Skript 1).","score":3,"nextStepId":"step-2"},{"text":"„Stimmt, die Pharmaindustrie hat wirklich genug Dreck am Stecken. Vielleicht habe ich das Ganze zu einseitig gesehen und sollte meine Haltung noch mal überdenken.“","style":"humorvoll","reaction":"„Na also, geht doch! Dann sind wir uns ja einig, dass beide Seiten nichts taugen. Pattsituation, ich nehm's!“","feedback":"Du lässt dich in die Defensive ziehen und erzeugst genau die moralische Pattsituation, die der Whataboutism beabsichtigt. Die Frage nach der Wirkung bleibt unbeantwortet.","score":-1,"nextStepId":"step-fail"}]},"step-2":{"id":"step-2","speaker":"xX_Dauerkommentator_Xx","speech":"„Meine Erfahrung zählt mehr als jede Studie! Und außerdem lügen die ‚Mainstream-Medien‘ doch auch ständig, oder glaubst du denen etwa blind? Die haben schon mal über Massenvernichtungswaffen gelogen!“","options":[{"text":"„Natürlich lügen Medien manchmal, deshalb prüfe ich Quellen. Aber dass Medien Fehler machen, beweist nicht, dass Homöopathie wirkt. Das sind zwei getrennte Behauptungen.“","style":"sokratisch","reaction":"„Hmpf. Jetzt tust du so klug. Bei dir muss man ja jedes Wort auf die Goldwaage legen!“","feedback":"Sehr gut. Du benennst den erneuten Themenwechsel ruhig und ohne Angriff und hältst beide Behauptungen getrennt (Skript 2).","score":3,"nextStepId":"step-3"},{"text":"„Du hast auch schon mal Fehler gemacht, oder? Wer im Glashaus sitzt, sollte nicht mit Steinen werfen, und das gilt erst recht für dich!“","style":"sarkastisch","reaction":"„Haha, jetzt benutzt du denselben Trick! Wer im Glashaus sitzt, ja? Dann sind wir ja quitt!“","feedback":"Du antwortest mit demselben Fehlschluss. Das Gespräch wird zum Schlagabtausch von Gegenvorwürfen und verliert die Sachebene vollständig.","score":-2,"nextStepId":"step-fail"},{"text":"„Deine Erfahrung ist dir wichtig, das merke ich. Beim Mediensatz musst du mir aber helfen: Wie hängt das mit der Wirkung von Homöopathie zusammen?“","style":"deeskalierend","reaction":"„Ähm... also... na, wenn man den Medien nicht trauen kann, dann kann man auch den Studien nicht trauen, oder?“","feedback":"Brauchbar. Du schätzt die Erfahrung wert und stellst eine echte Frage, ohne den Medienvorwurf zu entkräften. Die Logiklücke zeigt sich, aber der Kern bleibt noch offen.","score":1,"nextStepId":"step-3"}]},"step-3":{"id":"step-3","speaker":"xX_Dauerkommentator_Xx","speech":"„Du willst mich einfach nicht verstehen, oder? Du suchst nur nach Gründen, mir nicht zuzustimmen!“","options":[{"text":"„Ich suche keinen Streit. Aber ich merke, dass wir beide im Kreis laufen und ich hier viel Energie lasse. Ich lasse meinen Punkt einfach stehen, du kannst ihn prüfen oder nicht. Schönen Abend.“","style":"ausstieg","reaction":"„Ach, jetzt rennt er weg! Typisch, wenn die Argumente ausgehen! ...naja, schönen Abend.“","feedback":"Gut. Mit dem Management emotionaler Kosten erkennst du eine Schlacht, die du vermeiden solltest, und steigst ohne Gesichtsverlust aus. Der Punkt bleibt stehen.","score":3,"nextStepId":"step-exit"},{"text":"„Dann schreibe ich dir jetzt einen langen Beitrag mit allen Gründen, warum du falsch liegst, und bleibe so lange dran, bis du es einsiehst.“","style":"frontal","reaction":"„Her damit, ich habe die ganze Nacht Zeit! Du kommst hier nicht ungeschoren raus!“","feedback":"Du investierst Energie in eine Debatte ohne erkennbares Interesse am Austausch. Das ist der Kampf ohne Boden, den das Management emotionaler Kosten vermeiden will.","score":-1,"nextStepId":"step-struggle"},{"text":"„Ich möchte dich schon verstehen. Mein Punkt bleibt: Ein Gegenvorwurf macht meine Frage nicht ungültig. Wenn du magst, schauen wir gemeinsam in eine Quelle zur Wirksamkeit. Wenn nicht, ist das auch okay.“","style":"deeskalierend","reaction":"„Hmm... Eine Quelle? Na gut, schick mal, aber ich glaub's erst, wenn ich es selbst gelesen habe.“","feedback":"Brauchbar. Du bietest einen Weg an, lässt die Tür offen und setzt keine Frist. Sachebene und Beziehung bleiben getrennt, es kostet dich aber weiter Energie.","score":1,"nextStepId":"step-success"}]},"step-success":{"id":"step-success","speaker":"xX_Dauerkommentator_Xx","speech":"„*tippt* Na gut, schick die Quelle, ich werfe vielleicht später mal einen Blick drauf. Aber das heißt nicht, dass du recht hast!“","options":[{"text":"„Völlig in Ordnung. Du musst mir nicht recht geben, nur prüfen, was dir plausibel erscheint.“","style":"deeskalierend","reaction":"„Hmpf. Meinetwegen. Bis zum nächsten Thread.“","feedback":"Gut abgeschlossen. Du hast die Sachfrage vom Gegenvorwurf getrennt und den Austausch ohne Triumph beendet. Bei anonymen Accounts lohnt meist der frühe Ausstieg.","score":2},{"text":"„Eben, du hast nicht recht. Aber immerhin lernst du dabei etwas, und das ist ja schon was.“","style":"sarkastisch","reaction":"„Ha! Jetzt wird er auch noch überheblich. Vergiss es, ich sehe mir gar nichts mehr an!“","feedback":"Der letzte Satz zerstört den Gewinn. Wer zum Schluss triumphiert, macht aus einem Austausch einen Wettkampf, und die offene Tür fällt wieder ins Schloss.","score":-1}]},"step-exit":{"id":"step-exit","speaker":"xX_Dauerkommentator_Xx","speech":"„*tippt nichts mehr* … Der Thread bleibt still. Dein Punkt steht weiter da, und niemand hat dich zum Weiterschreiben gezwungen.“","options":[{"text":"Du schließt den Tab, atmest durch und widmest dich etwas anderem.","style":"ausstieg","reaction":"Kein Sieger, kein Schaden: Dein Abend gehört wieder dir.","feedback":"Meisterhaft. Du hast die Sachfrage vom Gegenvorwurf getrennt und deine Energie bewusst eingeteilt. Aussteigen war hier kein Verlieren, sondern eine Entscheidung.","score":2},{"text":"Du kehrst doch noch einmal zurück und schreibst: „Eine Sache noch…“","style":"frontal","reaction":"„Haha, er kann es nicht lassen! Her damit!“","feedback":"Der Ausstieg war schon geschafft. Wer noch einmal zurückkehrt, öffnet den Kampf ohne Boden neu und verschenkt, was das Management emotionaler Kosten gerade gewonnen hat.","score":-1}]},"step-struggle":{"id":"step-struggle","speaker":"xX_Dauerkommentator_Xx","speech":"„Und was ist mit den ganzen Pharma-Skandalen? Und mit der Kirche? Und überhaupt, wieso soll ich dir glauben?!“","options":[{"text":"„Das sind jetzt drei neue Themen, die meine Frage nicht beantworten. Das Ganze macht mich müde. Ich steige hier aus, damit mein Abend nicht daran hängt.“","style":"ausstieg","reaction":"„Pah, Feigling! Aber gut, geh halt.“","feedback":"Spät, aber richtig. Das Management emotionaler Kosten erlaubt dir, auch nach einer verbrannten Stunde auszusteigen. Der Gewinn: dein Abend gehört wieder dir.","score":1},{"text":"„Dann machen wir eben weiter. Ich beantworte jeden Punkt einzeln, auch wenn ich bis morgen früh dranbleibe und dafür keinen Schlaf bekomme.“","style":"frontal","reaction":"„Hehe, jetzt hab ich dich! Ich habe noch 47 weitere Themen, fang schon mal an!“","feedback":"Der Kampf an allen Fronten ist der Weg zum Ausbrennen. Du reagierst auf jeden Funken, statt zu triagieren.","score":-2}]},"step-fail":{"id":"step-fail","speaker":"xX_Dauerkommentator_Xx","speech":"„Siehste! Am Ende hast du nichts in der Hand. Hab ich's doch gewusst!“ *postet einen Screenshot mit drei Lach-Emojis*","options":[{"text":"Ende: Der Thread ist verbrannt, und die Sachfrage ging im Schlagabtausch unter.","style":"ausstieg","reaction":"Wer auf einen Gegenvorwurf mit Angriff oder Anbiederung antwortet, verliert den Faden.","feedback":"Beim nächsten Mal: Gegenvorwurf anerkennen, vom Thema trennen und zur Ausgangsfrage zurückkehren. Dann entscheiden, ob die Debatte die Energie wert ist.","score":0}]}},"status":"entwurf","familie":"du-auch-erkennen","fertigkeit":"F2","stufe":2,"kurz":"Ein Gegenvorwurf widerlegt das ursprüngliche Argument nicht: Fehler der Schulmedizin sagen nichts darüber, ob Homöopathie wirkt. Beide Aussagen werden getrennt geprüft, und du entscheidest bewusst, wie viel Energie dir die Debatte wert ist.","prueffrage":"Wenn alle Vorwürfe gegen Pharmaindustrie und Medien stimmten: Was wüsstest du dann über die Wirkung von Homöopathie mehr als vorher?","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy, Einträge „Tu Quoque“ und „You Too“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Fallacies (überarb. 30.08.2024), Abschn. 1 und 2.4","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"scen-kollege-gaensehaut-gedanken","title":"Fabians Manifestations-Boom","subtitle":"„Das Gesetz der Anziehung“, geübt mit der Deeskalations-Matrix","character":"Kollege Fabian","avatar":"🌠","context":"In der Kaffeeküche erzählt dein Kollege Fabian begeistert, dass er sich seine Beförderung „manifestiert“ hat. Er behauptet, wer intensiv genug positiv denkt, ziehe Erfolg wie ein Naturgesetz an. Als du zögerst, wird er spürbar gereizt.","goal":"Bleib im Gespräch, indem du Fabians Gefühl ernst nimmst, und prüfe das angebliche „Gesetz“ mit einer ruhigen Frage nach Falsifizierbarkeit statt mit einem Gegenangriff.","bereich":"Arbeit","laenge":"mittel","ton":"ernst","bestehenAb":6,"lektion":"Ein „Gesetz der Anziehung“ ist kein Gesetz im physikalischen Sinn: Es macht keine prüfbaren Vorhersagen und ist so gebaut, dass jedes Scheitern beim Anwender landet. Wer Fabians Freude und Verunsicherung zuerst ernst nimmt, schafft den Raum, in dem er die Testfrage selbst stellen kann. Rechthaben ist weniger wert als ein Gespräch, das offen bleibt.","toolRef":"H.2.1","faktenRef":"D.4.5","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Kollege Fabian","speech":"„Ich sag's dir, das funktioniert wirklich! Ich habe mir jeden Morgen die Beförderung vorgestellt, richtig mit Gefühl, und jetzt hat es geklappt. Das ist ein unumstößliches Gesetz, wie die Schwerkraft! Wer es nicht glaubt, hat einfach nicht genug Vertrauen.“","options":[{"text":"„Fabian, das ist esoterischer Quatsch. Mit Physik hat das gar nichts zu tun, und Schwerkraft fällt auch ohne Vorstellungskraft. Dass du das ernsthaft glaubst, wundert mich.“","style":"frontal","reaction":"„Aha, jetzt kommt wieder der große Wissenschaftler! Ihr Skeptiker habt doch keine Ahnung vom Leben. Mir hat es geholfen, und das zählt!“","feedback":"Frontalangriff: Der Kern deiner Kritik mag stimmen, aber Fabian hört Herabsetzung. Er verteidigt jetzt seine Identität, nicht mehr eine These.","score":-2,"nextStepId":"step-fail"},{"text":"„Das klingt, als hätte dich diese Beförderung richtig stolz gemacht, und als wäre dir wichtig, dass das niemand kleinredet. Erzähl mir mal, wie genau du das gemacht hast.“","style":"deeskalierend","reaction":"„*lehnt sich entspannt an die Anrichte* Genau, das ist es! Ich habe jeden Morgen zehn Minuten visualisiert, Dankbarkeit gespürt und alles aufgeschrieben. Und dann kam wirklich der Anruf vom Chef.“","feedback":"Gut gemacht: Du validierst das Gefühl (Stolz, Wunsch nach Anerkennung), ohne dem „Gesetz“ zuzustimmen. Der Ton entspannt sich, und Fabian erzählt weiter.","score":3,"nextStepId":"step-2"},{"text":"„Wow, krass! Das muss ich auch ausprobieren. Welches Buch hast du dazu gelesen? Ich will mir auch eine Gehaltserhöhung manifestieren!“","style":"humorvoll","reaction":"„Super, dass du Interesse hast! Kauf dir unbedingt das Buch und den Online-Kurs, ich schick dir den Link. Aber du musst wirklich daran glauben, sonst klappt es nicht!“","feedback":"Freundlich, aber du gehst mit, statt zu prüfen. Fabian fühlt sich bestätigt, und die Frage, ob hier wirklich ein Gesetz wirkt, bleibt ungestellt.","score":-1,"nextStepId":"step-2b"}]},"step-2":{"id":"step-2","speaker":"Kollege Fabian","speech":"„Siehst du, es hat funktioniert! Neulich hat's bei einem Kumpel allerdings nicht geklappt, der wollte unbedingt ein Haus. Aber der hat bestimmt unbewusst negativ gedacht. So ist das eben, das Gesetz lügt nicht.“","options":[{"text":"„Du, ich glaube, mich beschäftigt da eine Frage: Wenn es bei deinem Kumpel nicht klappt, liegt es dann am Gesetz oder an ihm? Woran würden wir erkennen, dass das Gesetz auch mal nicht stimmt?“","style":"sokratisch","reaction":"„Hm... am Gesetz liegt es natürlich nicht. Es muss an ihm liegen, an seiner Schwingung oder so. Aber woran man das genau merkt... gute Frage eigentlich.“","feedback":"Stark: Du stellst die Falsifizierbarkeitsfrage als echte Neugier („Ich“-Perspektive nach). Fabian stolpert über die Konstruktion, dass Scheitern immer beim Anwender liegt.","score":3,"nextStepId":"step-3-success"},{"text":"„Also bei deinem Kumpel liegt es an seinen Gedanken, bei dir am Gesetz? Praktisch, dann kann dich ja nie jemand widerlegen. Schön gegen jede Kritik abgedichtet, Fabian.“","style":"sarkastisch","reaction":"„Wow, na danke. Ich versuche, dir etwas Gutes zu zeigen, und du machst mich lächerlich. Tu doch nicht so überlegen!“","feedback":"Der inhaltliche Punkt trifft (das „Gesetz“ ist so gebaut, dass es nie scheitern kann, es ist also nicht falsifizierbar), aber der Sarkasmus kippt das Gespräch. Wer sich lächerlich gemacht fühlt, hört nicht mehr zu.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Das ist wirklich spannend. Ehrlich gesagt kenne ich mich nicht aus, und das Thema scheint dir viel zu bedeuten. Wollen wir kurz über etwas anderes reden und später noch mal draufschauen?“","style":"ausstieg","reaction":"„Na gut, meinetwegen. Aber du solltest dir das wirklich mal ansehen, es verändert das Leben.“","feedback":"Der Frieden bleibt gewahrt, aber du lässt eine gute Gelegenheit ungenutzt, die Testfrage zu stellen. Kein Schaden, aber auch kein Fortschritt.","score":0,"nextStepId":"step-3-struggle"}]},"step-2b":{"id":"step-2b","speaker":"Kollege Fabian","speech":"„Und wenn bei dir nichts klappt, dann lag es einfach daran, dass du innerlich noch gezweifelt hast. Das ist kein Hexenwerk, das ist ein Gesetz, so sicher wie die Schwerkraft!“","options":[{"text":"„Moment, Fabian: Wenn es nicht klappt, liegt es immer an mir? Dann ist es doch gar kein Gesetz wie die Schwerkraft. Die wirkt ja auch, wenn ich zweifle. Ist das nicht ein Widerspruch?“","style":"sokratisch","reaction":"„*zögert* Na ja... bei der Schwerkraft muss man nichts tun. Aber hier... hm. Das klingt jetzt schon irgendwie komisch, wenn du es so sagst.“","feedback":"Gute Korrektur im zweiten Anlauf: Der Vergleich mit der Schwerkraft zeigt den Unterschied zwischen Beschreibung und Anleitung. Die Frage kommt als Verständnisfrage, nicht als Angriff.","score":2,"nextStepId":"step-3-success"},{"text":"„Du, das ist mir echt zu viel Esoterik. Lass uns bitte über etwas Vernünftiges reden, sonst verliere ich die Geduld.“","style":"frontal","reaction":"„Ach, dann geh doch! Wer nicht offen ist für Neues, der wird auch nie etwas erreichen. Dann bleibst du eben ewig auf deiner Stelle sitzen.“","feedback":"Der Rückzug kommt mit einem Urteil, nicht mit einem Angebot. Fabian erlebt es als Abwertung und dreht den Spieß um.","score":-2,"nextStepId":"step-fail"},{"text":"„Ich merke, wie wichtig dir das ist, und ich will dir das nicht madigmachen. Mich irritiert nur eine Sache: Wie würde man herausfinden, dass das Gesetz nicht funktioniert hat?“","style":"deeskalierend","reaction":"„*überlegt kurz* Na ja... ich würde sagen, wenn es nicht klappt. Aber dann liegt es ja wieder an einem selbst. Hm, ehrlich gesagt hab ich darüber noch nie nachgedacht.“","feedback":"Sehr gut: Gefühl respektiert, dann eine „Ich“-Irritation als Frage formuliert. So kommt die Unfalsifizierbarkeit ins Spiel, ohne dass Fabian sich angegriffen fühlt.","score":3,"nextStepId":"step-3-success"}]},"step-3-success":{"id":"step-3-success","speaker":"Kollege Fabian","speech":"„Ich muss zugeben, die Sache mit dem Kumpel stört mich jetzt doch. Positiv zu denken hat mir ja wirklich gutgetan, aber vielleicht ist es einfach etwas anderes als ein Naturgesetz, oder?“","options":[{"text":"„Genau so sehe ich es auch: Eine positive Einstellung kann helfen, dranzubleiben, garantiert aber nichts. Dein Chef hat vermutlich auch deine Arbeit gesehen. Du darfst stolz auf dich sein.“","style":"deeskalierend","reaction":"„*lacht* Stimmt, ich habe das Quartal ja auch ziemlich durchgezogen. Danke, dass du nicht gleich draufgehauen hast. Kaffee?“","feedback":"Mission gelungen: Du trennst die nützliche Haltung („positiv denken“) vom angeblichen „Gesetz“ und würdigst Fabians echte Leistung. Das Gespräch endet auf Augenhöhe.","score":3},{"text":"„Siehst du, jetzt kommst du von selbst drauf. Ich hab's ja gleich gesagt: Reiner Humbug, und das Buch kannst du wegwerfen, es steht eh nur Unsinn drin.“","style":"frontal","reaction":"„Hm... na ja. So habe ich das nicht gemeint. Ich muss los.“ *geht etwas verschlossen*","feedback":"Fabian hat gerade selbst nachgedacht, und du nimmst ihm das Erfolgserlebnis mit einem Triumph. Das Ergebnis stimmt, der Ton verschenkt Vertrauen.","score":0},{"text":"„Mich würde interessieren, wie du das im Alltag beibehältst. Hast du schon mal einen Zeitraum ohne Visualisieren probiert, um zu schauen, was sich ändert?“","style":"sokratisch","reaction":"„Eigentlich nicht... Die Idee ist spannend. Ich könnte es ja mal zwei Wochen weglassen und beobachten, ob sich tatsächlich was verändert.“","feedback":"Gut: Du schlägst keinen Gegenbeweis vor, sondern einen kleinen Selbsttest, genau das, was ein echtes Gesetz aushalten müsste. Noch runder wäre es, zusätzlich Fabians eigene Leistung zu würdigen.","score":2}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Kollege Fabian","speech":"„Ich weiß nicht, ob das Sinn hat. Du glaubst mir ja ohnehin nicht. Ich hab mich gefreut, und jetzt fühlt sich das alles komisch an.“","options":[{"text":"„Das tut mir leid, ich wollte dir die Freude nicht verderben. Ich freue mich ehrlich für deine Beförderung. Lass uns ein andermal in Ruhe reden.“","style":"deeskalierend","reaction":"„*entspannt sich* Okay, danke. Ich fand's einfach schön, mal was Gutes zu teilen. Vielleicht reden wir wirklich später noch mal.“","feedback":"Ein sauberer Neustart: Du validierst Fabians Freude und lässt die Tür offen. Die Sachfrage bleibt offen, aber die Beziehung ist heil.","score":2},{"text":"„Du hast recht, ich glaube dir nicht. Das ist unwissenschaftlich, und ich sage es dir lieber ehrlich, als dir etwas vorzumachen.“","style":"frontal","reaction":"„Dann ist ja alles gesagt. Schönen Tag noch.“ *geht*","feedback":"Ehrlichkeit ohne Zuwendung verhärtet. Fabian geht, und das Thema ist zwischen euch erledigt, ohne dass er etwas überdacht hat.","score":-2}]},"step-fail":{"id":"step-fail","speaker":"Kollege Fabian","speech":"„Du willst mir nur etwas kleinreden. Ich habe es geschafft und du nicht, dann akzeptier das doch einfach!“ *nimmt seine Tasse und geht*","options":[{"text":"Ende: Fabian fühlt sich herabgesetzt und hält jetzt noch stärker am „Gesetz“ fest. Dein Argument kam nicht an, weil die Stimmung vorher gekippt war.","style":"ausstieg","reaction":"Nächstes Mal zuerst das Gefühl ernst nehmen, dann die Testfrage stellen.","feedback":"Die Deeskalations-Matrix empfiehlt zum Beispiel, zuerst das Gefühl zu validieren und dann eine „Ich“-Botschaft als Frage zu stellen. Seziert wird die Behauptung, nicht der Mensch.","score":0}]}},"status":"entwurf","familie":"widerlegung-benennen","fertigkeit":"F1","stufe":3,"kurz":"Ein „Gesetz der Anziehung“ ist kein Naturgesetz: Es macht keine prüfbaren Vorhersagen, und jedes Scheitern wird dem Anwender zugeschrieben. Wer Freude und Verunsicherung zuerst ernst nimmt, hält das Gespräch offen, in dem die Testfrage Platz hat.","prueffrage":"Welches Ergebnis müsste eintreten, damit Fabian sagen würde, das „Gesetz“ habe nicht funktioniert?","quellen":[{"typ":"url","kurz":"Hansson, S. O.: „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy (überarbeitet 28.07.2025)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschnitt 4.3","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Popper, K. R. (1935): Logik der Forschung. Wien: Springer (Abgrenzungskriterium; Immunisierung gegen Kritik nach Landkarte-Fn. band-01-18)","oeffentlich":false},{"typ":"doi","kurz":"Oettingen, G.; Mayer, D. (2002): „The Motivating Function of Thinking About the Future: Expectations Versus Fantasies“. Journal of Personality and Social Psychology 83(5) (aus Landkarte-Fn. t4-anziehung: positive Fantasien sagten weniger Erfolg voraus)","oeffentlich":false,"doi":"10.1037/0022-3514.83.5.1198"}],"thema":"Psychologie"},{"id":"scen-heike-gefuehle-krebs","title":"Heike und die verdrängten Gefühle","subtitle":"Krebsbiologie, geübt mit aktivem Zuhören","character":"Heike, langjährige Freundin","avatar":"🎗️","context":"Deine langjährige Freundin Heike hat vor drei Wochen die Diagnose Krebs erhalten. Beim Kaffee erzählt sie dir, sie habe ein Buch gelesen: Ihre Erkrankung komme von jahrelang unterdrückten Gefühlen, und wenn sie innerlich Frieden schließe, könne sie heilen. Der Termin für ihre Therapieplanung rückt näher, und sie überlegt, ihn zu verschieben.","goal":"Höre Heike zuerst wirklich zu, nimm ihre Angst und Schuldgefühle ernst und finde einen Weg, die Behandlung nicht zu verzögern, ohne dass sie sich beschuldigt oder belehrt fühlt.","bereich":"Gesundheit","laenge":"lang","ton":"ernst","bestehenAb":9,"lektion":"Wer schwer krank ist, braucht zuerst das Gefühl, gehört zu werden, und erst dann Sachinformation. Aktives Zuhören macht sichtbar, was hinter Heikes Satz steckt: Kontrollverlust, Angst und die Frage nach der Schuld. Krebs entsteht durch Mutationen im Erbgut, nicht durch unterdrückte Gefühle oder seelische Konflikte. Dein Zuhören schafft die Basis dafür, dass Heike diesen Satz überhaupt an sich heranlassen kann, und dafür, dass sie die Behandlung nicht aufschiebt.","toolRef":"H.2.3","faktenRef":"C.4.4","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Heike","speech":"„Ich habe viel nachgedacht. Weißt du, in dem Buch steht, dass Krebs von Gefühlen kommt, die man jahrelang runtergeschluckt hat. Bei mir passt das total: Ich habe nie über meine Wut geredet. Wenn ich jetzt innerlich Frieden schließe, kann ich heilen. Ich glaube, ich warte erstmal mit der Therapie.“","options":[{"text":"„Heike, das ist gefährlicher Unsinn. Krebs kommt von Mutationen, nicht von Gefühlen. Wenn du jetzt wartest, riskierst du dein Leben!“","style":"frontal","reaction":"„*zieht sich zurück* Na toll. Jetzt hältst du mich auch noch für dumm. Ich dachte, du verstehst mich. Lass uns das Thema lassen.“","feedback":"Inhaltlich richtig, aber du sendest nur, statt zuzuhören. Heike hört Abwertung, nicht Sorge, und macht dicht.","score":-2,"nextStepId":"step-fail"},{"text":"„Wenn ich dich richtig verstehe, ist dir wichtig, selbst etwas tun zu können, und du hast Angst, dass du früher etwas falsch gemacht hast. Habe ich das so richtig getroffen?“","style":"sokratisch","reaction":"„*schluckt* Ja... genau. Ich komme mir so hilflos vor. Und ich frage mich dauernd, ob ich das hätte verhindern können.“","feedback":"Sehr gut! Paraphrasieren benennt Gefühl und Bedürfnis, statt nur die Behauptung zu kommentieren. Heike fühlt sich verstanden und öffnet sich.","score":3,"nextStepId":"step-2"},{"text":"„Das klingt ja spannend! Meinst du, ich sollte das Buch auch lesen? Vielleicht kann man mit Meditation wirklich viel bewirken.“","style":"affektiv","reaction":"„Ja! Ich leihe es dir aus! Du verstehst mich wenigstens. Die Ärzte sehen immer nur den Tumor und nicht den Menschen.“","feedback":"Du schaffst Nähe, bestätigst aber den Mythos und lässt Heike mit der Idee allein, die Behandlung zu verschieben. Zuhören heißt nicht zustimmen.","score":-1,"nextStepId":"step-bestaetigt"}]},"step-2":{"id":"step-2","speaker":"Heike","speech":"„Vielleicht war ich einfach zu angepasst. Immer lieb, nie ein Streit. Das Buch sagt, genau solche Menschen erkranken. Was habe ich da bloß falsch gemacht?“","options":[{"text":"„Falsch gemacht? Heike, das ist eine simple Verwechslung: Krebs hat mit deinem Charakter überhaupt nichts zu tun. Punkt.“","style":"frontal","reaction":"„Punkt? So einfach ist das also für dich. Dann erklär mir halt, woher er kommt, wenn du so schlau bist.“","feedback":"Der Inhalt stimmt, aber du fertigst das Gefühl mit einem „Punkt“ ab. Heikes Schuldfrage bleibt unbeantwortet, und sie wird trotzig.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Das klingt, als würdest du dir die Schuld geben, und das tut weh. Wie ist das, wenn du an Wut denkst, die du heruntergeschluckt hast? Erzähl mir davon.“","style":"deeskalierend","reaction":"„*Stimme zittert* Mein Chef hat mich jahrelang kleingemacht, und ich habe nie etwas gesagt. Ich dachte, das sei halt so. Und jetzt bin ich krank, und es fühlt sich an wie die Quittung.“","feedback":"Stark! Gefühl benennen, offene Frage stellen: Du gibst Raum, statt zu korrigieren. Heike legt die eigentliche Sorge offen: die Schuldfrage.","score":3,"nextStepId":"step-3"},{"text":"„Ach, Heike, mach dir keine Vorwürfe. Wird schon alles gut, du schaffst das. Wollen wir noch ein Stück Kuchen bestellen?“","style":"humorvoll","reaction":"„*lächelt gequält* Ja, klar... Kuchen. Aber ich merke, du willst da lieber nicht drüber reden.“","feedback":"Ausweichen mit Beschwichtigung (statt Zuhören) lässt Heike spüren, dass ihre Sorge zu schwer für dich ist. Das Gespräch bleibt an der Oberfläche.","score":-1,"nextStepId":"step-3-struggle"}]},"step-3":{"id":"step-3","speaker":"Heike","speech":"„Wenn man es so sieht, wäre ich ja selbst schuld, oder? Und deshalb muss ich es auch selbst heilen. Von innen heraus. Das ist doch logisch, oder?“","options":[{"text":"„Du bist nicht schuld, Heike. Erzähl mir, woran du merkst, dass das Buch recht hat. Gab es etwas, das dich besonders überzeugt hat?“","style":"sokratisch","reaction":"„Hm... eigentlich nur, dass es sich so stimmig anfühlt. Und die Geschichten von Leuten, die geheilt wurden. Belegt ist da nicht viel, wenn ich ehrlich bin.“","feedback":"Sehr gut! Klärende Fragen lenken auf die Quelle der Überzeugung. Heike erkennt selbst, dass das Gefühl der Stimmigkeit kein Beleg ist.","score":3,"nextStepId":"step-4"},{"text":"„Ja, ich glaube, da ist was dran. Wut kann einen echt krank machen. Gut, dass du jetzt an dir arbeitest!“","style":"affektiv","reaction":"„Siehst du, genau! Dann plane ich erstmal Wochen für mich ein. Die Klinik kann auch später noch.“","feedback":"Du bestätigst die Ursachenbehauptung. Das Gegenteil ist belegt: Krebs entsteht durch Mutationen in der DNA, nicht durch unterdrückte Gefühle. Dein „Ja“ lässt Heike die Therapie aufschieben.","score":-2,"nextStepId":"step-fail"},{"text":"„Nein, falsch, das ist ein Denkfehler. Es gibt dafür null Belege, und wer das behauptet, verkauft Bücher. Punkt aus.“","style":"sarkastisch","reaction":"„*gereizt* Du redest über mein Buch, als wäre es Müll. Das hat mir echt geholfen. Ich will jetzt nicht streiten.“","feedback":"Du triffst die Sachlage, aber der Ton wertet Heikes Hoffnung ab. Seziert wird die Behauptung, nicht der Mensch.","score":0,"nextStepId":"step-3-struggle"}]},"step-4":{"id":"step-4","speaker":"Heike","speech":"„Weißt du, was ich eigentlich will? Ich will nicht, dass ich schuld bin. Und ich will wieder etwas in der Hand haben. Aber das Buch sagt, ich muss nur ruhig werden, dann klappt es. Und wenn nicht, habe ich es offenbar nicht richtig gemacht.“","options":[{"text":"„Heike, Krebs entsteht durch Veränderungen im Erbgut einzelner Zellen, auch durch zufällige Fehler bei der Zellteilung, und diese Zellen teilen sich dann ungebremst. Unterdrückte Gefühle gehören nicht zu den Ursachen. Dein Wunsch, etwas zu tun, ist völlig verständlich, aber du bist nicht schuld, auch nicht, wenn etwas schwierig wird.“","style":"sokratisch","reaction":"„*lange Pause* Zufallsfehler... Heißt das, ich hätte vieles gar nicht beeinflussen können? Das ist fast schlimmer. Und gleichzeitig auch irgendwie eine Erleichterung.“","feedback":"Gut! Du verbindest das Sachwissen (Mutationen in der DNA; seelische Konflikte sind nicht die Ursache der Mutationen) mit Wärme, und das erst nach dem Zuhören. Diese Reihenfolge funktioniert.","score":2,"nextStepId":"step-5"},{"text":"„Ich höre, wie sehr dich beides quält: die Schuldfrage und das Gefühl, nichts tun zu können. Magst du mir sagen, was du dir am meisten von einer Behandlung versprichst und was dir am meisten Angst macht?“","style":"deeskalierend","reaction":"„*atmet tief* Ich habe Angst vor den Nebenwirkungen und davor, dass ich dann nicht mehr ich selbst bin. Und davor, dass es trotzdem nicht hilft.“","feedback":"Sehr gut! Du hörst weiter zu, statt zu erklären, und bekommst das, was wirklich Angst macht. Das ist der Schlüssel für das weitere Gespräch.","score":3,"nextStepId":"step-5"},{"text":"„Wenn du dir jetzt Zeit nimmst und es klappt nicht, wirst du dir ewig Vorwürfe machen. Mach lieber die Therapie, sonst ist es zu spät.“","style":"frontal","reaction":"„*bricht fast in Tränen aus* Du setzt mich unter Druck. Ich wollte ein Gespräch, keine Predigt.“","feedback":"Die Sorge ist berechtigt, aber du drängst, statt weiter zuzuhören. Heike erlebt Druck statt Zuwendung und macht dicht.","score":-1,"nextStepId":"step-5-struggle"}]},"step-5":{"id":"step-5","speaker":"Heike","speech":"„Vielleicht kann ich ja beides machen? Meine Wut aufarbeiten und die Ärzte machen lassen? Aber ich habe Angst, dass die Chemo mich kaputt macht. Und die Dame vom Verein meinte, es gibt so viele natürliche Wege, die viel sanfter sind.“","options":[{"text":"„Beides klingt gut: Dich innerlich zu sortieren und dir Unterstützung zu holen. Wenn ich es richtig verstehe, ist deine größte Sorge die Nebenwirkung der Chemo. Wollen wir die Fragen aufschreiben, die du den Ärzten stellen willst, bevor du etwas verschiebst?“","style":"deeskalierend","reaction":"„*nickt langsam* Ja, das würde mir helfen. Ich habe so viele Fragen im Kopf, die ich mich nie zu stellen traue.“","feedback":"Sehr gut! Psychologische Unterstützung ist als Begleitung sinnvoll; sie darf nur nicht die Behandlung ersetzen oder verzögern (Kipppunkt). Du paraphrasierst die Sorge und bietest einen konkreten Schritt an.","score":3,"nextStepId":"step-6-success"},{"text":"„Wenn du dich innerlich gut fühlst, reicht das vielleicht auch erstmal. Die Chemo kannst du ja immer noch später nehmen, wenn es nicht klappt, und bis dahin hast du nichts verloren, du musst nichts überstürzen.“","style":"affektiv","reaction":"„Ja, das denke ich auch. Dann nehme ich mir erstmal drei Monate für mich. Danke, dass du das so siehst.“","feedback":"Gefährlich! Bei Krebs ist Zeit der entscheidende Faktor, jede Verzögerung kann den Unterschied zwischen heilbar und nicht mehr heilbar machen (Kipppunkt).","score":-2,"nextStepId":"step-fail"},{"text":"„Natürliche Wege sind oft Abzocke. Chemo ist hart, aber sie wirkt nachweislich. Dein Gefühl in allen Ehren, aber hier zählen Zahlen und keine Stimmungen, und mehr gibt es dazu nicht zu sagen. Damit ist alles gesagt.“","style":"frontal","reaction":"„*verschränkt die Arme* Du klingst wie die Ärzte. Ich komme mir vor wie bei einer Anklage.“","feedback":"Der Hinweis auf bewährte Therapien ist richtig, aber du sendest wieder, ohne zuzuhören. Heike fühlt sich verurteilt.","score":0,"nextStepId":"step-6-struggle"}]},"step-5-struggle":{"id":"step-5-struggle","speaker":"Heike","speech":"„Ich bin gerade so müde von allem. Ich weiß nicht, was ich tun soll.“","options":[{"text":"„Das verstehe ich, das ist gerade viel. Ich dränge dich nicht. Magst du mir sagen, was dir heute Abend guttun würde? Wenn du magst, begleite ich dich zum nächsten Arzttermin.“","style":"deeskalierend","reaction":"„*wischt sich eine Träne weg* Das würde ich mir wünschen. Alleine traue ich mich nicht zu fragen.“","feedback":"Gute Wendung: Du nimmst den Druck raus, bleibst präsent und bietest Begleitung an, ohne zu urteilen.","score":2},{"text":"„Ich kann dich nur warnen: Wenn du jetzt wartest, bereust du es. Mach, was du willst, aber komm nachher nicht zu mir und sag, ich hätte nichts gesagt.“","style":"ausstieg","reaction":"„Dann mache ich das auch. Und ich bitte dich, das nicht mehr anzusprechen.“","feedback":"Der Warnruf mündet in Rückzug. Die Beziehung leidet, Heike hat keine Ansprechperson mehr für ihre Zweifel.","score":-1}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Heike","speech":"„*seufzt* Ich weiß nicht mehr, was ich glauben soll. Das Gespräch macht mich müde.“","options":[{"text":"„Das war viel auf einmal. Lass uns eine Pause machen. Ich bin da, wenn du reden magst, und ich höre einfach zu, ohne etwas aufzudrängen.“","style":"deeskalierend","reaction":"„Danke. Genau das brauche ich gerade. Ich melde mich.“","feedback":"Guter Ausstieg: Du bleibst präsent und zeigst Bereitschaft zuzuhören. Die Beziehung bleibt heil, die Tür zum späteren Gespräch bleibt offen.","score":2},{"text":"„Dann denk mal drüber nach, was wirklich zählt: Dein Leben oder ein Buch. Ich ruf dich morgen an, damit du es dir nicht wieder anders überlegst.“","style":"sarkastisch","reaction":"„*kühl* Das war unnötig. Ruf lieber nicht an.“","feedback":"Die Zuspitzung entwertet Heikes Hoffnung und beschädigt das Vertrauen. Seziert wird die Behauptung, nicht der Mensch.","score":-1}]},"step-6-struggle":{"id":"step-6-struggle","speaker":"Heike","speech":"„Ich brauche jetzt Zeit zum Nachdenken. Lass mich bitte.“","options":[{"text":"„Natürlich. Nimm dir die Zeit. Ich bin für dich da, egal wie du dich entscheidest, und wenn du magst, hör ich einfach nur zu.“","style":"deeskalierend","reaction":"„*leise* Danke. Das hilft mir mehr, als du denkst.“","feedback":"Guter Ausstieg: Du lässt Heike Raum und bleibst als zuhörende Vertrauensperson erreichbar. Das hält die Tür offen.","score":2},{"text":"„Gut, dann lass ich dich. Aber du weißt, was ich davon halte, und ich sage es dir auch gern noch einmal, wenn du mich fragst.“","style":"ausstieg","reaction":"„Ja, das weiß ich. Und genau deshalb muss ich jetzt gehen.“","feedback":"Der Nachsatz klingt nach Vorwurf. Heike zieht sich zurück, die Beziehung wird belastet.","score":0}]},"step-6-success":{"id":"step-6-success","speaker":"Heike","speech":"„Ich glaube, ich rufe morgen in der Klinik an und frage, ob ich mit meinen Fragen früher kommen kann. Und vielleicht mache ich nebenbei einen Kurs, um mit meiner Wut besser umzugehen. Kommst du mit zum ersten Gespräch?“","options":[{"text":"„Sehr gern, Heike. Ich begleite dich und höre einfach zu. Und ich bin froh, dass du dir die Unterstützung holst, die du verdienst.“","style":"deeskalierend","reaction":"„*lächelt unter Tränen* Danke, dass du mir zugehört hast, statt mich zu belehren. Das hat den Unterschied gemacht.“","feedback":"Mission gelungen! Aktives Zuhören hat die Schuldfrage und die Angst sichtbar gemacht. Heike nimmt die Behandlung an, und die Freundschaft hat gehalten.","score":3}]},"step-bestaetigt":{"id":"step-bestaetigt","speaker":"Heike","speech":"„Siehst du, genau das sage ich ja! Ich nehme mir jetzt erstmal Zeit für mich. Die Klinik kann warten. Du bist die Einzige, die mich wirklich versteht.“","options":[{"text":"Ende: Die Zuwendung war da, aber der Mythos wurde bestätigt und die Behandlung verschoben.","style":"ausstieg","reaction":"Zuhören heißt nicht zustimmen: Wer nur Verständnis zeigt, ohne etwas zurechtzurücken, kann Schaden mit anrichten.","feedback":"Aktives Zuhören verlangt, zu verstehen und trotzdem ehrlich zu bleiben. Bei Krebs ist Zeit der entscheidende Faktor.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Heike","speech":"„Ich sehe schon, so komme ich nicht weiter. Ich entscheide das allein.“ *steht auf und geht*","options":[{"text":"Ende: Das Gespräch ist gescheitert, und Heike ist jetzt allein mit ihrer Entscheidung.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst zuhören und das Gefühl ernst nehmen, dann erst über Inhalte sprechen.","feedback":"Wer nicht zuhört, erfährt nie, was eine Überzeugung trägt. Bei Krebs kann jede Verzögerung der Therapie entscheidend sein.","score":0}]}},"status":"entwurf","familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","stufe":4,"kurz":"Krebs entsteht durch Mutationen im Erbgut, nicht durch unterdrückte Gefühle. Wer schwer krank ist, braucht zuerst das Gefühl, gehört zu werden: Aktives Zuhören macht Angst, Kontrollverlust und Schuldfrage sichtbar und schafft die Basis, die Behandlung nicht aufzuschieben.","prueffrage":"Worauf stützt sich der Ratgeber: auf Geschichten von Geheilten oder auf einen Vergleich, wie oft angepasste und streitbare Menschen an Krebs erkranken?","quellen":[{"typ":"url","kurz":"National Cancer Institute: „The Genetics of Cancer“ (aktualisiert 08.08.2024)","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/causes-prevention/genetics","abruf":"2026-10-12"},{"typ":"url","kurz":"Cancer Research UK: „Does stress cause cancer?“ (zuletzt geprüft 19.12.2024)","oeffentlich":true,"url":"https://www.cancerresearchuk.org/about-cancer/causes-of-cancer/cancer-myths/can-stress-cause-cancer","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Braun, V.; Burian, R.; Diefenbacher, A. (Hrsg.) (2016): Arzt-Patienten-Gespräche bei stressassoziierten Erkrankungen. Berlin: De Gruyter, Kap. 3 (offene Fragen, aktives Zuhören, Verbalisieren; nach Landkarte-Fn. gl-h-zuhoeren)","oeffentlich":false}],"thema":"Gesundheit"},{"id":"scen-mondphasen-haarschnitt","title":"Friseurin Biancas Mondkalender","subtitle":"Haare nur bei abnehmendem Mond, geübt mit Street Epistemology","character":"Bianca","avatar":"✂️","context":"Du sitzt im Friseurstuhl bei Bianca, die seit Jahren dein Haar schneidet und wirklich gut darin ist. Beim Blick in ihren Terminkalender erzählt sie dir gut gelaunt, sie nehme Haarschnitte nur bei abnehmendem Mond vor, denn dann wachse das Haar langsamer, und ihre Stammkundschaft schwöre darauf.","goal":"Bring Bianca mit neugierigen, respektvollen Fragen (Street Epistemology) dazu, selbst zu prüfen, wie sie zu ihrer Mondphasen-Gewissheit kommt, ohne ihr den Spaß am Beruf zu nehmen.","bereich":"Arbeit","laenge":"kurz","ton":"heiter","bestehenAb":4,"lektion":"Statt „Das stimmt nicht“ zu sagen, hilft die Frage nach der Methode: Woher weißt du es, und wie sicher bist du? Unser Gehirn sucht Muster auch im Zufall (Apophenie), und ohne einen Test, der auch scheitern könnte, bleibt ein „Das hat bei mir immer gestimmt“ eine schöne, aber ungeprüfte Geschichte. Street Epistemology zeigt, wie du das Gegenüber diese Prüfung selbst erfinden lässt.","toolRef":"H.2.2","faktenRef":"B.9","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Bianca","speech":"„Ich schneide nur bei abnehmendem Mond, das ist bei mir Gesetz! Dann wächst das Haar langsamer, und die Frisur sitzt länger. Bei zunehmendem Mond schießt es regelrecht nach, das sehe ich jedes Mal bei meinen Kundinnen. Wann magst du denn nächstes Mal kommen?“","options":[{"text":"„Bianca, das ist ein Mythos. Haare wachsen unabhängig vom Mond, das ist längst bekannt. Ich dachte, du als Profi weißt das besser, das lernt man doch in der Ausbildung.“","style":"frontal","reaction":"„*legt die Schere hin* Ach so, jetzt bin ich also unprofessionell? Ich mache das seit zwanzig Jahren, und meine Leute kommen nicht umsonst wieder!“","feedback":"Frontalangriff auf eine Behauptung, die Teil ihrer beruflichen Identität ist. Bianca hört „Du bist unprofessionell“ und verteidigt sich, statt nachzudenken. Street Epistemology beginnt mit Neugier, nicht mit Widerlegung.","score":-2,"nextStepId":"step-fail"},{"text":"„Spannend, das habe ich so noch nie gehört. Darf ich dich was fragen? Wenn du eine Skala von 0 bis 100 nimmst: Wie sicher bist du, dass der Mond das Haarwachstum beeinflusst?“","style":"sokratisch","reaction":"„Oh, da bin ich mir zu 90 Prozent sicher! Vielleicht 95. Das ist doch bekannt, schon unsere Großmütter haben nach dem Mond geschnitten.“","feedback":"Genau so beginnt Street Epistemology: erst um Erlaubnis bitten, dann den Sicherheitsgrad auf der 0-100-Skala erfragen. Du greifst die Behauptung nicht an, sondern machst Biancas Gewissheit sichtbar.","score":3,"nextStepId":"step-2"},{"text":"„Ha, dann schneide ich bei dir natürlich auch nur bei abnehmendem Mond. Ich will ja nicht, dass die Haare davongaloppieren. Und wann ist der nächste Termin?“","style":"humorvoll","reaction":"„*lacht* Genau! Du hast eben Verstand. Ich trage dir den nächsten Termin gleich ein.“","feedback":"Freundlich und bequem, aber du bestätigst die Behauptung, statt sie zu erkunden. Die Beziehung bleibt heil, doch es entsteht kein einziger Denkanstoß.","score":0,"nextStepId":"step-2-struggle"}]},"step-2":{"id":"step-2","speaker":"Bianca","speech":"„Ganz ehrlich: Das sehe ich doch jeden Tag im Salon! Wenn eine Kundin zum falschen Zeitpunkt bei mir war, kommt sie nach drei Wochen schon wieder mit den Spitzen. Bei abnehmendem Mond halten die Schnitte viel länger!“","options":[{"text":"„Du beobachtest das also in deinem Salon, das macht Sinn. Darf ich fragen, woran du dich dabei erinnerst, an alle Kundinnen oder eher an die auffälligen Fälle?“","style":"sokratisch","reaction":"„Hm... an die auffälligen, ehrlich gesagt. Die, die sich beschweren oder besonders begeistert sind. Aufgeschrieben habe ich das nie.“","feedback":"Treffer! Du hast Biancas Methode (Erfahrung im Salon) respektvoll anerkannt und dann ihre Erinnerungsauswahl sichtbar gemacht. Apophenie lässt uns Muster auch im Zufall sehen. Ihre Zwillingsschwester, der Bestätigungsfehler, sorgt dafür, dass wir uns danach vor allem die Treffer merken und Gegenbeispiele übersehen.","score":3,"nextStepId":"step-3-success"},{"text":"„Das ist doch nur Einbildung, Bianca. Dein Gehirn sucht sich Muster, wo keine sind, das nennt man Apophenie. Kann man nachlesen.“","style":"frontal","reaction":"„Aha, jetzt kommst du mir mit Fremdwörtern. Ich sehe es doch mit eigenen Augen!“","feedback":"Der Begriff stimmt, aber als Belehrung ist er ein Schlag auf den Kopf. Bianca fühlt sich vorgeführt und beruft sich nur noch fester auf ihre Augen.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Wenn du so sicher bist, nenn mir doch die Studie, die das zeigt. Ohne Studie glaube ich dir das nämlich nicht.“","style":"sarkastisch","reaction":"„Studie, Studie... ich brauche keine Studie, ich habe zwanzig Jahre Erfahrung. Du klingst wie meine Schwiegermutter.“","feedback":"Das klingt nach Kreuzverhör, nicht nach Neugier. Echte Street Epistemology fragt interessiert nach dem Weg zum Wissen und fordert keinen Beleg ein wie vor Gericht.","score":-1,"nextStepId":"step-3-struggle"}]},"step-2-struggle":{"id":"step-2-struggle","speaker":"Bianca","speech":"„Siehst du, so mache ich das schon immer, und es hat noch nie jemand reklamiert. Wollen wir den Termin gleich eintragen?“","options":[{"text":"„Gern. Aber sag mal ehrlich: Wenn du dir einen Beweis wünschen dürftest, wie könntest du herausfinden, ob es wirklich der Mond ist und nicht der Zufall?“","style":"sokratisch","reaction":"„Hm... Beweis? Ich müsste das wohl mal vergleichen. Aber wer soll sich das merken, bei hundert Kundinnen?“","feedback":"Gute Wende! Du bietest Bianca an, selbst nach einem Test zu suchen. So bleibt sie Expertin ihres Berufs und prüft nebenbei, wie verlässlich ihre Methode ist.","score":2,"nextStepId":"step-3-success"},{"text":"„Ja, passt, trag mich einfach ein. Die Mondphasen kenne ich eh nicht auswendig, du wirst schon wissen, wann es am besten passt, ich verlasse mich da auf dich.“","style":"ausstieg","reaction":"„Wunderbar! Dann bis in drei Wochen, bei abnehmendem Mond natürlich.“","feedback":"Ein friedlicher Rückzug, aber ohne jeden Denkanstoß. Das ist die Ausstiegsstrategie ohne den Versuch, vorher zu fragen, woher die Gewissheit stammt.","score":0}]},"step-3-success":{"id":"step-3-success","speaker":"Bianca","speech":"„Weißt du, wenn ich so überlege: Ich merke mir die Fälle, bei denen es gepasst hat. Die anderen vergesse ich wahrscheinlich einfach. Wie würde man denn überhaupt testen, ob da was dran ist?“","options":[{"text":"„Eine Idee: Du notierst ein halbes Jahr lang, wann jede Kundin kam und wann sie wiederkommt, und schaust, ob es bei abnehmendem Mond später ist. Der Test müsste auch scheitern können.“","style":"sokratisch","reaction":"„Du, das mache ich tatsächlich! Mal sehen, was rauskommt. Und wenn nichts dran ist, schneide ich eben, wann es euch passt. Setz dich, ich föhne dich noch trocken.“","feedback":"Rund! Du hast keinen Fakt vorgesetzt, sondern Biancas Neugier auf einen echten Test gelenkt, einen, der auch scheitern kann (Falsifizierbarkeit). So wirkt Street Epistemology: Bianca findet die Prüfung selbst und behält ihr Gesicht.","score":3},{"text":"„Mach, was du magst, Bianca, ist ja dein Salon. Hauptsache, die Frisur sitzt am Ende und die Kundinnen sind zufrieden. Ich will mich da nicht einmischen.“","style":"ausstieg","reaction":"„Die sitzt doch immer! Na gut, dann bleibt der Mond eben, wie er ist. Setz dich, ich föhne dich noch trocken.“","feedback":"Netter Ausklang, aber du lässt Biancas aufkeimende Neugier ohne Anschub liegen. Ein kleiner Hinweis auf einen Test hätte aus dem Funken einen echten Gedanken gemacht.","score":1},{"text":"„Genau, am besten schmeißt du die ganze Mondsache einfach weg. Dein Kalender ist ohnehin voller Humbug, und die Kundinnen merken es sowieso nicht.“","style":"sarkastisch","reaction":"„*stutzt* Na, das war jetzt nicht nett. Ich wollte gerade offen sein, und du holst gleich wieder die Keule raus.“","feedback":"Schade: Mit dem Spott zerstörst du die Offenheit, die Bianca gerade aufgebaut hat. Seziert wird die Behauptung, nicht der Mensch.","score":-2}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Bianca","speech":"„Ich weiß nicht, was du von mir willst. Ich schneide seit Jahren nach dem Mond, und alle sind zufrieden. Wollen wir jetzt weitermachen?“","options":[{"text":"„Entschuldige, das kam hart rüber. Ich fand es nur spannend und wollte verstehen, wie du das so sicher weißt. Erzählst du mir, wie du darauf gekommen bist?“","style":"deeskalierend","reaction":"„Na gut. Ich habe es von meiner Chefin gelernt, damals in der Lehre. Die hatte es von ihrer Oma, und bei ihr hat es immer gestimmt.“","feedback":"Gut repariert! Mit der Entschuldigung und einer offenen Frage stellst du das Gespräch wieder auf Augenhöhe. Biancas Weg zum Wissen (Überlieferung und eigene Erfahrung) ist jetzt klar, und darauf lässt sich in Ruhe weiterfragen.","score":2},{"text":"„Schon gut, lassen wir das Thema. Schneid mir einfach die Spitzen, wie immer, und wir reden ein andermal über den Mond, wenn überhaupt.“","style":"ausstieg","reaction":"„*greift zur Schere* Na also. Und nächstes Mal sagen wir Mondphase vorher, ja?“","feedback":"Ein sauberer Rückzug, der die Beziehung schützt, aber keinen Gedanken bewegt. Die Ausstiegsstrategie ist okay, nur eben ohne Ertrag für die Sachfrage.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Bianca","speech":"„Weißt du was? Such dir doch eine andere Friseurin, wenn dir mein Mondkalender nicht passt!“ *dreht den Stuhl zum Spiegel und greift zum Kamm*","options":[{"text":"Ende: Bianca fühlt sich nicht verstanden und hält an ihrem Mondkalender umso fester fest. Rechthaben und Verstehen sind zweierlei.","style":"ausstieg","reaction":"*kämmt schweigend weiter*","feedback":"Street Epistemology prüft nicht die Schlussfolgerung, sondern den Weg dorthin. Ein Frontalangriff schließt genau diesen Weg ab. Beim nächsten Mal: zuerst um Erlaubnis bitten und fragen, wie sicher sie ist und woher sie das weiß, ohne zu urteilen.","score":0}]}},"status":"entwurf","familie":"muster-im-zufall","fertigkeit":"F4","stufe":2,"kurz":"Statt „Das stimmt nicht“ hilft die Frage nach dem Weg: Woher weißt du es, und wie sicher bist du? Das Gehirn sucht Muster auch im Zufall, und ohne einen Test, der auch scheitern könnte, bleibt „Bei mir hat es immer gestimmt“ eine ungeprüfte Geschichte.","prueffrage":"Wie viele Kundinnen hat Bianca je mit Schnitt- und Wiederkehrtermin notiert, und an welche erinnert sie sich, wenn sie sagt, der Mond wirke jedes Mal?","quellen":[{"typ":"url","kurz":"Blain, S. D. u. a. (2020): „Apophenia as the Disposition to False Positives: A Unifying Framework for Openness and Psychoticism“. Journal of Abnormal Psychology 129(3), S. 279–292, DOI 10.1037/abn0000504 (frei als Autorenmanuskript in PMC)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7112154/","abruf":"2026-10-12"},{"typ":"url","kurz":"Hitchens, J. (2022): „Street Epistemology: Understanding the Basics“. Street Epistemology International","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/street-epistemology-the-basics","abruf":"2026-10-12"},{"typ":"url","kurz":"Street Epistemology International: „What is Street Epistemology? | Definition & Overview“","oeffentlich":true,"url":"https://streetepistemology.com/what-is-street-epistemology","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"scen-vitamin-c-kollege","title":"Torstens Vitamin-C-Schock","subtitle":"Dosis-Wirkung, geübt mit der Deeskalations-Matrix","character":"Torsten, Kollege","avatar":"🍊","context":"In der Kaffeeküche löst Torsten, ein Kollege, den du gut leidest, vor deinen Augen eine riesige Brausetablette auf. Er erzählt stolz, er nehme jeden Tag zehn Gramm Vitamin C, und deshalb werde er nie krank. Neben ihm hustet gerade ein Kollege mit Erkältung.","goal":"Bleib im Gespräch, nimm Torstens Sorge ernst und führe ihn mit dem Dosis-Gedanken und deeskalierenden Techniken zur Frage, wo bei Vitaminen die Grenze zwischen Nutzen und Schaden liegt.","bereich":"Arbeit","laenge":"mittel","ton":"ernst","bestehenAb":6,"lektion":"Bei Vitaminen gilt wie bei fast jedem Stoff: Es kommt auf die Menge an. „Natürlich“ schützt nicht vor der Dosisfrage, und auch natürliche Stoffe können in hohen Dosen schaden. Auch „deshalb werde ich nie krank“ trägt nicht weit: In placebokontrollierten Studien erkälteten sich Menschen aus der Allgemeinbevölkerung mit regelmäßigem Vitamin C kaum seltener als ohne, ihre Erkältungen dauerten nur etwas kürzer. Ob Torsten ohne Brause öfter krank gewesen wäre, kann seine eigene Erfahrung allein nicht zeigen. Gelingt es dir, zuerst Torstens Sorge zu validieren, Ich-Botschaften statt Vorwürfe zu nutzen und ihn selbst nach Zahlen suchen zu lassen, bleibt der Kanal offen.","toolRef":"H.2.1","faktenRef":"C.4.7","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Torsten","speech":"„Zehn Gramm Vitamin C, jeden Morgen. Seit drei Jahren! Ich war seitdem nie krank. Schau dir den da an, der hustet seit einer Woche. Der hätte einfach mehr Vitamine nehmen sollen. Bei Vitaminen ist mehr immer besser, das weiß doch jeder!“","options":[{"text":"„Torsten, das ist Quatsch. Mehr ist nicht immer besser, das lernt man schon in der Schule. Zehn Gramm sind einfach Unsinn, und du fällst da auf ein Werbeversprechen herein.“","style":"frontal","reaction":"„Ach ja? Ich fall auf Werbung rein? Ich beschäftige mich wenigstens mit meiner Gesundheit, im Gegensatz zu anderen hier!“ *stellt das Glas mit einem Knall ab*","feedback":"Die Aussage stimmt im Kern, aber du greifst Torsten an („du fällst herein“). Das ist die Eskalationsreaktion aus „Die Deeskalations-Matrix“: Er verteidigt sich, statt nachzudenken.","score":-2,"nextStepId":"step-fail"},{"text":"„Dass du seit drei Jahren so konsequent auf deine Gesundheit achtest, finde ich wirklich beeindruckend. Wie bist du eigentlich auf zehn Gramm gekommen?“","style":"deeskalierend","reaction":"„Danke! Endlich sagt das mal jemand. Ich hab das in einem Podcast gehört, und seitdem schwöre ich darauf. Mein Körper braucht eben Schutz, bei dem Stress hier im Büro.“","feedback":"Gut: Du würdigst sein Motiv (Gesundheit), ohne den Inhalt zu bestätigen, und fragst neugierig nach. So sinkt die Abwehr, und du erfährst seine Quelle (Gefühle validieren, nicht den Inhalt).","score":3,"nextStepId":"step-2"},{"text":"„Na, wenn du es sagst, wird das schon stimmen. Brause schmeckt ja auch gut. Hauptsache, es macht dir nichts aus.“","style":"ausstieg","reaction":"„Siehst du, genau! Du solltest auch mal damit anfangen. Ich geb dir gern ein paar Tabletten ab!“","feedback":"Du vermeidest den Konflikt, indem du nachgibst. Deeskalation heißt aber nicht, dem Inhalt zuzustimmen (Kipppunkt in). Torsten fühlt sich bestätigt.","score":-1,"nextStepId":"step-2"}]},"step-2":{"id":"step-2","speaker":"Torsten","speech":"„Außerdem ist Vitamin C doch natürlich, das kann gar nicht schaden. Das Zeug ist in jeder Orange! Was soll da bitte passieren, selbst wenn es mal ein bisschen mehr ist?“","options":[{"text":"„Ich habe da eine Frage, die mich selbst beschäftigt: Bei einer Orange nehme ich ja nur eine kleine Menge auf. Bei zehn Gramm sind wir in einer ganz anderen Größenordnung. Kann es sein, dass auch ein natürlicher Stoff in der falschen Menge Probleme macht?“","style":"sokratisch","reaction":"„Hm. Eine Orange, ja... das ist natürlich weit weniger. Aber die Menge kann doch nicht der Punkt sein, es ist doch trotzdem dasselbe Vitamin.“","feedback":"Stark: Eine Ich-Botschaft in Frageform führt auf den Kern der Dosis-Wirkungs-Beziehung: Es gibt keine giftigen oder ungiftigen Stoffe an sich, nur giftige und ungiftige Mengen. Du greifst Torsten nicht an, sondern lädst ihn zum Mitdenken ein.","score":3,"nextStepId":"step-3"},{"text":"„Du merkst schon, dass „natürlich“ nichts heißt, oder? Auch Gift in Pilzen ist natürlich. Wenn du so argumentierst, kannst du dir gleich Knollenblätterpilze in den Salat schneiden.“","style":"sarkastisch","reaction":"„Jetzt vergleichst du mich ernsthaft mit Pilzvergiftungen? Unglaublich. Mit dir kann man echt nicht reden.“ *geht einen Schritt zurück*","feedback":"Der Gedanke hinter dem Vergleich stimmt (Natürlichkeit sagt nichts über die Dosis aus), aber der Sarkasmus wertet Torsten ab. Die Energie des Angriffs kommt zurück.","score":-2,"nextStepId":"step-fail"},{"text":"„Das ist ein guter Punkt: Es steckt tatsächlich in Orangen. Aber ich frage mich: Wenn es um Sicherheit geht, kommt es dann nicht auf Menge und Schwelle an, wie bei vielen Stoffen? Kannst du mir helfen, das zu verstehen?“","style":"deeskalierend","reaction":"„Menge und Schwelle... na ja, wenn ich ehrlich bin, hab ich nie nachgesehen, wie viel das eigentlich ist, was mein Körper braucht.“","feedback":"Gut: Erst die Gemeinsamkeit (stimmt, steckt in Orangen), dann eine Ich-Botschaft mit der Frage nach Menge und Schwelle. Etwas allgemeiner, aber es öffnet die Tür.","score":2,"nextStepId":"step-3"}]},"step-3":{"id":"step-3","speaker":"Torsten","speech":"„Aber ich bin doch nie krank geworden! Das ist doch der Beweis. Wenn es nichts bringen würde, hätte ich mir doch schon längst eine Erkältung eingefangen. Du willst mir doch nur meine Routine ausreden!“","options":[{"text":"„Ich höre, wie wichtig dir deine Routine ist, und ich will sie dir gar nicht madig machen. Mir geht es um eine Frage: Woran würdest du merken, dass es ohne die zehn Gramm genauso wäre? Hast du mal geprüft, was bei so einer Menge wirklich messbar passiert?“","style":"sokratisch","reaction":"„Hmm. Ehrlich gesagt nicht. Ich hab es nur geglaubt. Aber ich bin ja auch nicht der Einzige, der das nimmt...“","feedback":"Sehr gut: Du validierst das Gefühl („Routine ist dir wichtig“), nimmst die Verteidigung heraus und stellst die Beweisfrage so, dass Torsten sie selbst beantworten muss (Ich-Botschaft statt Vorwurf).","score":3,"nextStepId":"step-4-success"},{"text":"„Du denkst also, du bist nie krank geworden, weil du dir eine Brausetablette einwirfst? Das ist ein klassischer Fehlschluss, Torsten. Mal ehrlich, wie oft bist du früher krank gewesen? Das sagst du ja nicht dazu.“","style":"frontal","reaction":"„Jetzt unterstellst du mir, ich würde etwas verschweigen? Ich bin nicht dein Patient, ich muss mich vor dir nicht rechtfertigen!“","feedback":"Die Kritik ist in der Sache nachvollziehbar, aber der Ton („Du sagst ja nicht dazu“) klingt wie ein Vorwurf. Torsten geht in die Verteidigung, das Gespräch kippt.","score":-1,"nextStepId":"step-4-struggle"},{"text":"„Torsten, ich merke, wir treten hier gerade auf der Stelle, und mir ist das Gespräch wichtig. Lass uns die Brause kurz stehen lassen und später noch mal einen Kaffee holen, ohne Vitamin-Debatte. Okay?“","style":"ausstieg","reaction":"„*brummt* Meinetwegen. Aber ich bleibe dabei, dass es mir hilft.“","feedback":"Die Auszeit (Strategische Auszeit) rettet die Beziehung, aber du lässt eine Chance liegen: Das Gespräch war noch nicht hitzig genug dafür, und die Sachfrage bleibt offen.","score":0,"nextStepId":"step-4-struggle"}]},"step-4-success":{"id":"step-4-success","speaker":"Torsten","speech":"„Okay, wenn ich ehrlich bin, weiß ich eigentlich gar nicht, wie viel Vitamin C man wirklich braucht und ab wann es nichts mehr bringt. Das hab ich nie nachgeschaut. Wie finde ich das raus?“","options":[{"text":"„Wie wäre es, wenn wir heute Mittag gemeinsam nachschlagen? Drei Dinge: wie viel du nimmst, welche Höchstmengen Fachgremien für unbedenklich halten und ab wann schädliche Wirkungen beobachtet wurden.“","style":"sokratisch","reaction":"„*lächelt schief* Abgemacht. Und wenn ich falsch lag, geb ich dir einen Kaffee aus.“","feedback":"Sehr gut: Angelehnt an die Schmiede-Übung zu „Die Dosis-Wirkungs-Beziehung“ sucht ihr gemeinsam nach Zahlen (eingenommene Menge, Obergrenze, Schwelle für schädliche Wirkung), statt dass du belehrst. Ihr arbeitet zusammen am Problem (Gemeinsamkeiten finden).","score":3},{"text":"„Ganz einfach: Zehn Gramm sind zu viel, das schadet dir nur. Hör am besten sofort damit auf, und du wirst sehen, dass nichts passiert. Ich rede da aus Erfahrung.“","style":"frontal","reaction":"„Du sagst mir jetzt, ich soll sofort aufhören? Ich dachte, wir klären das gemeinsam...“ *zögert und wird wieder reservierter*","feedback":"Du lieferst eine fertige Anweisung statt einer gemeinsamen Suche. Das nimmt Torsten die Eigenverantwortung und weckt wieder die Abwehr.","score":-1}]},"step-4-struggle":{"id":"step-4-struggle","speaker":"Torsten","speech":"„Ich glaube, ich lasse das Thema jetzt. Ich merke, wir kommen da nicht zusammen. Ich nehme meine Tablette, du deine Meinung, und gut ist.“","options":[{"text":"„Das ist fair. Ich bin nicht gegen dich, mir ist deine Gesundheit wichtig, genau wie dir. Falls du Lust hast, schauen wir irgendwann gemeinsam nach, wie viel man braucht.“","style":"deeskalierend","reaction":"„Mal sehen. Danke, dass du es so sagst.“ *nimmt sein Glas und nickt dir zu*","feedback":"Gut: Du nennst das gemeinsame Ziel, Gesundheit (Gemeinsamkeiten finden), und lässt die Tür offen, ohne zu drängen.","score":2},{"text":"„Na toll, dann kippst du dir eben weiter Überdosen in den Magen. Wenn das schiefgeht, sag nicht, ich hätte nichts gesagt. Ich habe dich oft genug gewarnt.“","style":"sarkastisch","reaction":"„Das ist ja wohl das Letzte! Du willst mir Angst machen, nur weil du recht haben willst. Lass mich in Ruhe.“","feedback":"Der Abgang als Drohung zerstört die Gesprächsbasis. Statt Angst zu machen, hilft die gemeinsame Frage nach der Dosis; so aber kommt deine Sorge als Angriff an.","score":-2}]},"step-fail":{"id":"step-fail","speaker":"Torsten","speech":"„Weißt du was? Lass mich einfach in Ruhe mit deiner Besserwisserei. Ich weiß, was mir guttut.“ *rührt demonstrativ die Brause um und geht*","options":[{"text":"Ende: Torsten fühlt sich angegriffen und hält jetzt erst recht an seiner Überzeugung fest. Rechthaben und Überzeugen sind zweierlei.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst sein Motiv würdigen (Gesundheit) und den Dosis-Gedanken als gemeinsame Frage stellen, nicht als Urteil.","feedback":"Frage dich: Wollte ich Torsten widerlegen oder erreichen? Die Deeskalations-Matrix ordnet die Reihenfolge: erst Gefühl, dann Inhalt.","score":0}]}},"status":"entwurf","familie":"dosis-entscheidet","fertigkeit":"F4","stufe":2,"kurz":"Bei Vitaminen gilt wie bei fast jedem Stoff: Es kommt auf die Menge an. „Natürlich“ schützt nicht vor der Dosisfrage, auch natürliche Stoffe können in hohen Dosen schaden; wer zuerst die Sorge des Gegenübers anerkennt, hält das Gespräch offen.","prueffrage":"Wie viele Orangen bräuchte es für Torstens Tagesmenge, und wie oft war er in den Jahren vor der Brause erkältet?","quellen":[{"typ":"url","kurz":"Bundesinstitut für Risikobewertung: „Proposed maximum levels for the addition of vitamin C to foods including food supplements“ (PDF, Dateidatum 04.04.2022)","oeffentlich":true,"url":"https://www.bfr.bund.de/cm/349/proposed-maximum-levels-for-the-addition-of-vitamin-c-to-foods-including-food-supplements.pdf","seite":"1","abruf":"2026-10-12"},{"typ":"url","kurz":"Paracelsus (1538): Sieben Defensiones … Hg. K. Sudhoff, Leipzig: Barth 1915 – Digitalisat der Wellcome Collection (Dritte Defension: „allein die Dosis macht …“)","oeffentlich":true,"url":"https://wellcomecollection.org/works/jxt2qtp7","abruf":"2026-10-12"},{"typ":"doi","kurz":"Hemilä, H.; Chalker, E. (2013): Vitamin C for preventing and treating the common cold. Cochrane Database of Systematic Reviews 2013(1), CD000980","oeffentlich":true,"doi":"10.1002/14651858.CD000980.pub4","url":"https://pubmed.ncbi.nlm.nih.gov/23440782/","abruf":"2026-10-13"}],"thema":"Gesundheit"},{"id":"scen-arbeitskollegin-teambuilding-typ","title":"Sabrinas Persönlichkeitstest-Etikett","subtitle":"Vier Farben für alle Kollegen, geübt mit intellektueller Barmherzigkeit","character":"Sabrina, Teamleiterin","avatar":"🎨","context":"Sabrina leitet euer Team und hat nach einem Workshop alle Kolleginnen und Kollegen einem von vier Farbtypen zugeordnet. Jetzt will sie das neue Projekt strikt nach Farben besetzen: Wer „Rot“ ist, führt, wer „Blau“ ist, bekommt die Zahlen. Du merkst, dass sich dabei einige im Team ungefragt in Schubladen gesteckt fühlen.","goal":"Bring Sabrina dazu, die Aussagekraft des Farbtests selbst zu prüfen, indem du zuerst ihre gute Absicht würdigst und dann den Barnum-Effekt mit einer Frage statt mit einer Belehrung sichtbar machst.","bereich":"Arbeit","laenge":"mittel","ton":"heiter","bestehenAb":5,"lektion":"Wer die gute Absicht hinter einer Überzeugung zuerst anerkennt, bekommt Gehör für die Kritik. Sabrina will ein stimmiges Team, das ist ein legitimer Wert (Intellektuelle Barmherzigkeit). Der Test wirkt vor allem deshalb so treffsicher, weil allgemeine Beschreibungen fast jeder auf sich bezieht (Barnum-Effekt), und die Erfahrung am eigenen Beispiel überzeugt mehr als jeder Vortrag.","toolRef":"H.1.3","faktenRef":"B.10","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Sabrina","speech":"„Du, ich bin total begeistert vom Workshop! Der Farbtest hat mich so exakt beschrieben, dass ich dachte, die kennen mich persönlich. Ich habe das ganze Team eingeteilt, und beim neuen Projekt besetzen wir streng nach Farben. Der Test sagt genau voraus, wer zusammenpasst!“","options":[{"text":"„Sabrina, ehrlich, das ist Horoskop-Niveau mit Buntstiften. Wer plant denn ernsthaft ein ganzes Projekt nach so einem bunten Esoterik-Quatsch?“","style":"frontal","reaction":"„Esoterik?! Das war ein professioneller Workshop mit einer zertifizierten Trainerin! Ich dachte, du freust dich, dass ich mir überhaupt Gedanken ums Team mache!“","feedback":"Verachtung statt Barmherzigkeit: Du sprichst nicht über die Behauptung, sondern wertest Sabrina ab. Damit stellst du ihre gute Absicht in Frage, und sie geht in die Verteidigung.","score":-2,"nextStepId":"step-fail"},{"text":"„Klingt spannend! Dass du dir so viele Gedanken darüber machst, wer im Team gut zusammenarbeitet, finde ich richtig stark. Erzähl mal: Was genau stand denn bei dir in der Beschreibung?“","style":"deeskalierend","reaction":"„*strahlt* Danke! Bei mir stand: Ich sei ein Mensch mit großem Bedürfnis nach Anerkennung, manchmal kritisch mit mir selbst und mit viel ungenutztem Potenzial. Das bin ich so was von!“","feedback":"Genau richtig: Du würdigst zuerst das legitime Anliegen (ein gutes Team) und holst Sabrina als Erzählerin ins Boot. Zugleich sammelst du nebenbei die Barnum-Aussagen, die du gleich brauchst.","score":3,"nextStepId":"step-2"},{"text":"„Ach, wie schön, dass es dir gefällt! Sag mir einfach, in welche Farbgruppe du mich eingeteilt hast, dann spiele ich das Spiel mit.“","style":"humorvoll","reaction":"„Du bist Grün, 'der Harmonische'. Passt super zu dir, oder? Siehst du, ich kenne meine Leute!“","feedback":"Freundlich, aber du spielst mit und bestätigst nebenbei ihr Bild. Es entsteht noch keine Gelegenheit, die Treffsicherheit zu hinterfragen.","score":0,"nextStepId":"step-2-lax"}]},"step-2":{"id":"step-2","speaker":"Sabrina","speech":"„Das war fast unheimlich. Und bei den anderen genauso: Alle im Workshop haben gesagt, ihre Beschreibung passt perfekt. Ein Test, der bei jedem so ins Schwarze trifft, muss doch einfach gut sein, oder?“","options":[{"text":"„Genau das ist der Haken, Sabrina: Ein Test, der bei allen trifft, misst nichts Besonderes. Das ist der Barnum-Effekt. Der Test ist wertlos, und deine Projektplanung steht damit auf Sand.“","style":"frontal","reaction":"„Wertlos?! Dann hat die ganze Firma Geld für nichts ausgegeben? Du machst mir meine Idee kaputt, ohne einen besseren Vorschlag zu haben!“","feedback":"Die Richtung stimmt, aber „wertlos“ ist zu pauschal: Solche Tests können durchaus Denkanstöße geben. Du lieferst das Urteil fertig, statt Sabrina selbst darauf kommen zu lassen. Eine Frage hätte mehr bewirkt.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Anerkennung und ein bisschen Selbstkritik wünscht sich fast jeder: Wie viele Leute kennst du, auf die das nicht zutrifft? Würdest du erwarten, dass sich andere im Team in deiner Beschreibung ohne Namen wiederfinden?“","style":"sokratisch","reaction":"„Hm... Anerkennung wollen wahrscheinlich alle. Und selbstkritisch sind wir ja auch irgendwie alle mal. ...Wobei: Ich habe mich nicht gefragt, ob es bei den anderen Farben nicht auch so gewesen wäre.“","feedback":"Stark: Du stellst die Aktivierungsfrage zum Barnum-Effekt als echte Frage. Sabrina erkennt selbst, dass die Aussagen fast jeden beschreiben. Das ist Street Epistemology.","score":3,"nextStepId":"step-3-success"},{"text":"„Stimmt schon, wenn alle sich wiedererkennen, ist das ein gutes Zeichen für den Test. Dann machen wir es nach Farben, ich bin dabei und freue mich auf die Teams.“","style":"ausstieg","reaction":"„Super, dass du das auch so siehst! Dann plane ich die Besetzung gleich so, auch für das Kundenprojekt.“","feedback":"Aus Harmoniebedürfnis bestätigst du genau den Fehlschluss: Dass sich alle wiedererkennen, spricht gerade gegen die Treffsicherheit. Die Zustimmung stützt die Fehlplanung.","score":-2,"nextStepId":"step-fail-zustimmung"}]},"step-2-lax":{"id":"step-2-lax","speaker":"Sabrina","speech":"„Und weißt du, das Beste: Alle im Workshop fanden ihre Beschreibung total passend. Das kann doch kein Zufall sein, oder?“","options":[{"text":"„Spannend! Ich habe gelesen, dass sich Leute oft auch in Texten erkennen, die nicht auf sie zugeschnitten sind. Zeig die Beschreibung doch mal einem Kollegen aus einer anderen Farbe und frag, ob sie auch passt.“","style":"sokratisch","reaction":"„Oh, das ist eine lustige Idee. Ein kleines Experiment. Okay, das probiere ich aus!“","feedback":"Gut: Du schlägst einen Selbsttest vor, statt zu belehren. Das ist die Idee hinter Forers Experiment. Weil du zuvor die Absicht nicht erst gewürdigt hast, wirkt es noch etwas beiläufig.","score":3,"nextStepId":"step-3-success"},{"text":"„Nein, kein Zufall, sondern der Barnum-Effekt. Das hat ein Professor 1948 bewiesen, und der Test ist Betrug. Du fällst auf einen bunten Schwindel herein, Sabrina, und blamierst dich damit im Team.“","style":"frontal","reaction":"„Betrug?! Du behandelst mich wie eine Dumme! Ich habe es gut gemeint, und du machst mich vor dem Team zum Gespött!“","feedback":"Die Begriffe stimmen, aber 'Betrug' und 'hereinfallen' greifen die Person an, nicht die Behauptung. Ohne Barmherzigkeit kommt die Sache nicht an.","score":-2,"nextStepId":"step-fail"},{"text":"„Sicher kein Zufall. Mach nur, du bist die Chefin, ich bin gespannt, wie es läuft. Ich halte mich da lieber raus und schaue mir das Ergebnis in Ruhe an.“","style":"ausstieg","reaction":"„Danke fürs Vertrauen! Ich schicke dir morgen die Besetzungsliste.“","feedback":"Rückzug ohne Klärung: Die Beziehung ist heil, aber die Planung läuft unhinterfragt weiter. Etwas mehr Mut zur Frage wäre hier möglich gewesen.","score":-1,"nextStepId":"step-3-struggle"}]},"step-3-success":{"id":"step-3-success","speaker":"Sabrina","speech":"„Weißt du was? Ich mache das Experiment: Ich gebe meine Beschreibung ohne Namen an drei Leute aus anderen Farben und frage, wie gut sie passt. Wenn alle ‚trifft zu‘ sagen, überlege ich, ob ich das Projekt wirklich nach Farben plane. Kann ich das als Teambuilding-Frage in der Runde stellen?“","options":[{"text":"„Gern! Und den Test kannst du ja trotzdem als Gesprächsanlass nutzen: Er bringt Leute dazu, über ihre Arbeitsweise zu reden. Für die Besetzung zählt dann, was jede und jeder konkret kann und will.“","style":"deeskalierend","reaction":"„Das gefällt mir. Der Test als Einstieg, die Besetzung nach Erfahrung und Wunsch. Danke, dass du mir nicht gleich die ganze Idee zerlegt hast!“","feedback":"Mission gelungen! Du hast Sabrinas Anliegen respektiert, den Barnum-Effekt sichtbar gemacht und ihr einen praktikablen Weg gezeigt, ohne dass sie ihr Gesicht verlieren musste.","score":3}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Sabrina","speech":"„Ich bin jetzt ehrlich verunsichert. Ich wollte nur etwas Gutes fürs Team tun und weiß nicht, ob ich dir recht geben soll...“","options":[{"text":"„Das Gute fürs Team nehme ich dir sofort ab, Sabrina. Lass uns beim nächsten Kaffee in Ruhe schauen, wie wir die Besetzung auch nach Erfahrung und Wünschen der Leute ergänzen können. Magst du?“","style":"deeskalierend","reaction":"„Ja, gern. Das klingt nach einem Plan, bei dem keiner in einer Schublade landet.“","feedback":"Guter Übergang: Beziehung gesichert, Absicht gewürdigt, das Thema bleibt offen für ein ruhigeres Gespräch.","score":2}]},"step-fail":{"id":"step-fail","speaker":"Sabrina","speech":"„Ich glaube, wir lassen das. Ich plane das Projekt nach meinem Gefühl, und das Gefühl sagt mir, dass die Farben stimmen.“ *wendet sich ab*","options":[{"text":"Ende: Sabrina fühlte sich nicht verstanden und hält jetzt erst recht an ihrem Farbmodell fest. Wer die gute Absicht übergeht, verliert das Gespräch.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst das legitime Anliegen anerkennen, dann mit einer Frage prüfen, wie treffsicher der Test wirklich ist.","feedback":"Frage dich: Wollte ich Sabrina belehren oder ihr beim Prüfen helfen? Barmherzigkeit kommt vor der Sachkritik.","score":0}]},"step-fail-zustimmung":{"id":"step-fail-zustimmung","speaker":"Sabrina","speech":"„Ich schicke dir gleich die Besetzungsliste: Alle Rollen nach Farben, auch beim Kundenprojekt. Das wird richtig gut!“","options":[{"text":"Ende: Sabrina plant alles nach Farben, auch das Kundenprojekt. Die Beziehung ist heil, aber der Fehlschluss wurde bestätigt: Dass sich alle wiedererkennen, spricht gerade gegen die Treffsicherheit des Tests.","style":"ausstieg","reaction":"Beim nächsten Mal die Zustimmung nicht aus Harmoniebedürfnis geben, sondern eine freundliche Frage stellen: Würde die Beschreibung auch auf andere im Team passen?","feedback":"Frage dich: Habe ich zugestimmt, weil ich überzeugt war, oder um Streit zu vermeiden? Eine Frage hätte die Beziehung genauso gewahrt und den Test geprüft.","score":0}]}},"status":"entwurf","familie":"passt-auf-jeden","fertigkeit":"F2","stufe":3,"kurz":"Ein solcher Farbtest wirkt vor allem deshalb treffsicher, weil allgemeine Beschreibungen fast jeder auf sich bezieht. Wer die gute Absicht hinter einer Überzeugung zuerst anerkennt, bekommt Gehör, und ein Versuch am eigenen Beispiel überzeugt mehr als jeder Vortrag.","prueffrage":"Wenn Sabrina ihre Beschreibung ohne Namen Leuten aus anderen Farbgruppen zeigt: Wie viele von ihnen würden sich darin wiederfinden?","quellen":[{"typ":"url","kurz":"Poškus, M. S. (2014): „A New Way of Looking at the Barnum Effect and Its Links to Personality Traits in Groups Receiving Different Types of Personality Feedback“. Psichologija 50","oeffentlich":true,"url":"https://www.zurnalai.vu.lt/psichologija/article/download/4893/3148/","seite":"95","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Forer, B. R. (1949): „The Fallacy of Personal Validation: A Classroom Demonstration of Gullibility“. Journal of Abnormal and Social Psychology 44, S. 118–123 (nach Landkarte-Fn. gl-b-forer; Mittelwert 4,26)","oeffentlich":false},{"typ":"url","kurz":"Dresner, E. (2011): „The Principle of Charity and Intercultural Communication“. International Journal of Communication 5, S. 969–982 (laut Belegregister geprüft)","oeffentlich":true,"url":"https://ijoc.org/index.php/ijoc/article/view/817"}],"thema":"Zusammenleben"},{"id":"scen-chat-bild-echt","title":"Papa und das empörende Foto","subtitle":"„Das Bild beweist alles“, geübt mit der Deeskalations-Matrix","character":"Papa Rainer","avatar":"🖼️","context":"Im Familienchat taucht ein Foto auf, das angeblich einen eindeutigen Skandal zeigt. Dein Vater Rainer hat es mit vielen Ausrufezeichen weitergeleitet und schreibt dir kurz darauf, er sei „außer sich“. Du rufst ihn an.","goal":"Beruhige die Lage mit den Techniken der Deeskalations-Matrix und lenke das Gespräch auf die Frage, woher das Bild stammt, ohne Papa bloßzustellen.","bereich":"Familie","laenge":"mittel","ton":"ernst","bestehenAb":6,"lektion":"Ein Bild, das Wut auslöst, ist erst eine Behauptung, noch kein Beweis: Ein Foto allein reicht heute nicht mehr als Beleg, und umgekehrt kann auch echtes Material als „Fake“ abgetan werden (Lügner-Dividende). Erst wenn Papa sich gehört fühlt, kann er die Quellenfrage zulassen. Die Deeskalations-Matrix rettet das Gespräch, indem sie Gefühle validiert, ohne dem Inhalt zuzustimmen.","toolRef":"H.2.1","faktenRef":"E.4.4","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Papa Rainer","speech":"„Hast du das Foto im Chat gesehen?! Das ist der Beweis, schwarz auf weiß! Da kann doch keiner mehr sagen, das sei erfunden! Die lügen uns doch alle an, und ihr schaut zu!“","options":[{"text":"„Papa, ich hab es gesehen. Und ehrlich: Heutzutage kann man jedes Bild fälschen. Du bist da schon wieder auf irgendeinen Quatsch hereingefallen.“","style":"frontal","reaction":"„Auf Quatsch hereingefallen?! Ich bin doch nicht blöd! Immer wollt ihr Jungen alles besser wissen. Ich hab Augen im Kopf!“","feedback":"Die Sachaussage stimmt im Kern, aber „schon wieder hereingefallen“ ist eine Du-Anklage. Papa geht in die Verteidigung, und die Sachebene ist vorerst verloren.","score":-2,"nextStepId":"step-fail"},{"text":"„Ich höre, wie wütend dich das macht, Papa. Das klingt, als würde dich das wirklich umtreiben. Erzähl mal in Ruhe, was genau du auf dem Bild siehst?“","style":"deeskalierend","reaction":"„*schnauft hörbar* Na ja... Du hörst mir wenigstens zu. Also: Da ist dieser Mann mit diesem Umschlag, und die Gesichter sprechen doch Bände...“","feedback":"Genau das Richtige: Aktives Zuhören und Gefühle validieren. Du nimmst die Wut ernst, ohne dem Inhalt zuzustimmen. Der Pegel sinkt, Papa erzählt.","score":3,"nextStepId":"step-2"},{"text":"„Wahnsinn, Papa, das ist ja unglaublich! Wenn das stimmt, muss man sofort etwas tun! Ich teile es gleich auch in meiner Gruppe, das müssen alle sehen!“","style":"affektiv","reaction":"„Genau! Endlich versteht mich mal einer! Schick es an alle, ich schreib noch die Nachbarn an!“","feedback":"Du steigst auf die Welle der Empörung und verbreitest ungeprüftes Material weiter. Mitgefühl ist nicht Mitmachen: Die Wut ist echt, der Beweis noch lange nicht.","score":-1,"nextStepId":"step-panic"}]},"step-2":{"id":"step-2","speaker":"Papa Rainer","speech":"„Das Bild ist so klar, da brauchst du keine Quelle! Wenn ich etwas mit eigenen Augen sehe, dann ist das doch Wahrheit. Oder soll ich meinen eigenen Augen nicht mehr trauen?“","options":[{"text":"„Papa, die Wahrheit ist: Dein Gehirn ist auf diese Täuschung hereingefallen, das ist reine Biologie. Du kannst dem Bild gar nicht trauen, das ist Fakt, und damit hat sich das.“","style":"frontal","reaction":"„Mein Gehirn?! Jetzt soll ich auch noch kaputt im Kopf sein? Spar dir deinen Professorenton!“","feedback":"Belehrend und mit Du-Botschaft („dein Gehirn ist hereingefallen“): Das wirkt wie ein Angriff auf die Person, nicht auf die Behauptung, und kippt das Gespräch zurück in die Eskalation.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Ich verstehe dein Misstrauen, Papa, wir wollen beide die Wahrheit. Aber heute kann auch ein falsches Bild so echt wirken. Hilf mir mal: Wer hat das Foto zuerst gepostet?“","style":"sokratisch","reaction":"„Wer zuerst...? Hm, das kam über die Gruppe von Karl. Und der hat es von irgendeinem Kanal. Ich weiß nicht genau, welcher es war.“","feedback":"Stark: Du baust eine Brücke über das gemeinsame Ziel (Wahrheit), nutzt eine Ich-Botschaft und stellst die Quellenfrage als gemeinsame Detektivarbeit. Die Beweiskette wird sichtbar lückenhaft.","score":3,"nextStepId":"step-3-success"},{"text":"„Gut, Papa, dann glaub es halt. Ich kann dich ja nicht umstimmen. Hauptsache, du regst dich nicht auf. Mach, was du willst, ich sage dazu nichts mehr.“","style":"ausstieg","reaction":"„Siehst du, selbst du kannst nichts dagegen sagen. Also stimmt es ja wohl.“","feedback":"Rückzug ohne Absicht zur Wiederaufnahme wirkt wie Zustimmung. Eine Auszeit muss klar benannt sein („später weiterreden“), sonst gibst du die Position auf (Kipppunkt).","score":-2,"nextStepId":"step-fail"}]},"step-3-success":{"id":"step-3-success","speaker":"Papa Rainer","speech":"„Du meinst, solange ich nicht weiß, wer es als Erster hatte, ist das noch kein Beweis? Aber was ist, wenn das Bild trotzdem echt ist und die es nur als Fälschung hinstellen, um sich rauszureden?“","options":[{"text":"„Genau, Papa, deshalb schauen wir ja nach. Wenn jemand ein Bild als Fälschung abtut, braucht er dafür Beweise. Lass uns zusammen die Originalquelle suchen, ich komme nachher vorbei.“","style":"sokratisch","reaction":"„Gut. Aber ich bleibe dabei: Wenn es stimmt, will ich es wissen. Komm vorbei, wir schauen gemeinsam.“","feedback":"Sehr gut: Du erkennst Papas Einwand an (die Lügner-Dividende gibt es wirklich) und drehst ihn in eine gemeinsame Prüfung. Die Beweislast liegt bei dem, der die Fälschung behauptet.","score":3},{"text":"„Wenn ich dir zeige, dass es ein Fake ist, löschst du dann dein Weiterleiten und entschuldigst dich im Chat bei allen?“","style":"frontal","reaction":"„Entschuldigen?! Ich soll mich auch noch entschuldigen? Vergiss es, jetzt erst recht nicht.“","feedback":"Eine Entschuldigungsforderung ist eine Anklage: Sie zwingt Papa in die Verteidigung. In eskalierten Gesprächen geht es dann nur noch um Gewinnen und Gesichtsverlust, und aus der Sachprüfung wird ein Duell.","score":-1},{"text":"„Gute Frage, Papa. Man kann beides nicht sicher sagen, solange wir die Herkunft nicht kennen. Deshalb leite es bitte bis dahin nicht weiter, okay?“","style":"deeskalierend","reaction":"„Na gut, ich warte. Aber nur, weil du fragst.“","feedback":"Brauchbar: Du bringst die Prüfung vor das Teilen und lässt Papa sein Gesicht wahren. Es fehlt der gemeinsame nächste Schritt, aber der Kanal bleibt offen.","score":2}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Papa Rainer","speech":"„Ich hab keine Lust auf deine Belehrungen. Was willst du eigentlich von mir? Ich bin schließlich dein Vater.“","options":[{"text":"„Du hast recht, Papa, das war grad nicht fair von mir. Ich hör mich an wie ein Schulmeister, tut mir leid. Lass uns kurz Luft holen und heute Abend nochmal in Ruhe reden?“","style":"deeskalierend","reaction":"„*brummt* Ja. Gut. Heute Abend, aber ohne Vorträge.“","feedback":"Gelungene strategische Auszeit: Du erkennst deinen Anteil an, würdigst die Beziehung und benennst die Wiederaufnahme. Das Thema bleibt für später offen, das Gespräch ist gerettet.","score":2},{"text":"„Dann denk halt, was du willst. Fakt ist, du verbreitest Falschinformationen im ganzen Familienchat, und irgendjemand muss dir das ja mal sagen.“","style":"frontal","reaction":"„Falschinformationen?! Jetzt reicht’s mir! Ich leg auf.“ *Klick*","feedback":"Anklage statt Brücke: Aus einem angespannten Gespräch wird ein Abbruch. Mit „Falschinformationen“ greifst du den Menschen an, nicht die Behauptung.","score":-2}]},"step-fail":{"id":"step-fail","speaker":"Papa Rainer","speech":"„Ich hab’s satt, mich von dir belehren zu lassen. Ich schick das Bild jetzt an alle, und wer es nicht sehen will, soll es lassen!“ *legt auf*","options":[{"text":"Ende: Papa fühlte sich nicht gehört und verteilt das Bild jetzt erst recht weiter. Rechthaben und Helfen sind zweierlei.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst das Gefühl ernst nehmen, dann erst über die Quelle reden.","feedback":"Frag dich: War mein Ziel, im Streit zu gewinnen oder das Gespräch zu retten? Die Deeskalations-Matrix stellt die Reihenfolge klar: erst das Gefühl, dann der Inhalt.","score":0}]},"step-panic":{"id":"step-panic","speaker":"Papa Rainer","speech":"„Siehst du, wir müssen das alle sofort wissen! Ich schreib noch Karl und die Nachbarn, und dann gehen wir damit zur Zeitung!“","options":[{"text":"Ende: Gemeinsame Empörung schaukelt sich hoch, und ein ungeprüftes Bild wandert weiter durch Chats und Gruppen. Der ruhige Gegenpol fehlt.","style":"ausstieg","reaction":"Mitgefühl ja, Mitempörung nein: Wer mitschreit, kann nichts prüfen.","feedback":"Ein Bild, das Wut auslöst, ist erst eine Behauptung. Deeskalation heißt, das Gefühl ernst zu nehmen und selbst ruhig zu bleiben, damit die Quellenfrage überhaupt Platz bekommt.","score":0}]}},"status":"entwurf","familie":"bild-und-video-pruefen","fertigkeit":"F1","stufe":3,"kurz":"Ein Bild, das Wut auslöst, ist zunächst eine Behauptung, noch kein Beweis; umgekehrt kann auch echtes Material vorschnell als Fälschung abgetan werden. Erst wer sich gehört fühlt, lässt die Frage nach der Herkunft zu, deshalb kommt das Gefühl vor der Quelle.","prueffrage":"Wer hat das Foto zuerst veröffentlicht, wann und in welchem Zusammenhang, und wie viele dieser Stationen kann Papa benennen?","quellen":[{"typ":"url","kurz":"Chesney, B.; Citron, D. (2019): „Deep Fakes: A Looming Challenge for Privacy, Democracy, and National Security“. California Law Review 107, S. 1753–1820, DOI 10.15779/Z38RV0D15J","oeffentlich":true,"url":"https://www.californialawreview.org/s/2-Chesney-Citron.pdf","seite":"1785","abruf":"2026-10-06"},{"typ":"doi","kurz":"Köbis, N. C.; Doležalová, B.; Soraperra, I. (2021): „Fooled Twice: People Cannot Detect Deepfakes but Think They Can“. iScience 24(11), 103364 (laut Belegregister Verlagsfassung CC BY-NC-ND)","oeffentlich":true,"doi":"10.1016/j.isci.2021.103364"}],"thema":"Netz und Medien"},{"id":"scen-vermieter-kaelte-winter","title":"Herr Pohl und der kalte Winter","subtitle":"„Wo bleibt die Erderwärmung?“, geübt mit Street Epistemology","character":"Herr Pohl, Nachbar","avatar":"🥶","context":"Es ist Januar, seit drei Tagen herrscht Dauerfrost, und dein Nachbar Herr Pohl kratzt vor dem Haus sein Auto frei. Als du vorbeikommst, hält er dir mit triumphierendem Grinsen sein Handy-Thermometer unter die Nase: Minus 14 Grad. Für ihn ist damit die Klimadebatte erledigt.","goal":"Bring Herrn Pohl mit neugierigen Fragen (Street Epistemology) dazu, selbst zu prüfen, ob drei Kältetage ein verlässliches Argument gegen einen langfristigen Klimatrend sind.","bereich":"Nachbarschaft","laenge":"mittel","ton":"heiter","bestehenAb":6,"lektion":"Wer jemanden nur korrigiert, bekommt oft Verteidigung; wer nach der Methode fragt („Woher wissen Sie das? Wie verlässlich ist das?“), regt eher Nachdenken an. Drei Kältetage sind Wetter, der Hund auf der Wiese. Das Klima ist der Spaziergänger, und den sieht man erst über Jahrzehnte. Street Epistemology prüft nicht die Schlussfolgerung, sondern den Weg dorthin.","toolRef":"H.2.2","faktenRef":"C.5.1","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Herr Pohl","speech":"„Na, guten Morgen! Schauen Sie sich das an: minus vierzehn Grad! Und die erzählen uns was von ‚Erderwärmung‘! Wenn das so weitergeht, brauche ich bald einen Schlitten statt eines Autos. Ha!“","options":[{"text":"„Herr Pohl, das ist der klassische Denkfehler: Das hier ist Wetter, kein Klima. Drei kalte Tage widerlegen gar nichts. Das lernt man eigentlich in der Schule.“","style":"frontal","reaction":"„Aha, jetzt belehrt mich auch noch der Nachbar! Ich spüre die Kälte an den Fingern, da brauche ich keine Schulweisheiten.“ *kratzt demonstrativ lauter*","feedback":"Inhaltlich richtig, aber als Belehrung verpackt. Herr Pohl fühlt sich vorgeführt und macht dicht. Street Epistemology beginnt mit Neugier statt mit der Korrektur.","score":-1,"nextStepId":"step-struggle"},{"text":"„Brrr, ja, das ist wirklich eisig! Darf ich Sie was fragen? Was genau meinen Sie: Dass es dieses Jahr nirgends wärmer wird, oder dass die ganze Erwärmungsgeschichte nicht stimmt?“","style":"sokratisch","reaction":"„Na, das Zweite! Wie soll sich die Erde erwärmen, wenn mir hier die Scheibenwischer festfrieren? Das sagt einem doch der gesunde Menschenverstand.“","feedback":"Gut: Du klärst zuerst, was genau behauptet wird. Und du holst dir die Erlaubnis zum Fragen, bevor du etwas anderes tust.","score":3,"nextStepId":"step-2"},{"text":"„Haha, ja, bei dem Wetter wünscht man sich fast die Erderwärmung herbei! Ich wünsche Ihnen einen schönen Tag, Herr Pohl, und fahren Sie vorsichtig.“","style":"humorvoll","reaction":"„Sehen Sie, selbst Sie geben es zu! Schönen Tag noch!“ *schmunzelt zufrieden*","feedback":"Freundlich, aber du lässt die Behauptung unwidersprochen stehen, und Herr Pohl sieht sich bestätigt. Beziehungspflege ist gut, aber hier wird keine Frage gestellt.","score":0,"nextStepId":"step-fail"}]},"step-2":{"id":"step-2","speaker":"Herr Pohl","speech":"„Ich bin da ziemlich sicher, sag ich Ihnen. Frostschäden, Eis auf den Straßen, die Heizkosten: Das spüre ich doch am eigenen Leib. Wärmer wird es da jedenfalls nicht.“","options":[{"text":"„Das glaube ich Ihnen sofort, das spürt man. Wenn Sie es auf einer Skala von 0 bis 100 sagen müssten: Wie sicher sind Sie, dass sich die Erde insgesamt nicht erwärmt?“","style":"sokratisch","reaction":"„Hm, Skala... na, so 90 Prozent. Vielleicht 95. Was soll man bei dem Wetter denn sonst glauben? Sie wollen wissen, warum ich so sicher bin?“","feedback":"Sehr gut: Die 0-bis-100-Skala macht aus „Ja oder Nein“ ein Spektrum und zeigt, wie viel Gewicht die Überzeugung trägt. Du bestätigst sein Erleben, nicht den Schluss daraus.","score":3,"nextStepId":"step-3"},{"text":"„Die Heizkosten spüren Sie, klar. Aber die NASA hat Messreihen von hundert Jahren, und die zeigen einen eindeutigen Aufwärtstrend. Schauen Sie sich die Grafik doch mal an!“","style":"frontal","reaction":"„Messreihen, Messreihen... Die kann man sich doch zurechtbiegen. Ich glaub, was ich vor der Haustür sehe!“","feedback":"Du wirfst eine Quelle in den Raum, bevor du weißt, worauf Herr Pohl seine Sicherheit gründet. Das provoziert nur das Gegenargument „Daten kann man biegen“.","score":-1,"nextStepId":"step-struggle"},{"text":"„Heizkosten? Dann sind Sie bestimmt auch gegen Ökostrom und Windräder, oder? Typisch.“","style":"sarkastisch","reaction":"„Was hat denn das jetzt damit zu tun? Jetzt unterstellen Sie mir auch noch was! Ich gehe rein.“ *knallt die Autotür zu*","feedback":"Du unterstellst ihm eine ganze Weltanschauung. Untersucht wird die Behauptung, nicht der Mensch. So endet das Gespräch, bevor es angefangen hat.","score":-2,"nextStepId":"step-fail"}]},"step-3":{"id":"step-3","speaker":"Herr Pohl","speech":"„Warum so sicher? Na, weil ich es doch sehe! Drei Tage Dauerfrost, und im Radio haben sie von Kälterekorden gesprochen. Wenn sich die Erde erwärmen würde, gäbe es sowas ja nicht. Das ist doch Beweis genug.“","options":[{"text":"„Das ist der Wetterbericht, nicht das Klima. Ein einzelner kalter Tag sagt so viel über den Klimatrend wie ein einzelner warmer. Das ist die berühmte Verfügbarkeitsheuristik, Herr Pohl.“","style":"frontal","reaction":"„Verfügbarkeits-was? Na toll, jetzt kommt er mir mit Fachwörtern. Ich weiß, was ich fühle!“","feedback":"Das Fachwort schreckt ab, und du lieferst die Lösung als Vortrag, statt Herrn Pohl selbst darauf kommen zu lassen. Die Methodenfrage bleibt ungestellt.","score":0,"nextStepId":"step-struggle"},{"text":"„Verstehe, Sie gehen nach dem, was Sie selbst erleben, das ist eine ehrliche Methode. Wie würden Sie merken, ob drei kalte Tage das normale Auf und Ab sind oder sich langfristig etwas verschiebt?“","style":"sokratisch","reaction":"„Hm... langfristig? Ich meine, man müsste wohl länger hinschauen als nur drei Tage. Aber dann wären es ja trotzdem nur meine eigenen Winter, die ich so erinnere...“","feedback":"Sehr gut: Du würdigst seine Methode („eigene Erfahrung“), prüfst sie aber auf Zuverlässigkeit. Herr Pohl entdeckt selbst, dass Erfahrung und Zeitraum zusammenhängen.","score":3,"nextStepId":"step-4"},{"text":"„Dann frage ich mal anders: Sind Sie bei jeder Behauptung so sicher? Hat Sie Ihr Bauchgefühl nie hereingelegt, Herr Pohl, auch nicht bei wichtigen Entscheidungen?“","style":"sarkastisch","reaction":"„Wie bitte? Wollen Sie mir sagen, dass ich keine Ahnung habe? Mein Bauchgefühl hat mich noch selten getäuscht!“","feedback":"Die Frage hat den richtigen Kern (Zuverlässigkeit der Methode), kommt aber als Spitze daher. Echte Neugier statt Kreuzverhör, so die Warnung der Street Epistemology.","score":-1,"nextStepId":"step-struggle"}]},"step-4":{"id":"step-4","speaker":"Herr Pohl","speech":"„Na gut, aber was soll ich denn sonst nehmen? Ich kann ja nicht dreißig Jahre lang jeden Tag ein Thermometer ablesen. Wie sollte man das sonst feststellen?“","options":[{"text":"„Dafür gibt es Messreihen über Jahrzehnte, etwa die globale Durchschnittstemperatur der letzten hundert Jahre, und die zeigen einen klaren Aufwärtstrend. Sie müssen nur mal googeln.“","style":"frontal","reaction":"„Googeln, googeln... da steht doch alles und das Gegenteil. Ich habe keine Lust auf Zahlenschlachten.“","feedback":"Wieder wirft Herr Pohl die Flinte ins Korn: Du hast Zahlen ohne Gesprächsfaden geliefert, und er wehrt ab. Sein eigenes Nachdenken kommt zu kurz.","score":0,"nextStepId":"step-struggle"},{"text":"„Stellen Sie sich vor, Sie gehen mit einem Hund spazieren: Der Hund rennt mal nach links, mal nach rechts, aber Sie gehen geradeaus. Wäre es klug, nur fünf Sekunden auf den Hund zu schauen, um zu wissen, wohin Sie gehen?“","style":"humorvoll","reaction":"„*lacht* Nein, da müsste man schon länger zuschauen. Der Hund springt ja überall herum! ...Moment, wollen Sie damit sagen, mein Frost ist der Hund?“","feedback":"Eine schöne Analogie aus „Das Klimasystem“: Wetter ist der Hund, Klima der Spaziergänger. Du lieferst sie als Frage, nicht als Vortrag, sodass Herr Pohl den Schluss selbst zieht.","score":2,"nextStepId":"step-5"},{"text":"„Gute Frage. Was wäre aus Ihrer Sicht die verlässlichste Methode, um das herauszufinden? Ihr eigener Winterfrost, die Messreihe von mehreren Jahrzehnten oder etwas ganz anderes?“","style":"sokratisch","reaction":"„Wenn ich es ehrlich überlege... die lange Messreihe wohl. Die ist ja gerade dafür gemacht. Aber ich will wissen, wer die macht und ob man denen trauen kann.“","feedback":"Sauber: Du lässt ihn die zuverlässigere Methode selbst benennen. Seine Folgefrage nach der Quelle ist legitim und eine gute Grundlage für ein weiteres Gespräch.","score":3,"nextStepId":"step-5"}]},"step-5":{"id":"step-5","speaker":"Herr Pohl","speech":"„Okay, okay, der Hund und der Spaziergänger. *kratzt sich am Kopf* Aber trotzdem: Wenn sich die Erde erwärmt, dürfte es solche Kälte doch gar nicht mehr geben. Das passt für mich nicht zusammen.“","options":[{"text":"„Ehrliche Frage. Was müsste man beobachten, um das zu prüfen: einzelne Kältetage oder wie oft Hitze- und Kälteextreme über Jahrzehnte vorkommen? Laut Forschung werden Hitzewellen häufiger und Kälteextreme seltener.“","style":"sokratisch","reaction":"„Ah, also nicht jeder Tag wird wärmer, sondern im Mittel... Dann müsste man wohl die Jahrzehnte anschauen und nicht den einzelnen Frosttag. Das hat mir noch nie jemand so erklärt. Muss ich mal in Ruhe nachlesen.“","feedback":"Treffer: Du würdigst den Einwand, lässt ihn die passende Beobachtungsmethode selbst wählen und ergänzt knapp den Befund aus „Das Klimasystem“: Extreme verschieben sich, einzelne Kälteeinbrüche sind Wetter, kein Gegenbeweis.","score":3,"nextStepId":"step-6-success"},{"text":"„Das ist ein sehr guter Punkt, und ich habe selbst nicht alle Details im Kopf. Wollen wir uns das mal zusammen anschauen, zum Beispiel bei einem Kaffee? Dann sehen wir beide klarer, was dahintersteckt.“","style":"ausstieg","reaction":"„Kaffee klingt gut, mir sind sowieso die Zehen eingefroren. Aber Sie laden ein!“","feedback":"Ein sympathischer Ausstieg: Beziehung gesichert, Neugier geweckt. Die Sachfrage bleibt aber offen, und den Zweifelskeim hast du nicht gezielt gesetzt.","score":1,"nextStepId":"step-6-success"},{"text":"„Das passt zusammen, wenn man die Thermodynamik versteht: Der zweite Hauptsatz sorgt für Wärmeausgleich zwischen Tropen und Polen und die zusätzliche Energie destabilisiert das ganze Wettermuster. Klar?“","style":"frontal","reaction":"„Thermo-was? Jetzt verstehe ich gar nichts mehr. Ich bleibe bei meinem Eiskratzer.“","feedback":"Die Physik stimmt, doch mitten im Gespräch ein Fachvortrag? Das überfordert und schreckt ab. Ein Beispiel oder eine Frage wäre hier stärker gewesen.","score":-1,"nextStepId":"step-struggle"}]},"step-6-success":{"id":"step-6-success","speaker":"Herr Pohl","speech":"„Wissen Sie was? Ich habe mich einfach vom Frost blenden lassen. Hund und Spaziergänger, das merke ich mir. Aber bevor ich Ihnen das ganz glaube, schaue ich mir die Grafik selbst an. Einverstanden?“","options":[{"text":"„Das wäre großartig, und wenn Sie mögen, schaue ich sie mir mit Ihnen an. Danke, dass Sie sich die Zeit genommen haben, das hat mir wirklich geholfen.“","style":"deeskalierend","reaction":"„*lacht* Na dann, Nachbar. Und jetzt helfen Sie mir mal beim Eiskratzen, damit ich losfahren kann!“","feedback":"Perfekter Abschluss: Du erzwingst kein Geständnis, sondern lässt einen kleinen Stein des Zweifels rollen und bedankst dich für das Gespräch. So bleibt er neugierig und die Beziehung heil.","score":3},{"text":"„Sehr gut! Und wenn Sie nach dem Blick in die Grafik immer noch so sicher sind, dann haben Sie eben verloren, und ich habe es von Anfang an gewusst. Abgemacht?“","style":"sarkastisch","reaction":"„Verloren?! Na warten Sie, ich schaue mir das an und dann reden wir. Aber mit Wettschulden habe ich es nicht so.“","feedback":"Die Wette macht aus der gemeinsamen Prüfung ein Duell mit Gewinner und Verlierer. Das widerspricht dem Geist der Street Epistemology: gemeinsam fragen, nicht gewinnen.","score":0},{"text":"„Gut so. Und wenn Sie dann merken, dass ich recht hatte, erwarte ich eine Entschuldigung, und zwar vor den anderen Nachbarn!“","style":"frontal","reaction":"„Eine Entschuldigung? Dafür kratzen Sie mir jetzt erst mal das Auto frei!“ *grinst schief, aber die Stimmung ist abgekühlt*","feedback":"Der Erfolg war da, aber der Nachsatz macht daraus wieder ein Rechthaberspiel. Mit Gesicht wahren lässt sich leichter umdenken.","score":-1}]},"step-struggle":{"id":"step-struggle","speaker":"Herr Pohl","speech":"„Ach, hören Sie doch auf. Ich habe keine Lust, mich jetzt auch noch zu rechtfertigen. Mir ist kalt und mein Auto steht noch unter einer Eisschicht.“","options":[{"text":"„Alles gut, Herr Pohl, ich wollte Sie nicht festnageln. Ich helfe Ihnen kurz beim Kratzen, und wenn Sie mal Lust haben, quatschen wir ein andermal in Ruhe weiter. Okay?“","style":"ausstieg","reaction":"„*brummt* Na gut. Nehmen Sie den kleinen Kratzer, der große ist meiner.“","feedback":"Guter Rückzug: Du nimmst den Druck raus, schützt die Beziehung und lässt die Tür für ein späteres Gespräch offen. Die Sache selbst bleibt unerledigt, aber nichts ist verbrannt.","score":2},{"text":"„Ich verstehe Sie nicht. Das ist doch wirklich einfach: Wetter ist nicht Klima! Das kann man doch in zwei Sätzen erklären, wenn man nur zuhören würde.“","style":"frontal","reaction":"„Dann verstehe ich Sie auch nicht! Schönen Tag!“ *dreht sich weg und steigt ins Auto*","feedback":"Wer die Behauptung wiederholt, statt zu fragen, verfestigt nur die Fronten. Herr Pohl fühlt sich gedrängt und geht in die Verteidigung.","score":-2},{"text":"„Sie haben recht, es ist wirklich saukalt. Ich gehe wieder rein. Bis bald, Herr Pohl, und gute Fahrt! Lassen Sie sich von mir nicht aufhalten.“","style":"ausstieg","reaction":"„Danke, Ihnen auch. Bis bald.“","feedback":"Ein stiller, freundlicher Rückzug: harmlos, aber ohne Gewinn. Es bleibt die Erkenntnis, dass die Frage nach der Methode früher hätte kommen können.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Herr Pohl","speech":"„Sehen Sie, so sieht's aus! Ich lasse mir von niemandem erzählen, dass sich die Welt erwärmt, solange mir die Finger abfrieren. Schönen Tag noch!“ *startet den Motor und fährt los*","options":[{"text":"Ende: Das Gespräch ist beendet, ohne dass Herr Pohl über seine Methode nachgedacht hat. Wer die Behauptung stehen lässt oder den Menschen angreift, öffnet keine Tür.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst fragen: „Woher wissen Sie das? Wie sicher sind Sie? Wie verlässlich ist diese Methode?“","feedback":"Street Epistemology beginnt mit Neugier und der Frage nach dem Weg, nicht nach dem Ergebnis. Die Aktivierungsfrage hilft: Sprechen wir gerade über den Hund oder über den Spaziergänger?","score":0}]}},"status":"entwurf","familie":"trend-statt-einzelfall","fertigkeit":"F4","stufe":1,"kurz":"Drei kalte Tage sagen etwas über das Wetter, nicht über den Klimatrend, der sich erst über Jahrzehnte zeigt. Wer nach dem Weg zur Überzeugung fragt („Woher weißt du das? Wie verlässlich ist das?“), regt eher Nachdenken an als jemand, der nur korrigiert.","prueffrage":"Wie viele Tage stecken in dieser Beobachtung, und wie lange müsste man messen, um eine Entwicklung über Jahrzehnte zu erkennen?","quellen":[{"typ":"url","kurz":"Umweltbundesamt: „Häufige Fragen zum Klimawandel“ (Stand 15.03.2021), Frage 1 und 9","oeffentlich":true,"url":"https://www.umweltbundesamt.de/themen/klima-energie/klimawandel/haeufige-fragen-klimawandel","abruf":"2026-10-12"},{"typ":"doi","kurz":"IPCC (2021): „Summary for Policymakers“. In: Climate Change 2021: The Physical Science Basis. Contribution of Working Group I to the Sixth Assessment Report (laut Belegregister geprüft)","oeffentlich":true,"doi":"10.1017/9781009157896.001"},{"typ":"url","kurz":"Hitchens, J. (2022): „Street Epistemology: Understanding the Basics“. Street Epistemology International","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/street-epistemology-the-basics","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"scen-lena-mathe","title":"Lena und die Mathe-Mauer","subtitle":"Selbsterfüllende Erwartungen, geübt mit aktivem Zuhören","character":"Lena, Studentin vor der Prüfung","avatar":"📐","context":"Lena, eine Kommilitonin, sitzt Tage vor der Statistik-Klausur blass in der Bibliothek. Ihre Lernmappe ist kaum angerührt. Sie sagt, sie sei „eben ein Mathe-Mensch-Gegenteil“, und Lernen bringe bei ihr sowieso nichts.","goal":"Höre Lena aktiv zu, finde heraus, woher ihre Überzeugung kommt, und mache ihr den Kreislauf aus niedriger Erwartung und weniger Übung sichtbar, ohne sie zu belehren.","bereich":"Ich selbst","laenge":"mittel","ton":"ernst","bestehenAb":6,"lektion":"Ein „Ich bin halt so“ ist oft ein Kreislauf: Wer wenig erwartet, übt weniger, scheitert eher und fühlt sich bestätigt. Erwartungen wirken auch nach innen (das nennt man Galatea-Effekt): Wer sich eine Aufgabe zutraut, investiert mehr Ausdauer. Sie können Leistung beeinflussen, ohne sie zu garantieren. Aktives Zuhören mit Paraphrasieren, Gefühle benennen und offenen Fragen macht diesen Kreislauf erst sichtbar, und Lena erkennt ihn dann oft selbst.","toolRef":"H.2.3","faktenRef":"E.3.4","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Lena","speech":"„Ich lerne gar nicht erst für Statistik. Ich bin einfach ein Mensch, der Mathe nie versteht. Das war schon in der Schule so, und daran ändert auch Lernen nichts. Ich schau mir die Aufgaben gar nicht mehr an.“","options":[{"text":"„Das ist Quatsch, Lena. Niemand ist ‚kein Mathe-Mensch‘. Du musst einfach nur anfangen und dich hinsetzen, dann klappt das schon.“","style":"frontal","reaction":"„Du verstehst das nicht. Du hast leicht reden. Ich habe es ja versucht! Lass mich einfach in Ruhe, okay?“ *klappt den Laptop halb zu*","feedback":"Zu schnell widersprochen, ohne zuzuhören. Lena hört: „Du übertreibst.“ Passives Hören sendet nur, statt zu verstehen, und sie macht dicht.","score":-2,"nextStepId":"step-fail"},{"text":"„Klingt, als würdest du schon länger mit diesem Gefühl kämpfen. Wenn ich dich richtig verstehe, glaubst du, dass Lernen bei dir nichts bringt. Wie ist das denn damals in der Schule gewesen?“","style":"deeskalierend","reaction":"„*zögert* Ja... genau so. In der Schule hatte ich eine Lehrerin, die schon in der Siebten gesagt hat, ich solle mir keine Hoffnungen machen. Danach hab ich irgendwie aufgehört.“","feedback":"Stark! Du paraphrasierst, benennst das Gefühl und stellst eine offene Frage. Lena öffnet sich und nennt eine Quelle ihrer Überzeugung.","score":3,"nextStepId":"step-2"},{"text":"„Ach, ich bin auch total schlecht in Mathe! Ich hab letztes Semester kaum bestanden. Ist doch nicht schlimm, dafür sind wir in anderen Sachen besser.“","style":"humorvoll","reaction":"„Ja, stimmt wohl... dann ist es ja eigentlich egal, ob ich lerne, oder? Dann lass ich es halt.“","feedback":"Gut gemeint, aber du bestätigst ihre Selbstbeschreibung und hörst nicht zu. Das verstärkt die niedrige Erwartung, statt sie zu prüfen.","score":-1,"nextStepId":"step-struggle"}]},"step-2":{"id":"step-2","speaker":"Lena","speech":"„Seitdem hab ich gedacht: Okay, dann bin ich eben nicht dafür gemacht. Wenn ich was nicht verstehe, merke ich: Siehst du, ich hab's gewusst. Das ist wie ein Beweis. Und dann lerne ich noch weniger.“","options":[{"text":"„Moment. Dann ist das Problem gar nicht dein Kopf, sondern ein Muster. Du lernst wenig, verstehst weniger und denkst: ‚Siehst du, ich bin eben schlecht.‘ Das ist wie ein Teufelskreis.“","style":"frontal","reaction":"„Hm. Teufelskreis... *schnaubt* Das klingt, als wäre ich selbst schuld an allem.“","feedback":"Der Gedanke ist richtig, aber du lieferst die Deutung fertig und etwas anklagend. Besser wäre, Lena das Muster selbst beschreiben zu lassen (klärende Fragen).","score":0,"nextStepId":"step-3-struggle"},{"text":"„Das klingt anstrengend, so ein Beweis, der sich immer wieder bestätigt. Magst du mir erzählen, wie viele Aufgaben du vor dem letzten Fehlschlag wirklich durchgerechnet hast?“","style":"sokratisch","reaction":"„*überlegt* Ehrlich? Kaum welche. Vielleicht zwei, drei. Dann hab ich schon aufgegeben, weil ich dachte, es bringt eh nichts. Hmm...“","feedback":"Treffer! Eine offene, neugierige Frage lässt Lena selbst merken, dass die Beweislage dünn ist. Der Kreislauf aus Erwartung, Aufgeben und Bestätigung wird sichtbar, ohne dass du ihn benennen musstest.","score":3,"nextStepId":"step-3-success"},{"text":"„Ich kenne das. Als ich in Französisch durchgefallen bin, war ich auch monatelang überzeugt, ich hätte kein Sprachtalent. Weißt du, was bei mir geholfen hat? Ich hab...“","style":"affektiv","reaction":"„*unterbricht* Mhm. Ja. Aber bei mir ist das ja was anderes... Ich glaube, ich geh mal Kaffee holen.“","feedback":"Eigene Geschichte statt Zuhören: Du lenkst das Gespräch auf dich (Red Flag in). Lena zieht sich zurück, obwohl sie sich gerade geöffnet hat.","score":-1,"nextStepId":"step-3-struggle"}]},"step-3-success":{"id":"step-3-success","speaker":"Lena","speech":"„Wow. Ich glaube, ich habe mich nie wirklich getestet. Ich war mir so sicher, dass es nichts bringt, dass ich es gar nicht richtig probiert habe. Aber was mache ich jetzt, die Klausur ist ja schon in ein paar Tagen?“","options":[{"text":"„Möchtest du ein Rezept, oder erst mal sortieren? Mein Vorschlag: Nimm dir heute nur eine Aufgabe vor und schau, wie weit du kommst. Ich setz mich dazu, wenn du magst.“","style":"deeskalierend","reaction":"„*lächelt vorsichtig* Eine Aufgabe schaffe ich. Okay. Danke, dass du mir nicht gleich gesagt hast, was ich alles falsch mache. Ich glaub, das hilft mir gerade echt.“","feedback":"Rundum gelungen: Du fragst nach, was Lena braucht, setzt auf einen kleinen, realistischen Schritt und bleibst an ihrer Seite. So wächst Zutrauen (Erwartungen können Leistung beeinflussen), ohne dass du Wunder versprichst.","score":3},{"text":"„Du schaffst das locker, Lena! Du bestehst die Klausur ganz sicher mit einer Eins, ich glaube fest an dich, und Statistik ist am Ende gar nicht so schwer!“","style":"affektiv","reaction":"„*skeptisch* Eine Eins? Du übertreibst. Ich sollte erst mal verstehen, was ein p-Wert ist...“","feedback":"Gut gemeint, aber überzogen: Positive Erwartungen sind meist nützlich, solange sie realistisch bleiben. Ein Versprechen wie „Eins“ klingt hohl und kann Lena unter Druck setzen.","score":0},{"text":"„Dann nimm dir doch einfach mal vor, jeden Tag drei Stunden zu lernen, bis zur Klausur. Das schaffst du locker, du musst es nur wirklich wollen und durchziehen.“","style":"frontal","reaction":"„Drei Stunden jeden Tag?! Das schaffe ich nie. Ich hab's ja gewusst...“ *lässt die Schultern sinken*","feedback":"Ein großer Plan, der von Lenas eigenen Bedürfnissen nicht ausgeht. Ohne zu fragen, was sie braucht, droht der nächste Frust, und die alte Erwartung bestätigt sich.","score":-1}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Lena","speech":"„Ich weiß nicht... Ich glaub, ich bin einfach zu müde für das alles. Vielleicht ist es das Beste, ich lasse die Klausur diesmal sausen.“","options":[{"text":"„Das klingt, als wärst du gerade ziemlich erschöpft und entmutigt. Ich nehme das ernst, und du musst heute nichts entscheiden. Magst du erzählen, was dich am meisten drückt?“","style":"deeskalierend","reaction":"„*atmet durch* Ja... Ich habe einfach Angst, wieder zu scheitern. Aber danke, dass du fragst. Ich glaube, ich brauche erst mal Schlaf und dann sehen wir weiter.“","feedback":"Gute Rettung: Du benennst das Gefühl und fragst offen nach. Die Sachfrage bleibt offen, aber Lena fühlt sich gehört, und das Gespräch bleibt tragfähig.","score":2},{"text":"„Wenn du jetzt aufgibst, bestätigst du ja genau, was du über dich denkst. Reiß dich zusammen, andere schaffen das auch, und du hast schon mehr geschafft als sie.“","style":"sarkastisch","reaction":"„Wow, danke fürs Mutmachen. Ich muss jetzt gehen.“ *packt hastig ihre Sachen*","feedback":"Die Beobachtung stimmt, aber als Vorwurf verpackt wirkt sie wie ein Angriff. Seziert wird die Behauptung, nicht der Mensch, und Zuhören fehlt völlig.","score":-2,"nextStepId":"step-fail"},{"text":"„Okay, verstehe ich. Dann lass es eben diesmal. Das Leben geht auch ohne bestandene Statistik weiter, und es gibt ja noch einen zweiten Versuch.“","style":"ausstieg","reaction":"„Ja... vermutlich. Danke, dass du mich nicht drängst. Ich schau mal, wie ich mich später fühle.“","feedback":"Respektvoll, aber du gibst die Gelegenheit ab, Lenas Muster überhaupt anzusprechen. Der Kreislauf bleibt unberührt.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Lena","speech":"„Ich sag ja: Es bringt nichts. Nicht mal mit dir kann man darüber reden.“ *schiebt die Mappe in die Tasche und geht*","options":[{"text":"Ende: Lena fühlte sich nicht gehört und sieht ihre Überzeugung bestätigt. Wer nicht zuhört, bestätigt oft unabsichtlich die Mauer, die er einreißen wollte.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst paraphrasieren und das Gefühl benennen, dann offen nachfragen.","feedback":"Frage dich: Habe ich zugehört, um zu verstehen, oder um zu antworten? Aktives Zuhören ist die Voraussetzung, damit der Erwartungs-Kreislauf überhaupt sichtbar wird.","score":0}]},"step-struggle":{"id":"step-struggle","speaker":"Lena","speech":"„Eben. Wenn selbst du sagst, dass Mathe einfach nicht für jeden ist, dann mach ich mir das Leben nicht unnötig schwer. Die Klausur schiebe ich einfach.“","options":[{"text":"„Moment, das habe ich schlecht ausgedrückt. Lass mich noch mal nachfragen: Was genau war es, das dich damals in der Schule so entmutigt hat?“","style":"deeskalierend","reaction":"„*zögert* Okay... also, da war diese Lehrerin, die meinte schon in der Siebten, ich solle mir keine Hoffnungen machen. Seitdem denke ich das irgendwie auch.“","feedback":"Gute Korrektur: Du erkennst den Fehler an und kehrst zum Zuhören zurück. Lena öffnet sich doch noch und nennt die Quelle ihrer Erwartung.","score":2,"nextStepId":"step-2"},{"text":"„Genau, du hast recht. Spar dir die Energie. Das Wichtigste ist, dass man sich nicht stresst.“","style":"humorvoll","reaction":"„Eben. Danke. Dann hab ich das ja auch geklärt.“ *packt die Mappe weg, ohne sie angesehen zu haben*","feedback":"Du bestätigst die niedrige Erwartung, und damit wächst die Wahrscheinlichkeit, dass sie sich selbst erfüllt. Ohne Zuhören bleibt der Kreislauf unberührt.","score":-2,"nextStepId":"step-fail"},{"text":"„Ehrlich gesagt klingt das, als würdest du dir da ziemlich wenig zutrauen. Seit wann glaubst du das eigentlich über dich?“","style":"sokratisch","reaction":"„Seit der Siebten, glaube ich. Da hat eine Lehrerin gesagt, ich solle mir keine Hoffnungen machen. Danach hat Mathe irgendwie nicht mehr funktioniert.“","feedback":"Die offene Frage bringt Lena auf die Spur ihrer Überzeugung. Der Einstieg „ziemlich wenig zutrauen“ klingt aber leicht wertend; besser wäre es, zuerst ihr Gefühl zu benennen.","score":1,"nextStepId":"step-2"}]}},"status":"entwurf","familie":"erwartung-erfuellt-sich","fertigkeit":"F2","stufe":3,"kurz":"Ein „Ich bin halt so“ ist oft ein Kreislauf: Wer wenig erwartet, übt weniger, scheitert eher und fühlt sich bestätigt. Erwartungen können Leistung beeinflussen, ohne sie zu garantieren. Zuhören und offene Fragen machen den Kreislauf sichtbar.","prueffrage":"Wie viele Aufgaben wurden vor dem Urteil „Ich verstehe Mathe nie“ tatsächlich durchgerechnet?","quellen":[{"typ":"doi","kurz":"Leung, A.; Sy, T. (2018): „I Am as Incompetent as the Prototypical Group Member: An Investigation of Naturally Occurring Golem Effects in Work Groups“. Frontiers in Psychology 9","oeffentlich":true,"doi":"10.3389/fpsyg.2018.01581","abruf":"2026-10-12"},{"typ":"doi","kurz":"Jussim, L.; Harber, K. D. (2005): „Teacher Expectations and Self-Fulfilling Prophecies: Knowns and Unknowns, Resolved and Unresolved Controversies“. Personality and Social Psychology Review 9(2), S. 131–155 (nach Landkarte-Fn. gl-e-rosenthal)","oeffentlich":false,"doi":"10.1207/s15327957pspr0902_3"},{"typ":"literatur","kurz":"Zimbardo, P. G.; Gerrig, R. J. (2008): Psychologie. München: Pearson Studium (Selbstwirksamkeit nach Bandura; nach Landkarte-Fn. gl-e-selbstwirksamkeit)","oeffentlich":false}],"thema":"Zusammenleben"},{"id":"scen-chef-sunk-cost","title":"Chef Rainers Prestigeprojekt","subtitle":"Versunkene Kosten, geübt mit der Ausstiegs-Strategie","character":"Rainer, Abteilungsleiter","avatar":"📊","context":"Dein Abteilungsleiter Rainer hat vor zwei Jahren eine neue Planungssoftware eingeführt. Sie läuft schlecht, kaum jemand im Team nutzt sie gern, und die nächste Rate steht an. In der Teambesprechung gibt es nun die Frage: weitermachen oder stoppen? Rainer steht stark unter Druck und hält am Projekt fest.","goal":"Bring Rainer dazu, die Entscheidung an den künftigen Kosten und dem künftigen Nutzen auszurichten statt am bereits ausgegebenen Geld, ohne dass er sein Gesicht verliert.","bereich":"Arbeit","laenge":"lang","ton":"ernst","bestehenAb":9,"lektion":"Bereits ausgegebenes Geld ist weg, egal ob das Projekt weiterläuft oder nicht. Entscheidend ist allein die Frage, was die nächsten Monate kosten und was sie bringen. Mit dem Null-Basis-Check und einer ruhigen, sokratischen Gesprächsführung öffnest du Rainer eine Tür, ohne ihn bloßzustellen. Und wenn das Gespräch sich nur noch in Schleifen dreht und keine Frage mehr ankommt, ist ein ruhiger Ausstieg besser als die Verschwendung deiner Energie. Hier war Rainer aber ansprechbar, deshalb war ein Ausstieg verfrüht.","toolRef":"H.2.4","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Rainer","speech":"„Ich weiß, die Software hakt noch. Aber wir haben schon zwei Millionen in dieses Projekt gesteckt! Wenn wir jetzt aufhören, war alles umsonst. Das kann ich der Geschäftsführung nicht erklären. Wir machen weiter, Punkt.“","options":[{"text":"„Rainer, das ist die klassische Versunkene-Kosten-Falle. Zwei Millionen sind weg, das ist ein Denkfehler. Mit dieser Logik versenkst du noch mehr Geld.“","style":"frontal","reaction":"„Ach, jetzt bin ich also auch noch dumm? Ich habe dieses Projekt gegen Widerstand durchgesetzt, und du erklärst mir hier Denkfehler?“ *verschränkt die Arme*","feedback":"Fachlich stimmt es, aber du attackierst Rainers Entscheidung und seine Person gleichzeitig. Wer sich angegriffen fühlt, verteidigt sich, statt nachzudenken. Ein Etikett wie „Falle“ bringt kein Gespräch in Gang.","score":-2,"nextStepId":"step-defensive"},{"text":"„Das klingt nach viel Druck, und zwei Millionen sind ein echtes Gewicht. Darf ich eine Frage stellen: Was würde das Projekt in den nächsten zwölf Monaten kosten, und was würde es uns konkret bringen?“","style":"sokratisch","reaction":"„Hm. Die genauen Zahlen für das nächste Jahr habe ich nicht im Kopf. Kosten wären wohl noch einmal rund eine halbe Million, und der Nutzen... ja, der soll ja kommen, sobald die Probleme behoben sind.“","feedback":"Stark! Du nimmst den Druck ernst und lenkst mit einer offenen Frage den Blick von der Vergangenheit auf Kosten und Nutzen der Zukunft, genau das, was die Versunkene-Kosten-Falle verdrängt.","score":3,"nextStepId":"step-2"},{"text":"„Wenn du meinst, Rainer. Du siehst ja das große Bild. Ich kümmere mich einfach um meine Aufgaben und halte mich aus der Entscheidung raus.“","style":"ausstieg","reaction":"„Gut, dann ist das ja geklärt. Ich schreibe die Verlängerung heute noch an die Geschäftsführung.“","feedback":"Der Rückzug ist hier verfrüht. Das Gespräch war noch gar nicht unehrlich oder erschöpft. Mit dem Ausstieg wartest du besser, bis wirklich nichts mehr geht, sonst bleibt die Falle unangetastet.","score":-1,"nextStepId":"step-fail"}]},"step-defensive":{"id":"step-defensive","speaker":"Rainer","speech":"„Ich habe zwei Jahre meines Berufslebens in dieses Projekt gesteckt, Nächte, Wochenenden, Überzeugungsarbeit. Das werfe ich nicht weg, nur weil jemand am Tisch schlaue Begriffe kennt.“","options":[{"text":"„Das merke ich, Rainer, und ich bestreite die Arbeit nicht. Ich will nur verstehen: Was müsste in den nächsten Monaten passieren, damit sich das Weitermachen für dich eindeutig lohnt?“","style":"deeskalierend","reaction":"„*atmet durch* Na ja... wenn die Fehlerquote sinken würde und das Team die Software wirklich nutzt. Aber ob das klappt, weiß ich noch nicht.“","feedback":"Gute Reparatur! Du nimmst seinen Einsatz ernst, ohne die Sachlage zu bestätigen, und verschiebst das Thema von „umsonst oder nicht“ auf überprüfbare Kriterien in der Zukunft.","score":3,"nextStepId":"step-3"},{"text":"„Ach komm, Rainer, genau diese Nächte und Wochenenden sind doch das Problem. Wer so viel investiert hat, will einfach nicht zugeben, dass es ein Fehler war, das kennt man.“","style":"sarkastisch","reaction":"„Das reicht jetzt! Ich lasse mir nicht von dir erklären, was ich zugeben soll. Dieses Gespräch ist beendet.“ *steht auf*","feedback":"Du triffst zwar den psychologischen Mechanismus (Kognitive Dissonanz), aber als Unterstellung und Spott. So wird aus „Seziert wird die Behauptung, nicht der Mensch“ ein Angriff auf Rainer.","score":-2,"nextStepId":"step-fail"},{"text":"„Du hast recht, tut mir leid. Das Projekt ist wichtig, und wenn du es für richtig hältst, ist das sicher gut so. Lass uns das nicht weiter vertiefen, ich will dir nichts aufdrängen.“","style":"ausstieg","reaction":"„Danke. Aber ehrlich gesagt lässt mich das Thema selbst nicht los. So einfach ist das nicht.“","feedback":"Du entschärfst den Streit, indem du die Sache fallen lässt. Rainer fühlt sich bestätigt, die Falle bleibt unberührt. Beziehung gerettet, Anliegen aufgegeben. Ganz zur Ruhe kommt Rainer damit aber nicht, das Thema bleibt offen.","score":0,"nextStepId":"step-3"}]},"step-2":{"id":"step-2","speaker":"Rainer","speech":"„Ehrlich gesagt hat das Team die Software bisher kaum angenommen. Aber stell dir vor, wir stoppen jetzt: Zwei Millionen einfach abgeschrieben, das sähe doch aus, als hätte ich die Firma verbrannt.“","options":[{"text":"„Dieses Gefühl kann ich nachvollziehen. Aber das Geld ist so oder so ausgegeben. Die Frage ist nur, ob wir noch eine halbe Million nachlegen. Würdest du das Projekt in diesem Zustand heute neu starten?“","style":"sokratisch","reaction":"„*zögert* Wenn mir das heute jemand so anböte, mit einer Software, die keiner mag, und einer halben Million Zusatzkosten... ehrlich gesagt, ich würde nein sagen.“","feedback":"Meisterhaft! Du trennst die bereits ausgegebene Summe sauber von der Zukunftsentscheidung und nutzt den Null-Basis-Check. Rainer entdeckt selbst, dass er heute nicht einsteigen würde.","score":3,"nextStepId":"step-3-success"},{"text":"„Viele Projekte kippen eben erst spät. Wir geben dem Ganzen noch ein halbes Jahr und schauen dann nochmal, einverstanden? Mit etwas Geduld dreht sich das Blatt oft von selbst.“","style":"humorvoll","reaction":"„Ein halbes Jahr, gut. Dann haben wir ein Polster, und bis dahin hat sich das vielleicht von selbst gelöst.“","feedback":"Ein Aufschub sieht nach Kompromiss aus, ist aber bequem: Ohne klare Kriterien wird jede Verlängerung zu einem weiteren Investment, das den Ausstieg schwerer macht. Die Hoffnung, dass sich das Problem von selbst löst, ist eine Red Flag der Falle.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Rainer, die zwei Millionen sind sowieso weg. Alles andere ist Selbstbetrug. Wer jetzt weitermacht, wirft schlechtem Geld gutes hinterher, und das weißt du auch ganz genau.“","style":"frontal","reaction":"„Selbstbetrug? Ich werfe überhaupt nichts hinterher! Du siehst nur die Zahlen, aber nicht, was dieses Projekt für die Firma bedeutet!“","feedback":"Der Sachkern stimmt, aber „Selbstbetrug“ ist ein Vorwurf an die Person. Rainer geht auf Abwehr und verteidigt seine Entscheidung (Kognitive Dissonanz) statt sie neu zu bewerten.","score":-2,"nextStepId":"step-fail"}]},"step-3":{"id":"step-3","speaker":"Rainer","speech":"„Aber so einfach ist das nicht. Wenn ich jetzt abbreche, heißt es: Rainer hat zwei Millionen in den Sand gesetzt. Und wenn ich weitermache und es doch klappt, bin ich der, der durchgehalten hat. Das ist doch auch was wert.“","options":[{"text":"„Durchhalten ist wertvoll, da hast du recht. Es heißt aber, weiterzumachen, solange es Aussicht auf Erfolg gibt. Gibt es konkrete Anzeichen, dass sich das Blatt wendet, außer der Hoffnung?“","style":"sokratisch","reaction":"„*schweigt kurz* Ehrlich? Außer meiner Hoffnung eigentlich nicht. Die Fehlerquote ist seit Monaten gleich geblieben.“","feedback":"Sehr gut! Du würdigst die nützliche Seite von Ausdauer und markierst den Kipppunkt zur Sturheit, nämlich wenn neue, negative Informationen ignoriert werden. Die Frage nach Anzeichen führt Rainer selbst zur Einsicht.","score":3,"nextStepId":"step-4-success"},{"text":"„Klar, und wenn es doch klappt, bist du der Held. Das Risiko trägt ja ohnehin die Firma, nicht du. Und wenn es schiefgeht, war es eben die Strategie der Geschäftsführung.“","style":"sarkastisch","reaction":"„Das ist jetzt unter der Gürtellinie. Ich trage sehr wohl die Verantwortung für diese Abteilung.“","feedback":"Der Spott trifft Rainers Motive statt die Entscheidung und verhärtet die Fronten. Ein sarkastischer Seitenhieb löst keinen Denkprozess aus.","score":-2,"nextStepId":"step-3-struggle"},{"text":"„Wenn das so ist, scheint der Zug für dich ja entschieden. Ich habe nicht vor, mich weiter mit dir darüber zu streiten, und ich will auch nicht in der Verantwortung stehen.“","style":"ausstieg","reaction":"„Gut. Dann sind wir uns einig, dass wir weitermachen.“","feedback":"Der Ausstieg ist für wirklich unehrliche, erschöpfende Debatten gedacht. Rainer argumentiert hier aber durchaus ansprechbar, du gibst zu früh auf.","score":-1,"nextStepId":"step-fail"}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Rainer","speech":"„Ich verstehe, was du sagen willst. Aber ich habe ein schlechtes Gefühl, wenn ich nur an Ausstieg denke. Ich weiß nicht, ob ich das schaffe. Mir schwirrt der Kopf bei dem Thema.“","options":[{"text":"„Das ist verständlich, das Thema ist schwer. Wie wäre es mit einer Liste: links, was schon bezahlt ist, rechts, was die nächsten zwölf Monate kosten und bringen? Entscheiden wir nur nach der rechten Spalte?“","style":"sokratisch","reaction":"„Eine Liste... na gut, das kann ich machen. Ich schaue mir das am Wochenende in Ruhe an.“","feedback":"Gute Landung! Die Zwei-Spalten-Übung gibt Rainer ein Werkzeug an die Hand und lässt ihm Zeit, ohne Gesichtsverlust zu entscheiden. Die Tür bleibt offen.","score":2},{"text":"„Du hast ja bald die Besprechung mit der Geschäftsführung. Dort wirst du merken, wie das ankommt. Ich halte mich hier raus, das ist am Ende deine Entscheidung und deine Verantwortung.“","style":"ausstieg","reaction":"„Gut. Dann sehen wir es dort.“","feedback":"Du lässt Rainer allein mit seinem Druck und der Falle, ohne Alternative anzubieten. Der Rückzug schützt dich, hilft aber niemandem weiter.","score":0},{"text":"„Rainer, jetzt reiß dich zusammen. Du bist Abteilungsleiter, da muss man auch unbequeme Entscheidungen treffen können! Ein Chef, der ständig zweifelt, ist keiner.“","style":"frontal","reaction":"„Du hast keine Ahnung, was auf mir lastet. Das war's für heute.“ *geht*","feedback":"Ein Appell an Härte setzt Rainer unter noch mehr Druck. Wer seine Entscheidung verteidigen muss, sucht keine Alternativen, er sucht Abwehr.","score":-2}]},"step-3-success":{"id":"step-3-success","speaker":"Rainer","speech":"„Wenn ich ehrlich bin, würde ich heute nicht einsteigen. Aber wie erkläre ich der Geschäftsführung, dass wir nach zwei Millionen aufhören?“","options":[{"text":"„Du erklärst, dass du nach künftigen Kosten und künftigem Nutzen entscheidest. Das ist keine Niederlage, das ist professionell. Wenn du magst, rechnen wir die nächsten zwölf Monate zusammen durch.“","style":"deeskalierend","reaction":"„*nickt langsam* So habe ich das noch nicht gesehen. Gut, ich lasse das Projekt auslaufen und stelle euch die Zahlen vor.“","feedback":"Erfolg! Du hast Rainer geholfen, ohne Gesichtsverlust aus der Falle zu kommen. Der Null-Basis-Check hat den Perspektivwechsel möglich gemacht.","score":3},{"text":"„Das ist dein Problem, Rainer. Du hast dir die Suppe eingebrockt, jetzt musst du sie auch auslöffeln. Ich hatte dich ja früh genug gewarnt, aber du wolltest nicht hören.“","style":"sarkastisch","reaction":"„Danke für die Unterstützung... Ich überlege mir das allein.“","feedback":"Rainer war einsichtig, und du lässt ihn mit Häme allein. Das trifft den Menschen statt der Sache. Hilfreiche Begleitung statt Spott hätte den Durchbruch gesichert.","score":-2},{"text":"„Sag einfach, es war ein Fehler von Anfang an, dann hast du es hinter dir. Alles andere klingt nach Ausreden, und die Geschäftsführung merkt das sofort.“","style":"frontal","reaction":"„Das kann ich nicht sagen. Das wäre das Ende meiner Karriere.“","feedback":"Ein pauschales Eingeständnis überfordert Rainer. Es geht nicht um „Fehler von Anfang an“, sondern darum, heute anhand der Zukunft zu entscheiden.","score":-1}]},"step-4-success":{"id":"step-4-success","speaker":"Rainer","speech":"„Also, wenn außer meiner Hoffnung nichts dafür spricht, dann lohnt sich die halbe Million nicht. Aber ich will der Geschäftsführung nicht sagen, wir stoppen einfach so.“","options":[{"text":"„Du sagst nicht „einfach so“. Du sagst: Wir haben geprüft, die Zahlen der nächsten zwölf Monate sprechen dagegen, und wir investieren das Geld lieber in etwas, das mehr bringt.“","style":"deeskalierend","reaction":"„Ja... so lässt sich das vertreten. Ich bereite das vor. Danke, dass du nicht einfach nur dagegen warst, sondern mir geholfen hast, es selbst zu sehen.“","feedback":"Volltreffer! Du gibst Rainer eine gesichtswahrende Formulierung und stärkst die Zukunftsorientierung. Genau so entschärft man die Versunkene-Kosten-Falle.","score":3},{"text":"„Wenn es dir peinlich ist, sag doch einfach, ich war es, der Zweifel hatte. Dann hast du jemanden, auf den du zeigen kannst, und ich nehme das gern auf mich.“","style":"humorvoll","reaction":"„Nein, das wäre unfair. Aber danke für das Angebot.“","feedback":"Nett gemeint, aber du verschiebst die Verantwortung, statt Rainer eine tragfähige Begründung zu geben. Die Falle löst sich, wenn die Entscheidung auf Zukunftsdaten beruht, nicht auf einem Sündenbock.","score":1},{"text":"„Dann lass es einfach laufen, bis sich jemand anderes beschwert. Dann bist du nicht schuld, und alle anderen müssen sich selbst darum kümmern.“","style":"ausstieg","reaction":"„Gut, dann verlängern wir erst einmal.“","feedback":"Wer die Entscheidung aufschiebt, bis jemand anders sie trifft, füttert die Falle weiter. Jeder zusätzliche Monat ist ein neues Investment, das den Ausstieg erschwert.","score":-2}]},"step-fail":{"id":"step-fail","speaker":"Rainer","speech":"„Ich habe entschieden: Wir machen weiter, so wie geplant. Das Thema ist für mich erledigt.“ *wendet sich ab*","options":[{"text":"Ende: Rainer hat sich nicht gehört gefühlt, und die Falle ist fester als vorher. Rechthaben und überzeugen sind zweierlei.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst Rainers Druck ernst nehmen, dann mit einer ruhigen Frage nach künftigen Kosten und Nutzen ansetzen.","feedback":"Die Versunkene-Kosten-Falle lässt sich nur lösen, wenn die Person ihr Gesicht wahren kann. Der Null-Basis-Check funktioniert als Frage, nicht als Urteil.","score":0}]}},"faktenRef":"B.6","status":"entwurf","familie":"versunkene-kosten","fertigkeit":"F4","stufe":3,"kurz":"Bereits ausgegebenes Geld ist weg, ob das Projekt weiterläuft oder nicht; entscheidend ist, was die nächsten Monate kosten und bringen. Ruhige Fragen öffnen dafür eine Tür, ohne jemanden bloßzustellen. Ein Ausstieg aus dem Gespräch lohnt erst, wenn keine Frage mehr ankommt.","prueffrage":"Welche der genannten Zahlen betreffen die kommenden zwölf Monate, und welche betreffen nur Geld, das schon ausgegeben ist?","quellen":[{"typ":"doi","kurz":"Petrov, N. B. u. a. (2023): „Sunk Cost Effects for Time Versus Money: Replication and Extensions Registered Report of Soman (2001)“. International Review of Social Psychology 36(1), Art. 17 (CC BY 4.0)","oeffentlich":true,"doi":"10.5334/irsp.883","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Arkes, H. R.; Blumer, C. (1985): „The Psychology of Sunk Cost“. Organizational Behavior and Human Decision Processes 35(1), S. 124–140 (nach Landkarte-Fn. gl-b-sunk-cost)","oeffentlich":false}],"thema":"Zusammenleben"},{"id":"scen-pyramiden-marek","title":"Marek und die Pyramidenbauer","subtitle":"Prä-Astronautik, geübt mit intellektueller Barmherzigkeit","character":"Marek, Kumpel vom Fußball","avatar":"🛸","context":"Nach dem Training sitzt ihr mit einem Bier in der Kabine. Dein Kumpel Marek hat gestern wieder eine Doku über die Pyramiden geschaut und ist begeistert: Das hätten Menschen damals niemals ohne Hilfe von außerirdischen Besuchern hinbekommen. Die anderen Jungs grinsen schon.","goal":"Bleib freundlich und wertschätzend, finde heraus, welche Faszination hinter Mareks Idee steckt, und bring ihn mit Fragen dazu, selbst zu überlegen, ob frühere Menschen wirklich weniger fähig waren als wir.","bereich":"Freunde","laenge":"mittel","ton":"heiter","bestehenAb":6,"lektion":"Wer sagt „Das konnten die nie allein“, schließt oft vom eigenen Nicht-Vorstellen-Können auf die Fähigkeiten anderer. „Das Prinzip der menschlichen Genialität“ rät, andere als kluge Akteure anzunehmen, die in ihrem Rahmen sinnvoll handeln. Wer Marek zuerst für seine Neugier würdigt, kommt mit ihm ins Gespräch, statt ihn als Idioten abzustempeln. Seziert wird die Behauptung, nicht der Mensch.","toolRef":"H.1.3","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Marek","speech":"„Ey, ich sag's dir: Diese Pyramiden! Riesige Steinblöcke, präzise geschichtet, und das ohne Maschinen? Das haben Außerirdische gebaut, sonst kann das gar nicht gehen! Die Leute damals waren doch viel zu primitiv dafür!“","options":[{"text":"„Marek, das ist völliger Quatsch. Die Menschen damals waren nicht primitiv, du schaust zu viele Dokus mit Verschwörungs-Soundtrack. Außerirdische, ernsthaft?“","style":"frontal","reaction":"„Ach komm, jetzt hältst du mich für einen Spinner! Immer müsst ihr alle gleich auf Leute losgehen, die mal was hinterfragen!“ *verschränkt die Arme*","feedback":"Frontalangriff: Der Inhalt stimmt, aber du schiebst Marek in die Spinner-Ecke. Seine Gründe interessieren dich nicht, also verteidigt er seine Idee nur noch trotziger.","score":-2,"nextStepId":"step-fail"},{"text":"„Haha, ja klar, und die Sphinx hat bestimmt auch ein Raumschiff-Parkdeck. Marek, hast du auch gesehen, wo die Ufos damals gewartet wurden?“","style":"sarkastisch","reaction":"„Lacht ihr ruhig. Ich weiß schon, dass ihr dann nichts erklären könnt. Typisch.“ *die Jungs lachen, Marek schweigt beleidigt*","feedback":"Spott gewinnt Lacher, aber keinen Zugang. Marek fühlt sich vorgeführt, und wer sich verspottet fühlt, hört nicht mehr zu. Das ist das Gegenteil von „Das Prinzip der intellektuellen Barmherzigkeit“.","score":-1,"nextStepId":"step-sarcasm"},{"text":"„Du bist richtig fasziniert von dem Ding, oder? Ich find's auch unfassbar, wie gigantisch das ist. Was hat dich an der Doku am meisten beeindruckt?“","style":"deeskalierend","reaction":"„Boah, endlich einer, der zuhört! Ich fand's krass, dass die Blöcke so genau passen. Da würde ich heute mit Kran und Laser schon schwitzen. Wie sollen die das damals gemacht haben?“","feedback":"Sehr gut: Du setzt bei der guten Motivation an, der echten Faszination und Neugier, und greifst die Idee noch nicht an. Marek öffnet sich und stellt selbst die Frage, die ihr gemeinsam untersuchen könnt.","score":3,"nextStepId":"step-2"}]},"step-2":{"id":"step-2","speaker":"Marek","speech":"„Genau, das ist es ja! Wenn ich mir vorstelle, dass die das ohne Kran und ohne Lasermessung gemacht haben sollen, kann ich mir das einfach nicht vorstellen. Und was ich mir nicht vorstellen kann, geht eben nicht. Also muss jemand geholfen haben.“","options":[{"text":"„Marek, nur weil du dir das nicht vorstellen kannst, heißt das noch lange nichts. Das ist ein klassischer Fehlschluss: Argument aus Unwissen.“","style":"frontal","reaction":"„Fehlschluss, aha. Jetzt kommst du mir mit Fachbegriffen, um mich klein zu kriegen. Dann erklär mir doch mal, wie sie es gemacht haben, Herr Professor!“","feedback":"Du hast einen Punkt, aber als Belehrung verpackt. Du lieferst ein Etikett, statt Mareks Gedanken zu folgen, und er reagiert mit Gegenwehr (Verachtung und Spott führen zu einem defensiven Kurzschluss).","score":0,"nextStepId":"step-3-struggle"},{"text":"„Spannend, dass du das so offen sagst. Mal angenommen, die Leute damals waren genauso schlau wie wir, nur eben mit anderem Werkzeug: Was würdest du als Bauchef tun, um so einen Block zu bewegen?“","style":"sokratisch","reaction":"„Hm... als Bauchef? Ich würde wohl ganz viele Leute holen, die ziehen. Und irgendwas, worauf der Block rutschen kann... Moment, so schwer wäre das vielleicht gar nicht, wenn man gut organisiert ist?“","feedback":"Treffer! Du lädst Marek ein, die Perspektive der Erbauer einzunehmen, und schlägst die Denkannahme aus „Das Prinzip der menschlichen Genialität“ vor: Was, wenn die Leute damals genauso klug waren wie wir, nur mit anderen Mitteln? So kommt er selbst auf Lösungen, statt sie vorgesetzt zu bekommen.","score":3,"nextStepId":"step-3-success"},{"text":"„Ja, das ist echt schwer vorzustellen. Vielleicht hast du recht, und ich habe mich einfach nie richtig damit beschäftigt. Wer weiß schon, wie die Dinger wirklich entstanden sind.“","style":"ausstieg","reaction":"„Siehst du, genau! Selbst du bist nicht sicher. Da muss was dran sein! Ich schick dir gleich noch ein Video.“","feedback":"Nett gemeint, aber du bestätigst unbeabsichtigt die Behauptung. Aus „ich kann mir das nicht vorstellen“ wird so „also muss es Außerirdische geben“, obwohl der Schluss nicht trägt.","score":-1,"nextStepId":"step-3-struggle"}]},"step-3-success":{"id":"step-3-success","speaker":"Marek","speech":"„Okay, wenn ich so drüber nachdenke: Die Leute damals waren ja nicht dumm, die hatten bestimmt gute Ideen, weil sie das jahrelang gemacht haben. Aber ich find's trotzdem komisch, dass wir uns so schwertun, das heute nachzuvollziehen. Was meinst du?“","options":[{"text":"„Guter Punkt, und stark, dass du nachbohrst. Uns fehlen wohl die Baupläne, nicht die Intelligenz. Schauen wir mal zusammen, was Forscher dazu herausgefunden haben.“","style":"sokratisch","reaction":"„Ey, das ist gar nicht schlecht. Dann hat vielleicht eher unser Wissen eine Lücke als die Leute damals eine Erfinder-Lücke gehabt. Schick mir, was du findest, dann schauen wir's uns nach dem nächsten Training an!“","feedback":"Mission gelungen: Du würdigst Mareks Neugier, trennst „wir wissen es nicht“ von „es ging nicht“ und bietest gemeinsames Nachschauen an. Das ist intellektuelle Barmherzigkeit in Aktion.","score":3},{"text":"„Du bist heute zum ersten Mal vernünftig, Marek. Hat ja nur eine Doku und drei Bier gebraucht, um dich zu überzeugen. Dass ich das noch erleben darf!“","style":"humorvoll","reaction":"„Haha, sehr witzig. Aber ja, so ganz sicher bin ich mir jetzt nicht mehr. Lass mich drüber nachdenken.“","feedback":"Der Scherz ist gut gemeint, hat aber einen herablassenden Unterton („zum ersten Mal vernünftig“). Er macht Marek klein, statt seinen guten Ansatz zu würdigen und weiterzutragen.","score":0}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Marek","speech":"„Weißt du, ich glaub, wir drehen uns im Kreis. Ich find's einfach merkwürdig, dass die das alleine geschafft haben sollen.“","options":[{"text":"„Fair, das muss heute Abend nicht entschieden werden. Ich find's gut, dass du dich dafür interessierst. Schauen wir ein andermal in Ruhe, wie solche Bauwerke entstanden sein könnten.“","style":"ausstieg","reaction":"„Ja, passt. Ich schick dir den Link zur Doku, dann schaust du's dir an, und wir reden drüber. Aber nur, wenn du auch was findest!“","feedback":"Guter Rückzug: Du wertschätzt Mareks Interesse, lässt die Sachfrage offen und hältst die Beziehung intakt. Die Tür für ein späteres Gespräch bleibt offen.","score":2},{"text":"„Marek, die Menschen damals waren schlauer, als du denkst, und du solltest das auch mal einsehen, anstatt immer auf Außerirdische zu tippen, nur weil dir sonst nichts einfällt.“","style":"frontal","reaction":"„Siehst du, jetzt wirst du wieder belehrend. Ich hab keinen Bock auf so ein Gespräch, wenn du mich eh für blöd hältst.“","feedback":"Die Aussage stimmt, kommt aber als Vorwurf an. Wer sich belehrt fühlt, macht dicht, und das Gespräch endet ohne Ertrag.","score":-1,"nextStepId":"step-fail"}]},"step-sarcasm":{"id":"step-sarcasm","speaker":"Marek","speech":"„Weißt du was, vergiss es. Mit euch kann man über so was eh nicht reden. Dann behalte ich meine Meinung eben für mich.“","options":[{"text":"„Moment, das war jetzt blöd von mir, Marek. Ich wollte dich nicht vorführen. Erzähl doch mal, was dich an der Doku wirklich gepackt hat.“","style":"deeskalierend","reaction":"„*zögert* Na ja... das mit den Blöcken. Aber wenn du ernsthaft zuhören willst, dann erzähl ich's dir gern.“","feedback":"Eine ehrliche Entschuldigung und der Neustart mit echtem Interesse retten das Gespräch. Seziert wird die Behauptung, nicht der Mensch.","score":2},{"text":"„Ach, jetzt sei nicht so empfindlich. War doch nur ein Spaß. Ihr Ufo-Fans nehmt immer alles gleich so ernst.“","style":"sarkastisch","reaction":"„Ja ja, immer lustig. Ich geh mal duschen, bis später.“ *geht*","feedback":"Wer sein Gegenüber auch noch für die Verletzung verantwortlich macht, beendet das Gespräch endgültig. Kein Zugang, kein Austausch.","score":-2,"nextStepId":"step-fail"}]},"step-fail":{"id":"step-fail","speaker":"Marek","speech":"„Okay, dann glaub eben, was du willst. Ich weiß, was ich gesehen habe, und ich lass mir von dir nichts sagen.“ *packt die Tasche und geht*","options":[{"text":"Ende: Marek fühlt sich nicht ernst genommen und klammert sich eher an seine Idee. Rechthaben und Überzeugen sind zweierlei.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst die Neugier und das Staunen würdigen, dann erst über Inhalte reden.","feedback":"Frage dich: Wollte ich Marek überzeugen oder ihn bloßstellen? Intellektuelle Barmherzigkeit beginnt bei der Annahme, dass hinter einer seltsamen Idee ein nachvollziehbares Bedürfnis steckt.","score":0}]}},"faktenRef":"A.13","status":"entwurf","familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","stufe":2,"kurz":"„Das konnten die nie allein“ schließt oft vom eigenen Nicht-Vorstellen-Können auf die Fähigkeiten anderer. Wer frühere Menschen als kluge Akteure mit anderem Werkzeug sieht und die Neugier des Gegenübers würdigt, kommt ins Gespräch. Seziert wird die Behauptung, nicht der Mensch.","prueffrage":"Welcher Beleg für fremde Hilfe wird eigentlich genannt, außer dass man sich den Bau ohne Kran und Laser nicht vorstellen kann?","quellen":[{"typ":"url","kurz":"Weiss, D. (2022): „Journeys of the Pyramid Builders“. Archaeology, Juli/August 2022","oeffentlich":true,"url":"https://archaeology.org/issues/july-august-2022/features/egypt-wadi-el-jarf-port-papyri/","abruf":"2026-10-12"},{"typ":"url","kurz":"Malpas, J.: „Donald Davidson“. Stanford Encyclopedia of Philosophy (überarbeitet 28.04.2023), Abschnitt 3.3 (laut Belegregister geprüft)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","seite":"Abschnitt 3.3"}],"thema":"Geschichte und Wissenschaft"},{"id":"scen-mondlandung-kantine","title":"Rolf und die Mondkulisse","subtitle":"Verschwörungsmythos-Muster, geübt mit dem Management emotionaler Kosten","character":"Rolf, Kollege aus der Logistik","avatar":"🌕","context":"In der Kantine setzt sich Rolf aus der Logistik zu dir und erzählt, die Mondlandung sei in einem Studio gedreht worden. Er hat dazu schon mehrfach Videos in die Teamgruppe geschickt, und jedes Mal hat jemand versucht, ihm zu widersprechen. Gestern ist ein Kollege dabei laut geworden, und die Stimmung ist seitdem angespannt.","goal":"Erkenne die Muster des Mythos, halte das Gespräch ruhig und entscheide bewusst, welche Schlacht du kämpfst und welche nicht.","bereich":"Arbeit","laenge":"lang","ton":"ernst","bestehenAb":9,"lektion":"Ein Mythos, der jeden Gegenbeweis zum Teil der Verschwörung erklärt, ist nicht mehr prüfbar. Das ist ein strukturelles Warnsignal, und wer ihm Faktenschlacht um Faktenschlacht entgegensetzt, verbrennt nur Energie. Das Management emotionaler Kosten heißt, vorher zu fragen, ob es eine Schlacht ist, die man kämpfen muss, die man kämpfen kann oder die man vermeiden sollte, und im Zweifel die Beziehung zu schützen, statt zu gewinnen.","toolRef":"H.1.2","faktenRef":"F.1.3.1","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Rolf","speech":"„Mal ehrlich, hast du dir die Bilder von der Mondlandung schon mal richtig angeschaut? Das war eine Studioaufnahme, das sieht doch jeder, der Augen im Kopf hat. Die Amerikaner haben das 1969 einfach in einer Halle gedreht.“","options":[{"text":"„Rolf, das ist Quatsch, und das weißt du auch. Wer so etwas glaubt, hat sich einfach ins Internet verrannt. Ich diskutiere nicht über Märchen.“","style":"frontal","reaction":"„Aha, da haben wir's: Wer Fragen stellt, ist gleich ein Spinner. Genau so läuft das immer. Dann red ich eben mit Leuten, die zuhören.“ *schiebt das Tablett zur Seite*","feedback":"Frontalangriff auf die Person statt auf die Behauptung. Rolf fühlt sich abgewertet und rückt noch enger mit seiner Erzählung zusammen. Die Frage nach den emotionalen Kosten hast du dir gar nicht erst gestellt.","score":-2,"nextStepId":"step-fail"},{"text":"„Spannend, dass dich das so beschäftigt. Woran machst du das fest? Was ist das Erste, was dir an den Bildern aufgefallen ist?“","style":"sokratisch","reaction":"„*lehnt sich vor* Na, zum Beispiel die Schatten. Die laufen in manchen Aufnahmen nicht parallel. Das gibt's nur, wenn mehrere Scheinwerfer im Studio stehen.“","feedback":"Gute Eröffnung: Du fragst nach dem Grund, statt zu widerlegen. So siehst du, wie Rolf argumentiert, und er fühlt sich ernst genommen. Das ist die Grundlage für die Triage nach „Das Management emotionaler Kosten“: Ist das ein Gespräch, das du kämpfen kannst?","score":3,"nextStepId":"step-2"},{"text":"„Ach Rolf, nicht schon wieder. Lass mich in Ruhe essen, ich hab heute keinen Nerv für deine Videos.“","style":"ausstieg","reaction":"„Siehst du, keiner will drüber reden. Das sagt doch alles. Wenn alles so klar wäre, könnte man es ja einfach erklären.“","feedback":"Ein spontaner Rückzug ohne Absprache. Schonen kann sinnvoll sein, aber hier wirkt es wie Ausweichen, und Rolf deutet dein Schweigen als Bestätigung.","score":-1,"nextStepId":"step-2-struggle"}]},"step-2":{"id":"step-2","speaker":"Rolf","speech":"„Und weißt du, warum die Beweise nicht zu finden sind? Weil die NASA alles vernichtet hat. Wer so einen Aufwand betreibt, der hat auch die Macht, Filmmaterial zu fälschen. Das ist doch kein Zufall, dass da so wenig Originalmaterial auftaucht.“","options":[{"text":"„Moment, Rolf: Wenn fehlendes Material beweist, dass vertuscht wurde, und vorhandenes Material gefälscht ist, wie könnte dich dann überhaupt irgendetwas überzeugen?“","style":"sokratisch","reaction":"„*stutzt* Ähm... na ja, wenn jemand mir ein Original zeigt, das nicht manipuliert ist. Aber das gibt's ja nicht, da sind sie ja alle in der Sache drin.“","feedback":"Treffer! Du legst die Warnsignale offen: Fehlendes Material gilt selbst als Beweis, und jeder Gegenbeweis wird in die Verschwörung eingebaut, die Behauptung ist nicht mehr prüfbar (Warnsignale 3 und 4.1). Als Frage gestellt, bleibt es ein Gespräch statt eines Urteils.","score":3,"nextStepId":"step-3"},{"text":"„Du hast recht, da ist wirklich auffällig wenig Material aufgetaucht. Hast du auch Links dazu? Schick mir die doch mal, ich will mir das ansehen.“","style":"affektiv","reaction":"„Klar, ich schick dir gleich drei Videos, die du dir ansehen musst. Warte, ich such die raus. Die sollten wirklich alle sehen!“","feedback":"Du bestätigst die Prämisse und öffnest dem Kaninchenbau die Tür. Außerdem bindest du dir selbst mit der Videoflut Zeit und Nerven ans Bein, ohne dass sich an der Struktur etwas ändert.","score":-2,"nextStepId":"step-fail"},{"text":"„Rolf, ich glaube, wir drehen uns im Kreis. Lass uns aufhören, bevor wir uns streiten. Ich mag unsere Gespräche sonst.“","style":"deeskalierend","reaction":"„*zuckt mit den Schultern* Hm. Mir egal, aber so einfach kommst du da nicht raus. Die Wahrheit wird sich durchsetzen, auch ohne dich.“","feedback":"Ein friedlicher Abbruch, der die Beziehung schont. Aber du hast die Struktur des Arguments noch nicht sichtbar gemacht. Das ist brauchbar, nicht stark.","score":1,"nextStepId":"step-3-struggle"}]},"step-2-struggle":{"id":"step-2-struggle","speaker":"Rolf","speech":"„Du siehst es ja selbst: Sobald man fragt, wird abgeblockt. Mich macht das eher sicherer, dass da was faul ist. Warum sonst würde jeder so reagieren?“","options":[{"text":"„Das tut mir leid, so war es nicht gemeint. Magst du mir kurz erklären, was dich dabei am meisten überzeugt hat? Ich höre jetzt zu.“","style":"deeskalierend","reaction":"„*entspannt sich ein wenig* Okay. Es ist vor allem dieses Gefühl, dass man uns nicht alles sagt. Das geht mir schon lange so.“","feedback":"Gute Reparatur: Du holst Rolf zurück ins Gespräch, ohne die Behauptung zu bestätigen. Das Gefühl dahinter ist wichtiger als der Streit um Schatten.","score":2,"nextStepId":"step-3"},{"text":"„Du hast recht, ich bin ausgewichen. Das Argument mit den Schatten ist für Laien nicht leicht zu knacken, aber ich kann es erklären, wenn du willst.“","style":"frontal","reaction":"„Ja klar, erklär mir das. Mal sehen, wie du das hinbiegst. *verschränkt die Arme*“","feedback":"Mutig und sachlich, aber in der Stimmung gefährlich: Rolf wartet nur darauf, den nächsten Einwand zu liefern. Die Energiekosten steigen, der Ertrag bleibt offen.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Rolf, wenn du dich nur bestätigt fühlen willst, such dir jemand anderen. Ich hab keine Lust, hier den Sparringspartner zu spielen.“","style":"sarkastisch","reaction":"„Genau so reagieren die, die was zu verbergen haben. Ich hab's kapiert.“","feedback":"Sarkasmus trifft die Person, nicht die Behauptung, und liefert Rolf sogar eine Bestätigung für seine Erzählung.","score":-2,"nextStepId":"step-fail"}]},"step-3":{"id":"step-3","speaker":"Rolf","speech":"„Ich bin ja nicht dumm. Ich hab einfach ein gutes Gespür für so etwas. Mir glaubt das im Team keiner, aber die meisten trauen sich nur nicht zu fragen. Ich bin einer von wenigen, die hinschauen.“","options":[{"text":"„Du bist definitiv nicht dumm, Rolf. Aber überleg mal: Wenn Hinschauen heißt, dass nichts dich je umstimmen kann, woran würdest du bemerken, dass du dich irrst?“","style":"sokratisch","reaction":"„*lange Pause* Gute Frage. Ich... müsste sagen, ich wüsste es nicht. Aber das heißt noch nicht, dass ich falsch liege.“","feedback":"Stark: Du würdigst die Person und stellst die Falsifizierbarkeit als offene Frage (.1). Rolf muss selbst merken, dass seine Position keinen Prüfstein zulässt.","score":3,"nextStepId":"step-4"},{"text":"„Hör mal, Rolf, ich habe heute noch einen vollen Tag. Magst du mir die Videos schicken, und ich schau am Wochenende mal rein? Dann reden wir nächste Woche.“","style":"deeskalierend","reaction":"„Ja, mach das. Ich bin gespannt, was du sagst. Ich schick dir gleich die besten drei.“","feedback":"Ein freundlicher Aufschub, der die Beziehung wahrt. Aber du nimmst dir damit unbezahlte Extraarbeit und lässt offen, ob das Gespräch überhaupt Wirkung haben kann.","score":1,"nextStepId":"step-4-struggle"},{"text":"„Dass dir im Team keiner glaubt, hat vielleicht Gründe. Die meisten wollen einfach nicht den ganzen Tag über Studio-Kulissen reden.“","style":"sarkastisch","reaction":"„Da haben wir's wieder. Keiner traut sich, ehrlich zu sein. Aber ich lasse mich nicht einschüchtern.“","feedback":"Der Seitenhieb verhärtet Rolfs Rolle als einsamer Wissender (das Muster der elitären Gruppe der Erwachten.1) und verschlechtert das Klima im Team.","score":-2,"nextStepId":"step-fail"}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Rolf","speech":"„Du, ich merke, du willst gerade nicht mehr. Aber ehrlich gesagt nervt es mich auch, dass das im Team jedes Mal zum Streit wird. Was würdest du denn vorschlagen?“","options":[{"text":"„Vielleicht kein Thema für die Mittagspause. Ich höre dir gern zu, aber nicht jeden Tag, und bitte nicht in der Teamgruppe. Wäre das okay für dich?“","style":"deeskalierend","reaction":"„*nickt* Ja, das kann ich nachvollziehen. In der Gruppe hat's eh nur Streit gegeben. Dann sag ich dir Bescheid, wenn mich was richtig beschäftigt.“","feedback":"Gelungene Triage: Du setzt eine freundliche Grenze, die deine Energie schützt und die Beziehung trägt. Die Sachfrage bleibt offen, aber der Kontakt auch.","score":2,"nextStepId":"step-4-struggle"},{"text":"„Ganz einfach: Lies mal, was die NASA selbst zu den Schatten sagt, und dann reden wir. Ohne Quelle gehe ich nicht weiter drauf ein.“","style":"frontal","reaction":"„Ach, jetzt soll ich bei der NASA selbst nachlesen? Das ist doch, als würdest du einen Verdächtigen fragen, ob er's war.“","feedback":"Der Verweis ist sachlich nicht falsch, aber die Quelle ist in Rolfs Weltbild bereits Teil der Verschwörung. Du erzeugst nur Gegenwehr und keine Bewegung.","score":0,"nextStepId":"step-4-struggle"},{"text":"„Mir ist das Thema ehrlich gesagt egal, Rolf. Schreib, was du willst, ich scrolle sowieso drüber.“","style":"ausstieg","reaction":"„Na, dann ist's ja gut. Dann sind wir uns einig, dass dir die Wahrheit egal ist.“","feedback":"Gleichgültigkeit statt klarer Grenze. Du schützt zwar deine Energie, aber auf Kosten der Beziehung, und Rolf deutet es als Desinteresse an der Wahrheit.","score":-1,"nextStepId":"step-fail"}]},"step-4":{"id":"step-4","speaker":"Rolf","speech":"„Okay, ich geb's zu: Ein bisschen verunsichert mich das gerade. Aber ich will mir das nicht von einem einzigen Gespräch kaputt machen lassen. Was soll ich jetzt tun, einfach alles glauben, was die offiziellen Stellen sagen?“","options":[{"text":"„Nein, Rolf, glauben musst du gar nichts. Spiel es mal durch: Welches Ergebnis würde dich dazu bringen, deine Meinung zu ändern? Wenn du das für dich aufschreibst, haben wir schon was gewonnen.“","style":"sokratisch","reaction":"„*überlegt* Dass jemand ein Detail im Material findet, das wirklich nicht ins Studio passt und das ich selbst prüfen kann. Das schreib ich mir tatsächlich mal auf.“","feedback":"Sehr gut: Du lädst zur Selbstprüfung ein und lässt die Entscheidung bei Rolf. So entsteht ein Kriterium, das die Behauptung prüfbar macht (.1).","score":3,"nextStepId":"step-5-success"},{"text":"„Dann gehen wir jetzt Punkt für Punkt durch, was es mit den Schatten und der Fahne auf sich hat. Ich hab da Zeit, auch bis über die Pause hinaus.“","style":"frontal","reaction":"„*seufzt* Okay, dann leg mal los. Aber ich sag dir gleich: Ich bin da kritisch.“","feedback":"Faktisch ehrenwert, aber du eröffnest ohne Not den Marathon an Einzeldebatten. Ob das den Aufwand wert ist, hast du dir nach „Das Management emotionaler Kosten“ nicht gefragt.","score":0,"nextStepId":"step-5-struggle"},{"text":"„Du kannst glauben, was du willst, Rolf. Das ist dein Leben. Hauptsache, du gehst nicht auf die Leute los, die anderer Meinung sind.“","style":"humorvoll","reaction":"„*lacht kurz* Okay, okay, das ist fair. Ich nerv ja wirklich manchmal. Aber ich bleib dabei, dass es komisch riecht.“","feedback":"Humor entspannt, und die Grenze im Ton ist klar. Aber du lässt die Frage nach Prüfbarkeit liegen. Beziehungsschonend, inhaltlich dünn.","score":1,"nextStepId":"step-5-struggle"}]},"step-4-struggle":{"id":"step-4-struggle","speaker":"Rolf","speech":"„Gut, dann lassen wir das für heute. Aber ich meld mich nochmal, wenn ich was Neues finde.“","options":[{"text":"„Gern, aber nicht in die Teamgruppe, sondern zu zweit. Und ich merk mir deine Frage: Was würde dich überzeugen? Denk mal drüber nach.“","style":"sokratisch","reaction":"„*lächelt schief* Gute Frage, die schiebst du mir einfach so zu. Okay, ich denk drüber nach.“","feedback":"Ein sauberer Abschluss: Du schützt die Gruppe, bleibst ansprechbar und gibst Rolf eine Frage mit, die weiterarbeiten kann.","score":2,"nextStepId":"step-5-success"},{"text":"„Gut. Aber schick mir bitte nicht mehr so viele Videos. Das kostet mich zu viel Zeit und Nerven, und ich habe ehrlich gesagt genug davon gesehen.“","style":"deeskalierend","reaction":"„Dann eben weniger. Aber wenn's wichtig ist, meld ich mich trotzdem.“","feedback":"Eine ehrliche Grenze nach „Das Management emotionaler Kosten“. Sie schützt deine Energie, verbindet aber kein inhaltliches Angebot.","score":1,"nextStepId":"step-5-struggle"},{"text":"„Von mir aus. Ich glaub eh nicht, dass sich bei dir noch was ändert, aber bitte, schick ruhig, was du findest, ich lach dann.“","style":"sarkastisch","reaction":"„*zuckt zusammen* Okay. Dann sind wir uns zumindest da einig.“","feedback":"Die Aufgabe der Hoffnung klingt hier wie ein Urteil über die Person. Das verbaut die Tür, statt Energie zu schonen.","score":-2,"nextStepId":"step-fail"}]},"step-5-success":{"id":"step-5-success","speaker":"Rolf","speech":"„Weißt du was, so ruhig hat mit mir hier noch keiner drüber geredet. Ich muss ehrlich sagen: Ich bin mir nicht mehr ganz sicher, ob ich da nicht was durcheinanderwerfe. Magst du am Freitag nochmal auf einen Kaffee kommen?“","options":[{"text":"„Gerne, Rolf. Aber nur, wenn wir auch mal über etwas anderes reden. Ich bring was zum Knabbern mit.“","style":"humorvoll","reaction":"„*lacht* Abgemacht. Und ich bring die Liste mit, was mich überzeugen würde. Dann schauen wir, ob sie je erfüllt wird.“","feedback":"Mission gelungen: Du hast Struktur sichtbar gemacht, die Beziehung gestärkt und gleichzeitig deine Energie im Blick behalten. Der Kaffee ist eine Schlacht, die du kämpfen kannst.","score":3}]},"step-5-struggle":{"id":"step-5-struggle","speaker":"Rolf","speech":"„Na gut. Ich schick dir die Videos, wenn du magst. Aber schau sie dir mal an, bevor du urteilst.“","options":[{"text":"„Ich schau rein, wenn ich Zeit habe, ohne Zusage. Und wenn ich mal eine Pause von dem Thema brauche, sag ich es dir offen. Okay?“","style":"deeskalierend","reaction":"„Okay, fair. Du hast ja deinen eigenen Kram. Ich bin dir nicht böse.“","feedback":"Eine klare, freundliche Grenze. Du bleibst im Kontakt, ohne dich zu verausgaben. Die Sachfrage bleibt offen, aber das Gespräch auch.","score":2}]},"step-fail":{"id":"step-fail","speaker":"Rolf","speech":"„Ich seh schon, mit dir kann man darüber nicht reden. Dann halt ich mich an die, die zuhören.“ *steht auf und nimmt sein Tablett*","options":[{"text":"Ende: Rolf hat sich nicht ernst genommen gefühlt und sucht jetzt Bestätigung in noch geschlosseneren Kreisen. Hier wurde Energie verbrannt, ohne dass etwas gewonnen wurde.","style":"ausstieg","reaction":"Beim nächsten Mal: erst fragen, ob das eine Schlacht ist, die du kämpfen musst, kämpfen kannst oder vermeiden solltest, und dann bewusst entscheiden.","feedback":"Frage dich: Wollte ich Rolf überzeugen oder meine Energie schützen? Das Management emotionaler Kosten hilft, beides sauber zu trennen.","score":0}]}},"status":"entwurf","familie":"kraefte-und-ausstieg","fertigkeit":"F3","stufe":4,"kurz":"Ein Mythos, der jeden Gegenbeweis zur Verschwörung erklärt, ist nicht mehr prüfbar; Faktenschlacht um Faktenschlacht kostet dann nur Energie. Vorher lohnt die Frage, ob man diesen Streit führen muss oder kann; im Zweifel schützt man die Beziehung, statt zu gewinnen.","prueffrage":"Was würde Rolf als Gegenbeweis gelten lassen, und wie deutet er bisher sowohl vorhandenes als auch fehlendes Material?","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"7, 10","abruf":"2026-10-12"},{"typ":"doi","kurz":"Lewandowsky, S.; Cook, J.; Ecker, U. K. H. u. a. (2020): The Debunking Handbook 2020","oeffentlich":true,"doi":"10.17910/b7.1182","url":"https://skepticalscience.com/docs/DebunkingHandbook2020.pdf","seite":"9","abruf":"2026-10-12"},{"typ":"doi","kurz":"Douglas, K. M.; Sutton, R. M.; Cichocka, A. (2017): The Psychology of Conspiracy Theories (Current Directions in Psychological Science 26(6))","oeffentlich":false,"doi":"10.1177/0963721417718261"}],"thema":"Geschichte und Wissenschaft"},{"id":"scen-schwiegermutter-hexenschuss","title":"Schwiegermutters Wunderheiler","subtitle":"Regression zur Mitte, geübt mit intellektueller Barmherzigkeit","character":"Ruth, Schwiegermutter","avatar":"🌦️","context":"Beim Sonntagskaffee erzählt dir deine Schwiegermutter Ruth strahlend, dass ihre Rückenschmerzen nach dem Besuch bei einem Wunderheiler, der ihr „die Hände aufgelegt“ hat, wie weggeblasen waren. Sie ist sich sicher: „Das war immer so, die Handauflegung wirkt!“ Ihr Sohn, dein Partner, verdreht schon die Augen.","goal":"Nimm Ruths Erleichterung ernst, ohne den Heiler zu verteidigen, und führe sie mit neugierigen Fragen zum natürlichen Auf und Ab ihrer Beschwerden.","bereich":"Familie","laenge":"kurz","ton":"heiter","bestehenAb":4,"lektion":"Viele Beschwerden wie Rückenschmerzen schwanken von selbst. Wer in der Spitze Hilfe sucht, erlebt danach mit hoher Wahrscheinlichkeit eine Besserung, auch ohne Behandlung. Das ist Regression zur Mitte und kein Beleg für die Wirkung der Behandlung. Mit intellektueller Barmherzigkeit würdigst du Ruths Sorge um ihre Gesundheit und fragst neugierig nach ihren Schmerzspitzen, statt sie als leichtgläubig abzustempeln.","toolRef":"H.1.3","faktenRef":"C.4.6","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Ruth, Schwiegermutter","speech":"„Stell dir vor, gestern konnte ich mich vor Schmerzen kaum bücken, und heute tanze ich fast durch die Küche! Das macht alles der Herr Winkler mit seinen Händen. Jedes Mal, wenn ich bei ihm war, war es danach weg. Das kann doch kein Zufall sein!“","options":[{"text":"„Ruth, das ist der klassische Trugschluss: Rückenschmerzen gehen von allein weg, das hätte auch ohne Handauflegung geklappt. Du bist da einem Geschäftemacher auf den Leim gegangen.“","style":"frontal","reaction":"„Auf den Leim gegangen?! Ich bin doch nicht senil! Ich weiß, was ich spüre, und du sitzt hier und weißt es besser!“ *stellt die Kaffeekanne etwas zu hart ab*","feedback":"Frontalangriff! Die Sache stimmt zwar im Kern, aber Ruth hört „Du bist naiv“. Ohne intellektuelle Barmherzigkeit wird aus der Sachfrage ein Streit um ihre Würde.","score":-2,"nextStepId":"step-fail"},{"text":"„Das freut mich riesig, Ruth! Du suchst aktiv nach etwas, das dir hilft, und das ist wichtig. Sag mal, war gestern ein besonders schlimmer Tag, oder sind die Schmerzen öfter mal so heftig und dann wieder besser?“","style":"sokratisch","reaction":"„Hm... gestern war es wirklich der Gipfel, ich konnte kaum die Strümpfe anziehen. Aber ehrlich gesagt, ein ständiges Auf und Ab ist es ja schon seit Jahren. Mal geht es, mal nicht.“","feedback":"Treffer! Du würdigst Ruths Motiv und stellst eine Detektivfrage nach dem Schmerzverlauf. So kommt sie selbst auf die Schwankungen, ohne dass du widersprichst.","score":3,"nextStepId":"step-2"},{"text":"„Na, wenn es dir hilft, Ruth! Hauptsache, du bist glücklich. Ich will da nicht reinreden, sonst gibt es nur wieder Streit, und den Nachmittag wollen wir uns nicht verderben.“","style":"ausstieg","reaction":"„Eben! Endlich versteht mich mal jemand. Nächste Woche gehe ich wieder hin, der Herr Winkler ist ein Segen.“","feedback":"Du vermeidest den Konflikt, aber Ruth fühlt sich in ihrer Deutung bestätigt. Barmherzigkeit heißt nicht, dem Mythos zuzustimmen, sondern ihn freundlich zu hinterfragen.","score":0,"nextStepId":"step-bestaetigt"}]},"step-2":{"id":"step-2","speaker":"Ruth, Schwiegermutter","speech":"„Aber ich gehe ja immer genau dann hin, wenn es am schlimmsten ist! Und danach ist es besser. Das muss doch am Herrn Winkler liegen, oder wozu soll ich sonst hingehen?“","options":[{"text":"„Genau das ist ja der Punkt, Ruth: Wenn man am schlimmsten Tag hingeht, wird es danach statistisch sehr wahrscheinlich besser, völlig egal, was man tut. Das nennt man Regression zur Mitte, und es beweist die Wirkung deines Heilers nicht.“","style":"frontal","reaction":"„Regression zur... was? Jetzt kommst du mir mit Fachwörtern. Ich weiß nur, dass es hilft. Lass uns lieber über was anderes reden.“","feedback":"Inhaltlich richtig, aber als fertige Belehrung mit Fachbegriff. Ruth fühlt sich überfahren und mauert, die gute Gesprächsbasis aus Schritt 1 geht verloren.","score":0,"nextStepId":"step-struggle"},{"text":"„Das ist ein cleverer Gedanke von dir, Ruth, dass der Zeitpunkt zählt. Wenn du an deinem allerschlimmsten Tag hingehst: Wie wahrscheinlich ist es, dass es danach sowieso wieder besser wird, ob nun jemand die Hände auflegt oder nicht?“","style":"sokratisch","reaction":"„Hm... besser wurde es ja eigentlich meistens, wenn ich mich ein, zwei Tage geschont habe. Meinst du, das wäre auch ohne den Herrn Winkler so gekommen? Also, ich fühle mich schon gut bei ihm aufgehoben...“","feedback":"Sehr gut! Du bestätigst Ruths gute Beobachtung und lässt sie den Kern der Regression zur Mitte selbst entdecken. Sie darf ihr gutes Gefühl behalten und gleichzeitig umdenken.","score":3,"nextStepId":"step-success"},{"text":"„Ruth, ich glaube, du bildest dir das ein. Das ist nur Placebo, und der Herr Winkler weiß das ganz genau und verdient daran.“","style":"sarkastisch","reaction":"„Placebo! Unterstellst du mir etwa, ich sei einfältig und er ein Betrüger? Du kennst ihn doch gar nicht!“ *verschränkt die Arme*","feedback":"Du unterstellst Ruth Einbildung und dem Heiler böse Absicht, ohne das beweisen zu können. Das ist das Gegenteil intellektueller Barmherzigkeit und schließt die Tür.","score":-2,"nextStepId":"step-fail"}]},"step-success":{"id":"step-success","speaker":"Ruth, Schwiegermutter","speech":"„Weißt du was, vielleicht schreibe ich mir einfach mal auf, wie die Schmerzen so von Tag zu Tag sind. Dann sehe ich ja, ob es auch besser wird, wenn ich gar nichts mache. Aber den Herrn Winkler mag ich trotzdem, der hört wenigstens zu!“","options":[{"text":"„Das ist eine tolle Idee, Ruth, wie eine kleine Forscherin! Und dass jemand zuhört, ist ja auch ein Wert für sich. Zeig mir dein Schmerztagebuch gern, ich bin gespannt.“","style":"humorvoll","reaction":"„Forscherin, na so was! *lacht* Dann bekommst du als Erste die Ergebnisse. Und jetzt nimm noch ein Stück Kuchen!“","feedback":"Mission gelungen! Ruth bleibt in ihrer Würde, entdeckt selbst das Auf und Ab und beginnt sogar zu beobachten. Das ist barmherzig und wirksam zugleich.","score":3},{"text":"„Gute Idee, Ruth. Und beim nächsten Besuch bei Herrn Winkler frag ihn doch, welche Studie zeigt, dass seine Methode wirkt.“","style":"sokratisch","reaction":"„Studien... na, das ist mir zu kompliziert. Aber das Tagebuch mache ich, versprochen.“","feedback":"Der Impuls ist nicht falsch, aber die Studienfrage überfordert Ruth etwas. Das Tagebuch genügt als erster Schritt.","score":1}]},"step-struggle":{"id":"step-struggle","speaker":"Ruth, Schwiegermutter","speech":"„Ach, du mit deinen Statistiken. Ich bin zufrieden mit meinem Herrn Winkler. Gibst du mir mal die Sahne?“","options":[{"text":"„Natürlich, hier. Ich freue mich einfach, dass es dir heute so gut geht, Ruth. Und falls du mal neugierig bist, wie so ein Schmerzverlauf übers Jahr aussieht, erzähle ich dir gern davon.“","style":"deeskalierend","reaction":"„Vielleicht ein andermal. Jetzt gibt es erst mal Kuchen. Du bist ein Guter, das sage ich auch dem Jungen.“","feedback":"Guter Rückzug: Du gibst den Streit auf, lässt aber ein Angebot offen. Die Beziehung bleibt heil, die Sachfrage ruht für später.","score":2},{"text":"„Ruth, ich meine das ernst: Ohne Kontrollgruppe weiß man gar nichts. Du hast dich ganz bestimmt täuschen lassen, und ich sage das nur, weil ich mir Sorgen um dich mache.“","style":"frontal","reaction":"„Dann täusche ich mich eben! Es ist mein Rücken und mein Geld. Iss deinen Kuchen auf und lass es gut sein.“","feedback":"Du drückst nach, obwohl Ruth längst zugemacht hat. Wer jetzt weiter belehrt, verliert Vertrauen statt Boden gutzumachen.","score":-1}]},"step-bestaetigt":{"id":"step-bestaetigt","speaker":"Ruth, Schwiegermutter","speech":"„Schön, dass du das auch so siehst. Nächste Woche gehe ich wieder hin. Und jetzt trink deinen Kaffee, bevor er kalt wird!“","options":[{"text":"Ende: Ruth fühlt sich bestätigt, aber eine Klärung hat nicht stattgefunden. Zustimmen aus Harmoniebedürfnis ist keine Barmherzigkeit, sondern Ausweichen.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst ihre Sorge um die eigene Gesundheit würdigen und dann neugierig nach dem Verlauf der Schmerzen fragen.","feedback":"Frage dich: Habe ich Ruth wirklich verstanden oder nur Streit vermieden? Intellektuelle Barmherzigkeit geht von guten Motiven aus und fragt neugierig weiter.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Ruth, Schwiegermutter","speech":"„Mit dir ist über meinen Herrn Winkler nicht zu reden. Ich habe schon für nächste Woche einen Termin gemacht. Und jetzt ist Kaffeezeit, Schluss mit dem Thema.“","options":[{"text":"Ende: Ruth hat sich nicht gehört gefühlt und hält an ihrer Deutung fest. Wer Rechthaben über Verstehen stellt, verliert beides.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst ihre Sorge um die eigene Gesundheit würdigen, dann nach dem Verlauf der Schmerzen fragen.","feedback":"Frage dich: Wollte ich Ruth überführen oder gemeinsam verstehen? Intellektuelle Barmherzigkeit geht von guten Motiven aus und fragt neugierig weiter.","score":0}]}},"status":"entwurf","familie":"was-waere-ohne","fertigkeit":"F2","stufe":3,"kurz":"Viele Beschwerden wie Rückenschmerzen schwanken von selbst. Wer am schlimmsten Tag Hilfe sucht, erlebt danach mit hoher Wahrscheinlichkeit eine Besserung, auch ohne Behandlung; das allein belegt keine Wirkung. Wer die Sorge ernst nimmt und nach dem Verlauf fragt, kommt weiter.","prueffrage":"An welchen Tagen geht Ruth zum Heiler, und wie entwickelten sich ihre Schmerzen nach solchen Tagen, wenn sie nicht hinging?","quellen":[{"typ":"doi","kurz":"Morton, V.; Torgerson, D. J. (2003): Effect of regression to the mean on decision making in health care (BMJ 326)","oeffentlich":true,"doi":"10.1136/bmj.326.7398.1083","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1125994/","abruf":"2026-10-12"},{"typ":"doi","kurz":"da C Menezes Costa, L. u. a. (2012): The prognosis of acute and persistent low-back pain: a meta-analysis (CMAJ 184(11))","oeffentlich":true,"doi":"10.1503/cmaj.111271","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3414626/","abruf":"2026-10-12"},{"typ":"url","kurz":"Malpas, J.: Donald Davidson, Stanford Encyclopedia of Philosophy (rev. 28.04.2023)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"scen-stromzaehler-smart","title":"Herr Brandts Smartmeter-Angst","subtitle":"Elektrosmog im Keller, geübt mit der Deeskalations-Matrix","character":"Herr Brandt","avatar":"🔌","context":"Im Treppenhaus erwischt dich dein Nachbar Herr Brandt. Seit im Keller der neue Stromzähler hängt, schläft er schlecht und ist überzeugt, dass das Gerät strahlt und die ganze Hausgemeinschaft krank macht. Er ist laut, aufgebracht und wirft dir vor, ihn nicht ernst zu nehmen.","goal":"Beruhige Herrn Brandt mit der Deeskalations-Matrix und leite das Gespräch auf eine nüchterne Energie-Buchhaltung um, ohne ihn bloßzustellen.","bereich":"Nachbarschaft","laenge":"kurz","ton":"ernst","bestehenAb":4,"lektion":"Wer sich bedroht fühlt, hört zuerst auf den Tonfall und dann erst auf Argumente. Erst die Gefühlsvalidierung macht Raum für die Frage der Energie-Buchhaltung: Welche Energieform soll wirken, wie viel kommt an, und lässt sie sich messen? Eine Behauptung ohne Energiequelle und Maßeinheit bleibt eine Behauptung. Gefühle zu validieren heißt dabei nie, dem Inhalt zuzustimmen.","toolRef":"H.2.1","faktenRef":"C.2.3","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Herr Brandt","speech":"„Haben Sie das Ding im Keller gesehen? Der neue Zähler strahlt! Seit der hängt, schlafe ich keine Nacht mehr durch, und die Frau Weber von oben klagt auch über Kopfschmerzen. Der macht uns alle krank, und keiner nimmt das ernst!“","options":[{"text":"„Herr Brandt, das ist Quatsch. Ein Stromzähler macht niemanden krank. Sie sollten aufhören, solche Schauermärchen im ganzen Haus zu verbreiten, das beunruhigt nur die Nachbarn.“","style":"frontal","reaction":"„Schauermärchen?! Ich verbreite gar nichts, ich mache mir Sorgen um uns alle! Aber mit Leuten, die alles wegwischen, rede ich nicht!“","feedback":"Du reagierst auf den Inhalt statt auf das Gefühl und wertest ihn ab. Brandt fühlt sich angegriffen und verhärtet. Die Deeskalations-Matrix rät, zuerst das Gefühl zu validieren.","score":-2,"nextStepId":"step-fail"},{"text":"„Das klingt, als würden Sie sich wirklich Sorgen machen und als hätte man Sie damit allein gelassen. Habe ich das richtig verstanden? Erzählen Sie mir, was Sie seit dem Einbau bemerken.“","style":"deeskalierend","reaction":"„*stutzt, die Stimme wird leiser* Ja... genau so ist es. Ich bin ja nicht blöd, ich merke doch, dass sich etwas verändert hat, seit der Zähler da ist.“","feedback":"Gut gemacht: Du validierst das Gefühl, nicht den Inhalt. Die emotionale Temperatur sinkt, und Brandt fühlt sich gehört, ohne dass du dem Strahlen-Mythos zugestimmt hast.","score":3,"nextStepId":"step-2"},{"text":"„Ach du meine Güte, wirklich? Dann sollten wir sofort den Netzbetreiber anrufen und das Ding ausbauen lassen, bevor noch jemand ernsthaft krank wird!“","style":"affektiv","reaction":"„Sehen Sie, endlich einer, der es versteht! Wir schreiben gleich eine Unterschriftenliste für das ganze Haus!“","feedback":"Du übernimmst seine Alarmstimmung und bestätigst den Inhalt. Gefühle zu validieren heißt nicht, der Behauptung zuzustimmen (Kipppunkt).","score":-1,"nextStepId":"step-2"}]},"step-2":{"id":"step-2","speaker":"Herr Brandt","speech":"„Das ist doch Elektrosmog! Der Zähler sendet ständig, und das geht durch die Wände bis in mein Schlafzimmer. Das muss doch einer mal untersuchen!“","options":[{"text":"„Da stimme ich Ihnen zu, dass man so etwas prüfen kann. Lassen Sie uns kurz Buch führen: Welche Art von Energie soll da genau wirken, Wärme oder Funkwellen? Und wie viel davon kommt bei Ihnen im Schlafzimmer an? So etwas lässt sich ja messen.“","style":"sokratisch","reaction":"„Hm, Wärme jedenfalls nicht, da ist ja nichts warm... Funkwellen vielleicht. Wie viel genau, das weiß ich nicht. Aber das könnte man messen, sagen Sie?“","feedback":"Treffer: Du stellst die Energie-Buchhaltung: Welche Energieform, woher kommt sie, wie viel kommt an, und ist sie messbar? Brandt wird selbst zum Prüfer, ohne dass du ihn belehrst.","score":3,"nextStepId":"step-3-success"},{"text":"„Ich verstehe, dass Sie das beschäftigt. Aber Sie haben ja keine Ahnung von der Physik dahinter, und die Leute, die Ihnen so etwas erzählen, wollen meist nur Geld verdienen.“","style":"frontal","reaction":"„Keine Ahnung?! Sie halten mich also für dumm und für einen Hereingefallenen! Das muss ich mir nicht anhören!“","feedback":"Du kippst in eine Du-Botschaft mit Unterstellung. Statt die Behauptung zu prüfen, greifst du den Menschen an, und das Gespräch eskaliert.","score":-2,"nextStepId":"step-fail"},{"text":"„Ich merke, wir drehen uns gerade im Kreis, und das ist für uns beide nicht produktiv. Lassen Sie uns das Thema für heute lassen und morgen mit frischem Kopf darüber reden. Mir ist das Gespräch wichtig.“","style":"ausstieg","reaction":"„Na gut... morgen. Aber ich lasse das nicht auf sich beruhen, nur damit Sie das wissen.“","feedback":"Die strategische Auszeit ist ein legitimer Reset und schützt die Nachbarschaft. Du verschenkst aber den Moment, in dem Brandt schon gesprächsbereit war und die Energie-Frage selbst hätte durchdenken können.","score":1,"nextStepId":"step-3-struggle"}]},"step-3-success":{"id":"step-3-success","speaker":"Herr Brandt","speech":"„Wenn man das messen kann, dann sollte man das doch einfach tun, statt zu streiten. Ich will ja nur wissen, ob da wirklich etwas ankommt. Was schlagen Sie vor?“","options":[{"text":"„Genau, dann klärt die Messung die Sache für uns alle. Ich schaue gern mit Ihnen nach, wer das fachgerecht messen kann, und wir sagen Frau Weber Bescheid. Bis dahin trinken wir einen Kaffee, einverstanden?“","style":"deeskalierend","reaction":"„Einverstanden. Das ist vernünftig. Und ich bin froh, dass Sie mich nicht für verrückt halten. Kaffee klingt gut.“","feedback":"Mission gelungen! Validierung und Energie-Fragen haben aus dem Streit ein gemeinsames Prüfprojekt gemacht. Brandt behält sein Gesicht und kommt über die Messung selbst zur Klarheit.","score":3},{"text":"„Messen brauchen wir da gar nicht. Das ist alles Einbildung, machen Sie sich einfach keine Gedanken mehr. Ich habe solche Fälle schon oft erlebt, und es war nie etwas dahinter.“","style":"frontal","reaction":"„Keine Gedanken machen? Das sagt sich leicht. Ich fühle mich schon wieder abgespeist.“","feedback":"Du ersetzt die gemeinsame Prüfung durch ein Machtwort. Das nimmt Brandt die Eigenverantwortung und wirkt abwertend.","score":-1}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Herr Brandt","speech":"„Ich lasse das nicht auf sich beruhen. Aber gut, dann reden wir morgen noch einmal in Ruhe.“","options":[{"text":"„Abgemacht. Bis morgen denken wir beide darüber nach, wie man so etwas sauber prüfen könnte. Schlafen Sie, so gut es geht.“","style":"deeskalierend","reaction":"„Danke. Das nehme ich mit. Bis morgen.“","feedback":"Ordentlicher Rückzug: Der Kanal bleibt offen, die Beziehung ist geschützt. Die Sachfrage ist noch ungeklärt, aber eine zweite Runde bleibt möglich.","score":2},{"text":"„Wie Sie wollen. Aber morgen bringen Sie dann bitte echte Belege mit statt nur Ihr Bauchgefühl, sonst reden wir gar nicht erst darüber.“","style":"sarkastisch","reaction":"„Aha, jetzt wird es also bissig. Dann können Sie sich das Gespräch morgen sparen.“","feedback":"Sarkasmus wirkt wie ein Gegenangriff. Du verspielst, was die Auszeit an Entspannung gebracht hat.","score":-1}]},"step-fail":{"id":"step-fail","speaker":"Herr Brandt","speech":"„Ich sehe schon, mit Ihnen ist darüber nicht zu reden. Dann rede ich eben mit den anderen im Haus!“ *geht mit schnellen Schritten die Treppe hinauf*","options":[{"text":"Ende: Brandt fühlte sich abgekanzelt und trägt seine Sorge jetzt ungebremst durchs Haus. Rechthaben und Helfen sind zweierlei.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst das Gefühl ernst nehmen, dann erst über die Energie-Frage reden.","feedback":"Frag dich: Wollte ich Brandt überzeugen oder das Gespräch retten? Die Deeskalations-Matrix ordnet die Reihenfolge.","score":0}]}},"status":"entwurf","familie":"bilanz-pruefen","fertigkeit":"F1","stufe":1,"kurz":"Wer sich bedroht fühlt, hört zuerst auf den Tonfall und erst dann auf Argumente. Gefühle zu bestätigen heißt nicht, dem Inhalt zuzustimmen. Danach hilft die nüchterne Frage, welche Energie wirken soll, wie viel davon ankommt und ob sie sich messen lässt.","prueffrage":"Welche Energie soll vom Zähler im Keller bis ins Schlafzimmer gelangen, und wie viel davon ist dort tatsächlich messbar?","quellen":[{"typ":"url","kurz":"Bundesamt für Strahlenschutz: Funkbasierte Verbrauchszähler im Haushalt (Stand 25.07.2025)","oeffentlich":true,"url":"https://www.bfs.de/DE/themen/emf/hff/quellen/smart-meter/smart-meter_node.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Bosch-Capblanch, X. u. a. (2024): The effects of radiofrequency electromagnetic fields exposure on human self-reported symptoms (Environment International 187)","oeffentlich":false,"doi":"10.1016/j.envint.2024.108612"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"}],"thema":"Technik und KI"},{"id":"scen-nachbar-wuenschelrute","title":"Nachbar Gustavs Wünschelrute","subtitle":"Wasseradern unterm Haus, geübt mit kognitiver Entkopplung","character":"Gustav","avatar":"🪄","context":"Am Gartenzaun erzählt dir Nachbar Gustav, dass er mit seiner Wünschelrute „Wasseradern“ unter seinem Haus aufgespürt hat, die seinen Schlaf stören sollen. Er ist stolz auf seine Gabe und hat schon überlegt, sein Bett umzustellen. Du wohnst seit Jahren neben ihm und willst das Gespräch freundlich halten.","goal":"Bring Gustav mit sokratischen Fragen und ohne Spott dazu, selbst einen fairen, verblindeten Test seiner Rute vorzuschlagen.","bereich":"Nachbarschaft","laenge":"mittel","ton":"heiter","bestehenAb":6,"lektion":"Eine Erfolgsgeschichte ist ein Startpunkt für eine Hypothese, aber noch kein Beweis, denn sie steht unten auf der Evidenzpyramide. Erst ein kontrollierter, verblindeter Test zeigt, ob mehr als Zufall dahintersteckt. Wer seine Fähigkeit als etwas sieht, das er hat, nicht als etwas, das er ist, kann sie ohne Gesichtsverlust prüfen lassen.","toolRef":"H.1.1","faktenRef":"A.2","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Gustav","speech":"„Stell dir vor, Nachbar: Ich bin gestern mit meiner Rute durchs Haus gegangen, und im Schlafzimmer hat sie so ausgeschlagen, dass sie mir fast aus der Hand gesprungen ist. Eine Wasserader, ganz klar! Kein Wunder, dass ich seit Jahren so schlecht schlafe!“","options":[{"text":"„Gustav, das ist Humbug. Mit so einem Stock kann man keine Wasseradern finden, das wissen doch alle. Hör auf, dir solchen Unsinn einzureden.“","style":"frontal","reaction":"„Humbug?! Ich mache das seit dreißig Jahren! Du hast ja keine Ahnung, was ich schon alles gefunden habe!“ *Er presst die Rute an sich, als wolle jemand sie ihm wegnehmen.*","feedback":"Frontalangriff: Du gibst ein Urteil ab, ohne Gustav einzubeziehen. Er hört einen Angriff auf sich selbst und verteidigt seine Gabe, wie man seine Identität verteidigt. Das ist genau die Kopplung, die „Kognitive Entkopplung“ beschreibt.","score":-2,"nextStepId":"step-fail"},{"text":"„Beeindruckend! Du musst ein echtes Talent haben. Dann pendle ich mal Omas alten Teppich durch und stelle mein Bett auch um, sicher ist sicher.“","style":"humorvoll","reaction":"„Siehst du, endlich einer, der es versteht! Mach das! Und kauf dir ruhig auch gleich so eine Rute, ich zeige dir, wie es geht.“","feedback":"Freundlich gemeint, aber du bestätigst die Behauptung, ohne sie zu prüfen. Eine begeisterte Geschichte ist nur eine Anekdote und noch kein Beweis; so bleibt Gustav, wo er ist.","score":-1,"nextStepId":"step-flat"},{"text":"„Das klingt ja unheimlich, Gustav, und schlechter Schlaf ist wirklich belastend. Erzähl mal: Wie läuft das genau ab, wenn die Rute ausschlägt?“","style":"sokratisch","reaction":"„Na, ich gehe langsam durch den Raum, halte die Rute locker vor mir, und an der richtigen Stelle schlägt sie nach unten aus. Das spüre ich richtig in den Händen!“","feedback":"Gut: Du nimmst das Anliegen ernst und fragst nach dem Ablauf, statt zu urteilen. So beschreibt Gustav seine Methode selbst, und die Behauptung rückt vor ihn, statt an ihm zu kleben.","score":3,"nextStepId":"step-2"}]},"step-2":{"id":"step-2","speaker":"Gustav","speech":"„Das ist wie bei einem Kompass, nur eben für Wasser. Die Rute weiß es, und ich folge ihr einfach. Die Wasserader im Schlafzimmer ist so sicher wie das Amen in der Kirche.“","options":[{"text":"„Du hältst die Rute selbst in der Hand. Könnte es sein, dass kleine Bewegungen deiner Hände sie zum Ausschlagen bringen, ohne dass du es merkst?“","style":"frontal","reaction":"„Meine Hände? Ich bewege die doch nicht! Ich merke ja wohl, ob ich die Rute bewege oder nicht!“ *Er verschränkt die Arme.*","feedback":"Der Gedanke ist eine prüfbare Hypothese, aber du lieferst die Erklärung fertig und als Vorwurf. Gustav hört darin „Du täuschst dich“ und geht in Abwehr. Besser wäre, ihn selbst nach möglichen anderen Ursachen fragen zu lassen.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Wie könnten wir denn herausfinden, ob die Rute wirklich das Wasser spürt und nicht nur wir selbst? Hast du eine Idee, wie man das prüfen könnte?“","style":"sokratisch","reaction":"„Prüfen? Hm. Na ja, ich bin sonst immer derjenige, der sagt, wo das Wasser ist, und dann wird gebohrt. Eine richtige Gegenprobe habe ich nie gemacht, ehrlich gesagt...“","feedback":"Sehr gut: Eine offene Frage, die Gustav selbst zur Prüffrage führt. Du stellst die Behauptung zur Debatte, nicht seine Person, und gibst ihm den Raum, sein eigenes Wissen zu hinterfragen.","score":3,"nextStepId":"step-3"},{"text":"„Ach, ich weiß nicht, Gustav. Da streiten sich die Leute seit Jahren drüber. Lass uns lieber über was anderes reden, zum Beispiel deine Tomaten.“","style":"ausstieg","reaction":"„Na gut, die Tomaten... die machen sich dieses Jahr prächtig.“ *Er klingt erleichtert, aber auch ein wenig enttäuscht.*","feedback":"Ein freundlicher Ausstieg, der die Beziehung schützt. Hier war aber ein Türspalt offen, denn Gustav klang selbst unsicher. Die Chance auf eine echte Prüfung bleibt liegen.","score":0,"nextStepId":"step-3-struggle"}]},"step-3":{"id":"step-3","speaker":"Gustav","speech":"„Weißt du, wenn ich so überlege: Beim Bohren lag ich nicht immer richtig. Aber das lag dann bestimmt an der Tagesform oder an Störungen. Vielleicht sollte ich das wirklich mal sauber testen... aber was, wenn die Rute dann versagt?“","options":[{"text":"„Dann hat die Rute versagt, Gustav, und das ist eben so. Aber ich wette, du bist einfach zu stur, um es zuzugeben, und fängst gleich wieder mit deinen Ausreden an.“","style":"sarkastisch","reaction":"„Stur?! Weißt du was, vergiss es. Ich muss mir von dir nichts sagen lassen.“ *Er stapft zurück in seinen Garten.*","feedback":"Sarkasmus macht aus einer ehrlichen Unsicherheit einen Streit. Gustav hatte gerade den Mut, über einen Test nachzudenken; du bestrafst ihn dafür und verlierst die Verbindung.","score":-2,"nextStepId":"step-fail"},{"text":"„Wenn die Rute einmal danebenliegt, sagt das nichts über dich als Menschen. Es wäre eine Information über das Werkzeug, so wie ein Schreiner einen schiefen Hobel prüft. Was würdest du dann sehen wollen?“","style":"sokratisch","reaction":"„Hm, so habe ich das noch nie gesehen. Wenn es nur um die Rute geht und nicht um mich... dann wäre ich tatsächlich neugierig. Ich würde sehen wollen, ob sie auch dann ausschlägt, wenn ich nicht weiß, wo das Wasser ist.“","feedback":"Sehr gut: Du trennst die Person von der Behauptung (Kognitive Entkopplung). Gustav kann sich der Prüfung öffnen, weil sein Selbstwert nicht am Ergebnis hängt, und er nennt von selbst den Kern eines verblindeten Tests.","score":3,"nextStepId":"step-4-success"},{"text":"„Dann hast du es wenigstens versucht. Aber du findest doch seit dreißig Jahren Wasser, das spricht ja für sich. Ich glaube dir einfach.“","style":"humorvoll","reaction":"„Siehst du, genau das sage ich ja auch! Danke für dein Vertrauen, Nachbar.“ *Er klingt zufrieden, die Prüfidee ist wieder vergessen.*","feedback":"Schade: Gustav war bereit, die Frage zu stellen, und du beruhigst ihn mit Vertrauen statt mit einer Prüfidee. Die Lage bleibt, wie sie war, und der Zweifel verschwindet wieder unter dem Alltagsgefühl.","score":0,"nextStepId":"step-3-struggle"}]},"step-4-success":{"id":"step-4-success","speaker":"Gustav","speech":"„Also pass auf: Du versteckst Wasserschläuche unter Eimern, ich weiß nicht, wo, und ich gehe mit der Rute drüber. Wenn ich häufiger richtig liege, als der Zufall erwarten lässt, dann stimmt es. Wenn nicht, dann hat wohl die Rute geirrt. Wann machen wir's?“","options":[{"text":"„Gern, Gustav. Wir würfeln aus, unter welchen Eimern die Schläuche liegen, und legen vorher fest, was als Treffer zählt. Samstag nach dem Frühstück, ich bringe alles mit.“","style":"sokratisch","reaction":"„Abgemacht! Und egal, wie es ausgeht: Hinterher gibt's bei mir Kaffee und Kuchen. Das wird spannend!“","feedback":"Perfekt: Du sicherst die Spielregeln vorab, damit niemand das Ergebnis umdeutet, und hältst die Atmosphäre freundlich. Dass die Verstecke ausgelost werden, macht aus der Anekdote eine echte Prüfung.","score":3}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Gustav","speech":"„Na ja, so genau muss man es auch nicht nehmen. Die Rute wird schon wissen, was sie tut. Ich schlafe jedenfalls besser, wenn ich weiß, wo die Adern liegen.“","options":[{"text":"„Vielleicht probieren wir bei Gelegenheit mal etwas zusammen aus. Bis dahin: Wenn du schlecht schläfst, lohnt sich auch ein Besuch beim Hausarzt, der sieht sich so etwas gern an.“","style":"deeskalierend","reaction":"„Hm, den Arzt habe ich tatsächlich lange nicht gesehen. Ich überlege es mir. Und das mit dem Ausprobieren... mal sehen.“","feedback":"Ein sanfter Ausstieg: Du lässt die Tür für einen späteren Test offen und lenkst auf die eigentliche Sorge, den Schlaf. Die Beziehung bleibt heil, die Sachfrage bleibt offen.","score":2}]},"step-flat":{"id":"step-flat","speaker":"Gustav","speech":"„Ich zeige dir morgen, wie man die Rute hält! Und wenn du Glück hast, ist dein Schlafzimmer auch ein Treffer. Dann wissen wir beide Bescheid, und alle Nachbarn können es nachmachen!“","options":[{"text":"Ende: Ihr beide seid jetzt überzeugt, ohne je geprüft zu haben. Gustav fühlt sich bestätigt, und aus einem Gefühl ist im Quartier eine „Tatsache“ geworden.","style":"ausstieg","reaction":"Mitmachen ist freundlich, aber ohne Prüfung bleibt die Behauptung eine Anekdote.","feedback":"Eine begeisterte Erfolgsgeschichte steht ganz unten auf der Evidenzpyramide. Ohne Gegenprobe wird sie durch Wiederholung nicht stärker, nur lauter.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Gustav","speech":"„Weißt du was? Mit dir rede ich darüber nicht mehr. Meine Rute und ich, wir wissen, was wir tun.“ *Er dreht sich um und schließt das Gartentor etwas lauter als nötig.*","options":[{"text":"Ende: Gustav fühlt sich angegriffen und hält jetzt noch fester an seiner Rute fest. Die Chance auf einen fairen Test ist erst einmal vertan.","style":"ausstieg","reaction":"Wer die Behauptung angreift, trifft den Menschen, wenn er Behauptung und Person nicht trennt.","feedback":"Wenn Gustavs Gabe zu seiner Identität gehört, fühlt sich jede Kritik wie ein Angriff auf ihn an. Hilfreicher wäre gewesen, die Behauptung zu prüfen, nicht den Menschen zu überführen.","score":0}]}},"status":"entwurf","familie":"fair-testen","fertigkeit":"F1","stufe":2,"kurz":"Eine Erfolgsgeschichte stößt eine Hypothese an, ist aber kein Beweis; erst ein kontrollierter, verblindeter Test zeigt, ob mehr als Zufall dahintersteckt. Wer eine Fähigkeit als etwas sieht, das er hat, nicht als etwas, das er ist, kann sie ohne Gesichtsverlust prüfen lassen.","prueffrage":"Wie oft wurde die Rute schon geprüft, ohne dass ihr Träger wusste, wo das Wasser tatsächlich liegt?","quellen":[{"typ":"doi","kurz":"Murad, M. H.; Asi, N.; Alsawas, M.; Alahdab, F. (2016): New evidence pyramid (Evidence-Based Medicine 21(4))","oeffentlich":true,"doi":"10.1136/ebmed-2016-110401","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4975798/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Schulz, K. F.; Grimes, D. A. (2002): Blinding in randomised trials: hiding who got what (Lancet 359)","oeffentlich":false,"doi":"10.1016/S0140-6736(02)07816-9"}],"thema":"Natur und Klima"},{"id":"scen-wildkamera-harald","title":"Haralds Wildkamera-Bild","subtitle":"Kryptozoologie, geübt mit Street Epistemology","character":"Harald, Nachbar und Hobbyjäger","avatar":"🐆","context":"Dein Nachbar Harald fängt dich am Gartenzaun ab und hält dir sein Handy hin. Auf dem Bild seiner Wildkamera zeichnet sich im Dämmerlicht ein dunkler, länglicher Schatten ab. Harald ist sich sicher: Das ist eine Großkatze, bei euch läuft unentdeckt ein Panther herum.","goal":"Bring Harald mit Street Epistemology dazu, selbst zu prüfen, wie verlässlich sein Bild als Beleg ist, ohne dass er dabei sein Gesicht verliert.","bereich":"Nachbarschaft","laenge":"mittel","ton":"heiter","bestehenAb":6,"lektion":"Nicht die Schlussfolgerung angreifen, sondern die Methode erfragen: Was macht dich sicher, und wie verlässlich ist das? Ein verschwommenes Bild ist eine Anekdote, kein Beleg. Ein unbekanntes Tier hinterlässt Kot, Spuren, Kadaver oder scharfe Fotos, und genau danach lässt sich gemeinsam suchen. Testbare Fragen und handfeste Belege statt Anekdoten: Das unterscheidet eine ernsthafte Suche nach unbekannten Tieren von Pseudowissenschaft, und der Nachbar bleibt dabei ein Nachbar.","toolRef":"H.2.2","faktenRef":"F.2.3","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Harald","speech":"„Schau dir das an! Letzte Nacht, Wildkamera am Waldrand. Das ist eine Großkatze, ein Panther, ich schwör's dir! Bei uns läuft ein Raubtier herum, und keiner glaubt mir!“","options":[{"text":"„Harald, das ist ein Schatten, mehr nicht. Ein Panther bei uns? Du fällst auf deine eigene Fantasie herein.“","style":"frontal","reaction":"„Fantasie?! Ich bin seit dreißig Jahren im Revier unterwegs! Du sitzt im Büro und willst mir erklären, was im Wald los ist? Gib mir das Handy zurück!“ *steckt das Handy beleidigt ein*","feedback":"Frontalangriff! Du greifst die Schlussfolgerung und Haralds Urteilskraft an. Er fühlt sich vorgeführt und verteidigt seine Überzeugung nur umso fester.","score":-2,"nextStepId":"step-fail"},{"text":"„Wow, ein Panther bei uns?! Harald, das ist ja Wahnsinn! Wir müssen das sofort melden, ruf die Polizei an, bevor einer unserer Hunde zu Schaden kommt!“","style":"affektiv","reaction":"„Genau, das sag ich ja! Die Polizei lacht mich aus, aber du verstehst's! Ich schick das Bild gleich an alle in der Straße, dann traut sich keiner mehr raus!“","feedback":"Du übernimmst die Behauptung ungeprüft und befeuerst die Aufregung. Mit sokratischer Neugier hat das nichts zu tun: Du klärst weder Behauptung noch Methode, sondern bestätigst sie.","score":-1,"nextStepId":"step-panic"},{"text":"„Das Bild macht einen echt neugierig, Harald! Darf ich dir ein paar Fragen dazu stellen? Mich interessiert, wie du zu dem Eindruck gekommen bist.“","style":"sokratisch","reaction":"„Klar, frag nur! Endlich mal einer, der zuhört.“ *grinst und hält dir das Handy näher hin*","feedback":"Guter Einstieg: Du holst die Erlaubnis ein und baust Beziehung auf, bevor du fragst. Das ist der erste Schritt der Street Epistemology.","score":3,"nextStepId":"step-2"}]},"step-2":{"id":"step-2","speaker":"Harald","speech":"„Also, was soll ich da groß erklären? Man sieht doch den Körper, den langen Schwanz, die Größe! Ein Fuchs oder ein Reh ist das jedenfalls nicht.“","options":[{"text":"„Auf einer Skala von 0 bis 100: Wie sicher bist du, dass dort wirklich eine Großkatze lief? Und was genau meinst du mit Panther, ein schwarzer Leopard, ein Puma?“","style":"sokratisch","reaction":"„Hm, Panther, Leopard, so genau hab ich's nie unterschieden. Eine große schwarze Katze eben. Sicher? ...Ich sag mal 90 Prozent, vielleicht 95.“","feedback":"Sehr gut: Du klärst die Behauptung und fragst nach dem Grad der Sicherheit. Die 0-100-Skala macht aus einem Ja/Nein ein flexibles Spektrum.","score":3,"nextStepId":"step-3"},{"text":"„Der Körper und der lange Schwanz, genau. Haben das nicht auch Marder, Hauskatzen oder Hunde? Außerdem fehlt dem Bild jede Größenreferenz, Harald.“","style":"frontal","reaction":"„Ein Marder, so groß wie ein Hund? Du willst mir doch nicht erzählen, ich erkenne nicht, was ich seh! Das ist doch lächerlich.“ *verschränkt die Arme*","feedback":"Inhaltlich nicht falsch, aber du lieferst Gegenargumente, bevor du Haralds Methode kennst. Das klingt nach Widerlegung statt nach Neugier und macht ihn defensiv.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Harald, im Dämmerlicht sieht jeder Busch wie ein Tier aus. Du bist da einfach voreingenommen, weil du unbedingt etwas sehen willst.“","style":"sarkastisch","reaction":"„Voreingenommen?! Ich hab jahrzehntelang Wild beobachtet! Der Nächste, der mir das sagt, kriegt das Bild nie wieder zu sehen!“","feedback":"Du unterstellst Haralds Motiv statt neugierig nach seiner Methode zu fragen. Seziert wird die Behauptung, nicht der Mensch.","score":-2,"nextStepId":"step-fail"}]},"step-3":{"id":"step-3","speaker":"Harald","speech":"„Sagen wir 95 Prozent, ich bin mir ziemlich sicher. Ich hab doch das Foto, und mein Jagdkollege Dieter hat vor einem Jahr auch was Dunkles durchs Unterholz huschen sehen. Zwei Leute, ein Tier, das passt doch!“","options":[{"text":"„95 Prozent, das ist ordentlich! Darf ich fragen, was für dich der Hauptgrund für diese Sicherheit ist? Welche Methode hat dich zu der Überzeugung geführt?“","style":"sokratisch","reaction":"„Methode? Na ja... das Foto, und dass Dieter dasselbe gesehen hat. Und mein Bauchgefühl, ehrlich gesagt. Ich kenn den Wald, da spürt man, wenn da was ist.“","feedback":"Schlüsselfrage der Street Epistemology: Du fragst nach dem Weg, nicht nach dem Ergebnis. Harald benennt selbst seine Methode: Foto, Augenzeugenbericht, Bauchgefühl.","score":3,"nextStepId":"step-4"},{"text":"„Dieters Sichtung ist ein Jahr her, Harald, und was Dunkles sehen ist kein Beweis. Ihr zwei seid euch einfach gegenseitig in eurer Wunschvorstellung bestätigt.“","style":"frontal","reaction":"„Wunschvorstellung?! Dieter ist ein nüchterner Mensch! Wenn du nur drüberbügelst, brauchen wir gar nicht weiterzureden.“","feedback":"Du bringst Argumente, bevor du Haralds Methode kennst. Das kippt das Gespräch in Verteidigung statt Reflexion. Erst die Methode erfragen.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Zwei Zeugen und ein Foto, das ist schon was. Gehen wir doch gemeinsam raus und schauen, ob wir Spuren finden. Was meinst du, wo könnte sie langgelaufen sein?“","style":"humorvoll","reaction":"„Ha, das gefällt mir! Aber an der Wegkreuzung war letzten Monat nur Matsch, da war nichts Eindeutiges zu sehen.“ *kratzt sich am Kopf*","feedback":"Brauchbar und freundlich, und die Spurensuche ist grundsätzlich ein guter Gedanke. Aber du fragst noch nicht nach Haralds Methode: Wie kommt er zu seiner Sicherheit? Das ist der Kern von „Street Epistemology“.","score":1,"nextStepId":"step-3-struggle"}]},"step-4":{"id":"step-4","speaker":"Harald","speech":"„Wenn ich's mir recht überlege: Foto, Dieters Erzählung, mein Gefühl für den Wald, das ist eigentlich alles, was ich hab. Aber reicht das nicht? Man kann doch nicht beweisen, dass es dort keinen Panther gibt!“","options":[{"text":"„Gute Frage. Lass uns mal kurz nachdenken: Könnte man mit genau diesen Methoden, Foto, Erzählung und Bauchgefühl, auch mal danebenliegen? Hast du das schon erlebt?“","style":"sokratisch","reaction":"„Hm... danebengelegen, ja, klar. Einmal hab ich nachts einen Wildschweinkeiler gesehen, und am Morgen war es ein Baumstumpf. Das hält mir Dieter heut noch vor.“ *lacht verlegen*","feedback":"Treffer: Du prüfst die Zuverlässigkeit der Methode, das Herzstück von „Street Epistemology“. Anekdoten und Augenzeugenberichte stehen auf den untersten Stufen der Evidenz-Hierarchie, und Harald erkennt das selbst.","score":3,"nextStepId":"step-5"},{"text":"„Harald, die Beweislast liegt bei dem, der etwas behauptet. Du musst den Panther belegen, ich muss nicht beweisen, dass es keinen gibt.“","style":"frontal","reaction":"„Ach, jetzt kommst du mit Fachgeschwafel. Ich hab ein Bild, du hast nur eine Theorie!“ *wedelt mit dem Handy*","feedback":"Richtig im Kern (Beweislastumkehr), aber als Lehrsatz vorgetragen. Harald hört Besserwisserei statt Einladung zum Nachdenken.","score":0,"nextStepId":"step-5-struggle"},{"text":"„Stimmt, beweisen kann man das nicht. Vielleicht läuft ja wirklich was herum, wer weiß? Ich würde an deiner Stelle einfach weiter filmen und abwarten.“","style":"ausstieg","reaction":"„Siehst du, genau das sag ich! Ich hänge gleich drei weitere Kameras auf, und dann haben wir ihn!“ *strahlt*","feedback":"Du weichst aus. Harald fühlt sich bestätigt und nimmt seine Methode nicht in den Blick. Zuhören ist gut, aber ohne die Methodenfrage bleibt er, wo er war.","score":-1,"nextStepId":"step-5-struggle"}]},"step-5":{"id":"step-5","speaker":"Harald","speech":"„Gut, gut, Bauchgefühl kann täuschen, das geb ich zu. Aber trotzdem: Wenn da wirklich ein Panther rumläuft, wie würde man das denn dann feststellen? Was würde dich denn überzeugen?“","options":[{"text":"„Gute Frage! Was hinterlässt ein großes Raubtier normalerweise, Kot, Spuren, gerissenes Wild? Und könnte ein einzelnes Tier hier überhaupt dauerhaft leben? Was davon würdest du am ehesten finden?“","style":"sokratisch","reaction":"„Kot und Spuren, klar... Und gerissenes Wild müsste ich als Jäger eigentlich längst gefunden haben, wenn da ein Panther sein Revier hätte. Hm. Und allein überlebt so ein Tier ja auch nicht ewig. Das ist ein Argument.“","feedback":"Sehr gut: Du lenkst auf verlässlichere Belege (Kot, Spuren, Kadaver, scharfes Foto) und stellst die Populationsfrage als Frage. Harald kommt selbst darauf, was fehlt. Verlässlichere Methoden ins Spiel zu bringen ist der letzte Schritt in „Street Epistemology“.","score":3,"nextStepId":"step-6-success"},{"text":"„Dann brauchen wir ein besseres Bild als das hier, am besten bei Tageslicht und scharf. Gib mir einfach Bescheid, wenn deine Kamera mal was Klareres erwischt.“","style":"deeskalierend","reaction":"„Das klingt vernünftig. Ich stell die Kamera um, dann sehen wir mehr. Danke, dass du nicht gleich gelacht hast.“","feedback":"Freundlich und brauchbar: Du benennst ein besseres Beweismittel, ohne zu belehren. Etwas konkreter (Spuren, Kot, Kadaver) wäre noch stärker gewesen.","score":2,"nextStepId":"step-6-success"},{"text":"„Ehrlich, Harald, das ist ein verschwommener Fleck. Dafür kriegst du bei der Zeitung höchstens ein müdes Lächeln, bei Wissenschaftlern erst recht.“","style":"sarkastisch","reaction":"„Pfff, dann eben nicht. Ich hab's ja schon gewusst: Hier will keiner was Neues hören!“ *dreht sich um und geht*","feedback":"Der Spott beschädigt das Gespräch genau dort, wo Harald gerade öffnete. Mit Verspottung gewinnt man keinen Zweifel.","score":-2,"nextStepId":"step-fail"}]},"step-5-struggle":{"id":"step-5-struggle","speaker":"Harald","speech":"„Drei Kameras, das wird was! Aber ehrlich, alle anderen winken ab, wenn ich davon anfange. Was meinst du, was soll ich als Nächstes tun?“","options":[{"text":"„Ich winke nicht ab, Harald, das Bild interessiert mich wirklich. Lass uns schauen, was sich am Waldrand an Spuren finden lässt. Sind es echte, wissen wir mehr, und wenn nicht, ist es auch ein Ergebnis.“","style":"deeskalierend","reaction":"„Das klingt fair. Samstag früh, bevor der Matsch wieder alles zertrampelt? Und ich bring den Kaffee mit.“","feedback":"Gut: Du holst das Gespräch mit einem prüfbaren Vorschlag zurück. Wer nach Spuren sucht, folgt der Logik der Grenzwissenschaft, und die Beziehung bleibt heil.","score":2},{"text":"„Vielleicht lässt du die Kameras einfach hängen, und wir schauen in ein paar Wochen, ob sich was zeigt. Bis dahin lohnt es nicht, sich aufzuregen.“","style":"ausstieg","reaction":"„Ja, du hast recht. Abwarten und Tee trinken. Danke für's Zuhören.“","feedback":"Ein freundlicher Rückzug, der die Beziehung wahrt. Die Methodenfrage bleibt aber offen.","score":1}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Harald","speech":"„Weißt du was, ich merk schon, du hältst mich für einen Spinner. Dabei hab ich nur ein Bild gezeigt. Das war mal wieder typisch.“","options":[{"text":"„Moment, Harald, so war das nicht gemeint. Ich will verstehen, wie du darauf kommst. Magst du erzählen, was dich bei dem Bild am meisten überzeugt?“","style":"deeskalierend","reaction":"„Na gut. Eigentlich der Körperbau und dass sich da jemand lautlos bewegt. Das ist kein Fuchs, das spür ich. Und Dieter hat ja auch schon was gesehen.“ *entspannt sich etwas*","feedback":"Gute Reparatur: Du entschuldigst die Schärfe und lenkst zurück zu echter Neugier. So kommst du wieder an Haralds Methode heran.","score":2,"nextStepId":"step-4"},{"text":"„Dann belassen wir es dabei. Pass auf dich auf im Wald, ja? Ich muss auch weiter, der Kaffee wartet schon, und ich will die Pause nicht verpassen.“","style":"ausstieg","reaction":"„Ja, mach's gut.“ *brummt und geht*","feedback":"Ein Rückzug, ohne Haralds Methode erfragt zu haben. Er geht mit dem Gefühl, nicht ernst genommen worden zu sein.","score":0,"nextStepId":"step-fail"}]},"step-6-success":{"id":"step-6-success","speaker":"Harald","speech":"„Weißt du was? Ich hänge eine zweite Kamera auf, an der Suhle, mit Tageslicht-Blitz, und schaue Samstag nach Spuren. Wenn da ein Panther ist, kriegen wir ihn scharf. Und wenn nicht... dann war's wohl ein Baumstumpf.“ *lacht*","options":[{"text":"„Das find ich stark, Harald. Hauptsache, wir prüfen es richtig, egal wie es ausgeht. Ich bring Kuchen mit, dann machen wir einen Spurensuche-Tag draus.“","style":"humorvoll","reaction":"„Abgemacht! Aber wehe, es ist am Ende doch nur ein Fuchs, dann zahlst du die Runde.“ *grinst und klopft dir auf die Schulter*","feedback":"Mission gelungen! Harald hat selbst eine verlässlichere Methode gewählt, und die Nachbarschaft bleibt heil. Genau das will Street Epistemology erreichen: einen kleinen Stein des Zweifels, kein Geständnis.","score":3}]},"step-fail":{"id":"step-fail","speaker":"Harald","speech":"„Ich hab keine Lust mehr, mir das anzuhören. Du glaubst mir ja doch nicht.“ *geht ins Haus und schlägt die Gartentür zu*","options":[{"text":"Ende: Harald fühlte sich nicht ernst genommen und hält jetzt erst recht an seinem Panther fest. Rechthaben und Überzeugen sind zweierlei.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst Erlaubnis einholen und die Methode erfragen, bevor es um Schlussfolgerungen geht.","feedback":"Frage dich: Wollte ich Harald überzeugen oder verstehen? Street Epistemology beginnt mit Neugier statt Widerspruch.","score":0}]},"step-panic":{"id":"step-panic","speaker":"Harald","speech":"„Ich hab das Bild schon in die Nachbarschaftsgruppe gestellt! Die ersten fragen, ob sie die Kinder noch draußen spielen lassen sollen. Ich sag's dir, bald hängt der ganze Ort am Zaun!“","options":[{"text":"Ende: Aus einem unscharfen Bild wurde eine Ortspanik, weil niemand nach Methode und Belegen gefragt hat.","style":"ausstieg","reaction":"Wer nur zustimmt, hilft nicht: Ohne Rückfragen bleibt aus einer Vermutung eine Gewissheit.","feedback":"Neugier heißt nicht Zustimmung. Street Epistemology fragt nach Behauptung, Sicherheit und Methode, statt die Behauptung mitzutragen.","score":0}]}},"status":"entwurf","familie":"population-und-spuren","fertigkeit":"F1","stufe":3,"kurz":"Statt die Schlussfolgerung anzugreifen, frag nach der Methode: Was macht dich sicher, und wie verlässlich ist das? Ein unscharfes Bild ist eine Anekdote; ein unbekanntes Tier hinterließe Kot, Spuren oder Risse, und genau danach lässt sich gemeinsam suchen.","prueffrage":"Welche Spuren müsste ein großes Raubtier in diesem Wald hinterlassen, und wie viele davon hat bisher jemand tatsächlich gefunden?","quellen":[{"typ":"doi","kurz":"Sykes, B. C. u. a. (2014): Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates (Proc. R. Soc. B 281)","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4100498/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kubodera, T.; Mori, K. (2005): First-ever observations of a live giant squid in the wild (Proc. R. Soc. B 272)","oeffentlich":true,"doi":"10.1098/rspb.2005.3158","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1559985/","abruf":"2026-10-12"},{"typ":"url","kurz":"Street Epistemology International: Startseite (Selbstbeschreibung der Methode)","oeffentlich":true,"url":"https://streetepistemology.com/","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"scen-onkel-heilfasten-erkaeltung","title":"Onkel Willis Schwitzkur","subtitle":"Erkältung „ausschwitzen“, geübt mit der Ausstiegs-Strategie","character":"Onkel Willi","avatar":"🧣","context":"Beim Familienkaffee erzählt dir Onkel Willi stolz, seine Erkältung sei nur deshalb weg, weil er zwei Tage in die Sauna gegangen ist und „alles ausgeschwitzt“ hat. Er ist begeistert und will das gleich der ganzen Verwandtschaft als Geheimtipp mitgeben.","goal":"Führe Willi mit neugierigen Fragen zum natürlichen Krankheitsverlauf und erkenne den Moment, in dem ein eleganter Ausstieg besser ist als weitere Überzeugungsarbeit.","bereich":"Familie","laenge":"kurz","ton":"heiter","bestehenAb":4,"lektion":"Erkältungen klingen von selbst ab, und wer erst am Höhepunkt der Beschwerden etwas „unternimmt“, schreibt die ohnehin fällige Besserung der letzten Maßnahme zu (natürlicher Krankheitsverlauf und Regression zur Mitte). Mit einer neugierigen Frage öffnest du mehr Türen als mit einer Belehrung. Wenn ein Gespräch sich im Kreis dreht, ist ein ruhiger, freundlicher Ausstieg kein Scheitern, sondern ein Schutz für dich und für die Beziehung.","toolRef":"H.2.4","faktenRef":"C.4.6","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Onkel Willi","speech":"„Sag mal, wisst ihr, was meine Erkältung geheilt hat? Die Sauna! Zwei Tage rein, alles raus geschwitzt, und zack: wie neugeboren! Das solltet ihr alle machen, Leute!“","options":[{"text":"„Willi, Schwitzen hat mit Erkältungen nichts zu tun. Die Besserung kam von allein, das ist bei einer Erkältung immer so. Du erzählst da Unsinn.“","style":"frontal","reaction":"„Unsinn?! Ich hab das am eigenen Leib erlebt, und du kommst mir mit Theorie! *verschränkt die Arme* Ich weiß, was bei mir gewirkt hat!“","feedback":"Der Kern stimmt (Erkältungen sind selbstlimitierend), aber „Du erzählst Unsinn“ wertet seine Erfahrung ab. Willi geht in Verteidigung, und die Sache gerät in den Hintergrund.","score":-2,"nextStepId":"step-fail"},{"text":"„Schön, dass es dir wieder gut geht! Sag mal, wie ging es dir eigentlich vor der Sauna: Wann hat die Erkältung angefangen, und wie schlimm war es an dem Tag, an dem du in die Sauna bist?“","style":"sokratisch","reaction":"„Hm, lass mich überlegen... Angefangen hat's am Montag mit Kratzen im Hals. Am Mittwoch war es am schlimmsten, da hab ich kaum geradeaus gucken können. Da bin ich dann in die Sauna.“","feedback":"Sehr gut! Mit offenen, neugierigen Fragen (Street Epistemology) rückst du den Zeitpunkt der Maßnahme ins Blickfeld: Willi hat am Höhepunkt der Beschwerden gehandelt, die Grundlage für den Verlaufs-Irrtum.","score":3,"nextStepId":"step-2"},{"text":"„Ach, super, Willi! Dann geh ich nächste Woche auch gleich in die Sauna, bevor mich die Erkältung erwischt. Welche Temperatur war es denn?“","style":"humorvoll","reaction":"„Neunzig Grad, mein Lieber, nicht weniger! Und danach kalt abduschen. So muss das! Ich schreib dir die Zeiten auf.“","feedback":"Freundlich, aber du bestätigst die Zuschreibung, ohne sie zu hinterfragen. Der Verlaufs-Irrtum bleibt unberührt, Willi fühlt sich bestärkt.","score":-1,"nextStepId":"step-bestaetigt"}]},"step-2":{"id":"step-2","speaker":"Onkel Willi","speech":"„Siehst du, genau am schlimmsten Tag hab ich zugeschlagen, und dann ging es bergauf! Das beweist doch, dass die Sauna gewirkt hat! Oder etwa nicht?“","options":[{"text":"„Gut möglich, dass es sich gut angefühlt hat. Bei einer Erkältung geht es aber nach dem schlimmsten Tag ohnehin meist bergauf, das passiert auch ganz ohne Sauna. Ob die Sauna selbst etwas bewirkt hat, lässt sich aus einem einzelnen Fall nicht sagen.“","style":"sokratisch","reaction":"„Hm... nach dem schlimmsten Tag geht's von selbst bergauf? ...Da hab ich noch nie so drüber nachgedacht. Aber ich hab mich nach der Sauna wirklich so befreit gefühlt!“","feedback":"Sachlich und warm: Du erklärst den natürlichen Verlauf, ohne seinen Erfolg kleinzureden. Allerdings gibst du ihm die Erkenntnis vor, statt ihn selbst darauf kommen zu lassen.","score":2,"nextStepId":"step-3-success"},{"text":"„Wenn ich dich richtig verstehe: Sauna hilft, Punkt. Und die Millionen Leute, die ohne Sauna wieder gesund werden, haben einfach Glück gehabt?“","style":"sarkastisch","reaction":"„Willst du mich veräppeln?! Mach dich nur lustig! Ich weiß, was ich weiß, und dir erzähl ich gar nichts mehr!“","feedback":"Sarkasmus wertet Willi ab und trifft nicht den Kern. Das Gespräch kippt, obwohl du inhaltlich nah dran warst („Seziert wird die Behauptung, nicht der Mensch“).","score":-2,"nextStepId":"step-fail"},{"text":"„Eine gute Frage! Nehmen wir mal an, du wärst am schlimmsten Tag einfach im Bett geblieben und hättest nichts gemacht: Was meinst du, wie es dir zwei Tage später gegangen wäre?“","style":"sokratisch","reaction":"„Na ja... besser wahrscheinlich auch. Das ist ja meistens so bei einer Erkältung, nach dem dritten Tag wird's bei mir immer leichter. Hm. Stimmt eigentlich.“","feedback":"Meisterhaft! Du lässt Willi selbst das Gedankenexperiment machen (Vergleich mit „nichts tun“, Kontrollgruppe im Kopf). Er entdeckt den natürlichen Verlauf eigenständig, Street Epistemology in Reinform.","score":3,"nextStepId":"step-3-success"}]},"step-3-success":{"id":"step-3-success","speaker":"Onkel Willi","speech":"„Na gut, vielleicht wär's auch so besser geworden. Aber die Sauna war trotzdem schön! Und ich geh bestimmt weiter, das tut mir einfach gut. *zwinkert*“","options":[{"text":"„Das glaube ich dir sofort, ein schöner Saunagang ist ja was Feines. Nur als Erkältungsmittel würde ich ihn nicht mehr verkaufen. Und jetzt: Kuchen?“","style":"humorvoll","reaction":"„Haha, erwischt! Gut, kein Wundermittel, aber Kuchen ist ein sehr gutes Argument! *schiebt dir den Teller zu*“","feedback":"Gelungen! Willi darf sein Saunaerlebnis behalten, nur die Heilversprechen sind vom Tisch. Das Gespräch endet warm und mit offenem Ohr, nicht mit Sieg und Niederlage.","score":3},{"text":"„Genau, und beim nächsten Mal bist du dann auch ohne Sauna schnell wieder fit. Also bleibt die Sauna eher ein Hobby, kein Heilmittel.“","style":"sokratisch","reaction":"„Na ja, wenn du so willst. Ich geh trotzdem, ich mag die Wärme.“","feedback":"In der Sache richtig, aber du fasst für ihn zusammen, statt ihm den Schluss selbst zu überlassen. Brauchbar, ohne den Raum für sein eigenes Fazit zu nutzen.","score":1},{"text":"„Siehst du, ich hab's ja gewusst, dass du es einsiehst. Wieder jemand überzeugt, und das ganz ohne lange Diskussion!“","style":"frontal","reaction":"„Überzeugt? Ich hab nur gesagt, dass die Sauna schön ist. Bild dir nichts ein, mein Lieber!“","feedback":"Siegerpose! Wer nach einem Erfolg auftrumpft, riskiert, dass der andere sein Gesicht wahren will und wieder zurückrudert. Es geht um Verständnis, nicht um Punkte.","score":-1}]},"step-bestaetigt":{"id":"step-bestaetigt","speaker":"Onkel Willi","speech":"„Siehst du, wenigstens einer, der mich versteht! Die anderen glauben mir ja nie! Und jetzt erzähl ich dir auch noch, was ich gegen Rückenschmerzen mache, das ist noch besser!“","options":[{"text":"„Willi, bevor du weiterredest: Bei der Erkältung war es eigentlich anders, als es aussieht. Nach dem schlimmsten Tag wird es bei so einer Erkältung meistens von allein besser, ganz ohne Sauna.“","style":"frontal","reaction":"„Eben warst du noch auf meiner Seite, und jetzt fällst du mir in den Rücken? Du weißt auch nicht, was du willst!“","feedback":"Der Umschwung kommt zu abrupt: Erst bestätigen, dann widersprechen, das verunsichert und wirkt unehrlich. Besser wäre gewesen, von Anfang an neugierig zu fragen.","score":-2,"nextStepId":"step-fail"},{"text":"„Haha, Willi, ich sehe schon, du hast für alles ein Mittelchen. Ich merke aber: Wir drehen uns gerade im Kreis. Lass uns lieber den Kuchen genießen, ja?“","style":"ausstieg","reaction":"„Haha, na gut, wenn du meinst! Aber die Rückengeschichte erzähl ich dir noch, Kuchen hin oder her! *greift trotzdem zum Teller*“","feedback":"Der freundliche Themenwechsel schützt die Stimmung und deine Energie. Für einen echten Ausstieg ist es aber noch zu früh: Willi ist nicht unredlich, und du hast noch keinen echten Versuch gemacht, das Gespräch auf die Sache zu lenken. So bleibt offen, was am Verlauf dran ist.","score":1},{"text":"„Gern, aber erst eine Frage: Wann hast du mit der Sauna angefangen, am ersten Tag oder erst, als es richtig schlimm war? Das würde mich echt interessieren.“","style":"sokratisch","reaction":"„Hm, tatsächlich erst, als es richtig schlimm war, am dritten Tag. Warum fragst du?“","feedback":"Gut gerettet! Mit einer neugierigen Frage kommst du doch noch zum entscheidenden Zeitpunkt. Der Einstieg war holprig, aber nicht verloren.","score":2,"nextStepId":"step-2"}]},"step-fail":{"id":"step-fail","speaker":"Onkel Willi","speech":"„Weißt du was? Das bringt doch nichts. Du hörst mir nicht zu, und ich hör dir auch nicht mehr zu. Ich geh mir jetzt den Kaffee nachfüllen.“ *steht auf und geht in die Küche*","options":[{"text":"Ruhig bleiben und freundlich hinterhergehen: „Willi, ich möchte nicht, dass wir im Streit auseinandergehen. Lass uns das Thema beiseitelegen, ich helf dir mit dem Kaffee.“","style":"ausstieg","reaction":"„*schnaubt, aber lächelt schief* Na gut. Aber nur, weil der Kuchen sonst kalt wird.“","feedback":"Der ruhige, freundliche und begründete Ausstieg rettet, was zu retten ist: Die Beziehung bleibt heil, das Thema kann ein andermal wieder aufkommen. Besser als ein Rückzug im Streit.","score":2},{"text":"Hinterherrufen: „Weglaufen hilft auch nichts, Willi! Die Fakten bleiben dieselben, ob du sie hören willst oder nicht, und das weißt du genau!“","style":"frontal","reaction":"„*knallt die Küchentür zu* Ich will davon nichts mehr hören!“","feedback":"Ein Sieg im Streit ist hier eine Niederlage für das Gespräch. Der Ausstieg wirkt nur, wenn er ruhig und ohne Nachtreten passiert.","score":-2},{"text":"Einfach sitzen bleiben, den Kuchen essen und später beim Abschied sagen: „Schön war's, Willi. Wir können gern ein andermal weiterquatschen, wenn du magst.“","style":"deeskalierend","reaction":"„*brummt versöhnlich* Mal sehen. Bis bald, mein Junge.“","feedback":"Gelassen: Du lässt Willi Raum und die Tür offen. Ein bewusster, ruhiger Ausstieg im Moment selbst hätte die Wogen aber schneller geglättet als Schweigen bis zum Abschied.","score":1}]}},"status":"entwurf","familie":"was-waere-ohne","fertigkeit":"F2","stufe":1,"kurz":"Erkältungen klingen von selbst ab. Wer erst am schlimmsten Tag etwas unternimmt, schreibt die ohnehin fällige Besserung leicht dem Mittel zu. Eine neugierige Frage öffnet mehr als eine Belehrung; dreht sich das Gespräch im Kreis, schützt ein freundlicher Ausstieg die Beziehung.","prueffrage":"An welchem Tag der Erkältung begann die Kur, und wie lief eine Erkältung früher ab, als es keine Kur gab?","quellen":[{"typ":"url","kurz":"IQWiG / gesundheitsinformation.de: Erkältung","oeffentlich":true,"url":"https://www.gesundheitsinformation.de/erkaeltung.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Morton, V.; Torgerson, D. J. (2003): Effect of regression to the mean on decision making in health care (BMJ 326)","oeffentlich":true,"doi":"10.1136/bmj.326.7398.1083","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1125994/","abruf":"2026-10-12"},{"typ":"url","kurz":"NHS: Common cold","oeffentlich":true,"url":"https://www.nhs.uk/conditions/common-cold/","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"scen-sprachnachricht-fake","title":"Erikas Sprachnachricht vom Cousin des Polizisten","subtitle":"Kettennachrichten und Hörensagen, geübt mit dem Management emotionaler Kosten","character":"Erika, Tante","avatar":"📱","context":"Deine Tante Erika schickt dir abends eine aufgeregte Sprachnachricht in den Familienchat: Im Stadtpark seien Banden unterwegs, man solle sie bloß weiterleiten. Die Nachricht stamme vom Cousin von Hannelores Nachbarin, der jemanden bei der Polizei kenne. Dann ruft sie dich an.","goal":"Nimm Erikas Sorge ernst, kläre freundlich, warum eine Nachricht aus dritter Hand kein Beleg ist, und achte dabei auf deine eigene Energie.","bereich":"Familie","laenge":"mittel","ton":"ernst","bestehenAb":6,"lektion":"Falsches und Aufwühlendes wird oft weitergetragen, weil Menschen es ungeprüft teilen, und eine Quelle aus dritter Hand ist kein Beleg, auch wenn sie dringend klingt. Hilfreicher als ein Beweisgefecht ist eine ruhige Frage: Woher weiß der Erste in der Kette das? Und nicht jede Diskussion muss heute Abend zu Ende geführt werden: Das Management emotionaler Kosten heißt, die Kämpfe zu wählen, die man kämpfen kann, und die Beziehung zu erhalten.","toolRef":"H.1.2","faktenRef":"E.4.3","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Erika","speech":"„Hast du meine Sprachnachricht gehört? Im Stadtpark treiben sich Banden herum, eine Frau wurde schon überfallen! Das weiß ich vom Cousin von Hannelores Nachbarin, und der kennt einen Polizisten, der muss es ja wissen! Leite das sofort an alle weiter!“","options":[{"text":"„Erika, das ist ein typischer Fake! Hörensagen von Hörensagen, da ist nichts dran. Und hör auf, so einen Quatsch an die ganze Familie zu schicken.“","style":"frontal","reaction":"„Quatsch?! Ich will euch nur schützen! Und wenn dann wirklich etwas passiert, bist du schuld! Immer machst du alles schlecht!“","feedback":"Frontalangriff: Die Sache mag stimmen, aber Erika hört, dass ihre Fürsorge als Dummheit abgetan wird. Die Abwehr verhärtet sich.","score":-2,"nextStepId":"step-fail"},{"text":"„Du machst dir Sorgen um uns, das merke ich, und das ist lieb von dir. Magst du mir erzählen, wie die Nachricht bei dir angekommen ist? Wer hat sie dir geschickt?“","style":"deeskalierend","reaction":"„*atmet durch* Hannelore hat sie mir geschickt, die hat sie von ihrer Nachbarin. Die sagt, deren Cousin kennt einen von der Polizei... Ich war ganz durcheinander.“","feedback":"Gut: Du nimmst die Sorge ernst und bestätigst den Inhalt nicht. Ganz im Sinne von „Das Management emotionaler Kosten“ schützt du zuerst die Beziehung, statt einen Streit zu gewinnen, und holst die Kette ruhig ans Licht.","score":3,"nextStepId":"step-2"},{"text":"„Ach du meine Güte, Erika! Dann gehe ich heute Abend bestimmt nicht mehr raus. Ich leite es gleich an meine Freunde weiter, damit niemand in den Park geht!“","style":"affektiv","reaction":"„Genau! Schick es überall hin, auch an die Nachbarn. Je mehr es wissen, desto besser!“","feedback":"Du übernimmst die Angst und trägst die Kette weiter. Falsches verbreitet sich vor allem, weil Menschen es ungeprüft teilen, und so prüft niemand die Quelle.","score":-1,"nextStepId":"step-panic"}]},"step-2":{"id":"step-2","speaker":"Erika","speech":"„Also, die Nachricht war richtig dringlich, mit Ausrufezeichen und allem. Und die Stimme klang total aufgeregt. Das erfindet doch keiner, oder? Warum sollte jemand so etwas schicken, wenn nichts dran ist?“","options":[{"text":"„Dass sie so aufgeregt klingt, heißt nur, dass jemand aufgeregt ist, nicht dass es stimmt. Und dringliche Nachrichten wie diese werden einfach häufiger weitergeleitet, genau deshalb schreit sie so.“","style":"frontal","reaction":"„Du hast immer eine Erklärung parat. Aber ob du recht hast, weiß ich trotzdem nicht...“ *klingt unsicher, aber leicht gekränkt*","feedback":"Inhaltlich richtig: Aufwühlendes und Falsches wird oft weitergetragen. Aber du lieferst die Antwort fertig, statt Erika selbst mitdenken zu lassen.","score":1,"nextStepId":"step-3-struggle"},{"text":"„Gute Frage. Spielen wir mal Detektiv: Die erste Person in der Kette, die wirklich dabei war oder bei der Polizei ist, wer wäre das? Und wüsste man bei so einer Warnung, wann und wo genau das passiert sein soll?“","style":"sokratisch","reaction":"„Hm... der erste in der Kette? Das wäre der Polizist. Aber den kennt ja keiner persönlich. Und wann das war... steht gar nicht drin. Nur ‚im Stadtpark‘.“","feedback":"Stark: Mit Detektivfragen erkennt Erika selbst, dass eine Quelle aus dritter Hand kein Beleg ist und Angaben fehlen. Das ist ein Gespräch, das man laut „Das Management emotionaler Kosten“ kämpfen kann: Sie stellt echte Fragen und ist offen.","score":3,"nextStepId":"step-3-success"},{"text":"„Du hast recht, so aufgeregt kann das keiner erfinden. Sicherheitshalber leite ich es weiter, wer weiß, vielleicht rettet es jemandem etwas.“","style":"affektiv","reaction":"„Siehst du, ich wusste es! Gut, dass wenigstens du mich verstehst. Schick es an alle!“","feedback":"Du belohnst die Kette mit Reichweite. Eine aufgeregte Stimme ist kein Beleg. Falschmeldungen verbreiten sich vor allem, weil Menschen sie ungeprüft teilen.","score":-2,"nextStepId":"step-fail"}]},"step-3-success":{"id":"step-3-success","speaker":"Erika","speech":"„Dann weiß ja eigentlich niemand etwas Genaues. Ich habe das alles nur geglaubt, weil es so dringend klang. Aber was, wenn trotzdem etwas dran ist? Ich möchte nicht, dass jemandem etwas passiert.“","options":[{"text":"„Dann prüfen wir es gemeinsam: Wir schauen auf der Seite der örtlichen Polizei nach und sagen den anderen im Chat, dass die Meldung unbestätigt ist.“","style":"sokratisch","reaction":"„Das ist ein guter Plan. Dann habe ich keine falsche Panik verbreitet, aber auch nichts verschwiegen. Und morgen sehen wir nach, ja?“","feedback":"Du bietest einen überprüfbaren Weg an, statt Erika allein mit ihrer Sorge zu lassen. Die Sachfrage wird gemeinsam geklärt, die Beziehung bleibt heil.","score":3},{"text":"„Ach was, da ist nichts dran. Lösch das einfach und vergiss es, darüber musst du dir wirklich keine Gedanken machen. Solche Nachrichten sind fast immer Quatsch.“","style":"frontal","reaction":"„*zögert* Na gut... aber so ganz beruhigt bin ich nicht. Ich hätte schon gern gewusst, wie man das nachprüft.“","feedback":"Die Sache ist richtig eingeordnet, aber Erika bleibt mit ihrer Sorge allein. Ohne Prüfweg bleibt der Zweifel offen.","score":1},{"text":"„Mach dir mal keine Sorgen. Beim nächsten Mal fragst du einfach mich, bevor du so etwas schickst, dann sparen wir uns die ganze Aufregung.“","style":"deeskalierend","reaction":"„Ich frage dich ja gern. Aber ich will auch selbst verstehen, wie man das herausfindet.“","feedback":"Freundlich, aber du machst dich zur Prüfstelle, statt Erika ein eigenes Werkzeug zu geben. Nachhaltiger ist die gemeinsame Prüffrage.","score":1}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Erika","speech":"„Ich weiß nicht... Du sagst, es ist nichts dran, aber was, wenn doch? Ich bin jetzt völlig durcheinander. Soll ich es nun weiterleiten oder nicht?“","options":[{"text":"„Leite es heute Abend einfach nicht weiter, das genügt. Morgen schaue ich mit dir auf die Seite der örtlichen Polizei, dann wissen wir mehr. Jetzt trinken wir erst mal einen Tee.“","style":"ausstieg","reaction":"„Ja, gut. Dann warte ich bis morgen. Danke, dass du dir Zeit nimmst, Kind.“","feedback":"Gut im Sinne von „Das Management emotionaler Kosten“: Du weißt, wann man ein Thema ruhen lässt. Kein Streit heute Abend, die Klärung kommt morgen in Ruhe, und die Beziehung bleibt heil.","score":2},{"text":"„Dann lass uns jetzt alle Gruppen und Chats durchgehen und überall richtigstellen, dass das erfunden ist, auch bei Hannelore und ihrer Nachbarin.“","style":"frontal","reaction":"„Das ist doch viel zu viel für heute Abend! Ich bin müde und will keinen Streit mit Hannelore.“","feedback":"Du verschwendest Energie an allen Fronten gleichzeitig. Das Management emotionaler Kosten rät, die Kämpfe zu wählen, nicht jeden Brand zu löschen.","score":-1},{"text":"„Mach, was du für richtig hältst, Erika. Ich bin müde und habe keine Lust mehr auf das Thema, ich kann dir da jetzt wirklich nicht weiterhelfen.“","style":"ausstieg","reaction":"„Na gut, wenn du so redest, schicke ich es eben weiter.“ *legt etwas verstimmt auf*","feedback":"Der Rückzug ist gesund, aber ohne warmen Ton wirkt er wie Desinteresse. Wer ein Thema ruhen lässt, braucht dazu ein Angebot für später.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Erika","speech":"„Du nimmst mich nicht ernst. Dann frage ich eben Hannelore, die versteht mich wenigstens!“ *legt auf*","options":[{"text":"Ende: Erika fühlte sich nicht gehört und sucht Rückhalt dort, wo die Nachricht herkam. Rechthaben und Helfen sind zweierlei.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst die Sorge ernst nehmen, dann die Quelle gemeinsam prüfen.","feedback":"Frag dich: Wollte ich Erika beruhigen oder Recht behalten? Die Empathie-Matrix ordnet die Reihenfolge.","score":0}]},"step-panic":{"id":"step-panic","speaker":"Erika","speech":"„Siehst du, jetzt verstehen wir uns! Ich schicke es auch an die Nachbarn und stelle es in die Stadtteil-Gruppe. Je mehr wissen, desto besser! Und morgen rufe ich beim Bürgermeister an!“","options":[{"text":"Ende: Eine ungeprüfte Warnung wandert weiter und macht anderen Angst. Wer mitzittert, kann Erika nicht helfen.","style":"ausstieg","reaction":"Mitgefühl ja, Mitpanik nein: Nur wer selbst ruhig bleibt, kann Halt geben.","feedback":"Weiterleiten trägt die Warnung weiter. Laut einer großen Twitter-Studie verbreitet sich Falsches weiter als Wahres, weil Menschen es häufiger teilen. Besser: Sorge ernst nehmen, Quelle erfragen, nicht weiterleiten.","score":0}]}},"status":"entwurf","familie":"quelle-zurueckverfolgen","fertigkeit":"F1","stufe":2,"kurz":"Eine Nachricht aus dritter Hand ist kein Beleg, auch wenn sie dringend klingt; Aufwühlendes wird oft ungeprüft weitergeleitet. Hilfreicher als ein Beweisgefecht ist die ruhige Frage, woher der Erste in der Kette es weiß. Und nicht jede Diskussion muss heute Abend enden.","prueffrage":"Wer in der Kette hat das Ereignis selbst erlebt, und welche Angaben zu Zeit und Ort enthält die Nachricht?","quellen":[{"typ":"doi","kurz":"Fazio, L. K. (2020): Pausing to consider why a headline is true or false can help reduce the sharing of false news (HKS Misinformation Review 1(2))","oeffentlich":true,"doi":"10.37016/mr-2020-009","url":"https://misinforeview.hks.harvard.edu/article/pausing-reduce-false-news/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Vosoughi, S.; Roy, D.; Aral, S. (2018): The spread of true and false news online (Science 359)","oeffentlich":false,"doi":"10.1126/science.aap9559"},{"typ":"doi","kurz":"Pennycook, G. u. a. (2021): Shifting attention to accuracy can reduce misinformation online (Nature 592)","oeffentlich":false,"doi":"10.1038/s41586-021-03344-2"}],"thema":"Netz und Medien"},{"id":"scen-vegan-fehlschluss-arbeit","title":"Svens Entweder-oder","subtitle":"Falsches Dilemma, geübt mit der Deeskalations-Matrix","character":"Sven, Teamkollege","avatar":"🥗","context":"In der Kaffeeküche hast du erzählt, dass du mittags manchmal eine Currywurst isst. Dein Teamkollege Sven stellt seine Müslischale ab und verkündet laut, es gebe nur zwei Möglichkeiten: entweder du isst nur Bio-Gemüse, oder du nimmst die Umweltzerstörung in Kauf. Die anderen im Raum sehen gespannt zu.","goal":"Erkenne das falsche Dilemma, nimm die Wut aus dem Gespräch und öffne mit einer ruhigen Frage den Raum für mehr als zwei Optionen.","bereich":"Arbeit","laenge":"kurz","ton":"sarkastisch","bestehenAb":4,"lektion":"Ein falsches Dilemma lässt mögliche Optionen weg und zwingt zu einer Schwarz-Weiß-Wahl; der Fehler liegt im Weglassen der Alternativen, nicht in der Sorge um die Umwelt. Wenn du zuerst Svens Gefühl anerkennst und das gemeinsame Ziel betonst (Deeskalations-Matrix), bleibt er im Gespräch, und die Frage „Welche Optionen C, D und E haben wir noch nicht in Betracht gezogen?“ sprengt den Rahmen, ohne dass du ihm inhaltlich nachgeben musst.","toolRef":"H.2.1","faktenRef":"D.1.3","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Sven","speech":"„*schiebt die Müslischale zur Seite* Currywurst. Na klar. Du musst dich einfach entscheiden: Entweder du isst nur Bio-Gemüse, oder du nimmst die Umweltzerstörung in Kauf. Dazwischen gibt es nichts. Aber hey, ist ja bequemer, wegzuschauen.“","options":[{"text":"„Du hast ja total einen an der Waffel! Dazwischen gibt es nichts? Du bist doch derjenige, der in seiner Öko-Blase festsitzt und alle anderen verurteilt!“","style":"frontal","reaction":"„*lauter* Aha, jetzt werde ich also auch noch beschimpft! Genau das meine ich: Man darf euch Wurstfans nie etwas sagen!“","feedback":"Gegenangriff statt Deeskalation: Du gibst Sven den Beweis für seine Opferrolle, die Fronten verhärten sich und das Gespräch ist tot.","score":-2,"nextStepId":"step-fail"},{"text":"„Klingt, als ginge dir das echt nah, Sven. Darf ich fragen: Gibt es wirklich nur diese zwei Möglichkeiten?“","style":"deeskalierend","reaction":"„*stutzt, die Schultern sinken ein Stück* ...Na ja. Ehrlich gesagt hab ich nie darüber nachgedacht, ob es mehr gibt. Warum, was meinst du?“","feedback":"Stark: Du validierst das Gefühl, nicht die Behauptung, und die Aktivierungs-Frage zum falschen Dilemma öffnet den Denkraum, ohne Sven bloßzustellen.","score":3,"nextStepId":"step-2"},{"text":"„Okay, du hast recht, Sven, dazwischen gibt es wohl wirklich nichts. Ab morgen esse ich nur noch Bio-Gemüse, versprochen.“","style":"humorvoll","reaction":"„*nickt zufrieden* Siehst du, so einfach ist das. Entweder richtig oder gar nicht.“","feedback":"Der Kipppunkt der Deeskalation: Frieden durch Zustimmung zum falschen Rahmen. Du bestätigst das falsche Dilemma, statt es zu öffnen.","score":-1,"nextStepId":"step-fail-zustimmung"}]},"step-2":{"id":"step-2","speaker":"Sven","speech":"„Moment, aber wenn es mehr Möglichkeiten gibt, warum sagt dann niemand etwas dazu? *verschränkt die Arme* Klingt für mich nach Ausrede. Entweder man macht es richtig oder gar nicht.“","options":[{"text":"„Dir ist das wichtig, und ich will nicht gegen dich arbeiten. Wir wollen doch beide, dass weniger Schaden entsteht. Was fällt uns außer deinen zwei Optionen noch ein?“","style":"deeskalierend","reaction":"„*überlegt* Hmm... man könnte natürlich weniger Fleisch essen, oder es nur gelegentlich. Oder Regionales kaufen. Aber dann... ist das ja immer noch nicht perfekt.“","feedback":"Perfekt: Gemeinsamkeit finden und gemeinsam Optionen C, D und E sammeln. Das sprengt das falsche Dilemma, ohne dass Sven sein Gesicht verliert.","score":3,"nextStepId":"step-3-success"},{"text":"„Sven, wer nicht für die Umwelt ist, ist gegen sie. Das ist doch deine Logik, oder? Dann bist du ja genau so ein Schwarz-Weiß-Denker wie ein Klischee-Öko aus dem Fernsehen.“","style":"sarkastisch","reaction":"„Ein Klischee-Öko?! Schön, dass du gleich in Schubladen denkst. Mit dir kann man nicht reden.“","feedback":"Du spiegelst den Fehler sarkastisch, aber mit einer Du-Botschaft, die ihn angreift. Das Dilemma ist damit nicht aufgelöst, sondern der Streit angeheizt.","score":-1,"nextStepId":"step-fail"},{"text":"„Das ist wirklich ein Thema, bei dem wir uns gerade im Kreis drehen und beide hitzig werden. Wollen wir das heute stoppen und morgen beim Kaffee in Ruhe weiterreden? Mir ist das Gespräch wichtig.“","style":"ausstieg","reaction":"„*zögert* ...Na gut. Aber ich bleibe dabei, dass es um Haltung geht. Morgen Kaffee, okay.“","feedback":"Eine solide strategische Auszeit: Respekt vor Gespräch und Person. Die Chance, das falsche Dilemma gleich aufzulösen, lässt du allerdings liegen.","score":1,"nextStepId":"step-2-struggle"}]},"step-3-success":{"id":"step-3-success","speaker":"Sven","speech":"„*grinst schief* Okay, vielleicht war mein Entweder-oder ein bisschen sehr entweder-oder. Wenn ich mir das so anschaue, gibt es da eine ganze Speisekarte statt zwei Gerichten. Aber ich hake bei dir trotzdem nach, ob die Currywurst wirklich dein Mittelweg ist!“","options":[{"text":"„Gern! Dann nehme ich zur Currywurst einfach heute den Salat dazu und schaue mir mit dir mal an, wie viel Fleisch bei mir so die Woche läuft. Abgemacht?“","style":"humorvoll","reaction":"„Abgemacht. Und ich bringe dir das nächste Mal ein regionales Rezept mit, das auch ohne Wurst schmeckt.“","feedback":"Gelungen: Mit Humor und einem konkreten Mittelweg ersetzt du das falsche Dilemma durch Kooperation. Die Stimmung im Team bleibt heil.","score":3}]},"step-2-struggle":{"id":"step-2-struggle","speaker":"Sven","speech":"„Na gut, dann eben morgen. Aber ich merke mir das.“ *geht zurück an seinen Platz*","options":[{"text":"„Gern, Sven. Und ich komme dann mit einer Frage: Gibt es für dich vielleicht auch Zwischenwege? Dann schauen wir gemeinsam, welche das sein könnten.“","style":"deeskalierend","reaction":"„*zuckt mit den Schultern* Ich schau es mir an. Aber verspreche nichts.“","feedback":"Guter Abschluss der Auszeit: Du kündigst die Rahmenfrage zum falschen Dilemma an, ohne Druck aufzubauen. Die Sache bleibt offen, die Beziehung ist geschützt.","score":2}]},"step-fail":{"id":"step-fail","speaker":"Sven","speech":"„*schnappt sich die Müslischale und rauscht aus der Küche* Wer nicht für die Umwelt ist, ist dagegen. So einfach ist das. Und mit dir will ich jetzt nicht weiterreden.“","options":[{"text":"Ende: Das Gespräch ist eskaliert. Sven wirkt in seinem Entweder-oder bestärkt, und im Team herrscht dicke Luft.","style":"ausstieg","reaction":"Beim nächsten Mal: erst das Gefühl ernst nehmen, dann den Denkraum mit der Frage nach weiteren Optionen öffnen.","feedback":"Ein falsches Dilemma löst du nicht durch Gegenangriff oder Zustimmung, sondern mit Deeskalation und der Frage nach Option C, D und E.","score":0}]},"step-fail-zustimmung":{"id":"step-fail-zustimmung","speaker":"Sven","speech":"„*lehnt sich zufrieden zurück* Siehst du, genau so geht das. Entweder richtig oder gar nicht. Ich bring dir morgen ein paar Rezepte mit.“","options":[{"text":"Ende: Der falsche Rahmen wurde bestätigt. Sven fühlt sich in seinem Entweder-oder bestärkt, und du hast ein Versprechen gegeben, das du so gar nicht halten willst.","style":"ausstieg","reaction":"Beim nächsten Mal: erst das Gefühl ernst nehmen, dann den Denkraum mit der Frage nach weiteren Optionen öffnen.","feedback":"Ein falsches Dilemma löst du nicht durch Zustimmung zum Rahmen, sondern mit Deeskalation und der Frage nach Option C, D und E.","score":0}]}},"status":"entwurf","familie":"falsches-dilemma","fertigkeit":"F2","stufe":2,"kurz":"Ein falsches Dilemma lässt Alternativen weg und erzwingt eine Schwarz-Weiß-Wahl; der Fehler liegt im Weglassen, nicht in der Sorge um die Umwelt. Wer zuerst das Gefühl ernst nimmt und dann nach weiteren Optionen fragt, öffnet den Rahmen, ohne inhaltlich nachgeben zu müssen.","prueffrage":"Wie viele Möglichkeiten lässt Svens Satz zu, und in welche davon passt das Mittagessen der meisten Leute im Raum?","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Internet Encyclopedia of Philosophy (Abschnitt „False Dilemma“ / „Black-or-White“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"scen-wahrsagerin-tarot","title":"Mias Tarot-Abend","subtitle":"Falsifizierbarkeit, geübt mit Street Epistemology","character":"Mia, Mitbewohnerin","avatar":"🃏","context":"Du kommst abends in die Küche. Deine Mitbewohnerin Mia mischt ihre Tarotkarten und strahlt: Die Karten hätten ihr letzte Woche „genau gesagt“, was passieren würde, und es sei auch so gekommen. Sie ist begeistert und will dir zeigen, wie gut das funktioniert.","goal":"Bring Mia mit Street Epistemology dazu, selbst zu prüfen, woher ihre Sicherheit kommt und woran man eine Tarot-Deutung überhaupt widerlegen könnte (Falsifizierbarkeit), ohne dass sie sich belächelt fühlt.","bereich":"Freunde","laenge":"kurz","ton":"heiter","bestehenAb":5,"lektion":"Eine Deutung, die so vage ist, dass sie im Nachhinein auf fast jedes Ereignis passt, kann nicht scheitern und sagt deshalb auch nichts Prüfbares voraus (Falsifizierbarkeit). Statt zu sagen „Das ist Zufall“, hilft die Street-Epistemology-Frage: „Wie hast du das herausgefunden, und was müsste passieren, damit du die Deutung als falsch ansehen würdest?“ So prüft Mia ihre eigene Methode, und du lässt sie dabei nicht allein stehen.","toolRef":"H.2.2","faktenRef":"A.3","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Mia","speech":"„Du, das musst du hören! Letzte Woche habe ich die Karten gelegt, und sie haben gesagt: ‚Eine Veränderung steht bevor, jemand aus der Vergangenheit meldet sich.‘ Und was passiert? Am Donnerstag schreibt mir meine Ex-Kollegin! Das kann doch kein Zufall sein, oder?“","options":[{"text":"„Mia, das ist doch klassischer Zufall. Mit so einem Satz triffst du jede Woche irgendwas. Tarot kann nichts vorhersagen, das ist längst bekannt.“","style":"frontal","reaction":"„Boah, du immer mit deinem Besserwissen! Ich erzähle dir was Schönes, und du machst es madig. Dann lass es halt.“ *mischt beleidigt die Karten*","feedback":"Frontalangriff: Du stellst die Schlussfolgerung ab, ohne zu fragen, wie Mia dazu kommt. Sie fühlt sich belächelt und verteidigt die Karten nur noch stärker.","score":-2,"nextStepId":"step-fail"},{"text":"„Wow, spannend! Und wie sicher bist du dir auf einer Skala von 0 bis 100, dass die Karten das wirklich vorhergesagt haben? Und woran machst du das fest?“","style":"sokratisch","reaction":"„Oh, ich würde sagen 90! Weil es ja genau gepasst hat: Veränderung, jemand aus der Vergangenheit, zack, Nachricht von früher.“","feedback":"Stark: Street Epistemology fragt zuerst nach dem Grad der Sicherheit und der Methode, ohne zu bewerten. Mia erklärt ihre eigene Begründung.","score":3,"nextStepId":"step-2"},{"text":"„Haha, wow, die Karten sind ja besser als jede Wetter-App! Dann leg mir doch mal die Lottozahlen, ich teile den Gewinn mit dir.“","style":"humorvoll","reaction":"„*lacht* Ja, ja, mach dich nur lustig. Aber irgendwas ist da dran, das spüre ich einfach.“","feedback":"Der Witz ist freundlich, schiebt das Thema aber nur zur Seite. Mia „spürt“ etwas, und du hast nicht gefragt, woher diese Sicherheit kommt.","score":0,"nextStepId":"step-2-struggle"}]},"step-2":{"id":"step-2","speaker":"Mia","speech":"„Weißt du, die Deutung war ja nicht irgendwas. ‚Veränderung steht bevor‘ und ‚jemand aus der Vergangenheit‘, das passt doch eindeutig zu der Nachricht von meiner Ex-Kollegin!“","options":[{"text":"„Das verstehe ich, Mia. Mich interessiert noch etwas: Gäbe es eine Woche, in der du sagen würdest, ‚Diese Deutung hat nicht gestimmt‘? Wie würde die aussehen?“","style":"sokratisch","reaction":"„Hmm... *überlegt* Wenn gar keine Veränderung gekommen wäre, vielleicht? Aber ‚Veränderung‘ ist ja irgendwie immer... naja, man müsste es halt anders deuten. Komisch, jetzt wo du fragst...“","feedback":"Treffer: Die Frage nach dem Gegenbeispiel führt zur Falsifizierbarkeit. Mia merkt selbst, dass eine so weite Deutung kaum scheitern kann. Du hast kein Urteil abgegeben, sie kommt von allein darauf.","score":3,"nextStepId":"step-3-success"},{"text":"„Jetzt mal ehrlich, das sind doch Gummisätze, die immer passen. ‚Jemand aus der Vergangenheit meldet sich‘ trifft bei jedem mal zu. Das ist einfach viel zu vage, das sagt gar nichts.“","style":"frontal","reaction":"„Pff, als ob du alles besser wüsstest. Ich hab's erlebt, du nicht!“","feedback":"Inhaltlich in die richtige Richtung (übermäßige Vagheit), aber als Belehrung verpackt. Statt Mia selbst die Vagheit entdecken zu lassen, nimmst du ihr die Erkenntnis ab, und sie geht in die Defensive.","score":-2,"nextStepId":"step-3-struggle"},{"text":"„Stimmt, das passt gut. Kannst du die Karten nicht einmal für mich legen? Ich bin gespannt, ob sie bei mir auch so punktgenau sind.“","style":"affektiv","reaction":"„Klar, gern! Ich lege dir gleich eine Dreier-Legung!“ *beginnt zu mischen, hält dann kurz inne* „Aber du glaubst eh nicht wirklich dran, oder?“","feedback":"Freundlich, aber du bestätigst die Behauptung mit, statt ihre Prüfbarkeit zu klären. Wer nur mitmacht, kann Mia nicht zum Nachdenken anregen, und sie spürt, dass etwas nicht ehrlich ist.","score":-1,"nextStepId":"step-3-struggle"}]},"step-2-struggle":{"id":"step-2-struggle","speaker":"Mia","speech":"„Weißt du, für mich fühlt sich das einfach richtig an. Es hat ja gestimmt, oder? Was willst du denn mehr?“","options":[{"text":"„Fair, ich verstehe, dass es sich für dich stimmig anfühlt. Ich bin neugierig: Woran hättest du es gemerkt, wenn die Deutung letzte Woche nicht gestimmt hätte?“","style":"sokratisch","reaction":"„Hm... das ist eine gute Frage. *überlegt* Ich glaube, ich hätte dann einfach anders gedeutet. Dass ‚Veränderung‘ halt was Kleineres meint. Hm.“","feedback":"Gut aufgefangen: Auch aus dem Gefühl heraus führt die Falsifizierbarkeitsfrage zum Kern. Mia bemerkt ihre eigene Umdeutung, ohne dass du ein Urteil fällen musstest.","score":2,"nextStepId":"step-3-success"},{"text":"„Ach, du immer mit deinen Gefühlen. Mach, was du willst, aber glaub nicht, dass das mit der Realität was zu tun hat. Ich lass das so stehen.“","style":"sarkastisch","reaction":"„Jetzt wirst du aber unfair. Mach du dein Ding, ich mach meins.“ *packt die Karten weg*","feedback":"Der Spott trifft den Menschen statt die Behauptung. Mia fühlt sich abgewertet, und das Gespräch endet, bevor sie ihre Methode prüfen konnte.","score":-2,"nextStepId":"step-fail"},{"text":"„Ich sehe das anders, aber lass uns einfach Pizza bestellen. Du hast bestimmt Hunger nach dem Tag, und über Karten reden wir ein andermal.“","style":"ausstieg","reaction":"„Pizza klingt super! Dann reden wir ein andermal drüber.“","feedback":"Ein freundlicher Ausstieg schützt die Stimmung und ist besser als Streit. Die Frage nach der Methode bleibt aber offen.","score":1,"nextStepId":"step-3-struggle"}]},"step-3-success":{"id":"step-3-success","speaker":"Mia","speech":"„Hm, ich glaube, ich habe vorhin mehr dazugedeutet, als die Karten eigentlich gesagt haben. Aber Spaß macht es mir trotzdem. Hättest du Lust, dass wir mal aufschreiben, was die Karten vorher sagen, und dann schauen, was wirklich passiert?“","options":[{"text":"„Das finde ich super! Dann schreiben wir ganz konkret auf, was vorher stehen muss, und was dann als ‚hat nicht gestimmt‘ zählt. Ich bin gespannt, was dabei rauskommt.“","style":"sokratisch","reaction":"„Abgemacht! *grinst* Aber wenn's nicht stimmt, bist du dran mit dem Abwasch.“","feedback":"Gelungen: Du hast die Behauptung nicht angegriffen, sondern gemeinsam einen Weg gefunden, sie prüfbar zu machen. Der Spaß bleibt, der Blick wird schärfer.","score":3}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Mia","speech":"„Ich weiß nicht... Du klingst, als wäre das alles Quatsch. Mir macht das halt Spaß, und manchmal stimmt's einfach.“","options":[{"text":"„Dass es dir Spaß macht, ist völlig in Ordnung. Ich frage mich nur manchmal, woran man erkennen würde, dass eine Deutung danebenlag. Wenn du magst, tüfteln wir ein andermal dran, bei einem Tee.“","style":"deeskalierend","reaction":"„Okay, das klingt fair. Tee ist eine gute Idee. Lass uns später weiterquatschen.“","feedback":"Guter Rückzug: Du würdigst ihr Hobby, lässt die Frage nach der Prüfbarkeit als offene Einladung stehen und schützt die Beziehung.","score":2}]},"step-fail":{"id":"step-fail","speaker":"Mia","speech":"„Ich glaube, wir lassen das Thema lieber. Ich mag meine Karten und lasse mir das nicht madig machen.“ *räumt die Karten weg und geht in ihr Zimmer*","options":[{"text":"Ende: Mia fühlt sich nicht ernst genommen, und die Karten sind ihr jetzt noch wichtiger. Rechthaben und Helfen sind zweierlei.","style":"ausstieg","reaction":"Beim nächsten Mal: erst nach der Methode fragen („Wie sicher bist du, und woran machst du das fest?“), dann nach dem Gegenbeispiel.","feedback":"Street Epistemology greift nicht die Schlussfolgerung an, sondern untersucht den Weg dorthin, und genau das macht Mia offen für Zweifel.","score":0}]}},"status":"entwurf","familie":"widerlegung-benennen","fertigkeit":"F1","stufe":3,"kurz":"Eine Deutung, die im Nachhinein auf fast jedes Ereignis passt, kann nicht scheitern und sagt deshalb nichts Prüfbares voraus. Statt „Das ist Zufall“ hilft die Frage, wie man es herausgefunden hat und was passieren müsste, damit die Deutung als falsch gilt.","prueffrage":"Wie hätte eine Woche aussehen müssen, auf die „Eine Veränderung steht bevor, jemand aus der Vergangenheit meldet sich“ nicht gepasst hätte?","quellen":[{"typ":"url","kurz":"Thornton, S.: Karl Popper, Stanford Encyclopedia of Philosophy (rev. 31.07.2026)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science, Stanford Encyclopedia of Philosophy (rev. 28.07.2025)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Forer, B. R. (1949): The Fallacy of Personal Validation: A Classroom Demonstration of Gullibility (Journal of Abnormal and Social Psychology 44)","oeffentlich":false}],"thema":"Geschichte und Wissenschaft"},{"id":"scen-waschmittel-nuesse","title":"Hannas Waschnüsse","subtitle":"Natürlich vs. chemisch, geübt mit aktivem Zuhören","character":"Hanna, Nachbarin","avatar":"🧺","context":"Beim Wäscheaufhängen im Hof strahlt dich deine Nachbarin Hanna an. Sie hat ihr Waschmittel gegen Waschnüsse getauscht und verkündet, ihre Wäsche sei jetzt „endlich richtig rein und gesund“. Sie ist begeistert und möchte dich gleich bekehren.","goal":"Höre Hanna zuerst aktiv zu, finde heraus, was hinter ihrer Begeisterung steckt, und lenke das Gespräch freundlich auf die Frage, was „natürlich“ eigentlich über Sicherheit und Wirkung aussagt.","bereich":"Nachbarschaft","laenge":"kurz","ton":"heiter","bestehenAb":4,"lektion":"Wer zuerst zuhört und paraphrasiert, erfährt, was hinter dem Satz „Chemie ist schlecht“ steckt, bei Hanna etwa die Sorge um ihre Haut. Eine offene Frage öffnet eher als eine Belehrung. Denn ein Molekül bleibt dasselbe, egal woher es stammt, und „natürlich“ sagt nichts über Sicherheit oder Wirksamkeit aus.","toolRef":"H.2.3","faktenRef":"D.4.3","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Hanna","speech":"„Stell dir vor, ich habe das ganze Chemiezeug rausgeworfen! Nur noch Waschnüsse, rein natürlich, direkt vom Baum. Da ist null Chemie drin, das ist viel gesünder für meine Haut und für die Umwelt. Du solltest das auch machen!“","options":[{"text":"„Hanna, ‚null Chemie‘ gibt es gar nicht. Alles besteht aus Chemikalien, auch deine Waschnüsse. Das ist einfach Marketing, und darauf bist du reingefallen.“","style":"frontal","reaction":"„*verschränkt die Arme* Reingefallen? Ich habe mich lange informiert! Du willst nur recht haben. Ich merke schon, du hörst mir gar nicht zu.“","feedback":"Der Kern stimmt (Alles ist chemisch), aber du belehrst, ohne zuzuhören, und wertest Hanna ab. Wer sich verstanden fühlt, öffnet sich eher; hier passiert das Gegenteil.","score":-2,"nextStepId":"step-fail"},{"text":"„Du wirkst richtig glücklich damit. Wenn ich dich richtig verstehe, ist dir vor allem wichtig, dass deine Haut und die Umwelt geschont werden. Was hat dich dazu gebracht, umzusteigen?“","style":"deeskalierend","reaction":"„*strahlt* Ganz genau! Meine Haut war immer so gereizt nach dem Waschen. Und dann habe ich gelesen, wie viel Chemie überall drinsteckt, da wollte ich einfach was Ehrliches, Reines nehmen.“","feedback":"Sehr gut! Paraphrasieren plus offene Frage: Hanna fühlt sich verstanden, und du erfährst ihr eigentliches Anliegen (empfindliche Haut) statt nur die Parole.","score":3,"nextStepId":"step-2"},{"text":"„Ach, Waschnüsse, die habe ich auch mal ausprobiert. Und bei dir ist die Wäsche jetzt wirklich sauberer als vorher, ja?“","style":"humorvoll","reaction":"„Na ja, ich *finde* schon... Sie riecht halt nach nichts, und das ist doch ein gutes Zeichen. Warum, riecht sie für dich anders?“","feedback":"Freundlich, aber es bleibt oberflächlich: Du stellst eine geschlossene Ja/Nein-Frage und gräbst nicht nach Hannas eigentlichem Grund. Das Gespräch plätschert weiter, ohne dass etwas geklärt wird.","score":0,"nextStepId":"step-2-struggle"}]},"step-2":{"id":"step-2","speaker":"Hanna","speech":"„Weißt du, Waschmittel sind einfach aus dem Labor, und was aus der Natur kommt, ist immer besser verträglich als das, was sich irgendein Chemiker ausdenkt. Natur ist einfach gütiger.“","options":[{"text":"„Du vertraust also eher der Natur. Woran machst du das fest? Würde dir ein Stoff mit gleichen Eigenschaften weniger gefallen, nur weil er aus dem Labor stammt?“","style":"sokratisch","reaction":"„Hm... *überlegt* Gleiche Eigenschaften, wenn sie genau dasselbe kann? Eigentlich... dann wäre mir das wohl egal. Ich habe das so noch nie gefragt, ich dachte immer, Labor heißt automatisch künstlich und schlecht.“","feedback":"Sehr gut! Aktives Zuhören plus eine Frage, die Hanna selbst zum Nachdenken bringt. Das Beispiel des Vitamin-C-Tests zeigt: Identische Moleküle sind identisch, egal ob aus Frucht oder Labor.","score":3,"nextStepId":"step-3-success"},{"text":"„Gütig? Dann iss mal einen Knollenblätterpilz, der ist rein natürlich. Natur ist nicht gütig, sondern manchmal tödlich, und das sollte man nicht verklären, Hanna.“","style":"sarkastisch","reaction":"„*verzieht das Gesicht* Jetzt übertreibst du aber. Ich habe ja nicht gesagt, dass ich Giftpilze esse! Du drehst mir das Wort im Mund um.“","feedback":"Das Beispiel an sich passt zur Sachlage (viele giftige Stoffe sind „rein natürlich“), aber der sarkastische Ton lässt Hanna in die Defensive gehen. Sie erfährt nichts Neues, sondern fühlt sich vorgeführt.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Ja, das mag sein. Ich selbst bleibe lieber bei meinem Waschmittel, aber jeder, wie er mag. Da muss ich niemanden überzeugen, und du musst es auch nicht.“","style":"ausstieg","reaction":"„Ach so, na gut. Schade, ich dachte, wir könnten uns mal austauschen. Aber egal, jedem das Seine.“","feedback":"Der Rückzug schützt zwar die Nachbarschaftsruhe, aber du verpasst die Chance, Hannas Annahme „natürlich = besser“ behutsam zu hinterfragen. Eine kurze offene Frage hätte genügt.","score":1,"nextStepId":"step-3-struggle"}]},"step-2-struggle":{"id":"step-2-struggle","speaker":"Hanna","speech":"„Hauptsache, kein Labor. Was die Chemiker da zusammenmischen, kann doch nicht gesund sein, das sagt einem doch der gesunde Menschenverstand.“","options":[{"text":"„Verstehe ich dich richtig: Entscheidend ist für dich, ob etwas aus dem Labor oder aus der Natur kommt? Was genau ändert sich dadurch für deine Haut?“","style":"sokratisch","reaction":"„Hm, das kann ich gar nicht so genau sagen. Ich *glaube* einfach, dass es besser ist. Aber warum eigentlich?“","feedback":"Gut gerettet! Paraphrasieren und eine offene, klärende Frage holen das Gespräch auf den richtigen Kurs. Hanna fällt auf, dass sie ihre Überzeugung nur gefühlt, nie geprüft hat.","score":2,"nextStepId":"step-3-success"},{"text":"„Gesunder Menschenverstand sagt auch, dass die Sonne um die Erde kreist. Sorry, Hanna, aber so einfach ist das nicht, das stimmt hinten und vorne nicht.“","style":"sarkastisch","reaction":"„*schnaubt* Jetzt werde ich also mit Leuten verglichen, die glauben, die Sonne kreise um die Erde! Danke für nichts.“","feedback":"Der Vergleich trifft Hanna persönlich, nicht die Behauptung. „Seziert wird die Behauptung, nicht der Mensch“, und genau das gelingt dir hier nicht.","score":-2,"nextStepId":"step-fail"},{"text":"„Mmh, kann sein. Ich muss jetzt auch los, die Wäsche trocknet ja nicht von allein. Schönen Tag noch, und lass dich nicht von mir stören!“","style":"ausstieg","reaction":"„Dir auch! Und denk mal darüber nach mit den Waschnüssen!“","feedback":"Ein freundlicher Abgang, aber ohne dass sich an Hannas Sicht oder an deinem Verständnis etwas geändert hätte. Ein wenig Neugier hätte ein echtes Gespräch ermöglicht.","score":0}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Hanna","speech":"„Ich finde einfach, ‚natürlich‘ muss doch schon mal ein Pluspunkt sein. Das sagt schon das Wort, oder nicht?“","options":[{"text":"„Wenn ich dich richtig verstehe, ist ‚natürlich‘ für dich ein Hinweis auf Qualität. Woran würdest du prüfen, ob ein Waschmittel wirklich gut ist: am Wort selbst oder an etwas Nachmessbarem?“","style":"sokratisch","reaction":"„Hm... nachmessen wäre schon besser, ehrlich gesagt. Das Wort allein sagt ja eigentlich nichts über die Wirkung, oder? Ich hätte vielleicht erst mal schauen sollen, ob das überhaupt belegt ist.“","feedback":"Sehr gut! Du paraphrasierst und stellst eine offene Frage, die auf Prüfbares statt auf das Wort lenkt, genau das, was „natürlich“ laut „Natürlich“ vs. „Chemisch/Synthetisch“ nicht liefert.","score":3},{"text":"„Ja, ‚natürlich‘ klingt immer gut, das gebe ich zu. Aber das Wort allein sagt halt nicht viel aus, das muss man sich genauer ansehen, bevor man kauft oder weiterempfiehlt.“","style":"deeskalierend","reaction":"„Stimmt schon, da ist was dran. Ich schau mir das noch mal in Ruhe an. Danke fürs Zuhören.“","feedback":"Freundlich und sachlich richtig: „Natürlich“ allein sagt nichts über Sicherheit oder Wirkung aus. Etwas knapp, weil du Hanna keine Frage stellst, die ihr selbst weiterhilft.","score":2},{"text":"„Nein, das ist einfach falsch. Natürlich heißt nicht gut, das ist ein bekannter Denkfehler. Punkt. Darüber braucht man auch nicht lange zu reden, das lernt man schon in der Schule.“","style":"frontal","reaction":"„Na, dann weiß ich ja, wie viel dir meine Meinung wert ist. Schönen Tag noch.“ *geht zur Haustür*","feedback":"Du triffst die Sache, aber nicht den Menschen. Ohne aktives Zuhören bleibt eine korrekte Aussage wirkungslos, und Hanna zieht sich beleidigt zurück.","score":-2}]},"step-3-success":{"id":"step-3-success","speaker":"Hanna","speech":"„Weißt du was, vielleicht sollte ich mir mal genauer ansehen, ob die Waschnüsse wirklich so viel besser sind, oder ob ich einfach nur dem Wort ‚natürlich‘ vertraut habe. Wie würdest du das herausfinden?“","options":[{"text":"„Gute Idee. Frag dich: Was ist der Stoff genau, und was weiß man aus Tests über Wirkung, Verträglichkeit und Dosis? Die Herkunft allein, ob Baum oder Labor, verrät das nicht.“","style":"sokratisch","reaction":"„Das machen wir! Und danke, dass du mir nicht gleich den Kopf abgerissen hast. Heute Abend gibt es bei mir übrigens ein Glas Holundersaft, magst du kommen?“","feedback":"Mission gelungen! Du hast die Aktivierungsfrage aus Struktur, Wirkung, Dosis zusammen mit aktivem Zuhören angewendet, und Hanna kommt selbst zu dem Schluss, genauer hinzusehen.","score":3},{"text":"„Ach, probier einfach alles aus, ist doch deine Wäsche. Ich halte mich da lieber raus, ich habe von Waschmitteln ohnehin keine Ahnung.“","style":"ausstieg","reaction":"„Na gut... dann mache ich einfach so weiter wie bisher. Schönen Tag noch.“","feedback":"Schade: Hanna war offen für eine echte Prüfung, und du lässt sie allein. Ein kleiner Schubs mit offenen Fragen hätte hier viel bewirkt.","score":0},{"text":"„Ich sag dir, was du herausfinden wirst: dass alles Marketing ist. Die Waschnuss-Hersteller wollen nur Geld verdienen, genau wie die großen Konzerne.“","style":"frontal","reaction":"„*verzieht den Mund* Jetzt klingst du auch wie jemand, der gar nichts mehr glaubt. Mit so einer Haltung brauche ich nicht anzufangen.“","feedback":"Du kippst ins Gegenteil: Eine pauschale Unterstellung ersetzt die Prüfung und trifft Hannas ehrliches Anliegen nicht. Aktives Zuhören hätte genügt, um sie selbst prüfen zu lassen.","score":-1}]},"step-fail":{"id":"step-fail","speaker":"Hanna","speech":"„Du hörst mir ja gar nicht richtig zu. Ich glaube, ich bleibe bei meinen Waschnüssen und erzähle dir lieber nichts mehr.“ *nimmt den Wäschekorb und geht*","options":[{"text":"Ende: Hanna fühlte sich nicht gehört und hat sich zurückgezogen. Ohne Zuhören bleibt jede korrekte Aussage wirkungslos.","style":"ausstieg","reaction":"Beim nächsten Mal erst paraphrasieren, dann fragen, und die Behauptung prüfen statt den Menschen angreifen.","feedback":"Frage dich: Wollte ich Hanna belehren oder verstehen? Aktives Zuhören heißt: erst die Sorge dahinter hören, dann über „natürlich“ und Belege sprechen.","score":0}]}},"status":"entwurf","familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","stufe":1,"kurz":"Wer zuerst zuhört und mit eigenen Worten wiedergibt, erfährt, was hinter „Chemie ist schlecht“ steckt, etwa die Sorge um die eigene Haut. Ein Molekül bleibt dasselbe, egal ob es vom Baum oder aus dem Labor stammt; „natürlich“ sagt nichts über Sicherheit oder Wirksamkeit.","prueffrage":"Was müsste man an der Wäsche oder an der Haut messen, um zu wissen, ob die Waschnüsse besser sind als das alte Waschmittel?","quellen":[{"typ":"doi","kurz":"Carr, A. C. u. a. (2013): A randomized steady-state bioavailability study of synthetic versus natural (kiwifruit-derived) vitamin C (Nutrients 5(9))","oeffentlich":true,"doi":"10.3390/nu5093684","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3798928/","abruf":"2026-10-12"},{"typ":"url","kurz":"WHO: Natural toxins in food (Fact sheet, 10.03.2023)","oeffentlich":true,"url":"https://www.who.int/news-room/fact-sheets/detail/natural-toxins-in-food","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Braun, V.; Burian, R.; Diefenbacher, A. (Hrsg.) (2016): Arzt-Patienten-Gespräche bei stressassoziierten Erkrankungen, Kap. 3","oeffentlich":false}],"thema":"Natur und Klima"},{"id":"scen-wutkommentar-impf","title":"Der Wut-Kommentar unter dem Zeitungsartikel","subtitle":"Schlagzeilen und Wut, geübt mit dem Management emotionaler Kosten","character":"Kommentator „RealMichi77“","avatar":"🔥","context":"Unter einem geteilten Zeitungsartikel in deinem Social-Media-Feed entdeckst du einen Kommentar von „RealMichi77“: „Alles gelogen! Hier wird nur hochgespült, was Wut macht, weil Wut sich verkauft!“ Der Kommentar hat schon viele Likes, und du merkst, wie dein Puls steigt.","goal":"Trenne die berechtigte Beobachtung (Algorithmen belohnen Empörung) von der falschen Schlussfolgerung (jede Nachricht ist gelogen), und entscheide bewusst, wie viel Energie du in diese Debatte steckst.","bereich":"Online","laenge":"mittel","ton":"sarkastisch","bestehenAb":6,"lektion":"Michi hat einen wahren Kern: Plattform-Algorithmen sind auf Engagement optimiert, und Empörung bringt Reichweite. Daraus folgt aber nicht, dass jede Nachricht gelogen ist; die Verstärkung betrifft vor allem, was dir im Feed angezeigt wird. Und nicht jede Schlacht lohnt sich: Wer seine begrenzte Energie einteilt und gezielt dort einsetzt, wo ein Gespräch möglich ist, bleibt handlungsfähig.","toolRef":"H.1.2","faktenRef":"E.4.3","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"RealMichi77","speech":"„Na, auch wieder auf den Köder reingefallen? Die schreiben doch nur Schlagzeilen, damit du dich aufregst und klickst. Wut verkauft sich, Wahrheit nicht. Alles Lüge, jedes Wort, und du glaubst es auch noch!“","options":[{"text":"„Du hast ja keine Ahnung! Kein Journalist sitzt da und denkt sich Lügen aus. Wer so einen Unsinn schreibt, hat den Artikel nicht mal gelesen.“","style":"frontal","reaction":"„Ach so, ich hab keine Ahnung? Typisch, wer nicht mitschreit, wird angepöbelt. Du bist doch Teil des Systems, sonst würdest du das nicht verteidigen!“","feedback":"Ein Frontalangriff bringt den Kommentator in die Verteidigung. Er fühlt sich als Person getroffen, nicht als jemand, der etwas Richtiges beobachtet hat.","score":-2,"nextStepId":"step-fail"},{"text":"„Moment, an einem Punkt hast du recht: Empörende Inhalte bekommen online mehr Reichweite. Magst du mir sagen, woran du merkst, dass in diesem Artikel etwas nicht stimmt?“","style":"sokratisch","reaction":"„*schnaubt* Na wenigstens einer, der zuhört. Die Überschrift ist schon so geschrieben, dass man wütend wird. Das kann doch kein Zufall sein, oder?“","feedback":"Stark: Du erkennst den wahren Kern an (Empörung bringt Reichweite) und fragst nach dem Beleg. So bleibt das Gespräch offen, und du trennst Beobachtung von Schlussfolgerung.","score":3,"nextStepId":"step-2"},{"text":"„Ich prüfe kurz: Will der hier reden oder nur gewinnen? Ich stelle eine einzige ehrliche Frage, und wenn nichts zurückkommt, lasse ich es.“","style":"deeskalierend","reaction":"„Eine Frage? Na, schieß los. Aber erwarte keine Wunder von mir.“","feedback":"Bewusste Triage: Du investierst dosiert, statt dich zu verausgaben, und lässt dem Gespräch trotzdem eine Chance.","score":2,"nextStepId":"step-2"},{"text":"„Haha, ja klar, und der Mond ist aus Käse. Du bist ja ein ganz Schlauer, so ein Kommentar bringt mich echt zum Lachen.“","style":"sarkastisch","reaction":"„Lach nur. Die Lacher gehen bald zu Ende, wenn du aufwachst. Aber dir ist ja nicht zu helfen.“","feedback":"Sarkasmus gegen die Person zementiert Fronten. Seziert wird die Behauptung, nicht der Mensch, und hier wird der Mensch verspottet.","score":-1,"nextStepId":"step-fail"}]},"step-2":{"id":"step-2","speaker":"RealMichi77","speech":"„Na eben! Die Überschrift ist auf Wut gebaut. Also wollen die uns manipulieren. Und wenn die schon bei der Überschrift tricksen, kannst du den ganzen Rest vergessen. Alles gelogen!“","options":[{"text":"„Du verwechselst da zwei Dinge. Reißerische Überschrift heißt nicht automatisch erfundene Fakten, und das ist ein Denkfehler, den du gerade machst. Lies erst mal richtig.“","style":"frontal","reaction":"„Jetzt kommt wieder die Belehrung. Ich lese genug, danke. Du hältst mich wohl für dumm.“","feedback":"Inhaltlich richtig, aber als Belehrung verpackt. Michi hört vor allem „du denkst falsch“ und blockt ab, statt selbst nachzudenken.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Gute Frage, wie unterscheidet man das eigentlich? Wenn eine Plattform vor allem zeigt, was Reaktionen auslöst: Heißt das, dass der Text dahinter falsch ist, oder nur, dass er dir lauter angeboten wird?“","style":"sokratisch","reaction":"„Hm... lauter angeboten. Du meinst, die Wut kommt von dem, was mir gezeigt wird, nicht unbedingt davon, dass es gelogen ist? ...Das ist ein Unterschied, ja.“","feedback":"Treffend: Der Algorithmus kennt weder Wahrheit noch Wut, er sieht nur Engagement. Die Verstärkung betrifft, was angezeigt wird, nicht automatisch, was wahr ist. Michi entdeckt die Unterscheidung selbst.","score":3,"nextStepId":"step-3-success"},{"text":"„Ja, stimmt wohl, gelogen ist da alles. Das haben mir auch schon andere gesagt. Dann lese ich eben gar keine Nachrichten mehr.“","style":"affektiv","reaction":"„Siehst du, so ist es richtig! Hör auf zu glauben, was die dir vorsetzen. Und du fühlst dich doch auch immer so wütend danach, oder?“","feedback":"Du übernimmst die falsche Schlussfolgerung, um Frieden zu haben. Dabei wird aus einer wahren Beobachtung ein Pauschalmisstrauen, das niemandem hilft.","score":-2,"nextStepId":"step-fail"}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"RealMichi77","speech":"„Ich lass mir nichts vorschreiben. Aber gut, wenn du meinst, dass ich blöd bin, dann sag mir wenigstens, was an dem Artikel konkret stimmt.“","options":[{"text":"„Ich sehe, das Gespräch dreht sich im Kreis, und ich merke, dass es mich Energie kostet. Ich schreibe dir noch einen Link zu dem Thema hin und steige dann aus. Tschüss!“","style":"ausstieg","reaction":"„Wie du willst. Ich hab gesagt, was ich zu sagen hatte. *Kommentar bleibt stehen*“","feedback":"Der Ausstieg ist hier vertretbar: Der Austausch war schon angespannt. Du investierst nicht mehr, als es dir wert ist, und bleibst höflich.","score":1,"nextStepId":"step-4"},{"text":"„Ich zähle dir jetzt Punkt für Punkt auf, was am Artikel stimmt und wo du dich irrst, und du antwortest mir auf jeden einzelnen Absatz. Wir klären das heute noch.“","style":"frontal","reaction":"„Ach, ein Verhör. Dafür habe ich keine Zeit und keine Lust. Du willst nur gewinnen.“","feedback":"Ein Marathon mit einem Gegenüber, das sich verteidigt, kostet viel Energie und bringt wenig. Triage heißt hier: Dieser Kampf war nicht der richtige.","score":-1,"nextStepId":"step-fail"},{"text":"„Du hast recht, das war eben zu belehrend. Mich würde ehrlich interessieren, wie du das siehst: Wo hast du schon mal erlebt, dass eine Schlagzeile viel schlimmer klang als der Artikel selbst?“","style":"deeskalierend","reaction":"„*zögert* ...Ja, das habe ich tatsächlich mal gehabt. Die Überschrift klang nach Weltuntergang, im Text stand dann ein ganz normaler Sachverhalt.“","feedback":"Gut gerettet: Du nimmst Druck raus, räumst den eigenen Ton ein und holst Michi mit einer echten Frage zurück ins Gespräch.","score":2,"nextStepId":"step-4"}]},"step-3-success":{"id":"step-3-success","speaker":"RealMichi77","speech":"„Okay, das ist ein Unterschied. Aber wenn mir die Plattform so viel Wut hinschiebt, was soll ich dann tun? Nur noch gar nichts lesen?“","options":[{"text":"„Eher das Gegenteil: Frag dich bei jedem Aufreger, ob es dir gezeigt wird, weil es wichtig ist, oder weil es dich am ehesten zu einer Reaktion bringt. Und lies auch mal gezielt Quellen, die dein Feed dir nie vorschlagen würde.“","style":"sokratisch","reaction":"„Das klingt machbar. Ich frag mich beim nächsten Aufreger mal, warum der gerade bei mir landet, und schau auch mal woanders rein. Danke, dass du nicht gleich draufgehauen hast.“","feedback":"Sehr gut: Du gibst Michi die Aktivierungsfrage aus „Algorithmen & Wut“ mit und schlägst den Feed-Reset vor, ohne zu dozieren. Eine Handlungsoption statt einer Gegenthese.","score":3},{"text":"„Nachrichten komplett meiden bringt dir auch nichts. Aber nimm wahr, wann der Aufreger dich zieht, und mach nach so einem Kommentar eine Pause. Du musst nicht jede Debatte führen.“","style":"deeskalierend","reaction":"„Pause klingt gut. Ich bin eh jedes Mal danach sauer auf alles und jeden. Vielleicht lasse ich das einfach mal.“","feedback":"Solide: Du betonst die Selbstfürsorge und lässt die Entscheidung bei Michi. Der Hinweis auf die Rolle des Feeds fehlt allerdings.","score":2}]},"step-4":{"id":"step-4","speaker":"RealMichi77","speech":"„Na gut. Aber eins lass ich mir nicht nehmen: Dass sich Wut besser verkauft als Wahrheit. Das stimmt doch, oder?“","options":[{"text":"„Dass Empörung online mehr Reichweite bekommt, stimmt. In einer großen Auswertung von Beiträgen von Medien und Abgeordneten wurden Posts, die über die politische Gegenseite sprachen, deutlich häufiger geteilt. Nur heißt das nicht, dass alles gelogen ist.“","style":"sokratisch","reaction":"„Okay, so gesehen lasse ich das gelten. Wut verkauft sich, aber nicht alles, was sich verkauft, ist gelogen. Das merke ich mir.“","feedback":"Du bestätigst die gut belegte Beobachtung und ziehst gleichzeitig die Grenze zur Falschbehauptung. Das ist der Kern der Sache.","score":3},{"text":"„Ja, klar, und deshalb sollte man gar nichts mehr glauben. Da hast du völlig recht. Wenn alles nur Wut ist, kann man sich die ganzen Nachrichten auch sparen, denn gelogen wird ohnehin in jeder Zeitung und auf jedem Kanal.“","style":"affektiv","reaction":"„Siehst du, endlich sagt es mal einer. Dann sind wir uns ja einig.“","feedback":"Aus „Wut bringt Reichweite“ wird „alles ist gelogen“: Genau der Fehlschluss, den du eigentlich auflösen wolltest.","score":-2},{"text":"„Kann sein. Ich muss jetzt aber los, die Bahn wartet nicht. Schönen Tag noch, und lass uns das Thema vielleicht ein andermal weiter besprechen, wenn ich mehr Zeit habe und nicht gleich weg muss.“","style":"ausstieg","reaction":"„Na dann. Bis zum nächsten Mal.“","feedback":"Vertretbar: Du schützt deine Energie. Den wahren Kern hättest du vorher noch würdigen können.","score":1}]},"step-fail":{"id":"step-fail","speaker":"RealMichi77","speech":"„Mit dir ist wohl nicht zu reden. Ich habe genug gesehen. Mein Kommentar bleibt stehen, und wer es besser weiß, soll es beweisen.“","options":[{"text":"Ende: Michi fühlt sich bestätigt, nicht widerlegt. Der Streit hat dich Energie gekostet und nichts verändert.","style":"ausstieg","reaction":"Frage dich beim nächsten Mal: Ist das eine Schlacht, die ich kämpfen muss, kann oder vermeiden sollte?","feedback":"Die Triage aus „Das Management emotionaler Kosten“ hilft: Bei anonymen Kommentaren mit wenig Interesse am Austausch lohnt sich oft der Rückzug oder eine einzige sokratische Frage.","score":0}]}},"status":"entwurf","familie":"anreize-durchschauen","fertigkeit":"F1","stufe":3,"kurz":"Plattformen sind auf Engagement optimiert, und Empörung bringt Reichweite. Daraus folgt nicht, dass jede Nachricht gelogen ist: Die Verstärkung betrifft vor allem, was im Feed angezeigt wird. Setz deine begrenzte Energie dort ein, wo ein Gespräch möglich ist.","prueffrage":"Welche konkrete Angabe im Artikel selbst, nicht in der Überschrift, wird als falsch benannt, und lässt sie sich nachprüfen?","quellen":[{"typ":"doi","kurz":"Rathje, S.; Van Bavel, J. J.; van der Linden, S. (2021): Out-group animosity drives engagement on social media. PNAS 118(26), e2024292118","oeffentlich":true,"doi":"10.1073/pnas.2024292118","abruf":"2026-10-12"},{"typ":"doi","kurz":"Milli, S. u. a. (2025): Engagement, user satisfaction, and the amplification of divisive content on social media. PNAS Nexus 4(3), pgaf062","oeffentlich":true,"doi":"10.1093/pnasnexus/pgaf062","abruf":"2026-10-12"},{"typ":"doi","kurz":"Guess, A. M. u. a. (2023): How do social media feed algorithms affect attitudes and behavior in an election campaign? Science 381(6656), 398–404","oeffentlich":false,"doi":"10.1126/science.abp9364","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"scen-bernd-galileo","title":"Bernds Genie-Gambit","subtitle":"Galileo-Gambit, geübt mit der Ausstiegs-Strategie","character":"Bernd, Kollege mit der Wunderidee","avatar":"💡","context":"In der Kaffeeküche erzählt dir Bernd zum dritten Mal von seiner „Revolution“: Er will mit seinem Konzept die Abläufe im Betrieb umkrempeln. Die Abteilung hat es abgelehnt. Für ihn ist genau das der Beweis, dass er mit seiner Idee ein verkanntes Genie ist.","goal":"Lenk das Gespräch vom Ablehnungs-Drama zur prüfbaren Vorhersage zurück (Falsifizierbarkeit), und steig elegant aus, wenn es nur noch im Kreis läuft.","bereich":"Arbeit","laenge":"mittel","ton":"sarkastisch","bestehenAb":6,"lektion":"Ablehnung ist kein Beleg, sondern Rauschen: Abgelehnt werden die seltenen Galileis genauso wie die vielen Bozos, und deshalb sagt sie nichts über die Idee. Überzeugt hat Galilei, weil jeder durch sein Fernrohr schauen konnte; die Frage nach dem Fernrohr, also der prüfbaren Vorhersage, holt das Gespräch zurück zur Sache. Wenn sich nichts bewegt, ist der ruhige, begründete Ausstieg kein Scheitern, sondern Energieschutz.","toolRef":"H.2.4","faktenRef":"D.3.8","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Bernd","speech":"„Jeder in der Abteilung hat mein Konzept abgeschmettert, einstimmig. Tja. Wisst ihr, wer sonst noch ausgelacht wurde? Galilei! Semmelweis! Wegener! Die Großen werden immer erst verlacht. Ich sag's ja: Wenn alle dagegen sind, bin ich auf der richtigen Spur.“","options":[{"text":"„Bernd, das ist doch Quatsch. Wenn alle dagegen sind, hast du schlicht unrecht. Deine Idee ist Murks, finde dich damit ab. Einstimmig heißt einstimmig, und dagegen kommst du nicht an.“","style":"frontal","reaction":"„Aha, jetzt wirst du also auch persönlich! Typisch. Genau so haben sie auch über Galilei geredet.“ *verschränkt die Arme*","feedback":"Frontal und selbst ein Fehlschluss: „Alle sind dagegen, also stimmt es nicht“ ist genauso wenig ein Beleg wie Bernds Umkehrung. Du lieferst ihm noch ein Stück Verfolgungsgeschichte.","score":-2,"nextStepId":"step-fail"},{"text":"„Stimmt, solche Fälle gibt es. Nur wurde über die Brüder Wright gelacht, aber auch über Bozo den Clown. Dass über dich gelacht wird, sagt nicht, welcher von beiden du bist. Was ist dein Beleg für das Konzept?“","style":"sokratisch","reaction":"„Hmpf, Bozo... sehr witzig. *überlegt kurz* Mein Beleg ist, dass es logisch ist. Das sieht doch jeder, der kein Betonkopf ist.“","feedback":"Stark: Du würdigst den wahren Kern, nennst Sagans Gegenbeispiel und stellst die Beweislast-Frage zurück an den Behauptenden. Bernd weicht allerdings noch aus.","score":3,"nextStepId":"step-2"},{"text":"„Haha, ja, Bernd, du bist natürlich das nächste Genie. Ich bestelle schon mal das Denkmal für die Kantine, und die Abteilung wird dich später feiern, wenn du erst berühmt bist.“","style":"sarkastisch","reaction":"„Lach nur! Lachen ist genau, was sie bei Galilei auch gemacht haben. Mich bestätigt das nur.“","feedback":"Der Spott füttert das Gambit: Verlachen wird zum Beweis. Mit Sarkasmus wirst du Teil von Bernds Heldengeschichte.","score":-1,"nextStepId":"step-2-struggle"}]},"step-2":{"id":"step-2","speaker":"Bernd","speech":"„Die Leute wollen das nur nicht verstehen. Die etablierte Abteilungsmeinung blockiert jeden, der was verändern will. Ich weiß, was ich weiß. Und dass sie sich so dagegen wehren, zeigt doch, dass was dran ist.“","options":[{"text":"„Galilei überzeugte nicht durch Gegenwehr, sondern weil jeder durch sein Fernrohr schauen konnte. Wo ist dein Fernrohr? Welche Vorhersage deines Konzepts kann ich in vier Wochen nachprüfen?“","style":"sokratisch","reaction":"„Eine Vorhersage...? *stockt* Na, dass die Abläufe schneller werden. Irgendwann. Das Fernrohr-Bild gefällt mir nicht, aber... hm.“","feedback":"Exakt das Skript aus „Das Galileo-Gambit“: Weg von der Verfolgung, hin zur Prüfbarkeit (Falsifizierbarkeit). Bernd muss zum ersten Mal konkret werden.","score":3,"nextStepId":"step-3"},{"text":"„Wenn es nicht stimmen würde, würden sie sich ja nicht so wehren? Meinst du das? Bernd, so kann man jede Ablehnung zum Beweis umdeuten, egal was passiert.“","style":"frontal","reaction":"„Nein, nein, ich sage nur: Es ist auffällig! Du drehst mir das Wort im Mund um.“","feedback":"Der Hinweis auf die Immunisierung ist inhaltlich richtig, wirkt aber als abstrakte Belehrung. Bernd fühlt sich vorgeführt und weicht aus.","score":1,"nextStepId":"step-3"},{"text":"„Du hast recht, die Abteilung ist wirklich verknöchert. Bei Semmelweis war es auch so. Bleib einfach dran, irgendwann sehen sie es, und dann stehst du ganz oben.“","style":"affektiv","reaction":"„Danke! Endlich jemand mit Weitblick. Ich wusste, dass du das verstehst. Ich mache dann einfach weiter wie bisher.“","feedback":"Aus Sympathie bestätigst du das Gambit. Semmelweis und Wegener setzten sich durch, weil ihre Behauptungen prüfbar waren und die Prüfung bestanden, nicht weil sie verspottet wurden.","score":-2,"nextStepId":"step-fail"}]},"step-2-struggle":{"id":"step-2-struggle","speaker":"Bernd","speech":"„Siehst du, selbst du lachst. Die Großen werden eben erst belächelt. Das ist der Preis, wenn man der Zeit voraus ist.“","options":[{"text":"„Lass uns das ohne Spott sortieren: Galilei überzeugte mit einem Fernrohr, das jeder benutzen konnte. Welche prüfbare Vorhersage macht dein Konzept?“","style":"sokratisch","reaction":"„*zögert* Okay, ohne Witze... Eine Vorhersage. Dass es Zeit spart, vermute ich mal.“","feedback":"Gute Korrektur: Du kehrst vom Spott zur Prüfbarkeit zurück. Der Gesprächsfaden ist gerettet.","score":2,"nextStepId":"step-3"},{"text":"„Ach, Bernd, ich glaube, du bist halt einfach stur. Machen wir Schluss damit, es bringt ja ohnehin nichts, mit dir darüber zu reden, und ich habe noch zu tun.“","style":"ausstieg","reaction":"„Stur! Wie die Kirche bei Galilei! Danke, bestätigt wieder alles.“","feedback":"Ein genervter Abgang ohne Begründung ist eine kleine emotionale Niederlage und liefert Bernd ein weiteres Märtyrer-Bild.","score":-1,"nextStepId":"step-fail"}]},"step-3":{"id":"step-3","speaker":"Bernd","speech":"„Na gut, meine Vorhersage: Es wird besser. Aber das merkt man erst, wenn man es voll umsetzt, nicht in so einem Mini-Test. Und wenn es nicht besser wird, dann liegt es daran, dass die Abteilung nicht richtig mitgezogen hat.“","options":[{"text":"„Fragen wir andersherum: Was müsste passieren, damit du dein Konzept aufgibst? Eine Zahl, ein Datum, irgendein Ergebnis?“","style":"sokratisch","reaction":"„Aufgeben?! Also... *kratzt sich am Kopf* ...wenn es nach einem halben Jahr bei einer einzigen Kennzahl schlechter wäre, vielleicht. Aber das ist unfair, das würde ja nie...“","feedback":"Treffer: Die Frage nach dem Aufgabe-Kriterium ist der Härtetest der Falsifizierbarkeit (Red Flags). Dass Bernd zögert, zeigt, wo das Problem liegt.","score":3,"nextStepId":"step-4"},{"text":"„Okay, dann gib mir einen Bericht, in dem alles steht, was dein Konzept bringt. Ich lese ihn mir durch.“","style":"deeskalierend","reaction":"„Gerne! Ich schreib dir was Schönes. *grinst* Wirst sehen, das überzeugt dich.“","feedback":"Das Entgegenkommen ist nett, aber ohne vorab festgelegte prüfbare Kriterien kann jedes Ergebnis später umgedeutet werden. Brauchbar, aber nicht der Kern.","score":1,"nextStepId":"step-4"},{"text":"„Dann ist dein Konzept so gebaut, dass es nie falsch sein kann. Das ist keine Idee, das ist ein Glaubenssatz.“","style":"frontal","reaction":"„Glaubenssatz?! Du redest wie die Dogmatiker, die alles Neue abwürgen! Mit dir ist offenbar nicht zu reden.“","feedback":"Inhaltlich zielst du richtig, aber als Etikett am Gegenüber. Die Frage nach dem Aufgabe-Kriterium hätte denselben Punkt ohne Angriff gemacht.","score":-1,"nextStepId":"step-4"}]},"step-4":{"id":"step-4","speaker":"Bernd","speech":"„Ihr wollt mir alle bloß meine Idee kaputtmachen. Die Abteilung, du, die Chefs. Alle stecken unter einer Decke gegen echte Innovation. Aber ich lass mich nicht unterkriegen, ich bin ein Pionier!“","options":[{"text":"„Ich merke, wir drehen uns im Kreis: Du sprichst über deine Gegner, ich möchte über Zahlen reden. So kommen wir nicht weiter. Ich habe gern über eine prüfbare Vorhersage diskutiert, aber für heute lassen wir es hier gut sein.“","style":"ausstieg","reaction":"„Na gut, dann eben nicht. *brummt* Aber du wirst schon sehen.“","feedback":"Elegant: ruhig, begründet, ohne Abwertung. Das ist die Meta-Kommunikation aus „Die Ausstiegs-Strategie“. Der Ausstieg schützt deine Energie und lässt die Tür für Daten offen.","score":3,"nextStepId":"step-success"},{"text":"„Wenn du nicht bereit bist, ein einziges überprüfbares Kriterium zu nennen, ist die Unterhaltung für mich beendet. Ich bin gern für Fakten da, aber nicht für Verschwörungsgeschichten über die Abteilung.“","style":"ausstieg","reaction":"„Verschwörungsgeschichten ... na ja. *seufzt* Vielleicht hab ich mich da reingesteigert. Gut, für heute ist Schluss.“","feedback":"Der Ausstieg ist richtig und begründet, nur der Zusatz „Verschwörungsgeschichten“ ist ein Etikett und gibt Bernd Munition. Brauchbar, aber nicht elegant.","score":1,"nextStepId":"step-success"},{"text":"„Dann hole ich eben noch drei Kollegen dazu, die dir das alle sagen, und dann klären wir das hier und jetzt, bis du es einsiehst.“","style":"frontal","reaction":"„Na toll, ein Tribunal! Das ist genau, was Galilei erlebt hat! Ich hab's ja gesagt!“","feedback":"Die Versunkene-Kosten-Falle im Gespräch: Du investierst weiter in ein Spiel, das nicht mehr nach gemeinsamen Regeln läuft, und lieferst Bernd das Märtyrer-Bild frei Haus.","score":-2,"nextStepId":"step-fail"}]},"step-success":{"id":"step-success","speaker":"Bernd","speech":"„*schaut auf die Uhr* ...Eine prüfbare Vorhersage, hm. Ich schreib mal auf, welche Kennzahl ich eigentlich messen würde. Kaffee?“","options":[{"text":"„Gern. Und wenn du die Kennzahl hast, schau ich mir die Auswertung in einem halben Jahr mit dir an, egal, wie sie ausgeht.“","style":"deeskalierend","reaction":"„Abgemacht. Aber wenn ich recht habe, gibt's ein Denkmal.“ *grinst*","feedback":"Rund: Du bietest eine konkrete, prüfbare Verabredung an und beendest das Gespräch ohne Gesichtsverlust. Bernd hat zum ersten Mal ein Fernrohr in der Hand.","score":3}]},"step-fail":{"id":"step-fail","speaker":"Bernd","speech":"„Wie ich es mir gedacht habe: Alle gegen mich. Genau wie bei den Großen der Geschichte. Ich zieh das durch, und in zehn Jahren wollt ihr alle dabei gewesen sein.“ *rauscht ab*","options":[{"text":"Ende: Bernd fühlt sich in seiner Heldenrolle bestätigt, die Idee bleibt ungeprüft. Rechthaben und Weiterkommen sind zweierlei.","style":"ausstieg","reaction":"Beim nächsten Mal: nicht über die Ablehnung streiten, sondern nach dem Fernrohr fragen, also nach der prüfbaren Vorhersage.","feedback":"Das Gambit lebt davon, die Kritiker zum Thema zu machen. Jede Antwort über die Kritiker statt über die Prüfbarkeit füttert es.","score":0}]}},"status":"entwurf","familie":"ablehnung-ist-kein-beleg","fertigkeit":"F2","stufe":4,"kurz":"Ablehnung ist kein Beleg: Abgelehnt werden die seltenen Genies ebenso wie die vielen Irrtümer, also sagt sie nichts über die Idee. Was zählt, ist eine prüfbare Vorhersage. Bewegt sich nichts, ist ein ruhiger, begründeter Ausstieg kein Scheitern, sondern Energieschutz.","prueffrage":"Welches Ergebnis bis zu welchem Datum würde zeigen, dass das Konzept nicht funktioniert?","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (Thornton, S.; überarb. 31.07.2026)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Galileo Galilei (Miller, D. M.; überarb. 17.12.2025)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/galileo/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Sagan, C. (1979): Broca's Brain. Reflections on the Romance of Science. New York: Random House, Kap. 5 („Night Walkers and Mystery Mongers“)","oeffentlich":false}],"thema":"Zusammenleben"},{"id":"scen-influencer-eigene-recherche","title":"Kimmos Recherche-Stolz","subtitle":"Eigene Recherche, geübt mit Emotion und Motivation","character":"Kimmo, Studienfreund","avatar":"🔍","context":"Dein alter Studienfreund Kimmo erzählt dir beim Kaffee, er habe drei Stunden lang „selbst recherchiert“ und wisse jetzt, dass sein Arzt bei seiner Behandlung falschliegt. Er misstraut dem Arzt, seit er einen bestimmten Videokanal entdeckt hat, und fühlt sich zum ersten Mal als jemand, der „wirklich durchblickt“.","goal":"Nimm Kimmos Wunsch, selbst zu denken, ernst, und lenke ihn mit einer offenen Frage dazu, seine eigene Methode zu prüfen, ohne ihn bloßzustellen.","bereich":"Freunde","laenge":"mittel","ton":"sarkastisch","bestehenAb":6,"lektion":"„Selbst nachdenken“ ist eine Tugend, solange man auch die eigene Methode prüft; ohne diese Prüfung läuft „eigene Recherche“ meist auf Bestätigungsfehler hinaus. Nimm den Appell beim Wort („Absolut, selbst nachdenken!“) und frage nach der Methode: Wie suchst du aktiv nach den stärksten Gegenargumenten? Dahinter steckt oft ein Gefühl (hier: Stolz und Unabhängigkeit), das die Überzeugung trägt (Emotion und Motivation). Wer dieses Gefühl ernst nimmt, statt es zu belächeln, bleibt im Gespräch.","toolRef":"H.1.4","faktenRef":"G.1.2","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Kimmo","speech":"„Ich sag's dir: Drei Stunden habe ich mich reingegraben. Videos, Foren, Erfahrungsberichte. Und jetzt weiß ich mehr über meine Behandlung als mein Arzt. Der liest doch nur von der Pharma-Folie ab. Ich denke eben noch selbst nach, nicht wie die Schafe!“","options":[{"text":"„Drei Stunden Internet und du weißt mehr als jemand, der jahrelang studiert und Patienten behandelt hat? Das ist das Selbstbewusstsein eines Menschen, der noch nie eine Prüfung abgelegt hat.“","style":"sarkastisch","reaction":"„*verschränkt die Arme* Aha. Also bin ich jetzt dumm, weil ich nachdenke? Typisch. Wer Fragen stellt, wird abgestempelt. Genau das sagen sie in den Videos auch!“","feedback":"Der Spott trifft Kimmo als Person, nicht seine Behauptung. Er fühlt sich bestätigt: Wer ihn kritisiert, gehört zu den „Schafen“. So verstärkst du die Abwehr.","score":-2,"nextStepId":"step-fail"},{"text":"„Selbst nachdenken finde ich gut, da bin ich bei dir. Mich interessiert: Wie bist du bei den drei Stunden vorgegangen? Wonach hast du gesucht, und woran hast du gemerkt, dass eine Quelle was taugt?“","style":"sokratisch","reaction":"„Hm, wonach ich gesucht habe? Na ja, ich habe halt eingegeben, was ich vermutet habe, und geschaut, was kommt. Und was gut klang, habe ich mir gemerkt.“","feedback":"Stark! Du nimmst den Appell beim Wort und fragst nach der Methode (Anti-Denkmuster). Kimmos Wunsch, selbst zu denken, nimmst du ernst. Er beschreibt dabei selbst, dass er nach seiner Vermutung gesucht hat.","score":3,"nextStepId":"step-2"},{"text":"„Wow, das ist ja spannend! Dann solltest du deinem Arzt vielleicht wirklich nicht mehr vertrauen. Hast du schon einen anderen im Blick?“","style":"affektiv","reaction":"„Siehst du, endlich versteht mich mal einer! Ich habe da sogar einen Kanal, der erklärt, was man stattdessen tun kann. Schick ich dir gleich!“","feedback":"Du stimmst zu, nur um die Stimmung zu retten. Damit bestärkst du Kimmos Stolz und seine Abkehr vom Arzt, ohne die Methode je zu prüfen.","score":-1,"nextStepId":"step-fail"}]},"step-2":{"id":"step-2","speaker":"Kimmo","speech":"„Aber die Treffer waren ja eindeutig! Nach drei Stunden sind es Dutzende Berichte, die alle dasselbe sagen. Das kann doch kein Zufall sein. Ich habe nicht Meinungen gelesen, ich habe Beweise gesammelt!“","options":[{"text":"„Dutzende Berichte, die alle dasselbe sagen: Das ist genau der Zirkelschluss der Echokammer. Du hast nur gefunden, wonach du gesucht hast, weil du Glaubwürdigkeit nicht prüfen kannst.“","style":"frontal","reaction":"„Du hast ja keine Ahnung, wie viel Arbeit das war. Aber klar, wenn jemand gegen den Strom schwimmt, wird er gleich belehrt.“","feedback":"Inhaltlich nicht falsch, aber als fertige Diagnose kommt es als Belehrung an. Kimmo kann sie abwehren, weil er nicht selbst darauf kommt.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Du hast viel Zeit investiert, das merkt man. Eine Frage: Hast du auch gezielt nach der stärksten Gegenposition gesucht, also nach dem besten Argument, das dein Arzt vorbringen würde? Wie hat das ausgesehen?“","style":"sokratisch","reaction":"„Gegenposition? ...Ehrlich gesagt, nein. Die Seiten, die für meinen Arzt sprechen, habe ich überflogen, die waren alle so... von oben herab. Ich habe sie nicht richtig gelesen.“","feedback":"Treffer! Die Frage nach der aktiven Suche nach Gegenargumenten ist die Aktivierungs-Frage aus „Selbst nachdenken“ / „Eigene Recherche“. Sie führt Kimmo zum Bestätigungsfehler, ohne dass du ihn nennen musst.","score":3,"nextStepId":"step-3-success"},{"text":"„Dutzende Berichte klingen schon überzeugend. Aber vielleicht fragst du morgen trotzdem kurz deinen Arzt, was er dazu sagt?“","style":"ausstieg","reaction":"„Bringt doch nichts, der wiederholt ja nur seine Folie. Aber okay, wenn du meinst. Ich überlege es mir.“","feedback":"Freundlich und beziehungswahrend, aber ohne Anstoß zum Nachdenken. Kimmo bleibt in seiner Sicht, der Vorschlag verpufft.","score":1,"nextStepId":"step-3-struggle"}]},"step-3-success":{"id":"step-3-success","speaker":"Kimmo","speech":"„Okay, das ist unangenehm. Ich habe also nur die Seite gelesen, die mir recht gegeben hat. Aber dann weiß ich ja trotzdem nicht, wer recht hat. Und mein Arzt hat sich in der Sprechstunde wirklich keine Zeit genommen, das nervt mich einfach.“","options":[{"text":"„Dass er sich keine Zeit nimmt, ärgert dich zu Recht, und dein Antrieb ist gut. Wie wäre es, beim nächsten Termin deine Recherche mitzubringen und ihn nach den Gegenargumenten zu fragen?“","style":"deeskalierend","reaction":"„Hm. Eigentlich keine schlechte Idee. Dann kann ich prüfen, ob er mir das Gleiche verkaufen will wie die Videos. Gut, ich schreibe mir meine Fragen auf.“","feedback":"Rund! Du nimmst das Gefühl hinter der Haltung (Frust, Wunsch nach Mitsprache) ernst und gibst Kimmo einen konkreten Weg, seine Neugier zu nutzen.","score":3},{"text":"„Genau, du bist ja auch nicht dumm. Du hast nur die falschen Quellen erwischt. Nimm ab jetzt die richtigen, dann kommst du auf das gleiche Ergebnis wie ich.“","style":"frontal","reaction":"„Die richtigen Quellen? Also sagst du mir jetzt, welche ich gut finden soll? Das war ja auch wieder nur eine andere Autorität.“","feedback":"Du lieferst die Antwort fertig und trittst als neue Autorität auf. Der Ansatz zur Selbstprüfung geht verloren.","score":0},{"text":"„Siehst du, genau das habe ich dir gleich gesagt! Das hättest du dir drei Stunden sparen können, wenn du gleich auf mich gehört hättest. Man muss nicht alles selbst nachlesen.“","style":"sarkastisch","reaction":"„*schnaubt* Na klar, jetzt bist du wieder obenauf. Ich geh mir erstmal ein Wasser holen.“","feedback":"Kleines Triumphieren kostet Vertrauen. Kimmo war gerade offen und zieht sich zurück, weil er sich vorgeführt fühlt.","score":-1}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Kimmo","speech":"„Ich will einfach nicht mehr wie ein Patient behandelt werden, der nur nickt. Ich habe endlich das Gefühl, selbst zu verstehen, was mit mir los ist. Das nehmen mir die da oben nicht weg.“","options":[{"text":"„Das Gefühl, selbst zu verstehen, was mit dir los ist, verstehe ich gut. Wollen wir nächste Woche zusammen die Gegenseite lesen, nur zum Vergleich? Bei einem Kaffee.“","style":"deeskalierend","reaction":"„Zusammen? Ja, okay, warum nicht. Aber ich sag dir gleich: Ich bleibe skeptisch. Von beiden Seiten.“","feedback":"Gut gelöst: Du würdigst das Motiv (Selbstbestimmung) und bietest einen gemeinsamen, zwanglosen Vergleich an. Das Gespräch bleibt offen.","score":2},{"text":"„Dann viel Erfolg. Aber wundere dich nicht, wenn es schiefgeht, und renn nicht zu mir, wenn es dir schlecht geht.“","style":"sarkastisch","reaction":"„Danke für die Unterstützung. Ich wusste doch, dass man sich auf Freunde verlassen kann.“","feedback":"Drohung und Sarkasmus schneiden das Gespräch ab. Kimmo erlebt dich als Gegner, nicht als Verbündeten, und bleibt allein mit seinen Quellen.","score":-1},{"text":"„Schreib dir einfach mal auf, wo du bei den Quellen unsicher warst. Das ist kein Angriff auf dich, nur ein Gedankenspiel. Wir reden später weiter, einverstanden?“","style":"ausstieg","reaction":"„Hm. Aufschreiben kann ich ja mal. Später reden ist okay.“","feedback":"Ruhiger Ausstieg: Du lässt einen kleinen Prüfauftrag da und schützt die Freundschaft. Die Sachfrage bleibt für ein andermal offen.","score":1}]},"step-fail":{"id":"step-fail","speaker":"Kimmo","speech":"„Ich weiß, was ich gelesen habe, und ich bleibe dabei. Ich schick dir nachher den Kanal, dann siehst du es selbst.“ *packt sein Handy weg und steht auf*","options":[{"text":"Ende: Kimmo fühlt sich entweder belächelt oder nur bestätigt, die Frage nach seiner Methode ist nie gestellt worden. Sein Stolz auf die eigene Recherche ist eher größer geworden.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst nach dem Weg fragen, nicht nach dem Ergebnis: „Wie hast du das geprüft?“","feedback":"Der Wunsch, selbst zu denken, ist ein starkes Motiv. Wer ihn belächelt oder bedient, statt die Methode zu erfragen, verschenkt die Chance, dass Kimmo seine Quellen selbst hinterfragt.","score":0}]}},"status":"entwurf","familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","stufe":2,"kurz":"„Selbst nachdenken“ ist gut, wenn man auch die eigene Methode prüft: Wer nur sucht, was er schon vermutet, findet meist Bestätigung. Frag nach dem Vorgehen statt nach dem Ergebnis, und nimm das Gefühl ernst, das die Überzeugung trägt.","prueffrage":"Wonach genau wurde in den drei Stunden gesucht, und wie viele der gelesenen Quellen vertraten die Sicht des Arztes?","quellen":[{"typ":"doi","kurz":"Chinn, S.; Hasell, A. (2023): Support for „doing your own research“ is associated with COVID-19 misperceptions and scientific mistrust. Harvard Kennedy School Misinformation Review 4(3)","oeffentlich":true,"doi":"10.37016/mr-2020-117","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kunda, Z. (1990): The case for motivated reasoning. Psychological Bulletin 108(3), 480–498","oeffentlich":false,"doi":"10.1037/0033-2909.108.3.480","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"scen-krankenhausserie-ich","title":"Ich google meine Symptome","subtitle":"Verfügbarkeit und Angst, geübt mit dem Management emotionaler Kosten","character":"Ich selbst, mit Kopfschmerzen","avatar":"🩺","context":"Seit drei Tagen drückt ein dumpfer Kopfschmerz hinter deinen Schläfen. Gestern Abend hast du die Symptome gegoogelt, und seither kreisen deine Gedanken nur noch um die dramatischsten Treffer. Dein Kollege Jonas sitzt gegenüber, merkt, dass du blass bist, und fragt, was los ist. Bevor du ihm antwortest, führst du ein inneres Gespräch: Du nimmst die Rolle des klaren Denkens ein, die Figur im Gespräch ist deine eigene, ängstliche Stimme.","goal":"Hilf deinem ängstlichen Ich, die Verfügbarkeitsheuristik zu durchschauen, die Angst ernst zu nehmen und die eigene Energie klug einzuteilen.","bereich":"Ich selbst","laenge":"lang","ton":"ernst","bestehenAb":9,"lektion":"Was sich beim Googeln aufdrängt, ist nicht das, was am häufigsten vorkommt: Dramatische Einzelfälle sind im Gedächtnis und in den Suchtreffern überrepräsentiert, und das Gehirn verwechselt Verfügbarkeit mit Wahrscheinlichkeit. Die Aktivierungs-Frage „Was sagen die langweiligen Statistiken?“ ersetzt das Gefühl durch Zahlen, und das Management emotionaler Kosten erinnert dich daran, deine begrenzte mentale Energie nicht an Grübelschleifen zu verbrennen. Angst ernst nehmen, ohne ihr zu folgen, ist die Kunst. Anhaltende Beschwerden gehören in jedem Fall ärztlich abgeklärt.","toolRef":"H.1.2","faktenRef":"B.3","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Ich selbst, mit Kopfschmerzen","speech":"„Ich habe die ganze Nacht gegoogelt. Die Beschreibung passt exakt auf mich: Kopfschmerzen hinter den Schläfen, morgens schlimmer. Das ist garantiert ein Hirntumor, im Netz steht es ganz genau so. Ich kann an nichts anderes mehr denken.“","options":[{"text":"„Das ist völliger Quatsch. Du hast nur Stress und hysterisch gegoogelt. Hör auf mit dem Unsinn, ein Tumor ist es ganz sicher nicht, so ein Theater ist nicht nötig.“","style":"frontal","reaction":"„Ach, jetzt bin ich also hysterisch? Du hast leicht reden. Es steht doch schwarz auf weiß da! Ich fühle mich nicht ernst genommen.“","feedback":"Frontal und abwertend: Die Angst wird vom Tisch gewischt, ohne sie zu verstehen. Wer sich nicht ernst genommen fühlt, klammert sich fester an das, was ihn ängstigt.","score":-2,"nextStepId":"step-fail"},{"text":"„Das klingt wirklich beängstigend, und ich merke, wie sehr dich das beschäftigt. Erzähl mal: Welche Seiten hast du gelesen, und was ist dir davon am stärksten im Kopf geblieben?“","style":"deeskalierend","reaction":"„*atmet langsam aus* Danke, dass du fragst. Da war ein Erfahrungsbericht von einer Frau, die zuerst auch nur Kopfschmerzen hatte. Der hat mich total mitgenommen. Den habe ich noch ganz genau vor Augen.“","feedback":"Gut: Du nimmst das Gefühl ernst, bestätigst aber nicht den Inhalt. Außerdem lenkst du auf den entscheidenden Punkt, nämlich das, was mental besonders verfügbar ist.","score":3,"nextStepId":"step-2"},{"text":"„Oh nein, das klingt ja schrecklich. Lass uns sofort weitergoogeln, was die Frühwarnzeichen sind und welche Klinik die beste ist, bevor es schlimmer wird.“","style":"affektiv","reaction":"„Genau, ich brauche alle Informationen! Ich suche gleich nach weiteren Fällen, vielleicht finde ich noch mehr Parallelen zu mir.“","feedback":"Du übernimmst die Panik und fütterst die Suche weiter. Jeder zusätzliche dramatische Treffer macht das Bild im Kopf noch verfügbarer und verbraucht zugleich Energie.","score":-1,"nextStepId":"step-panic"}]},"step-2":{"id":"step-2","speaker":"Ich selbst, mit Kopfschmerzen","speech":"„Der Bericht war so lebendig, mit Fotos, mit der ganzen Geschichte, wie schnell alles ging. Und die Suchtreffer waren fast alle von der Sorte. Das kann doch kein Zufall sein, dass mir ständig diese Fälle angezeigt werden!“","options":[{"text":"„Wer schreibt eigentlich ins Netz: eher die dramatischen Fälle oder die vielen harmlosen Kopfschmerzen, die von selbst vergehen? Was heißt das dann für die Auswahl, die du siehst?“","style":"sokratisch","reaction":"„Hm... Die harmlosen Geschichten erzählt wirklich niemand. Wer schreibt schon einen Blog über Kopfschmerzen, die nach zwei Tagen weg waren? Das heißt, ich sehe fast nur die Spitze des Eisbergs.“","feedback":"Treffend: Du lässt das Ich die Verzerrung der Stichprobe selbst entdecken und knüpfst an die Verfügbarkeitsheuristik an.","score":3,"nextStepId":"step-3"},{"text":"„Das ist eben die Verfügbarkeitsheuristik, Punkt. Dein Gehirn ist halt fehlerhaft gebaut, da kannst du nichts machen.“","style":"sarkastisch","reaction":"„Na toll, mein Gehirn ist also kaputt. Und das soll mich jetzt beruhigen? Ich habe trotzdem diese Kopfschmerzen!“","feedback":"Das Fachwort wird als Etikett benutzt, ohne es zu erklären, und klingt dabei abwertend. Dass die Faustregel oft korrekt und nützlich ist, geht unter.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Stimmt, das ist wirklich auffällig. Wahrscheinlich ist da wirklich was dran, wenn so viele Fälle auftauchen. Vielleicht sollten wir das ernster nehmen.“","style":"affektiv","reaction":"„Siehst du, genau das sage ich ja! Wenn schon alle Treffer in diese Richtung zeigen, dann muss es doch stimmen.“","feedback":"Du schließt von der Menge leicht greifbarer Beispiele auf die Wahrscheinlichkeit. Genau das ist der Denkfehler der Verfügbarkeitsheuristik.","score":-2,"nextStepId":"step-fail"}]},"step-3":{"id":"step-3","speaker":"Ich selbst, mit Kopfschmerzen","speech":"„Okay, das leuchtet mir ein. Aber das Bild von dieser Frau geht mir einfach nicht aus dem Kopf. Es fühlt sich so wahrscheinlich an. Wie kriege ich Abstand von diesem Gefühl?“","options":[{"text":"„Frag dich mal: Dieses Bild fällt mir leicht ein und fühlt sich wichtig an. Aber was sagen die langweiligen Statistiken zur tatsächlichen Häufigkeit? Das kann dein Arzt beantworten.“","style":"sokratisch","reaction":"„Die langweiligen Zahlen... Das ist eine gute Idee. Ich lasse das Gefühl kurz beiseite und frage lieber nach, wie oft so etwas wirklich vorkommt. Das fühlt sich schon ruhiger an.“","feedback":"Sehr gut: Die Aktivierungs-Frage des Anti-Denkmusters trennt das leichte Abrufen vom tatsächlichen Vorkommen und schickt dich an die richtige Informationsquelle.","score":3,"nextStepId":"step-4"},{"text":"„Denk einfach nicht mehr daran. Wenn du dich fest darauf konzentrierst, nicht daran zu denken, ist das Gefühl bald weg.“","style":"frontal","reaction":"„Das ist genau, was ich schon die ganze Nacht versuche! Je mehr ich es verdränge, desto stärker kommt das Bild wieder hoch.“","feedback":"Verdrängen nimmt dem Gefühl nicht die Kraft und verbraucht zusätzlich Energie. Hilfreicher ist, das Gefühl durch eine konkrete Frage zu ersetzen.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Lass uns erst mal die Gefühle beiseitelegen und schauen, was wir über die Häufigkeit solcher Fälle wissen. Das Bild bleibt wahrscheinlich noch eine Weile, aber es muss nicht entscheiden.“","style":"deeskalierend","reaction":"„Ja, vielleicht kann ich das Bild einfach da sein lassen, ohne ihm zu glauben. Wo finde ich denn verlässliche Zahlen?“","feedback":"Brauchbar: Du erlaubst dem Bild, da zu sein, und lenkst auf Zahlen um. Die konkrete Aktivierungs-Frage fehlt noch, aber die Richtung stimmt.","score":2,"nextStepId":"step-4"}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Ich selbst, mit Kopfschmerzen","speech":"„Ich drehe mich im Kreis. Ich will das ja loswerden, aber es hilft nichts. Was mache ich bloß?“","options":[{"text":"„Lass uns zurück zu einer konkreten Frage: Was sagen die Zahlen statt deines Gefühls? Wie häufig kommt so etwas wirklich vor, und was ist viel häufiger?“","style":"sokratisch","reaction":"„Die Häufigkeit... ja, das ist eine konkrete Frage. Die kann ich beantworten lassen, statt sie zu fühlen. Das beruhigt mich ein bisschen.“","feedback":"Gute Korrektur: Du kehrst zur Aktivierungs-Frage zurück und gibst dem Ich einen konkreten Auftrag, statt es zum Verdrängen zu zwingen.","score":2,"nextStepId":"step-4"},{"text":"„Dann lass es halt. Du musst auch nicht alles verstehen, grüble einfach weiter, wenn es dir hilft.“","style":"ausstieg","reaction":"„Wenn ich weitergrüble, wird es nur schlimmer. Aber egal, ich komme eh nicht davon los.“","feedback":"Aufgeben ohne Alternative überlässt das Ich der Grübelschleife. Das Management emotionaler Kosten verlangt, einen Ausweg anzubieten.","score":-2,"nextStepId":"step-fail"},{"text":"„Erlaub dir, die Suche für heute zu beenden. Wir schreiben auf, was du wissen willst, und holen uns morgen die verlässlichen Antworten dazu.“","style":"deeskalierend","reaction":"„Aufschreiben und morgen klären... das fühlt sich machbar an. Ich muss nicht heute Nacht alles lösen.“","feedback":"Brauchbar: Du entlastest das Ich und legst eine Pause ein. Das spart Energie, die inhaltliche Klärung der Häufigkeit bleibt aber noch offen.","score":1,"nextStepId":"step-4"}]},"step-4":{"id":"step-4","speaker":"Ich selbst, mit Kopfschmerzen","speech":"„Das hilft. Aber ich merke: Ich habe mich in den letzten Tagen komplett verausgabt. Stundenlang gelesen, mich immer unruhiger gefühlt, kaum geschlafen. Soll ich jetzt jeden Tag in den Foren nachschauen, ob ich etwas übersehe?“","options":[{"text":"„Genau, bleib wachsam. Je mehr du liest, desto besser bist du vorbereitet. Wer aufhört zu suchen, übersieht vielleicht etwas Wichtiges, und das möchtest du nicht.“","style":"affektiv","reaction":"„Du hast recht, sicher ist sicher. Ich lese heute Abend gleich weiter und schaue auch in anderen Foren.“","feedback":"Das Dauergrübeln wird als Vorsicht verkauft. Es kostet Schlaf und Nerven, ohne die Sachlage zu klären. Mehr Treffer machen das Bild nur noch lebhafter.","score":-2,"nextStepId":"step-fail"},{"text":"„Überleg mal, wie viel Energie dich die letzten Nächte gekostet haben. Ist das eine Schlacht, die du mit weiterem Googeln gewinnst, oder eine, die du besser mit einem Arzt klärst?“","style":"sokratisch","reaction":"„Beim Googeln gewinne ich nichts, das merke ich jetzt. Das klärt ein Arzt viel besser. Ich verbrenne meine Kräfte an der falschen Stelle.“","feedback":"Sehr gut: Die Aktivierungs-Frage des Energie-Managements fragt nach Kosten und realistischem Gewinn und lenkt die Kraft dahin, wo sie wirkt.","score":3,"nextStepId":"step-5-success"},{"text":"„Du könntest die Suche zumindest auf eine halbe Stunde am Tag begrenzen. Dann bleibst du informiert, aber verlierst dich nicht in endlosen Foren.“","style":"deeskalierend","reaction":"„Eine halbe Stunde... das ist ein Kompromiss. Aber ob ich da wirklich aufhören kann, weiß ich nicht.“","feedback":"Brauchbar: Eine feste Grenze schont Energie. Der Kern bleibt aber unbeantwortet, nämlich ob weiteres Googeln hier überhaupt etwas bringt.","score":1,"nextStepId":"step-5-success"}]},"step-5-success":{"id":"step-5-success","speaker":"Ich selbst, mit Kopfschmerzen","speech":"„Gut, ich mache einen Termin beim Hausarzt aus und lasse die Foren links liegen. Eine Sache noch: Wie sage ich Jonas, dass ich kaum geschlafen habe, ohne dass er mich für hysterisch hält?“","options":[{"text":"„Sag ihm einfach, wie es dir geht: Du hast dich verrannt und kümmerst dich jetzt um einen Arzttermin. Das ist keine Schwäche, sondern Fürsorge für dich selbst.“","style":"deeskalierend","reaction":"„Ja, so sage ich es ihm. Es fühlt sich gut an, die Angst ernst zu nehmen, ohne ihr hinterherzulaufen. Danke, dass du mich runtergeholt hast.“","feedback":"Rund: Selbstfürsorge, ein konkreter nächster Schritt und der Verzicht auf das Dauergrübeln verbinden Verfügbarkeits-Check und Energie-Management.","score":3},{"text":"„Erzähl ihm lieber gar nichts. Die Leute verstehen das sowieso nicht und halten dich nur für überempfindlich, und am Ende hast du nur Ärger.“","style":"ausstieg","reaction":"„Dann behalte ich es für mich... Aber ehrlich gesagt macht mich das auch einsam.“","feedback":"Sich zu verschließen, schont nicht die Energie, sondern isoliert. Ein offenes Wort entlastet, und genau dazu soll das Energie-Management beitragen.","score":0}]},"step-panic":{"id":"step-panic","speaker":"Ich selbst, mit Kopfschmerzen","speech":"„Jeder neue Treffer bestätigt mich: immer wieder dieselben Geschichten, immer wieder dasselbe Bild. Es muss einfach stimmen. Ich suche heute Nacht weiter, bis ich alles gelesen habe.“","options":[{"text":"Ende: Die Suche hat die Angst nur größer gemacht. Mehr dramatische Treffer heißt nicht mehr Wahrscheinlichkeit.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst innehalten, die Aktivierungs-Frage stellen und anhaltende Beschwerden ärztlich abklären lassen, statt weiterzusuchen.","feedback":"Je mehr lebhafte Fälle du liest, desto verfügbarer wird das Bild. Gleichzeitig laugt das Dauergrübeln dich aus. Die Klärung gehört in ärztliche Hände.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Ich selbst, mit Kopfschmerzen","speech":"„Ich fühle mich nicht verstanden. Dann mache ich es eben allein weiter. Ich lese nachts weiter, bis ich Gewissheit habe.“","options":[{"text":"Ende: Das Gespräch endet ohne Klärung. Die Angst bleibt, die Nächte werden länger.","style":"ausstieg","reaction":"Ein ruhiger Blick auf Häufigkeit und die eigene Energie hätte mehr gebracht als jede weitere Recherche.","feedback":"Mentale Verfügbarkeit ist keine Wahrscheinlichkeit, und wer seine Kräfte im Grübeln aufbraucht, hat nichts mehr für das, was zählt.","score":0}]}},"status":"entwurf","familie":"basisrate-beachten","fertigkeit":"F4","stufe":3,"kurz":"Was beim Googeln am stärksten ins Auge springt, ist nicht das Häufigste: Dramatische Einzelfälle werden öfter erzählt und bleiben besser im Gedächtnis. Frag nach den Häufigkeiten statt nach dem Gefühl, und lass anhaltende Beschwerden ärztlich abklären.","prueffrage":"Wie viele Menschen mit genau diesen Kopfschmerzen schreiben danach einen Bericht ins Netz, und welche Verläufe tauchen in den Treffern kaum auf?","quellen":[{"typ":"doi","kurz":"White, R. W.; Horvitz, E. (2009): Cyberchondria: Studies of the Escalation of Medical Concerns in Web Search. ACM Transactions on Information Systems 27(4) (Autorenfassung frei)","oeffentlich":true,"doi":"10.1145/1629096.1629101","url":"https://www.erichorvitz.com/cyberchondria_TOIS.pdf","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"scen-feed-algorithmus-wut","title":"Jule und der Feed voller Empörung","subtitle":"„Alle denken so wie ich“, geübt mit kognitiver Entkopplung","character":"Jule, Freundin","avatar":"📱","context":"Deine Freundin Jule sitzt beim Kaffee mit dir zusammen und scrollt immer wieder auf ihrem Handy. Sie ist aufgebracht, weil sich in ihrem Feed seit Wochen ein wütender Beitrag an den nächsten reiht. Für sie ist klar: Die Mehrheit im Land ist außer sich, und alles steht kurz vor dem Kollaps.","goal":"Hilf Jule zu erkennen, dass ihr Feed eine auf Aufmerksamkeit optimierte Auswahl ist und kein Abbild der Gesellschaft, ohne sie bloßzustellen oder die Freundschaft zu belasten.","bereich":"Freunde","laenge":"mittel","ton":"ernst","bestehenAb":6,"lektion":"Ein Feed ist keine Umfrage, sondern eine Auswahl, die auf Verweildauer und Engagement getrimmt ist, und Empörung bringt Reichweite. Der Algorithmus weiß nicht, was wahr ist, er weiß nur, was dich zum Reagieren bringt. Wer eine Überzeugung als etwas behandelt, das man hat, nicht als etwas, das man ist, kann sie prüfen, ohne das Gesicht zu verlieren. Das ist kognitive Entkopplung. Wer dabei die Person schont und nur die Behauptung prüft, schützt zugleich die Freundschaft.","toolRef":"H.1.1","faktenRef":"E.4.3","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Jule","speech":"„Hast du das heute schon gesehen? Schon wieder ein Skandal, und schon wieder tausende Kommentare, in denen alle ausrasten. Ehrlich, die Leute sind am Ende. Das ganze Land brennt, und du tust so, als wäre alles normal!“","options":[{"text":"„Jule, das ist doch alles nur Social-Media-Gebrüll. Du lässt dich seit Wochen von Wutbeiträgen aufhetzen. Leg das Handy weg, du übertreibst maßlos.“","style":"frontal","reaction":"„Ich übertreibe?! Ich bin informiert, im Gegensatz zu dir! Du willst nur nicht hinsehen, wie schlimm es ist.“ *verschränkt die Arme und dreht das Handy weg*","feedback":"Frontalangriff. Du triffst vielleicht einen wahren Kern, aber Jule hört: „Du bist hysterisch.“ Ihre Identität als Informierte wird angegriffen, nicht ihre Behauptung, und sie macht dicht.","score":-2,"nextStepId":"step-fail"},{"text":"„Das klingt wirklich belastend. Du bist offenbar richtig aufgewühlt. Zeig mal, was dich heute am meisten gepackt hat?“","style":"deeskalierend","reaction":"„*atmet durch* Ehrlich gesagt ja, ich komme kaum noch zur Ruhe. Es ist fast jeden Tag dasselbe Thema, und alle sind so wütend.“","feedback":"Gut gemacht. Mitfühlende Empathie: Du nimmst das Gefühl ernst, ohne die Behauptung „das Land brennt“ zu bestätigen. Der Gesprächsfaden bleibt offen.","score":3,"nextStepId":"step-2"},{"text":"„Das stimmt, es ist furchtbar. Ich krieg das ja auch mit, ich bin schon ganz fertig. Vielleicht sollten wir uns wirklich auf das Schlimmste einstellen.“","style":"affektiv","reaction":"„Siehst du, genau! Endlich versteht mich jemand. Es geht ja alles den Bach runter, das spürt doch jeder!“","feedback":"Du steigst in die Stimmung ein und bestätigst eine Zuspitzung, die du gar nicht überprüft hast. Aus Mitgefühl wird Mitverstärkung.","score":-1,"nextStepId":"step-panic"}]},"step-2":{"id":"step-2","speaker":"Jule","speech":"„Na, guck doch selbst: Ich scrolle durch und überall dasselbe. Wütende Posts, empörte Kommentare, kaum jemand, der noch ruhig ist. Wenn ich überall Wut sehe, dann ist die Wut eben überall. Das ist doch eine Tatsache!“","options":[{"text":"„Dein Feed ist keine Umfrage, Jule. Algorithmen füttern dich mit Wut, weil Wut Klicks bringt. Das ist wissenschaftlich belegt, also kannst du daraus gar nichts über die Mehrheit ableiten.“","style":"frontal","reaction":"„Ach, jetzt kommst du mit Algorithmen. Ich sehe doch mit eigenen Augen, was los ist! Du erklärst mir die Welt, als wärst du der Einzige, der Bescheid weiß.“","feedback":"Teils stimmig: Empörung bringt nachweislich Reichweite. Dass Algorithmen dich gezielt mit Wut füttern, ist aber vereinfacht, die Beleglage dazu ist gemischt. Vor allem lieferst du das Ergebnis als Belehrung und stellst eine Gewissheit gegen ihre. Ohne eigenes Nachdenken wirkt das wie ein Angriff.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Das kann ich verstehen, es fühlt sich überall nach Wut an. Mich würde interessieren: Wer ist denn in deinem Feed besonders laut, und wie viele von deinen Freunden und Kollegen sind im echten Leben so aufgebracht?“","style":"sokratisch","reaction":"„Hm... im echten Leben? Ehrlich gesagt, meine Kollegin Mareike redet eher übers Wochenende. Und mein Nachbar kümmert sich gerade nur um seinen Garten. Aber das sind eben die, die nichts mitbekommen!“","feedback":"Sehr gut. Street Epistemology: Du lenkst mit einer offenen Frage auf einen Abgleich zwischen Feed und Alltag, ohne zu urteilen. Jule beginnt, zwei Datenquellen zu vergleichen.","score":3,"nextStepId":"step-3"},{"text":"„Ja, die Stimmung ist wirklich aufgeheizt. Ich würde da an deiner Stelle besser alles mitverfolgen, damit du immer auf dem Laufenden bist.“","style":"affektiv","reaction":"„Genau, das mache ich ja auch! Ich muss wissen, was los ist, und je mehr ich lese, desto klarer wird mir, wie schlimm es ist.“","feedback":"Du bestärkst ausgerechnet das Verhalten, das den Feed weiter in Richtung Empörung trimmt. Mehr Konsum bringt hier kein klareres Bild, sondern ein einseitigeres.","score":-2,"nextStepId":"step-fail"}]},"step-3":{"id":"step-3","speaker":"Jule","speech":"„Okay, die beiden sind nicht sauer, aber das heißt ja nichts. Die sind eben ahnungslos. Auf der Plattform sehe ich, was wirklich los ist, nämlich bei denen, die sich engagieren und die Wahrheit sagen.“","options":[{"text":"„Dann seh ich das wohl falsch, und dein Feed hat recht. Ich mach mir nur Sorgen, dass du dich so reinsteigerst, aber ich halte mich da lieber raus.“","style":"ausstieg","reaction":"„Ja, halt dich da ruhig raus. Ich weiß schon, was ich sehe.“","feedback":"Du ziehst dich zu früh zurück und nimmst die Frage vom Tisch, bevor Jule sie selbst zu Ende denken konnte. Der Zugang geht verloren.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Kann sein. Aber überleg mal: Wie entscheidet die Plattform eigentlich, was sie dir zeigt? Zeigt sie dir, was am wichtigsten ist, oder das, worauf du am ehesten reagierst?“","style":"sokratisch","reaction":"„Hm. Sie zeigt mir wohl das, worauf ich klicke... *stockt* Ich hab letzte Woche einen Beitrag wütend kommentiert, und seitdem kommen ständig solche. Aber heißt das, dass die Wut nicht echt ist?“","feedback":"Treffend. Du stellst die Aktivierungsfrage aus „Algorithmen & Wut“ in eigenen Worten und lässt Jule selbst darauf kommen, dass sie am Auswahlprozess beteiligt ist. So bleibt ihr Selbstbild unversehrt.","score":3,"nextStepId":"step-4"},{"text":"„Wenn die anderen angeblich ahnungslos sind, dann ist dein Feed halt eine Blase. Du merkst gar nicht, wie du dich in deiner eigenen Welt einschließt.“","style":"sarkastisch","reaction":"„Eine Blase? Na toll. Jetzt bin ich also die Dumme, die nichts kapiert. Danke für nichts.“","feedback":"Der Sarkasmus macht aus einer gemeinsamen Frage ein Urteil über Jule. Seziert wird die Behauptung, nicht der Mensch, und hier hast du den Menschen getroffen.","score":-2,"nextStepId":"step-fail"}]},"step-4":{"id":"step-4","speaker":"Jule","speech":"„Also ist meine Wut nicht echt? Willst du sagen, ich habe mich total verrannt? Dann war ich ja ziemlich naiv, was?“","options":[{"text":"„Deine Wut ist echt, und es ist verständlich, dass dich das mitnimmt. Ob sie die ganze Gesellschaft abbildet, hängt davon ab, was dein Feed zeigt. Mit Naivität hat das nichts zu tun.“","style":"deeskalierend","reaction":"„*atmet auf* Okay. Das klingt wenigstens nicht, als wäre ich blöd. Es ist nur seltsam, zu merken, dass ich so mitgerissen wurde. Und was mache ich jetzt damit?“","feedback":"Sehr stark. Du trennst die Person von der Idee, wie es kognitive Entkopplung verlangt: Ihre Überzeugung ist etwas, das sie hat, nicht etwas, das sie ist. So bleibt der Weg für ein Umdenken ohne Gesichtsverlust offen.","score":3,"nextStepId":"step-5-success"},{"text":"„Naja, ein bisschen verrannt schon, wenn ich ehrlich bin. Du hast dich da ziemlich hineinziehen lassen. Aber das wird schon wieder, das passiert vielen.“","style":"frontal","reaction":"„Ein bisschen verrannt... *schaut weg* Du hast ja leicht reden. Ich muss jetzt erstmal verdauen, dass du mich so siehst.“","feedback":"Es stimmt zwar im Kern, aber die Wortwahl bestätigt ihre Sorge, sich blamiert zu haben. Wer sich beschämt fühlt, verteidigt sich, statt nachzudenken.","score":0,"nextStepId":"step-5-struggle"},{"text":"„Nein, du hast dich überhaupt nicht verrannt. Eigentlich hast du in allem recht, dein Feed spiegelt die Lage einfach wider. Ich war nur etwas zu skeptisch.“","style":"affektiv","reaction":"„Siehst du, ich wusste es! Dann bin ich ja doch auf dem richtigen Weg. Danke, dass du es endlich einsiehst.“","feedback":"Um den Konflikt zu glätten, nimmst du alles zurück. Das bestärkt die verzerrte Sicht und lässt Jule mit dem Algorithmus allein.","score":-2,"nextStepId":"step-fail"}]},"step-5-success":{"id":"step-5-success","speaker":"Jule","speech":"„Okay, dann will ich es ausprobieren. Ich kenne ja diese Idee, den Feed einfach mal durcheinanderzubringen. Aber was bringt das genau, und wo fange ich an?“","options":[{"text":"„Such dir ein, zwei Kanäle abseits deiner üblichen Quellen und schau, was der Feed danach zeigt. Nächste Woche vergleichen wir dein Gefühl. Ich bring den Kuchen mit.“","style":"humorvoll","reaction":"„*lacht* Abgemacht, und ohne Kuchen mach ich da gar nichts. Ich versuch’s mal, und ich bin gespannt, ob sich meine Stimmung wirklich ändert.“","feedback":"Gelungen. Du gibst eine konkrete, machbare Übung mit und verknüpfst sie mit Verbundenheit. Jule behält die Handlungshoheit, und die Freundschaft ist gestärkt.","score":3},{"text":"„Am besten löschst du die App komplett und bleibst für immer offline, dann hast du Ruhe vor dem ganzen Spuk. Das macht ohnehin nur unglücklich.“","style":"frontal","reaction":"„Komplett offline? Dann bekomme ich ja gar nichts mehr mit! Das ist doch übertrieben, das kann ich nicht.“","feedback":"Das ist eine überzogene Radikalmaßnahme, die niemand durchhält. Eine kleine, machbare Übung schlägt hier den großen Umbruch.","score":-1},{"text":"„Ach, das erledigt sich wahrscheinlich von allein. Mach dir keine Gedanken, wird schon. Algorithmen ändern sich ständig, da kommt es auf dich nicht an.“","style":"ausstieg","reaction":"„Naja... vielleicht. Dann lass ich es wohl, wie es ist.“","feedback":"Du lässt die gewonnene Offenheit verpuffen. Ohne konkrete nächste Schritte bleibt der Erkenntnisschub folgenlos.","score":-1}]},"step-5-struggle":{"id":"step-5-struggle","speaker":"Jule","speech":"„Ich weiß gerade nicht, was ich davon halten soll. Ich muss das erst mal sacken lassen.“","options":[{"text":"„Völlig okay, nimm dir die Zeit. Mir ist wichtig, dass wir uns gut verstehen. Lass uns am Wochenende rausgehen, den Kopf freibekommen, dann sehen wir weiter.“","style":"deeskalierend","reaction":"„Ja, das klingt gut. Danke, dass du nicht lockerlässt, aber auch nicht drängst. Ein Spaziergang tut mir bestimmt gut.“","feedback":"Guter Ausstieg. Du schützt die Beziehung und lässt die Sachfrage für einen besseren Moment offen, statt weiter zu drängen.","score":2},{"text":"„Du musst das nicht sacken lassen, du musst es einfach einsehen. Die Fakten liegen doch auf dem Tisch, und es gibt nichts mehr zu überlegen.“","style":"frontal","reaction":"„Siehst du, genau deswegen kann man mit dir nicht reden. Ich muss jetzt los.“","feedback":"Du erhöhst den Druck, obwohl Jule ausdrücklich Raum braucht. Ein Mensch, der gedrängt wird, verteidigt seine Position.","score":-2},{"text":"„Alles klar. Dann lassen wir das Thema ruhen und reden einfach über etwas anderes. Was steht bei dir diese Woche an, Jule?“","style":"ausstieg","reaction":"„*entspannt sich sichtlich* Gern, danke. Ich hab da einen Ausflug geplant, ich erzähl dir davon.“","feedback":"Ein freundlicher, wenn auch etwas abrupter Themenwechsel. Er schützt die Stimmung, lässt aber offen, wie es mit dem Feed weitergeht.","score":1}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Jule","speech":"„Ich will jetzt eigentlich nicht weiter darüber streiten. Das geht mir alles zu nah.“","options":[{"text":"„Das verstehe ich, ich möchte nicht mit dir streiten. Lass uns einfach den Kaffee genießen und uns ein andermal in Ruhe darüber unterhalten.“","style":"deeskalierend","reaction":"„Ja, bitte. Ich bin ein bisschen erschöpft von dem Ganzen. Danke, dass du mir den Druck rausnimmst.“","feedback":"Gute Ausstiegsstrategie. Die Beziehung bleibt heil, und die Tür für ein späteres Gespräch ist offen.","score":2},{"text":"„Du blockst ja ständig ab, wenn jemand etwas anderes sagt. Das ist genau das Problem an deiner Haltung, und das sage ich dir jetzt mal ehrlich.“","style":"sarkastisch","reaction":"„Wow, jetzt reicht’s mir wirklich. Ich geh jetzt.“ *packt ihre Sachen*","feedback":"Ein Vorwurf an die Person statt eine Frage zur Sache. Damit endet das Gespräch, ohne dass irgendetwas geklärt ist.","score":-2},{"text":"„Schon gut, dann lassen wir es. Aber denk bitte mal darüber nach, wo du deine Infos herhast und wer sie dir zeigt.“","style":"sokratisch","reaction":"„Mach ich vielleicht. Aber jetzt nicht, okay?“","feedback":"Ein sanfter Gedankenanstoß zum Mitnehmen, ohne Druck. Es bleibt ein Samenkorn, auch wenn heute nicht mehr drin ist.","score":1}]},"step-fail":{"id":"step-fail","speaker":"Jule","speech":"„Weißt du was, ich merke schon, du verstehst es nicht. Ich lese lieber weiter bei Leuten, die mich ernst nehmen.“ *steckt das Handy ein und wendet sich ab*","options":[{"text":"Ende: Jule fühlte sich nicht gehört und taucht jetzt vermutlich noch tiefer in ihren Feed ein.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst das Gefühl ernst nehmen und dann mit offenen Fragen arbeiten.","feedback":"Frag dich: Wollte ich Jule recht geben, mich durchsetzen oder ihr beim Nachdenken helfen? Die Empathie-Matrix hilft, die Reihenfolge richtig zu setzen.","score":0}]},"step-panic":{"id":"step-panic","speaker":"Jule","speech":"„Wir müssten eigentlich alles dafür tun, uns vorzubereiten. Ich lese ab jetzt noch mehr mit, damit mir nichts entgeht. Und du solltest das auch tun!“","options":[{"text":"Ende: Ihr bestärkt euch gegenseitig in der düsteren Stimmung, weil niemand mehr den ruhigen Gegenpol hält.","style":"ausstieg","reaction":"Mitgefühl ja, Mitverstärkung nein: Wer mitzieht, kann nicht stützen.","feedback":"Mitfühlende Empathie heißt, das Gefühl zu verstehen und selbst klar zu bleiben, damit Jule einen Halt hat und keinen Verstärker.","score":0}]}},"status":"entwurf","familie":"anreize-durchschauen","fertigkeit":"F1","stufe":2,"kurz":"Ein Feed ist keine Umfrage, sondern eine Auswahl, die auf Reaktionen getrimmt ist, und Empörung bringt Reichweite. Wer die eigene Überzeugung als etwas betrachtet, das man hat, nicht als etwas, das man ist, kann sie prüfen, ohne das Gesicht zu verlieren.","prueffrage":"Wie viele Menschen im eigenen Alltag sind so aufgebracht wie die Stimmen im Feed, und wonach wählt die Plattform aus, was sie zeigt?","quellen":[{"typ":"doi","kurz":"Milli, S. u. a. (2025): Engagement, user satisfaction, and the amplification of divisive content on social media. PNAS Nexus 4(3), pgaf062","oeffentlich":true,"doi":"10.1093/pnasnexus/pgaf062","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rathje, S.; Van Bavel, J. J.; van der Linden, S. (2021): Out-group animosity drives engagement on social media. PNAS 118(26), e2024292118","oeffentlich":true,"doi":"10.1073/pnas.2024292118","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"scen-glueckssocken-vorstellungsgespraech","title":"Leas Glücks-Ritual","subtitle":"Rituale vor wichtigen Terminen, geübt mit kognitiver Entkopplung","character":"Lea","avatar":"🧦","context":"Deine Freundin Lea hat morgen ein Vorstellungsgespräch für ihren Traumjob. Beim Packen holt sie ihre rot-gelb geringelten Socken aus der Schublade. Sie ist überzeugt: Ohne diese Socken wird das Gespräch nichts, denn bei ihrer letzten Zusage hatte sie sie auch an.","goal":"Nimm Lea die Nervosität, ohne ihr das Ritual madig zu machen, und hilf ihr mit Neugier statt Belehrung, das Muster hinter den Glückssocken selbst zu erkennen.","bereich":"Ich selbst","laenge":"kurz","ton":"heiter","bestehenAb":4,"lektion":"Ein Ritual wie die Glückssocken kann sich beruhigend anfühlen, aber es verursacht den Erfolg nicht: Aberglaube entsteht aus zufälligen Treffern, die wir als Beweis zählen, und aus der Kontrollillusion. Wer die Idee vom Selbst trennt, kann sie neugierig prüfen, und ein Misserfolg wird nicht zur Selbstanklage.","toolRef":"H.1.1","faktenRef":"F.1.2","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Lea","speech":"„Ich hab die Socken! Die rot-gelben! Ohne die geh ich da morgen nicht rein, bei meiner letzten Zusage hatte ich genau die an. Wenn ich die vergesse, ist alles vorbei, das weiß ich einfach!“","options":[{"text":"„Lea, das ist Aberglaube, mehr nicht. Socken haben noch nie ein Gespräch gewonnen. Du bist doch eine kluge Frau, lass den Quatsch.“","style":"frontal","reaction":"„Wow, danke. Ich bin also nicht nur nervös, sondern auch noch albern. Super Aufbau, wirklich.“ *knallt die Schublade zu*","feedback":"Frontalangriff: Du sezierst die Person statt die Behauptung. Lea fühlt sich bloßgestellt, hält am Ritual fest, und ihre Nervosität steigt.","score":-2,"nextStepId":"step-fail"},{"text":"„Die Socken sind dir wichtig, oder? Wie kam das eigentlich mit ihnen?“","style":"sokratisch","reaction":"„*lacht kurz auf* Okay, das war so: Mein Vorstellungsgespräch letztes Jahr, die hatte ich eigentlich nur an, weil alle anderen Socken in der Wäsche waren. Und dann kam die Zusage...“","feedback":"Stark: Du nimmst die Aufregung ernst und fragst neugierig nach der Entstehung, statt zu widersprechen. Lea kann ihre Socken-Idee betrachten wie eine Hypothese, nicht wie einen Teil von sich, und erzählt selbst, dass der erste ‚Treffer‘ Zufall war.","score":3,"nextStepId":"step-2"},{"text":"„Na klar, dann pack die Socken auf jeden Fall ein! Besser ist das. Ich leg dir morgen früh auch noch einen Ersatz-Glücksbringer in die Tasche.“","style":"affektiv","reaction":"„Oh ja! Und vielleicht trag ich auch noch das Armband von damals! Jetzt hab ich wenigstens zwei Sicherheiten.“","feedback":"Du bestätigst das Ritual und baust die Kontrollillusion weiter aus. Lea koppelt ihre Sicherheit jetzt an noch mehr Dinge, die verloren gehen können.","score":-1,"nextStepId":"step-2-weak"}]},"step-2":{"id":"step-2","speaker":"Lea","speech":"„Aber trotzdem: Bei den anderen zwei Gesprächen hatte ich andere Socken an und es lief nicht so gut. Das kann doch kein Zufall sein, oder?“","options":[{"text":"„Das ist klassisches Post hoc ergo propter hoc, Lea. Du verwechselst Korrelation mit Kausalität. Lies mal im Netz nach, da steht alles dazu.“","style":"frontal","reaction":"„Ich wollte kein Seminar, ich wollte einen Rat. Du klingst wie meine Statistik-Dozentin.“","feedback":"Das Fachwort ist richtig, aber du lieferst die Erklärung als Belehrung. Ohne Neugier von Lea wirkt sie wie ein Urteil über ihr Denken.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Interessant, drei Gespräche, drei Socken-Varianten. Was glaubst du: Wenn du die Socken morgen trägst und es läuft schlecht, woran würdest du dann zuerst denken?“","style":"sokratisch","reaction":"„Hm... ehrlich? Wahrscheinlich, dass ich irgendwas falsch gemacht habe. Dass ich zu wenig geübt hab oder zu nervös war. Die Socken würde ich wohl nicht in Frage stellen...“","feedback":"Treffer: Mit einer offenen Frage lässt du Lea die asymmetrische Erklärung selbst entdecken: Erfolg zählt für die Socken, Misserfolg geht auf ihr Konto. Erst wenn ein Misserfolg nicht ihren Selbstwert trifft, kann sie das Ritual prüfen.","score":3,"nextStepId":"step-3-success"},{"text":"„Es gibt keinen Beweis, dass Socken irgendwas bewirken. Also lass sie weg und zieh dir was Bequemes an, dann klappt es genauso gut.“","style":"frontal","reaction":"„Genauso gut? Das weißt du doch gar nicht. Wenn ich sie weglasse und es geht schief, bin ich schuld. Das riskier ich nicht!“","feedback":"Du forderst den Verzicht auf ein Ritual, das sich für Lea beruhigend anfühlt, ohne die Angst selbst anzusprechen. Das erzeugt Abwehr statt Einsicht.","score":-1,"nextStepId":"step-fail"}]},"step-2-weak":{"id":"step-2-weak","speaker":"Lea","speech":"„Wobei... wenn ich zwei Glücksbringer brauche, ist das jetzt schon ein bisschen viel, oder? Mein Kopf dreht sich gerade im Kreis. Was soll ich denn machen, wenn ich einen davon verliere?“","options":[{"text":"„Gute Frage. Vielleicht hängt dein Erfolg morgen gar nicht an den Dingen, sondern an dir: an deiner Vorbereitung und dem, was du kannst. Wollen wir mal durchgehen, was du morgen sagen willst?“","style":"deeskalierend","reaction":"„*atmet auf* Ja. Das wäre mir eigentlich lieber, als die Socken nochmal zu zählen. Okay, fang an, ich erzähl dir meinen Pitch.“","feedback":"Gute Korrektur: Du lenkst von den Gegenständen auf das, was Lea tatsächlich beeinflussen kann (Kontrollillusion vs. echte Vorbereitung).","score":2}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Lea","speech":"„Ich weiß auch nicht, ich bin einfach nur nervös. Die Socken helfen mir irgendwie...“","options":[{"text":"„Das verstehe ich. Wenn dich das ruhiger macht, zieh sie ruhig an. Und lass uns zusammen noch deine Antworten üben, damit du dich auch ohne Socken sicher fühlst.“","style":"deeskalierend","reaction":"„Ja, das klingt gut. Ein bisschen Üben schadet nie. Danke, dass du das nicht noch größer machst.“","feedback":"Solide: Das Ritual darf bleiben, solange es nur beruhigt und keine kostspieligen Entscheidungen lenkt (kein Kipppunkt). Du ergänzt echte Vorbereitung, aber die Frage nach dem Muster bleibt offen.","score":2}]},"step-3-success":{"id":"step-3-success","speaker":"Lea","speech":"„Wenn ich das so sage, klingt das ja fast komisch: Klappt es, waren's die Socken. Klappt es nicht, war ich's. Dabei haben die Socken wohl nicht mal beim ersten Mal was gemacht. Ich zieh sie morgen trotzdem an, aber die Zusage hängt nicht an ihnen, oder?“","options":[{"text":"„Genau. Die Socken sind dein Maskottchen, aber die Antworten gibst du. Was zählt, hast du schon in der Tasche: deine Vorbereitung und dein Können. Sollen wir noch einmal die erste Frage durchgehen?“","style":"humorvoll","reaction":"„Gern! Und falls es klappt, geb ich nur halb den Socken die Ehre.“ *grinst*","feedback":"Rundum gelungen: Lea trennt ihr Selbstvertrauen von dem Ritual. Das Ritual bleibt als harmlose Krücke, die Verantwortung und Kompetenz liegen wieder bei ihr.","score":3}]},"step-fail":{"id":"step-fail","speaker":"Lea","speech":"„Lass uns das Thema lassen. Ich zieh die Socken an und gut ist.“ *packt schweigend weiter*","options":[{"text":"Ende: Lea fühlt sich beurteilt statt unterstützt und hält umso fester an ihrem Ritual fest. Das Gespräch ist vorbei, ohne dass sie ihre Nervosität losgeworden ist.","style":"ausstieg","reaction":"Beim nächsten Mal: zuerst die Angst ernst nehmen, dann neugierig nach dem Ritual fragen, statt es zu bewerten.","feedback":"Wer ein Ritual angreift, greift in Leas Gefühl von Kontrolle ein. Wer die Angst ernst nimmt und eine offene Frage stellt, lässt sie die Idee selbst prüfen, ohne sich angegriffen zu fühlen.","score":0}]}},"status":"entwurf","familie":"was-waere-ohne","fertigkeit":"F2","stufe":1,"kurz":"Ein Ritual kann beruhigen, verursacht den Erfolg aber nicht: Aberglaube entsteht, wenn zufällige Treffer als Beweis zählen und Misserfolge anders erklärt werden. Wer die Idee vom Selbst trennt, kann sie neugierig prüfen.","prueffrage":"Was würde nach einem schlechten Gespräch mit den Glückssocken als Ursache gelten, und was nach einem guten?","quellen":[{"typ":"url","kurz":"Skinner, B. F. (1948): ‚Superstition‘ in the pigeon. Journal of Experimental Psychology 38(2), 168–172 (Nachdruck: Classics in the History of Psychology, York University)","oeffentlich":true,"doi":"10.1037/h0055873","url":"https://psychclassics.yorku.ca/Skinner/Pigeon/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Calin-Jageman, R. J.; Caldwell, T. L. (2014): Replication of the Superstition and Performance Study by Damisch, Stoberock, and Mussweiler (2010). Social Psychology 45(3), 239–245","oeffentlich":true,"doi":"10.1027/1864-9335/a000190","abruf":"2026-10-12"},{"typ":"doi","kurz":"Lang, M.; Krátký, J.; Xygalatas, D. (2020): The role of ritual behaviour in anxiety reduction. Philosophical Transactions of the Royal Society B 375(1805), 20190431","oeffentlich":true,"doi":"10.1098/rstb.2019.0431","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"scen-opa-fruehwarnung-schlaganfall","title":"Opa Egon und die Nahrungsergänzung","subtitle":"Tablettenregal statt Arztbesuch, geübt mit der Empathie-Matrix","character":"Opa Egon","avatar":"💊","context":"Dein Opa Egon (74) hatte vor drei Wochen einen kurzen Schwindelanfall mit Sehstörung. Seitdem schwört er auf sein neues Regal voller Pflanzenpräparate und Kapseln. Den Termin beim Hausarzt und die Blutdrucktabletten hat er abgesagt, er sei jetzt „versorgt“. Du besuchst ihn am Sonntag, das Regal glänzt schon im Flur.","goal":"Nimm seine Sorge ernst, bleib im Gespräch und bring ihn mit mitfühlender Empathie und der Dosis-Frage dazu, den Arzttermin wieder zu wagen.","bereich":"Gesundheit","laenge":"lang","ton":"ernst","bestehenAb":9,"lektion":"Wer Angst um seinen Körper hat, greift nach dem, was ihm Kontrolle verspricht; ein Regal voller „Natur“ fühlt sich nach Handeln an. „Natürlich“ sagt aber weder etwas über Wirkung noch über Sicherheit: Die Dosis entscheidet, und auch pflanzliche Stoffe können schaden oder mit Medikamenten wechselwirken, wie etwa Johanniskraut. Ein plötzlicher Schwindel mit Sehstörung kann ein Warnzeichen für einen Schlaganfall sein und gehört deshalb rasch ärztlich abgeklärt. Mit mitfühlender Empathie – verstehen, kurz spiegeln, ruhig bleiben und helfen – bringst du Egon eher zum Arzt als mit jeder Belehrung.","toolRef":"H.1.6","faktenRef":"C.4.7","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Opa Egon","speech":"„Da schau her, mein Regal! Johanniskraut, Mariendistel, Knoblauchkapseln, das volle Programm. Das Zeug hält mich gesund. Zum Arzt muss ich nicht mehr, und die Blutdrucktabletten habe ich in die Schublade gelegt. Chemie brauche ich keine, ich nehme nur noch Natur!“","options":[{"text":"„Opa, das ist Quatsch. Natur hin oder her, ohne Blutdrucktabletten riskierst du einen Schlaganfall! Das Regal kannst du wegwerfen, geh endlich zum Arzt!“","style":"frontal","reaction":"„Wegwerfen?! Ich bin 74 und weiß selbst, was mir guttut! Du hörst dich an wie der Doktor, der mir nur Chemie aufschwatzen will!“","feedback":"Frontalangriff: Die Sorge ist berechtigt, aber Egon hört Entmündigung und Abwertung. Wer zuerst das Regal angreift, greift in seinen Ohren ihn an.","score":-2,"nextStepId":"step-fail"},{"text":"„Du wirkst richtig entschlossen, und ich merke, dass dich der Schwindel neulich ziemlich erschreckt hat. Es ist gut, dass du etwas für dich tun willst. Magst du mir erzählen, wie das bei dir losging?“","style":"deeskalierend","reaction":"„*setzt sich langsam* Ja, das war ein Schreck, das kannst du mir glauben. Plötzlich ging das linke Auge nicht mehr richtig und mir war schwindelig. Da dachte ich: Jetzt tue ich was.“","feedback":"Stark: Kognitive Empathie (verstehen, woher das Regal kommt) plus kurzes Spiegeln seiner Angst, ohne Zustimmung zum Mythos. Mitfühlende Empathie öffnet die Tür.","score":3,"nextStepId":"step-2"},{"text":"„Oh Mann, Opa, das klingt ja furchtbar! Hast du etwa schon einen Schlaganfall gehabt? Ich kriege richtig Angst um dich, und was ist, wenn du plötzlich umkippst, während ich nicht da bin?!“","style":"affektiv","reaction":"„Nun mach nicht so ein Theater! Jetzt hast du mich ganz nervös gemacht. Vielleicht sollte ich doch noch eine Kapsel mehr nehmen...“","feedback":"Affektiver Kollaps: Du übernimmst und verstärkst die Angst. Egon greift jetzt erst recht zur Kapsel, weil Beruhigung für ihn im Regal liegt.","score":-1,"nextStepId":"step-panic"}]},"step-2":{"id":"step-2","speaker":"Opa Egon","speech":"„Der Mann im Reformhaus hat gesagt: Johanniskraut stärkt die Nerven, Mariendistel entgiftet die Leber, Knoblauch hält die Gefäße frei. Alles pflanzlich, alles natürlich. Da kann gar nichts passieren, sonst dürften sie es ja nicht verkaufen.“","options":[{"text":"„Dass jemand etwas verkaufen darf, heißt nicht, dass es dir hilft, Opa. Und ‚natürlich‘ heißt auch nicht harmlos. Das ist eine alte Verkäuferlüge, und du bist darauf hereingefallen, so leicht geht das.“","style":"frontal","reaction":"„Verkäuferlüge! Der Mann war sehr freundlich und hat sich Zeit genommen, anders als mein Doktor. Du hältst mich für einen alten Trottel.“","feedback":"Der Kern stimmt, aber der Ton („hereingefallen“) beschämt Egon. Der freundliche Verkäufer hat ihm etwas gegeben, was er gebraucht hat: Zuwendung.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Einen Moment: Wenn ein Stoff wirklich wirkt, kann er doch auch Nebenwirkungen haben, oder? Wie Salz in der Suppe: ein bisschen schmeckt gut, zu viel verdirbt sie. Woran erkennst du, ob ein Kraut bei dir mehr hilft als schadet?“","style":"sokratisch","reaction":"„Hm... Salz, ja. Zu viel davon ist ungesund, das weiß ich. Woran ich es erkenne? ...Ich dachte, ich spüre es einfach, wenn es mir besser geht.“","feedback":"Meisterhaft: Mit der Salz-Analogie bringst du die Dosis-Wirkungs-Beziehung ins Spiel und stellst eine Detektivfrage im Sinne der Street Epistemology, statt einen Vortrag zu halten.","score":3,"nextStepId":"step-3"},{"text":"„Ach, so ein Regal ist doch eine nette Sache. Wenn es dir ein gutes Gefühl gibt, soll es dich nicht stören. Hauptsache, du fühlst dich wohl, Opa. Das Regal tut dir bestimmt nichts Böses.“","style":"ausstieg","reaction":"„Siehst du, genau! Endlich versteht mich mal einer. Dann bleibt das Regal, und der Termin beim Doktor bleibt auch abgesagt.“","feedback":"Du vermeidest den Streit, bestätigst aber stillschweigend die Absage von Vorsorge und Medikament. Harmonie auf Kosten der Gesundheit ist keine Mitfühlende Empathie.","score":-2,"nextStepId":"step-fail"}]},"step-3":{"id":"step-3","speaker":"Opa Egon","speech":"„Kann schon sein, dass man mal zu viel erwischt. Aber bei Pflanzen? Meine Oma hat Kräutertee getrunken und wurde 90. Und die Tabletten vom Doktor, die sind doch bloß Chemie, die macht mich auf Dauer erst richtig krank.“","options":[{"text":"„Deine Oma hatte vermutlich Glück, Opa, und Tee ist etwas anderes als Kapseln. Aber ein Blutdruckmittel ist ebenfalls ein Stoff mit genau abgestimmter Dosis: Zu wenig hilft nicht, zu viel schadet. Der Arzt sucht dafür das richtige Fenster, bei Kapseln aus dem Regal kennt keiner deine Menge.“","style":"sokratisch","reaction":"„Ein Fenster... Hm. Das klingt, als würde der Doktor tatsächlich was Gutes im Sinn haben. Aber wer sagt mir denn, dass die Tabletten besser sind als meine Kräuter?“","feedback":"Gut: Du entkoppelst „Chemie = Gift“, indem du auf das therapeutische Fenster verweist, und bleibst bei Egons Oma respektvoll. Die Frage nach dem Beleg ist die Brücke zum nächsten Schritt.","score":2,"nextStepId":"step-4"},{"text":"„Hast du denn mal geschaut, ob die Kapseln bei dir etwas bewirken? Und was ist, wenn sie sich mit etwas anderem beißen, das du nimmst? Wie wäre es, wenn wir das zusammen herausfinden?“","style":"sokratisch","reaction":"„Zusammen herausfinden... na gut, du hast ja nicht unrecht. Ich habe nämlich seit dem Johanniskraut manchmal einen komischen Magen. Wie sollen wir das denn rauskriegen?“","feedback":"Sehr stark: Du lädst Egon zur gemeinsamen Prüfung ein, statt ihm das Ergebnis zu diktieren, und schlägst eine Brücke zur Wechselwirkungsfrage. Neugier statt Kampf.","score":3,"nextStepId":"step-4"},{"text":"„Opa, das ist doch Unsinn mit dem ‚Chemie macht krank‘! Dein Körper besteht selbst aus Chemie, und alles, was du isst, ist Chemie. Hör auf, so einen Mist zu reden.“","style":"sarkastisch","reaction":"„Mist?! Na schönen Dank auch! Ich bin alt, aber nicht dumm. Dann geh doch, wenn ich dir so auf den Wecker falle.“","feedback":"Inhaltlich richtig, aber herablassend verpackt. Wer den Menschen mit der Behauptung gleichsetzt, verliert beides: Seziert wird die Behauptung, nicht der Mensch.","score":-2,"nextStepId":"step-fail"}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Opa Egon","speech":"„*verschränkt die Arme* Der Verkäufer war wenigstens freundlich. Der Doktor hat nur auf den Bildschirm gestarrt und mir ein Rezept hingeschoben. Ich fühle mich da nicht ernst genommen.“","options":[{"text":"„Das tut mir leid, Opa, und das ist ein berechtigter Punkt: Man will gehört werden. Wäre es okay, wenn ich dich zum nächsten Termin begleite und wir gemeinsam alle Fragen stellen, die dich beschäftigen?“","style":"deeskalierend","reaction":"„*wird weicher* Du würdest mitkommen? ...Das wäre mir tatsächlich lieb. Dann trau ich mich vielleicht auch zu fragen, was ich fragen will.“","feedback":"Gut gerettet: Du erkennst sein Bedürfnis (gesehen werden) an und bietest Begleitung statt Belehrung an. Das ist Mitfühlende Empathie: fürsorgliches Handeln ohne Angstübernahme.","score":2,"nextStepId":"step-5"},{"text":"„Dann ist dein Doktor eben ein schlechter Doktor. Such dir einen anderen und lass das Regal stehen, wenn es dir hilft, Hauptsache du hörst auf zu jammern.“","style":"sarkastisch","reaction":"„Jammern! Na, jetzt ist es aber genug. Ich brauche deinen Rat nicht, ich komme alleine klar.“","feedback":"Zynisch und abwertend: Egons Kränkung wird nicht aufgegriffen, sondern abgetan. Damit verbaust du dir den Zugang für das nächste Gespräch.","score":-2,"nextStepId":"step-fail"},{"text":"„Ja, manche Ärzte haben wenig Zeit, das stimmt. Aber das heißt noch nicht, dass die Tabletten schlecht sind. Wir können das Regal erst einmal lassen und ich frage dich nächste Woche, wie es dir geht.“","style":"ausstieg","reaction":"„Gut, dann sprechen wir nächste Woche. Das Regal bleibt aber, wie es ist.“","feedback":"Du schützt die Beziehung, aber nach Schwindel mit Sehstörung und abgesetzten Tabletten ist eine Woche Abwarten riskant. Fürsorge heißt hier, zeitnah zu handeln.","score":0,"nextStepId":"step-5"}]},"step-4":{"id":"step-4","speaker":"Opa Egon","speech":"„Ich gebe zu, dass ich mich nicht auskenne. Aber ich habe Angst vor Nebenwirkungen bei den Tabletten, und die Kräuter fühlen sich sanfter an. Warum sollte ich denn dem Doktor mehr trauen als dem Verkäufer?“","options":[{"text":"„Gute Frage. Der Unterschied liegt nicht darin, wie sanft sich etwas anfühlt, sondern in Dosis und Wirkung. Auch ‚natürlich‘ heißt nicht unschädlich: Johanniskraut kann zum Beispiel die Wirkung anderer Medikamente verändern. Das Zusammenspiel prüft am besten der Arzt oder Apotheker.“","style":"sokratisch","reaction":"„Johanniskraut verändert andere Medikamente? Das hat mir keiner gesagt. Dann ist das Natürliche also nicht automatisch ungefährlich... Das gibt mir zu denken.“","feedback":"Treffsicher: Du trennst Herkunft von Wirkung und nennst mit der Johanniskraut-Wechselwirkung ein konkretes Beispiel, ohne Egon zu beschämen.","score":3,"nextStepId":"step-5"},{"text":"„Weil Ärzte studiert haben und Verkäufer bloß Provision wollen. Das ist ein Unterschied wie Tag und Nacht, Opa. Da brauchst du gar nicht lange zu überlegen, wem du glaubst, denn Verkäufer verdienen an dir und Ärzte wollen dir nur helfen.“","style":"frontal","reaction":"„Alle sind gleich, wenn es ums Geld geht. Der Doktor verdient doch auch an mir. Das überzeugt mich nicht.“","feedback":"Der Hinweis auf Provision wirkt wie ein Pauschalvorwurf und liefert keinen prüfbaren Grund. Vertrauen lässt sich nicht verordnen, Belege lassen sich zeigen.","score":-1,"nextStepId":"step-5"},{"text":"„Ich verstehe, dass Nebenwirkungen Angst machen. Wie wäre es, wenn wir die Packungsbeilage deiner Blutdrucktabletten zusammen durchgehen und ich schreibe dir alle Fragen auf, die du dem Arzt stellen möchtest, damit du beim nächsten Termin nichts vergisst?“","style":"deeskalierend","reaction":"„Fragen aufschreiben... Das könnte ich mir vorstellen. Ich vergesse sonst immer die Hälfte, wenn ich im Sprechzimmer sitze.“","feedback":"Gute Brücke: Du nimmst die Angst vor Nebenwirkungen ernst und machst daraus einen konkreten, machbaren Schritt. Mitfühlende Empathie zeigt sich im Handeln, nicht im Mitzittern.","score":2,"nextStepId":"step-5"}]},"step-5":{"id":"step-5","speaker":"Opa Egon","speech":"„*seufzt* Na schön. Ich sehe schon, du lässt nicht locker. Aber ich sage dir ehrlich: Ich schäme mich ein bisschen, dass ich die Tabletten einfach in die Schublade gelegt habe. Was soll ich denn jetzt machen?“","options":[{"text":"„Du musst dich nicht schämen, Opa, du hast aus Sorge gehandelt. Ich rufe morgen früh in der Praxis an, und wir machen den Termin neu aus. Das Regal bringst du mit, dann schaut der Arzt oder Apotheker gleich drauf.“","style":"deeskalierend","reaction":"„*lächelt erleichtert* Das Regal mitbringen... Das ist eine gute Idee. Dann muss ich nichts verstecken. Ja, ruf morgen mit mir an.“","feedback":"Ideal: Du nimmst die Scham, bietest konkrete Unterstützung an und lässt Egon sein Gesicht wahren. Das Regal wird zum Prüfobjekt statt zum Streitpunkt.","score":3},{"text":"„Dann nimm die Tabletten eben wieder, Opa, sofort heute Abend. Und die Kapseln wirfst du am besten alle weg, dann ist die Sache erledigt. Ein Arzt muss da nicht mehr rein, das regelst du allein.“","style":"frontal","reaction":"„Alle weg? Das habe ich teures Geld für ausgegeben! Ich überlege es mir, aber zwing mich zu nichts.“","feedback":"Dein Anliegen ist verständlich, aber Wiederbeginn und Absetzen gehören in ärztliche Hand. Dazu kostet der Befehlston Vertrauen: Ohne das Gefühl, selbst zu entscheiden, hält kein Entschluss.","score":0},{"text":"„Ach, das hat doch Zeit. Wir sehen mal, wie es dir in den nächsten Wochen geht. Wenn der Schwindel wiederkommt, kannst du immer noch hingehen, eilig ist das nicht, das kann warten.“","style":"ausstieg","reaction":"„Gut, dann warte ich ab. Mir geht es ja gerade ganz ordentlich.“","feedback":"Zu lasch: Nach einem Schwindelanfall mit Sehstörung ist Abwarten riskant. Mitfühlende Empathie heißt, Fürsorge in Handeln zu verwandeln, nicht zu vertagen.","score":-2}]},"step-fail":{"id":"step-fail","speaker":"Opa Egon","speech":"„Das reicht jetzt. Ich weiß, was ich tue. Das Regal bleibt, die Tabletten bleiben in der Schublade, und der Arzt kann mir gestohlen bleiben.“ *dreht sich weg und geht in die Küche*","options":[{"text":"Ende: Egon fühlt sich nicht gehört oder wurde bestätigt, statt ernst genommen zu werden. Das Regal bleibt, die Tabletten bleiben in der Schublade.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst die Angst hinter dem Regal ernst nehmen, dann erst über Wirkung und Dosis sprechen.","feedback":"Rechthaben und Helfen sind zweierlei. Die Empathie-Matrix ordnet die Reihenfolge: verstehen, kurz spiegeln, dann ruhig helfen.","score":0}]},"step-panic":{"id":"step-panic","speaker":"Opa Egon","speech":"„Vielleicht sollte ich zur Sicherheit doppelt so viele Kapseln nehmen, damit mir nichts mehr passiert! Hilft viel, dann hilft es auch viel, oder?“","options":[{"text":"Ende: Zwei Menschen in Aufregung, und die Kapselmenge steigt. Wer mitzittert, kann nicht stützen.","style":"ausstieg","reaction":"Hilft viel, hilft viel? Gerade das Gegenteil: Die Dosis macht die Wirkung, und mehr ist nicht automatisch besser.","feedback":"Mitfühlende Empathie heißt, die Angst zu verstehen und selbst ruhig zu bleiben. Zur Dosis: Auch „natürliche“ Stoffe können in hohen Mengen schaden.","score":0}]}},"status":"entwurf","familie":"dosis-entscheidet","fertigkeit":"F4","stufe":4,"kurz":"„Natürlich“ sagt nichts über Wirkung oder Sicherheit: Die Dosis entscheidet, und auch Pflanzenstoffe können schaden oder mit Medikamenten wechselwirken. Wer zuerst die Angst hinter dem Handeln ernst nimmt, bringt einen Menschen eher zum Arzt als mit Belehrung.","prueffrage":"Woran ließe sich erkennen, ob eine Kapsel aus dem Regal hilft, und wer prüft, wie sie mit anderen Mitteln zusammenwirkt?","quellen":[{"typ":"url","kurz":"National Center for Complementary and Integrative Health (NIH): St. John's Wort: Usefulness and Safety (Stand Mai 2025)","oeffentlich":true,"url":"https://www.nccih.nih.gov/health/st-johns-wort","abruf":"2026-10-12"},{"typ":"url","kurz":"European Medicines Agency, HMPC (2022): European Union herbal monograph on Hypericum perforatum L., herba. EMA/HMPC/7695/2021, Final – Revision 1, Abschn. 4.5","oeffentlich":true,"url":"https://www.ema.europa.eu/en/documents/herbal-monograph/final-european-union-herbal-monograph-hypericum-perforatum-l-herba-revision-1_en.pdf","seite":"9–10","abruf":"2026-10-12"},{"typ":"doi","kurz":"Klimecki, O. M.; Leiberg, S.; Ricard, M.; Singer, T. (2014): Differential pattern of functional brain plasticity after compassion and empathy training. Social Cognitive and Affective Neuroscience 9(6), 873–879","oeffentlich":true,"doi":"10.1093/scan/nst060","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"scen-lehrer-lerngruppe-ausreden","title":"Herr Winters Notenschnitt-Mythos","subtitle":"Nur Willenskraft zählt, geübt mit der Ausstiegs-Strategie","character":"Herr Winter","avatar":"📚","context":"Du sitzt im Elternabend neben Herrn Winter, einem engagierten Lehrer. Gerade ging es um die Noten in der Klasse, und er hat eine klare Meinung: Wer gute Noten will, brauche nur genug Willenskraft; Begabung und alles andere seien Ausreden. Du hörst, wie er sich dabei immer weiter in Rage redet.","goal":"Zeige Herrn Winter, dass Noten selten nur eine einzige Ursache haben, indem du ihn selbst nach weiteren Faktoren suchen lässt.","bereich":"Schule","laenge":"kurz","ton":"ernst","bestehenAb":4,"lektion":"Gute oder schlechte Noten entstehen wie die meisten komplexen Ergebnisse aus einem Zusammenspiel vieler Faktoren, und die Antwort „Es liegt nur an der Willenskraft“ ist ein klassischer monokausaler Fehlschluss. Die Aktivierungsfrage („Welche weiteren Faktoren könnten beigetragen haben?“) öffnet das Denken. Die Ausstiegs-Strategie ist dagegen die Notbremse für Gespräche, in denen das Gegenüber wiederholt unehrlich spielt, etwa mit Gaslighting oder Ad-hominem-Angriffen. Bei einem redlich argumentierenden Gesprächspartner wie Herrn Winter, der selbst Faktoren nennt, ist ein früher Ausstieg voreilig.","toolRef":"H.2.4","faktenRef":"B.24","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Herr Winter","speech":"„Ich sage es, wie es ist: Wer gute Noten will, muss einfach nur genug wollen. Willenskraft, mehr braucht es nicht! Begabung, Elternhaus, Schlaf – alles nur Ausreden von Leuten, die sich nicht anstrengen wollen.“","options":[{"text":"„Das ist Quatsch, Herr Winter. Wer so redet, hat keine Ahnung von Kindern und macht es sich zu leicht. Bei so einer Einstellung wundert mich gar nichts.“","style":"frontal","reaction":"„*verschränkt die Arme* Bitte? Ich unterrichte seit Jahrzehnten! Wenn Sie meinen Ansatz persönlich angreifen, brauchen wir gar nicht weiterzureden.“","feedback":"Frontalangriff! Du sezierst nicht die Behauptung, sondern den Menschen. Herr Winter geht in Verteidigung, und das Gespräch wird zum Machtkampf statt zum Austausch.","score":-2,"nextStepId":"step-fail"},{"text":"„Das ist eine klare und einfache Erklärung, Herr Winter. Welche weiteren Faktoren könnten Ihrer Meinung nach noch dazu beitragen, ob jemand gute Noten schreibt, vielleicht auch weniger offensichtliche?“","style":"sokratisch","reaction":"„Hm... weitere Faktoren? Na ja, ein ruhiger Arbeitsplatz zu Hause vielleicht. Und manche Kinder sind natürlich schneller im Kopf. Aber das ist doch Beiwerk, oder nicht?“","feedback":"Sehr gut! Die Aktivierungsfrage aus dem Anti-Denkmuster lädt ein, über weitere Ursachen nachzudenken, statt die Willenskraft-These frontal zu bekämpfen. Herr Winter nennt bereits selbst zwei Faktoren.","score":3,"nextStepId":"step-2"},{"text":"„Da haben Sie sicher recht, Willenskraft ist bestimmt der wichtigste Punkt. Ich will hier keinen Streit anfangen, sagen wir einfach, dass wir uns einig sind.“","style":"deeskalierend","reaction":"„Na also, endlich mal jemand mit Verstand! Dann sagen Sie das bitte auch den anderen Eltern.“","feedback":"Du vermeidest den Streit, bestätigst aber den monokausalen Fehlschluss. Harmonie ohne Substanz: Die Vereinfachung bleibt unangetastet und wird sogar noch bestärkt.","score":-1,"nextStepId":"step-fail-agree"}]},"step-2":{"id":"step-2","speaker":"Herr Winter","speech":"„Ruhiger Arbeitsplatz, schneller im Kopf... gut, das mag eine kleine Rolle spielen. Aber am Ende entscheidet doch der Wille! Ein Kind, das wirklich will, schafft das trotzdem. Alles andere ist Jammerei.“","options":[{"text":"„Als Gedankenexperiment: Wenn bei einem Kind Arbeitsplatz, Schlaf und gute Erklärungen stimmen und beim anderen nicht, ist der Wille dann nicht nur ein Faktor unter mehreren? Wie würden Sie das prüfen?“","style":"sokratisch","reaction":"„*überlegt* Vielleicht... nur ein Faktor unter mehreren. Hm. Ich habe Kinder erlebt, die trotz schwieriger Verhältnisse brillant waren. Aber ja, ich kenne auch Fälle, wo am Ende vieles zusammenkam. Das lässt mich nachdenken.“","feedback":"Meisterhaft! Du lässt Herrn Winter die Multikausalität selbst durchdenken, statt sie zu predigen. Mit einer offenen Prüffrage statt einer Belehrung gerät seine Gewissheit ins Wanken, ohne dass er sein Gesicht verliert.","score":3,"nextStepId":"step-3-success"},{"text":"„Das Gespräch dreht sich im Kreis, Herr Winter. Wir kommen hier nicht weiter. Ich schlage vor, wir belassen es dabei, und ich wünsche Ihnen noch einen schönen Abend.“","style":"ausstieg","reaction":"„*zuckt mit den Schultern* Na gut. Wie Sie meinen. Aber Sie werden schon sehen, dass ich recht habe.“","feedback":"Ein ruhiger, höflicher Ausstieg, aber voreilig: Die Ausstiegs-Strategie ist die Notbremse bei wiederholten unehrlichen Taktiken und gescheiterten Versuchen, zur Sache zurückzukehren. Herr Winter argumentiert redlich und hat selbst Faktoren genannt. Du schützt deine Energie, verschenkst aber die Chance.","score":1,"nextStepId":"step-3-struggle"},{"text":"„Dann sind Kinder, die schlechte Noten schreiben, eben einfach faul, oder? Sagen Sie das ruhig auch den Eltern ins Gesicht, dann sind wir hier fertig und können gehen.“","style":"sarkastisch","reaction":"„*wird laut* Jetzt legen Sie mir Worte in den Mund! Das habe ich nie gesagt, aber wenn Sie hier nur auf Streit aus sind, dann bitte!“","feedback":"Sarkasmus verzerrt Herrn Winters Position zu einer Karikatur und lenkt vom Thema ab. Er fühlt sich angegriffen, und die Chance auf ein echtes Gespräch ist vorerst verspielt.","score":-2,"nextStepId":"step-fail"}]},"step-3-success":{"id":"step-3-success","speaker":"Herr Winter","speech":"„Wissen Sie, vielleicht habe ich es mir bisher zu einfach gemacht. Wenn ich nur auf den Willen schaue, übersehe ich womöglich, wo ich einem Kind wirklich helfen könnte. Wie gehe ich da am besten vor?“","options":[{"text":"„Vielleicht fangen Sie einfach damit an, bei jedem Kind erst zu fragen, welche Faktoren gerade zusammenkommen: Schlaf, Arbeitsplatz, Erklärungen, Stress. Dann sehen Sie, wo ein Hebel liegt, statt immer nur auf den Willen zu schauen.“","style":"sokratisch","reaction":"„Das ist ein guter Gedanke. Eine Liste statt eines Urteils. Das probiere ich gleich diese Woche aus.“","feedback":"Mission gelungen! Du hast die Multikausalität als praktisches Werkzeug angeboten, statt Herrn Winter zu belehren. So wird aus dem monokausalen Urteil eine Suche nach mehreren Stellschrauben.","score":3}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Herr Winter","speech":"„Na gut, dann eben nicht. Aber ich bleibe dabei: Wer will, der kann. Schönen Abend noch.“","options":[{"text":"„Danke, Ihnen auch. Und falls Sie mal Lust haben, über die einzelnen Faktoren zu sprechen, bin ich gern dabei. Gute Nacht.“","style":"deeskalierend","reaction":"„*nickt knapp* Mal sehen. Gute Nacht.“","feedback":"Ein sauberer, freundlicher Abgang. Die Tür bleibt offen, der Kontakt unbeschädigt. Der Ausstieg kam hier nur etwas früh, die Sachfrage bleibt offen.","score":1}]},"step-fail-agree":{"id":"step-fail-agree","speaker":"Herr Winter","speech":"„Schön, dass wir uns einig sind. Ich sag's ja immer: Wer will, der kann.“ *nickt zufrieden und wendet sich dem nächsten Gespräch zu*","options":[{"text":"Ende: Das Gespräch endet friedlich, aber der Mythos ist bestätigt. Die vielen Faktoren hinter Noten kamen nicht zur Sprache.","style":"deeskalierend","reaction":"Beim nächsten Mal zuerst fragen, welche weiteren Faktoren eine Rolle spielen, statt die Vereinfachung um des Friedens willen zu bestätigen.","feedback":"Der monokausale Fehlschluss lässt sich am besten mit der Frage nach weiteren Ursachen auflösen. Zustimmung um des Friedens willen festigt ihn dagegen.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Herr Winter","speech":"„Ich sehe schon, so kommen wir nicht weiter. Dann bleibe ich eben bei meiner Meinung. Schönen Abend noch.“ *wendet sich ab und geht*","options":[{"text":"Ende: Das Gespräch ist im Streit beendet, ohne dass sich etwas bewegt hat. Statt die vielen Faktoren hinter Noten ins Spiel zu bringen, ging es nur noch um Angriff und Verteidigung.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst fragen, welche weiteren Faktoren eine Rolle spielen, statt die Person zu bewerten oder ihre Position zu karikieren.","feedback":"Der monokausale Fehlschluss lässt sich am besten mit der Frage nach weiteren Ursachen auflösen. Angriff oder Sarkasmus bringen die Person dagegen in die Verteidigung und verschließen das Gespräch.","score":0}]}},"status":"entwurf","familie":"monokausal-erkennen","fertigkeit":"F2","stufe":1,"kurz":"Noten entstehen wie die meisten komplexen Ergebnisse aus vielen Faktoren; „Es liegt nur am Willen“ greift zu kurz. Die Frage nach weiteren Faktoren öffnet das Denken, und wer redlich mitdenkt, verdient Geduld statt eines frühen Gesprächsabbruchs.","prueffrage":"Welche Faktoren außer dem Willen unterscheiden sich zwischen zwei Kindern mit sehr verschiedenen Noten?","quellen":[{"typ":"doi","kurz":"Krapohl, E. u. a. (2014): The high heritability of educational achievement reflects many genetically influenced traits, not just intelligence. PNAS 111(42), 15273–15278","oeffentlich":true,"doi":"10.1073/pnas.1408777111","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"scen-onkel-masernparty","title":"Onkel Horsts Masernparty","subtitle":"Natürliche Infektion vs. Schutz, geübt mit intellektueller Barmherzigkeit","character":"Horst, Onkel","avatar":"👨‍🦳","context":"Beim Familienkaffee erzählt dein Onkel Horst, dass bei einer Bekannten ein Kind an Masern erkrankt ist. Er will die Kinder der Familie zu ihr bringen: Kinderkrankheiten müsse man richtig durchmachen, das stärke das Immunsystem mehr als jede Impfung. Du weißt, dass Horst seine Nichten und Neffen liebt und ihnen nur das Beste wünscht.","goal":"Nimm Horsts Sorge um die Kinder ernst, statt ihn als unvernünftig abzustempeln, und führe das Gespräch mit klaren Fragen zu der Unterscheidung zwischen einer Impfung als gezieltem Training und einer echten Infektion.","bereich":"Familie","laenge":"mittel","ton":"ernst","bestehenAb":6,"lektion":"Wer Horst als Dummkopf behandelt, verliert ihn; wer seine Sorge um die Kinder anerkennt, kann mit ihm über die Sache reden. Eine Impfung ist ein gezieltes Trainingslager für die adaptive Immunantwort: Das Immunsystem lernt den Erreger kennen, ohne dass die gefährliche Erkrankung nötig wäre. Eine echte Maserninfektion kann dagegen einen Teil der schon vorhandenen Antikörper gegen andere Erreger auslöschen und so anfälliger für andere Infektionen machen; in einer Studie war dieser Effekt bei gegen Masern geimpften Säuglingen nicht zu sehen. Intellektuelle Barmherzigkeit heißt, die Behauptung zu prüfen und den Menschen dabei als fürsorglich zu behandeln.","toolRef":"H.1.3","faktenRef":"C.4.3","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Onkel Horst","speech":"„Du, bei Annegret hat die Kleine gerade Masern. Da fahren wir am Wochenende mit den Kindern hin, die sollen das ruhig mal durchmachen. Das haben wir früher auch alle gehabt, und danach ist das Immunsystem richtig fit. Eine Impfung ersetzt das nie!“","options":[{"text":"„Onkel Horst, das ist verantwortungslos! Wer Kinder absichtlich anstecken will, hat nicht alle Tassen im Schrank. Das ist gefährlicher Unsinn, und ich mache das nicht mit!“","style":"frontal","reaction":"„Verantwortungslos?! Ich habe meine eigenen Kinder großgezogen, ich brauche mir von dir nichts sagen zu lassen! Du hast doch keine Ahnung!“ *schiebt die Kaffeetasse weg*","feedback":"Das ist ein bekanntes Muster: Beleidigung statt Argument. Horst fühlt sich angegriffen und verteidigt jetzt sein Gesicht, nicht mehr seine Überzeugung.","score":-2,"nextStepId":"step-fail"},{"text":"„Das klingt, als läge dir viel an der Gesundheit der Kinder. Erzähl mal: Was stellst du dir vor, was bei so einer Ansteckung im Körper passiert und warum das besser schützen soll?“","style":"sokratisch","reaction":"„Na, der Körper kämpft die Krankheit selbst durch und merkt sich das. Das ist wie Muskeltraining: Was einen nicht umbringt, macht einen stärker!“","feedback":"Gut: Du erkennst die fürsorgliche Absicht an und lässt Horst sein Bild selbst ausformulieren. So kommt die Frage in Gang, ohne dass er sich vorgeführt fühlt.","score":3,"nextStepId":"step-2"},{"text":"„Hmm, wenn du meinst. Ich halte mich da lieber raus, ist ja nicht mein Kind. Aber sag Bescheid, was dabei rauskommt, ich bin gespannt.“","style":"ausstieg","reaction":"„Siehst du, so locker sollte man das sehen. Die Eltern machen sich heute viel zu viele Gedanken.“","feedback":"Der Rückzug wirkt wie Zustimmung. Aus Sorge um Streit lässt du Horst allein mit seiner Idee und stärkst sie damit unbeabsichtigt.","score":-1,"nextStepId":"step-fail"}]},"step-2":{"id":"step-2","speaker":"Onkel Horst","speech":"„Genau, wie beim Training! Der Körper lernt nur richtig, wenn er die echte Krankheit erlebt. So ein bisschen Impfzeug aus der Spritze kann das doch gar nicht, das ist ja nur ein Piks. Und ich will einfach, dass die Kinder wirklich geschützt sind.“","options":[{"text":"„Du willst, dass sie wirklich geschützt sind, und das will ich auch. Die Frage ist, wie das Training funktioniert: Muss der Körper den gefährlichen Erreger in voller Stärke durchleben, oder reicht ihm eine abgeschwächte Form davon?“","style":"sokratisch","reaction":"„Eine abgeschwächte Form? ...Hm. Du meinst, der Körper lernt auch von einem Virus, das so geschwächt ist, dass es kaum noch krank macht? Das wäre mir neu.“","feedback":"Stark: Du betonst das gemeinsame Ziel und gibst einen Denkanstoß: Eine Impfung gibt dem Immunsystem etwas zum Lernen, ohne dass die gefährliche Erkrankung nötig ist. Bei Masern ist das ein abgeschwächtes Lebendvirus, bei anderen Impfungen etwa ein abgetötetes Erreger oder nur ein einzelnes Protein.","score":3,"nextStepId":"step-3"},{"text":"„Ach Horst, ‚nur ein Piks‘! Die Immunologie ist da seit Jahrzehnten weiter als dein Bauchgefühl. Lies mal ein Buch statt Facebook-Gruppen, das hilft dir mehr als jede Meinung.“","style":"sarkastisch","reaction":"„Ach, jetzt bin ich auch noch blöd und lese nur Facebook! Mit dir kann man über so was nicht reden!“","feedback":"Sarkasmus macht die Person zur Zielscheibe, nicht die Behauptung. Horst bleibt in der Abwehr, und die Chance auf ein echtes Gespräch ist vertan.","score":-2,"nextStepId":"step-fail"},{"text":"„Ich verstehe, dass das nach wenig aussieht. Aber auch der Piks zeigt dem Immunsystem etwas vom Erreger, und daraus bildet es Gedächtniszellen, die ihn später wiedererkennen. So funktioniert das nun mal.“","style":"frontal","reaction":"„Mag sein, aber das ist doch nicht dasselbe wie die echte Krankheit. Das ist alles so theoretisch.“","feedback":"Inhaltlich richtig und freundlich im Ton, aber du lieferst die Erklärung fertig, statt Horst selbst nachdenken zu lassen. Das bringt ihn nicht in Bewegung.","score":1,"nextStepId":"step-3-struggle"}]},"step-3":{"id":"step-3","speaker":"Onkel Horst","speech":"„Na gut, dass der Körper aus einer abgeschwächten Form des Virus lernen könnte, leuchtet mir fast ein. Aber was bringt dann die echte Krankheit zusätzlich? Dass sie mehr bringt, glaube ich trotzdem. Wir haben die Masern auch alle überlebt!“","options":[{"text":"„Genau das ist der Punkt: Bei der echten Infektion lernt das Immunsystem im Ernstfall, und der Ausgang ist ungewiss. Bei der Impfung lernt es ohne die echte Gefahr. Lesen wir mal nach, welche Komplikationen Masern haben können?“","style":"sokratisch","reaction":"„Komplikationen... klar, Fieber, Ausschlag, das kennt man. Aber lies ruhig nach, ich bin gespannt. Gefährlich fand ich es bisher nicht.“","feedback":"Sehr gut: Du unterscheidest Training und Erkrankung nach Impfung als Trainingslager statt gefährlicher Erstinfektion und lädst zum gemeinsamen Nachschauen ein. Horst bleibt Partner statt Gegner.","score":3,"nextStepId":"step-4"},{"text":"„Dass wir das überlebt haben, beweist nichts. Wir kennen ja nur die, die es überlebt haben. Du redest wie ein Überlebender, der behauptet, Lawinen seien harmlos, nur weil er unten angekommen ist.“","style":"frontal","reaction":"„Jetzt vergleichst du mich mit... also, du bist ganz schön überheblich für dein Alter. Das ist doch was ganz anderes!“","feedback":"Der Gedanke dahinter ist gut, die Wirkung nicht: Der Vergleich klingt wie eine Spitze gegen Horst. Ohne Barmherzigkeit fühlt er sich vorgeführt und blockt ab.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Ein starkes Immunsystem ist ja toll. Aber ist es dann nicht auch eine gute Idee, es gezielt mit Impfungen zu trainieren? Dann hat es doch alles Nötige gelernt, ohne dass jemand erkranken muss.“","style":"deeskalierend","reaction":"„Haha, du bist mir ein Schlitzohr. Aber nein, ich bleibe dabei: natürlich ist besser.“","feedback":"Der Ton ist freundlich, aber die Frage deckt die Schwachstelle nicht auf. Du hast noch keinen Unterschied zwischen Lernen und Erkranken sichtbar gemacht.","score":1,"nextStepId":"step-3-struggle"}]},"step-4":{"id":"step-4","speaker":"Onkel Horst","speech":"„Okay, ich will mich nicht blamieren, schauen wir mal nach. Aber ehrlich gesagt: Bei Annegrets Kleiner sieht das bisher auch nicht dramatisch aus.“","options":[{"text":"„Da hast du einen Punkt: Bei Annegrets Kleiner verläuft es bisher vielleicht mild. Das sagt nichts über andere Kinder, vorher weiß man nicht, wie es ausgeht. Das Risiko will ich den Kindern ersparen.“","style":"deeskalierend","reaction":"„Hm, das Risiko vorher nicht zu kennen, das stimmt schon. Ich will den Kindern ja nicht schaden... Ich sehe mir das an, versprochen.“","feedback":"Sehr gut: Du würdigst Horsts Beobachtung, trennst den Einzelfall vom allgemeinen Risiko und bleibst bei dem gemeinsamen Ziel. So bleibt die Tür offen.","score":3,"nextStepId":"step-success"},{"text":"„Ein einzelnes Kind beweist nichts. Wenn du so argumentierst, könnte man auch jedes Mal ohne Gurt fahren, weil es bisher gutging. Das ist kein Argument, das trägt.“","style":"frontal","reaction":"„Gurt, Gurt... du machst immer alles gleich so dramatisch. Ich bin schließlich kein Anfänger.“","feedback":"Der Vergleich trifft sachlich zu, wirkt aber belehrend. Ohne die Anerkennung von Horsts Fürsorge kommt er als Rüge an.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Ach, lassen wir das. Mach, was du für richtig hältst, dann soll es eben so sein. Ich will mich nicht länger mit dir darüber streiten, es ist ja deine Familie und nicht meine.“","style":"ausstieg","reaction":"„Na also, Einsicht! Dann fahren wir am Samstag los.“","feedback":"Aus Erschöpfung gibst du das Gespräch auf, und Horst deutet es als Zustimmung. Ein bewusster Ausstieg wäre in Ordnung gewesen, aber mit klarem Hinweis, dass du anderer Meinung bleibst.","score":-2,"nextStepId":"step-fail"}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Onkel Horst","speech":"„Ich weiß nicht, ihr redet immer so klug daher. Ich habe meine Meinung, und die wird sich nicht von heute auf morgen ändern.“","options":[{"text":"„Das muss sie auch nicht, Horst. Du willst den Kindern etwas Gutes tun, das schätze ich an dir. Wollen wir am Wochenende gemeinsam nachlesen, was die Fachleute zu Masern sagen?“","style":"deeskalierend","reaction":"„Nachlesen, das kann ich machen. Aber ich lege mich nicht fest, nur damit du es weißt.“","feedback":"Gute Landung: Du erhältst die Beziehung, würdigst Horsts gute Absicht und lässt die Sachfrage offen für ein nächstes Mal.","score":2,"nextStepId":"step-struggle-end"},{"text":"„Dann besteh halt auf deinem Dickkopf. Wundere dich nur nicht, wenn es schiefgeht. Ich habe dich gewarnt, und alle anderen in der Familie sehen das genauso wie ich.“","style":"frontal","reaction":"„Ach, das war es dann wohl mit dir. Wir sprechen uns, wenn die Kinder gesund sind!“","feedback":"Eine Drohung statt eines Angebots: Das beendet das Gespräch und zeigt Horst, dass seine Fürsorge für dich keine Rolle spielt.","score":-2,"nextStepId":"step-fail"}]},"step-success":{"id":"step-success","speaker":"Onkel Horst","speech":"„Weißt du, vielleicht schaue ich mir erst mal an, was der Kinderarzt sagt, bevor wir am Samstag zu Annegret fahren. Mir geht es ja nur um die Kinder. Danke, dass du mich nicht gleich zur Schnecke gemacht hast.“","options":[{"text":"„Das ist ein guter Plan, Horst. Und hey: Dass dir die Kinder so wichtig sind, ist genau das, was ich an dir mag.“","style":"deeskalierend","reaction":"„*schmunzelt* Na dann. Noch ein Stück Kuchen?“","feedback":"Rundes Ende: Die Beziehung ist heil, Horst überlegt neu, und ihr habt es mit Barmherzigkeit geschafft, die Behauptung zu prüfen statt den Menschen.","score":3}]},"step-struggle-end":{"id":"step-struggle-end","speaker":"Onkel Horst","speech":"„Schauen wir mal, wie es am Wochenende passt. Jetzt aber ein anderes Thema: Wie läuft es eigentlich bei dir auf der Arbeit?“","options":[{"text":"„Gern, ich erzähle dir davon. Und das mit den Masern: Sag mir einfach Bescheid, wenn du etwas gefunden hast, ich bin gespannt.“","style":"deeskalierend","reaction":"„Mach ich. Und jetzt hol uns mal noch Kaffee.“","feedback":"Sanfter Ausstieg mit offenem Faden: Du bleibst im Kontakt, Horst fühlt sich respektiert, und das Thema kann später weitergehen.","score":2}]},"step-fail":{"id":"step-fail","speaker":"Onkel Horst","speech":"„Schluss jetzt. Ich weiß, was ich weiß, und am Samstag fahren wir hin. Daran ändert dein Gerede nichts.“","options":[{"text":"Ende: Horst fühlte sich angegriffen oder allein gelassen, und der Plan für Samstag steht. Rechthaben und Helfen sind zweierlei.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst Horsts gute Absicht würdigen, dann erst über die Sache reden.","feedback":"Frage dich: Habe ich die Behauptung geprüft oder den Menschen abgewertet? Intellektuelle Barmherzigkeit ordnet die Reihenfolge: erst Sorge anerkennen, dann Argumente.","score":0}]}},"status":"entwurf","familie":"genau-unterscheiden","fertigkeit":"F1","stufe":3,"kurz":"Eine Impfung trainiert das Immunsystem ohne die gefährliche Erkrankung. Bei Masern ist der Ausgang ungewiss, und sie können sogar einen Teil der vorhandenen Antikörper gegen andere Erreger auslöschen. Wer die Fürsorge hinter einer Meinung anerkennt, kann über die Sache reden.","prueffrage":"Was lässt sich vor einer Ansteckung darüber wissen, wie die Krankheit bei einem bestimmten Kind verlaufen wird?","quellen":[{"typ":"url","kurz":"World Health Organization: Vaccines and immunization: What is vaccination? (Stand 22.10.2025)","oeffentlich":true,"url":"https://www.who.int/news-room/questions-and-answers/item/vaccines-and-immunization-what-is-vaccination","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Donald Davidson (Malpas, J.; überarb. 28.04.2023), Abschn. 3.3","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Mina, M. J. u. a. (2019): Measles virus infection diminishes preexisting antibodies that offer protection from other pathogens. Science 366(6465), 599–606","oeffentlich":true,"doi":"10.1126/science.aay6485","url":"https://pubmed.ncbi.nlm.nih.gov/31672891/","abruf":"2026-10-13"}],"thema":"Gesundheit"},{"id":"scen-freund-lauch-fasten","title":"Leos 72-Stunden-Fastenwunder","subtitle":"Fasten heilt alles, geübt mit der Deeskalations-Matrix","character":"Leo","avatar":"🥛","context":"Dein Kumpel Leo hat gerade drei Tage nur Wasser getrunken und ist euphorisch. Er schwärmt, das habe seinen Körper „entgiftet“ und er wolle jetzt nur noch so seine Müdigkeit und seine Rückenschmerzen behandeln. Heute Abend drängt er dich, mitzumachen, und reagiert schnell gereizt, wenn du zögerst.","goal":"Bleib im Gespräch, nimm Leos Gefühle ernst und lenke mit Nachfragen darauf, was „Entgiften“ konkret bedeutet und woran man eine Wirkung erkennen würde.","bereich":"Freunde","laenge":"lang","ton":"ernst","bestehenAb":9,"lektion":"Wer sich nach drei Tagen Fasten tatsächlich besser fühlt, hat eine echte Erfahrung gemacht, aber „Toxine“ und „Schlacken“ bleiben ohne Namen, Messwert und Mechanismus leere Begriffe. Mit der Deeskalations-Matrix nimmst du zuerst das Gefühl ernst, dann wird die Frage „Was genau wurde entfernt, und woran hast du es gemessen?“ gemeinsam möglich. Wo es um Beschwerden geht, gehört eine ärztliche Abklärung dazu, und die Freundschaft ist wichtiger als das letzte Wort.","toolRef":"H.2.1","faktenRef":"G.3.1","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Leo","speech":"„Alter, 72 Stunden nur Wasser, und ich fühle mich wie neugeboren! Der ganze Dreck ist raus aus meinem Körper. Du musst das auch machen, die Toxine sammeln sich bei dir ja auch an!“","options":[{"text":"„Leo, das ist Quatsch. Deine Leber und deine Nieren entgiften dich sowieso rund um die Uhr. Da ist nichts ‚raus‘, du bist einfach nur hungrig.“","style":"frontal","reaction":"„Na klar, typisch! Du glaubst immer nur, was in deinen Lehrbüchern steht. Ich spüre den Unterschied, und du weißt es besser als ich selbst?“","feedback":"Die Sachaussage ist im Kern richtig (Leber und Nieren), aber als Frontalangriff gegen sein Erlebnis ausgesprochen. Leo fühlt sich abgewertet und verteidigt den Mythos, statt nachzudenken.","score":-2,"nextStepId":"step-fail"},{"text":"„Das klingt, als ginge es dir gerade richtig gut, und ich merke, wie stolz du bist, dass du das durchgezogen hast. Erzähl mal: Wie war das für dich, drei Tage nur Wasser?“","style":"deeskalierend","reaction":"„Ehrlich gesagt: Der zweite Tag war die Hölle. Aber am dritten war ich plötzlich klar im Kopf und viel wacher. Das war wie ein Reset.“","feedback":"Gefühl validieren statt Inhalt bestätigen: Du erkennst sein Erlebnis an, ohne dem Mythos zuzustimmen. Das öffnet die Tür.","score":3,"nextStepId":"step-2"},{"text":"„Wow, krass! Okay, wenn das so gut wirkt, probiere ich das nächste Woche auch gleich aus. Welche Wasserflasche hast du genommen?“","style":"humorvoll","reaction":"„Super, ich schicke dir meinen Plan! Und wenn du alles beschreibst, was passiert, bin ich dein Coach!“","feedback":"Du bleibst freundlich, stimmst aber der Entgiftungsbehauptung stillschweigend zu. Der Kanal ist offen, die Aussage unhinterfragt (Kipppunkt in).","score":-1,"nextStepId":"step-2-cheer"}]},"step-2":{"id":"step-2","speaker":"Leo","speech":"„Weißt du, mein Rücken tut seit Monaten weh, und ich war ständig müde. Seitdem ich das Fasten gemacht habe, ist es besser. Das ist doch der Beweis: Die Giftstoffe sind raus!“","options":[{"text":"„Ich verstehe, dass du dir das erklären willst, nach Monaten mit Schmerzen. Ich habe nur Schwierigkeiten, das nachzuvollziehen: Welcher Stoff genau wäre das, den dein Körper ausgeschieden hat?“","style":"sokratisch","reaction":"„Welcher Stoff... na ja, die Toxine eben. Die Schlacken, die sich über Jahre ansammeln. Den genauen Namen kenne ich nicht, aber das sagen alle Fastenärzte.“","feedback":"Eine Ich-Botschaft mit einer offenen Frage und die Kernfrage aus „Toxine“ / „Schlacken“ / „Entgiften“: Was ist das konkrete Toxin? Ohne Namen bleibt der Begriff leer. Leo bemerkt die Lücke selbst.","score":3,"nextStepId":"step-3"},{"text":"„Du hast ja keine Ahnung von Medizin, Leo. Rückenschmerzen heilen nicht durch Wasser. Du machst dir was vor.“","style":"frontal","reaction":"„Ach, jetzt bin ich also ein Idiot, der sich was vormacht? Erstens geht es mir besser, zweitens lasse ich mir das von dir nicht ausreden!“","feedback":"Eine Du-Botschaft als Anklage zwingt ihn in die Verteidigung. Du gewinnst vielleicht den Punkt, aber verlierst das Gespräch.","score":-2,"nextStepId":"step-fail"},{"text":"„Moment mal, das wollen wir beide schaffen: Es soll dir besser gehen. Lass uns das zusammen anschauen. Hast du schon mal bei einem Arzt abklären lassen, woher dein Rücken kommt?“","style":"deeskalierend","reaction":"„Ach, Ärzte... die geben dir nur Tabletten. Beim Orthopäden war ich einmal, der hat mir Krankengymnastik aufgeschrieben. Aber das ist doch nur Symptombekämpfung.“","feedback":"Gemeinsames Ziel finden ist ein guter Schachzug und bringt die Abklärung ins Spiel. Der Weg zur Detox-Frage ist aber noch offen.","score":2,"nextStepId":"step-3-alt"}]},"step-2-cheer":{"id":"step-2-cheer","speaker":"Leo","speech":"„Du wirst es merken! Und weißt du was? Ich habe diese Woche noch einen Detox-Tee bestellt, 45 Euro, damit die Toxine nicht gleich zurückkommen. Du kannst ja mit bestellen.“","options":[{"text":"„Moment, ich will das verstehen und nicht nur nicken. Wie heißt der Stoff, den der Tee entfernen soll, und woran würdest du merken, dass er wirklich weg ist?“","style":"sokratisch","reaction":"„Hm. Der Name steht nirgends. Aber auf der Packung steht ‚entschlackend und reinigend‘. Und merken tut man es halt am Körpergefühl.“","feedback":"Gute Korrektur! Du kehrst zur Kernfrage nach Namen und Messung zurück und bleibst dabei freundlich.","score":2,"nextStepId":"step-3"},{"text":"„Ach komm, ein bisschen Tee schadet ja nicht. Aber gib mal die Seite, ich schau, ob es da Rabatt gibt, 45 Euro sind schon happig.“","style":"humorvoll","reaction":"„Haha, genau! Ich schicke dir den Link. Gemeinsam ist das noch besser!“","feedback":"Du bleibst nett, unterstützt aber ein Produkt ohne belegte Wirkung. Da Leo damit seine Beschwerden behandeln will, rückt der Kipppunkt näher: Detox als Ersatz für echte Abklärung.","score":-2,"nextStepId":"step-fail"},{"text":"„Entschlackend ist ein Wort aus dem Hüttenwesen und hat im Körper keine Bedeutung. Der Tee ist rausgeschmissenes Geld, spar dir die 45 Euro.“","style":"frontal","reaction":"„Wow, schön abgelesen aus dem Lehrbuch. Hör auf, mir mein Wohlbefinden madig zu machen!“","feedback":"Inhaltlich richtig (Schlacken sind ein Begriff der Metallurgie), aber ohne Beziehungsarbeit kommt die Sachaussage als Angriff an.","score":-1,"nextStepId":"step-fail"}]},"step-3":{"id":"step-3","speaker":"Leo","speech":"„Okay, den genauen Namen kenne ich nicht. Aber ich weiß, wie ich mich fühle! Reicht das nicht? Der Körper ist doch von Umweltgiften und Fast Food total belastet, das weiß doch jeder!“","options":[{"text":"„Ich nehme dein Gefühl ernst, wir wollen beide, dass es dir gut geht. Nur: Wie hätten wir vorher und nachher messen können, ob wirklich etwas verschwunden ist?“","style":"sokratisch","reaction":"„Messen... na ja, ein Bluttest vielleicht? Aber ich habe nie einen gemacht. Ich habe mich einfach drauf verlassen, dass es stimmt.“","feedback":"Eine starke Kombination aus Gefühl validieren, Gemeinsamkeit finden und die Messfrage. Leo sieht selbst, dass ein objektiver Beleg fehlt.","score":3,"nextStepId":"step-4"},{"text":"„Jeder weiß das? Dann sag mir doch bitte mal: Welche Studie hat das nachgewiesen? Los, Quelle her!“","style":"sarkastisch","reaction":"„Du willst mich vorführen, oder? Das nervt! Ich muss mich nicht vor dir rechtfertigen!“","feedback":"Ein Verhörton eskaliert das Gespräch, obwohl die Frage berechtigt ist (Ziel ist das Gespräch, nicht der Punkt).","score":-2,"nextStepId":"step-fail"},{"text":"„Das Gefühl nach drei Tagen Wasser könnte auch daran liegen, dass du wenig gegessen hast und dich vielleicht etwas leichter und stolzer fühlst. Das ist ein Gefühl von Reinheit, das viele kennen.“","style":"deeskalierend","reaction":"„Hm, vielleicht... Aber ich will nicht glauben, dass alles nur Einbildung ist.“","feedback":"Eine freundliche Alternativerklärung, die Leos Gefühl ernst nimmt. Sie ist nicht schlecht, aber ohne die konkrete Messfrage bleibt sie weicher als nötig.","score":1,"nextStepId":"step-4-alt"}]},"step-3-alt":{"id":"step-3-alt","speaker":"Leo","speech":"„Weißt du, ich vertraue da einfach meinem Körper mehr als einem Rezept. Das Fasten war richtig. Und wenn mein Rücken wieder schlimmer wird, mache ich das einfach nochmal.“","options":[{"text":"„Das kann ich nachvollziehen. Eine Frage noch: Woran würdest du erkennen, dass das Fasten wirklich der Grund war und nicht einfach, dass der Schmerz sowieso schwankt?“","style":"sokratisch","reaction":"„Hm... der Schmerz schwankt tatsächlich, das stimmt. Mal besser, mal schlechter, auch ohne Fasten.“","feedback":"Gute Anschlussfrage: Du nimmst den Wunsch nach Selbstwirksamkeit ernst und lenkst auf die Frage nach einer belegbaren Wirkung. Die Detox-Frage selbst bleibt aber offen.","score":2,"nextStepId":"step-4"},{"text":"„Mach, was du willst. Aber wenn du dann im Krankenhaus landest, sag nicht, ich hätte dich nicht gewarnt. Ich habe es dir oft genug gesagt.“","style":"sarkastisch","reaction":"„Oh toll, jetzt drohst du mir auch noch. Danke für die Unterstützung, wirklich.“","feedback":"Drohung und Sarkasmus schließen das Gespräch. Dein Anliegen ist berechtigt, aber der Ton macht es zunichte.","score":-2,"nextStepId":"step-fail"},{"text":"„Ich merke, wir drehen uns im Kreis und die Stimmung wird angespannt. Lass uns das Thema für heute lassen und morgen mit frischem Kopf weiterreden.“","style":"ausstieg","reaction":"„Ja, okay. Vielleicht hast du recht. Aber morgen sprechen wir weiter, ja?“","feedback":"Eine strategische Auszeit rettet die Beziehung, löst aber die Sachfrage nicht. In einer ruhigen Phase ist das legitim, aber nicht der beste Zug, solange das Gespräch noch läuft.","score":0,"nextStepId":"step-4-alt"}]},"step-4":{"id":"step-4","speaker":"Leo","speech":"„Okay, ich gebe zu: Ich habe nie etwas gemessen. Aber mein Rücken, meine Müdigkeit... das ist ja nicht eingebildet. Was soll ich denn jetzt machen, einfach nichts?“","options":[{"text":"„Nein, genau das nicht. Dein Rücken und deine Müdigkeit sind echt, und genau deshalb lohnt sich eine Abklärung. Ich komme gern mit zu einem Arzt.“","style":"deeskalierend","reaction":"„Du würdest mitkommen? Echt? Okay... ich habe mich da lange nicht getraut, aber so mit dir wäre das einfacher.“","feedback":"Perfekter Abschluss: Kein Rechthaben, sondern ein konkreter nächster Schritt, der auf eine echte Abklärung statt auf ein Ritual setzt.","score":3,"nextStepId":"step-success"},{"text":"„Dann hör einfach auf mit dem ganzen Wellness-Quatsch und lass dich mal von einem richtigen Arzt untersuchen.“","style":"frontal","reaction":"„Wellness-Quatsch... na super. Ich dachte, wir sind Freunde und du hörst mir zu.“","feedback":"Die Richtung stimmt (ärztliche Abklärung), aber „Wellness-Quatsch“ ist abwertend und löst wieder Abwehr aus. Der Gedanke geht im Ton unter.","score":0,"nextStepId":"step-struggle"},{"text":"„Mach doch einfach alle paar Wochen so eine Fastenkur. Schaden kann es ja nicht, und vielleicht hilft es ja, wenn du daran glaubst.“","style":"humorvoll","reaction":"„Siehst du, genau das sage ich! Dann mache ich das ab jetzt monatlich und kaufe noch den Tee dazu.“","feedback":"Du bist nett, aber du bestärkst ihn darin, ein Ritual an die Stelle einer Abklärung zu setzen (Kipppunkt in). Der Erfolg bleibt zufällig.","score":-1,"nextStepId":"step-struggle"}]},"step-4-alt":{"id":"step-4-alt","speaker":"Leo","speech":"„Ich überlege schon, ob ich das alles zu sehr geglaubt habe. Aber ich will jetzt nicht, dass du denkst, ich sei leichtgläubig.“","options":[{"text":"„Das denke ich nicht. Dass man sich nach so einer Kur leichter fühlt, ist ein echtes Gefühl. Schauen wir, was bei deinem Rücken wirklich hilft. Ich begleite dich gern zum Arzt.“","style":"deeskalierend","reaction":"„Danke, das bedeutet mir was. Ich mache mal einen Termin aus.“","feedback":"Sehr gut: Du entlastest Leo vom Gesichtsverlust, validierst sein Gefühl und eröffnest einen konstruktiven Weg.","score":3,"nextStepId":"step-success"},{"text":"„Naja, ein bisschen leichtgläubig war das schon, ehrlich gesagt. Man hätte es vorher besser wissen können, wenn man nur einmal nachgelesen hätte.“","style":"frontal","reaction":"„Super, danke. Dann mache ich das eben allein weiter.“","feedback":"Ehrlich, aber verletzend. Gerade in dem Moment, in dem Leo sich öffnet, schließt du die Tür wieder.","score":-2,"nextStepId":"step-fail"},{"text":"„Ach, wer weiß schon so genau, was stimmt. Mach einfach, was dir guttut, und mach dir keinen Kopf darüber, ob das nun belegt ist oder nicht.“","style":"ausstieg","reaction":"„Ja, genau. Dann bleibe ich erstmal bei meinem Plan. Danke für dein Verständnis.“","feedback":"Du vermeidest den Konflikt, aber auch jede Klärung. Die Beziehung bleibt heil, die Sachfrage unberührt.","score":0,"nextStepId":"step-struggle"}]},"step-success":{"id":"step-success","speaker":"Leo","speech":"„Weißt du, ich dachte, du machst dich über mich lustig. Dass du zuhörst und trotzdem ehrlich bleibst, hilft mir echt. Gehen wir nächste Woche zusammen hin, und danach gibt es Pizza, okay?“","options":[{"text":"„Abgemacht. Und Pizza bezahle ich, wenn du mir danach erzählst, was der Arzt gesagt hat.“","style":"humorvoll","reaction":"„Deal! Und danach reden wir nochmal über meinen Tee. Vielleicht lasse ich den doch weg.“","feedback":"Mission gelungen! Gefühl ernst genommen, Messfrage gestellt, konkreten Schritt vereinbart. Die Freundschaft ist intakt, und Leo hat selbst gemerkt, dass der Beleg fehlt.","score":3},{"text":"„Gerne. Und beim Essen schauen wir uns an, welche Mittel gegen deine Müdigkeit tatsächlich belegt sind.“","style":"sokratisch","reaction":"„Gute Idee, dann habe ich endlich eine Quelle, der ich vertrauen kann.“","feedback":"Ein starker Abschluss: Du bietest eine gemeinsame Suche nach belastbarer Evidenz an, statt eine fertige Antwort zu liefern.","score":2}]},"step-struggle":{"id":"step-struggle","speaker":"Leo","speech":"„Ich weiß nicht, ich bin jetzt echt durcheinander. Lass uns später weiterreden, ich muss das erstmal sacken lassen.“","options":[{"text":"„Klar, gerne. Das war ein ehrliches Gespräch, und mir ist unsere Freundschaft wichtiger als jedes Thema. Meld dich, wenn du magst.“","style":"deeskalierend","reaction":"„Danke, Mann. Genau das brauche ich gerade. Bis bald.“","feedback":"Gute Auszeit: Die Beziehung ist geschützt und die Tür bleibt offen. Die Sachfrage ist noch ungeklärt, aber Leo wird nicht allein gelassen.","score":2},{"text":"„Okay. Aber überleg dir das gut, sonst gehst du bald an deiner Gesundheit zugrunde. Ich sage das nicht, um dich zu ärgern, sondern weil es stimmt.“","style":"sarkastisch","reaction":"„Super, jetzt prophezeist du mir auch noch den Untergang. Tschüss.“","feedback":"Eine düstere Drohung zum Abschied verbaut den Neustart. Schade, die gute Absicht geht im Ton verloren.","score":-2}]},"step-fail":{"id":"step-fail","speaker":"Leo","speech":"„Ich sehe schon, mit dir kann man darüber nicht reden. Ich ziehe mein Ding durch, und meine Fastenfreunde verstehen mich wenigstens.“ *greift zum Handy und geht*","options":[{"text":"Ende: Leo fühlt sich nicht gehört und rückt innerlich noch näher an die Fasten-Community. Rechthaben und Helfen sind zweierlei.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst das Gefühl ernst nehmen, dann erst nach Name, Messung und Mechanismus fragen.","feedback":"Frage dich: Wollte ich Leo überzeugen oder verstehen? Die Deeskalations-Matrix ordnet die Reihenfolge: erst Gefühl validieren, dann Fragen stellen.","score":0}]}},"status":"entwurf","familie":"begriff-messbar-machen","fertigkeit":"F1","stufe":3,"kurz":"Sich nach dem Fasten besser zu fühlen, ist eine echte Erfahrung, aber „Toxine“ und „Schlacken“ bleiben ohne Namen, Messwert und Mechanismus leere Begriffe. Erst das Gefühl ernst nehmen, dann gemeinsam fragen, was entfernt wurde; Beschwerden gehören ärztlich abgeklärt.","prueffrage":"Welcher Stoff genau soll den Körper verlassen haben, und mit welcher Messung vorher und nachher ließe sich das zeigen?","quellen":[{"typ":"url","kurz":"National Center for Complementary and Integrative Health (NIH): „Detoxes“ and „Cleanses“: What You Need To Know (Stand März 2025)","oeffentlich":true,"url":"https://www.nccih.nih.gov/health/detoxes-and-cleanses-what-you-need-to-know","abruf":"2026-10-12"},{"typ":"doi","kurz":"Klein, A. V.; Kiat, H. (2015): Detox diets for toxin elimination and weight management: a critical review of the evidence. Journal of Human Nutrition and Dietetics 28(6), 675–686","oeffentlich":false,"doi":"10.1111/jhn.12286","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"scen-vollmond-notaufnahme","title":"Schwester Annas Vollmondnächte","subtitle":"Verfügbarkeit, geübt mit Street Epistemology","character":"Anna, Krankenschwester","avatar":"🌕","context":"Du holst deine Freundin Anna von der Spätschicht in der Notaufnahme ab. Erschöpft steigt sie ins Auto und sagt, es sei ja klar gewesen, dass heute die Hölle los ist, denn draußen steht ein dicker Vollmond. Seit zwanzig Jahren, sagt sie, erlebe sie das immer wieder.","goal":"Bring Anna mit Street Epistemology dazu, selbst zu prüfen, wie sie zu ihrem Vollmond-Eindruck gekommen ist, ohne dass sie sich belehrt fühlt.","bereich":"Arbeit","laenge":"kurz","ton":"heiter","bestehenAb":4,"lektion":"Auffällige Nächte mit Vollmond bleiben im Gedächtnis, ruhige Vollmondnächte und turbulente Neumondnächte vergessen wir. Das ist die Verfügbarkeitsheuristik: Was uns leicht einfällt, erscheint uns häufig und wichtig. Street Epistemology fragt nicht „Du liegst falsch“, sondern „Wie weißt du das, und wie verlässlich ist diese Methode?“ und lässt das Gegenüber den entscheidenden Schritt selbst gehen.","toolRef":"H.2.2","faktenRef":"B.3","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Anna","speech":"„Puh, was für eine Nacht! Drei Einlieferungen in einer Stunde, und ich sag dir: Es ist Vollmond, ich hab's kommen sehen. Bei Vollmond ist bei uns in der Notaufnahme immer die Hölle los, das erlebe ich seit zwanzig Jahren!“","options":[{"text":"„Anna, das ist doch ein alter Mythos. Wie kannst du nach zwanzig Jahren im Gesundheitswesen noch so etwas glauben?“","style":"frontal","reaction":"„Wie ich das glauben kann? Ich stehe da jede Nacht, und du sitzt im Warmen und weißt es besser? Ich hab's mit eigenen Augen gesehen, das reicht mir!“","feedback":"Frontalangriff: Du bestreitest die Schlussfolgerung und stellst ihre Erfahrung infrage. Anna fühlt sich abgekanzelt und verteidigt den Mythos nur noch fester (nicht die Schlussfolgerung angreifen, sondern das Verfahren untersuchen).","score":-2,"nextStepId":"step-fail"},{"text":"„Oje, das klingt anstrengend. Und du bist sicher: Vollmond heißt immer Chaos? Sag mal, wie sicher bist du dir da auf einer Skala von 0 bis 100?“","style":"sokratisch","reaction":"„*lacht müde* Oh, 90 Prozent, mindestens! Fast alle Kolleginnen sagen dasselbe. Warum fragst du?“","feedback":"Gut: Die Skala von 0 bis 100 macht aus „stimmt/stimmt nicht“ ein flexibles Spektrum. Dir fehlt noch die Frage nach der Methode, aber die Gesprächsbasis ist freundlich.","score":2,"nextStepId":"step-2-skala"},{"text":"„Spannend! Darf ich dich dazu etwas fragen? Woran machst du das fest, dass Vollmondnächte bei euch anders laufen? Was ist dein Hauptgrund, dir da so sicher zu sein?“","style":"sokratisch","reaction":"„*lehnt sich zurück* Na, weil ich's erlebe! Ich merke mir die Nächte doch: Vollmond, Sirenen, überfüllte Flure. Das prägt sich ein, glaub mir.“","feedback":"Sehr gut: Du holst dir die Erlaubnis zum Fragen und deckst gleich die Methode hinter ihrer Überzeugung auf. Anna nennt jetzt ihre eigene Quelle: das Erinnern.","score":3,"nextStepId":"step-2-methode"}]},"step-2-skala":{"id":"step-2-skala","speaker":"Anna","speech":"„Warum ich so sicher bin? Weil Kollegin Mareike und ich wirklich schwören: Vollmond heißt Ausnahmezustand. Das weiß doch jeder in der Pflege!“","options":[{"text":"„Ich habe mal gelesen, dass das nur Einbildung ist. Du erinnerst dich eben an die Vollmondnächte, weil du sie erwartest. Die ruhigen vergisst du einfach.“","style":"frontal","reaction":"„Einbildung?! Na danke. Du warst noch nie nachts im Schockraum. Lassen wir das Thema.“ *schaut aus dem Fenster*","feedback":"Inhaltlich im Kern richtig, aber als fertige Belehrung serviert. Anna fühlt sich nicht verstanden, und die Methodenfrage bleibt ungestellt.","score":-1,"nextStepId":"step-fail"},{"text":"„Verstehe, 90 Prozent ist viel. Darf ich noch eine Frage stellen? Was ist für dich der Hauptgrund, der dich so sicher macht? Woher weißt du, dass es so ist?“","style":"sokratisch","reaction":"„Woher ich das weiß? *überlegt* Na, aus meiner Erfahrung! Wenn Vollmond ist, merke ich mir die Nacht, weil sie so besonders chaotisch war.“","feedback":"Gut: Nach der Sicherheitsskala fragst du jetzt nach der Methode. Anna bringt von selbst ins Spiel, dass sie sich die chaotischen Nächte „merkt“, der Schlüssel zur Verfügbarkeitsheuristik.","score":3,"nextStepId":"step-3-success"},{"text":"„Haha, dann hängt wohl die gesamte Pflege am Mondkalender! Seid ihr nachts eigentlich alle Werwölfe oder nur ein bisschen mondsüchtig?“","style":"sarkastisch","reaction":"„*verdreht die Augen* Sehr witzig. Ich hab gerade zwölf Stunden gearbeitet, ich brauche keine Witze auf meine Kosten.“","feedback":"Sarkasmus auf Kosten der Person: Anna fühlt sich nicht ernst genommen. Street Epistemology lebt von echter Neugier, nicht von Spott. Seziert wird die Behauptung, nicht der Mensch.","score":-2,"nextStepId":"step-fail"}]},"step-2-methode":{"id":"step-2-methode","speaker":"Anna","speech":"„Ich sag's dir: Ich merke mir diese Nächte einfach. Wenn es Vollmond ist und es kracht, das vergisst man nicht, das erzähle ich noch Wochen später im Pausenraum.“","options":[{"text":"„Das glaube ich dir, solche Nächte brennen sich ein. Ich frage mich gerade: Wie sieht es mit den Vollmondnächten aus, in denen kaum was los war? Merkst du dir die genauso gut?“","style":"sokratisch","reaction":"„*stutzt* Die ruhigen Vollmondnächte? Hm. Ehrlich gesagt... die bleiben nicht hängen. Da denke ich am nächsten Tag gar nicht mehr drüber nach.“","feedback":"Treffer: Du lenkst den Blick auf die vergessenen Fälle und legst damit den Kern der Verfügbarkeitsheuristik frei: Leichter abrufbar ist, was auffällig war.","score":3,"nextStepId":"step-3-success"},{"text":"„Das ist doch genau die Verfügbarkeitsheuristik, Anna! Dein Gehirn merkt sich nur das Spektakuläre und schätzt deshalb die Häufigkeit völlig falsch ein.“","style":"frontal","reaction":"„Verfügbarkeits-was? Spar dir die Fachbegriffe. Du erklärst mir meinen Beruf und meine Wahrnehmung, na vielen Dank.“","feedback":"Fachlich benennst du es richtig, aber als fertige Diagnose statt als gemeinsame Entdeckung. Das Etikett kommt zu früh und wirkt wie ein Urteil (Fragen statt Fakten präsentieren).","score":-1,"nextStepId":"step-fail"},{"text":"„Genau, Erinnerung ist alles. Ich wünsche dir jedenfalls eine ruhige nächste Nacht, egal bei welchem Mond. Magst du noch einen Kaffee?“","style":"ausstieg","reaction":"„Ach, ein Kaffee wäre toll! Und ruhig wird die Nacht sicher nicht, aber danke dir.“","feedback":"Freundlicher Ausstieg: Die Beziehung bleibt heil, aber die Chance ist vertan. Du hast die Methode nur gestreift und keinen Zweifelsstein ins Rollen gebracht.","score":0,"nextStepId":"step-neutral"}]},"step-3-success":{"id":"step-3-success","speaker":"Anna","speech":"„*lacht verblüfft* Moment mal... Ich merke mir die wilden Nächte, klar. Aber die ruhigen Vollmondnächte? Die vergesse ich wohl. Ob das auch stimmen würde, wenn ich wirklich mal Strichlisten führen würde?“","options":[{"text":"„Gute Frage! Wärst du neugierig auf einen Test? Ihr gleicht eure Einsatzzahlen der letzten Monate mit dem Mondkalender ab und schaut, was verlässlicher ist: Erinnerung oder Strichliste.“","style":"sokratisch","reaction":"„Das mache ich! Ich frage Mareike morgen, ob wir mal die Dienstbücher anschauen. Wenn ich falsch liege, geb ich dir einen aus!“","feedback":"Perfekt: Du lässt Anna ihre eigene Methode prüfen und bietest eine verlässlichere an (Daten statt Gedächtnis). Das ist Street Epistemology in Reinform, und Anna zieht den Schluss selbst.","score":3},{"text":"„Genau, Anna! Dann ist das mit dem Vollmond ja wohl erledigt. Kopf hoch, bald wirst du über deine alten Vollmond-Geschichten schmunzeln, wetten? Das ist alles nur Einbildung.“","style":"frontal","reaction":"„Naja... vielleicht. Ich muss das erst mal sacken lassen. Mal sehen, was Mareike dazu sagt.“","feedback":"Du nimmst ihr den Gedanken ab und verkündest das Ergebnis, bevor sie es selbst geprüft hat. Die Einsicht bleibt wackelig; besser wäre gewesen, die Prüfung bei ihr zu lassen.","score":1},{"text":"„Wahrscheinlich liegt's an der Gruppe, ihr bestätigt euch gegenseitig. Typisches Herdendenken! So entstehen solche Geschichten in jedem Team, das kennt man doch.“","style":"sarkastisch","reaction":"„*kühl* Herdendenken? Ich dachte, du verstehst mich. Fahr einfach, ja?“","feedback":"Kurz vor dem Ziel wertest du ihre Kolleginnen und sie selbst ab. Die entstandene Offenheit schließt sich wieder; Neugier statt Spott ist der Kern von „Street Epistemology“.","score":-2}]},"step-neutral":{"id":"step-neutral","speaker":"Anna","speech":"„Danke fürs Abholen, wirklich. Und morgen Nacht ist wieder Vollmond. Ich sag's dir, das wird wieder wild.“","options":[{"text":"Ende: Das Gespräch blieb freundlich, aber Annas Eindruck steht unverändert. Du hast die Beziehung geschützt, ohne den Zweifel zu säen.","style":"ausstieg","reaction":"Beim nächsten Mal die Frage nach den ruhigen Vollmondnächten stellen und Anna die Gegenprobe selbst entdecken lassen.","feedback":"Street Epistemology braucht eine Frage, die das eigene Verfahren zeigt. Ohne die ruhigen Vollmondnächte bleibt die Verfügbarkeitsheuristik unsichtbar.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Anna","speech":"„*schaut stur geradeaus* Weißt du was? Ich habe gerade echt keine Lust auf Mondphasen-Diskussionen. Fahr einfach.“","options":[{"text":"Ende: Anna fühlte sich belehrt oder verspottet und hält nur noch stärker an ihrem Vollmond-Eindruck fest. Recht haben und Helfen sind zweierlei.","style":"ausstieg","reaction":"Beim nächsten Mal mit Neugier fragen, nicht mit Urteil: Wie weißt du das? Wie verlässlich ist diese Methode?","feedback":"Wer die Schlussfolgerung angreift, löst Verteidigung aus. Street Epistemology untersucht das Verfahren, nicht die Schlussfolgerung, und seziert die Behauptung, nicht den Menschen.","score":0}]}},"status":"entwurf","familie":"basisrate-beachten","fertigkeit":"F4","stufe":1,"kurz":"Turbulente Vollmondnächte bleiben im Gedächtnis, ruhige Vollmondnächte und wilde Neumondnächte werden vergessen. Was leicht einfällt, wirkt häufig; weiter hilft die Frage, wie verlässlich der Weg zu einem solchen Eindruck ist.","prueffrage":"Welche Nächte fehlen, wenn nur die erinnerten Vollmondnächte zählen, und was ergäbe ein Abgleich der Einsatzzahlen mit dem Mondkalender?","quellen":[{"typ":"url","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), Abstract bei PubMed (DOI 10.1126/science.185.4157.1124)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/17835457/","abruf":"2026-10-12"},{"typ":"url","kurz":"Street Epistemology International: Street Epistemology (Startseite, Selbstdarstellung der Methode)","oeffentlich":true,"url":"https://streetepistemology.com/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kamat, S. u. a. (2014): Pediatric psychiatric emergency department visits during a full moon. Pediatric Emergency Care 30(12) (Abstract bei PubMed)","oeffentlich":true,"doi":"10.1097/PEC.0000000000000291","url":"https://pubmed.ncbi.nlm.nih.gov/25407032/","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"scen-schwager-recherche","title":"Schwagers 400 Browser-Tabs","subtitle":"„Eigene Recherche“, geübt mit Neuroplastizität und Konzentration","character":"Jürgen, Schwager im Familienchat","avatar":"🔎","context":"Im Familienchat schreibt dein Schwager Jürgen, er habe sich „tagelang selbst eingelesen“ und wisse jetzt, was Fachleute alles verschweigen. Er schickt dir einen Stapel Links aus Blogs, Videos und Telegram-Kanälen und wirft allen, die ihm widersprechen, vor, sie würden „einfach alles glauben, was man ihnen erzählt“.","goal":"Nimm Jürgens Wunsch nach eigenem Denken ernst, hinterfrage ruhig seine Methode statt seiner Person und bring das Gespräch auf Quellenprüfung und Gegenbelege.","bereich":"Online","laenge":"lang","ton":"ernst","bestehenAb":9,"lektion":"„Selbst nachdenken“ ist ein guter Appell, solange er heißt, die eigenen Methoden zu prüfen und gezielt nach den stärksten Gegenargumenten zu suchen. Wer nur sucht, was zur eigenen Meinung passt, sammelt Bestätigung und keine Belege. Wer Jürgens Anspruch annimmt und ihn auf diese höhere Ebene hebt, bleibt im Gespräch. Konzentration lässt sich üben, am ehesten an genau der Tätigkeit, für die man sie braucht: etwa täglich eine feste, kurze Zeit (als Faustregel 15–30 Minuten) einen Beleg ohne Ablenkung prüfen statt vierhundert offene Tabs.","toolRef":"H.1.5","faktenRef":"G.1.2","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Jürgen","speech":"„Ich sag nur: Mach mal deine eigene Recherche! Ich hab mich tagelang durchs Netz gearbeitet, über 400 Tabs. Wer das nicht tut, glaubt einfach alles, was im Fernsehen erzählt wird. Ich denke wenigstens selbst nach!“","options":[{"text":"„Das Internet ist keine Quelle, Jürgen. Das ist alles Quatsch, was du da liest. Überlass das Recherchieren lieber denen, die davon was verstehen.“","style":"frontal","reaction":"„Aha, ich soll also das Denken den Eliten überlassen. Genau so sprechen die Schlafschafe. Ich dachte, du bist anders!“","feedback":"Frontalangriff! Du lehnst sein Selbstbild als Selbstdenker pauschal ab. Das bestätigt genau seine Erzählung vom „blinden Vertrauen“ und macht dich zum Teil der Outgroup.","score":-2,"nextStepId":"step-fail"},{"text":"„Selbst nachzudenken ist wirklich wichtig, da bin ich bei dir. Mich interessiert: Wie gehst du vor, wenn du recherchierst? Womit fängst du an?“","style":"sokratisch","reaction":"„Na, ich such mir Infos zusammen, die nicht im Mainstream stehen. Videos, Blogs, Kanäle, wo die Leute noch den Mund aufmachen. Eigentlich immer da, wo es um das geht, was verschwiegen wird.“","feedback":"Stark! Du nimmst den Appell beim Wort und fragst nach der Methode statt nach dem Ergebnis. Echte Neugier öffnet das Gespräch.","score":3,"nextStepId":"step-2"},{"text":"„Wow, 400 Tabs, das klingt nach richtig viel Arbeit. Dann machen wir es so: Du schickst mir deine zwei besten Links, ich lese sie nach Feierabend durch.“","style":"humorvoll","reaction":"„Gut, wenigstens einer, der zuhört! Ich schick dir gleich die Perlen. Aber lies sie mit offenen Augen!“","feedback":"Freundlich und beziehungsschonend, aber du lässt offen, wie er seine Quellen auswählt und prüft. Als Einstieg brauchbar, die Methodenfrage fehlt noch.","score":1,"nextStepId":"step-2"}]},"step-2":{"id":"step-2","speaker":"Jürgen","speech":"„Die offiziellen Stellen sagen doch eh nur, was sie sagen sollen. Wenn fünf Quellen aus verschiedenen Ecken dasselbe berichten, dann muss doch was dran sein. Und die finde ich alle selbst!“","options":[{"text":"„Fünf unabhängige Quellen sind ein gutes Zeichen. Wie stellst du sicher, dass sie wirklich unabhängig sind und nicht alle voneinander abschreiben? Woran erkennst du das?“","style":"sokratisch","reaction":"„Hm... Dass die sich gegenseitig zitieren, ist mir tatsächlich schon aufgefallen. Aber das heißt ja nicht, dass es falsch ist. Ich schau da genau hin, glaub ich.“","feedback":"Sehr gut! Du machst aus „fünf Quellen“ eine prüfbare Frage. Das ist die Frage nach der Methode, die „Selbst nachdenken“ / „Eigene Recherche“ empfiehlt: nicht ablehnen, sondern beim Wort nehmen.","score":3,"nextStepId":"step-3"},{"text":"„Fünf Treffer in derselben Ecke des Netzes sind kein Beweis. Das ist Bestätigungsfehler, der ist wissenschaftlich belegt. Lies mal nach, Jürgen.“","style":"frontal","reaction":"„Bestätigungsfehler, wieder so ein Fachwort, mit dem ihr jeden abbügelt, der nicht eurer Meinung ist. Typisch!“","feedback":"Inhaltlich nicht falsch (Bestätigungsfehler), aber als Etikett hingeworfen wirkt es wie ein Totschlagargument. Besser eine Frage, die ihn selbst die Lücke finden lässt.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Ich verstehe, dass dir die offiziellen Stellen manchmal zu glatt klingen. Lass uns zusammen schauen, welche deiner fünf Quellen die erste war. Von dort ging ja alles aus.“","style":"deeskalierend","reaction":"„Die erste? Das war irgendein Telegram-Kanal, glaub ich. Dann kam alles Weitere von dort.“","feedback":"Ruhig und gemeinsam am Material gearbeitet. Du klärst, ob die „fünf Quellen“ eigentlich eine einzige sind. Das ist ein guter Hebel für eine Prüfung.","score":2,"nextStepId":"step-3"}]},"step-3":{"id":"step-3","speaker":"Jürgen","speech":"„Okay, ein bisschen was ist da ein Echo, kann sein. Aber die anderen glauben doch blind den Experten. Ich dagegen verlasse mich auf niemanden, nur auf mich selbst.“","options":[{"text":"„Dann ist dein Gehirn eben besser als das aller Wissenschaftler zusammen. Wenn du es besser weißt, geh doch zum Nobelpreis, Jürgen.“","style":"sarkastisch","reaction":"„Du machst dich über mich lustig! Das ist genau dieser Hochmut, den ich meine. Ihr hört nie zu!“","feedback":"Sarkasmus trifft den Menschen, nicht die Behauptung. Du bestätigst sein Bild von arroganten Besserwissern und verlierst den Gesprächsfaden.","score":-2,"nextStepId":"step-fail"},{"text":"„Entweder blind vertrauen oder alles allein herausfinden, ist das wirklich die einzige Wahl? Man kann doch auch prüfen, wie verlässlich eine Quelle ist, und das ist ja selbstständiges Denken.“","style":"sokratisch","reaction":"„Prüfen, wie verlässlich eine Quelle ist... Na ja, das mach ich ja irgendwie auch. Nur anders als die Mainstream-Leute, die einfach alles abnicken.“","feedback":"Treffer! Du entlarvst das falsche Dilemma: Es gibt eine dritte Option, nämlich die Glaubwürdigkeit von Quellen selbst zu bewerten. Dem Wunsch nach Unabhängigkeit wird damit entsprochen.","score":3,"nextStepId":"step-4"},{"text":"„Ich finde es gut, dass du dir Gedanken machst. Mich würde interessieren: Hast du schon mal nach der stärksten Gegenposition gesucht und sie ernsthaft gelesen?“","style":"sokratisch","reaction":"„Gegenposition? Die kenn ich doch, das ist das, was im Fernsehen kommt. Muss ich mir doch nicht extra antun...“","feedback":"Gute Frage, die genau auf die Lücke zielt: gezielt nach Gegenbelegen suchen. Er weicht noch aus, aber der Gedanke ist platziert.","score":2,"nextStepId":"step-4"}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Jürgen","speech":"„Ich hab keinen Bock auf Fachwörter-Bingo. Entweder du schaust dir meine Sachen an, oder wir lassen es.“","options":[{"text":"„Fair genug, ich nehme das Wort zurück. Zeig mir den Beitrag, der dich am meisten überzeugt hat, und ich gucke ihn mir in Ruhe an.“","style":"deeskalierend","reaction":"„Na gut. Der hier hat mich komplett umgehauen, der erklärt alles. Aber schau ihn bis zum Ende!“","feedback":"Gute Reparatur. Du nimmst Druck raus und holst dir die Gelegenheit zurück, gemeinsam am Material zu arbeiten.","score":1,"nextStepId":"step-4"},{"text":"„Stimmt, das war zu schulmeisterlich. Weißt du, was? Wir hören hier auf und sprechen am Wochenende in Ruhe, bei einem Bier.“","style":"ausstieg","reaction":"„Ja, lass gut sein. Aber ich überzeug dich noch, wirst sehen.“","feedback":"Würdiger Ausstieg: Die Beziehung bleibt heil, die Sachfrage offen. Kein Fortschritt in der Sache, aber auch kein Schaden.","score":0,"nextStepId":"step-end-neutral"}]},"step-4":{"id":"step-4","speaker":"Jürgen","speech":"„Was mich nervt: Ich komm einfach nicht mehr dazu, einen langen Artikel am Stück zu lesen. Nach zwei Absätzen bin ich schon im nächsten Tab. Dabei wollte ich alles gründlich durchgehen.“","options":[{"text":"„Das ist kein Wunder: Wer ständig hin- und herspringt, übt genau das ein, und das wird zur Gewohnheit. Ausdauer beim Lesen lässt sich aber auch wieder üben, am besten beim Lesen selbst.“","style":"sokratisch","reaction":"„Echt? Dass man das üben kann, wusste ich nicht. Ich dachte immer, entweder man kann sich konzentrieren oder nicht.“","feedback":"Erklärt den Mechanismus, bietet aber noch keinen konkreten nächsten Schritt wie die 15–30-Minuten-Übung.","score":2,"nextStepId":"step-5"},{"text":"„Dann liegt es eben an deinem Handy, nicht an den Quellen. Schmeiß es weg, dann klappt's.“","style":"frontal","reaction":"„Du sagst das so einfach. Ohne Handy bin ich doch aufgeschmissen, und mein Alltag läuft darüber.“","feedback":"Zu pauschal und etwas belehrend. Der Rat ist weder umsetzbar noch erklärt er den Mechanismus. Gesprächsöffner wäre eine kleine, machbare Übung gewesen.","score":-1,"nextStepId":"step-5"},{"text":"„Kenn ich auch. Mir hilft es, 15 bis 30 Minuten nur eine Sache zu machen, Handy außer Sichtweite. Am Anfang rebelliert der Kopf, aber es wird besser. Wollen wir das mal probieren?“","style":"humorvoll","reaction":"„15 Minuten nur ein Text? Das klingt machbar. Eigentlich fast zu einfach... aber okay, ich probier's.“","feedback":"Alltagsnah und machbar: eine kurze, feste Zeit ohne Ablenkung (als Faustregel 15–30 Minuten), eingebettet in eigene Erfahrung statt als Vortrag.","score":3,"nextStepId":"step-5"}]},"step-5":{"id":"step-5","speaker":"Jürgen","speech":"„Dann sag mir: Wie würdest du es denn machen? Wenn ich wirklich sauber prüfen will, ob an einer Sache was dran ist, was soll ich tun?“","options":[{"text":"„Such dir einen Beleg, den du glaubst, und lies in Ruhe die stärkste Gegenposition dazu. Prüf bei beiden: Wer sagt das, woher weiß er es, und was spräche dagegen?“","style":"sokratisch","reaction":"„Hm, die stärkste Gegenposition... das hab ich bisher eigentlich nie gemacht. Okay. Ich versuch es mit dem ersten Video von vorhin.“","feedback":"Genau das ist der Kern von „Selbst nachdenken“ / „Eigene Recherche“: Methoden hinterfragen und aktiv nach den stärksten Gegenargumenten suchen. Konkret, machbar und ohne Belehrung.","score":3,"nextStepId":"step-6-success"},{"text":"„Sieh dir erst mal an, wer hinter einer Quelle steckt und woher sie ihr Wissen hat. Das hilft schon viel, auch wenn es mehr Zeit kostet und nicht jede Quelle sofort preisgibt.“","style":"deeskalierend","reaction":"„Klingt vernünftig. Quelle prüfen, ja. Das mach ich ab jetzt, glaub ich, öfter.“","feedback":"Brauchbarer erster Schritt (Quellenprüfung), aber ohne den entscheidenden Zusatz: gezielt nach Gegenbelegen suchen. Etwas weniger Wirkung als die vollständige Methode.","score":1,"nextStepId":"step-6-success"},{"text":"„Wahrscheinlich bringt es gar nichts, Jürgen. Am Ende glaubst du ohnehin nur, was in dein Bild passt, egal wie viele Quellen du liest.“","style":"sarkastisch","reaction":"„Na toll. Dann hab ich also keine Chance, nur weil ich nicht studiert habe. Danke für nichts.“","feedback":"Du entwertest den Menschen, nicht die Methode. Aus einer offenen Frage wird ein Rückzug, und die „Sezier-den-Menschen“-Falle schnappt zu.","score":-2,"nextStepId":"step-fail"}]},"step-6-success":{"id":"step-6-success","speaker":"Jürgen","speech":"„Gut. Ich mach das jetzt mal in Ruhe, einen Beleg, eine Gegenposition. Und wenn ich merke, dass meine fünf Quellen alle von einer abgeschrieben haben, sag ich dir Bescheid.“","options":[{"text":"„Das fände ich stark, Jürgen. Und wenn ich mich irre, sag mir das auch. Zwei gute Quellen schlagen vierhundert Tabs, und am Ende ist es dein eigenes Denken, das gewinnt.“","style":"deeskalierend","reaction":"„Abgemacht. Und danke, dass du nicht gleich wieder auf mich losgegangen bist. Das war mal ein Gespräch.“","feedback":"Stark abgerundet: Der Slogan der Aufklärung wird in seiner anspruchsvollen Bedeutung zurückgegeben und die Beziehung bleibt gesund.","score":3}]},"step-end-neutral":{"id":"step-end-neutral","speaker":"Jürgen","speech":"„Bis Samstag dann. Aber bring Argumente mit.“","options":[{"text":"Ende: Das Gespräch ist offen geblieben. Die Beziehung ist heil, ein Gedanke ist gesät, aber die Methodenfrage wartet auf eine bessere Gelegenheit.","style":"ausstieg","reaction":"Beim nächsten Mal mit einer offenen Frage nach Jürgens Vorgehen beginnen, statt mit Etiketten.","feedback":"Der Ausstieg schützt die Beziehung. Die stärkste Wirkung hätte aber die Methodenfrage nach Quellenprüfung und Gegenbelegen gehabt.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Jürgen","speech":"„Weißt du was, mit euch Schlafschafen kann man nicht reden. Ich schicke meine Links lieber in die Gruppe, da versteht man mich wenigstens!“ *verlässt den Familienchat*","options":[{"text":"Ende: Jürgen hat sich nicht gehört gefühlt und zieht sich tiefer in die Echokammer zurück. Seziert wurde der Mensch, nicht die Behauptung.","style":"ausstieg","reaction":"Beim nächsten Mal seinen Wunsch nach eigenem Denken ernst nehmen und die Methode hinterfragen statt die Person.","feedback":"„Eigene Recherche“ ist ein Appell, den man beim Wort nehmen sollte. Wer ihn abwertet, bestätigt die Erzählung der Außenseiter-Gruppe.","score":0}]}},"status":"entwurf","familie":"quelle-zurueckverfolgen","fertigkeit":"F1","stufe":4,"kurz":"Selbst nachdenken heißt, die eigene Methode zu prüfen und gezielt nach den stärksten Gegenargumenten zu suchen. Wer nur sammelt, was zur eigenen Meinung passt, sammelt Bestätigung statt Belege, und Quellen, die voneinander abschreiben, sind keine unabhängige Bestätigung.","prueffrage":"Woher stammen die fünf Quellen jeweils, und wie viele davon gehen auf denselben Ursprung zurück?","quellen":[{"typ":"doi","kurz":"Chinn, S.; Hasell, A. (2023): Support for „doing your own research“ is associated with COVID-19 misperceptions and scientific mistrust. Harvard Kennedy School Misinformation Review 4(3)","oeffentlich":true,"doi":"10.37016/mr-2020-117","abruf":"2026-10-12"},{"typ":"doi","kurz":"Owen, A. M. u. a. (2010): Putting brain training to the test. Nature 465(7299) (Autorenfassung PMC2884087)","oeffentlich":true,"doi":"10.1038/nature09042","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2884087/","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"scen-kommentar-kein-beweis","title":"„Dafür gibt es keinen Beweis!“","subtitle":"Wenn die Beweislast umgedreht wird, geübt mit Street Epistemology","character":"Anon_Falke, Kommentator","avatar":"💬","context":"Unter einem Artikel über ein angebliches Wundermittel für alle Beschwerden hat Anon_Falke kommentiert: „Und? Hat irgendjemand bewiesen, dass es NICHT wirkt? Eben! Solange das keiner schafft, glaube ich daran.“ Inzwischen antwortet er auf jeden Einwand mit Spott und Sarkasmus.","goal":"Bring Anon_Falke mit Street Epistemology dazu, über seine eigene Methode nachzudenken, statt ihn mit Fakten zu überrollen.","bereich":"Online","laenge":"mittel","ton":"sarkastisch","bestehenAb":6,"lektion":"Ein „Das wurde nicht widerlegt“ ist kein Beleg, denn die Beweislast trägt, wer die Behauptung aufstellt, und eine Wissenslücke darf nicht mit der Lieblingserklärung gefüllt werden. Wer stattdessen höflich nach Methode, Sicherheit und einem fairen Test fragt, lässt das Gegenüber selbst über die Zuverlässigkeit seines Wegs nachdenken, ohne dass es das Gesicht verliert.","toolRef":"H.2.2","faktenRef":"B.11","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Anon_Falke","speech":"„Na, wer traut sich? Beweist mir doch, dass das Mittel nicht wirkt! Ich warte. Und solange keiner liefert, bleibt es für mich wahr. So einfach ist das, ihr Schulmedizin-Gläubigen!“","options":[{"text":"„Dein Argument ist ein klassischer Fehlschluss. Wer nichts belegen kann, sollte lieber den Mund halten, statt andere aufzufordern, seine Märchen zu widerlegen.“","style":"frontal","reaction":"„Oho, der Herr Oberlehrer! Fehlschluss hier, Fehlschluss da. Hauptsache klug klingen, aber nicht einen einzigen Beweis liefern. Typisch!“","feedback":"Frontalangriff! Die Diagnose stimmt, aber du greifst den Menschen an und nicht die Methode. Anon_Falke wird defensiv, genau das warnt „Street Epistemology“ vor.","score":-2,"nextStepId":"step-fail"},{"text":"„Spannend! Darf ich nachfragen: Was genau soll dieses Mittel bewirken, und was ist für dich der Hauptgrund, dass du so sicher bist?“","style":"sokratisch","reaction":"„Ach, jetzt kommt die Fragestunde. Na gut: Es soll Beschwerden lindern, und der Hauptgrund ist ganz einfach: Es gibt keine Studie, die das Gegenteil zeigt. Reicht dir das?“","feedback":"Sehr gut! Street Epistemology: Erst die Behauptung klären, dann nach dem Hauptgrund fragen, ohne zu urteilen. Anon_Falke legt seine Methode selbst offen.","score":3,"nextStepId":"step-2"},{"text":"„Bestimmt wirkt es auch bei manchen. Was soll’s, jeder wie er mag. Ich halte mich aus solchen Diskussionen lieber raus.“","style":"ausstieg","reaction":"„Haha, wieder einer, der kneift! So gewinnt man Debatten. Danke fürs Zugeben, dass ihr nichts habt.“","feedback":"Ein Rückzug wirkt hier wie ein Zugeständnis. Die Ausstiegs-Option wäre erst später sinnvoll, wenn eine Klärung nicht mehr möglich ist.","score":-1,"nextStepId":"step-fail"}]},"step-2":{"id":"step-2","speaker":"Anon_Falke","speech":"„Genau: Keine Studie widerlegt es, und die Schulmedizin weiß selbst nicht, was meine Beschwerden auslöst. Wenn die Experten ratlos sind, warum soll ich dann nicht dem vertrauen, was bei mir hilft?“","options":[{"text":"„Danke, jetzt verstehe ich dich besser. Wenn du eine Skala von 0 bis 100 nimmst: Wie sicher bist du dir, dass das Mittel wirkt?“","style":"sokratisch","reaction":"„Hm. Neunzig, würde ich sagen. Mindestens. Ich merke ja, was bei mir passiert.“","feedback":"Stark! Die 0-100-Skala macht aus Ja/Nein ein Spektrum. Wer eine Zahl nennt, hat sich schon ein Stück auf Selbstprüfung eingelassen.","score":3,"nextStepId":"step-3"},{"text":"„Die Ratlosigkeit der Experten ist kein Beleg für dein Mittel. Aus einer Wissenslücke folgt nicht, dass deine Lieblingserklärung stimmt. Das ist das Argument aus Unwissenheit.“","style":"frontal","reaction":"„Boah, jetzt bitte nicht das Fachwörterbuch. Ich habe nur gesagt, was bei mir hilft. Mit dir kann man echt nicht reden.“","feedback":"Inhaltlich richtig, aber als fertige Belehrung. Die Person fühlt sich korrigiert statt eingeladen, selbst nachzudenken.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Dann wirst du auch Homöopathie, Reiki und die Mondphasen-Kur noch unbedingt wollen, bei diesem Beweisstandard! Warum hören wir nicht gleich bei Einhörnern auf?“","style":"sarkastisch","reaction":"„Ach, jetzt wirst du lustig auf meine Kosten. Dann macht’s halt gut. Ich diskutiere nicht mit Leuten, die sich über andere lustig machen.“","feedback":"Der Spott trifft den Menschen, nicht die Behauptung. „Seziert wird die Behauptung, nicht der Mensch“: Das Gespräch ist damit beendet.","score":-2,"nextStepId":"step-fail"}]},"step-3":{"id":"step-3","speaker":"Anon_Falke","speech":"„Neunzig, ja. Meine Erfahrung ist da eindeutig. Und ich sage dir: Solange du nicht das Gegenteil beweist, bleibt das so. Ich brauche keine Studien, ich kenne meinen Körper.“","options":[{"text":"„Persönliche Erfahrung ist also deine Methode, verstehe. Könnte die Besserung auch andere Gründe haben, etwa Placebo oder dass es von allein besser wurde? Wie fände man das heraus?“","style":"sokratisch","reaction":"„Hm... von allein besser? Möglich wäre es schon. Aber woher soll ich das wissen, wenn ich nur eine Packung habe?“","feedback":"Treffer! Die Methode wird benannt und ihre Grenzen werden gemeinsam geprüft: Alternative Erklärungen und die Frage nach einem verlässlicheren Test. Genau hier entsteht ein kleiner Zweifel.","score":3,"nextStepId":"step-4-success"},{"text":"„Wenn du so sicher bist, kannst du bestimmt auch erklären, wie das Mittel wirkt. Los, erklär es uns allen hier!“","style":"frontal","reaction":"„Das muss ich nicht! Der Beweis ist, dass es wirkt. Du kannst ja nicht einmal erklären, warum es NICHT wirkt!“","feedback":"Das klingt wie ein Kreuzverhör. Statt zur Selbstprüfung einzuladen, setzt du ihn unter Druck, und er dreht die Frage direkt zurück.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Gut, ich merke, wir drehen uns im Kreis. Darf ich dir noch eine letzte Frage stellen, bevor wir’s gut sein lassen: Was würde dich überzeugen, dass es nicht wirkt?“","style":"ausstieg","reaction":"„Gar nichts, ehrlich gesagt. Ich weiß ja, dass es wirkt. Und jetzt willst du mir das wohl ausreden, oder?“","feedback":"Brauchbar: Die Frage nach dem, was ihn umstimmen würde, öffnet eine Tür, aber die Verbindung zu seiner Methode bleibt noch offen.","score":1,"nextStepId":"step-3-struggle"}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Anon_Falke","speech":"„Ich seh schon, du willst mir mein Mittel ausreden. Meine Erfahrung zählt für mich, und fertig. Was willst du von mir?“","options":[{"text":"„Nichts weiter, ich wollte nur verstehen, wie du darauf kommst. Danke dir. Mein Gedanke dazu: Fehlende Gegenbeweise machen eine Behauptung noch nicht wahr. Alles Gute!“","style":"deeskalierend","reaction":"„Hm. Na gut. Schönen Abend noch.“","feedback":"Guter Abschluss: Das Gespräch endet positiv, ein kleiner Impuls bleibt stehen. Der Stein des Zweifels ist zumindest ins Rollen gekommen.","score":2},{"text":"„Genau, du kennst dich und deinen Körper, und ich keinen von beiden. Dann glaub eben, was du willst, mich geht das nichts an, und ich schreibe dazu auch nichts mehr.“","style":"sarkastisch","reaction":"„Danke für nichts. Habe ich’s doch gewusst: Ihr habt keine Argumente!“","feedback":"Der Sarkasmus gibt ihm genau das Gefühl, recht zu haben. Das Gespräch endet, ohne dass ein Gedanke hängen bleibt.","score":-1}]},"step-4-success":{"id":"step-4-success","speaker":"Anon_Falke","speech":"„Na ja... einen Test mit Vergleich, ob es besser wird als ohne, das könnte man machen, klar. Aber wenn der dann sagt, es wirkt nicht, was dann?“","options":[{"text":"„Das ist eine ehrliche Frage. Ich würde sagen: Dann hätten wir etwas gelernt, statt nur zu hoffen. Eine fehlende Widerlegung ist noch kein Beleg. Aber das entscheidest du selbst. Danke fürs Gespräch, das war wirklich aufschlussreich.“","style":"sokratisch","reaction":"„Hm. Danke, dass du nicht blöd geworden bist. Ich überleg’s mir. Vielleicht frage ich meinen Arzt mal.“","feedback":"Mission gelungen! Du hast nicht „Du liegst falsch“ gesagt, sondern ihn selbst die Zuverlässigkeit seiner Methode prüfen lassen. Die Beziehung ist heil, der Zweifel gesät.","score":3}]},"step-fail":{"id":"step-fail","speaker":"Anon_Falke","speech":"„Siehst du, genau wie ich dachte: Keine Argumente, nur Spott und Ausreden. Mein Mittel bleibt, wo es ist.“ *postet noch drei Zustimmungs-Emojis unter den eigenen Kommentar*","options":[{"text":"Ende: Anon_Falke fühlt sich bestätigt, weil die Stimmung gekippt ist. Wer angegriffen oder ausgelacht wird, verteidigt nicht mehr eine Behauptung, sondern sich selbst.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst fragen, dann beurteilen: Was ist die Methode hinter der Überzeugung?","feedback":"Street Epistemology greift nicht die Schlussfolgerung an, sondern untersucht das Verfahren. Wer neugierig nach Methode und Sicherheit fragt, erreicht mehr als mit einem schnellen Punktsieg.","score":0}]}},"status":"entwurf","familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","stufe":3,"kurz":"Dass niemand eine Behauptung widerlegt hat, belegt sie nicht: Die Beweislast trägt, wer behauptet, und eine Wissenslücke darf nicht mit der Lieblingserklärung gefüllt werden. Eine Besserung nach einem Mittel kann auch andere Gründe haben.","prueffrage":"Wer müsste hier etwas belegen, und welcher Vergleich mit und ohne das Mittel könnte zeigen, ob die Besserung wirklich am Mittel liegt?","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies (Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Street Epistemology International: Street Epistemology (Startseite, Selbstdarstellung der Methode)","oeffentlich":true,"url":"https://streetepistemology.com/","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"scen-klassenarbeit-schuld-lehrer","title":"Jonas und die ungerechte Klassenarbeit","subtitle":"Der Lehrer hat mich auf dem Kieker, geübt mit aktivem Zuhören","character":"Jonas","avatar":"📝","context":"Dein Kumpel Jonas bekommt in der Pause seine Mathe-Klassenarbeit zurück: eine Fünf. Er ist wütend und überzeugt, dass sein Lehrer ihn nicht leiden kann und deshalb extra streng bewertet hat. Du merkst, dass dahinter mehr stecken könnte als die Note.","goal":"Hör Jonas aktiv zu, statt ihn zu belehren, und hilf ihm, selbst nach den Umständen hinter der Note zu fragen.","bereich":"Schule","laenge":"kurz","ton":"ernst","bestehenAb":4,"lektion":"Aktives Zuhören heißt, erst zu verstehen und dann zu antworten: Paraphrasieren, Gefühle benennen und offene Fragen öffnen mehr Türen als jedes Gegenargument. Jonas erklärt die strenge Note mit dem Charakter des Lehrers („der kann mich nicht leiden“) und übersieht die Umstände, etwa dass für alle dieselben Maßstäbe gelten oder dass er am Abend vorher kaum lernen konnte. Das Verhalten anderer mit ihrem Charakter statt mit den Umständen zu erklären, ist ein typisches Muster des Attributionsfehlers; hinzu kommt, dass man die Ursache für das eigene Scheitern oft zuerst bei anderen sucht. Wer zuerst zuhört und dann gemeinsam nach den Umständen fragt, kommt dem Kern näher als mit Widerspruch oder Zustimmung.","toolRef":"H.2.3","faktenRef":"B.8","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Jonas","speech":"„Eine Fünf! Schon wieder! Der Herr Weber hat mich auf dem Kieker, das merkt doch jeder. Der kann mich einfach nicht leiden und bewertet mich deshalb extra hart. Das ist so unfair!“","options":[{"text":"„Ach komm, Jonas, das bildest du dir ein. Lehrer haben besseres zu tun, als sich Schüler auszusuchen. Du hast wahrscheinlich einfach zu wenig gelernt.“","style":"frontal","reaction":"„Siehst du, genau das meine ich! Alle halten zu ihm, und mich hört keiner an! Du bist auch nicht besser als die anderen.“ *verschränkt die Arme*","feedback":"Frontalangriff! Du wischst sein Gefühl weg („das bildest du dir ein“) und lieferst gleich dein eigenes Urteil, bevor du ihm zugehört hast. Jonas fühlt sich nicht gehört und macht dicht.","score":-2,"nextStepId":"step-fail"},{"text":"„Ich höre, wie sauer und enttäuscht du bist. Wenn ich dich richtig verstehe, fühlst du dich von Herrn Weber ungerecht behandelt. Erzähl mal: Woran machst du das fest?“","style":"deeskalierend","reaction":"„*atmet durch* Na ja... er ruft mich nie dran, wenn ich mich melde. Und bei der Rückgabe hat er so komisch geguckt.“","feedback":"Stark! Paraphrasieren, Gefühl benennen und eine offene Frage: Jonas fühlt sich gehört und öffnet sich. Du sammelst, was hinter der Überzeugung steckt, ohne sie zu bestätigen.","score":3,"nextStepId":"step-2"},{"text":"„Typisch Lehrer! Der hat bei mir letztes Jahr auch so getan. Der gehört echt mal zur Schulleitung gemeldet. Dem würde ich was erzählen!“","style":"sarkastisch","reaction":"„Ja, genau! Endlich versteht mich mal einer! Wir müssen was unternehmen, der ist echt unmöglich!“","feedback":"Du holst Jonas zwar ab, bestätigst aber ungeprüft seinen Charakterverdacht gegen den Lehrer. Du verstärkst die Schuldzuweisung, statt zuzuhören und nachzufragen.","score":-1,"nextStepId":"step-2-struggle"}]},"step-2":{"id":"step-2","speaker":"Jonas","speech":"„Und ehrlich gesagt... ich war nicht ganz unvorbereitet. Aber an dem Abend davor war bei uns zu Hause alles drunter und drüber, meine Eltern haben sich gestritten. Ich konnte nicht richtig lernen. Aber das sieht ja keiner!“","options":[{"text":"„Das klingt, als wäre der Abend vorher richtig belastend gewesen. Die Note hängt für dich also auch mit dem Abend zusammen, nicht nur mit Herrn Weber. Was hat die Fünf am meisten beeinflusst?“","style":"sokratisch","reaction":"„Hm... ehrlich gesagt der Abend, glaube ich. Ich war einfach total durch den Wind. Mit Herrn Weber hat das vielleicht gar nichts zu tun.“","feedback":"Meisterhaft! Du paraphrasierst, benennst das Gefühl und stellst eine offene Frage. Jonas entdeckt selbst einen Umstand hinter der Note, statt sie allein dem Charakter des Lehrers zuzuschreiben.","score":3,"nextStepId":"step-3-success"},{"text":"„Dann hast du doch einen guten Grund! Geh zu Herrn Weber und sag ihm, dass die Arbeit nicht zählen darf, weil bei dir zu Hause Stress war. Das muss er verstehen.“","style":"frontal","reaction":"„Echt? Aber wenn der mir dann wieder nicht glaubt? Der hat doch eh was gegen mich... Ach, ich weiß nicht.“","feedback":"Gut gemeint, aber du gibst einen Ratschlag, bevor du verstanden hast, was Jonas braucht (erst verstehen, dann antworten). Jonas fühlt sich überrollt und wird wieder unsicher.","score":0,"nextStepId":"step-2-struggle"},{"text":"„Mein Gott, das mit deinen Eltern tut mir leid, aber Streit haben andere auch. Deswegen schreiben die nicht gleich eine Fünf. Du suchst nur Ausreden, Jonas.“","style":"frontal","reaction":"„Ausreden?! Du hast keine Ahnung, wie es bei mir zu Hause ist! Lass mich einfach in Ruhe!“","feedback":"Schwach. Du wertest seine Lage ab und zeigst keine Empathie. Aktives Zuhören hätte das Gefühl anerkannt, statt es zu beurteilen.","score":-2,"nextStepId":"step-fail"}]},"step-3-success":{"id":"step-3-success","speaker":"Jonas","speech":"„Weißt du was, ich hab den Weber vorschnell zum Bösewicht gemacht. Er hat die Arbeit ja wahrscheinlich bei allen gleich bewertet. Ich will mit ihm reden, ob ich die Arbeit nachschreiben darf. Kommst du mit, falls ich mich nicht traue?“","options":[{"text":"„Klar, ich komme mit. Und es spricht für dich, dass du das jetzt von dir aus angehst.“","style":"deeskalierend","reaction":"„Danke. Das fühlt sich gerade echt besser an als vorhin. Wollen wir gleich nach der Pause zu ihm gehen?“","feedback":"Mission gelungen! Aktives Zuhören hat Jonas geholfen, nach den Umständen zu fragen statt nach einem Schuldigen. Du bist dabei geblieben, ohne zu belehren.","score":3},{"text":"„Ich bin da zwar skeptisch, ob der überhaupt zuhört, aber probier es halt.“","style":"sarkastisch","reaction":"„Hm. Wenn du schon skeptisch bist, will ich vielleicht doch nicht hin... Ach, lass mal.“","feedback":"Du nimmst Jonas den frisch gewonnenen Mut, weil du selbst wieder die Charakter-Brille aufsetzt. Schade, das Zuhören hatte schon gewirkt.","score":-1}]},"step-2-struggle":{"id":"step-2-struggle","speaker":"Jonas","speech":"„Ich weiß auch nicht. Vielleicht liegt es doch an mir, oder an ihm. Keine Ahnung. Mir schwirrt der Kopf.“","options":[{"text":"„Das kann ich verstehen, das war heute viel. Magst du nach der Schule mit mir was essen gehen und in Ruhe darüber reden?“","style":"deeskalierend","reaction":"„Ja... das wäre gut. Danke, dass du nicht gleich urteilst.“","feedback":"Guter Rückzug: Du schützt die Beziehung und bietest ein ruhiges Gespräch an. Die Sachfrage bleibt offen, aber die Tür ist es auch.","score":2},{"text":"„Dann bleibt halt alles, wie es ist. Mit einer Fünf muss man leben, so ist das eben, und es nützt nichts, sich darüber aufzuregen.“","style":"sarkastisch","reaction":"„Danke für nichts. Ich geh dann mal.“ *dreht sich weg*","feedback":"Du lässt Jonas allein mit seinem Frust und beendest das Gespräch abweisend. Aktives Zuhören wäre jetzt dran gewesen.","score":-1}]},"step-fail":{"id":"step-fail","speaker":"Jonas","speech":"„Ihr hört mir alle nicht zu. Dann bleibe ich eben dabei: Der Weber hat was gegen mich, und ihr seid alle blind.“ *geht*","options":[{"text":"Ende: Jonas fühlt sich nicht gehört und hält jetzt noch fester an seiner Überzeugung fest. Bevor man widerspricht, muss man erst verstehen.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst paraphrasieren und das Gefühl benennen, dann erst über Gründe reden.","feedback":"Frag dich: Wollte ich Jonas recht geben oder ihn verstehen? Aktives Zuhören heißt, erst zu verstehen, bevor man antwortet.","score":0}]}},"status":"entwurf","familie":"umstaende-vor-absicht","fertigkeit":"F2","stufe":2,"kurz":"Wer eine schlechte Note allein dem Charakter des Lehrers zuschreibt, übersieht leicht die Umstände, etwa gleiche Maßstäbe für alle oder einen belastenden Abend vorher. Erst zuhören, paraphrasieren und offen fragen hilft, diese Umstände selbst zu entdecken.","prueffrage":"Welche Noten haben die anderen bei derselben Arbeit bekommen, und was war am Abend vor der Arbeit los?","quellen":[{"typ":"url","kurz":"Agency for Toxic Substances and Disease Registry (ATSDR/CDC): A Guide to Active Listening (Community Engagement Playbook)","oeffentlich":true,"url":"https://www.atsdr.cdc.gov/community-engagement-playbook/media/pdfs/2024/09/A-Guide-to-Active-Listening.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The correspondence bias. Psychological Bulletin 117(1), Abstract bei PubMed (DOI 10.1037/0033-2909.117.1.21)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/7870861/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Ross, L.; Anderson, C. A. (1982): Shortcomings in the attribution process. In: Kahneman/Slovic/Tversky (Hrsg.): Judgment under Uncertainty, Kap. 9 (aus Landkarte B.8)","oeffentlich":false}],"thema":"Zusammenleben"},{"id":"scen-schwimmen-nach-essen","title":"Omas Badeverbot","subtitle":"Nach dem Essen nicht schwimmen, geübt mit intellektueller Barmherzigkeit","character":"Oma Hilde","avatar":"🏊","context":"Beim Familienausflug an den See hast du gerade Kartoffelsalat gegessen und willst ins Wasser. Oma Hilde hält dich am Arm fest: „Nach dem Essen schwimmt man nicht, sonst bekommst du Krämpfe und gehst unter!“ Sie meint es völlig ernst, und die halbe Familie schaut zu.","goal":"Nimm Omas Sorge ernst, ohne ihre Regel ungeprüft zu bestätigen, und lenke das Gespräch mit sokratischen Fragen darauf, woher dieses Wissen stammt und wie oft so etwas wirklich passiert.","bereich":"Familie","laenge":"kurz","ton":"heiter","bestehenAb":4,"lektion":"Eine Warnung, die uns seit der Kindheit begleitet, fühlt sich wie gesichertes Wissen an: Was man oft hört, wirkt vertraut und dadurch glaubwürdig, und ein einziger eindrücklicher Fall bleibt stärker im Kopf als viele harmlose (Verfügbarkeitsheuristik). Belege dafür, dass Schwimmen nach dem Essen das Risiko zu ertrinken erhöht, fand eine Literaturprüfung für die Internationale Lebensrettungsföderation nicht. Wer wie Oma Hilde aus Fürsorge warnt, wird am besten erreicht, wenn man zuerst ihre gute Absicht würdigt und erst dann gemeinsam fragt, woher das Wissen kommt. Geprüft wird die Behauptung, nicht die Oma.","toolRef":"H.1.3","faktenRef":"B.3","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Oma Hilde","speech":"„Halt, mein Junge! Nicht ins Wasser! Du hast gerade erst gegessen. Der Sohn von der Nachbarin hat damals auch nach dem Essen gebadet, und dann hat es ihn im Wasser gepackt, so ein Krampf! Das ist doch bekannt: Eine Stunde warten, mindestens!“","options":[{"text":"„Oma, das ist ein alter Mythos, den jeder Erwachsene mal erzählt bekommen hat. Das ist völlig überholt, ich gehe jetzt schwimmen.“","style":"frontal","reaction":"„Überholt?! Ich habe vier Kinder großgezogen, und keins ist ertrunken! Aber bitte, wenn du es besser weißt als die ganze Familie...“ *verschränkt die Arme und wendet sich ab*","feedback":"Frontal und von oben herab: Oma hört „Du bist von gestern“ und nicht ihre eigene Sorge. Ohne Anerkennung der guten Absicht ist sie für Gegenargumente zu.","score":-2,"nextStepId":"step-fail"},{"text":"„Du hast ja recht, Oma, der Kartoffelsalat war riesig. Ich warte die Stunde, setze mich zu dir, und wir spielen Karten.“","style":"ausstieg","reaction":"„Na siehst du, vernünftig! Man kann nicht vorsichtig genug sein. Das habe ich schon deiner Mutter immer gesagt.“","feedback":"Der Frieden ist gesichert, aber Omas Regel wird stillschweigend bestätigt. Du bleibst beziehungsfreundlich, ohne die Sachfrage anzufassen.","score":0,"nextStepId":"step-struggle"},{"text":"„Oma, ich merke, wie sehr du dich um mich sorgst, und das bedeutet mir was. Magst du mir erzählen, was damals bei dem Sohn der Nachbarin passiert ist?“","style":"sokratisch","reaction":"„*wird weicher* Das war so ein heißer Tag, und der Junge ist weit rausgeschwommen. Plötzlich war er unter Wasser, die Mutter hat geschrien... Das vergesse ich nie.“","feedback":"Exzellent! Intellektuelle Barmherzigkeit: Du gehst von ihrem besten Motiv aus, nämlich Fürsorge, und lässt sie erzählen. Das lebhafte Bild hinter der Überzeugung kommt auf den Tisch (Verfügbarkeitsheuristik).","score":3,"nextStepId":"step-2"}]},"step-2":{"id":"step-2","speaker":"Oma Hilde","speech":"„Seitdem ist mir das ein Gräuel. Und alle sagen es doch: die Nachbarn, meine Schwester, früher sogar der Bademeister. Da muss doch was dran sein, oder?“","options":[{"text":"„Dass alle es sagen, beweist gar nichts, Oma. Die haben das auch nur voneinander. Das ist ein klassischer Fehlschluss, schau dir mal die Studien an, dann siehst du es selbst.“","style":"frontal","reaction":"„Studien, Studien! Ich brauche keine Studien, ich habe Augen im Kopf! Und mit Fremdwörtern kommst du mir nicht.“","feedback":"Die Richtung stimmt, aber der Ton nicht: Fachbegriffe und Belehrung lassen Oma in die Defensive gehen, und die Sorge hinter ihrer Überzeugung bleibt unbeachtet.","score":-1,"nextStepId":"step-fail"},{"text":"„Das war bestimmt furchtbar mitanzusehen. Ich frage mich: Wie oft ist das eigentlich passiert? Dieser eine Fall bleibt uns im Kopf. Aber wie viele gehen jeden Sommer nach dem Essen baden, und es passiert nichts?“","style":"sokratisch","reaction":"„Hmm... *überlegt* Ich selbst bin früher nach dem Mittagessen oft in den Fluss gesprungen. Und die Kinder auch, wenn ich nicht hingeschaut habe. Passiert ist nie was.“","feedback":"Sehr gut! Du würdigst das Erlebnis und lenkst sanft auf die Frage nach der Häufigkeit. Ein einzelnes, bildstarkes Ereignis wirkt wichtiger, als es statistisch sein muss. Oma kommt mit eigenen Erfahrungen selbst darauf.","score":3,"nextStepId":"step-success"},{"text":"„Wahrscheinlich ist da wirklich was dran, Oma. Aber mir ist heiß, könnten wir nicht einfach bis zum Knietiefen reingehen? Das ist doch dann kein richtiges Schwimmen.“","style":"humorvoll","reaction":"„*lacht* Du bist mir einer! Na gut, knietief, aber ich behalte dich im Auge!“","feedback":"Charmant und beziehungswahrend, aber Omas Regel wird nicht angefasst. Als Kompromiss in Ordnung, als Aufklärung ein Umweg.","score":0,"nextStepId":"step-struggle"}]},"step-success":{"id":"step-success","speaker":"Oma Hilde","speech":"„Weißt du was? Vielleicht habe ich einfach nur dieses eine Mal so stark im Kopf behalten und alles andere vergessen. Trotzdem: Schwimm nicht zu weit raus, ich habe doch Angst um dich!“","options":[{"text":"„Das mache ich, Oma, versprochen. Und danke, dass du so auf mich aufpasst. Kommst du mit ans Ufer und winkst mir zu?“","style":"deeskalierend","reaction":"„Aber gern, Junge! Ich setze mich in den Schatten und winke. Und pass auf dich auf!“","feedback":"Mission gelungen! Du hast ihre Fürsorge gewürdigt, und sie hat ihre Gewissheit selbst hinterfragt. Die Beziehung ist heil, und die Warnung hat ihren Schrecken verloren.","score":3}]},"step-struggle":{"id":"step-struggle","speaker":"Oma Hilde","speech":"„Hauptsache, dir passiert nichts. Ich bin doch nur eine alte Frau, die sich Sorgen macht.“","options":[{"text":"„Du bist die beste Aufpasserin der Familie, Oma. Beim nächsten Ausflug erzählst du mir noch mal die Geschichte von damals, und dann reden wir in Ruhe darüber, einverstanden?“","style":"deeskalierend","reaction":"„*lächelt* Einverstanden, Junge. Und jetzt iss erst mal ein Stück Kuchen.“","feedback":"Ein freundlicher Ausstieg: Die Beziehung bleibt geschützt, die Tür für ein späteres, ruhiges Gespräch steht offen. Die Sachfrage bleibt aber vorerst unberührt.","score":2}]},"step-fail":{"id":"step-fail","speaker":"Oma Hilde","speech":"„Mach doch, was du willst. Ich sage nichts mehr. Aber wenn was passiert, hast du es dir selbst zuzuschreiben!“ *wendet sich beleidigt ab*","options":[{"text":"Ende: Oma fühlt sich belehrt und nicht gehört, und ihre Überzeugung sitzt fester als zuvor. Wer die Sorge nicht würdigt, erreicht den Inhalt nicht.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst ihr Motiv anerkennen, dann erst fragen.","feedback":"Intellektuelle Barmherzigkeit heißt: von der besten Absicht ausgehen. Oma will dich schützen. Sie ist nicht dumm, ihr Bild im Kopf ist nur sehr lebhaft.","score":0}]}},"status":"entwurf","familie":"basisrate-beachten","fertigkeit":"F4","stufe":1,"kurz":"Eine Warnung, die seit der Kindheit wiederholt wird, fühlt sich wie gesichertes Wissen an, auch wenn vor allem Wiederholung und ein eindrückliches Bild dahinterstehen. Wer zuerst die fürsorgliche Absicht würdigt, kann danach gemeinsam fragen, woher das Wissen stammt.","prueffrage":"Wie oft sind Menschen im eigenen Umfeld nach dem Essen schwimmen gegangen, und wie oft ist dabei tatsächlich etwas passiert?","quellen":[{"typ":"url","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), Abstract bei PubMed","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/17835457/","abruf":"2026-10-12"},{"typ":"url","kurz":"International Life Saving Federation: Medical Position Statement MPS-18 „Eating before Swimming“ (Literaturprüfung L. Quan, 2013)","oeffentlich":true,"url":"https://www.ilsf.org/wp-content/uploads/2018/11/MPS-18-2014-Eating-before-Swimming.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Malpas, J.: Donald Davidson. Stanford Encyclopedia of Philosophy (Fassung 28.04.2023), Abschnitt 3.3 (aus Landkarte H.1.3, im Belegregister)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/"}],"thema":"Gesundheit"},{"id":"scen-fieber-senken-wahn","title":"Mutter Claudias Fieberpanik","subtitle":"Fieber als Feind, geübt mit der Empathie-Matrix","character":"Claudia","avatar":"🌡️","context":"Deine Freundin Claudia ruft dich abends an. Ihr kleiner Sohn hat 38,6 Grad Fieber, und sie ist überzeugt, dass sie es sofort drücken muss, sonst nehme er Schaden. Sie klingt panisch und hat schon die Fieberzäpfchen in der Hand.","goal":"Nimm Claudia ihre Panik mit mitfühlender Empathie und lenke den Blick auf das, was das Fieber im Körper tatsächlich tut.","bereich":"Gesundheit","laenge":"mittel","ton":"ernst","bestehenAb":6,"lektion":"Mitfühlende Empathie heißt: Claudias Angst verstehen, kurz spiegeln und dann ruhig Halt geben, ohne die Panik zu übernehmen. Erst dann kann sie hören, dass Fieber Teil der Abwehrreaktion des Körpers ist, gleichsam ein Alarm, mit dem das Immunsystem Verstärkung ruft, und dass meist mehr zählt, wie es dem Kind insgesamt geht, als die eine Zahl auf dem Thermometer. Bei Warnzeichen, bei Säuglingen oder wenn sie unsicher ist, gehört die Frage zur Kinderärztin. Du stellst dich mit einer Frage statt mit einem Vortrag an ihre Seite.","toolRef":"H.1.6","faktenRef":"C.4.3","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Claudia","speech":"„Luca glüht, 38,6! Ich muss das sofort runterbekommen, sonst nimmt er Schaden, das weiß man doch! Ich habe solche Angst, ich weiß nicht, was ich zuerst tun soll!“","options":[{"text":"„Ach Claudia, jetzt hör doch auf mit der Panik. Fieber ist völlig normal, das ist reine Hysterie, was du da machst. Wie kann man sich nur so reinsteigern?“","style":"frontal","reaction":"„Hysterie?! Du hast leicht reden, es ist ja nicht dein Kind! Ich will einfach nur das Richtige tun!“","feedback":"Frontalangriff! Du wertest die Person ab, statt ihre Angst zu verstehen. So entsteht kein Anker, nur ein Gegner. Seziert wird die Behauptung, nicht der Mensch.","score":-2,"nextStepId":"step-fail"},{"text":"„Ich höre, wie viel Angst du um Luca hast, und das ist total verständlich. Atme einmal durch, ich bin bei dir. Wie geht es ihm denn gerade, wie wirkt er auf dich?“","style":"deeskalierend","reaction":"„*atmet zitternd aus* Danke... Er ist müde und quengelig, aber er hat vorhin noch einen Schluck Wasser getrunken. Ich dachte nur, wenn das Fieber weiter steigt...“","feedback":"Exzellent! Mitfühlende Empathie: Du spiegelst kurz ihr Gefühl, bleibst selbst ruhig und lenkst mit einer offenen Frage auf das Kind. Die emotionale Temperatur sinkt.","score":3,"nextStepId":"step-2"},{"text":"„Oh Gott, 38,6! Das ist ja furchtbar! Gib ihm sofort alles, was du da hast, und ruf sicherheitshalber den Notarzt! Ich hätte genauso Panik!“","style":"affektiv","reaction":"„Siehst du, du siehst es auch so! Ich gebe ihm gleich die doppelte Menge, damit es schneller geht!“","feedback":"Affektiver Kollaps: Du übernimmst ihre Panik und verstärkst sie. Statt Anker der Ruhe zu sein, ertrinkst du mit der Ertrinkenden.","score":-1,"nextStepId":"step-panic"}]},"step-2":{"id":"step-2","speaker":"Claudia","speech":"„Aber Fieber ist doch gefährlich, oder? Meine Nachbarin sagt, über 38 darf man nie abwarten, das Kind muss sofort runter, sonst nimmt es Schaden. Das ist doch immer so, oder nicht?“","options":[{"text":"„Deine Nachbarin hat da keine Ahnung. Fieber ist nie gefährlich, du musst gar nichts tun. Leg ihn ins Bett und gut ist, das regelt sich von allein.“","style":"frontal","reaction":"„Gar nichts tun?! Du bist ja unverantwortlich! Ich sitze hier mit meinem glühenden Kind, und du tust, als wäre das nichts!“","feedback":"Zu schroff und zu pauschal. Du entwertest ihre Sorge und setzt selbst eine absolute Aussage dagegen. Das ist kalte Analyse statt mitfühlender Empathie.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Ich verstehe, warum du das glaubst, bei einem glühenden Kind will man einfach etwas tun. Lass uns kurz überlegen: Was macht der Körper eigentlich, wenn er Fieber bekommt? Wozu könnte das gut sein?“","style":"sokratisch","reaction":"„Wozu es gut sein soll...? Hm. Der Körper bekämpft ja irgendwas, oder? Aber ist das nicht trotzdem gefährlich?“","feedback":"Stark! Mitfühlende Empathie: Du verstehst ihr Gefühl, ohne die These zu übernehmen, und lädst mit einer offenen Frage zum gemeinsamen Nachdenken ein. Claudia beginnt selbst zu überlegen.","score":3,"nextStepId":"step-3-success"},{"text":"„Natürlich, sicher ist sicher. Gib ihm das Zäpfchen, dann beruhigst du dich auch endlich. Fiebersenken kann ja nicht schaden, und der Mythos hält sich ja nicht ohne Grund.“","style":"ausstieg","reaction":"„Genau, das sage ich ja! Ich gebe ihm gleich noch eins und wecke ihn nachts alle zwei Stunden zum Messen!“","feedback":"Du beruhigst Claudia kurzfristig, indem du die Behauptung bestätigst. Damit festigst du die Angst vor jedem Fieber, statt den Blick auf die Funktion des Fiebers zu lenken.","score":-2,"nextStepId":"step-fail"}]},"step-3-success":{"id":"step-3-success","speaker":"Claudia","speech":"„Moment... er hat ja vorgestern in der Kita so einen Infekt aufgeschnappt. Dann ist das Fieber vielleicht gar nicht der Feind, sondern der Körper, der sich wehrt? Aber woher weiß ich dann, wann es wirklich gefährlich wird?“","options":[{"text":"„Das ist genau die richtige Frage. Fieber ist Teil des Alarms, mit dem das Immunsystem Verstärkung ruft. Entscheidend ist der Verlauf: Wie wirkt Luca insgesamt, und wie entwickelt sich das?“","style":"sokratisch","reaction":"„Ach so, es geht also mehr darum, wie es ihm insgesamt geht, als um die eine Zahl auf dem Thermometer. Das beruhigt mich schon.“","feedback":"Treffend: Fieber gehört zum Alarm der angeborenen Abwehr, der Entzündungsreaktion, die mehr Truppen ruft. Du gibst Claudia einen sachlichen Anker, ohne sie zu belehren.","score":3,"nextStepId":"step-4"},{"text":"„Genau, Claudia, das Fieber ist total nützlich, du darfst es deshalb niemals senken, egal wie hoch es steigt oder wie schlecht es ihm geht. Das ist reine Natur.“","style":"frontal","reaction":"„Niemals? Auch nicht, wenn er richtig leidet? Jetzt bin ich wieder total verunsichert...“","feedback":"Du kippst ins gegenteilige Extrem und ersetzt ein Dogma durch ein anderes. Das verunsichert Claudia erneut, statt ihr Halt zu geben.","score":-1,"nextStepId":"step-4"},{"text":"„Gute Frage. Wir können zusammen überlegen, auf welche Anzeichen du achten möchtest. Und wenn du unsicher bist, ist dein Kinderarzt genau die richtige Anlaufstelle.“","style":"deeskalierend","reaction":"„Ja, stimmt. Dass ich jemanden anrufen kann, hilft mir irgendwie schon. Dann bin ich nicht allein mit der Entscheidung.“","feedback":"Solide: Du bleibst warm und verweist auf professionelle Hilfe. Du lieferst aber keinen inhaltlichen Anker zur Funktion des Fiebers, das Gespräch bleibt etwas an der Oberfläche.","score":1,"nextStepId":"step-4"}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Claudia","speech":"„Ich weiß nicht mehr, was ich glauben soll. Meine Nachbarin sagt das eine, du das andere... und Luca glüht trotzdem. Ich bin so durcheinander.“","options":[{"text":"„Das tut mir leid, ich war eben zu schroff. Du machst dir Sorgen, weil Luca dir wichtig ist, und das ist richtig so. Lass uns neu anfangen: Was beunruhigt dich am Fieber am meisten?“","style":"deeskalierend","reaction":"„*atmet auf* Danke... Ich glaube, ich hatte einfach Angst, etwas falsch zu machen. Wenn ich unsicher bin, rufe ich die Kinderärztin an.“","feedback":"Gelungene Reparatur: Du entschuldigst dich, nimmst das Gefühl ernst und fragst nach der konkreten Angst dahinter. So findet das Gespräch auf eine tragfähige Ebene zurück.","score":2,"nextStepId":"step-4"},{"text":"„Dann musst du eben selbst wissen, was du glaubst. Ich habe dir meine Meinung gesagt, mehr kann ich nicht tun. Alles Weitere liegt bei dir und deinem Kinderarzt.“","style":"ausstieg","reaction":"„Na toll. Dann bin ich eben allein damit. Ich muss jetzt auflegen.“","feedback":"Du ziehst dich zurück und lässt Claudia mit ihrer Verunsicherung allein. Der Kontakt bricht ab, bevor eine Brücke steht.","score":-1,"nextStepId":"step-fail"}]},"step-4":{"id":"step-4","speaker":"Claudia","speech":"„Okay, ich beruhige mich langsam. Aber sag ehrlich: Wenn das Immunsystem das Fieber selbst macht, ist es dann nicht trotzdem grausam, das Kind so leiden zu lassen? Ich kann ihn doch nicht einfach glühen lassen.“","options":[{"text":"„Du sollst ihn nicht leiden lassen. Du kannst ihm Nähe, Ruhe und Flüssigkeit geben und bewusst entscheiden, ob und wann du etwas gibst: nach ruhiger Beobachtung, nicht aus Angst vor der Zahl.“","style":"deeskalierend","reaction":"„Ja, das klingt vernünftig. Ich bleibe bei ihm, beobachte ihn und rufe die Kinderärztin an, wenn ich unsicher werde. Danke, dass du so ruhig geblieben bist.“","feedback":"Rund: Du gibst Handlungsfähigkeit zurück, ohne Dogmen. Mitfühlende Empathie: Du verstehst die Angst, übernimmst sie nicht und bietest Stabilität an.","score":3},{"text":"„Wenn du dich besser fühlst, gib ihm einfach alle paar Stunden etwas, damit er unter 38 bleibt. Dann ist die Sache für dich erledigt und du kannst schlafen.“","style":"ausstieg","reaction":"„Gut, dann mache ich das so. Bis morgen Früh dann, ich stelle mir den Wecker alle drei Stunden.“","feedback":"Du bleibst bei der Zahl und stützt damit die Grundidee, Fieber sei stets zu bekämpfen. Der Kern der Sorge, die Angst vor der Zahl, wird nicht angesprochen.","score":0},{"text":"„Dann lies halt mal nach, was das Immunsystem macht, und google nicht mehr nachts. Die Angst kommt von deiner mangelnden Bildung, das sage ich dir als gute Freundin.“","style":"sarkastisch","reaction":"„Wow, danke. Ich dachte, du wolltest mir helfen. Ich lege jetzt auf.“","feedback":"Du wertest Claudia ab. „Seziert wird die Behauptung, nicht der Mensch“: Wer die Person angreift, verliert das Vertrauen, das jede Veränderung braucht.","score":-2}]},"step-fail":{"id":"step-fail","speaker":"Claudia","speech":"„Ich sehe schon, mit dir kann man darüber nicht reden. Ich mache jetzt, was ich für richtig halte, und frage dich nicht mehr.“ *legt auf*","options":[{"text":"Ende: Claudia fühlte sich nicht gehört und bleibt bei ihrer Angst vor jedem Fieber. Rechthaben und Helfen sind zweierlei.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst das Gefühl ernst nehmen, dann erst über Inhalte reden.","feedback":"Frage dich: Wollte ich Claudia beruhigen oder nur recht behalten? Die Empathie-Matrix ordnet die Reihenfolge: verstehen, kurz spiegeln, dann fürsorglich handeln.","score":0}]},"step-panic":{"id":"step-panic","speaker":"Claudia","speech":"„Du hast recht, jede Minute zählt! Ich messe jetzt alle zehn Minuten und ruf gleich noch meine Mutter an, die weiß bestimmt noch mehr Notmaßnahmen!“","options":[{"text":"Ende: Zwei Menschen in Panik helfen keinem Kind. Mitzittern ist nicht Mitfühlen.","style":"ausstieg","reaction":"Mitgefühl ja, Mitpanik nein: Wer mitzittert, kann nicht stützen.","feedback":"Mitfühlende Empathie heißt, das Gefühl zu verstehen, selbst ruhig zu bleiben und Claudia Halt zu geben, statt ihre Angst zu spiegeln und zu verstärken.","score":0}]}},"status":"entwurf","familie":"mechanismus-verlangen","fertigkeit":"F1","stufe":2,"kurz":"Fieber ist Teil der Abwehrreaktion des Körpers; wichtiger als die eine Zahl auf dem Thermometer ist, wie es dem Kind insgesamt geht und wie sich das entwickelt. Wer die Angst zuerst spiegelt und ruhig bleibt, wird eher gehört, und bei Unsicherheit hilft die Kinderärztin.","prueffrage":"Was sagt die Zahl auf dem Thermometer allein darüber, wie es dem Kind geht, und was zeigen sein Verhalten und der Verlauf?","quellen":[{"typ":"url","kurz":"IQWiG / gesundheitsinformation.de: Fieber bei Kindern (Stand 26.11.2025)","oeffentlich":true,"url":"https://www.gesundheitsinformation.de/fieber-bei-kindern.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Klimecki, O. M.; Leiberg, S.; Ricard, M.; Singer, T. (2014): Differential pattern of functional brain plasticity after compassion and empathy training. Social Cognitive and Affective Neuroscience 9(6) (PMC4040103)","oeffentlich":true,"doi":"10.1093/scan/nst060","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4040103/","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"scen-wlan-schlaf","title":"Gabis WLAN-Schlafstörung","subtitle":"Nocebo, geübt mit der Deeskalations-Matrix","character":"Gabi, Nachbarin","avatar":"📶","context":"Seit zwei Wochen steht im Nachbarhaus ein neuer Router. Gabi klingelt an deiner Tür, übermüdet und gereizt. Sie schläft schlecht, hat Kopfschmerzen und ist überzeugt, dass die Strahlung von nebenan schuld ist.","goal":"Bleib ruhig, nimm ihre Beschwerden ernst und führe das Gespräch mit Deeskalation und neugierigen Fragen zur Frage, ob die Erwartung eine Rolle spielen könnte.","bereich":"Nachbarschaft","laenge":"mittel","ton":"ernst","bestehenAb":6,"lektion":"Wer schlecht schläft und sich bedroht fühlt, braucht zuerst das Gefühl, ernst genommen zu werden, erst danach kommen Argumente an. Die Beschwerden sind real, aber in Blindversuchen erkennen Menschen nicht besser als der Zufall, ob ein Sender an ist; Symptome traten vermehrt auf, wenn die Exposition nur angekündigt war (Nocebo-Effekt). Deeskalation validiert das Gefühl, nicht den Inhalt, und hält so den Kanal für eine gemeinsame, überprüfbare Frage offen.","toolRef":"H.2.1","faktenRef":"C.4.5","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Gabi","speech":"„Ich sag's dir, seit die Leute nebenan diesen Router haben, kann ich nachts nicht mehr schlafen! Kopfschmerzen, Herzklopfen, alles! Das ist die Strahlung, da gibt's nichts zu diskutieren. Und ihr tut alle so, als wäre das harmlos!“","options":[{"text":"„Gabi, das ist Quatsch. Router sind nachweislich unschädlich, das ist nur Einbildung. Wahrscheinlich bist du einfach gestresst.“","style":"frontal","reaction":"„Einbildung?! Ich liege nachts wach und habe Schmerzen, und du erzählst mir, ich bilde mir das ein? Ihr nehmt einen überhaupt nicht ernst!“","feedback":"Frontalangriff: Gabis Beschwerden sind real, und „Einbildung“ klingt wie „Du lügst“. Die Deeskalations-Matrix verlangt, erst das Gefühl zu validieren, nicht den Inhalt abzuwehren.","score":-2,"nextStepId":"step-fail"},{"text":"„Das klingt furchtbar, wenn du nachts wachliegst und dein Herz klopft. Ich höre, wie sehr dich das belastet. Seit wann geht das so, und wann ist es am schlimmsten?“","style":"deeskalierend","reaction":"„*atmet hörbar durch* Endlich fragt mal jemand. Seit zwei Wochen. Abends im Bett ist es am schlimmsten, da denke ich nur noch an das Ding nebenan.“","feedback":"Stark: Du validierst das Gefühl, ohne die Strahlungsthese zu bestätigen (Technik 1 der Deeskalations-Matrix). Die Frage öffnet das Gespräch.","score":3,"nextStepId":"step-2"},{"text":"„Oh nein, dann geh ich gleich rüber und sag den Nachbarn, dass sie den Router ausmachen müssen! Das geht so nicht!“","style":"affektiv","reaction":"„Nein, lass das, das gibt nur Streit... Die lachen mich doch aus. Ich weiß gar nicht mehr, was ich machen soll.“","feedback":"Du übernimmst Gabis Deutung und stürzt dich in einen Nachbarschaftskonflikt. Das bestätigt die Annahme, statt sie zu prüfen, und löst keine Schlafstörung.","score":-1,"nextStepId":"step-3-struggle"}]},"step-2":{"id":"step-2","speaker":"Gabi","speech":"„Weißt du, ich hab im Internet gelesen, dass das bei vielen so ist. Elektrosensibel nennt man das. Und neulich kam ein Bericht, dass Handystrahlung Krebs macht. Ich hab richtig Angst, was das mit mir macht.“","options":[{"text":"„Ich kann verstehen, dass dich das beunruhigt. Lass uns gemeinsam schauen: Meinst du, wir könnten das irgendwie prüfen, ob es wirklich der Router ist, der dir den Schlaf raubt?“","style":"sokratisch","reaction":"„Prüfen? Wie denn, ich kann das Ding ja nicht abschalten, das gehört den Nachbarn... Aber ich bin neugierig, was meinst du?“","feedback":"Gut: Du zeigst Verständnis und lädst zu einer gemeinsamen Prüfung ein, ohne zu belehren. Das öffnet den Weg zu einem überprüfbaren Test.","score":2,"nextStepId":"step-3"},{"text":"„Es gibt Studien, die zeigen, dass Elektrosensibilität nur Nocebo ist. Das ist wissenschaftlich widerlegt, Gabi, da gibt es nichts zu diskutieren.“","style":"frontal","reaction":"„Widerlegt, widerlegt... Die Wissenschaft hat auch schon viel Falsches behauptet! Ihr wollt einen doch nur zum Schweigen bringen!“","feedback":"Die Studienlage spricht stark für Nocebo, doch „widerlegt, nichts zu diskutieren“ überzieht und kommt als Absage und Belehrung an. Gabi fühlt sich abgefertigt, die Emotion steigt wieder.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Das mit der Angst ist echt belastend. Magst du eine Tasse Tee mit mir trinken? Dann reden wir ganz in Ruhe, und danach schaust du, wie du dich fühlst.“","style":"deeskalierend","reaction":"„*zögert* ...Ja, gern. Ich hab das Gefühl, ich komme gerade gar nicht mehr runter. Tee klingt gut.“","feedback":"Fürsorglich und beruhigend, aber die Sachfrage bleibt unberührt. Die Tür bleibt offen, die Lösung noch fern.","score":1,"nextStepId":"step-3-struggle"}]},"step-3":{"id":"step-3","speaker":"Gabi","speech":"„Na gut. Ich bin ehrlich: Am Anfang hab ich nichts gemerkt. Erst als mir meine Schwester erzählt hat, dass ihre Freundin wegen so einem Router krank geworden ist, ging es los. Aber heißt das nicht, dass was dran sein muss?“","options":[{"text":"„Interessant, dass es erst nach dieser Geschichte losging. In Blindversuchen merken Betroffene nicht besser als per Zufall, ob ein Sender an ist. Könnte das bei dir mitspielen?“","style":"sokratisch","reaction":"„*nachdenklich* Du meinst, ich spüre das nur, weil ich damit rechne? Aber meine Kopfschmerzen sind doch echt... Das ist ja schon komisch, dass es genau damit anfing.“","feedback":"Sehr gut: Du führst die Rolle der Erwartung (Nocebo) als offene Frage ein, nicht als Urteil, und bestreitest nicht die Beschwerden selbst. Die Beschwerden sind real, die Deutung ist prüfbar.","score":3,"nextStepId":"step-4-success"},{"text":"„Ja, da kann schon was dran sein. Dann sollten wir die Nachbarn bitten, den Router wenigstens nachts abzuschalten, sicher ist sicher. Schaden kann das ja nicht.“","style":"affektiv","reaction":"„Ja, genau, nachts aus! ...Aber ehrlich, ob das was bringt? Ich bin so durcheinander.“","feedback":"Du bestätigst ungeprüft den vermuteten Zusammenhang und bremst eine Klärung aus. Sicher ist sicher klingt nett, verfestigt aber die Angst.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Es freut mich, dass du so ehrlich bist. Aber ehrlich gesagt: Es ist keine Strahlung, es ist Kopfsache. Das kann man nicht mehr anders sagen, und das weißt du auch.“","style":"frontal","reaction":"„Kopfsache?! Danke auch. Wenn du nur so etwas zu sagen hast, gehe ich lieber.“","feedback":"Der Kern („Kopfsache“) trifft Gabis Würde. Das Wort klingt nach „eingebildet“ und beendet das Gespräch, statt es zu öffnen.","score":-2,"nextStepId":"step-fail"}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Gabi","speech":"„Ich weiß nicht... ich bin gerade so müde und durcheinander. Eigentlich will ich nur schlafen können. Aber was soll ich bloß tun?“","options":[{"text":"„Das verstehe ich gut. Wie wäre es, wenn wir nicht heute alles klären? Schlaf erst einmal eine Nacht, und morgen schauen wir in Ruhe, was dir helfen könnte.“","style":"deeskalierend","reaction":"„Ja, das ist lieb von dir. Heute komme ich nicht mehr klar. Morgen vielleicht.“","feedback":"Strategische Auszeit (Technik 4): Das Gespräch wird nicht im Streit beendet, sondern bewusst vertagt. Respektvoll, aber die Sachklärung bleibt offen.","score":2},{"text":"„Dann ist es vielleicht das Beste, wenn du einfach einen Strahlenschutz-Baldachin fürs Bett kaufst. Der soll da helfen, und er kostet nicht viel.“","style":"ausstieg","reaction":"„Ach, so was gibt es? Mensch, danke, das klingt ja vernünftig! Das bestelle ich gleich.“","feedback":"Gut gemeint, aber du empfiehlst ein Scheinprodukt gegen etwas, das in Blindversuchen nicht nachweisbar ist, und stützt die Furcht, statt sie zu klären.","score":-2}]},"step-4-success":{"id":"step-4-success","speaker":"Gabi","speech":"„Okay... und wie finden wir raus, ob es wirklich der Router ist? Ich will nicht, dass du mir erzählst, ich bilde mir das ein. Aber ich will auch wissen, was los ist.“","options":[{"text":"„Wir bitten die Nachbarn, den Router ein paar Nächte mal an und mal aus zu lassen, ohne dass du weißt, wann was gilt. Du notierst jeden Morgen, wie du geschlafen hast. Sprich zusätzlich mit deiner Ärztin über den Schlaf.“","style":"sokratisch","reaction":"„Ohne zu wissen, wann er an ist... Das ist eigentlich eine gute Idee. Dann kann ich es nicht mit dem Kopf beeinflussen. Und zur Ärztin gehe ich ohnehin, die Kopfschmerzen sind ja auch echt.“","feedback":"Sehr gut: Ein einfacher Blindversuch macht die Frage überprüfbar, ohne Gabi bloßzustellen. Der Hinweis auf die Ärztin nimmt die Beschwerden ernst.","score":3},{"text":"„Am besten schaltest du dein eigenes WLAN auch aus und legst das Handy in den Flur. Dann merkst du ja, ob es besser wird, und kannst es mir erzählen, wenn du wieder besser schläfst.“","style":"humorvoll","reaction":"„Gute Idee, das mache ich! Obwohl... wenn es dann besser wird, weiß ich ja trotzdem nicht, ob es am Router lag, oder?“","feedback":"Nett gemeint und eine hilfreiche Beobachtung von Gabi selbst: Ohne Blindbedingung bleibt unklar, ob Erwartung oder Strahlung wirkt.","score":1},{"text":"„Das mit dem Test ist mir zu aufwendig. Probier einfach Ohrstöpsel und eine Schlafmaske, das hilft oft, kostet fast nichts und ist sofort erledigt, ganz ohne Nachbarn und Aufwand.“","style":"ausstieg","reaction":"„Naja, probieren kann ich es. Aber ob das die Ursache beseitigt... ich glaube eigentlich immer noch, es ist der Router.“","feedback":"Ein pragmatischer Tipp, aber du lässt die Gelegenheit zur Klärung ungenutzt. Der Mythos bleibt unangetastet.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Gabi","speech":"„Ich merke schon, mit dir kann man nicht darüber reden. Dann schlafe ich eben schlecht und kümmere mich selbst darum.“ *dreht sich um und geht*","options":[{"text":"„Gabi, warte, es tut mir leid. Ich wollte dich nicht abwimmeln. Komm, lass uns noch einmal in Ruhe reden.“","style":"deeskalierend","reaction":"„*bleibt stehen* Na gut... aber nur, wenn du mir wirklich zuhörst.“","feedback":"Gute Reparatur: Du entschuldigst dich und gibst der Beziehung eine zweite Chance. Die Sachklärung steht noch aus, aber das Gespräch ist gerettet.","score":1},{"text":"„Wie du meinst. Dann lass es eben. Ich habe dir nur die Wahrheit gesagt, und das ist nicht meine Schuld.“","style":"frontal","reaction":"„Wahrheit?! Du hast mir nur gezeigt, dass ich dir egal bin. Schönen Tag noch.“ *Tür knallt*","feedback":"Rechthaben statt Helfen: Du verlierst den Kontakt und bestärkst Gabi in ihrem Gefühl, nicht ernst genommen zu werden.","score":-2}]}},"status":"entwurf","familie":"fair-testen","fertigkeit":"F1","stufe":3,"kurz":"Beschwerden können echt sein, ohne dass die vermutete Ursache stimmt: In Blindversuchen erkennen Betroffene nicht besser als der Zufall, ob ein Sender an ist, und Symptome traten vermehrt auf, wenn ein Sender nur angekündigt war. Klären kann das ein verblindeter Test.","prueffrage":"Wann genau haben die Beschwerden angefangen: als der Router aufgestellt wurde oder als jemand von seiner schädlichen Wirkung erzählte?","quellen":[{"typ":"doi","kurz":"Bosch-Capblanch, X. u. a. (2024): The effects of radiofrequency electromagnetic fields exposure on human self-reported symptoms: A systematic review of human experimental studies. Environment International 187, 108612 (Abstract bei PubMed)","oeffentlich":true,"doi":"10.1016/j.envint.2024.108612","url":"https://pubmed.ncbi.nlm.nih.gov/38640611/","abruf":"2026-10-12"},{"typ":"url","kurz":"Rubin, G. J.; Das Munshi, J.; Wessely, S. (2005): Electromagnetic hypersensitivity: a systematic review of provocation studies. Psychosomatic Medicine 67(2), Abstract bei PubMed (DOI 10.1097/01.psy.0000155664.13300.64)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/15784787/","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"scen-spielplatz-fluorid","title":"Sabines Zahnpasta-Verdacht","subtitle":"Dosis und Angst, geübt mit aktivem Zuhören","character":"Sabine, Mutter vom Spielplatz","avatar":"🪥","context":"Du sitzt auf dem Spielplatz neben Sabine, deren Sohn mit deinem Kind im Sandkasten spielt. Beim Plaudern über Kinderzähne erzählt sie, dass sie nur noch fluoridfreie Zahnpasta kauft, weil Fluorid für sie ein Gift ist, das ihren Kindern schadet.","goal":"Höre Sabine so lange zu, bis du ihre eigentliche Sorge verstanden hast, und bring dann das Prinzip „Die Dosis macht’s“ ins Gespräch, ohne sie zu belehren.","bereich":"Gesundheit","laenge":"mittel","ton":"ernst","bestehenAb":6,"lektion":"Wer sofort widerlegt, hört nicht zu, und wer nicht zuhört, trifft die Sorge nicht. Erst durch Paraphrasieren und offene Fragen erfährst du, was Sabine antreibt, und kannst dann mit der Dosis-Wirkungs-Beziehung einordnen, dass nicht der Stoff allein, sondern die Menge über Nutzen und Schaden entscheidet. Die Behauptung wird geprüft, Sabine bleibt eine fürsorgliche Mutter mit nachvollziehbaren Gründen.","toolRef":"H.2.3","faktenRef":"C.4.7","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Sabine","speech":"„Ich kaufe für Lukas nur noch fluoridfreie Zahnpasta. Fluorid ist ein Gift, das steht doch überall. Ich lasse doch nicht jeden Morgen Gift in mein Kind rein!“","options":[{"text":"„Sabine, Fluorid ist doch kein Gift. Das ist ein alter Mythos. Zahnärzte empfehlen es seit Jahren, also schadest du Lukas eher, wenn du es weglässt.“","style":"frontal","reaction":"„Aha, jetzt bin ich also auch noch schuld, wenn Lukas Karies bekommt? Ich wollte doch nur das Beste für ihn!“ *verschränkt die Arme und rückt ein Stück ab*","feedback":"Frontal und belehrend: Du sendest nur, statt zuzuhören. Sabine hört Vorwurf statt Information und verteidigt ihre Haltung noch fester.","score":-2,"nextStepId":"step-fail"},{"text":"„Du möchtest Lukas schützen, das merkt man. Magst du mir erzählen, woher du das mit dem Gift hast und was dir dabei am meisten Sorgen macht?“","style":"sokratisch","reaction":"„Danke, dass du mich nicht gleich abbügelst. Also... ich habe in einer Elterngruppe gelesen, dass Fluorid sich im Körper anreichert und die Kinder krank macht.“","feedback":"Stark! Offene Fragen und eine Anerkennung der Fürsorge öffnen das Gespräch. Du erfährst Quelle und Sorge, ohne den Inhalt zu bestätigen.","score":3,"nextStepId":"step-2"},{"text":"„Oh je, wenn es Gift ist, sollten wir das alle sofort lassen! Ich schau gleich nach, was in der Zahnpasta meiner Tochter drin ist.“","style":"affektiv","reaction":"„Siehst du, du denkst genauso! Wir sollten uns zusammentun und die anderen Mütter warnen!“","feedback":"Du steigst in die Angst ein, statt sie zu verstehen. Die Sorge wird bestätigt, die Dosisfrage bleibt unberührt.","score":-1,"nextStepId":"step-panic"}]},"step-2":{"id":"step-2","speaker":"Sabine","speech":"„Da stand, dass schon winzige Mengen Fluorid reichen, um Kinder zu vergiften. Und auf der Tube steht sogar ein Warnhinweis: nur eine erbsengroße Menge, nur unter Aufsicht putzen, damit die Kinder nicht zu viel verschlucken! Wenn das kein Gift ist, was dann?“","options":[{"text":"„Wenn ich dich richtig verstehe, ist deine Hauptsorge, dass schon ganz kleine Mengen schaden und dass Lukas beim Putzen etwas verschlucken könnte. Habe ich das so richtig zusammengefasst?“","style":"sokratisch","reaction":"„Ja, genau! Er schluckt doch immer etwas runter, er ist ja erst vier. Und dann denke ich, jeden Tag ein bisschen Gift, das summiert sich.“","feedback":"Paraphrasieren zeigt, dass du zugehört hast, und lässt Sabine ihre Sorge selbst schärfen. Jetzt siehst du den Kern: Menge, Verschlucken, tägliche Wiederholung.","score":3,"nextStepId":"step-3"},{"text":"„Die Warnung auf der Tube ist reine Vorsicht, Sabine. Es gibt auch Warnungen auf Kaffeetassen, ohne dass Kaffee gleich Gift wäre.“","style":"frontal","reaction":"„Kaffee und Zahnpasta für Kinder kann man ja wohl kaum vergleichen. Du nimmst mich nicht ernst.“","feedback":"Sofortige Relativierung statt Verständnis: Der Vergleich hinkt, und Sabine fühlt sich abgewiegelt statt gehört.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Sehr, sehr viele Eltern machen sich da Gedanken. Man kann es als Mutter eben nie ganz richtig machen. Lass uns einfach schauen, dass die Kinder nachher noch ein Eis bekommen.“","style":"ausstieg","reaction":"„Ja, ein Eis ist schön... *wirkt unzufrieden* Aber die Zahnpasta bleibt trotzdem draußen.“","feedback":"Freundlich, aber du weichst aus. Die Sorge bleibt unverstanden und die Behauptung unberührt; für einen Gesprächsausstieg ist es hier noch zu früh.","score":0,"nextStepId":"step-3-struggle"}]},"step-3":{"id":"step-3","speaker":"Sabine","speech":"„Ich will einfach nicht, dass sich da jeden Tag etwas im Körper ansammelt. Gift ist doch Gift, oder nicht? Gibt es da irgendeine Grenze?“","options":[{"text":"„Gute Frage. Schon Paracelsus sagte: Alle Dinge sind Gift, allein die Dosis macht, dass ein Ding kein Gift ist. Selbst Wasser kann in extremen Mengen tödlich sein. Was heißt das für die Zahnpasta?“","style":"sokratisch","reaction":"„Wasser kann tödlich sein? Hm. Dann kommt es also gar nicht auf den Stoff an, sondern auf die Menge? ...Aber wie viel ist denn bei Zahnpasta zu viel?“","feedback":"Sehr gut! Du bringst die Dosis-Wirkungs-Beziehung als Denkanstoß ein und gibst die Schlussfolgerung an Sabine zurück, statt sie vorzugeben.","score":3,"nextStepId":"step-4"},{"text":"„Klar gibt es eine Grenze, und die normale Putzmenge liegt weit darunter. Du machst dir völlig umsonst Sorgen, das ist alles längst erforscht und im Detail untersucht worden.“","style":"frontal","reaction":"„Längst erforscht, längst erforscht... Das sagen alle! Und ich soll das einfach so glauben?“","feedback":"Inhaltlich in die richtige Richtung, aber als Basta-Aussage. Ohne Erklärung der Dosis klingt es nach Autorität statt nach Einsicht.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Natürlich, du hast absolut recht. Gift ist Gift, egal wie wenig. Deshalb lassen wir lieber alles Chemische weg und putzen nur mit Wasser, so wie früher.“","style":"sarkastisch","reaction":"„Machst du dich gerade über mich lustig? Ich meine das ernst.“ *rückt ab*","feedback":"Sarkasmus macht Sabine lächerlich, statt die Behauptung zu prüfen. Zugleich spielst du das Schwarz-Weiß von „giftig“ und „sicher“ nach und ignorierst die Dosis komplett.","score":-2,"nextStepId":"step-fail"}]},"step-4":{"id":"step-4","speaker":"Sabine","speech":"„Okay, die Menge ist also wichtig. Aber wie soll ich als Laie wissen, welche Menge für Lukas noch in Ordnung ist? Das kann doch keiner so genau abschätzen, wenn er morgens müde und hektisch putzt.“","options":[{"text":"„Du hast recht, das ist die eigentliche Frage. Die Zahnärztin kennt die passende Menge für sein Alter. Wollen wir vorher mal schauen, was auf der Packung steht?“","style":"sokratisch","reaction":"„Ja, das wäre mir recht. Wenn jemand, der sich auskennt, mir die Menge sagt, fühle ich mich sicherer. Ich schau mir die Packung heute Abend mal richtig an.“","feedback":"Ideal! Du nimmst ihre Sorge ernst, hältst an der Dosisfrage fest und verweist für die konkrete Menge auf Fachleute und die Packungsangabe, statt selbst ein Dosisurteil zu fällen.","score":3,"nextStepId":"step-5-success"},{"text":"„Das ist gar kein Problem. Verschluckst du mal etwas, passiert nichts. Das ist doch alles total harmlos.“","style":"frontal","reaction":"„Total harmlos? Eben warst du noch bei der Dosis, und jetzt ist alles harmlos? Das ist auch wieder ein Schwarz-Weiß.“","feedback":"Du kippst ins andere Extrem. Nach „Die Dosis-Wirkungs-Beziehung“ gibt es kein „total harmlos“ an sich, nur harmlose und schädliche Mengen. „Total harmlos“ ignoriert die Dosis genauso wie „Gift“.","score":-1,"nextStepId":"step-5-struggle"},{"text":"„Ich verstehe, dass dich das beschäftigt. Mach dir heute einfach keinen Kopf mehr, das klärt sich schon. Wir sehen uns nächste Woche wieder.“","style":"ausstieg","reaction":"„Na gut, aber ich weiß immer noch nicht, was ich Lukas morgen geben soll...“","feedback":"Der Ausstieg kommt zu früh und lässt Sabine mit ihrer Unsicherheit allein, obwohl sie gerade offen für die Dosisfrage war.","score":0,"nextStepId":"step-5-struggle"}]},"step-5-success":{"id":"step-5-success","speaker":"Sabine","speech":"„Dann ist also nicht das Fluorid an sich das Problem, sondern die Menge, und die kann ich richtig dosieren. Gut, dass du mich nicht belehrt, sondern mir zugehört hast. Ich frage am Donnerstag die Zahnärztin.“","options":[{"text":"„Das finde ich eine gute Idee. Und wenn du magst, schauen wir uns danach gemeinsam an, was sie gesagt hat. Ich bin gespannt.“","style":"deeskalierend","reaction":"„Sehr gern. Ich hätte nicht gedacht, dass mich so ein Gespräch auf dem Spielplatz ruhiger macht. Danke dir.“","feedback":"Gelungener Abschluss: Du hast zugehört, die Dosis ins Spiel gebracht und die Beziehung gestärkt. Sabine entscheidet selbst, informierter als vorher.","score":3}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Sabine","speech":"„Ich weiß nicht... Alle sagen etwas anderes. Ich kann das nicht mehr einordnen.“","options":[{"text":"„Das verstehe ich, bei so vielen Meinungen schwirrt einem der Kopf. Schau heute Abend mal auf die Packung, wie viel dort für Lukas empfohlen wird. Erzähl mir nächste Woche, wie es war.“","style":"deeskalierend","reaction":"„Ja, das kann ich machen. Danke, dass du nicht gleich wieder mit Fakten kommst.“","feedback":"Guter Ausstieg: Du entschärfst die Situation, hältst die Beziehung offen und gibst einen kleinen, überprüfbaren Schritt mit (Dosisangabe auf der Packung nachlesen).","score":2},{"text":"„Dann lass mich dir kurz zusammenfassen, was das Problem ist: Du hast einfach zu viel im Internet gelesen und zu wenig auf die Fachleute gehört, die es besser wissen.“","style":"sarkastisch","reaction":"„Wenn du mich für so naiv hältst, brauchen wir auch nicht weiterreden.“","feedback":"Eine herablassende Zusammenfassung ist kein Paraphrasieren. Du wertest Sabine ab und beendest das Gespräch auf ihre Kosten.","score":-2}]},"step-5-struggle":{"id":"step-5-struggle","speaker":"Sabine","speech":"„Ich bin jetzt noch verunsicherter als vorher. Mal heißt es Dosis, mal harmlos, mal Gift. Was stimmt denn nun?“","options":[{"text":"„Du hast recht, ich habe das zu schnell abgetan. Die Dosis ist der Punkt, und die empfohlene Menge für Lukas kann dir seine Zahnärztin nennen. Fragst du sie beim nächsten Termin?“","style":"deeskalierend","reaction":"„Ja, das mache ich. Danke, dass du dich korrigiert hast, das hilft mir.“","feedback":"Eine ehrliche Korrektur schafft Vertrauen. Du kehrst zur Dosisfrage zurück und verweist auf Fachleute, statt Gewissheit zu behaupten.","score":2},{"text":"„Ich sag es dir, wie es ist: Gift ist es nicht, Punkt. Wenn du mir nicht glaubst, bist du eben selbst schuld, und ich diskutiere das nicht weiter mit dir.“","style":"frontal","reaction":"„Schuld, schuld... Du bist genau wie alle anderen. Ich rede nicht mehr mit dir darüber.“","feedback":"Ein Schlusswort mit Schuldzuweisung verbrennt das Gespräch. Die Sachlage bleibt unerklärt, und Sabine zieht sich zurück.","score":-2}]},"step-fail":{"id":"step-fail","speaker":"Sabine","speech":"„Ich merke schon, mit dir kann man darüber nicht reden. Ich bleibe bei meiner fluoridfreien Zahnpasta, und die anderen Mütter sehen das genauso.“ *ruft Lukas und geht zur Bank am anderen Ende des Spielplatzes*","options":[{"text":"Ende: Sabine fühlte sich nicht gehört und hält jetzt noch fester an ihrer Überzeugung fest. Wer Behauptungen zu schnell widerlegt oder bestätigt, verpasst die eigentliche Sorge.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst zuhören, paraphrasieren und die Sorge verstehen, dann erst die Dosis ins Gespräch bringen.","feedback":"Aktives Zuhören zielt auf Verstehen, nicht auf Antworten. Die Dosis-Wirkungs-Beziehung kommt erst an, wenn die Sorge angekommen ist.","score":0}]},"step-panic":{"id":"step-panic","speaker":"Sabine","speech":"„Wir sollten sofort eine Liste mit allen Zahnpasten zusammenstellen, die Fluorid enthalten, und die anderen Eltern warnen! Gift im Badezimmer, und niemand sagt etwas!“","options":[{"text":"Ende: Die gemeinsame Alarmstimmung verstärkt die Angst, und die Frage nach der Dosis geht völlig unter.","style":"ausstieg","reaction":"Mitgefühl ja, Mitpanik nein: Wer die Angst teilt, kann sie nicht einordnen helfen.","feedback":"Du hast die Angst übernommen, statt sie zu verstehen. Ohne Dosisfrage bleibt „Fluorid“ ein Reizwort, und das Gespräch verstärkt die Sorge.","score":0}]}},"status":"entwurf","familie":"dosis-entscheidet","fertigkeit":"F4","stufe":2,"kurz":"Ob ein Stoff nützt oder schadet, entscheidet nicht der Stoff allein, sondern die Menge. Wer zuerst zuhört und die eigentliche Sorge erfragt, etwa dass ein Kind beim Putzen etwas schluckt, kann die Dosis gezielt ansprechen, ohne die Person abzuwerten.","prueffrage":"Welche Menge Zahnpasta wird für ein Kind dieses Alters empfohlen, und wie viel davon wird beim Putzen tatsächlich geschluckt?","quellen":[{"typ":"url","kurz":"Bundesinstitut für Risikobewertung: FAQ „Fluorid – Ein wichtiger Baustoff für die Zähne“ (17.03.2026)","oeffentlich":true,"url":"https://www.bfr.bund.de/assets/01_Ver%C3%B6ffentlichungen/FAQ_deutsch/fluorid-ein-wichtiger-baustoff-fuer-die-zaehne.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Agency for Toxic Substances and Disease Registry (ATSDR/CDC): A Guide to Active Listening","oeffentlich":true,"url":"https://www.atsdr.cdc.gov/community-engagement-playbook/media/pdfs/2024/09/A-Guide-to-Active-Listening.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Paracelsus (1538): Sieben Defensiones, hg. K. Sudhoff 1915, Dritte Defension; Digitalisat Wellcome Collection (aus Landkarte C.4.7)","oeffentlich":true,"url":"https://wellcomecollection.org/works/jxt2qtp7"}],"thema":"Gesundheit"},{"id":"scen-mikrowelle-nachbarin","title":"Frau Ahrens und die Mikrowellen-Strahlung","subtitle":"Mikrowellenessen angeblich „verstrahlt“, geübt mit aktivem Zuhören","character":"Frau Ahrens, Nachbarin","avatar":"🍲","context":"Im Treppenhaus triffst du deine Nachbarin Frau Ahrens. Als du erwähnst, dass du gleich deinen Auflauf in der Mikrowelle aufwärmst, verzieht sie das Gesicht. Sie erzählt dir, dass sie ihre Mikrowelle neulich zum Sperrmüll gestellt hat: Das Essen daraus sei „verstrahlt“ und habe keine Nährstoffe mehr. Seitdem kocht sie nur noch auf dem Herd.","goal":"Höre Frau Ahrens zuerst aktiv zu, finde heraus, was hinter ihrer Sorge steckt, und führe das Gespräch dann auf die Chemie des Erhitzens.","bereich":"Nachbarschaft","laenge":"kurz","ton":"ernst","bestehenAb":4,"lektion":"Wer zuerst zuhört und die Sorge in eigenen Worten zurückspiegelt, erfährt, woher die Angst kommt, und kann dann gezielt ansetzen. Beim Erhitzen werden Bindungen nach denselben chemischen Regeln aufgebrochen, egal woher die Hitze kommt, und wer nur Fakten sendet, statt zuzuhören, erreicht sein Gegenüber meist gar nicht.","toolRef":"H.2.3","faktenRef":"C.2.2","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Frau Ahrens","speech":"„Ich sage dir, die Mikrowelle hab ich entsorgt. Das Essen daraus ist verstrahlt, da ist nichts Gutes mehr drin. Alle Nährstoffe kaputt! Seitdem koche ich nur noch auf dem Herd, und ich sage jedem: Finger weg von dem Ding!“","options":[{"text":"„Das ist physikalischer Unsinn, Frau Ahrens. Mikrowellen machen Essen nicht radioaktiv. Das lernt man in der Schule, und trotzdem fallen Leute immer noch darauf herein.“","style":"frontal","reaction":"„Ach, jetzt belehrst du mich auch noch! Ich koche seit vierzig Jahren, ich weiß, was ich tue! Du hörst mir ja gar nicht zu.“","feedback":"Frontalangriff! Du sendest nur und hörst nicht zu. Frau Ahrens fühlt sich belehrt und verteidigt ihre Überzeugung umso härter.","score":-2,"nextStepId":"step-fail"},{"text":"„Dir ist das wirklich wichtig, das höre ich. Habe ich richtig verstanden: Du machst dir Sorgen, dass das Essen aus der Mikrowelle dir und anderen schadet? Was hat dich darauf gebracht?“","style":"deeskalierend","reaction":"„*nickt* Genau, so ist es. Mein Schwager hat mir das erzählt, und dann kam im Fernsehen noch so ein Bericht. Ich will einfach, dass meine Enkel gesund essen, weißt du?“","feedback":"Sehr gut! Paraphrasieren und eine offene Frage: Du zeigst, dass du zugehört hast, und erfährst die eigentliche Sorge, nämlich die Gesundheit der Enkel.","score":3,"nextStepId":"step-2"},{"text":"„Ach, ich nutze meine Mikrowelle eigentlich auch nur selten. Wenn es dir damit besser geht, ist das doch völlig in Ordnung, oder?“","style":"ausstieg","reaction":"„Siehst du, du verstehst mich! Hoffentlich machen das bald mehr Leute so wie wir.“","feedback":"Du weichst aus, statt zuzuhören. Die Behauptung bleibt unberührt, und Frau Ahrens fühlt sich in ihrem Mythos sogar bestätigt.","score":-1,"nextStepId":"step-fail"}]},"step-2":{"id":"step-2","speaker":"Frau Ahrens","speech":"„Na ja, Strahlung ist doch Strahlung. Und was da im Essen passiert, das weiß doch keiner so genau. Auf dem Herd sehe ich wenigstens, was passiert. Beim Anbrennen merkt man es ja gleich.“","options":[{"text":"„Beim Erhitzen passiert chemisch immer dasselbe: Hitze bricht Bindungen auf, und die Atome ordnen sich neu. Das gilt für Herd und Mikrowelle gleichermaßen. Das Gerät liefert nur die Wärme, radioaktiv wird davon nichts.“","style":"frontal","reaction":"„Hm, das klingt so, als hättest du das auswendig gelernt. Aber ich verstehe das nicht. Ich bin da keine Wissenschaftlerin.“","feedback":"Inhaltlich richtig, aber du lieferst die Erklärung am Stück. Frau Ahrens fühlt sich eher überrollt als verstanden, und ihre eigene Beobachtung wurde nicht aufgegriffen.","score":1,"nextStepId":"step-3-struggle"},{"text":"„Wenn ich dich richtig verstehe, vertraust du dem Herd, weil du dort siehst, was passiert, und bei der Mikrowelle fehlt dir dieser Einblick. Was würde dir helfen, um sicher zu sein?“","style":"sokratisch","reaction":"„*überlegt* Wenn mir jemand erklären könnte, was da überhaupt passiert. Wenn ich wüsste, wie das Essen warm wird. Dann hätte ich weniger Angst davor.“","feedback":"Meisterhaft! Aktives Zuhören: Du spiegelst ihr Bedürfnis nach Nachvollziehbarkeit zurück. Jetzt ist sie offen für eine Erklärung, die sie sich selbst gewünscht hat.","score":3,"nextStepId":"step-3-success"},{"text":"„Nimm es mir nicht übel, aber das stimmt einfach nicht, was dein Schwager erzählt hat. Hast du mal darüber nachgedacht, dass er sich vielleicht irrt?“","style":"frontal","reaction":"„Mein Schwager ist ein kluger Mann! Du kennst ihn ja nicht mal. Jetzt reicht es aber, ich glaube, wir lassen das Thema.“","feedback":"Du greifst ihre Vertrauensperson an und nicht die Behauptung. Das erzeugt Abwehr statt Nachdenken, und das Gespräch kippt.","score":-2,"nextStepId":"step-fail"}]},"step-3-success":{"id":"step-3-success","speaker":"Frau Ahrens","speech":"„Also mach mir doch mal verständlich, wie das mit dem Essen ist. Wenn das nur Hitze ist wie beim Herd, dann hätte ich ja eine ganz gute Mikrowelle weggeworfen!“","options":[{"text":"„Die Mikrowelle macht das Essen einfach heiß, so wie dein Herd, nur auf anderem Weg. Es bleibt keine geheimnisvolle ‚Strahlung‘ im Essen zurück. Wie viele Vitamine verloren gehen, hängt vor allem davon ab, wie lange, wie heiß und in wie viel Wasser man gart, und das gilt für beide Geräte. Magst du mal ausprobieren, wie Gemüse aus beiden Geräten aussieht und schmeckt?“","style":"sokratisch","reaction":"„Ah, so einfach ist das? Dann ist es im Grunde nur eine andere Art, Wärme zu machen. Das leuchtet mir ein. Vielleicht sollte ich mir doch eine neue kaufen. Und ja, probieren wir das mal zusammen aus!“","feedback":"Mission gelungen! Erst zuhören, dann erklären: Hitze bricht Bindungen nach denselben chemischen Regeln auf, egal woher sie kommt. Das gemeinsame Ausprobieren lässt Frau Ahrens ihr Gesicht wahren.","score":3},{"text":"„Das ist ein ganz einfacher Mechanismus, den kann man bei Wikipedia nachlesen. Da steht alles drin, schau einfach mal selbst nach, ich muss das nicht auch noch erklären, das ist wirklich Allgemeinwissen.“","style":"ausstieg","reaction":"„Wikipedia... na gut. Ich schaue mal. Aber eigentlich wollte ich es von dir hören.“","feedback":"Du schiebst die Arbeit zurück und verschenkst die gewonnene Offenheit. Die Beziehung bleibt intakt, aber Frau Ahrens fühlt sich abgewimmelt.","score":0}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Frau Ahrens","speech":"„Ich weiß nicht, was ich noch glauben soll. Das ist alles so kompliziert. Ich bleibe lieber bei dem, was ich kenne.“","options":[{"text":"„Das verstehe ich, ich war vielleicht zu schnell mit meinen Erklärungen. Magst du mir noch einmal sagen, was dich am meisten beschäftigt? Ich hör dir gern zu.“","style":"deeskalierend","reaction":"„*lächelt* Danke. Es ist eigentlich die Sorge um die Kleinen. Ich will nichts falsch machen. Vielleicht erklärst du es mir ein andermal ganz in Ruhe, Schritt für Schritt.“","feedback":"Gute Korrektur: Du kehrst zum Zuhören zurück, statt weiter zu erklären. Das Gespräch bleibt offen, ihre eigentliche Sorge kommt auf den Tisch, und die Erklärung zum Erhitzen kann in Ruhe nachfolgen.","score":2}]},"step-fail":{"id":"step-fail","speaker":"Frau Ahrens","speech":"„Mit dir kann man darüber nicht reden. Ich weiß, was ich weiß, und mein Herd tut es auch.“ *wendet sich ab und geht in ihre Wohnung*","options":[{"text":"Ende: Frau Ahrens fühlte sich nicht gehört. Wer zuhört, um zu antworten, statt um zu verstehen, erreicht sein Gegenüber nicht.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst paraphrasieren und die Sorge hinter dem Mythos erfragen, erst dann über Inhalte reden.","feedback":"Aktives Zuhören heißt: verstehen, bevor du antwortest. Ohne das bleibt jede noch so richtige Erklärung ungehört.","score":0}]}},"status":"entwurf","familie":"mechanismus-verlangen","fertigkeit":"F1","stufe":1,"kurz":"Beim Erhitzen gelten dieselben chemischen Regeln, egal woher die Hitze kommt. Doch wer nur Fakten sendet, erreicht sein Gegenüber meist nicht: Erst zuhören und die Sorge in eigenen Worten zurückspiegeln, dann zeigt sich, woher die Angst kommt und wo man ansetzen kann.","prueffrage":"Wie viel weißt du über ihre Sorge und deren Herkunft, bevor du mit Erklärungen beginnst?","quellen":[{"typ":"url","kurz":"Bundesamt für Strahlenschutz: Mikrowellenkochgeräte (Stand 15.11.2023)","oeffentlich":true,"url":"https://www.bfs.de/DE/themen/emf/hff/quellen/mikrowelle/mikrowelle.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Agency for Toxic Substances and Disease Registry (ATSDR/CDC): A Guide to Active Listening","oeffentlich":true,"url":"https://www.atsdr.cdc.gov/community-engagement-playbook/media/pdfs/2024/09/A-Guide-to-Active-Listening.pdf","abruf":"2026-10-12"}],"thema":"Technik und KI"},{"id":"scen-nachbar-baum-blitz","title":"Herr Krämer und der Zufallsbeweis","subtitle":"Zwei Zufälle, ein „Muster“, geübt mit Street Epistemology","character":"Herr Krämer, Nachbar","avatar":"⚡","context":"Beim Müllcontainer erzählt dir dein Nachbar Herr Krämer aufgeregt von zwei Unfällen in eurer Straße: Am Freitag, den 13., ist eine Frau mit dem Rad gestürzt, und kurz darauf hat jemand beim Einparken einen Zaun erwischt. Für ihn ist klar: Dieser Tag bringt Unglück, das kann doch kein Zufall sein.","goal":"Bring Herrn Krämer mit neugierigen Fragen dazu, selbst zu prüfen, wie verlässlich seine Methode ist, ohne ihn zu belehren.","bereich":"Nachbarschaft","laenge":"kurz","ton":"heiter","bestehenAb":4,"lektion":"Unser Gehirn sucht Muster im Rauschen (Apophenie); der Bestätigungsfehler merkt sich dann die Treffer und vergisst die ereignislosen Freitage. Wer stattdessen fragt „Wie weißt du das, und wie könnten wir es testen?“, nutzt Street Epistemology: Nicht die Behauptung wird angegriffen, sondern die Methode dahinter gemeinsam geprüft.","toolRef":"H.2.2","faktenRef":"B.9","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Herr Krämer","speech":"„Guten Morgen! Haben Sie das mitbekommen? Freitag, der 13., und gleich zwei Unfälle bei uns in der Straße! Erst die Radfahrerin, dann der Zaun von den Hoffmanns. Ich sage Ihnen: Das kann kein Zufall sein! Dieser Tag ist verhext.“","options":[{"text":"„Das ist Aberglaube, Herr Krämer. Freitag der 13. ist ein Datum wie jedes andere, und zwei Unfälle in einer Straße kommen eben mal vor. Da steckt nichts dahinter.“","style":"frontal","reaction":"„Aberglaube, aha! Und ich bin wohl der Dorftrottel? Ich habe das mit eigenen Augen gesehen, junger Mann!“ *verschränkt die Arme*","feedback":"Frontalangriff: Das Ergebnis mag stimmen, aber Herr Krämer hört „Du bist abergläubisch“ und geht in Verteidigung. Street Epistemology fragt stattdessen nach dem Weg zur Überzeugung.","score":-2,"nextStepId":"step-fail"},{"text":"„Zwei Unfälle an einem Tag, das war bestimmt ein Schreck! Darf ich Sie etwas fragen? Wie sicher sind Sie sich, auf einer Skala von 0 bis 100, dass dieser Tag Unglück bringt? Und was macht Sie so sicher?“","style":"sokratisch","reaction":"„Hm, wie sicher? ...Na, so 85 Prozent, würde ich sagen! Zwei Unfälle an einem Tag, das ist doch kein Spaß.“","feedback":"Sehr gut: Du holst Herrn Krämer ab, bittest um Erlaubnis, fragst den Grad der Sicherheit und den Grund dafür ab. Das ist der Einstieg der Street Epistemology, ganz ohne Gegenbehauptung.","score":3,"nextStepId":"step-2"},{"text":"„Ach, Herr Krämer, wirklich schlimm! Bei mir ist am Freitag der 13. auch mal der Kaffeebecher umgekippt. Da ist wohl was dran!“","style":"humorvoll","reaction":"„Sehen Sie! Das habe ich immer gesagt! Wir sollten uns merken: Freitag der 13., da bleibe ich künftig zu Hause!“ *nickt zufrieden*","feedback":"Gut gemeint, aber du fütterst das Muster mit einem weiteren „Treffer“. So verstärkst du die Mustersuche (Apophenie) und den Bestätigungsfehler, statt die Methode zu hinterfragen.","score":-1,"nextStepId":"step-fail"}]},"step-2":{"id":"step-2","speaker":"Herr Krämer","speech":"„Warum ich mir so sicher bin? Na, ich habe es doch gerade erlebt! Und überhaupt: Jeder weiß, dass an diesem Tag mehr passiert. Ich merke mir das schon seit Jahren, an so einem Freitag geht immer irgendwas schief.“","options":[{"text":"„Das klingt nach einer langen Beobachtung. Meinen Sie, so ein Eindruck könnte auch täuschen? Zum Beispiel, wenn man die ruhigen Freitage vergisst und sich nur die Unfalltage merkt?“","style":"sokratisch","reaction":"„Hm... die ruhigen Freitage? Daran erinnert man sich natürlich nicht, da passiert ja nichts. ...Moment, das ist ein Punkt. Aber wie sollte man das denn rausfinden?“","feedback":"Treffend: Du fragst nach der Zuverlässigkeit der Methode „Erinnerung und Eindruck“. Die Mustersuche (Apophenie) findet den Treffer, der Bestätigungsfehler blendet die ruhigen Freitage aus. Du gibst die Einsicht nicht vor, sondern lässt Herrn Krämer sie selbst finden.","score":3,"nextStepId":"step-3-success"},{"text":"„Dann nehmen Sie doch einfach mal die Unfallstatistik vom letzten Jahr her. Sie werden sehen, dass an Freitagen, die der 13. sind, nicht mehr passiert als sonst.“","style":"frontal","reaction":"„Statistik, Statistik! Mit Zahlen kann man alles beweisen. Ich weiß, was ich gesehen habe!“ *winkt ab*","feedback":"Du behauptest ein Ergebnis, das du hier nicht belegen kannst, und die Belehrung löst Abwehr aus. Besser: Herrn Krämer selbst nach einer verlässlichen Prüfung fragen.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Ich verstehe, dass zwei Unfälle hintereinander unheimlich wirken. Wir müssen das nicht klären. Haben Sie schon die Müllabfuhr-Termine für nächste Woche gesehen?“","style":"ausstieg","reaction":"„Ach ja, die Termine... Nein, die habe ich noch nicht gesehen. Danke für den Hinweis!“","feedback":"Ein freundlicher Ausstieg, die Beziehung bleibt heil. Aber du lässt die Chance liegen, mit einer einzigen Frage nach der Methode einen Denkanstoß zu setzen.","score":0,"nextStepId":"step-3-struggle"}]},"step-3-success":{"id":"step-3-success","speaker":"Herr Krämer","speech":"„Wie man das rausfindet? Na ja, man müsste wohl mal aufschreiben, wie es an ganz normalen Freitagen läuft, nicht nur am Dreizehnten. Und dann vergleichen. ...Hm, das habe ich in all den Jahren nie gemacht. Ist ja eigentlich komisch.“","options":[{"text":"„Genau, das fände ich auch spannend. Und wenn wir in der Straße eine Weile mitzählen würden: Würde das Ihre 85 Prozent verändern, wenn sich zeigt, dass es nicht auffällig mehr Unfälle gibt?“","style":"sokratisch","reaction":"„Wenn nicht mehr passiert als sonst? Dann wären es wohl eher 50 Prozent. Oder weniger. Wissen Sie was, ich schreibe mir den nächsten Freitag mal auf. Und den davor und danach auch!“ *lacht*","feedback":"Mission gelungen! Der Sicherheitsgrad ist ins Rutschen gekommen, und Herr Krämer will seine Methode selbst prüfen. Ein kleiner Stein des Zweifels, ganz ohne Gesichtsverlust.","score":3}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Herr Krämer","speech":"„Na, wie dem auch sei. Ich bleibe dabei, so ein Zufall war das nicht. Aber reden kann man ja mal darüber.“","options":[{"text":"„Sehr gern. Eine Frage lasse ich Ihnen noch mit: Woran würden Sie merken, dass es doch nur Zufall war? Würde Ihnen dazu etwas einfallen?“","style":"sokratisch","reaction":"„Woran ich das merke? ...Gute Frage. Da muss ich mal drüber nachdenken. Vielleicht, wenn ein Freitag ganz ruhig bleibt?“ *kratzt sich am Kinn*","feedback":"Guter Rettungsanker: Auch wenn das Gespräch holprig lief, lässt du eine offene Frage zurück. Das ist die Idee der Street Epistemology: einen Stein des Zweifels ins Rollen bringen, nicht ein Geständnis erzwingen.","score":2},{"text":"„Wissen Sie, Herr Krämer, das ist reine Statistik. Zwei Unfälle sind noch lange kein Beweis, und irgendwann müssen Sie das einsehen.“","style":"frontal","reaction":"„Einsehen! Ich lasse mir von Ihnen doch nichts vorschreiben!“ *dreht sich um und geht*","feedback":"Noch einmal belehrt statt gefragt: Wer die Schlussfolgerung angreift, statt die Methode zu erkunden, schließt die Tür.","score":-2}]},"step-fail":{"id":"step-fail","speaker":"Herr Krämer","speech":"„Ich sehe schon, ich bleibe bei meiner Meinung. Freitag der 13. ist und bleibt ein Unglückstag, und ich habe heute wieder den Beweis gesehen!“ *stapft davon*","options":[{"text":"Ende: Herr Krämer sieht sich bestätigt. Das Gespräch hat sein Muster eher gefestigt als hinterfragt.","style":"ausstieg","reaction":"Beim nächsten Mal nicht gegen die Überzeugung, sondern nach dem Weg dorthin fragen.","feedback":"Frag dich: Wollte ich recht behalten oder verstehen, wie Herr Krämer zu seiner Sicherheit kommt? Street Epistemology untersucht die Methode, nicht die Schlussfolgerung.","score":0}]}},"status":"entwurf","familie":"muster-im-zufall","fertigkeit":"F4","stufe":2,"kurz":"Zwei Unglücke an einem besonderen Tag wirken wie ein Muster, weil das Gedächtnis die Treffer behält und die ereignislosen Freitage vergisst. Statt die Überzeugung anzugreifen, hilft es, gemeinsam zu fragen, woher man das weiß und wie es sich prüfen ließe.","prueffrage":"Wie viele Unfälle gab es in der Straße an gewöhnlichen Freitagen, und wer hat die je gezählt?","quellen":[{"typ":"doi","kurz":"van Prooijen, J.-W.; Douglas, K. M.; De Inocencio, C. (2018): Connecting the dots: Illusory pattern perception predicts belief in conspiracies and the supernatural. European Journal of Social Psychology 48(3) (PMC5900972)","oeffentlich":true,"doi":"10.1002/ejsp.2331","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5900972/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Blain, S. D. u. a. (2020): Apophenia as the Disposition to False Positives. Journal of Abnormal Psychology 129(3) (aus Landkarte B.9; Zugang nicht selbst geprüft)","oeffentlich":false,"doi":"10.1037/abn0000504"},{"typ":"url","kurz":"Street Epistemology International: Street Epistemology (Startseite, Selbstdarstellung der Methode)","oeffentlich":true,"url":"https://streetepistemology.com/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen"},{"id":"scen-gedaechtnis-wie-video","title":"Ich weiß das noch genau!","subtitle":"Gedächtnis als Rekonstruktion, geübt mit kognitiver Entkopplung","character":"Matthias, 52, Hobby-Erzähler","avatar":"🎞️","context":"Beim Grillabend erzählt Matthias zum hundertsten Mal die Geschichte vom legendären Campingurlaub. Diesmal widerspricht seine Schwester in einem Detail, und Matthias ist sicher: Sein Kopf speichert das alles wie ein Video, er weiß es haargenau. Du sitzt daneben und merkst, wie die Stimmung kippen könnte.","goal":"Bring Matthias dazu, die eigene Erinnerung als möglicherweise veränderlich zu betrachten, ohne dass er sein Gesicht verliert – mit Hilfe der kognitiven Entkopplung.","bereich":"Ich selbst","laenge":"kurz","ton":"heiter","bestehenAb":4,"lektion":"Eine Erinnerung ist kein Video, sondern wird bei jedem Abruf neu zusammengesetzt – und dabei kann sie sich verändern. Dass sie sich glasklar und sicher anfühlt, ist deshalb allein noch kein Beleg dafür, dass sie stimmt. Wer sich selbst von seinen Erinnerungen und Überzeugungen entkoppelt, kann „Ich lag da wohl daneben“ sagen, ohne dass seine Identität Schaden nimmt.","toolRef":"H.1.1","faktenRef":"E.3.6","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Matthias","speech":"„Also bitte, Sabine, der Blitz hat das rote Zelt getroffen, nicht das blaue! Ich seh das vor mir wie im Kino, jedes Detail! Mein Gedächtnis ist wie eine Videokamera. Was ich erlebt habe, weiß ich haargenau!“","options":[{"text":"„Matthias, dein Gedächtnis ist keine Videokamera, das ist wissenschaftlich längst widerlegt. Gib's einfach zu, du liegst da falsch, und wir können weitergrillen.“","style":"frontal","reaction":"„Wissenschaftlich widerlegt! Ich war dabei, du nicht! Erst die Schwester, jetzt du, ihr fallt mir alle in den Rücken!“ *verschränkt die Arme*","feedback":"Die Sachaussage ist richtig, aber du packst sie als Angriff auf seine Person. Wer sich angegriffen fühlt, verteidigt seine Identität statt die Wahrheit zu suchen.","score":-2,"nextStepId":"step-fail"},{"text":"„Du erzählst das mitreißend, ich sehe die Szene richtig vor mir. Darf ich dich was fragen: Wie sicher bist du dir bei dem Zelt, und woran machst du diese Sicherheit fest?“","style":"sokratisch","reaction":"„Wie sicher? Hundert Prozent! Ich spüre es doch, so klar wie nur irgendwas. Das Bild ist ganz scharf in meinem Kopf... *stutzt kurz* Woran ich das festmache? Na, am Bild eben.“","feedback":"Gut! Du wertschätzt ihn und lenkst den Blick auf das Gefühl der Sicherheit selbst. Das lässt sich später prüfen, denn auch klare, sichere Erinnerungen können Konstruktionen sein. So trennst du die Frage nach dem Zelt von Matthias als Erzähler.","score":3,"nextStepId":"step-2"},{"text":"„Ach, wer weiß das nach so vielen Jahren schon so genau. Lasst uns lieber noch eine Wurst auflegen und über etwas Schöneres reden.“","style":"ausstieg","reaction":"„Ich weiß es aber genau! Siehst du, Sabine, er will sich nur nicht einmischen. Das Zelt war rot.“","feedback":"Du entschärfst die Lage, aber Matthias fühlt sich in seiner Sicherheit bestätigt. Ein Ausstieg ist legitim, hier lässt er jedoch die Chance liegen, dass er seine Gewissheit hinterfragt.","score":0,"nextStepId":"step-2-struggle"}]},"step-2":{"id":"step-2","speaker":"Matthias","speech":"„Ich seh's doch deutlich: der Blitz, das rote Zelt, der Qualm! Warum sollte mein Kopf mir was Falsches zeigen?“","options":[{"text":"„Weil das Gehirn gar nichts abspielt, sondern bei jedem Erzählen die Erinnerung neu zusammenbaut. Dein Bild kann sich dabei verändert haben, ohne dass du es merkst.“","style":"frontal","reaction":"„Verändert? Also dass ich lüge, oder was?“ *verzieht das Gesicht* „Nee, das lass ich mir nicht erzählen.“","feedback":"Der Sachverhalt stimmt, kommt aber als Behauptung über Matthias selbst an. Ohne Entkopplung von seiner Geschichte klingt „kann sich verändert haben“ für ihn nach „du lügst“.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Dein Kopf will dir nichts Falsches zeigen, er füllt Lücken, damit die Geschichte rund wird, das macht jedes Gehirn. Prüfen wir es: Gibt es von damals ein Foto vom Zelt?“","style":"sokratisch","reaction":"„Ein Foto? ...Warte. Sabine hat doch damals alles geknipst. Das Album liegt bei ihr. *grinst schief* Na gut, schauen wir nach. Ich bin gespannt, ob ich recht habe!“","feedback":"Stark! Du trennst Matthias von seiner Erinnerung („nur eine Hypothese“) und nennst einen überprüfbaren Weg: ein Foto ist deutlich verlässlicher als das bloße Gefühl.","score":3,"nextStepId":"step-3-success"},{"text":"„Dein Kopf zeigt dir nichts Falsches, Matthias, dein Gedächtnis ist halt einfach besonders gut. Bei mir wäre das längst weg, ich vergesse schon, was ich gestern gegessen habe.“","style":"humorvoll","reaction":"„Eben! Ich sag's ja, Sabine, bei mir sitzt jedes Detail!“ *strahlt und lehnt sich zurück*","feedback":"Nett gemeint, aber du bestärkst die Videokamera-Idee und er fühlt sich bestätigt. Ein freundlicher Scherz ersetzt hier keine Frage.","score":-1,"nextStepId":"step-fail"}]},"step-2-struggle":{"id":"step-2-struggle","speaker":"Matthias","speech":"„Ich sag ja: Mein Gedächtnis ist Gold wert. Andere vergessen alles, bei mir ist das wie eingebrannt. Das Zelt war rot, Punkt!“","options":[{"text":"„Ich glaub dir, dass es sich so anfühlt. Nur: Auch eine ganz sichere Erinnerung kann sich mit den Jahren verschoben haben. Schauen wir mal, ob es Fotos von damals gibt?“","style":"sokratisch","reaction":"„Fotos? *überlegt* Na gut, meinetwegen. Sabine hat das Album sicher noch. Aber du wirst sehen, ich hab recht.“","feedback":"Gut gerettet! Du nimmst sein Gefühl ernst, zeigst aber, dass auch sichere Erinnerungen sich verschieben können, und bietest eine neutrale Prüfung an, ohne ihn bloßzustellen.","score":2,"nextStepId":"step-3-success"},{"text":"„Dann ist ja alles geklärt. Aber ehrlich, dass sich jemand an alles so genau erinnert, ist schon seltsam, oder? Ich kann das von mir jedenfalls nicht behaupten.“","style":"sarkastisch","reaction":"„Seltsam? Soll das heißen, ich spinne? Ich glaub, ich geh mir mal ein Bier holen.“ *steht auf*","feedback":"Der leise Spott trifft die Person, nicht die Behauptung. Matthias fühlt sich vorgeführt, und das Gespräch endet, bevor es eine Frage hätte klären können.","score":-2,"nextStepId":"step-fail"}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Matthias","speech":"„Meine Erinnerung ist halt so. Ich weiß nicht, warum ihr mir das alle ausreden wollt.“ *klingt ein wenig verletzt*","options":[{"text":"„Ich will dir gar nichts ausreden, Matthias. Deine Geschichten sind das Beste an diesen Abenden. Bringen wir beim nächsten Mal die alten Fotos mit, dann haben wir noch mehr Stoff.“","style":"deeskalierend","reaction":"„Alte Fotos... *lächelt* Das wär eigentlich nett. Hab ich seit Jahren nicht mehr angeschaut. Okay, abgemacht.“","feedback":"Guter Ausstieg: Die Beziehung ist heil, und das Foto als neutrale Prüfung ist als offene Tür geblieben.","score":2},{"text":"„Weil sich ein Gedächtnis eben irren kann, und du bist eben nicht die Ausnahme. Das ist einfach so, und daran ändert auch deine Sicherheit nichts, Matthias.“","style":"frontal","reaction":"„Na toll. Dann bin ich eben der Depp der Runde. Erzählt eure Geschichten doch selbst.“","feedback":"Wieder eine richtige Aussage in falscher Verpackung: Statt Matthias zu entkoppeln, drückst du ihn in die Ecke und er macht dicht.","score":-1}]},"step-3-success":{"id":"step-3-success","speaker":"Matthias","speech":"„Sabine, hol mal das Album! *blättert, stutzt* Das Zelt auf dem Foto ist... blau? Mit einem roten Kocher davor? Das darf doch nicht wahr sein, ich hätte schwören können...“","options":[{"text":"„Ist doch spannend! Vielleicht hat dein Kopf das Rot vom Kocher ins Zelt gemalt und dir trotzdem ein scharfes Bild geliefert. Das passiert jedem, und die Story vom Blitz bleibt klasse.“","style":"humorvoll","reaction":"„*lacht laut* Mein Kopf, der alte Maler! Okay, das merk ich mir: Wenn ich mir so richtig sicher bin, schau ich lieber mal ins Album.“","feedback":"Meisterhaft: Matthias zeigt echte kognitive Entkopplung. Er kann einen Irrtum mit Humor annehmen, weil seine Identität nicht an der Zeltfarbe hängt. Und du hast ihm die Geschichte gelassen.","score":3},{"text":"„Siehst du, ich hab's gleich gesagt: Du hast dich geirrt. Dein Gedächtnis ist eben doch keine Videokamera, und jetzt hast du den Beweis schwarz auf weiß vor dir.“","style":"frontal","reaction":"„Ja, ja, jetzt schön draufhauen. Hast du auch mal falschgelegen? Ich geh ein Bier holen.“ *klappt das Album zu*","feedback":"Der Triumph kostet Gesicht. Wer sich ertappt fühlt, entkoppelt sich nicht von der Idee, sondern verteidigt sich. Das Foto hatte die Arbeit schon getan.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Matthias","speech":"„Ich weiß, was ich weiß, und damit Schluss!“ *wendet sich demonstrativ ab und erzählt dem Nachbarn dieselbe Geschichte noch einmal, jetzt lauter*","options":[{"text":"Ende: Matthias hat sich verschanzt. Wer an seiner Erinnerung angegriffen wird, verteidigt eher sein Selbstbild als die Wahrheit.","style":"ausstieg","reaction":"Beim nächsten Mal: erst nachfragen und die Sicherheit prüfbar machen (Foto, Beleg), statt die Erinnerung selbst anzugreifen.","feedback":"Ein Angriff auf die Erinnerung wirkt wie ein Angriff auf die Person. Mit Entkopplung wird die Erinnerung zur Hypothese, die man prüfen kann, ohne dass jemand verliert.","score":0}]}},"status":"entwurf","familie":"erinnerung-ist-rekonstruktion","fertigkeit":"F5","stufe":3,"kurz":"Eine Erinnerung wird bei jedem Abruf neu zusammengesetzt und kann sich dabei verändern. Wie klar und sicher sie sich anfühlt, belegt allein nicht, dass sie stimmt; wer sich nicht mit ihr gleichsetzt, kann einen Irrtum zugeben, ohne das Gesicht zu verlieren.","prueffrage":"Worauf stützt sich die Gewissheit über die Zeltfarbe, und was außer dem Bild im Kopf könnte sie bestätigen?","quellen":[{"typ":"url","kurz":"Schacter, D. L.; Guerin, S. A.; St. Jacques, P. L. (2011): Memory distortion: an adaptive perspective. Trends in Cognitive Sciences 15(10) (Autorenmanuskript in PMC)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3183109/","abruf":"2026-10-12"},{"typ":"url","kurz":"Wixted, J. T.; Wells, G. L. (2017): The Relationship Between Eyewitness Confidence and Identification Accuracy: A New Synthesis. Psychological Science in the Public Interest 18(1) (Abstract bei PubMed; DOI 10.1177/1529100616686966)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/28395650/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Loftus, E. F.; Pickrell, J. E. (1995): The Formation of False Memories. Psychiatric Annals 25(12)","oeffentlich":false}],"thema":"Psychologie"},{"id":"scen-roulette-rot","title":"Fünfmal Rot, jetzt Schwarz!","subtitle":"Spielerfehlschluss, geübt mit Neuroplastizität und Konzentration","character":"Kevin, Freund beim Spieleabend","avatar":"🎰","context":"Ihr seid zu einem lockeren Spieleabend mit einem kleinen Roulette-Brettspiel verabredet. Kevin hat fünfmal in Folge Rot kommen sehen und will jetzt seine Chips auf Schwarz schieben, weil „Schwarz einfach dran ist“. Er meint es nicht böse, er will bloß clever sein.","goal":"Bring Kevin dazu, selbst zu merken, dass die Kugel kein Gedächtnis hat, ohne ihn vor den anderen bloßzustellen.","bereich":"Freunde","laenge":"kurz","ton":"heiter","bestehenAb":4,"lektion":"Beim Zufallsspiel haben frühere Ergebnisse keinen Einfluss auf die nächste Runde. Die Kugel, die Münze und der Würfel haben kein Gedächtnis, und eine Serie wird nicht „ausgeglichen“, sondern nur über viele Würfe hinweg verdünnt. Mit der Aktivierungs-Frage „Weiß das Ding, das hier gerade würfelt, was vorher passiert ist?“ und freundlicher, gemeinsamer Neugier kommst du weiter als mit dem Zeigefinger. Was wir oft wiederholen, wird zur eingefahrenen Bahn: Wer die Aktivierungs-Frage bewusst immer wieder stellt, trainiert sein Gehirn aufs Prüfen.","toolRef":"H.1.5","faktenRef":"B.30","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Kevin","speech":"„Fünfmal hintereinander Rot, Leute! Das ist doch jetzt Wahnsinn. Jetzt kommt todsicher Schwarz, die Chance steigt mit jeder Runde! Ich setze alles auf Schwarz, wer ist dabei?“","options":[{"text":"„Kevin, das ist der klassische Spielerfehlschluss. Die Kugel hat kein Gedächtnis, Schwarz ist kein bisschen wahrscheinlicher als vorher. Schau doch mal ein Mathebuch an.“","style":"frontal","reaction":"„Oh, danke, Herr Professor! Dann setz du doch auf Rot, wenn du so schlau bist. Mit dir macht Spielen echt keinen Spaß.“ *verschränkt die Arme*","feedback":"Fachlich stimmt es, aber Kevin hört nur „du bist dumm“ und geht in die Abwehr. Mit Belehrung kommst du nicht zu ihm durch.","score":-1,"nextStepId":"step-fail"},{"text":"„Dann setze ich auch auf Schwarz! Bei fünfmal Rot ist das doch logisch. Und wenn Schwarz nicht kommt, verdoppeln wir einfach den Einsatz, dann holen wir es wieder rein.“","style":"humorvoll","reaction":"„Genau das ist der Plan! Wir sind ein Team! Verdoppeln, bis es klappt, das kann gar nicht schiefgehen!“ *klatscht dich ab*","feedback":"Du bestärkst den Fehlschluss und lobst sogar die Verdopplungs-Strategie, die schon viele Spieler ruiniert hat. Nett gemeint, aber hilfreich ist das nicht.","score":-2,"nextStepId":"step-fail"},{"text":"„Fünfmal Rot, das fühlt sich echt nach Wende an. Aber sag mal: Woher soll die Kugel wissen, dass vorher fünfmal Rot kam? Merkt sie sich das irgendwie?“","style":"sokratisch","reaction":"„Merkt sie sich...? Naja, nicht direkt, aber irgendwie muss sich das doch ausgleichen, oder? *kratzt sich am Kopf* Das ist doch das Gesetz der Serie!“","feedback":"Gut! Mit der Aktivierungs-Frage „Weiß das Ding, das hier gerade würfelt, was vorher passiert ist?“ lässt du Kevin selbst nachdenken, statt ihm die Antwort zu liefern.","score":3,"nextStepId":"step-2"}]},"step-2":{"id":"step-2","speaker":"Kevin","speech":"„Aber irgendwann gleicht sich das doch aus! Nach hundert Runden ist es fast fifty-fifty. Also muss Schwarz jetzt aufholen, sonst käme ja nie ein Gleichgewicht zustande!“","options":[{"text":"„Das stimmt langfristig, aber nichts wird ‚aufgeholt‘: Die frühe Rot-Serie fällt bei sehr vielen Runden immer weniger ins Gewicht. Läuft die nächste Runde anders, wenn wir den Tisch neu aufbauen?“","style":"sokratisch","reaction":"„Verdünnt... *überlegt* Also die fünf Rot werden nicht ausgeglichen, sie gehen nur im großen Haufen unter? Und eine neue Runde ist eigentlich immer wieder eine erste Runde... Hm, das ist ziemlich gemein für meinen Plan.“","feedback":"Sehr gut: Du greifst Kevins berechtigte Intuition (langfristig fifty-fifty) auf und erklärst den Unterschied zwischen „ausgleichen“ und „verdünnen“. Die Gedankenübung lässt ihn selbst weiterdenken.","score":3,"nextStepId":"step-3-success"},{"text":"„Ach komm, das haben schon Tausende vor dir gedacht, und Casinos leben genau davon. Hör einfach auf, mit dem Bauchgefühl zu spielen, sonst verlierst du bloß dein Geld.“","style":"sarkastisch","reaction":"„Mein Bauchgefühl hat mich schon oft nicht im Stich gelassen! *winkt ab* Naja, vielleicht setze ich einfach mal aus und schaue zu.“","feedback":"Kevin zieht sich zurück, aber nicht, weil er etwas verstanden hat, sondern weil er sich ertappt fühlt. Der Hinweis auf die Casinos ist richtig, ersetzt aber das Verstehen nicht.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Stimmt, irgendwo muss ja ausgeglichen werden. Dann bist du nach der Logik in der nächsten Runde bestimmt dran. Ich würde an deiner Stelle richtig viel setzen, die Chance kommt nicht wieder.“","style":"humorvoll","reaction":"„Siehst du, selbst du siehst es! Ich schiebe jetzt alles aufs Feld, bis hierhin war ich eh schon im Minus!“ *schiebt den ganzen Chipstapel nach vorn*","feedback":"Du bestärkst ihn und spielst die Gefahr herunter. Wer nach Verlusten seinen Einsatz erhöht, steht genau an dem Punkt, an dem der Spielerfehlschluss gefährlich wird.","score":-2,"nextStepId":"step-fail"}]},"step-3-success":{"id":"step-3-success","speaker":"Kevin","speech":"„Okay, okay, ich hab's kapiert, die Kugel hat kein Gedächtnis. Peinlich, ich hab immer gesagt, ‚nach fünfmal Rot ist Schwarz dran‘. Was mache ich denn jetzt mit meinem Bauchgefühl? Das drängelt ja trotzdem.“","options":[{"text":"„Dein Bauchgefühl ist vielleicht eher für Dinge gemacht, die sich wirklich erschöpfen, wie ein Beerenstrauch, der irgendwann leer ist. Beim Roulette liegt es daneben. Frag dich vorm Setzen: Weiß das Ding, was vorher passiert ist? Und nachher machen wir den Münztest: oft werfen und schauen, wie lang die Serien werden.“","style":"sokratisch","reaction":"„Beerensträucher, ha! Das merke ich mir. Und ja, den Münztest machen wir, ich wette, ich komme nie auf mehr als drei in Folge.“ *grinst* „Und du wirst mir hoffentlich nicht ewig vorrechnen, dass ich falsch liege!“","feedback":"Rundes Ende: Du würdigst Kevins Intuition, gibst ihm die Aktivierungs-Frage als Werkzeug und lädst ihn zum Selbsttest ein. Wer das Prüfen übt, trainiert sein Gehirn in diese Richtung.","score":3},{"text":"„Ganz einfach: Hör auf dein Bauchgefühl nie wieder, das lügt sowieso immer. Rechne lieber alles nach, bevor du irgendetwas entscheidest, auch beim Einkaufen.“","style":"frontal","reaction":"„Nie wieder? Mein Bauchgefühl rettet mich auch bei vielen anderen Sachen. Hör auf, so zu tun, als wüsstest du alles.“","feedback":"Zu absolut. Die Intuition ist in vielen Lebensbereichen nützlich, ihr Fehler liegt nur darin, dass sie sich auf echte Zufallsgeneratoren überträgt.","score":0},{"text":"„Gute Frage. Lass uns das auf morgen verschieben, ich will jetzt einfach nur spielen. Heute Abend läuft es bei mir, und da will ich nicht groß nachdenken.“","style":"ausstieg","reaction":"„Alles klar, dann halt morgen. Aber erinnere mich dran, ich will das mit der Kugel ganz sicher noch verstehen.“","feedback":"Okay, die Beziehung bleibt heil. Du lässt aber die Chance liegen, Kevin direkt ein Werkzeug mitzugeben, solange er noch offen ist.","score":1}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Kevin","speech":"„Ich schau jetzt erst mal zu. Aber irgendwie bleibt in meinem Kopf hängen: Nach fünfmal Rot muss doch was passieren. Das fühlt sich einfach so an.“","options":[{"text":"„Dieses Gefühl hat fast jeder, das ist normal. Beim nächsten Spieleabend rechnen wir das mal mit einer Münze durch. Spielst du heute noch eine Runde ohne Einsatz mit, nur zum Spaß?“","style":"deeskalierend","reaction":"„Ohne Einsatz? Meinetwegen, das klingt entspannt. Und die Münzgeschichte machen wir wirklich noch.“ *nimmt wieder Platz*","feedback":"Guter Ausstieg: Du erkennst das Gefühl an, nimmst den Druck raus und lässt die Tür für später offen. Der Fehlschluss ist noch da, die Freundschaft aber heil.","score":2},{"text":"„Dann setz halt weiter auf dein Gefühl, ist ja dein Geld. Ich hab’s dir gesagt, und ich sage es dir auch gern noch mal, wenn du verloren hast und wieder alles nachrechnest.“","style":"sarkastisch","reaction":"„Na toll, jetzt ist der Abend verdorben. Danke fürs Gespräch.“ *wendet sich ab*","feedback":"Der Abgang kippt in Rechthaberei. Kevin bleibt beim Fehlschluss und fühlt sich außerdem belehrt.","score":-1},{"text":"„Na ja, vielleicht hast du ja recht, keine Ahnung. Spielen wir einfach weiter und schauen, was die nächsten Runden bringen, vielleicht dreht sich das Blatt ja noch.“","style":"ausstieg","reaction":"„Ja, Spielen ist besser als Diskutieren.“ *lacht verlegen*","feedback":"Ruhiger Ausgang, aber du nimmst deine eigene Sachaussage zurück, obwohl sie stimmte. Dadurch fehlt Kevin jeder Anstoß zum Weiterdenken.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Kevin","speech":"„Alle auf Schwarz, Leute! Jetzt kommt es sicher!“ *schiebt den ganzen Chipstapel nach vorn, die Kugel rollt... und landet auf Rot*","options":[{"text":"Ende: Kevin hat seinen Stapel verloren und denkt: „Pech gehabt, nächstes Mal klappt’s.“ Der Fehlschluss lebt weiter.","style":"ausstieg","reaction":"Ein Gespräch, das zuerst Kevins Intuition ernst nimmt und dann mit der Frage „Weiß das Ding, was vorher passiert ist?“ ansetzt, hätte ihn eher erreicht.","feedback":"Rechthaben und Helfen sind zweierlei. Seziert wird die Behauptung, nicht der Mensch, und Kevin hat sie aus einem verständlichen Muster heraus aufgestellt.","score":0}]}},"status":"entwurf","familie":"zufall-ohne-gedaechtnis","fertigkeit":"F4","stufe":1,"kurz":"Beim Zufallsspiel beeinflussen frühere Ergebnisse die nächste Runde nicht: Kugel, Münze und Würfel haben kein Gedächtnis. Eine Serie wird nicht „ausgeglichen“, sondern fällt erst über sehr viele Runden immer weniger ins Gewicht.","prueffrage":"Was müsste sich nach fünfmal Rot an Kugel oder Kessel verändert haben, damit Schwarz jetzt wahrscheinlicher wird?","quellen":[{"typ":"url","kurz":"Chen, D.; Moskowitz, T. J.; Shue, K. (2016): Decision-Making under the Gambler's Fallacy: Evidence from Asylum Judges, Loan Officers, and Baseball Umpires. NBER Working Paper 22026","oeffentlich":true,"url":"https://www.nber.org/papers/w22026","abruf":"2026-10-12"},{"typ":"url","kurz":"Clotfelter, C. T.; Cook, P. J. (1991): The \\"Gambler's Fallacy\\" in Lottery Play. NBER Working Paper 3769","oeffentlich":true,"url":"https://www.nber.org/papers/w3769","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1971): Belief in the law of small numbers. Psychological Bulletin 76(2)","oeffentlich":false,"doi":"10.1037/h0031322"}],"thema":"Geld und Zahlen"},{"id":"scen-chef-zufaellig-erfolg","title":"Geschäftsführerin Marlenes Erfolgsrezept","subtitle":"Warum meine Firma lief, geübt mit Street Epistemology","character":"Marlene","avatar":"💼","context":"Beim Networking-Abend erzählt dir Marlene, Geschäftsführerin einer kleinen Agentur, strahlend von ihrem Erfolg. Sie ist sicher: Ihre Morgenroutine und ihr Führungsstil sind der Grund, warum ihre Firma so gut läuft. Gerade hat sie dich gefragt, ob du ihr Seminar buchen willst.","goal":"Bring Marlene mit neugierigen Fragen (Street Epistemology) dazu, selbst zu prüfen, woher sie so sicher weiß, dass ihr Rezept die Ursache ihres Erfolgs ist, ohne sie bloßzustellen.","bereich":"Arbeit","laenge":"mittel","ton":"sarkastisch","bestehenAb":6,"lektion":"Eine runde Erfolgsgeschichte ist noch kein Beweis: Im Rückblick wirkt jede Entscheidung brillant, und Glück, Timing und Zufall fallen aus der Erzählung (Erzählfehler). Mit Street Epistemology fragst du nicht „Du liegst falsch“, sondern „Wie weißt du das, und wie verlässlich ist diese Methode?“. So darf Marlene stolz auf ihre Arbeit bleiben und trotzdem selbst die Lücken in ihrer Geschichte entdecken.","toolRef":"H.2.2","faktenRef":"B.5","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Marlene","speech":"„Ich sag dir, mein Erfolg ist kein Zufall! Um fünf Uhr aufstehen, Eisbad, Journaling, und im Büro klare Kante: So führt man ein Unternehmen. Sieh dir die Firma an, sie läuft! Das beweist doch alles. Mein Seminar kostet übrigens nur 990 Euro.“","options":[{"text":"„Marlene, das ist ein klassischer Fehlschluss. Dass deine Firma läuft, beweist gar nichts über dein Eisbad. Das ist reine Erzählung im Rückblick, Stichwort Erzählfehler.“","style":"frontal","reaction":"„Ah, jetzt kommt die Belehrung! Ich habe eine Firma aufgebaut, und du erklärst mir meine Geschichte? Komm doch erst mal auf meinen Umsatz.“","feedback":"Frontalangriff: Der Begriff stimmt, aber Marlene hört nur Abwertung. Sie wird defensiv, und das Gespräch endet, bevor sie nachdenken kann.","score":-2,"nextStepId":"step-fail"},{"text":"„Beeindruckend, Marlene. Darf ich dich was fragen? Woran hast du festgemacht, dass es gerade die Morgenroutine und dein Führungsstil waren, die den Erfolg gebracht haben?“","style":"sokratisch","reaction":"„Wie ich das festgestellt habe? Na, ich sehe es doch! Seit ich das mache, geht es bergauf. Aber gut, frag ruhig, ich liebe Fragen.“","feedback":"Stark: Du lenkst ohne Angriff auf die Methode statt auf die Schlussfolgerung. Marlene darf ihre eigene Begründung aussprechen.","score":3,"nextStepId":"step-2"},{"text":"„Wow, Eisbad um fünf! Ich glaube, mit meinem Schlaf könnte ich das nie. Du musst wirklich eisern sein, Marlene, das ist echt beeindruckend.“","style":"humorvoll","reaction":"„Eisern ist das richtige Wort! Genau das braucht man als Chefin. Dann buchst du also das Seminar?“","feedback":"Nett, aber folgenlos: Du schmeichelst, ohne die Behauptung zu klären. Marlene fühlt sich bestätigt, nichts wird hinterfragt.","score":0,"nextStepId":"step-2"}]},"step-2":{"id":"step-2","speaker":"Marlene","speech":"„Ich vergleiche einfach vorher und nachher! Vor meiner Routine lief die Agentur mittelmäßig, danach ging es steil nach oben. Was braucht man mehr als das? Und die anderen Chefs, die ich kenne, die erfolgreich sind, machen es genauso.“","options":[{"text":"„Dass du Erfolgreiche kennst, die es genauso machen, ist spannend. Kennst du auch Chefs, die um fünf aufstehen und trotzdem mit ihrer Firma gescheitert sind?“","style":"sokratisch","reaction":"„Gescheiterte? ...Hm. Die erzählen eher nichts auf Bühnen. Ein Kollege hat vor zwei Jahren zugemacht, der stand auch früh auf. Aber das war eine andere Branche, da lief halt alles schief.“","feedback":"Treffer: Du bringst die unsichtbare Seite ins Spiel, die Gescheiterten mit gleicher Routine. Das ist die Lücke, die der Erzählfehler lässt, und Marlene entdeckt sie selbst.","score":3,"nextStepId":"step-3"},{"text":"„Das klingt nach einer ziemlich einfachen Rechnung. Aber ein Vorher-nachher ist doch auch bei jedem Horoskop so, oder? Das ist nichts weiter als Wunschdenken.“","style":"sarkastisch","reaction":"„Horoskop?! Du vergleichst meine Disziplin mit Sternzeichen? Das ist unter deinem Niveau, ehrlich.“","feedback":"Der Vergleich sitzt als Spott, nicht als Frage. Du setzt Marlene herab, statt ihre Methode zu erkunden, und sie macht dicht.","score":-2,"nextStepId":"step-fail"},{"text":"„Das ist ein nachvollziehbarer Gedanke. Ich frage mich nur: Hat sich in der Zeit sonst noch etwas verändert, zum Beispiel Kunden, Markt oder Aufträge?“","style":"deeskalierend","reaction":"„Na ja, ein Großkunde ist dazugekommen, genau in dem Jahr. Aber den habe ich ja auch durch meine Haltung gewonnen... glaube ich.“","feedback":"Brauchbar: Du öffnest den Blick für andere Faktoren, ohne zu belehren. Der Hebel ist etwas schwächer, weil Marlene sie sofort wieder in ihre Geschichte einbaut.","score":1,"nextStepId":"step-3"}]},"step-3":{"id":"step-3","speaker":"Marlene","speech":"„Okay, ich geb zu, ein bisschen Glück war auch dabei. Aber ohne mich und meinen Biss hätte der Großkunde nie unterschrieben! Wenn du mich fragst, bin ich zu 95 Prozent sicher, dass es mein Stil war.“","options":[{"text":"„Dann schlage ich dir etwas vor: Gib mir die 95 Prozent schriftlich, und dazu die Garantie, dass dein Seminar bei jedem Teilnehmer das Gleiche bewirkt. Sonst ist das Seminar ja Etikettenschwindel.“","style":"sarkastisch","reaction":"„Jetzt wirst du unverschämt. Garantien gibt es nirgends, das weißt du genau. Ich glaube, wir drehen uns im Kreis.“","feedback":"Du drehst die Frage in eine Falle um und drohst mit Garantien. Das wirkt wie ein Kreuzverhör, nicht wie echte Neugier.","score":-1,"nextStepId":"step-4-struggle"},{"text":"„Spannend, 95 Prozent ist sehr sicher. Was könnte für dich ein Hinweis sein, dass es doch eher Glück und Timing waren? Und woran würdest du das erkennen?“","style":"sokratisch","reaction":"„Woran ich das erkennen würde? ...Hm, wenn jemand genau meine Routine macht und trotzdem baden geht, wäre das wohl ein Hinweis. Darüber habe ich ehrlich noch nie so nachgedacht.“","feedback":"Sehr gut: Du fragst nach dem, was sie umstimmen würde. So prüft Marlene selbst, ob ihre Überzeugung überhaupt widerlegbar ist.","score":3,"nextStepId":"step-4-success"},{"text":"„Dass du Glück zugibst, finde ich stark. Ich frage mich: Wenn du die Zeit zurückdrehen könntest, würde dein Weg wohl noch einmal genauso ausgehen oder ein bisschen anders?“","style":"deeskalierend","reaction":"„Genauso? Ehrlich gesagt, wohl nicht. Der Anruf des Großkunden kam an einem Zufallstag. Aber mein Stil bleibt der Kern, das lasse ich mir nicht nehmen.“","feedback":"Gut gemacht: Du würdigst ihre Ehrlichkeit und lädst sie zum Gedankenexperiment ein. Der Zufall rückt ins Bild, auch wenn Marlene an ihrem Kern festhält.","score":2,"nextStepId":"step-4-success"}]},"step-4-success":{"id":"step-4-success","speaker":"Marlene","speech":"„Weißt du was? Ich glaube weiter an Disziplin. Aber vielleicht sollte ich im Seminar erwähnen, wie viel Glück und Timing bei mir mitspielte. Das macht die Geschichte ehrlicher, oder?“","options":[{"text":"„Das fände ich großartig und mutig. Ehrliche Erfolgsgeschichten helfen mehr als Heldengeschichten. Beim Kaffee besprechen wir, was bei dir Können und was Glück war.“","style":"deeskalierend","reaction":"„Gern! Und ich gebe dir einen Rabatt aufs Seminar, falls es dich noch interessiert.“ *lacht*","feedback":"Mission gelungen! Neugier und Respekt haben Marlene selbst auf den Erzählfehler gebracht, ohne dass sie ihr Gesicht verlieren musste.","score":3},{"text":"„Ehrlich gesagt bin ich froh, dass du das sagst. Das Seminar spare ich mir trotzdem, ich habe schon genug Motivationsredner gehört in meinem Leben.“","style":"ausstieg","reaction":"„Schade, aber verstanden. Danke fürs Zuhören und für die guten Fragen.“","feedback":"Ehrlich und freundlich, die Beziehung bleibt heil. Du hättest Marlenes neue Offenheit aber noch festigen können, statt sofort abzusagen.","score":1}]},"step-4-struggle":{"id":"step-4-struggle","speaker":"Marlene","speech":"„Ich weiß nicht, ob du mich heute provozieren willst. Vielleicht lassen wir das Thema einfach.“","options":[{"text":"„Du hast recht, das wurde zu spitz, tut mir leid. Mich interessiert weiter, welche Rolle Glück bei Erfolg spielt. Lass uns das ein andermal in Ruhe ansehen.“","style":"deeskalierend","reaction":"„Danke, dass du das sagst. Okay, ein andermal. Ich hole uns erst mal was zu trinken.“","feedback":"Guter Rückzug: Du entschuldigst den Ton und hältst die Tür offen. Die Sachfrage bleibt offen, die Beziehung bleibt heil (Gespräch positiv abschließen).","score":2},{"text":"„Wie du meinst. Solange du Erfolg mit Eisbädern erklärst, reden wir eh aneinander vorbei. Ich lasse es, aber überzeugt hast du mich damit nicht.“","style":"sarkastisch","reaction":"„Offenbar ja. Schönen Abend noch.“ *geht*","feedback":"Ein spöttischer Abgang schließt jede Tür. Die Behauptung blieb unberührt, und Marlene fühlt sich nur belächelt.","score":-2}]},"step-fail":{"id":"step-fail","speaker":"Marlene","speech":"„Ich glaube, ich suche mir lieber Gesprächspartner, die mich unterstützen. Viel Spaß noch beim Besserwissen!“ *wendet sich ab*","options":[{"text":"Ende: Marlene fühlte sich angegriffen und hält jetzt noch fester an ihrer Geschichte fest. Rechthaben und Überzeugen sind zweierlei.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst fragen, wie sie es weiß, statt zu sagen, dass sie sich irrt.","feedback":"Street Epistemology greift nicht die Schlussfolgerung an, sondern untersucht das Verfahren, mit Neugier statt Frontalangriff.","score":0}]}},"status":"entwurf","familie":"deutung-von-fakten-trennen","fertigkeit":"F2","stufe":3,"kurz":"Eine runde Erfolgsgeschichte ist noch kein Beweis: Im Rückblick wirkt jede Entscheidung klug, während Glück, Timing und Zufall aus der Erzählung fallen. Weiter hilft die Frage, woher man die Ursache kennt und wie verlässlich dieser Weg zum Wissen ist.","prueffrage":"Was änderte sich im Jahr des Aufschwungs außer der Routine noch, und wie erging es anderen Chefs mit derselben Routine?","quellen":[{"typ":"url","kurz":"Association for Psychological Science (2012): ‘I Knew It All Along…Didn’t I?’ – Understanding Hindsight Bias (zu Roese, N. J.; Vohs, K. D.: Hindsight Bias, Perspectives on Psychological Science 7(5))","oeffentlich":true,"url":"https://www.psychologicalscience.org/news/releases/i-knew-it-all-along-didnt-i-understanding-hindsight-bias.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Street Epistemology: What is Street Epistemology? Definition & Overview","oeffentlich":true,"url":"https://streetepistemology.com/what-is-street-epistemology","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Taleb, N. N. (2007): The Black Swan. The Impact of the Highly Improbable. New York: Random House","oeffentlich":false}],"thema":"Zusammenleben"},{"id":"scen-pruefungsangst-glueck","title":"Mein Glückspulli","subtitle":"Aberglaube, geübt mit kognitiver Entkopplung","character":"Ich selbst, vor der Prüfung","avatar":"🧶","context":"Morgen früh steht deine nächste Prüfung an. Beim Packen stellst du fest: Der graue Pulli, den du bei der letzten bestandenen Prüfung getragen hast, hängt noch im Wäschekorb. Du hörst in dir eine Stimme, die dir erklärt, dass ohne diesen Pulli alles schiefgeht.","goal":"Entkopple dich von deinem Glückspulli: Prüfe die Ritual-Idee wie eine Hypothese, ohne dich selbst dafür zu verurteilen.","bereich":"Ich selbst","laenge":"kurz","ton":"heiter","bestehenAb":4,"lektion":"Ein Ritual verknüpft ein Ereignis mit einem Ergebnis, das zufällig danach kam (Post hoc ergo propter hoc). Das Gefühl von Kontrolle kann beruhigen; einen kausalen Einfluss des Pullis auf die Prüfungsfragen gibt es nicht, und ob Rituale die Leistung verbessern, ist offen. Mit kognitiver Entkopplung kannst du die Idee „Der Pulli wirkt“ als Hypothese prüfen und den Pulli trotzdem anziehen, wenn er dir einfach guttut.","toolRef":"H.1.1","faktenRef":"F.1.2","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Ich selbst, vor der Prüfung","speech":"„Der Pulli muss mit! Letztes Mal habe ich ihn getragen und es hat geklappt. Wenn ich ihn morgen nicht anhabe, ist das, als würde ich das Schicksal herausfordern. Ich will kein Risiko eingehen!“","options":[{"text":"„Das ist völlig albern. Ein Pulli hat noch nie eine Prüfung bestanden. Du bist erwachsen, hör auf mit diesem Quatsch!“","style":"frontal","reaction":"„Albern?! Ich will nur nichts falsch machen, und du machst mich auch noch runter. Jetzt bin ich noch nervöser!“","feedback":"Der Inhalt stimmt, aber die Abwertung trifft die Person statt der Idee. Wer sich angegriffen fühlt, verteidigt sich, statt zu prüfen (Kognitive Entkopplung).","score":-2,"nextStepId":"step-fail"},{"text":"„Stimmt, der Pulli ist wahrscheinlich ein echter Talisman. Dann trage ich ihn sicherheitshalber zusätzlich zu einem zweiten Glücksbringer, vielleicht nehme ich auch noch meinen Glücksstift mit.“","style":"humorvoll","reaction":"„Gute Idee! Dann bin ich doppelt abgesichert. Und wenn ich dann noch dreimal auf Holz klopfe, kann nichts schiefgehen...“","feedback":"Nett gemeint, aber du bestätigst das Ritual, statt es zu hinterfragen. Mehr Talismane heißen mehr Dinge, die man „exakt richtig“ machen muss, und mehr Angst, es zu vermasseln (Red Flags).","score":-1,"nextStepId":"step-fail"},{"text":"„Ich verstehe, dass dich die Prüfung nervös macht. Lass uns kurz fragen: Was war eigentlich sonst noch anders beim letzten Mal, außer dem Pulli?“","style":"sokratisch","reaction":"„Hm... Sonst? Ich habe mehr gelernt als sonst. Und ich hatte gut gefrühstückt. Und die Fragen lagen mir einfach...“","feedback":"Treffer! Du nimmst das Gefühl ernst und öffnest zugleich den Blick auf andere Erklärungen. Der Pulli war nur eines von vielen Dingen, die zeitlich vor dem Erfolg lagen (Post hoc ergo propter hoc).","score":3,"nextStepId":"step-2"}]},"step-2":{"id":"step-2","speaker":"Ich selbst, vor der Prüfung","speech":"„Ja, schon... aber was, wenn der Pulli trotzdem eine Rolle gespielt hat? Dann wäre es doch dumm, ihn wegzulassen. Ich will mir hinterher nicht vorwerfen müssen, dass ich es vermasselt habe.“","options":[{"text":"„Dann lass ihn weg und trag etwas anderes. Du wirst schon sehen, dass nichts passiert. Mutig sein, los!“","style":"frontal","reaction":"„Ohne Pulli? Jetzt, wo ich so aufgeregt bin? Das halte ich nicht aus. Wenn ich durchfalle, bin ich schuld!“","feedback":"Ein erzwungener Bruch mit dem Ritual treibt die Angst hoch. Es geht nicht darum, mutig zu sein, sondern die Idee zu prüfen (Kognitive Entkopplung).","score":-1,"nextStepId":"step-fail"},{"text":"„Gute Frage. Stell dir vor, der Pulli hängt morgen zufällig noch nass im Wäschekorb und du gehst ohne ihn hin und bestehst trotzdem. Würde das etwas über dich als Person aussagen, oder nur über die Hypothese ‚der Pulli wirkt‘?“","style":"sokratisch","reaction":"„Hm... Dann wäre es nur die Hypothese, die falsch war. Ich wäre ja immer noch ich. Und ich hätte sogar etwas gelernt. Das fühlt sich fast leicht an.“","feedback":"Genau die Entkopplung: Die Idee ist etwas, das du hast, nicht etwas, das du bist. So kann das Ritual scheitern, ohne dass du scheiterst.","score":3,"nextStepId":"step-3-success"},{"text":"„Wenn du dich mit dem Pulli wohler fühlst, dann zieh ihn an. Er kann dir ein Gefühl von Sicherheit geben, auch wenn er selbst keine Macht über die Prüfung hat. Und wenn es mal schiefgeht, lag es nicht am Pulli und auch nicht an deinem Glauben.“","style":"deeskalierend","reaction":"„Das klingt beruhigend. Ich nehme ihn mit, weil er mir guttut, nicht weil ich glaube, dass er den Ausgang festlegt. Obwohl... ein bisschen glaube ich es immer noch.“","feedback":"Brauchbar: Das Ritual darf als Beruhigung bleiben (Illusion von Kontrolle), und du nimmst die Selbstvorwürfe heraus. Die Hypothese selbst bleibt aber ungeprüft.","score":1,"nextStepId":"step-3-struggle"}]},"step-3-success":{"id":"step-3-success","speaker":"Ich selbst, vor der Prüfung","speech":"„Okay. Ich trage den Pulli morgen, weil er bequem ist und gut riecht, aber nicht, weil er das Ergebnis bestimmt. Und wenn es schiefgeht, schaue ich mir an, was ich beim Lernen anders machen kann, statt mir Vorwürfe zu machen.“","options":[{"text":"„Perfekt. Dann packen wir jetzt noch die Unterlagen ein und gehen früh schlafen. Der Pulli darf mit, aber die Verantwortung bleibt bei dir.“","style":"humorvoll","reaction":"„*lacht* Abgemacht. Der Pulli hat Urlaub von der Kausalität, und ich schlafe heute Nacht gut.“","feedback":"Mission gelungen! Du hast die Idee „Der Pulli wirkt“ als Hypothese behandelt, ohne dich selbst abzuwerten. Das ist der Kern von Entkopplung.","score":3}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Ich selbst, vor der Prüfung","speech":"„Ich nehme den Pulli einfach mit, zur Sicherheit. Die Nervosität ist trotzdem nicht ganz weg...“","options":[{"text":"„Das ist okay. Atme einmal tief durch, geh die wichtigsten Punkte noch einmal durch und leg dich früh hin. Morgen schauen wir, wie es gelaufen ist.“","style":"deeskalierend","reaction":"„Ja, das hilft. Ich lerne noch eine halbe Stunde und dann ist Schluss für heute.“","feedback":"Solider Ausstieg: Die Angst wird gedämpft, die Hypothese bleibt allerdings ungeprüft. Das Ritual wirkt weiter als Krücke.","score":2}]},"step-fail":{"id":"step-fail","speaker":"Ich selbst, vor der Prüfung","speech":"„Ich lasse den Pulli lieber nicht aus den Augen. Und morgen früh klopfe ich dreimal auf Holz, nur zur Sicherheit...“","options":[{"text":"Ende: Das Ritual wächst weiter, und mit ihm der Druck, es korrekt zu erfüllen. Wer sich angegriffen fühlt oder mitmacht, prüft die Hypothese nicht.","style":"ausstieg","reaction":"Nächstes Mal: das Gefühl ernst nehmen und die Idee als Hypothese betrachten, nicht als Teil von dir.","feedback":"Frage dich: Ist der Pulli ein Werkzeug oder ein Teil meiner Identität? Kognitive Entkopplung trennt beides.","score":0}]}},"status":"entwurf","familie":"was-waere-ohne","fertigkeit":"F2","stufe":2,"kurz":"Ein Ritual verknüpft einen Gegenstand mit einem Erfolg, der zufällig danach kam. Das Gefühl von Kontrolle kann beruhigen, auf die Prüfungsfragen hat der Pulli keinen Einfluss. Die Idee „Er wirkt“ lässt sich wie eine Hypothese prüfen, anziehen darfst du ihn trotzdem.","prueffrage":"Was war bei der letzten bestandenen Prüfung außer dem Pulli noch anders als sonst?","quellen":[{"typ":"url","kurz":"Skinner, B. F. (1948): 'Superstition' in the Pigeon. Journal of Experimental Psychology 38 (Classics in the History of Psychology, York University)","oeffentlich":true,"url":"https://psychclassics.yorku.ca/Skinner/Pigeon/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lang, M.; Krátký, J.; Xygalatas, D. (2020): The role of ritual behaviour in anxiety reduction: an investigation of Marathi religious practices in Mauritius. Phil. Trans. R. Soc. B 375(1805), 20190431 (Volltext in PMC; DOI 10.1098/rstb.2019.0431)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7423266/","abruf":"2026-10-12"},{"typ":"url","kurz":"FORRT: FLoRA Replication Atlas, Eintrag zu Damisch, Stoberock & Mussweiler (2010): Keep Your Fingers Crossed! (Replikation Calin-Jageman & Caldwell 2014, Social Psychology)","oeffentlich":true,"url":"https://forrt.org/flora-replication-atlas/doi/10.1177/0956797610372631/","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"scen-klassenlehrerin-lob-pygmalion","title":"Benny und das Schubladen-Etikett","subtitle":"„Aus mir wird eh nichts“, geübt mit dem Management emotionaler Kosten","character":"Benny, Schüler","avatar":"📒","context":"Benny, 15, bekommt seinen Aufsatz mit einer schwachen Note zurück. Du hilfst ihm bei den Hausaufgaben und siehst, wie er das Heft zuklappt. Er sagt, er sei in Deutsch einfach unbegabt, Üben lohne sich daher nicht.","goal":"Nimm Bennys Frust ernst, hinterfrage sein Etikett „unbegabt“ mit Neugier statt Druck und lenke ihn auf einen kleinen, machbaren nächsten Schritt, ohne dass du dich dabei verausgabst.","bereich":"Schule","laenge":"lang","ton":"ernst","bestehenAb":9,"lektion":"Ein Etikett wie „unbegabt“ kann wie eine Prophezeiung wirken: Wer sich für unbegabt hält, übt weniger und bestätigt das Etikett selbst (Galatea-Effekt). Auch Erwartungen anderer können so wirken, positiv wie negativ (Pygmalion- und Golem-Effekt). Ob eine Fähigkeit wirklich feststeht, zeigt sich nicht an einem Gefühl, sondern an dem, was ein Mensch nach echtem Üben schafft. Und: Du musst nicht jede Schlacht in einem Gespräch gewinnen. Wer seine Energie einteilt, bleibt als verlässlicher Ansprechpartner erhalten.","toolRef":"H.1.2","faktenRef":"E.3.4","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Benny","speech":"„*klappt das Heft zu* Vergiss es. Ich bin in Deutsch einfach unbegabt, das war schon immer so. Aus mir wird da eh nichts. Warum soll ich üben, wenn es sowieso nichts bringt?“","options":[{"text":"„Unsinn, Benny, so etwas wie ‚unbegabt‘ gibt es nicht. Hör auf, dir das einzureden, und setz dich wieder hin. Du schaffst das, du musst nur wollen!“","style":"frontal","reaction":"„Du verstehst das nicht! Du hast leicht reden. Wenn ich nur wollen müsste, hätte ich es längst geschafft. Lass mich in Ruhe!“","feedback":"Pauschales „Du musst nur wollen“ übergeht Bennys Frust und klingt nach Vorwurf. Er fühlt sich nicht gehört und macht dicht.","score":-2,"nextStepId":"step-2-defensive"},{"text":"„Das klingt, als hätte dich die Note ganz schön getroffen. Magst du mir erzählen, woran du merkst, dass du in Deutsch ‚unbegabt‘ bist?“","style":"sokratisch","reaction":"„*zuckt mit den Schultern* Naja... meine Aufsätze sind immer schlecht. Und letzte Woche hat meine Tante zu meiner Mutter gesagt, ich sei halt nicht der Sprachentyp.“","feedback":"Gut: Du nimmst das Gefühl ernst und fragst nach den Gründen, statt zu widersprechen. So wird das Etikett sichtbar und überprüfbar.","score":3,"nextStepId":"step-2-reasons"},{"text":"„Ach, wir haben doch alle unsere Stärken und Schwächen. Dann lassen wir Deutsch eben mal und schauen, was dir mehr Spaß macht.“","style":"ausstieg","reaction":"„Echt? Ja, okay. Ist auch besser so, ich bin eh nicht gut darin.“","feedback":"Du meinst es lieb, bestätigst damit aber das Etikett: Wer nicht übt, hat keine Chance, es zu widerlegen. Das Urteil „unbegabt“ steht danach unangefochten da.","score":-1,"nextStepId":"step-2-comfort"}]},"step-2-reasons":{"id":"step-2-reasons","speaker":"Benny","speech":"„Und in der Schule geht es mir auch so: Die Frau Weber nimmt mich eh nie dran, wenn es um Textarbeit geht. Die weiß wohl auch, dass da nichts kommt.“","options":[{"text":"„Dann beweist doch dein ‚Nie drangenommen werden‘, dass du unbegabt bist, oder? Klingt doch logisch. Wer nicht drankommt, hat eben auch nichts zu sagen.“","style":"sarkastisch","reaction":"„*schnaubt* Na toll. Danke fürs Bestätigen. Dann kann ich ja gleich aufhören.“","feedback":"Sarkasmus hilft hier nicht: Bennys Etikett wirkt jetzt auch noch wie von dir abgesegnet. Seziert wird die Behauptung, nicht der Mensch.","score":-2,"nextStepId":"step-fail"},{"text":"„Moment, das ist spannend: Könnte es sein, dass Frau Weber wenig erwartet, du dich nicht meldest und es dann aussieht, als könntest du es nicht? Wie viel ist Können, wie viel Gewohnheit?“","style":"sokratisch","reaction":"„*schweigt kurz* ...Hm. Ich melde mich in Deutsch wirklich nie, weil ich sowieso denke, dass es falsch ist. Aber vielleicht... keine Ahnung.“","feedback":"Treffend: Du führst behutsam den Kreislauf aus Erwartung, Verhalten und Bestätigung ein (Pygmalion-/Golem-Effekt), ohne ihm etwas vorzuschreiben.","score":3,"nextStepId":"step-3"},{"text":"„Ich hab gelesen, dass Erwartungen von Lehrern Schüler messbar besser machen, Benny. Frau Weber ist also einfach schuld, wenn du schlecht bist, das ist ganz klar.“","style":"frontal","reaction":"„Also liegt es gar nicht an mir? Dann muss ich ja auch nichts ändern, oder?“","feedback":"Die Studienlage ist differenzierter: Solche Effekte sind meist klein, und Schuld zuzuweisen entlässt Benny aus seiner Rolle. Der Mechanismus erklärt, er entschuldigt nicht.","score":0,"nextStepId":"step-3"}]},"step-2-defensive":{"id":"step-2-defensive","speaker":"Benny","speech":"„Ich hab keine Lust auf Belehrungen. Jeder erzählt mir, ich soll mich mehr anstrengen. Das nervt.“","options":[{"text":"„Du hast recht, das war gerade wie ein Befehl, sorry. Ich frag lieber anders: Was nervt dich am meisten an dem Aufsatz?“","style":"deeskalierend","reaction":"„*lässt die Schultern sinken* ...Dass ich nie weiß, was ich schreiben soll. Und dass alle denken, ich sei zu faul.“","feedback":"Gut gerettet: Die Entschuldigung senkt die Spannung und öffnet die Tür wieder. Benny erzählt, was ihn wirklich beschäftigt.","score":2,"nextStepId":"step-3"},{"text":"„Wenn du so weitermachst, wirst du in Deutsch wirklich durchfallen. Dann wirst du dich ärgern.“","style":"frontal","reaction":"„Siehst du, genau das meine ich. Du denkst auch, dass ich es nicht kann. Hab ich doch gesagt.“","feedback":"Drohung statt Gespräch: Du bestätigst indirekt, dass du ihm wenig zutraust. Das verstärkt sein Etikett.","score":-2,"nextStepId":"step-fail"},{"text":"„Okay, ich merke, das bringt heute nichts. Sag Bescheid, wenn du es nochmal probieren willst. Ich bin da.“","style":"ausstieg","reaction":"„*zuckt mit den Schultern, bleibt aber sitzen* Mal sehen... Weißt du, was mich eigentlich stört?“","feedback":"Klug, wenn die Lage verfahren ist: Du schützt deine Energie und die Beziehung. Das Thema ist aber noch nicht gelöst.","score":1,"nextStepId":"step-3"}]},"step-2-comfort":{"id":"step-2-comfort","speaker":"Benny","speech":"„Siehst du, selbst du findest, dass ich in Deutsch wahrscheinlich nichts reißen kann. Dann hab ich ja recht.“","options":[{"text":"„Moment, das habe ich nicht gesagt. Mich interessiert: Woher weißt du, dass es am Können liegt und nicht daran, dass du nie richtig drangeblieben bist?“","style":"sokratisch","reaction":"„*schweigt* ...Ich weiß es nicht. Ich hab ehrlich gesagt nie lange geübt, weil ich dachte, es lohnt sich nicht.“","feedback":"Elegant korrigiert: Du nimmst die Missdeutung zurück und stellst die entscheidende Frage. Das Etikett wird als Annahme sichtbar.","score":3,"nextStepId":"step-3"},{"text":"„Genau, man kann nicht alles. Du bist halt eher der Technik-Typ, das ist völlig in Ordnung und nichts, wofür man sich schämen müsste.“","style":"ausstieg","reaction":"„Ja, voll. Mit Texten kann ich echt nix anfangen.“","feedback":"Du zementierst die Schublade: Aus „schwach in einem Test“ wird „Typ ohne Sprachtalent“. Typ-Etiketten sind besonders hartnäckig.","score":-1,"nextStepId":"step-fail"},{"text":"„Quatsch, du hast mich missverstanden. Ich traue dir viel mehr zu, als du glaubst. Wie wäre es, wenn wir kurz mal hinschauen, was in dem Aufsatz schon klappt?“","style":"deeskalierend","reaction":"„*skeptisch* Da klappt doch nichts... aber meinetwegen, zeig mal.“","feedback":"Zugewandt, ohne zu beschönigen: Du holst die Missdeutung zurück und lenkst auf Konkretes statt auf ein Urteil.","score":2,"nextStepId":"step-3"}]},"step-3":{"id":"step-3","speaker":"Benny","speech":"„Aber selbst wenn ich üben würde: Meine Cousine ist in Deutsch mega gut und gibt keinen Cent aus für Nachhilfe. Die hat das einfach drauf. Ich eben nicht.“","options":[{"text":"„Du vergleichst dich mit jemandem, der ein anderes Leben hat. Was hat deine Cousine in den letzten Jahren gemacht, das du nicht gesehen hast? Liest sie viel?“","style":"sokratisch","reaction":"„Ähm... ja, die liest ständig Bücher. Und schreibt Tagebuch. Das habe ich nie so mitbekommen, ehrlich gesagt.“","feedback":"Treffend: Du stellst die Frage, ob „Begabung“ oft nur sichtbare Übung ist. Ob eine Fähigkeit feststeht, zeigt sich im Üben, nicht im Gefühl.","score":3,"nextStepId":"step-4-practice"},{"text":"„Es stimmt, manche sind einfach bessere Schreiber. Aber du kannst ja trotzdem versuchen, besser zu werden, auch wenn es dir nicht so leicht fällt wie anderen.“","style":"deeskalierend","reaction":"„Hm, versuchen... na gut. Aber nicht so, dass ich mich wieder blamiere.“","feedback":"Okay, aber weich: Du lässt den Gedanken „manche haben es einfach“ stehen. Das Etikett bleibt in Bennys Kopf unberührt.","score":1,"nextStepId":"step-4-practice"},{"text":"„Dann hör auf, dich zu vergleichen, das ist doch Quatsch. Das bringt nichts, wenn du nicht einfach anfängst, und Ausreden helfen dir auch nicht weiter.“","style":"frontal","reaction":"„Du redest wie meine Mutter. ‚Fang einfach an.‘ Wenn das so leicht wäre.“","feedback":"Der Impuls stimmt, doch er klingt wieder nach Druck und spricht Bennys Zweifel nicht an. So wächst nur der Widerstand.","score":-1,"nextStepId":"step-4-practice"}]},"step-4-practice":{"id":"step-4-practice","speaker":"Benny","speech":"„Okay, vielleicht... vielleicht hab ich nie richtig probiert. Aber was soll ich denn machen? Ich weiß ja nicht mal, wo ich anfangen soll.“","options":[{"text":"„Schön, dass du das sagst. Wie wäre es mit einem kleinen Experiment: Eine Woche lang jeden Tag zehn Minuten üben, ohne Note. Am Ende schauen wir, ob sich etwas verändert hat.“","style":"sokratisch","reaction":"„Zehn Minuten... das klingt machbar. Und wenn nichts besser wird?“","feedback":"Stark: Ein kleiner, überprüfbarer Test macht aus dem Etikett eine Hypothese. Wer es probiert, kann es widerlegen oder bestätigen, statt es nur zu glauben.","score":3,"nextStepId":"step-5"},{"text":"„Ich schreibe dir einen Plan: Jeden Tag eine Stunde Deutsch, am Wochenende zwei. Dann wirst du sehen, dass du es kannst, und zwar schneller, als du denkst.“","style":"frontal","reaction":"„*verzieht das Gesicht* Eine Stunde jeden Tag? Das schaffe ich nie. Dann lass ich es lieber gleich.“","feedback":"Zu groß, zu schnell: Ein überzogener Plan scheitert, und das Scheitern bestätigt das Etikett. Besser klein anfangen.","score":-1,"nextStepId":"step-5"},{"text":"„Das entscheidest du selbst, Benny. Ich kann dir nur sagen: Wenn du magst, helfe ich dir, aber ich dränge dich nicht, und ich werde dich auch nicht kontrollieren.“","style":"deeskalierend","reaction":"„Okay... danke. Vielleicht mach ich mal einen Versuch.“","feedback":"Respektvoll, aber vage: Du lässt ihm die Entscheidung, gibst aber keinen konkreten Anker. Etwas konkreter wäre wirksamer.","score":1,"nextStepId":"step-5"}]},"step-5":{"id":"step-5","speaker":"Benny","speech":"„Und was ist, wenn ich nach der Woche immer noch schlecht bin? Dann wisst ihr doch alle: Ich bin halt unbegabt.“","options":[{"text":"„Dann wissen wir nur, dass eine Woche nicht reicht, nicht, dass es nicht geht. Eine Woche ist ein erster Schritt, kein Urteil. Wir schauen auf jede Kleinigkeit.“","style":"sokratisch","reaction":"„*atmet auf* Okay. Das klingt fairer. Dann probier ich es.“","feedback":"Sehr gut: Du verhinderst, dass ein einzelnes Ergebnis zum endgültigen Urteil wird. Fähigkeiten zeigen sich im Verlauf, nicht in einer Momentaufnahme.","score":3,"nextStepId":"step-6"},{"text":"„Wenn du nach einer Woche immer noch schlecht bist, hör ich auf, dich zu nerven. Versprochen. Dann lassen wir das Thema und reden nie wieder darüber.“","style":"humorvoll","reaction":"„*lacht kurz* Okay, abgemacht. Aber nur eine Woche!“","feedback":"Locker und entlastend, aber das Versprechen macht die Woche zur Prüfung: fällt sie schlecht aus, hat Benny sein Urteil schwarz auf weiß.","score":0,"nextStepId":"step-6"},{"text":"„Dann bist du eben unbegabt, und wir hören auf. Aber probier es ehrlich, sonst zählt es nicht, und ich will keine halbherzigen Versuche sehen.“","style":"frontal","reaction":"„Also entscheidet ihr, ob ich es kann. Super. Dann ist ja schon alles klar.“","feedback":"Du stellst das Etikett als mögliches Endergebnis in den Raum und verschärfst den Druck. So wird aus dem Experiment ein Test, den Benny nur verlieren kann.","score":-2,"nextStepId":"step-fail"}]},"step-6":{"id":"step-6","speaker":"Benny","speech":"„Bist du eigentlich nicht genervt von mir? Ich meine, ich sage dir ständig, dass ich es nicht kann, und du hilfst mir trotzdem.“","options":[{"text":"„Ehrlich gesagt: Solche Gespräche kosten Kraft. Deshalb mache ich es in kleinen Schritten. Wichtig ist, dass du weißt, dass du mit mir reden kannst.“","style":"deeskalierend","reaction":"„*lächelt leicht* Das fühlt sich gut an. Ich bin froh, dass du da bist.“","feedback":"Ehrlich und gelassen: Du teilst deine Kräfte ein und zeigst, dass du verlässlich bleibst. Ein Gespräch muss nicht in einer Sitzung gewonnen werden.","score":3,"nextStepId":"step-end-success"},{"text":"„Natürlich nicht, ich helfe dir immer, egal was ist. Ich mache einfach alles, was du brauchst, und zwar jederzeit, ohne dass es mich Kraft kostet.“","style":"affektiv","reaction":"„Echt? Dann kannst du ja gleich meinen Aufsatz schreiben, oder?“","feedback":"Gut gemeint, aber ein Freibrief ohne Grenzen führt zu Überforderung auf deiner Seite und zu Abhängigkeit auf seiner. Einteilen statt verausgaben.","score":-1,"nextStepId":"step-end-struggle"},{"text":"„Ach, du bist schon okay. Ich hab ja auch nichts Besseres vor, und die Zeit habe ich sowieso, da stört es mich nicht weiter.“","style":"sarkastisch","reaction":"„Super. Also bin ich nur dein Zeitvertreib. Danke.“","feedback":"Ein flapsiger Spruch kann hier verletzen: Benny hört, dass er kaum zählt. Gerade bei Selbstzweifeln braucht es Klarheit statt Ironie.","score":-1,"nextStepId":"step-end-struggle"}]},"step-end-success":{"id":"step-end-success","speaker":"Benny","speech":"„Dann fang ich morgen an, zehn Minuten. Und wenn ich nicht weiter weiß, schreibe ich dir. Okay?“","options":[{"text":"„Abgemacht. Und schreib ruhig auch, was gut lief, nicht nur, was schiefging.“","style":"deeskalierend","reaction":"„Mach ich. Danke, dass du mich nicht abgeschrieben hast.“","feedback":"Rund gelungen: Das Etikett ist zur Hypothese geworden, der nächste Schritt ist klein und machbar, und du hast deine Energie eingeteilt statt verbraucht.","score":3},{"text":"„Gut. Aber wenn es nicht klappt, sag es mir sofort, damit wir nicht lange rumdrucksen.“","style":"frontal","reaction":"„Ähm... klar. Dann sage ich lieber nichts, wenn es nicht läuft.“","feedback":"Aus „sag es mir“ hört Benny „enttäusche mich nicht“. Besser ist es, Rückschläge als normal zu rahmen.","score":0},{"text":"„Super, dann bis morgen. Und denk dran: Aus dir wird was.“","style":"humorvoll","reaction":"„Ja, ja. Mal sehen. Aber ich versuch's.“","feedback":"Freundlich und ermutigend, aber vage. Ein zuversichtlicher Satz ersetzt keinen konkreten Plan, hilft aber der Stimmung.","score":1}]},"step-end-struggle":{"id":"step-end-struggle","speaker":"Benny","speech":"„Ich glaube, ich schaffe das heute nicht mehr. Ich bin müde.“","options":[{"text":"„Das ist völlig okay. Wir machen morgen weiter, ganz entspannt. Gönn dir heute eine Pause.“","style":"deeskalierend","reaction":"„Danke. Bis morgen dann.“","feedback":"Ordentlicher Abschluss: Du verschiebst, ohne zu verurteilen, und schützt die Beziehung. Das Experiment bleibt allerdings ohne konkreten Termin offen.","score":1},{"text":"„Du willst schon aufgeben? Dann ist das Ganze sinnlos, und ich habe meine Zeit umsonst verschwendet.“","style":"frontal","reaction":"„Siehst du, genau deshalb habe ich keinen Bock auf dich.“","feedback":"Der Vorwurf kippt die Stimmung: Benny zieht sich zurück, und das Etikett bekommt neue Nahrung.","score":-2},{"text":"„Kein Problem. Schlaf gut, wir sehen uns morgen, und danach reden wir einfach weiter, wo wir aufgehört haben.“","style":"ausstieg","reaction":"„Ja, gute Nacht.“","feedback":"Neutral und freundlich. Der Faden des Experiments bleibt dabei aber lose.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Benny","speech":"„Ich hab's ja gewusst. Egal, was ich mache, es kommt eh nichts dabei raus.“ *steht auf und geht*","options":[{"text":"Ende: Benny fühlt sich bestätigt in seinem Etikett, und das Gespräch hat es eher verfestigt als geöffnet.","style":"ausstieg","reaction":"Das Etikett wirkt wie eine Prophezeiung: Wer nichts versucht, bestätigt es selbst.","feedback":"Beim nächsten Mal: erst zuhören und nachfragen, dann einen kleinen, überprüfbaren Schritt anbieten. So bleibt Benny im Gespräch und das Etikett prüfbar.","score":0}]}},"status":"entwurf","familie":"erwartung-erfuellt-sich","fertigkeit":"F2","stufe":4,"kurz":"Ein Etikett wie „unbegabt“ kann sich selbst erfüllen: Wer sich dafür hält, übt weniger und bestätigt es so. Ob eine Fähigkeit feststeht, zeigt sich erst nach echtem Üben, nicht an einem Gefühl. Wer dabei seine Kraft einteilt, bleibt als Ansprechpartner erhalten.","prueffrage":"Wie oft und wie lange hat Benny in Deutsch schon geübt, bevor er sich das Urteil „unbegabt“ gab?","quellen":[{"typ":"url","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies: Knowns and Unknowns, Resolved and Unresolved Controversies. Personality and Social Psychology Review 9(2) (Abstract bei PubMed; DOI 10.1207/s15327957pspr0902_3)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/15869379/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Leung, A.; Sy, T. (2018): I Am as Incompetent as the Prototypical Group Member: An Investigation of Naturally Occurring Golem Effects in Work Groups. Frontiers in Psychology 9","oeffentlich":true,"doi":"10.3389/fpsyg.2018.01581","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rosenthal, R.; Jacobson, L. (1966): Teachers’ Expectancies: Determinants of Pupils’ IQ Gains. Psychological Reports 19(1)","oeffentlich":false,"doi":"10.2466/pr0.1966.19.1.115"}],"thema":"Zusammenleben"},{"id":"scen-schwester-dunkelziffer","title":"Pia will alles zurückholen","subtitle":"Verluste zurückholen, geübt mit intellektueller Barmherzigkeit","character":"Pia, Schwester","avatar":"💸","context":"Beim Sonntagskaffee an Pias Küchentisch zückt deine Schwester stolz einen Zettel. Sie spielt seit sechs Wochen Lotto und hat bisher nur verloren. Jetzt hat sie einen Plan: Weil ihre Lieblingszahl 13 lange nicht gezogen wurde und deshalb „überfällig“ sei, spielt sie nach jeder verlorenen Woche doppelt so viele Felder wie zuvor. Mit dem Gewinn will sie alles zurückholen. Ausgerechnet hat sie das in einer Tabelle.","goal":"Nimm Pia, ihre Mühe und ihren Wunsch, das verlorene Geld zurückzuholen, ernst, und hilf ihr, selbst zu erkennen, dass höhere Einsätze nach Verlusten nichts zurückholen und Aufhören kein Scheitern ist, ohne dass sie sich bloßgestellt fühlt.","bereich":"Familie","laenge":"mittel","ton":"heiter","bestehenAb":6,"lektion":"Lottokugeln wissen nicht, wann sie zuletzt gezogen wurden: Keine Zahl wird „überfällig“, und das Geld der verlorenen Wochen ist weg, egal was jetzt kommt. Mehr Felder erhöhen zwar die Chance auf einen Gewinn, aber nicht die Chance pro eingesetztem Euro, und weil beim Lotto im Schnitt weniger zurückfließt, als eingesetzt wird, wächst mit jedem Verdoppeln vor allem der erwartete Verlust. Weiterzuspielen oder den Einsatz zu erhöhen, um Verluste zurückzuholen, gilt als typisches Merkmal der Glücksspielstörung; ein fester Betrag, der nach Verlusten nicht steigt, ist darum eine klare Grenze. Wer zuerst die Mühe und den Wunsch dahinter würdigt, kann die Rechnung gemeinsam prüfen, ohne den Menschen anzugreifen.","toolRef":"H.1.3","faktenRef":"B.30","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Pia","speech":"„Schau mal, mein Plan! Seit sechs Wochen gewinne ich nichts, aber die 13 wurde ewig nicht gezogen, die ist total überfällig. Darum spiele ich ab jetzt nach jeder verlorenen Woche doppelt so viele Felder. Wenn sie dann kommt, hole ich alles auf einmal zurück! Ich hab das in einer Tabelle ausgerechnet, das war richtig Arbeit!“","options":[{"text":"„Pia, das ist Quatsch. Die Kugeln wissen doch nicht, was letzte Woche war, und dann auch noch verdoppeln? Wie kann man nur so viel Zeit in so einen Unsinn stecken?“","style":"frontal","reaction":"„Wie bitte? Ich dachte, du freust dich, dass ich mir Gedanken mache! Du musst nicht gleich so von oben herab tun. Dann spiel ich eben allein!“ *knüllt den Zettel zusammen*","feedback":"Frontalangriff auf die Person statt auf die Behauptung. Pia hört „Du bist dumm“ und verteidigt ihr System nur noch hartnäckiger. Das Gegenteil von intellektueller Barmherzigkeit.","score":-2,"nextStepId":"step-fail"},{"text":"„Oh wow, das ist ja richtig durchgerechnet! Weißt du was, ich steige mit ein, dann verdoppeln wir zusammen und teilen uns den großen Gewinn.“","style":"humorvoll","reaction":"„Ja, super! Du bist die Beste! Zu zweit können wir noch länger verdoppeln, dann klappt es bestimmt!“","feedback":"Nett gemeint, aber du bestätigst den Irrtum und machst bei der Einsatzsteigerung sogar mit. Das ist Naivität, nicht Barmherzigkeit: Wohlwollen heißt nicht, falsche Annahmen abzusegnen.","score":-1,"nextStepId":"step-2-bluff"},{"text":"„Du hast dir echt Mühe gemacht, und ich verstehe gut, dass du das Geld zurückhaben willst. Erzähl mal: Wie bist du darauf gekommen, dass die 13 jetzt ‚dran‘ ist?“","style":"sokratisch","reaction":"„Naja, das ist doch logisch! Wenn eine Zahl so lange nicht kam, muss sie doch irgendwann wieder dran sein. Das gleicht sich doch aus, oder? Und dann zahlt sich das Verdoppeln aus.“","feedback":"Gut! Du würdigst zuerst die Mühe und den Wunsch, das Verlorene zurückzuholen, und fragst offen nach, statt zu belehren. So macht Pia sichtbar, worauf ihr ganzer Plan steht: auf dem „Ausgleich“, dem typischen Warnsignal des Spielerfehlschlusses.","score":3,"nextStepId":"step-2"}]},"step-2":{"id":"step-2","speaker":"Pia","speech":"„Und selbst wenn es noch ein paar Wochen dauert: Ich verdopple einfach weiter. Irgendwann kommt der Gewinn, und dann ist alles wieder drin. Ich kann doch jetzt nicht aufhören, sonst war das ganze Geld umsonst!“","options":[{"text":"„Genau das ist der Spielerfehlschluss, Pia. Die 13 hat jede Woche dieselbe Chance, und beim Lotto fließt im Schnitt weniger zurück, als eingesetzt wird. Mehr Einsatz heißt im Schnitt nur mehr Verlust. Merk dir das einfach.“","style":"frontal","reaction":"„Ach, jetzt kommst du mit Fachwörtern. Ich bin halt keine Mathematikerin, aber ein Gefühl für Zahlen habe ich trotzdem!“","feedback":"Inhaltlich richtig, aber als fertige Belehrung mit Fachwort. Pia fühlt sich abgekanzelt und wehrt ab, statt selbst zu denken.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Ich verstehe, dass sich Aufhören anfühlt, als wäre alles umsonst gewesen. Lass uns zwei Dinge durchdenken: Woher sollen die Kugeln wissen, dass die 13 lange nicht dran war? Und was würde dich dein Plan in sechs weiteren Wochen kosten, wenn du bei zehn Euro anfängst?“","style":"sokratisch","reaction":"„Hm... woher sollen sie das wissen, die haben ja kein Gehirn. *rechnet* Zehn, zwanzig, vierzig, achtzig, hundertsechzig, dreihundertzwanzig... Moment, das wären zusammen über sechshundert Euro!“","feedback":"Treffer! Mit der Frage nach dem „Gedächtnis“ der Kugeln und einer kleinen Rechnung lässt du Pia selbst sehen, worauf ihr Plan baut: auf einer Chance, die nicht steigt, und auf Einsätzen, die sich jede Woche verdoppeln. Sie darf die Antwort selbst finden.","score":3,"nextStepId":"step-3-success"},{"text":"„Ach, Pia, jetzt lass uns nicht über Mathe reden. Dein Kuchen ist übrigens richtig lecker heute!“","style":"ausstieg","reaction":"„Danke, freut mich! Ich trag den doppelten Einsatz für Samstag trotzdem schon mal in die Tabelle ein.“","feedback":"Der Themenwechsel ist freundlich, lässt den Irrtum und die steigenden Einsätze aber unberührt. Als Rückzug ist das okay, die Chance auf eine gute Frage bleibt ungenutzt.","score":0,"nextStepId":"step-3-struggle"}]},"step-2-bluff":{"id":"step-2-bluff","speaker":"Pia","speech":"„Weißt du, wenn es diese Woche wieder nicht klappt, verdoppeln wir einfach noch mal. Und noch mal. Irgendwann muss die 13 ja kommen, sie wird ja immer überfälliger!“","options":[{"text":"„Pia, stopp mal kurz, da war ich gerade zu schnell begeistert. Ich sehe, wie viel Herzblut du reinsteckst und wie sehr du das Geld zurückwillst. Aber wenn wir nach jedem Verlust verdoppeln, wird es jede Woche teurer. Darf ich dich was zu den Kugeln fragen?“","style":"deeskalierend","reaction":"„Hm, du klingst echt besorgt. Na gut, frag. Aber ich sag dir gleich: Die 13 ist überfällig, das gleicht sich aus.“","feedback":"Gute Korrektur! Du nimmst deine vorschnelle Zustimmung zurück, würdigst Pias Mühe, sprichst offen deine Sorge an und holst sie mit einer Frage zurück ins Gespräch. Den Einsatz nach Verlusten zu steigern, um sie zurückzuholen, ist genau der Punkt, an dem der Spielerfehlschluss teuer wird.","score":2,"nextStepId":"step-2"},{"text":"„Das ist doch Unsinn, Pia! Mit dieser Verdopplungs-Idee ruinierst du dich noch. Du benimmst dich wie die Leute im Kasino, die am Ende alles verlieren, und das will ich bei dir nicht erleben!“","style":"sarkastisch","reaction":"„Jetzt vergleichst du mich mit Spielsüchtigen? Das ist gemein! Ich will gar nicht mehr darüber reden.“","feedback":"Die Sorge ist berechtigt, aber der Vergleich wertet Pia ab. Wer die Person angreift, verliert das Gespräch.","score":-2,"nextStepId":"step-fail"},{"text":"„Na, so schlimm wird es schon nicht werden. Mach einfach mal, irgendwann muss es ja klappen, und dann hast du alles wieder drin.“","style":"ausstieg","reaction":"„Genau, ich wusste, dass du mich verstehst! Dann leg ich gleich noch mal nach.“","feedback":"Den Plan abzunicken, während jemand den Einsatz nach Verlusten immer weiter steigert, ist keine Barmherzigkeit. Du lässt Pia mit dem Irrtum allein.","score":-1,"nextStepId":"step-fail"}]},"step-3-success":{"id":"step-3-success","speaker":"Pia","speech":"„Moment mal... Die Kugeln haben ja wirklich kein Gedächtnis. Dann wird die 13 nicht ‚überfälliger‘, und mit jedem Verdoppeln zahle ich nur mehr, ohne dass sie wahrscheinlicher kommt. Und das Geld der letzten Wochen ist weg, egal was ich jetzt mache, oder?“","options":[{"text":"„Ja, und das zu sehen ist das Schwerste daran. Du hast gerade etwas erkannt, das viele nie hinterfragen. Wenn dir das Tippen Spaß macht, leg dir einen festen Betrag fest, den du verschmerzen kannst, und erhöh ihn nicht, um Verluste zurückzuholen. Und das nächste Kuchenstück geht auf mich, okay?“","style":"humorvoll","reaction":"„*lacht* Das mit dem Kuchen nehme ich dir ab. Und weißt du was? Ich streich das Verdoppeln aus der Tabelle und bleib bei meinem alten Einsatz. Den Zettel hänge ich trotzdem an den Kühlschrank, als Erinnerung.“","feedback":"Mission gelungen! Du hast Pias Mühe und ihren Wunsch, das Verlorene zurückzuholen, ernst genommen, sie selbst auf das fehlende Gedächtnis der Kugeln und die wachsenden Einsätze stoßen lassen und ihr dabei das Gesicht gewahrt. Ein fester Betrag, der nach Verlusten nicht steigt, gibt ihr eine klare Grenze.","score":3}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Pia","speech":"„Ich weiß nicht, du machst mich ganz unsicher. Aber wenn ich jetzt aufhöre, war das ganze Geld umsonst. Und die 13 muss doch irgendwann kommen...“","options":[{"text":"„Ich will dir dein Hobby nicht madigmachen, Pia. Wollen wir es mal durchrechnen? Schreib in deine Tabelle, was dich das Verdoppeln in den nächsten sechs Wochen kosten würde, wenn die 13 nicht kommt, und überleg dir, in welcher Woche du aufhören würdest.“","style":"sokratisch","reaction":"„Hm, okay, das kann ich ja mal machen. Ich schätze, so schlimm wird's nicht. Mal sehen!“","feedback":"Guter Schlenker: Du lädst Pia ein, ihre eigene Tabelle weiterzurechnen und sich vorher eine Grenze zu überlegen. Weil sich der Einsatz jede Woche verdoppelt, wird die Summe schnell größer, als sie gerade schätzt, und diese Erfahrung kann ihr Bild vom „Zurückholen“ besser korrigieren als jede Erklärung.","score":2},{"text":"„Also gut, wenn du meinst. Ich sag nichts mehr. Mach, was du willst, es ist ja dein Geld und deine Entscheidung, nicht meine.“","style":"sarkastisch","reaction":"„Na gut, dann eben so. Ich hab ja gleich gewusst, dass du es nicht verstehst.“","feedback":"Beleidigtes Zurückziehen hilft niemandem. Pia fühlt sich abgeschoben, und das System bleibt unangetastet.","score":-1},{"text":"„Du hast recht, das war genug Zahlenzauber für einen Sonntag. Ich mag es, dass du dir überhaupt Gedanken machst, und wir können gern ein andermal weiterknobeln.“","style":"deeskalierend","reaction":"„Ja, lass uns das ein andermal machen. Danke, dass du mich nicht auslachst.“","feedback":"Sanfter Ausstieg: Die Beziehung bleibt heil, und die Tür für ein späteres Gespräch ist offen. Die Sachfrage bleibt allerdings ungeklärt.","score":1}]},"step-fail":{"id":"step-fail","speaker":"Pia","speech":"„Ich tippe, wie ich will. Und diese Woche setze ich noch mehr als sonst!“","options":[{"text":"Ende: Pia hält jetzt noch fester an ihrem Plan fest und steigert ihren Einsatz weiter.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst die Mühe und den Wunsch, das Verlorene zurückzuholen, würdigen, dann mit einer Frage nach dem „Gedächtnis“ der Kugeln und den wachsenden Einsätzen ansetzen.","feedback":"Frage dich: Wollte ich Pia überzeugen oder bloßstellen? Intellektuelle Barmherzigkeit greift die Behauptung an, nicht den Menschen.","score":0}]}},"status":"entwurf","familie":"zufall-ohne-gedaechtnis","fertigkeit":"F4","stufe":2,"kurz":"Lottokugeln haben kein Gedächtnis: Keine Zahl wird „überfällig“, und jeder Einsatz ist im Schnitt ein Verlustgeschäft. Wer nach Verlusten höher setzt, um alles zurückzuholen, erhöht vor allem den erwarteten Verlust. Würdige erst den Wunsch dahinter, dann rechnet gemeinsam.","prueffrage":"Was müsste die Ziehung über Pias verlorene Wochen wissen, damit sich ihr verdoppelter Einsatz eher auszahlt?","quellen":[{"typ":"url","kurz":"Clotfelter, C. T.; Cook, P. J. (1991): The \\"Gambler's Fallacy\\" in Lottery Play. NBER Working Paper 3769","oeffentlich":true,"url":"https://www.nber.org/papers/w3769","abruf":"2026-10-12"},{"typ":"url","kurz":"Chen, D.; Moskowitz, T. J.; Shue, K. (2016): Decision-Making under the Gambler's Fallacy. NBER Working Paper 22026","oeffentlich":true,"url":"https://www.nber.org/papers/w22026","abruf":"2026-10-12"},{"typ":"url","kurz":"Malpas, J.: Donald Davidson. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","seite":"Abschn. 3.3","abruf":"2026-10-12"},{"typ":"doi","kurz":"Banerjee, N.; Chen, Z.; Clark, L.; Noël, X. (2023): Behavioural expressions of loss-chasing in gambling: A systematic scoping review. Neuroscience & Biobehavioral Reviews 153, 105377","oeffentlich":true,"doi":"10.1016/j.neubiorev.2023.105377","url":"https://pubmed.ncbi.nlm.nih.gov/37648042/","abruf":"2026-10-13"}],"thema":"Geld und Zahlen"},{"id":"scen-wuensche-einbildung-ich","title":"Ich bin nicht voreingenommen","subtitle":"Der blinde Fleck bei mir selbst, geübt mit Emotion und Motivation","character":"Ich selbst (Spiegel-Ich)","avatar":"🪞","context":"Du hast gerade einen Artikel über kognitive Verzerrungen gelesen und warst begeistert: Er beschreibt haargenau deinen Schwager, deinen Kollegen und halb Twitter. Abends meldet sich dein Spiegel-Ich, das sich für ziemlich objektiv hält, und möchte sich diesen Gedanken einmal in Ruhe gönnen.","goal":"Bring dein Spiegel-Ich dazu, den blinden Fleck bei sich selbst zu suchen, statt nur bei anderen, und zwar ohne es zu beschämen.","bereich":"Ich selbst","laenge":"mittel","ton":"heiter","bestehenAb":6,"lektion":"Verzerrungen erkennen wir bei anderen leichter als bei uns, denn bei uns selbst suchen wir vor allem nach unseren guten Absichten, und die finden wir fast immer. Wissen über Denkfehler schützt nicht automatisch, und auch dein Gefühl, „ganz sachlich“ zu sein, ist ein Gefühl, das mitlenkt. Hilfreich sind die Aktivierungsfrage „Angenommen, ich liege falsch: Was wäre das stärkste Argument der Gegenseite?“ und ein Gegenüber, das dein Argument prüft (Advocatus Diaboli).","toolRef":"H.1.4","faktenRef":"B.29","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Spiegel-Ich","speech":"„Weißt du, ich habe da gerade diesen Artikel über Denkfehler gelesen. Mein Schwager ist ja der Klassiker für Bestätigungsfehler, der liest nur, was ihm passt. Zum Glück kenne ich all diese Fallen. Ich falle auf so etwas nicht herein.“","options":[{"text":"„Wenn du die Fallen kennst, bist du praktisch immun. Dann musst du dich ja nicht mehr kontrollieren, du bist ja das gut informierte Exemplar der Familie.“","style":"humorvoll","reaction":"„Genau! Endlich versteht mich jemand. *lehnt sich zufrieden zurück* Ich bin eben ein rationaler Mensch, und in Diskussionen merke ich das auch immer.“","feedback":"Du bestätigst genau den Gedanken, der den blinden Fleck nährt: Wissen über Fehlschlüsse macht uns oft nur besser darin, sie bei anderen zu entdecken.","score":-2,"nextStepId":"step-fail"},{"text":"„Klingt, als wärst du ziemlich sicher. Mich würde interessieren: Woran würdest du es merken, wenn du selbst gerade voreingenommen wärst?“","style":"sokratisch","reaction":"„Hm. Woran ich es merken würde? *kratzt sich am Kopf* Na ja, ich würde in mich hineinhorchen und feststellen, dass ich eine Seite bevorzuge.“","feedback":"Gut: Du stellst eine ehrliche Frage statt eines Urteils. Das Spiegel-Ich muss sein Prüfverfahren selbst benennen, und genau dort zeigt sich gleich der Introspektions-Trugschluss.","score":3,"nextStepId":"step-2"},{"text":"„Moment, das stimmt doch gar nicht, du bist genauso voreingenommen wie dein Schwager. Dass du das nicht siehst, ist ja gerade das Problem!“","style":"frontal","reaction":"„Wie bitte?! Ausgerechnet ich? *verschränkt die Arme* Ich habe das sogar nachgelesen. Du hast offenbar den Teil mit dem Quellenstudium verpasst.“","feedback":"Frontaler Zugriff auf das Selbstbild. Der Kern stimmt, aber so geht das Ego in Verteidigung, und Verteidigung ist das Gegenteil von Neugier.","score":-1,"nextStepId":"step-struggle"}]},"step-2":{"id":"step-2","speaker":"Spiegel-Ich","speech":"„Beim Schwager sehe ich es am Verhalten: Er ignoriert meine besten Argumente und wiederholt widerlegte Punkte. Bei mir selbst, da schaue ich nach innen, und dort finde ich nichts. Ich will ja wirklich nur die Wahrheit finden.“","options":[{"text":"„Dann hast du den Beweis, dass du neutral bist. Wenn nach gründlichem Nachsehen nichts da ist, ist auch nichts da, und du kannst beruhigt weitermachen.“","style":"affektiv","reaction":"„Eben! Wer sucht und nichts findet, hat nichts. Also liege ich richtig und mein Schwager falsch, schön einfach.“","feedback":"Fehlschluss: Die meisten Verzerrungen laufen unbewusst ab und sind per Definition nicht durch bloßes Nach-innen-Schauen zu finden. Wer nichts findet, schließt fälschlich auf „nichts da“.","score":-2,"nextStepId":"step-fail"},{"text":"„Du beurteilst deinen Schwager nach seinem Verhalten und dich selbst nach deinen Absichten. Wie oft suchst du bei dir aktiv nach Fehlern in den eigenen Argumenten?“","style":"sokratisch","reaction":"„*zögert* Du meinst... ich messe uns mit zweierlei Maß? Bei ihm zählt, was er tut, bei mir, was ich vorhabe. Ehrlich gesagt suche ich eher Fehler bei den anderen. Neunzig zu zehn, schätze ich.“","feedback":"Treffer! Du benennst den Introspektions-Trugschluss als Frage statt als Vorwurf, und das Spiegel-Ich erkennt das Muster selbst. Das hilft mehr als jede Belehrung.","score":3,"nextStepId":"step-3-success"},{"text":"„Keine Sorge, das liegt in der Natur des Menschen. Mach dir keinen Kopf, die meisten merken das bei sich nie, und es schadet ja auch niemandem.“","style":"ausstieg","reaction":"„Stimmt, kann man nichts machen. Gut, dass ich zumindest einer von den Aufgeklärten bin. Ich lehne mich dann mal zurück.“","feedback":"Zu weich: Du beruhigst, statt etwas in Gang zu bringen. Der blinde Fleck bleibt unangetastet, und das Spiegel-Ich fühlt sich sogar bestätigt.","score":0,"nextStepId":"step-struggle"}]},"step-3-success":{"id":"step-3-success","speaker":"Spiegel-Ich","speech":"„Okay, das ist unangenehm. Aber ich glaube, es stimmt. Als ich neulich über die Ernährungsdebatte gestritten habe, habe ich nur die Studien zitiert, die mir passten, und mir dabei ziemlich schlau vorgekommen. Und weißt du, was ich erst jetzt merke? Dieses Gefühl, überlegen zu sein, war angenehm. Es hat mich regelrecht angetrieben.“","options":[{"text":"„Genau dieses Gefühl ist ein Signal. ‚Ich bin der Vernünftige‘ ist Teil der Verzerrung und lenkt wie ein Steuerrad mit. Prüfe: Welche Argumente der Gegenseite habe ich ausgeblendet?“","style":"sokratisch","reaction":"„Als Datenpunkt, nicht als Beweis. *nickt* Das gefällt mir. Ich nehme das Gefühl ernst, aber ich lasse es nicht allein entscheiden. Und ich habe da wirklich noch ein paar Argumente liegen lassen.“","feedback":"Rundum stimmig: Das Gefühl der Überlegenheit gehört zum Lenkrad, das mitsteuert. Es wird ernst genommen, aber mit Prüffragen gegengeprüft. So bleibt die Neugier an Bord.","score":3,"nextStepId":"step-4-success"},{"text":"„Dann sag dir ab sofort bei jeder Diskussion: Ich bin nicht überlegen, ich irre mich auch, ich bin voreingenommen. Und fertig, dann klappt es ganz von allein.“","style":"frontal","reaction":"„Das klingt streng. Das Mantra aufsagen kann ich, aber mir fehlt noch ein konkreter Moment, in dem es mir hilft. Es bleibt ein Satz.“","feedback":"Gut gemeint, aber ein Mantra ohne Übung bleibt hohl. Hilfreicher wäre eine konkrete Prüffrage in der Situation, statt pauschaler Selbstvorwürfe.","score":1,"nextStepId":"step-4-struggle"},{"text":"„Dann hör einfach auf, dich überlegen zu fühlen. Gefühle stören nur, wenn man klar denken will, also schalte sie am besten ab, dann bist du objektiv.“","style":"affektiv","reaction":"„Gefühle abschalten? *lacht kurz* Dann könnte ich auch gleich aufhören, überhaupt Entscheidungen zu treffen. Das hört sich nach Wahnsinn an.“","feedback":"Falsche Trennung von Logik und Gefühl: Nach Damasios einflussreicher, aber umstrittener Hypothese lenken Emotionen die Wahl, die Logik ist der Motor. Das Ziel ist nicht Abschalten, sondern Gegenprüfen.","score":-2,"nextStepId":"step-fail"}]},"step-4-success":{"id":"step-4-success","speaker":"Spiegel-Ich","speech":"„Also schön. Nur: Ich kann den Fehler offenbar nicht von innen finden. Wie komme ich an die blinden Flecken heran, die ich selbst nicht sehe?“","options":[{"text":"„Such dir jemanden, dem du vertraust und der anderer Meinung ist, und bitte ihn, dein Argument zu zerlegen. Du hörst nur zu. Frag auch: Was wäre das stärkste Gegenargument?“","style":"sokratisch","reaction":"„*lacht* Ich frage meinen Schwager. Das wird wehtun, aber ich bin neugierig geworden. Danke, dass du mich nicht abgekanzelt hast.“","feedback":"Auf den Punkt: Von innen findest du den Fehler nicht, deshalb braucht es Feedback von außen (Advocatus Diaboli; Stahlmann-Argument). Die Neugier ist geweckt, und das Spiegel-Ich bleibt mit Würde im Spiel.","score":3},{"text":"„Lies noch mehr Bücher über Denkfehler, dann hast du alle Fallen im Kopf und merkst es sofort, wenn du selbst in eine hineintappst, und kannst dich dagegen wappnen.“","style":"humorvoll","reaction":"„Gute Idee, ich kaufe gleich drei weitere. *grinst* Dann bin ich bald richtig gut darin, Fehler zu erkennen. Meine Familie wird staunen.“","feedback":"Ironisch: Mehr Wissen über Fehlschlüsse verbessert vor allem die Fehlersuche bei anderen. Der eigene Fleck bleibt, solange kein Gegenüber ihn zeigt.","score":-1},{"text":"„Grüble regelmäßig in Ruhe über dich selbst nach, dann siehst du mit der Zeit, wo du voreingenommen bist, und kannst gegensteuern, ohne dass dir jemand hineinredet.“","style":"ausstieg","reaction":"„Gute Idee, ich setze mich heute Abend hin und denke gründlich nach. Das klappt bestimmt.“","feedback":"Besser als nichts, aber zu wenig: Unbewusste Verzerrungen entziehen sich dem bloßen Nachgrübeln. Ein externer Check macht den Unterschied.","score":1}]},"step-4-struggle":{"id":"step-4-struggle","speaker":"Spiegel-Ich","speech":"„Ich verstehe das Prinzip, aber so richtig greifen kann ich es noch nicht.“","options":[{"text":"„Dann machen wir es klein: Schreib auf, wann du in der letzten Woche selbst einen Denkfehler gemacht haben könntest. Ein bis zwei Sätze, nichts Großes.“","style":"sokratisch","reaction":"„Ein bis zwei Sätze, das schaffe ich. Vermutlich wird es unangenehm, aber ich probiere es.“","feedback":"Gut gerettet: Die Werkbank-Übung aus „Der blinde Fleck des Skeptikers“ macht den blinden Fleck greifbar. Dass sie unangenehm ist, ist ein gutes Zeichen.","score":2},{"text":"„Dann lass es einfach, das ist ohnehin schwer zu fassen. Vielleicht verstehst du es später mal, wenn du mehr Erfahrung damit gesammelt hast.“","style":"ausstieg","reaction":"„Wahrscheinlich. Ich lasse es erst mal liegen und gehe zu etwas Konkretem über.“","feedback":"Aufgeben ist verständlich, bringt hier aber nichts: Ohne konkrete Übung bleibt der blinde Fleck abstrakt.","score":0}]},"step-struggle":{"id":"step-struggle","speaker":"Spiegel-Ich","speech":"„Ich weiß nicht. Du machst mich gerade ein bisschen unsicher. Ich habe doch lange gebraucht, um mir ein klares Bild von der Welt zu bauen.“","options":[{"text":"„Dein Bild darf bleiben, es geht nicht um Schuld. Lass uns klein anfangen: In welcher Diskussion warst du zuletzt sicher, völlig objektiv zu sein?“","style":"deeskalierend","reaction":"„*atmet durch* Die über das Essen neulich. Ich war mir so sicher. ...Ich vermute, ich habe da auch nur gehört, was ich hören wollte.“","feedback":"Guter Neustart: Du nimmst den Druck raus, bleibst bei der Sache und öffnest den Blick auf ein konkretes eigenes Beispiel.","score":2,"nextStepId":"step-3-success"},{"text":"„Dann belassen wir es dabei. Du hast ein klares Bild, und das Thema war ohnehin nur ein Gedankenspiel, das uns nicht weiter beschäftigen muss.“","style":"ausstieg","reaction":"„Genau, nur ein Gedankenspiel. Danke fürs Verständnis. Ich bleibe bei meinem Bild.“","feedback":"Rückzug ohne Brücke: Das Gespräch endet harmonisch, aber das Spiegel-Ich nimmt nichts mit.","score":0,"nextStepId":"step-fail"}]},"step-fail":{"id":"step-fail","speaker":"Spiegel-Ich","speech":"„Gut, dass wir das geklärt haben. Ich bleibe bei meinem Bild: Die anderen machen die Denkfehler, ich bin die Ausnahme. *zufriedenes Nicken*“","options":[{"text":"Ende: Das Spiegel-Ich fühlt sich bestätigt und der blinde Fleck bleibt unberührt. Wer nur bei anderen sucht, findet nur bei anderen.","style":"ausstieg","reaction":"„*nickt zufrieden* Schön, dass das geklärt ist.“","feedback":"Der blinde Fleck schützt das Ego. Er löst sich nicht durch Rechthaben, sondern durch Neugier, Prüffragen und Feedback von außen. Beim nächsten Mal zuerst fragen, wie das Spiegel-Ich eigene Verzerrungen erkennen würde, statt zu urteilen oder zu bestätigen.","score":0}]}},"status":"entwurf","familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","stufe":3,"kurz":"Denkfehler fallen bei anderen leichter auf als bei sich selbst, weil man andere nach ihrem Verhalten und sich selbst nach den guten Absichten beurteilt. Wissen über Denkfehler schützt nicht automatisch, und auch das Gefühl, „ganz sachlich“ zu sein, lenkt mit.","prueffrage":"Woran machst du die Voreingenommenheit deines Schwagers fest, und welches beobachtbare Zeichen würde sie bei dir selbst verraten?","quellen":[{"typ":"url","kurz":"West, R. F.; Meserve, R. J.; Stanovich, K. E. (2012): Cognitive Sophistication Does Not Attenuate the Bias Blind Spot. Journal of Personality and Social Psychology 103(3) (Abstract bei PubMed; DOI 10.1037/a0028857)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/22663351/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lord, C. G.; Lepper, M. R.; Preston, E. (1984): Considering the opposite: a corrective strategy for social judgment. Journal of Personality and Social Psychology 47(6) (Abstract bei PubMed)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/6527215/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Pronin, E.; Lin, D. Y.; Ross, L. (2002): The Bias Blind Spot: Perceptions of Bias in Self Versus Others. Personality and Social Psychology Bulletin 28(3)","oeffentlich":false}],"thema":"Psychologie"},{"id":"scen-erbse-schlau-bio","title":"Svens Bio-Brain-Boost","subtitle":"„Natürlich ist besser“, geübt mit Street Epistemology","character":"Sven","avatar":"🥬","context":"Dein Freund Sven kommt strahlend zum Kaffee und stellt ein Fläschchen mit grünem Pflanzenextrakt auf den Tisch. Es kostet ein kleines Vermögen, soll sein Gedächtnis auf Höchstform bringen und ist „rein natürlich, ohne Chemie“. Schon holt er die Dosierempfehlung hervor, die er nach Gefühl zu verdoppeln plant.","goal":"Bring Sven mit neugierigen Fragen dazu, selbst zu prüfen, woher seine Sicherheit stammt, statt ihm seine Begeisterung auszureden.","bereich":"Freunde","laenge":"mittel","ton":"heiter","bestehenAb":6,"lektion":"„Natürlich“ sagt nichts über Sicherheit oder Wirkung: Der Knollenblätterpilz ist ebenso natürlich wie Arsen, und alles, was aus Materie besteht, ist Chemie. Mit Street Epistemology greifst du nicht die Schlussfolgerung an, sondern fragst nach dem Weg dorthin, nach Sicherheit, Methode und möglichen Alternativerklärungen. So bleibt Sven ein Freund mit Gründen und bekommt trotzdem etwas zum Nachdenken.","toolRef":"H.2.2","faktenRef":"B.14","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Sven","speech":"„Schau mal, mein neues Wundermittel! Rein pflanzlich, null Chemie, nur das, was die Natur uns gibt. Seit drei Tagen nehme ich es und mein Kopf ist so klar wie nie! Die Natur weiß einfach am besten, was gut für uns ist.“","options":[{"text":"„Sven, der Satz ‚Die Natur weiß, was gut für uns ist‘ ist ein Fehlschluss. Auch Knollenblätterpilze sind natürlich. Das Zeug ist rausgeschmissenes Geld, glaub mir.“","style":"frontal","reaction":"„Na toll, Herr Professor. Du musst immer gleich alles zerpflücken! Ich merke es doch an meinem eigenen Kopf, da brauche ich keine Belehrung.“ *drückt das Fläschchen an die Brust*","feedback":"Frontalangriff: Der Hinweis auf natürliche Gifte stimmt, kommt aber als Urteil über Svens Kopf und Geldbeutel. Sven geht in die Verteidigung und hört nicht mehr zu.","score":-2,"nextStepId":"step-fail"},{"text":"„Klingt spannend! Erzähl mal: Was genau stellt das Mittel mit deinem Kopf an, und wie bist du darauf gekommen?“","style":"sokratisch","reaction":"„*lehnt sich zurück, froh über das Interesse* Also, es soll die Merkfähigkeit steigern. Eine Kollegin schwört darauf, und als ich es genommen habe, lief die Arbeit plötzlich wie von selbst.“","feedback":"Gute Eröffnung der Street Epistemology: Du klärst zuerst die Behauptung und baust Beziehung auf, ohne zu bewerten. So kommt die Methode hinter Svens Überzeugung zum Vorschein.","score":3,"nextStepId":"step-2"},{"text":"„Klarer Kopf aus der Flasche? Da will ich mehr wissen! Hast du schon mal andere Pflanzenmittel probiert?“","style":"humorvoll","reaction":"„Ja, Ginkgo, Ginseng, das ganze Programm! Aber das hier ist das beste, und die Natur ist ja auch der beste Chemiker.“","feedback":"Freundlich und beziehungsstärkend, aber du kommst vom Thema ab: Die Frage nach Svens Methode bleibt offen, und der Satz „Natur ist der beste Chemiker“ steht unwidersprochen im Raum.","score":1,"nextStepId":"step-2"}]},"step-2":{"id":"step-2","speaker":"Sven","speech":"„Das Schöne ist ja: Das ist reine Pflanze, kein Labor, keine Chemie. Da kann man gar nichts falsch machen, ich nehme sicherheitshalber gleich die doppelte Menge.“","options":[{"text":"„Wenn du eine Skala von 0 bis 100 nimmst: Wie sicher bist du, dass das Mittel bei dir wirkt und unbedenklich ist?“","style":"sokratisch","reaction":"„*überlegt* Hm, Sicherheit ... so 90 Prozent, würde ich sagen. Warum fragst du?“","feedback":"Treffer! Die 0-100-Skala macht aus „Ja oder Nein“ ein Spektrum und öffnet Raum für Zweifel, ohne Druck aufzubauen.","score":3,"nextStepId":"step-3"},{"text":"„Alles ist Chemie, Sven! Wasser ist Chemie, dein Apfel ist Chemie. Dein Satz ‚keine Chemie‘ ist physikalisch gesehen Quatsch.“","style":"sarkastisch","reaction":"„Ach, jetzt wirst du pedantisch. Du weißt genau, was ich meine: Das Zeug ist halt nicht künstlich zusammengepanscht.“","feedback":"Inhaltlich richtig (Alles Stoffliche ist Chemie), aber die spitze Belehrung lässt Sven auf dem Wort herumreiten. Die Frage nach seiner Methode bleibt ungestellt.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Von der doppelten Menge würde ich die Finger lassen. Halte dich an die Packungsangabe.“","style":"frontal","reaction":"„Wieso denn das? Es ist doch pflanzlich! Mehr Natur kann doch nicht schaden.“","feedback":"Der Rat ist vernünftig, kommt aber als Anweisung. Dass bei Pflanzenstoffen die Dosis zählt, erkennt Sven so nicht selbst, und du erfährst nichts über seine Gründe.","score":0,"nextStepId":"step-3-struggle"}]},"step-3":{"id":"step-3","speaker":"Sven","speech":"„Ich frag ja nur, weil ... ach so, du willst wissen, was mich so sicher macht? Die Kollegin schwört darauf, und ich merke es ja selbst: Seit ich es nehme, bin ich viel fokussierter. Das ist doch Beweis genug, oder?“","options":[{"text":"„Danke, dass du das so offen sagst. Du verlässt dich also auf deine eigene Erfahrung und die deiner Kollegin. Ist das der Hauptgrund, oder gibt es noch einen anderen?“","style":"sokratisch","reaction":"„Nein, eigentlich ist das der Hauptgrund. Und es klingt ja auch logisch: Pflanzen sind seit Jahrtausenden Medizin.“","feedback":"Sehr gut: Du spiegelst die Methode wertschätzend und lässt Sven sie selbst benennen. Genau das ist die Schlüsselfrage der Street Epistemology.","score":3,"nextStepId":"step-4"},{"text":"„Das ist eine reine Anekdote, Sven. Persönliche Erfahrung ist wissenschaftlich wertlos, und deine Kollegin ist kein Beweis, auch wenn sie noch so überzeugt ist.“","style":"frontal","reaction":"„Wertlos?! Ich spüre den Unterschied jeden Tag. Du glaubst mir nicht, dass es mir besser geht, ja?“","feedback":"Frontal: Du wertest Svens Erfahrung ab, bevor er überhaupt über ihre Grenzen nachdenken konnte. Das Gespräch kippt auf Beziehungsebene.","score":-2,"nextStepId":"step-fail"},{"text":"„Fokussiert, das klingt super! Ich bin gespannt, ob das anhält. Wie lange nimmst du es schon? Vielleicht probiere ich es auch mal aus.“","style":"humorvoll","reaction":"„Erst drei Tage, aber es wirkt jetzt schon. Die Natur braucht eben keine Zeit zum Aufwärmen!“","feedback":"Freundlich, aber du lässt die Gelegenheit verstreichen, Svens Methode zu hinterfragen. Das Gespräch tröpfelt weiter, ohne an Tiefe zu gewinnen.","score":0,"nextStepId":"step-4-struggle"}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Sven","speech":"„Ich verstehe nicht, warum du so skeptisch bist. Ich nehme es doch nur, weil es mir guttut. Willst du mir das etwa kaputtreden?“","options":[{"text":"„Nein, ganz und gar nicht, entschuldige. Ich bin einfach neugierig, wie du darauf gekommen bist und was dich so sicher macht.“","style":"deeskalierend","reaction":"„*entspannt sich* Na gut. Die Kollegin schwört darauf, und ich merke es ja selbst, ich bin viel fokussierter seitdem.“","feedback":"Gute Reparatur: Du nimmst den Druck raus und kehrst zur offenen Frage nach Svens Gründen zurück.","score":2,"nextStepId":"step-4"},{"text":"„Ja, ehrlich gesagt will ich dir sagen, dass du auf Marketing hereinfällst und dein Geld verschwendest, wie so viele andere auch.“","style":"sarkastisch","reaction":"„Jetzt reicht es aber! Dann trinke ich es eben allein.“","feedback":"Das ist ein Angriff auf Sven und seine Entscheidung. Er fühlt sich bloßgestellt und verabschiedet sich innerlich aus dem Gespräch.","score":-2,"nextStepId":"step-fail"},{"text":"„Schon gut, vergiss es, ich sage nichts mehr. Trink einfach, was du magst, und lass dich von mir nicht weiter stören.“","style":"ausstieg","reaction":"„Na also, geht doch. Wollen wir noch ein Stück Kuchen?“","feedback":"Ein friedlicher, aber vorschneller Ausstieg (verlangt Neugier statt Rückzug): Die Freundschaft bleibt heil, doch kein Gedanke wird angestoßen.","score":0,"nextStepId":"step-4-struggle"}]},"step-4":{"id":"step-4","speaker":"Sven","speech":"„Ich meine, es wirkt ja bei mir, also muss doch was dran sein! Pflanzen sind seit Jahrtausenden Medizin. Warum fragst du so genau nach?“","options":[{"text":"„Weil mich interessiert, wie man das sicher herausfindet. Wie ließe sich testen, ob wirklich das Mittel dahintersteckt und nicht der Placebo-Effekt oder dass du seit drei Tagen besser schläfst?“","style":"sokratisch","reaction":"„Hm ... stimmt, seit Montag schlafe ich tatsächlich besser, weil das Projekt abgeschlossen ist. Wie würde man das denn trennen?“","feedback":"Meisterhaft: Du bietest Alternativerklärungen an und fragst nach einer verlässlicheren Methode, statt selbst die Antwort zu liefern. Svens Zweifel entsteht aus seinen eigenen Beobachtungen.","score":3,"nextStepId":"step-5-success"},{"text":"„Weil ‚seit Jahrtausenden bewährt‘ allein nichts beweist, Sven. Das ist der Appell an die Tradition, ein enger Verwandter des Appells an die Natur, und der zieht bei mir nicht.“","style":"frontal","reaction":"„Oh Mann, jetzt kommst du mit Fachwörtern. Ich wollte doch nur was für mein Gedächtnis tun.“","feedback":"Inhaltlich gedeckt (nennt den Appell an die Tradition), aber du reichst Sven ein Etikett statt einer Frage. Er fühlt sich eingeordnet und schaltet ab.","score":0,"nextStepId":"step-5-struggle"},{"text":"„Sven, nimm es bloß nicht weiter, das ist alles Einbildung! Wer so etwas nimmt, wird auch nicht klüger, glaub mir das einfach, ich habe mich damit lange genug beschäftigt.“","style":"frontal","reaction":"„Einbildung?! Du kannst mir meine Erfahrung nicht ausreden. Wir sind fertig mit dem Thema!“","feedback":"Ein Urteil statt einer Frage: Statt die Behauptung zu untersuchen, erklärst du Svens Erfahrung für Einbildung. Er fühlt sich als Mensch angegriffen und beendet das Thema.","score":-2,"nextStepId":"step-fail"}]},"step-4-struggle":{"id":"step-4-struggle","speaker":"Sven","speech":"„Ach, ich merk's halt. Und auf der Packung steht ‚rein natürlich‘, das klingt doch sicher, oder?“","options":[{"text":"„Das kann ich gut verstehen. Magst du es zum Spaß testen: Wenn du eine Woche lang abwechselnd Tage mit und ohne Mittel hast, merkst du dann wirklich einen Unterschied?“","style":"sokratisch","reaction":"„Ha, das wäre eigentlich ein cooles Experiment! Ich führe mal ein kleines Tagebuch.“","feedback":"Sanfter Weg: Du bietest eine Prüfmethode an, die Sven selbst durchführen kann. Nicht perfekt, aber ein erster Schritt zu verlässlicherer Erkenntnis.","score":2},{"text":"„Die Packung ist Marketing, Sven. ‚Natürlich‘ heißt überhaupt nichts, das steht da nur, weil sich das gut verkauft und die Leute beruhigt.“","style":"frontal","reaction":"„Ach komm, ich bin doch kein Kind. Lass mich einfach in Ruhe.“","feedback":"Der Satz ist sachlich nah dran an „Der Appell an die Natur“, aber als Dekret gesprochen. Sven verteidigt sich, statt zu denken.","score":-1}]},"step-5-success":{"id":"step-5-success","speaker":"Sven","speech":"„Okay, das ist ein guter Punkt. Eigentlich kann ich aus drei Tagen und der Kollegin nicht viel schließen. Wie würdest du das prüfen?“","options":[{"text":"„Ein paar Wochen Tagebuch, mit und ohne Mittel, und dann vergleichen? Und die doppelte Menge lassen wir lieber, auf die Dosis kommt es an.“","style":"sokratisch","reaction":"„Mach ich! Und die Packungsangabe halte ich dann lieber ein. Danke, dass du nicht gleich gemeckert hast. Kaffee?“","feedback":"Überzeugendes Ende: Du lieferst keine Wahrheit, sondern gemeinsam gefundene Prüfschritte. Dass auch Natürliches auf Dosis und Substanz ankommt, kommt ruhig ins Spiel, und die Freundschaft bleibt heil.","score":3},{"text":"„Gar nicht, du hast recht: Natur ist immer besser, probier ruhig weiter.“","style":"humorvoll","reaction":"„Siehst du, wusste ich! Prost, auf die Natur!“ *kippt die doppelte Dosis*","feedback":"Aus Konfliktscheu bestätigst du den Mythos. „Natürlich“ ist kein Qualitätsmerkmal, und die gute Gesprächsarbeit der letzten Minuten ist damit verpufft.","score":-1},{"text":"„Gute Frage. Ein einfacher Anfang wäre, dass du die Packungsangabe einhältst, denn bei jedem Stoff gilt: Auf die Dosis kommt es an.“","style":"deeskalierend","reaction":"„Das stimmt wohl. Dann nehme ich die normale Menge. Und frage die Kollegin, woher sie das weiß.“","feedback":"Solider Abschluss: Du bringst den Kernpunkt Dosis ein und lässt Sven selbst weiterfragen. Allerdings fehlt noch ein Schritt zur Prüfung der Wirkung.","score":2}]},"step-5-struggle":{"id":"step-5-struggle","speaker":"Sven","speech":"„Ich sag ja nur: Es fühlt sich richtig an. Aber gut, lass uns nicht streiten.“","options":[{"text":"„Streiten wollen wir auch nicht. Ich finde es spannend, wie man Gefühl und Wirkung auseinanderhält. Probier es gern aus, aber nimm nur die angegebene Menge. Kaffee?“","style":"deeskalierend","reaction":"„Einverstanden. Kaffee klingt gut, und die normale Menge nehme ich dann halt.“","feedback":"Sauberer Ausstieg: Die Beziehung bleibt heil, ein kleiner Stein des Zweifels und der Dosis-Hinweis sind gesetzt.","score":2},{"text":"„Streiten will ich auch nicht, aber mach, was du willst. Ich sag nichts mehr. Wenn du es unbedingt ausprobieren musst, dann tu es eben, ich halte dich nicht auf.“","style":"ausstieg","reaction":"„Gut so.“ *Schweigen*","feedback":"Rückzug ohne Brücke: Das Gespräch endet kühl, und Sven nimmt keinen Gedanken mit. Ein freundlicher Abschluss hätte beides ermöglicht.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Sven","speech":"„Weißt du was? Ich habe keine Lust, mich vor dir zu rechtfertigen. Ich nehme es weiter, und zwar doppelt!“ *steckt das Fläschchen ein*","options":[{"text":"Ende: Sven fühlte sich belehrt und hält jetzt noch fester an seinem Mittel und der doppelten Dosis fest. Wer die Person angreift, verliert die Sachfrage.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst die Methode erfragen statt die Schlussfolgerung zu bekämpfen.","feedback":"Street Epistemology greift nicht die Überzeugung an, sondern fragt, wie jemand zu ihr gekommen ist. Frage dich: Wollte ich recht haben oder Sven zum Nachdenken bringen?","score":0}]}},"status":"entwurf","familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","stufe":1,"kurz":"„Natürlich“ sagt nichts über Sicherheit oder Wirkung: Auch der Knollenblätterpilz ist natürlich, und alles aus Materie ist Chemie. Wer nach dem Weg zur Überzeugung fragt, nach Sicherheit, Methode und Alternativerklärungen, statt das Ergebnis anzugreifen, gibt Denkstoff.","prueffrage":"Worauf stützt sich die Sicherheit, dass das Mittel wirkt und auch in doppelter Menge harmlos ist, und was davon lässt sich nachprüfen?","quellen":[{"typ":"url","kurz":"National Center for Complementary and Integrative Health (NCCIH): Natural Doesn't Necessarily Mean Safer, or Better","oeffentlich":true,"url":"https://www.nccih.nih.gov/health/know-science/natural-doesnt-mean-better","abruf":"2026-10-12"},{"typ":"url","kurz":"Street Epistemology: What is Street Epistemology? Definition & Overview","oeffentlich":true,"url":"https://streetepistemology.com/what-is-street-epistemology","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"scen-mia-nur-theorie","title":"Mia und die „bloße Theorie“","subtitle":"Evolution verstehen, geübt mit Street Epistemology","character":"Mia, Schülerin in der 9. Klasse","avatar":"🦎","context":"Im Biologieunterricht steht gerade die Evolution auf dem Plan. Mia, eine Mitschülerin aus deiner Lerngruppe, lehnt sich zurück und sagt, das sei doch alles nur eine Theorie, bewiesen sei da gar nichts. Ihr sitzt zusammen am Gruppentisch, die Stunde hat gerade erst angefangen.","goal":"Finde mit Street Epistemology heraus, was Mia unter „Theorie“ versteht und wie sie zu ihrer Sicherheit kommt, ohne sie zu belehren oder bloßzustellen.","bereich":"Schule","laenge":"mittel","ton":"ernst","bestehenAb":6,"lektion":"Bei „nur eine Theorie“ lohnt es sich, zuerst zu klären, was das Wort für den anderen bedeutet. Mit einfachen Fragen nach Sicherheit und Methode kommt das Gespräch in Gang, während eine Faktenwand eher zumacht. Und: Evolution ist nicht reiner Zufall. Die Variation ist zufällig, die Selektion ist es nicht.","toolRef":"H.2.2","faktenRef":"C.3.3","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Mia","speech":"„Ehrlich, wir lernen hier Evolution, als wäre das ein Fakt. Aber das ist doch nur eine Theorie. Bewiesen ist da gar nichts.“","options":[{"text":"„Das ist doch Quatsch, Mia. Evolution ist das zentrale Prinzip der ganzen Biologie. Wenn du das anzweifelst, hast du im Unterricht nicht aufgepasst.“","style":"frontal","reaction":"„Aha, jetzt bin ich also faul und dumm? Ich sag nur, was ich denke. Dann red halt mit jemand anderem.“ *verschränkt die Arme und dreht sich weg*","feedback":"Frontalangriff: Die Aussage stimmt, aber Mia hört nur den Vorwurf. Street Epistemology beginnt mit Neugier statt mit einem Urteil über den Menschen.","score":-2,"nextStepId":"step-fail"},{"text":"„Interessant, dass du das sagst. Darf ich dich was fragen? Was meinst du genau mit ‚Theorie‘?“","style":"sokratisch","reaction":"„Na, eine Theorie ist halt so eine Idee. Jemand denkt sich was aus, und solange es keiner beweist, ist es eben nur ein Vorschlag.“","feedback":"Genau der richtige Einstieg: Du klärst zuerst die Behauptung und die Bedeutung des Wortes (Schritt 2). So siehst du, woran ihr Eindruck hängt, ohne etwas zu unterstellen.","score":3,"nextStepId":"step-2"},{"text":"„Haha, ja klar, Mia. Und die Schwerkraft ist wahrscheinlich auch nur ein Gerücht, oder? Dann spring doch mal aus dem Fenster.“","style":"sarkastisch","reaction":"„Sehr witzig. Du machst dich lustig, statt zu antworten. Ich hab nur eine Frage gestellt.“","feedback":"Sarkasmus lässt Mia schlecht aussehen, obwohl sie nur ihre Sicht schildert. Seziert wird die Behauptung, nicht der Mensch.","score":-1,"nextStepId":"step-2-struggle"}]},"step-2":{"id":"step-2","speaker":"Mia","speech":"„Also eine Theorie ist für mich so etwas wie eine Vermutung. Und bei der Evolution sagt keiner: ‚Ja, das ist sicher.‘ Das sagen die doch nur, weil es im Schulbuch steht.“","options":[{"text":"„Danke, jetzt verstehe ich dich besser. Wenn du eine Skala von 0 bis 100 nimmst: Wie sicher bist du, dass die Evolution nicht stimmt?“","style":"sokratisch","reaction":"„Hm. Sicher sicher bin ich nicht. Vielleicht so 70? Es kommt mir halt komisch vor, dass alles nur durch Zufall entstanden sein soll.“","feedback":"Stark: Die 0-bis-100-Skala macht aus „stimmt/stimmt nicht“ ein Spektrum und zeigt Mias eigentlichen Zweifel: den vermeintlichen „reinen Zufall“.","score":3,"nextStepId":"step-3"},{"text":"„Falsch, Mia: In der Wissenschaft ist eine Theorie keine Vermutung, sondern eine gut geprüfte Erklärung. Das ist ein großer Unterschied, merk dir das.“","style":"frontal","reaction":"„Okay, okay, dann ist es halt eine gute Theorie. Trotzdem hat das für mich nichts mit dem echten Leben zu tun.“ *klingt genervt*","feedback":"Als Korrektur serviert: Mia hat sich noch nicht selbst geprüft, und du hast ihr das Wort fertig erklärt, statt sie zum Nachdenken einzuladen (Behauptung klären, nicht belehren).","score":0,"nextStepId":"step-3-struggle"},{"text":"„Wow, für dich ist ja alles bloß ‚nur eine Meinung‘. Dann glaubst du vermutlich auch, der Mond ist aus Käse.“","style":"sarkastisch","reaction":"„Ey, das hab ich nie gesagt! Ich hab keine Lust, mich von dir veräppeln zu lassen.“","feedback":"Überspitzung und Spott verdrehen Mias Position und verhärten die Fronten. Ohne ehrliche Neugier trägt keine Frage.","score":-2,"nextStepId":"step-fail"}]},"step-2-struggle":{"id":"step-2-struggle","speaker":"Mia","speech":"„Na gut. Aber du hast doch auch keinen Beweis, oder? Du glaubst das nur, weil es dir jemand erzählt hat.“","options":[{"text":"„Fair, ich war eben ziemlich flapsig, das tut mir leid. Mich interessiert wirklich, wie du darauf kommst. Was macht dich bei deiner Einschätzung so sicher?“","style":"deeskalierend","reaction":"„Hm, okay. Ich finde halt, dass vieles in der Schule als Wahrheit verkauft wird, ohne dass man es selbst prüfen kann.“","feedback":"Gute Reparatur: Du entschuldigst dich kurz und kehrst zur offenen Methodenfrage zurück (Schritt 4). Das Gespräch kommt wieder in Gang.","score":2,"nextStepId":"step-3-struggle"},{"text":"„Natürlich habe ich Belege, ich hab die ganzen Studien gelesen. Du eher nicht, oder?“","style":"frontal","reaction":"„Was soll das jetzt? Dann ist das Gespräch für mich eben zu Ende.“","feedback":"Eine Prahlerei ohne Beleg und ein Seitenhieb gegen Mia: Das wirkt als Machtspiel und beendet den Austausch.","score":-2,"nextStepId":"step-fail"},{"text":"„Stimmt, ich kann das Thema hier nicht mal eben in zwei Sätzen klären. Wir sollten uns dafür Zeit nehmen. Wollen wir nach dem Unterricht kurz zusammen schauen?“","style":"ausstieg","reaction":"„Ja, okay. Vielleicht. Mal sehen.“ *zuckt mit den Schultern*","feedback":"Ein freundlicher Rückzug schützt die Beziehung, aber das Gespräch bleibt an der Oberfläche. Brauchbar, wenn der Moment sonst zu hitzig wäre.","score":1,"nextStepId":"step-3-struggle"}]},"step-3":{"id":"step-3","speaker":"Mia","speech":"„Mich stört halt, dass das alles Zufall sein soll. Ein Auge oder ein Vogelflügel, die sehen so durchdacht aus. Das kann doch nicht einfach so zufällig entstehen.“","options":[{"text":"„Das verstehe ich, bei so komplexen Dingen wirkt es oft so. Woran würdest du erkennen, dass etwas nicht durch Zufall entstehen kann? Welche Methode würdest du nehmen?“","style":"sokratisch","reaction":"„Hm... meine Methode ist eigentlich nur mein Bauchgefühl. Es sieht halt einfach geplant aus. Aber ein Bauchgefühl ist wahrscheinlich nicht der beste Beweis.“","feedback":"Ausgezeichnet: Du würdigst den Eindruck und fragst nach der Methode (Schritt 4 und 5). Mia erkennt selbst, dass „sieht geplant aus“ auf einer Intuition beruht, die täuschen kann.","score":3,"nextStepId":"step-4-success"},{"text":"„Evolution ist ja auch kein reiner Zufall: Mutationen sind zufällig, aber die Selektion nicht. Die Umwelt filtert, was überlebt. Nur das Erste ist Zufall, das Zweite nicht.“","style":"frontal","reaction":"„Ach so, es ist also nicht nur Zufall... Hm, das klingt schon logischer. Ich muss mal darüber nachdenken.“","feedback":"Inhaltlich sauber und hilfreich, aber als reine Erklärung. Sie nimmt Mias Zweifel auf, lässt sie aber nicht selbst prüfen, wie verlässlich ihr Eindruck ist.","score":1,"nextStepId":"step-4-struggle"},{"text":"„Ach komm, Mia, wenn alle Wissenschaftler sich einig sind, wirst du dich ja wohl nicht für schlauer halten als die alle. Die werden schon wissen, was sie tun.“","style":"frontal","reaction":"„Darum geht’s nicht. Aber klar, wenn du so redest, fragt man sich nur noch, ob man überhaupt was fragen darf.“","feedback":"Ein Autoritätsargument mit leisem Druck: Es ersetzt die Frage nach der Methode durch „glaub den Experten“ und lässt Mia sich klein fühlen.","score":-1,"nextStepId":"step-4-struggle"}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Mia","speech":"„Keine Ahnung. Für mich fühlt sich das alles trotzdem irgendwie nicht ganz richtig an. Zufällig, und trotzdem so perfekt?“","options":[{"text":"„Das Gefühl kann ich nachvollziehen, so geht es vielen. Darf ich fragen, woran es sich für dich nicht richtig anfühlt? Und wie verlässlich ist so ein Gefühl bei Fakten?“","style":"sokratisch","reaction":"„Hm. Vermutlich nicht besonders verlässlich. Ein Gefühl sagt ja nichts darüber, was wirklich passiert ist.“","feedback":"Gut gelenkt: Du holst das Gespräch zur Methode zurück (Schritt 5), ohne zu belehren. Mia prüft ihren Maßstab selbst.","score":2,"nextStepId":"step-4-success"},{"text":"„Dann glaub eben, was du willst. Ich bin raus, das bringt nichts, und ich habe keine Lust, mich weiter mit dir im Kreis zu drehen.“","style":"ausstieg","reaction":"„Na toll. Dann halt nicht.“ *kritzelt auf ihrem Block*","feedback":"Ein genervter Abbruch, der nichts klärt. Ein Ausstieg ist legitim, sollte aber freundlich sein und die Tür offenlassen.","score":-1,"nextStepId":"step-fail"},{"text":"„Also gut, ich erkläre dir die Evolution jetzt komplett von vorn, ich hole schnell meine Notizen. Das dauert etwa eine Stunde, setz dich schon mal.“","style":"frontal","reaction":"„Ähm, ich hab jetzt gerade keine Lust auf einen Vortrag. Vielleicht ein andermal.“","feedback":"Ein Vortrag überrollt Mia mit Fakten, statt ihre eigene Methode zu prüfen. Neugier ist hier stärker als Erklärung.","score":0,"nextStepId":"step-4-struggle"}]},"step-4-struggle":{"id":"step-4-struggle","speaker":"Mia","speech":"„Na ja. Ganz überzeugt bin ich trotzdem nicht. Irgendwie ist mir das alles noch nicht klar.“","options":[{"text":"„Das ist völlig in Ordnung, Mia. Ich fand spannend, wie du darüber denkst. Schauen wir uns später ein Beispiel an: wie sich Bakterien an Antibiotika anpassen.“","style":"deeskalierend","reaction":"„Ja, okay. Das klingt konkret. Vielleicht kapier ich es dann besser.“","feedback":"Ein guter Abschluss: Du schaffst Beziehung und bietest einen überprüfbaren Zugang an (Antibiotikaresistenz). Der kleine Zweifel darf weiterarbeiten.","score":2},{"text":"„Gut, dann lass uns das Thema für heute lassen. Danke, dass du so offen darüber gesprochen hast, das war nicht selbstverständlich.“","style":"ausstieg","reaction":"„Ja, passt schon. Danke fürs Zuhören.“","feedback":"Ein höflicher Schluss, bei dem Mia ihr Gesicht wahrt (Schritt 6). Es bleibt allerdings offen, was sie mitnimmt.","score":1},{"text":"„Tja, wenn du es nicht verstehst, kann ich dir auch nicht helfen. Ich habe es dir jetzt oft genug erklärt, mehr kann ich nicht tun.“","style":"sarkastisch","reaction":"„Wow. Danke für nichts.“ *packt demonstrativ ihre Sachen*","feedback":"Ein abfälliger Satz zum Schluss zerstört, was an Vertrauen entstanden war. Seziert wird die Behauptung, nicht der Mensch.","score":-2}]},"step-4-success":{"id":"step-4-success","speaker":"Mia","speech":"„Wenn ich ehrlich bin, stützt sich mein Zweifel nur auf ein Bauchgefühl. Dass etwas geplant aussieht, heißt ja noch nicht, dass es geplant ist. Wie soll das denn ohne Plan gehen?“","options":[{"text":"„Ehrliche Frage. Das Buch sagt dazu: Die Variation ist zufällig, die Auswahl durch die Umwelt nicht. Kleine Vorteile setzen sich über Generationen durch. Spielen wir es durch?“","style":"deeskalierend","reaction":"„Ja, gern! Das mit den kleinen Schritten würde ich gern mal an einem Tier durchspielen.“","feedback":"Rundum gelungen: Du nimmst Mias Frage ernst, ergänzt den Kernpunkt aus „Evolution durch natürliche Selektion“ (zufällige Variation, nicht-zufällige Selektion) und lädst zum gemeinsamen Weiterdenken ein.","score":3},{"text":"„Siehst du, ich hab’s ja gesagt. Man muss eben nur richtig nachdenken, dann kommt man von allein drauf. Dafür brauchst du kein Buch und keine Hilfe von mir.“","style":"humorvoll","reaction":"„Haha, na ja, ohne deine Fragen wäre ich nicht draufgekommen. Aber ich geb’s zu, ich hab dazugelernt.“","feedback":"Locker und ohne böse Absicht, aber ein leichtes „Ich hab’s gewusst“ schmälert Mias Lernmoment ein wenig. Die Beziehung bleibt gut.","score":1}]},"step-fail":{"id":"step-fail","speaker":"Mia","speech":"„Ich hab keine Lust mehr auf das Gespräch. Du hörst mir eh nicht zu.“ *dreht sich weg und wendet sich dem Arbeitsblatt zu*","options":[{"text":"Ende: Das Gespräch ist abgebrochen, Mia fühlt sich nicht ernst genommen und bleibt bei ihrer Sicht.","style":"ausstieg","reaction":"Beim nächsten Mal mit einer offenen Frage nach der Bedeutung und der Sicherheit beginnen, statt zu korrigieren.","feedback":"Frage dich: Wollte ich Mia zuhören oder sie widerlegen? Street Epistemology untersucht die Methode, nicht den Menschen.","score":0}]}},"status":"entwurf","familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","stufe":2,"kurz":"Bei „nur eine Theorie“ lohnt es sich, erst zu klären, was das Wort für das Gegenüber bedeutet; Fragen nach Sicherheit und Methode öffnen das Gespräch, eine Faktenwand schließt es eher. Evolution ist kein reiner Zufall: Die Variation ist zufällig, die Selektion nicht.","prueffrage":"Was meint Mia mit „Theorie“, und mit welcher Methode prüft sie, ob ein Auge durch Zufall entstanden sein kann?","quellen":[{"typ":"url","kurz":"Understanding Evolution (UC Museum of Paleontology, UC Berkeley): Misconceptions about evolution","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"},{"typ":"url","kurz":"Understanding Evolution (UC Museum of Paleontology, UC Berkeley): But it’s not random either!","oeffentlich":true,"url":"https://evolution.berkeley.edu/misconceptions-about-natural-selection-and-adaptation/but-its-not-random-either","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"scen-ich-selbst-erinnerung-streit","title":"Ich weiß genau, wer angefangen hat","subtitle":"Streit im Rückblick, geübt mit Emotion und Motivation","character":"Ich (du selbst nach einem Streit)","avatar":"💢","context":"Gestern Abend gab es Streit mit deiner Mitbewohnerin Lena, weil sie wieder einmal schroff reagierte, als du die Küche angesprochen hast. Jetzt liegst du wach, und dein Kopf spielt die Szene in Dauerschleife ab. Eine Stimme in dir ist sich sicher: Sie hat es aus bösem Willen getan, du warst nur verständlich gereizt.","goal":"Prüfe deine eigene Erklärung des Streits, statt sie blind zu übernehmen: Erkenne den Attributionsfehler, nutze deine Emotionen als Datenpunkt und wechsle zu einer fairen Sicht auf Lena.","bereich":"Ich selbst","laenge":"mittel","ton":"ernst","bestehenAb":6,"lektion":"Beim Streit erklären wir das Verhalten anderer gern mit ihrem Charakter und unterschätzen die Umstände: der fundamentale Attributionsfehler. Dass wir uns selbst milder beurteilen, ist eine eigene Hypothese mit schwacher Beleglage, bei negativem Verhalten wie hier aber als kleiner Effekt messbar. Dein Ärger ist ein wichtiger Datenpunkt, aber kein Beweis: Er sagt etwas über dich und deine Werte, nicht automatisch über die Absichten der anderen. Frag dich deshalb erst, welche unsichtbaren Umstände ihr Verhalten erklären könnten, und fang das Gespräch mit einer ehrlichen Frage statt mit einem Urteil an.","toolRef":"H.1.4","faktenRef":"B.8","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Ich (du selbst nach einem Streit)","speech":"„Ich weiß es genau: Lena hat mich gestern absichtlich so angeschnauzt. Die macht das immer, die ist einfach so. Und ich? Ich war nur genervt, weil ich einen miesen Tag hatte. Das kann doch jeder verstehen, oder?“","options":[{"text":"„Genau, Lena ist eben so. Ich muss mich nicht rechtfertigen. Morgen sage ich ihr deutlich, wie egoistisch sie ist, dann ist das geklärt und ich habe meine Ruhe.“","style":"frontal","reaction":"*Die Stimme nickt zufrieden.* „Ja, genau. Sie hat es verdient, dass jemand ihr die Wahrheit sagt. Endlich Klartext!“","feedback":"Du bestätigst das Charakterurteil über Lena, ohne es zu prüfen. Das ist der fundamentale Attributionsfehler: Ihr Verhalten wird dem Charakter zugeschrieben, die Umstände bleiben außen vor.","score":-2,"nextStepId":"step-fail"},{"text":"„Moment. Ich nehme meinen Ärger ernst, er sagt mir ja etwas. Aber ich erkläre ihr Verhalten mit ‚so ist sie halt‘ und mein eigenes mit meinem miesen Tag. Das ist doppelter Maßstab.“","style":"sokratisch","reaction":"*Die Stimme zögert.* „Hm... stimmt. Wenn Lena so wie ich gestern einen schlechten Tag gehabt hätte, hätte ich das genauso wenig bemerkt wie sie meinen.“","feedback":"Stark! Du nimmst den Ärger als Datenpunkt und bemerkst, dass du bei Lena die Umstände ausblendest, den Kern des Attributionsfehlers. Für dich selbst hast du sie gleich parat, ein doppelter Maßstab.","score":3,"nextStepId":"step-2"},{"text":"„Ach, ich sollte aufhören, darüber nachzudenken. Gefühle sind sowieso unlogisch. Ich schlafe jetzt und tue so, als wäre nichts gewesen, das erledigt sich von allein.“","style":"ausstieg","reaction":"*Die Stimme grummelt.* „Na gut. Aber ich merke mir das. Beim nächsten Mal bin ich vorbereitet.“","feedback":"Dein Ärger ist kein Störfaktor, sondern eine schnelle Zusammenfassung von Erfahrung. Wegschieben löst den Kern nicht, die Deutung bleibt unbesehen im Hintergrund stehen.","score":-1,"nextStepId":"step-2b"}]},"step-2":{"id":"step-2","speaker":"Ich (du selbst nach einem Streit)","speech":"„Okay, vielleicht war ich nicht ganz fair. Aber trotzdem: Es fühlt sich so klar an, dass sie Absicht hatte. Soll ich mein Gefühl jetzt einfach wegwerfen?“","options":[{"text":"„Nein, ich behalte das Gefühl als Datenpunkt: Es zeigt, dass mir Respekt wichtig ist. Ob Lena böse Absicht hatte, kann ich daraus nicht ablesen. Das muss ich getrennt prüfen.“","style":"sokratisch","reaction":"*Die Stimme atmet auf.* „Das macht Sinn. Mein Ärger zeigt mir, was mir wichtig ist, und gibt die Richtung vor. Aber ob Lena Absicht hatte, muss mein Verstand prüfen. Herrschen lasse ich das Gefühl nicht.“","feedback":"Genau das meint „Emotion & Motivation“: Emotionen geben Richtung und Motivation, ersetzen aber nicht die Prüfung. Gefühl ernst nehmen, Urteil trotzdem prüfen.","score":3,"nextStepId":"step-3"},{"text":"„Ich schreibe Lena sofort eine Nachricht, wie wütend ich bin. Das Gefühl ist echt, also hat sie auch das Recht, es zu wissen. Besser jetzt als nie.“","style":"affektiv","reaction":"*Die Stimme drängt.* „Ja, los, solange es noch heiß ist! Sonst redest du dir das wieder klein!“","feedback":"Hier kapert die Emotion das Steuer: Impuls statt Prüfung. In der Hitze greifst du vermutlich ihren Charakter an – und der Streit eskaliert.","score":-2,"nextStepId":"step-fail"},{"text":"„Ich schreibe auf, was gestern genau passiert ist und was ich dabei gefühlt habe. Dann sehe ich, was Tatsache ist und was meine Deutung, und kann gelassener ins Gespräch gehen.“","style":"deeskalierend","reaction":"*Die Stimme wird ruhiger.* „Gute Idee. Dann habe ich nicht nur das Gefühl, sondern auch Material, mit dem ich arbeiten kann.“","feedback":"Brauchbar: Du trennst Beobachtung und Deutung und weckst damit das ruhige Denken. Du hast noch nicht gefragt, welche Umstände bei Lena eine Rolle gespielt haben könnten.","score":1,"nextStepId":"step-3"}]},"step-2b":{"id":"step-2b","speaker":"Ich (du selbst nach einem Streit)","speech":"„Ich kann nicht einschlafen. Die Szene läuft immer wieder: Lenas Blick, ihr Ton... Das war so eindeutig böse. Warum geht mir das nicht aus dem Kopf?“","options":[{"text":"„Weil mein Ärger noch etwas klären will. Ich höre hin, was er mir sagt, und prüfe dann: Habe ich gerade ‚Lena ist halt so‘ gedacht, aber für mich selbst Umstände geltend gemacht?“","style":"sokratisch","reaction":"*Die Stimme stockt.* „...Ja. Genau das habe ich getan. Ich habe sie sofort verurteilt und mich selbst entschuldigt.“","feedback":"Gut gedreht: Die Grübelei als Signal nehmen und den Attributionsfehler benennen. So geht Gefühl in Erkenntnis über.","score":2,"nextStepId":"step-3"},{"text":"„Weil ich dumm bin und immer alles hochkoche. Ich bin eben ein Mensch, der nachtragend ist. So bin ich halt.“","style":"sarkastisch","reaction":"*Die Stimme seufzt bitter.* „Ja, vermutlich. Dann ist sowieso alles egal.“","feedback":"Jetzt schiebst du den Charakterfehler auf dich selbst, ein Tausch des Fehlers statt seine Korrektur. Auch ‚so bin ich halt‘ ersetzt keine Prüfung der Umstände.","score":-1,"nextStepId":"step-fail"},{"text":"„Ich greife nach dem Handy und schreibe Lena eine knappe Nachricht: ‚Wir müssen reden.‘ Dann hat sie die Nacht Zeit, darüber nachzudenken, was sie falsch gemacht hat.“","style":"frontal","reaction":"*Die Stimme grinst grimmig.* „Soll sie ruhig schwitzen. Sie hat es nicht anders verdient.“","feedback":"Drohkulisse statt Neugier: Du sperrst Lena in die Rolle der Schuldigen, bevor du ihre Seite kennst. Das ist die Folge des Attributionsfehlers.","score":-2,"nextStepId":"step-fail"}]},"step-3":{"id":"step-3","speaker":"Ich (du selbst nach einem Streit)","speech":"„Gut. Und was ist, wenn sie wirklich bösartig ist? Es gibt ja auch solche Menschen. Kann ich nicht einfach davon ausgehen, dass sie mich nerven wollte?“","options":[{"text":"„Ich gehe zunächst nicht von Bosheit aus, wenn Überforderung oder ein schlechter Tag die Sache auch erklären könnten. Aber das kann ich nur am Verhalten prüfen, nicht am Bauchgefühl.“","style":"sokratisch","reaction":"*Die Stimme räumt ein.* „Stimmt. Ich frage mich erst, welche unsichtbaren Umstände ihr Verhalten erklären könnten. Bosheit ist nicht ausgeschlossen, aber kein Startpunkt.“","feedback":"Treffend: Du nutzt die Aktivierungsfrage aus „Der fundamentale Attributionsfehler“: Würde ich mich in ihrer Lage ähnlich verhalten? Bosheit schließt du nicht aus, machst sie aber nicht zur Standardannahme. Geprüft wird am Verhalten, nicht am Bauchgefühl.","score":3,"nextStepId":"step-4"},{"text":"„Ich überlege, was bei Lena in den letzten Tagen los war: Prüfungsstress? Ärger auf der Arbeit? Was könnte ich übersehen haben?“","style":"sokratisch","reaction":"*Die Stimme denkt nach.* „Sie hatte zuletzt viel um die Ohren, glaube ich. Davon habe ich mir aber nie ein Bild gemacht.“","feedback":"Das ist die Aktivierungsfrage zum Attributionsfehler: Welche unsichtbaren Umstände könnten ihr Verhalten erklären? Es fehlt nur noch die Prüfung durch ein Gespräch.","score":2,"nextStepId":"step-4"},{"text":"„Es gibt bestimmte Typen, die einfach bösartig sind. Lena gehört dazu, das habe ich schon vorher gespürt. Ich halte mich besser an Abstand.“","style":"frontal","reaction":"*Die Stimme nickt.* „Genau. Ich vertraue meinem Bauchgefühl. Distanz ist die sicherste Lösung.“","feedback":"Du erklärst ihr gesamtes Verhalten aus einem stabilen Charakterzug, auf Basis eines Gefühls. Du schützt dich zwar, aber blendest alles andere aus.","score":-1,"nextStepId":"step-fail"}]},"step-4":{"id":"step-4","speaker":"Ich (du selbst nach einem Streit)","speech":"„Okay. Und jetzt? Morgen früh begegne ich ihr in der Küche. Wie fange ich das Gespräch an, ohne dass es wieder kracht?“","options":[{"text":"„Ich sage: ‚Gestern ist es zwischen uns laut geworden. Mich hat das geärgert, und ich war selbst gereizt. Magst du erzählen, wie das für dich war?‘ Erst fragen, dann bewerten.“","style":"deeskalierend","reaction":"*Die Stimme atmet durch.* „Das klingt ehrlich. Ich zeige mein Gefühl, ohne sie zu verurteilen. Und lasse Raum für ihre Seite.“","feedback":"Sehr gut: Ich-Botschaft, eigene Gereiztheit eingestanden, Neugier statt Urteil. Der Ärger bleibt als Datenpunkt, der Attributionsfehler wird aktiv gebremst.","score":3,"nextStepId":"step-success"},{"text":"„Ich sage: ‚Lena, du hast gestern völlig überreagiert. Hör mal, wie du mit Leuten umgehst.‘ Dann weiß sie gleich, woran sie ist, und wir müssen nicht lange drumherum reden.“","style":"frontal","reaction":"*Die Stimme verzieht das Gesicht.* „Na ja... klingt hart. Aber vielleicht muss man das sagen.“","feedback":"Das Urteil über ihren Charakter steht schon im ersten Satz. Das öffnet keine Tür, sondern löst Verteidigung aus.","score":-2,"nextStepId":"step-fail"},{"text":"„Ich warte ab, bis sie von selbst ankommt. Wenn sie sich entschuldigen will, tut sie das. Den ersten Schritt mache ich nicht, das wäre ein Zeichen von Schwäche.“","style":"ausstieg","reaction":"*Die Stimme zuckt mit den Schultern.* „Okay, sicher ist sicher. Dann bleibt alles, wie es ist.“","feedback":"Vermeiden schützt dich kurz, klärt aber nichts. Du lässt die eigene Deutung ungeprüft stehen und hoffst, dass sich das von selbst löst.","score":0,"nextStepId":"step-struggle"}]},"step-struggle":{"id":"step-struggle","speaker":"Ich (du selbst nach einem Streit)","speech":"„Na gut, vielleicht ist Warten nicht die beste Idee. Aber ich bin immer noch sauer. Wie soll ich das hinkriegen, ohne dass ich mich komplett verbiege?“","options":[{"text":"„Ich bleibe bei meinem Ärger und sage ihr das ehrlich, aber erst nach der Frage, wie es ihr ging. So bleibe ich ich selbst und gebe ihr Raum.“","style":"deeskalierend","reaction":"*Die Stimme entspannt sich.* „Ja. Mein Ärger darf mitlenken, aber nicht allein herrschen. Mein Verstand prüft, bevor ich urteile. Das fühlt sich stimmig an.“","feedback":"Gut gelandet: Das Gefühl bleibt Datenpunkt, und die Frage nach ihrer Seite bremst den Attributionsfehler.","score":2},{"text":"„Ich schreibe ihr nur, dass ich sauer bin, und lasse es dabei. Sie wird schon merken, was los ist und woran es liegt, dazu muss ich nichts weiter erklären.“","style":"sarkastisch","reaction":"*Die Stimme brummt.* „Dann soll sie eben selbst draufkommen. Ich sage nichts weiter.“","feedback":"Du teilst deine Wut mit, aber ohne Neugier auf ihre Seite. Das verhärtet eher, als dass es klärt.","score":-1}]},"step-success":{"id":"step-success","speaker":"Ich (du selbst nach einem Streit)","speech":"„Ich merke: Mein Ärger war echt und wichtig. Aber was er mir über Lenas Absicht gesagt hat, war nur eine Vermutung. Mit einer offenen Frage habe ich zum ersten Mal wirklich Chancen auf Klärung.“","options":[{"text":"„Und wenn ich merke, dass ich wieder ‚die ist halt so‘ denke, stelle ich mir die Frage: Wie würde ich mich in ihrer Lage verhalten, mit ihrem Druck?“","style":"sokratisch","reaction":"*Die Stimme lächelt müde.* „Gut. Dann habe ich ein Werkzeug für die Zukunft und nicht nur eine Meinung für heute.“","feedback":"Mission gelungen: Du hast den Attributionsfehler erkannt, deinen Ärger als Datenpunkt genutzt und dir eine Frage als Gewohnheit mitgenommen.","score":3}]},"step-fail":{"id":"step-fail","speaker":"Ich (du selbst nach einem Streit)","speech":"„Egal. Ich weiß, was ich gesehen habe. Lena ist, wie sie ist, und ich war im Recht. Punkt.“ *Die Stimme klingt entschlossen, aber irgendwie müde.*","options":[{"text":"Ende: Du hast dein Urteil über Lena nicht geprüft. Der Ärger bleibt, und die Fronten verhärten sich eher, als dass sie sich klären.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst fragen: Welche unsichtbaren Umstände könnten ihr Verhalten erklären? Und: Was sagt mein Ärger über mich, was nicht über sie?","feedback":"Der fundamentale Attributionsfehler lässt uns Verhalten anderer als Charakter lesen und die Umstände unterschätzen. Der Ärger ist ein Datenpunkt, kein Beweis.","score":0}]}},"status":"entwurf","familie":"umstaende-vor-absicht","fertigkeit":"F2","stufe":3,"kurz":"Im Streit erklärt man das Verhalten anderer gern mit ihrem Charakter und unterschätzt die Umstände. Ärger ist ein wichtiger Datenpunkt, aber kein Beweis: Er zeigt, was einem wichtig ist, nicht automatisch die Absicht der anderen. Besser als ein Urteil: eine ehrliche Frage.","prueffrage":"Mit welchen Gründen erklärst du Lenas schroffen Ton und mit welchen deinen eigenen, und welche Umstände auf ihrer Seite kennst du gar nicht?","quellen":[{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The correspondence bias. Psychological Bulletin 117(1) (Abstract bei PubMed; DOI 10.1037/0033-2909.117.1.21)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/7870861/","abruf":"2026-10-12"},{"typ":"url","kurz":"Malle, B. F. (2006): The actor-observer asymmetry in attribution: a (surprising) meta-analysis. Psychological Bulletin 132(6) (Abstract bei PubMed; DOI 10.1037/0033-2909.132.6.895)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/17073526/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Ross, L.; Anderson, C. A. (1982): Shortcomings in the attribution process. In: Kahneman, D.; Slovic, P.; Tversky, A. (Hg.): Judgment under Uncertainty: Heuristics and Biases. Cambridge University Press, Kap. 9","oeffentlich":false}],"thema":"Psychologie"},{"id":"scen-fruehstueck-zucker-sucht","title":"Papas Zucker-Entzug","subtitle":"Zucker als „Droge“, geübt mit aktivem Zuhören","character":"Papa Ralf","avatar":"🍬","context":"Beim Frühstück hat Papa Ralf das Nutella aus dem Schrank verbannt. Er hat ein Video gesehen, laut dem Zucker „genauso süchtig macht wie Heroin“. Ab sofort gibt es zu Hause keinen Zucker mehr, auch nicht für die Kinder, und sogar die Marmelade wandert in die Tonne.","goal":"Höre zuerst zu, bis du Papas Sorge wirklich verstanden hast, und lenke das Gespräch dann behutsam auf Menge und Wirkung, ohne Papa vorzuführen.","bereich":"Familie","laenge":"mittel","ton":"ernst","bestehenAb":6,"lektion":"Wer sofort widerlegt, hört nicht zu und erfährt nie, was hinter der Regel steckt. Papas Sorge um die Kinder ist berechtigt. Erst wenn du sie in eigenen Worten wiedergeben kannst, öffnet er sich für die Frage nach Menge und Wirkung. „Gift oder nicht“ ist genau das binäre Denken, vor dem die Dosis-Wirkungs-Beziehung warnt: Entscheidend sind Menge, Häufigkeit und Zusammenhang. Zur Behauptung „genauso süchtig wie Heroin“: Ein Forschungsüberblick fand beim Menschen wenig Beleg für eine Zuckersucht; Papas Heißhunger ist trotzdem echt und ernst zu nehmen, nur belegt er keine Sucht.","toolRef":"H.2.3","faktenRef":"C.4.7","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Papa Ralf","speech":"„Das Nutella ist weg, die Marmelade auch, und die Kinder kriegen ab jetzt keinen Zucker mehr. Wusstest du, dass Zucker genauso süchtig macht wie Heroin? Das Video war eindeutig. Ich lasse nicht zu, dass meine Kinder anfangen, Drogen zu essen.“","options":[{"text":"„Papa, das ist doch Quatsch. Zucker ist kein Heroin, und von Nutella wird keiner süchtig. Du übertreibst total und machst den Kindern nur Stress.“","style":"frontal","reaction":"„Ich übertreibe? Ich kümmere mich wenigstens um die Gesundheit der Kinder! Du hast das Video ja nicht mal gesehen!“ *verschränkt die Arme*","feedback":"Frontaler Widerspruch ohne Zuhören: Papa hört „Du bist ein schlechter Vater“ und verteidigt die Regel nur noch heftiger. Aktives Zuhören kommt vor jeder Widerlegung.","score":-2,"nextStepId":"step-fail"},{"text":"„Du machst dir offenbar große Sorgen um die Kinder, das merke ich. Erzähl mal: Was genau hat dich in dem Video am meisten erschreckt?“","style":"sokratisch","reaction":"„*zögert kurz* ...Dass man davon nicht mehr loskommt. Der Mann sagte, im Gehirn passiert da dasselbe wie bei Drogen. Und ich merke bei mir selbst: Ich krieg nachmittags diesen Heißhunger auf Süßes.“","feedback":"Sehr gut: Du benennst das Gefühl (Sorge) und stellst eine offene, klärende Frage. So erfährst du, was wirklich dahintersteckt, nämlich Papas eigener Heißhunger.","score":3,"nextStepId":"step-2"},{"text":"„Okay, Papa, wenn du meinst. Dann essen wir eben keinen Zucker mehr. Ich helfe dir, die Schränke auszuräumen.“","style":"ausstieg","reaction":"„Siehst du, endlich versteht mich mal jemand! Dann räumen wir alles raus, auch den Honig und die Kekse. Und morgen schauen wir, was in Obst alles drin ist.“","feedback":"Du weichst dem Konflikt aus und bestätigst die Regel, statt zuzuhören. Papas Sorge bleibt unbesprochen, die Regel wird nur strenger.","score":-1,"nextStepId":"step-strict"}]},"step-2":{"id":"step-2","speaker":"Papa Ralf","speech":"„Wenn ich um drei Uhr nachmittags nicht mindestens einen Keks habe, werde ich richtig unruhig. Das ist doch ein Entzug! Genau wie bei Drogen. Und das will ich den Kindern ersparen.“","options":[{"text":"„Wenn ich dich richtig verstehe, merkst du bei dir selbst ein starkes Verlangen nachmittags und hast Angst, dass die Kinder dasselbe entwickeln. Stimmt das so?“","style":"deeskalierend","reaction":"„Ja, genau. *atmet aus* Ich hab das Gefühl, ich kontrolliere mich nicht mehr. Und die Kinder lernen das von mir.“","feedback":"Paraphrasieren: Du gibst Inhalt und Gefühl in eigenen Worten wieder. Papa fühlt sich verstanden und gibt eine tiefere Sorge preis.","score":3,"nextStepId":"step-3"},{"text":"„Das heißt Gewohnheit, Papa, und keine Sucht. Echte Entzugserscheinungen sehen ganz anders aus. Der Mann im Video hat dich einfach reingelegt.“","style":"frontal","reaction":"„Du weißt wohl alles besser. Der Mann war Experte, und du hast keine Ahnung, wie sich das anfühlt!“","feedback":"Du stellst eine Gegenbehauptung auf und unterstellst dem Video Täuschung, bevor du Papas Erleben verstanden hast. Ohne vorheriges Zuhören klingt selbst ein berechtigter Einwand wie eine Abfuhr.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Dann iss doch einfach einen Keks, wenn du unruhig bist. Das hat doch noch keinem geschadet. Du machst dir zu viele Gedanken.“","style":"ausstieg","reaction":"„Siehst du, genau das ist das Problem! Alle nehmen das auf die leichte Schulter. Ein Keks, und zack, das war's.“ *winkt ab*","feedback":"Beschwichtigung ohne Zuhören: Du bagatellisierst, ohne verstanden zu haben, was Papa umtreibt. Er fühlt sich nicht ernst genommen.","score":-1,"nextStepId":"step-fail"}]},"step-3":{"id":"step-3","speaker":"Papa Ralf","speech":"„Ich will einfach nicht, dass sie so werden wie ich. Deshalb alles raus, ganz oder gar nicht. Zucker ist doch Gift, oder nicht? Jeder sagt das.“","options":[{"text":"„Eine Frage dazu: Wie viel Zucker meinst du, wird für die Kinder zum Problem? Ein Löffel Marmelade, oder eher das, was sich über den Tag summiert?“","style":"sokratisch","reaction":"„Hm... ein Löffel Marmelade wohl nicht. Es sind eher die Limos und Süßigkeiten, die sich summieren. Aber woher soll man wissen, wo die Grenze liegt?“","feedback":"Treffer: Eine offene Frage lenkt auf Menge und Wirkung. Papa merkt selbst, dass es um die Dosis geht, nicht um „Gift oder nicht“.","score":3,"nextStepId":"step-4-success"},{"text":"„Gift ist Zucker nicht. Paracelsus hat schon gesagt: Die Dosis macht das Gift. Mit Wasser kann man sich sogar vergiften, wenn man zu viel trinkt.“","style":"frontal","reaction":"„Willst du mir jetzt Zucker mit Wasser vergleichen? Das ist doch an den Haaren herbeigezogen!“","feedback":"Das Prinzip stimmt, aber du lieferst es fertig als Belehrung und Papa fühlt sich vorgeführt. Das Prinzip wirkt besser als Frage, die er selbst beantwortet.","score":1,"nextStepId":"step-3-struggle"},{"text":"„Genau, Papa! Und in Obst steckt ja auch Zucker. Am besten streichen wir auch das, um ganz sicherzugehen.“","style":"affektiv","reaction":"„Stimmt, daran habe ich noch gar nicht gedacht. Dann müssen wir gleich den ganzen Obstkorb prüfen und alles streichen.“","feedback":"Du übernimmst Papas Schwarz-Weiß-Denken und verschärfst es. Aus „gefährlich oder sicher“ wird eine Verbotsspirale, die Menge und Zusammenhang komplett ausblendet.","score":-2,"nextStepId":"step-strict"}]},"step-4-success":{"id":"step-4-success","speaker":"Papa Ralf","speech":"„Dann ist vielleicht gar nicht der Löffel Marmelade das Problem, sondern die Menge und wie oft. Und mein Heißhunger kommt vielleicht eher von der Gewohnheit, nachmittags was Süßes zu essen. Wie machen wir das jetzt mit den Kindern?“","options":[{"text":"„Wie wäre es, wenn wir gemeinsam überlegen, was über den Tag zusammenkommt, statt alles zu verbieten? Und die Marmelade darf am Samstag wieder auf den Frühstückstisch.“","style":"deeskalierend","reaction":"„Das klingt vernünftig. Ich war wohl ziemlich streng. Okay, wir schauen zusammen, was wir wirklich ändern wollen. Und ein Löffel Marmelade am Wochenende bringt uns schon nicht um.“","feedback":"Rundum gelungen: Papas Sorge wurde ernst genommen, und gemeinsam wurde die Menge zum Maßstab. Aus dem Verbot wird ein gemeinsamer Plan.","score":3},{"text":"„Wenn du den Nutella-Schrank wieder aufmachst, mache ich dir einen Wochenplan mit festen Mengen, an den sich alle halten müssen.“","style":"frontal","reaction":"„Ein fester Plan für alle? Hm, so streng wollte ich eigentlich nicht sein. Aber vielleicht geht das.“","feedback":"Der Impuls ist brauchbar (Menge im Blick), aber ein starrer Plan mit Druck ersetzt das gemeinsame Überlegen. Papa bleibt im Kontrollmodus.","score":1}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Papa Ralf","speech":"„Ich weiß nicht... Ich will doch nur das Beste für die Kinder. Vielleicht war ich zu schnell. Aber ich kann mich nicht von heute auf morgen umstellen.“","options":[{"text":"„Das merke ich, und es ist völlig okay. Mein Vorschlag: Die Marmelade bleibt erst mal im Schrank, und wir schauen Samstag in Ruhe, was die Kinder wirklich essen. Einverstanden?“","style":"deeskalierend","reaction":"„Gut, das ist fair. Ich geb dir meine Zusage, Samstag schauen wir gemeinsam drauf. Danke, dass du nicht gestritten hast.“","feedback":"Guter Rückzug: Du schützt die Beziehung und lässt die Sachfrage für später offen. Die Sorge wurde zwar erkannt, aber noch nicht gemeinsam bearbeitet.","score":2},{"text":"„Ach komm, Papa, mach dich nicht verrückt. Heißhunger haben alle mal, das geht vorbei. Du machst dir viel zu viele Gedanken wegen so einer Kleinigkeit.“","style":"humorvoll","reaction":"„*seufzt* Ja, vielleicht. Ich glaube, ich muss das alleine herausfinden.“","feedback":"Deine Beruhigung kommt gut gemeint, aber sie umgeht Papas Sorge. Er bleibt allein mit der Frage, wie viel genug ist.","score":0}]},"step-strict":{"id":"step-strict","speaker":"Papa Ralf","speech":"„Siehst du, so mache ich das. Kein Zucker mehr, nicht mal in Saft. Die Kinder werden mir später danken. Wer braucht schon Gummibärchen?“","options":[{"text":"Ende: Papa fühlt sich bestätigt, die Regel wird immer strenger. Die Kinder bekommen kaum noch etwas Süßes, und Papa hat nie erklärt, was ihn eigentlich antreibt.","style":"ausstieg","reaction":"„Jetzt sind wir endlich auf der sicheren Seite.“","feedback":"Wer mitmacht, statt zuzuhören, verstärkt das Schwarz-Weiß-Denken. Die Frage nach Menge und Wirkung und Papas eigentliche Sorge bleiben auf der Strecke.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Papa Ralf","speech":"„Ich seh schon, mit dir kann man nicht darüber reden. Ich weiß, was ich im Video gesehen habe, und ich ziehe das durch. Frühstück ist beendet.“ *räumt den Tisch ab*","options":[{"text":"Ende: Papa fühlt sich nicht gehört und verteidigt seine Regel jetzt erst recht. Rechthaben und Verstehen sind zweierlei.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst zuhören und die Sorge in eigenen Worten wiedergeben, bevor du widersprichst.","feedback":"Frage dich: Wollte ich Papa widerlegen oder verstehen? Aktives Zuhören öffnet die Tür, die ein Gegenargument zuschlägt.","score":0}]}},"status":"entwurf","familie":"dosis-entscheidet","fertigkeit":"F4","stufe":2,"kurz":"Wer sofort widerlegt, überhört die Sorge hinter einer Regel; erst wer sie in eigenen Worten wiedergibt, öffnet das Gespräch. Statt „Gift oder nicht“ zählen Menge, Häufigkeit und Zusammenhang. Heißhunger ist echt, doch eine Zuckersucht ist beim Menschen wenig belegt.","prueffrage":"Was genau befürchtet Papa für die Kinder, und welche Mengen Zucker kommen bei ihnen über einen Tag tatsächlich zusammen?","quellen":[{"typ":"url","kurz":"WHO (2015): WHO calls on countries to reduce sugars intake among adults and children (Pressemitteilung, 04.03.2015)","oeffentlich":true,"url":"https://www.who.int/news/item/04-03-2015-who-calls-on-countries-to-reduce-sugars-intake-among-adults-and-children","abruf":"2026-10-12"},{"typ":"url","kurz":"Paracelsus (1538): Sieben Defensiones, hg. K. Sudhoff, Leipzig 1915, Dritte Defension (Digitalisat Wellcome Collection)","oeffentlich":true,"url":"https://wellcomecollection.org/works/jxt2qtp7","seite":"S. 25","abruf":"2026-10-12"},{"typ":"url","kurz":"Kluger, A. N.; Itzchakov, G. (2022): The Power of Listening at Work. Annual Review of Organizational Psychology and Organizational Behavior 9 (Vorabfassung, Leibniz-Institut für Psychologie)","oeffentlich":true,"url":"https://leibniz-psychology.org/fileadmin/user_upload/pdf/il_Kluger-and-Itzchakov-OPOB-RR.pdf","seite":"PDF-S. 18 und 28 (Vorabfassung)","abruf":"2026-10-12"},{"typ":"doi","kurz":"Westwater, M. L.; Fletcher, P. C.; Ziauddeen, H. (2016): Sugar addiction: the state of the science. European Journal of Nutrition 55 (Suppl 2), 55–69 (Übersichtsarbeit)","oeffentlich":true,"doi":"10.1007/s00394-016-1229-6","url":"https://pubmed.ncbi.nlm.nih.gov/27372453/","abruf":"2026-10-13"}],"thema":"Gesundheit"},{"id":"scen-saftkur-svenja","title":"Svenjas Saftkur","subtitle":"Detox und „Schlacken“, geübt mit kognitiver Entkopplung","character":"Svenja","avatar":"🥤","context":"Deine Kollegin Svenja hat drei Tage lang eine teure Detox-Saftkur durchgezogen, die ein Influencer beworben hat. Heute schwärmt sie in der Kaffeeküche, wie „rein“ und „leicht“ sie sich fühlt, und rät allen im Team, es ihr gleichzutun.","goal":"Prüfe gemeinsam mit Svenja, was „Entgiften“ konkret bedeuten soll, ohne sie bloßzustellen, und hilf ihr, die Idee als prüfbare Hypothese von ihrer Person zu trennen (Kognitive Entkopplung).","bereich":"Gesundheit","laenge":"kurz","ton":"heiter","bestehenAb":4,"lektion":"Leber und Nieren entgiften den Körper laufend selbst. Für „Schlacken“, die sich per Saftkur ausspülen ließen, gibt es keine Belege, und wer nicht sagen kann, welcher Stoff gemeint ist, hat noch keine Behauptung geprüft. Mit Kognitiver Entkopplung wird die Idee zur Hypothese, die man prüfen darf, ohne dass es Svenja als Person trifft: Das gute Gefühl bleibt ihres, die Frage nach dem Mechanismus bleibt offen für alle.","toolRef":"H.1.1","faktenRef":"G.3.1","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Svenja","speech":"„Drei Tage Saftkur, und ich sage euch: Die Giftstoffe sind raus aus meinem Körper, das spüre ich ganz deutlich! Ich fühle mich so leicht und rein wie lange nicht. Das solltet ihr alle machen!“","options":[{"text":"„Svenja, das ist Quatsch. ‚Entgiften‘ ist reine Geldmacherei, und du bist auf einen Influencer hereingefallen. Dein Körper entgiftet sich ganz allein.“","style":"frontal","reaction":"„Wow, danke. Ich bin also naiv, ja? Ich habe mir drei Tage lang Mühe gegeben, und du machst es einfach madig!“ *verschränkt die Arme und dreht sich zur Kaffeemaschine*","feedback":"Die Sachaussage ist im Kern richtig, aber du greifst die Person statt die Behauptung an. Wer sich als Mensch kritisiert fühlt, verteidigt die Idee noch fester (Identität und Überzeugung verschmelzen).","score":-2,"nextStepId":"step-fail"},{"text":"„Du klingst richtig zufrieden, das freut mich! Magst du mir erzählen, welcher Giftstoff bei dir denn rausgegangen sein soll? Mich interessiert, was die Kur genau gemacht hat.“","style":"sokratisch","reaction":"„Welcher Giftstoff? Na ja... Toxine halt. Das stand in der Werbung. *stutzt* Die haben, glaube ich, keinen einzelnen genannt.“","feedback":"Gut: Du würdigst ihr Gefühl und stellst die zentrale Frage aus „Wie heißt das Toxin?“ als echte Neugier, nicht als Angriff. Die Definitionslücke fällt Svenja selbst auf.","score":3,"nextStepId":"step-2"},{"text":"„Ach, ich hab auch mal eine Saftkur gemacht. Ich war danach nur hungrig und mies gelaunt. Aber bei jedem ist es eben anders, oder?“","style":"humorvoll","reaction":"„Haha, mies gelaunt, kann ich mir bei dir vorstellen! Na ja, vielleicht vertrage ich sie einfach besser. Trinkst du noch Kaffee?“ *lacht und nimmt eine Tasse*","feedback":"Locker und freundlich, aber du stellst keine Frage, die die Behauptung prüft. „Bei jedem anders“ lässt den Mythos („Giftstoffe sind raus“) unangetastet stehen.","score":0,"nextStepId":"step-2-weak"}]},"step-2":{"id":"step-2","speaker":"Svenja","speech":"„Okay, ein konkretes Gift hat mir keiner genannt. Aber ich fühle mich ja trotzdem besser! Das kann doch nicht alles Einbildung sein, oder?“","options":[{"text":"„Einbildung ist es nicht, du hast dich ja wirklich leichter gefühlt. Die Frage ist nur, woher das kommt. Was meinst du: Könnte es an den drei Tagen mit wenig Essen liegen statt an ausgespülten Giftstoffen?“","style":"sokratisch","reaction":"„Hm... ich war ehrlich gesagt hauptsächlich hungrig. Und leichter gefühlt habe ich mich wohl auch, weil ich mir so viel Gutes getan habe. Leber und Nieren machen ja eh den ganzen Tag ihre Arbeit, oder?“","feedback":"Sehr gut: Ihr Gefühl bleibt gültig, die Deutung wird zur Hypothese, die man prüfen darf. Svenja beginnt, ihre Idee als etwas zu betrachten, das sie hat, nicht das sie ist, und erinnert sich an Leber und Nieren.","score":3,"nextStepId":"step-3-success"},{"text":"„Das ist der Placebo-Effekt, Svenja. Du hast dir das Wohlbefinden eingeredet, weil du fest daran geglaubt hast. Mehr steckt nicht dahinter.“","style":"frontal","reaction":"„Eingeredet? Du sagst also, ich bilde mir das alles bloß ein? Na danke. Ich spüre doch, was ich spüre!“","feedback":"Der Hinweis ist nicht falsch, aber als Urteil formuliert („eingeredet“) wertet er Svenjas Erleben ab. Statt sie die Idee prüfen zu lassen, geht sie in die Verteidigung.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Moment, ich frag dich was: Wenn sich morgen herausstellen würde, dass die Kur gar keine Gifte ausspült, wäre das für dich ein Problem? Wärst du dann irgendwie blamiert?“","style":"sokratisch","reaction":"„Blamiert? ...Hm, vielleicht ein bisschen, ehrlich gesagt. Ich hab ja allen davon erzählt. Wieso fragst du?“","feedback":"Eine gute Entkopplungsfrage: Du testest, ob Svenjas Selbstwert an der Idee hängt. Es fehlt noch die Brücke zum Sachthema, sie bleibt aber im Gespräch.","score":2,"nextStepId":"step-3-struggle"}]},"step-2-weak":{"id":"step-2-weak","speaker":"Svenja","speech":"„Ich habe übrigens schon die nächste Kur bestellt, die kostet nur 89 Euro. Bei der Werbung steht: ‚Reinigt dich von innen von angesammelten Schlacken‘. Willst du auch eine?“","options":[{"text":"„Das klingt gut, bestell mir ruhig eine mit! Gesund essen kann nie schaden, und bei dem Preis kann man ja nichts falsch machen.“","style":"ausstieg","reaction":"„Super, ich nehme gleich zwei, dann gibt es Mengenrabatt! Wir ‚entschlacken‘ uns zusammen!“","feedback":"Du bestätigst den Mythos und das Produkt gleich mit. Aus „Schlacken“, die es biologisch nicht gibt, wird eine gemeinsame Geldausgabe.","score":-2,"nextStepId":"step-fail"},{"text":"„Was genau sind denn ‚Schlacken‘ im Körper, Svenja? Erklär mir das bitte, bevor du noch mal Geld ausgibst. Ich verstehe den Begriff nicht richtig.“","style":"sokratisch","reaction":"„Schlacken? ...Das ist eigentlich ein Wort aus der Metallverarbeitung, glaube ich. Ich weiß gar nicht, was das beim Menschen sein soll. Komisch.“","feedback":"Gute Nachfrage: Du machst die Unschärfe des Begriffs sichtbar („Schlacken“ stammt aus der Metallurgie), ohne Svenja zu belehren.","score":2,"nextStepId":"step-3-struggle"},{"text":"„Svenja, ‚Schlacken im Körper‘ gibt es medizinisch gar nicht. Das ist ein Begriff aus der Metallurgie. Spar dir das Geld und iss lieber normal.“","style":"frontal","reaction":"„Ach, jetzt bist du auch noch Chemiker? Ich lasse mir meine Gesundheit nicht von dir ausreden. Ende der Diskussion.“","feedback":"Inhaltlich stimmt es, aber als Belehrung ohne Neugier ausgesprochen kommt es als Angriff an. Svenja geht in die Abwehr.","score":-1,"nextStepId":"step-fail"}]},"step-3-success":{"id":"step-3-success","speaker":"Svenja","speech":"„Weißt du was? Ich glaube, ich habe mir drei Tage lang Saft gegönnt und dabei viel weniger Mist gegessen. Vielleicht lag es daran. Die nächste Kur lasse ich wohl sausen.“","options":[{"text":"„Das finde ich stark, dass du das so offen ansiehst. Und das gute Gefühl darf ruhig bleiben, das hast du dir ja auch verdient. Wollen wir morgen zusammen zum Mittagessen gehen?“","style":"humorvoll","reaction":"„Gerne! Aber ohne Saft, bitte. Ich hab jetzt Appetit auf etwas Richtiges, das man kauen kann!“ *grinst*","feedback":"Rundum gelungen: Svenja hat ihre Hypothese selbst geprüft und fallen lassen, ohne ihr Gesicht zu verlieren. Genau das meint Kognitive Entkopplung: Die Idee wird aktualisiert, die Person bleibt heil.","score":3}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Svenja","speech":"„Hm. Vielleicht ist an der Sache nicht alles so klar, wie die Werbung sagt. Aber irgendwie fühle ich mich gerade ein bisschen dumm, dass ich das Geld ausgegeben habe...“","options":[{"text":"„Dumm ist da nichts: Du hast etwas ausprobiert und lernst dazu. Schreib dir die Frage auf: ‚Welcher Stoff genau?‘ Die kannst du bei der nächsten Werbung stellen.“","style":"deeskalierend","reaction":"„Stimmt eigentlich. ‚Welcher Stoff genau?‘ Das merke ich mir. Danke, dass du mich nicht ausgelacht hast.“","feedback":"Sehr gut: Du entlastest Svenja von der Scham und gibst ihr ein Werkzeug mit. Für Kognitive Entkopplung heißt das: Falschliegen ist ein Lernschritt, kein Urteil über die Person.","score":3},{"text":"„Ja, ein bisschen blauäugig war das schon. Aber egal, beim nächsten Mal fällst du nicht mehr darauf rein, wenn du ein bisschen mehr nachdenkst.“","style":"sarkastisch","reaction":"„Blauäugig... na toll. *zuckt mit den Schultern* Schon gut, ich muss weiterarbeiten.“","feedback":"Der Seitenhieb verstärkt genau die Scham, die Entkopplung abbauen soll. Svenja zieht sich zurück, statt aus dem Irrtum zu lernen.","score":-1},{"text":"„Ach, vergiss die Sache einfach. Hauptsache, du fühlst dich gut. Wollen wir noch einen Kaffee trinken und über etwas anderes reden?“","style":"ausstieg","reaction":"„Ja, gern. Kaffee klingt gut.“ *atmet auf*","feedback":"Die Beziehung bleibt heil, aber du lässt die offene Frage („Welcher Stoff?“) einfach liegen. Als Pause in Ordnung, als Abschluss etwas dünn.","score":1}]},"step-fail":{"id":"step-fail","speaker":"Svenja","speech":"„Weißt du was? Ich bestelle mir die nächste Kur heute noch, und diesmal im Dreierpack!“ *verlässt die Küche*","options":[{"text":"Ende: Die Idee ist für Svenja zur Identität geworden, deshalb wirkt jede Kritik wie ein Angriff. Beim nächsten Mal zuerst Neugier, dann Fakten.","style":"ausstieg","reaction":"Behauptung prüfen heißt nicht, Svenja zu prüfen: Frag „welcher Stoff genau?“ statt „wie kannst du nur?“.","feedback":"Erst wenn die Idee von der Person getrennt wird, kann man sie gemeinsam ansehen. Die Fragen aus „Welcher Stoff? Wie gemessen?“ funktionieren nur als Einladung.","score":0}]}},"status":"entwurf","familie":"begriff-messbar-machen","fertigkeit":"F1","stufe":1,"kurz":"Leber und Nieren entgiften den Körper laufend selbst, und für „Schlacken“, die eine Saftkur ausspülen könnte, gibt es keine Belege. Wer nicht sagen kann, welcher Stoff gemeint ist, hat noch nichts geprüft. Als Hypothese lässt sich die Idee prüfen, ohne die Person anzugreifen.","prueffrage":"Welcher Stoff genau soll durch die Kur den Körper verlassen haben, und was könnte das gute Gefühl nach drei Tagen sonst erklären?","quellen":[{"typ":"url","kurz":"British Dietetic Association (2025): Detox Diets (Food Fact Sheet)","oeffentlich":true,"url":"https://bda.uk.com/foodfacts/detoxdiets","abruf":"2026-10-12"},{"typ":"url","kurz":"NCCIH (2025): „Detoxes“ and „Cleanses“: What You Need To Know","oeffentlich":true,"url":"https://www.nccih.nih.gov/health/detoxes-and-cleanses-what-you-need-to-know","abruf":"2026-10-12"},{"typ":"doi","kurz":"Klein, A. V.; Kiat, H. (2015): Detox Diets for Toxin Elimination and Weight Management: A Critical Review of the Evidence. Journal of Human Nutrition and Dietetics 28(6), 675–686","oeffentlich":false,"doi":"10.1111/jhn.12286"}],"thema":"Gesundheit"},{"id":"scen-lehrling-aufstiegs-chef","title":"Chef Dirk und der Aufstiegsmythos","subtitle":"„Ich habe es allein geschafft“, geübt mit der Ausstiegs-Strategie","character":"Dirk, Abteilungsleiter","avatar":"🏆","context":"Beim Feierabendbier erzählt dir Dirk, dein Abteilungsleiter, wie er sich „von ganz unten“ hochgearbeitet hat. Jetzt hat er auch noch gehört, dass eine Kollegin bei der Beförderungsrunde leer ausging, und für ihn ist die Sache klar.","goal":"Zeig Dirk den Überlebensirrtum, ohne ihn bloßzustellen, und erkenne den Moment, in dem ein eleganter Ausstieg klüger ist als weiterzudiskutieren.","bereich":"Arbeit","laenge":"kurz","ton":"sarkastisch","bestehenAb":4,"lektion":"Erfolgsgeschichten sind nur die Hälfte der Daten: Wer nur die Überlebenden betrachtet, übersieht die vielen Fleißigen, die trotzdem nicht befördert wurden. Die Frage „Wo ist der Friedhof?“ öffnet mehr als die fertige Gegenrede. Und wenn das Gespräch nur noch Verteidigung und Gegenangriff ist, schützt ein ruhiger Ausstieg deine Energie und die Beziehung.","toolRef":"H.2.4","faktenRef":"B.15","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Dirk, Abteilungsleiter","speech":"„Ich sag's dir, wie's ist: Ich hab immer als Erster angefangen und als Letzter aufgehört, und zack, Abteilungsleiter. So funktioniert das eben. Wer hart arbeitet, wird befördert. Und wer nicht befördert wird, na ja, der hat halt nicht genug getan. Die Meike zum Beispiel, bei der war jeden Tag pünktlich um fünf der Stift gefallen.“","options":[{"text":"„Dirk, das ist doch Quatsch. Es gibt massenhaft Leute, die schuften wie verrückt und nie befördert werden. Du machst es dir viel zu einfach mit deiner Rechnung.“","style":"frontal","reaction":"„Quatsch? *lacht trocken* Ach so, ich hab mir das alles also nur eingebildet. Danke auch, dass du meine Lebensleistung so wertschätzt.“","feedback":"Die Richtung stimmt, aber der Tonfall trifft Dirk als Person. Er fühlt sich in seiner Lebensleistung angegriffen und verteidigt jetzt seinen Stolz statt seine These.","score":-1,"nextStepId":"step-fail"},{"text":"„Respekt, du hast dich da richtig reingehängt, das hört man. Mich interessiert was: Du kennst ja viele Kollegen. Gab es welche, die genauso viel gearbeitet haben wie du und trotzdem nicht aufgestiegen sind?“","style":"sokratisch","reaction":"„*kratzt sich am Kinn* Hm... also, der Holger war auch so einer. Hat auch immer Überstunden geschoben. Aber der... na ja, der hatte halt Pech mit seinem Chef damals.“","feedback":"Gute Eröffnung: Du würdigst seinen Einsatz und stellst die Frage nach den „Gescheiterten“ als echte Neugier (Aktivierungsfrage: „Wo ist der Friedhof?“). Dirk liefert schon das erste Gegenbeispiel selbst.","score":3,"nextStepId":"step-2"},{"text":"„Ja, stimmt schon, Fleiß wird belohnt. Ich glaube, die Meike hat das auch ein bisschen locker gesehen. Echt schade für sie, aber so ist das Geschäft.“","style":"humorvoll","reaction":"„Siehst du, du verstehst das! Leistung setzt sich durch. Du wirst es auch noch weit bringen, wenn du so denkst.“","feedback":"Du bestätigst den Mythos und urteilst über Meike, ohne ihre Situation zu kennen. Das stärkt Dirks Schluss, dass Nicht-Befördert-Werden gleich Faulheit ist.","score":-2,"nextStepId":"step-fail"}]},"step-2":{"id":"step-2","speaker":"Dirk, Abteilungsleiter","speech":"„Pech, Timing, Chef, okay, aber das sind Ausreden. Wer wirklich will, der schafft es auch. Ich bin der Beweis! Ich hab schließlich auch nichts geschenkt bekommen. Die Erfolgreichen haben's halt drauf, und die anderen jammern.“","options":[{"text":"„Dann sag mir doch mal ehrlich: Wie viele Leute haben wohl dieselben Überstunden gemacht wie du, und wie viele davon sitzen heute auf deinem Stuhl? Ist nicht der Stuhl vielleicht einfach nur einmal frei geworden?“","style":"sokratisch","reaction":"„*schweigt kurz* Der Stuhl... ja, mein Vorgänger ist damals plötzlich in Rente gegangen. Und es gab zwei Bewerber. Mit dem anderen hab ich mich ein Jahr lang um die Stelle gestritten. Der war auch richtig gut.“","feedback":"Stark: Du lenkst den Blick von den Überlebenden auf die Gesamtmenge und auf unsichtbare Faktoren wie Glück und Timing. Dirk erkennt selbst, dass es mehr Kandidaten als Stühle gab.","score":3,"nextStepId":"step-3-success"},{"text":"„Dirk, ich glaube, du übersiehst den Überlebensirrtum. Das ist ein klassischer Selektionsfehler, wie bei Abraham Wald und den Bombern. Googel das mal, dann verstehst du, wo dein Denkfehler liegt.“","style":"frontal","reaction":"„Ach, jetzt kommst du mir mit Fachbegriffen und Weltkriegsgeschichten? Ich sag dir, wie die Praxis läuft, du Theoretiker.“","feedback":"Der Begriff stimmt, aber du schickst ihn als Belehrung statt als gemeinsame Frage. Dirk hört „du hast einen Denkfehler“ und macht dicht.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Du hast ja so recht, Dirk. Die Gescheiterten sind alle selbst schuld, ich hab die auch nie vermisst. Auf die Leistungsträger!“","style":"sarkastisch","reaction":"„*hebt das Glas* Endlich mal einer, der's kapiert! Prost!“","feedback":"Dein Sarkasmus kommt als Zustimmung an. Dirk hört keinen Zweifel heraus, und der Irrtum bleibt unangetastet.","score":-2,"nextStepId":"step-fail"}]},"step-3-success":{"id":"step-3-success","speaker":"Dirk, Abteilungsleiter","speech":"„*seufzt und dreht sein Glas* Wenn ich so überlege... der andere Bewerber hat damals genauso geschuftet wie ich. Vielleicht hatte ich einfach auch ein Stück Glück. Hm. Dann war die Meike womöglich gar nicht faul, oder?“","options":[{"text":"„Wer weiß schon, was bei der Beförderungsrunde den Ausschlag gegeben hat? Ich würde sie einfach mal fragen, wie sie die Runde erlebt hat. Vielleicht erfährst du dabei noch etwas Nützliches.“","style":"deeskalierend","reaction":"„Gute Idee, das mach ich. Und weißt du was? Ich glaub, ich sollte das nächste Mal weniger über Fleiß reden und mehr zuhören. Noch ein Bier?“","feedback":"Das trifft den Kern: Du zeigst keinen Sieg, sondern einen Weg. Dirk bleibt stolz auf seine Arbeit, sieht aber die unsichtbaren Faktoren und die Gescheiterten mit.","score":3}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Dirk, Abteilungsleiter","speech":"„Ich hab keine Lust auf Theorie nach Feierabend. Du hast deine Meinung, ich meine, fertig. Ich sag nur: Wer arbeitet, kommt weiter.“","options":[{"text":"„Fair genug, Dirk. Ich merke, wir kommen bei dem Thema heute nicht weiter. Lass es uns dabei belassen, vielleicht reden wir ein andermal in Ruhe drüber. Schönen Abend dir noch.“","style":"ausstieg","reaction":"„Na also, geht doch. Mach's gut, und wenn du mal Karrieretipps brauchst, weißt du, wo du mich findest.“","feedback":"Ruhiger, begründeter Ausstieg: Du drehst dich nicht weiter im Kreis und lässt die Tür offen. Gut, dass du die Reißleine sauber ziehst. Noch besser wäre gewesen, es vorher gar nicht so weit kommen zu lassen: Die belehrende Fachwort-Antwort hat Dirk erst in die Abwehr getrieben.","score":2}]},"step-fail":{"id":"step-fail","speaker":"Dirk, Abteilungsleiter","speech":"„Ich weiß ja, wie das läuft: Wer hart arbeitet, kommt nach oben. Und wer nicht aufsteigt, hat eben was falsch gemacht. Daran ändert auch dein Gerede nichts.“","options":[{"text":"Ende: Dirk ist in seiner Sicht bestärkt oder in der Verteidigung. Der Überlebensirrtum bleibt ungesehen.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst nach den Gescheiterten fragen, statt zu bewerten.","feedback":"Seziert wird die Behauptung, nicht der Mensch: Die Frage „Wo ist der Friedhof?“ hätte Dirk selbst zum Nachdenken gebracht. Wenn nichts mehr hilft, wäre ein ruhiger Ausstieg besser gewesen als ein Schlagabtausch.","score":0}]}},"status":"entwurf","familie":"fehlende-faelle-suchen","fertigkeit":"F2","stufe":2,"kurz":"Erfolgsgeschichten sind nur die Hälfte der Daten: Wer nur die Aufgestiegenen betrachtet, übersieht die Fleißigen, die nicht befördert wurden. Die Frage „Wo ist der Friedhof?“ öffnet mehr als eine fertige Gegenrede, und wird es nur noch Verteidigung, hilft ein ruhiger Ausstieg.","prueffrage":"Wie viele andere haben ähnlich viele Überstunden gemacht wie Dirk, und wie viele davon wurden tatsächlich befördert?","quellen":[{"typ":"url","kurz":"Denrell, J. (2003): Vicarious Learning, Undersampling of Failure, and the Myths of Management. Organization Science 14(3), 227–243 (Abstract, Stanford GSB)","oeffentlich":true,"url":"https://www.gsb.stanford.edu/faculty-research/publications/vicarious-learning-undersampling-failure-myths-management","abruf":"2026-10-12"},{"typ":"doi","kurz":"Mangel, M.; Samaniego, F. J. (1984): Abraham Wald’s Work on Aircraft Survivability. Journal of the American Statistical Association 79(386), 259–267","oeffentlich":false,"doi":"10.1080/01621459.1984.10478038"}],"thema":"Zusammenleben"},{"id":"scen-pfarrerin-wunderheilung","title":"Gemeindemitglied Irmas Wunderheilung","subtitle":"Heilung durch Gebet, geübt mit der Empathie-Matrix","character":"Irma","avatar":"🕯️","context":"Du bist Pfarrerin und kennst Irma seit vielen Jahren aus der Gemeinde. Ihr Mann Heinz war vor drei Wochen schwer erkältet und fühlte sich elend. Nach einer Gebetsrunde der Gemeinde ging es ihm bald wieder gut. Irma erzählt jetzt überall von einem „Wunder“ und will, dass die Gemeinde künftig Gebetsrunden anstelle von Arztbesuchen anbietet.","goal":"Nimm Irmas Glauben und ihre Dankbarkeit ernst, führe den natürlichen Krankheitsverlauf und den Behandlungszeitpunkt am Höhepunkt der Symptome mit sanften Fragen ein und halte die Tür zur ärztlichen Versorgung offen.","bereich":"Gesundheit","laenge":"lang","ton":"ernst","bestehenAb":9,"lektion":"Du musst Irmas Glauben nicht kleinreden, um zu fragen, ob eine Erkältung auch ohne Gebet am Wendepunkt besser geworden wäre. Wer in der Not Hilfe sucht, tut das meist am Höhepunkt der Symptome, und von dort aus wird eine Erkältung ohnehin besser. Erst wenn sich ein Mensch gehört fühlt (Mitfühlende Empathie), werden die Fragen nach Kontrollgruppe und Verlauf zur gemeinsamen Neugier statt zum Angriff auf den Glauben. Und wo Beschwerden schwer werden oder nicht abklingen, schließen sich Gebet und ärztliche Hilfe nicht aus: Gebet kann tragen, ersetzt aber keine Behandlung.","toolRef":"H.1.6","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Irma","speech":"„Frau Pfarrerin, ich muss es Ihnen einfach erzählen. Mein Heinz lag drei Tage mit Fieber und Halsschmerzen im Bett, ihm ging es richtig schlecht. Wir haben in der Gebetsrunde für ihn gebetet, und wenige Tage später war er wieder auf den Beinen. Das war eindeutig ein Wunder. Und deshalb denke ich: Wir sollten in der Gemeinde mehr beten und weniger zum Arzt rennen.“","options":[{"text":"„Irma, das war kein Wunder. Erkältungen gehen von allein weg, das weiß jeder. Dein Mann wäre auch ohne Gebet gesund geworden.“","style":"frontal","reaction":"„Also das Gebet war für Sie nichts wert? Von Ihnen hätte ich das nie erwartet! Wir haben Heinz zuliebe gebetet, und Sie tun so, als wäre das alles Zufall gewesen.“","feedback":"Frontalangriff! Die Sachaussage stimmt im Kern, aber Irma hört: „Dein Glaube und deine Dankbarkeit sind wertlos.“ Ohne Beziehung und ohne Fragen prallt die Erklärung ab.","score":-2,"nextStepId":"step-fail"},{"text":"„Ich freue mich so mit euch, dass es Heinz wieder gut geht, und ich weiß, wie viel Angst du um ihn hattest. Erzähl mir, wie waren diese Tage für dich?“","style":"deeskalierend","reaction":"„*atmet auf* Danke, dass Sie fragen. Es war furchtbar, ihn so hilflos zu sehen. Ich saß nachts neben seinem Bett und wusste nicht, was ich tun soll. Das Beten war das Einzige, was ich konnte.“","feedback":"Sehr gut! Mitfühlende Empathie: Du verstehst die Angst (kognitiv), spiegelst sie kurz (affektiv) und bleibst selbst ruhig. Das Gefühl wird ernst genommen, der Mythos nicht bestätigt.","score":3,"nextStepId":"step-2"},{"text":"„Ja, was für ein Wunder, wie wunderbar! Gott hat Heinz gehört. Sagen wir das nächsten Sonntag der ganzen Gemeinde weiter?“","style":"affektiv","reaction":"„Ja, unbedingt! Und ich möchte, dass wir dafür sorgen, dass keiner mehr unnötig zum Arzt geht, wenn das Gebet hilft.“","feedback":"Du spiegelst ihre Begeisterung, ohne einen Gedanken zu bremsen. So verstärkst du die Zuschreibung, statt ein ruhiger Gegenpol zu sein (affektive Empathie ohne Entkopplung).","score":-1,"nextStepId":"step-weak"}]},"step-2":{"id":"step-2","speaker":"Irma","speech":"„Am dritten Tag war es am schlimmsten, Fieber, laufende Nase, Heinz konnte kaum schlucken. Da haben wir die Gebetsrunde zusammengerufen. Und gleich danach ging es aufwärts. Das kann doch kein Zufall sein, oder?“","options":[{"text":"„Das ist der klassische Post-hoc-Fehlschluss, Irma: erst das Gebet, dann die Besserung, also Gebet gleich Ursache. Das ist Logik für Anfänger, das lernt man im ersten Semester.“","style":"frontal","reaction":"„Ich habe keine Logik studiert, aber ich weiß, was ich gesehen habe! Sie reden mit mir, als wäre ich dumm.“","feedback":"Der Begriff trifft, aber du nutzt ihn wie einen Hammer und wertest Irma ab. Seziert wird die Behauptung, nicht der Mensch.","score":-2,"nextStepId":"step-fail"},{"text":"„Dass ihr am schlimmsten Tag zusammengekommen seid, kann ich gut verstehen. Mich beschäftigt: Wie lange dauert so eine Erkältung normalerweise, bis es von selbst wieder aufwärtsgeht?“","style":"sokratisch","reaction":"„Hm... Meistens eine Woche oder so, glaube ich. Heinz war ja nach ungefähr einer Woche wieder fit. Worauf wollen Sie hinaus?“","feedback":"Treffsicher! Du führst den natürlichen Krankheitsverlauf als neugierige Frage ein und lässt Irma selbst auf den üblichen Verlauf kommen, ohne ihren Glauben anzutasten.","score":3,"nextStepId":"step-3"},{"text":"„Heinz hat sicher auch seinen Tee getrunken und im Bett gelegen, das hilft ja auch. Meinst du nicht, dass das eher geholfen hat als die Gebetsrunde?“","style":"deeskalierend","reaction":"„Tee und Bett, na ja... Das macht er ja bei jeder Erkältung. Aber diesmal war es doch anders, diesmal haben wir gebetet.“","feedback":"Ein freundlicher Gedanke, aber noch kein klarer Hebel: Du nennst eine Nebenerklärung, ohne den natürlichen Verlauf und den Zeitpunkt der Behandlung am Höhepunkt ins Spiel zu bringen.","score":1,"nextStepId":"step-3-struggle"}]},"step-3":{"id":"step-3","speaker":"Irma","speech":"„Ja, eine Woche etwa. Aber warum ging es denn genau nach dem Gebet aufwärts? Das war doch derselbe Tag!“","options":[{"text":"„Gute Frage. Wann sucht man denn Hilfe, wenn jemand krank ist: am besten Tag oder am schlimmsten? Und was kommt nach dem schlimmsten Tag einer Erkältung meistens?“","style":"sokratisch","reaction":"„Am schlimmsten Tag natürlich, da will man ja etwas tun... *stutzt* Und danach wird es eigentlich fast immer wieder besser. Moment mal.“","feedback":"Sehr gut! Du erarbeitest mit Irma den natürlichen Krankheitsverlauf: Hilfe wird am Höhepunkt der Symptome gesucht, und von diesem Wendepunkt aus wird eine Erkältung ohnehin besser. Die Erkenntnis kommt von ihr selbst.","score":3,"nextStepId":"step-4"},{"text":"„Gott wirkt ja oft ganz leise. Vielleicht hat Heinz' Körper einfach in dem Moment angefangen, sich zu erholen.“","style":"humorvoll","reaction":"„Ja, Gott wirkt durch den Körper, das glaube ich auch. Dann ist es also doch ein Wunder gewesen!“","feedback":"Du lässt die Frage nach Ursache und Zeitpunkt offen und bestätigst eher das Wunder. Der natürliche Verlauf kommt nicht zur Sprache.","score":0,"nextStepId":"step-4-struggle"},{"text":"„Irma, unser Immunsystem heilt solche Infekte immer von allein, da braucht es kein Gebet. Dein Mann hat eine ganz normale Erkältung überstanden.“","style":"frontal","reaction":"„Immunsystem, Immunsystem... Dafür haben wir doch gebetet! Sie nehmen uns den ganzen Segen weg.“","feedback":"Im Kern richtig, aber überzogen: Die meisten, nicht alle Infekte heilen von allein. Zudem lieferst du es als fertiges Urteil und lässt Irma keinen Raum, es selbst zu entdecken. Sie fühlt sich belehrt und verteidigt den Mythos stärker.","score":-1,"nextStepId":"step-fail"}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Irma","speech":"„Ich weiß nur, was ich erlebt habe. Heinz ging es schlecht, wir haben gebetet, und es wurde besser. Was soll daran falsch sein?“","options":[{"text":"„Nichts daran ist falsch, was du erlebt hast. Nur eine Frage: Wann habt ihr gebetet, am Anfang oder am schlimmsten Tag? Und was kommt danach meistens?“","style":"sokratisch","reaction":"„Am schlimmsten Tag, da waren wir verzweifelt. Und danach... na ja, es wird meistens wieder besser. Das stimmt eigentlich.“","feedback":"Gute Korrektur. Du holst den Zeitpunkt der Behandlung am Höhepunkt der Symptome nach und lässt Irma die Antwort selbst finden.","score":2,"nextStepId":"step-4"},{"text":"„Du hast recht, es hat geholfen, das sieht man ja. Lassen wir es dabei, ich will dir deinen Glauben nicht nehmen und mich auch nicht mit dir über Krankheiten streiten.“","style":"ausstieg","reaction":"„Sehen Sie, Sie verstehen mich! Dann machen wir das also in der Gemeinde bekannt.“","feedback":"Du ziehst dich zurück, ohne den Verlauf zu klären. Die Beziehung bleibt heil, aber das Missverständnis wächst: Irma fühlt sich in einer falschen Zuschreibung bestätigt.","score":-1,"nextStepId":"step-weak"}]},"step-4":{"id":"step-4","speaker":"Irma","speech":"„*nachdenklich* Dann wäre Heinz vielleicht auch ohne die Gebetsrunde wieder gesund geworden? Aber wie soll man das jemals wissen? Er war ja nur dieses eine Mal krank und wir haben nur dieses eine Mal gebetet.“","options":[{"text":"„Das ist genau die richtige Frage. Man müsste viele Erkältete vergleichen, mit und ohne Gebet, und sehen, ob es einen Unterschied gibt. Eine einzelne Geschichte kann das nicht zeigen.“","style":"sokratisch","reaction":"„Das leuchtet mir ein. Eine einzelne Geschichte beweist nicht, was ohne Gebet passiert wäre. Aber nehmen Sie mir meine Dankbarkeit damit nicht weg?“","feedback":"Hervorragend! Du erklärst, warum eine Kontrollgruppe nötig ist (Hierarchie der Evidenz), und trennst das Beweisproblem von Irmas Gefühl. Ihre Sorge um die Dankbarkeit öffnet den Raum für Mitgefühl.","score":3,"nextStepId":"step-5"},{"text":"„Heinz hat nur Glück gehabt. Für andere wird auch gebetet, und da passiert nichts. Das beweist, dass das Gebet nicht der Grund war.“","style":"sarkastisch","reaction":"„*gekränkt* Wollen Sie damit sagen, Gebet nützt nichts? Das dürfen Sie als Pfarrerin doch nicht sagen!“","feedback":"Der Seitenhieb bringt Irma in die Defensive, und mit dem Vorwurf an die Gebetspraxis verlierst du ihr Vertrauen. Die Methodenfrage rückt in den Hintergrund.","score":-1,"nextStepId":"step-fail"},{"text":"„Genau, man kann es nicht wissen. Vielleicht beten wir als Gemeinde einfach weiter und rufen bei Krankheit zusätzlich den Arzt an. So ist man in beiden Welten gut aufgehoben.“","style":"deeskalierend","reaction":"„Das klingt vernünftig. Beides zusammen, das könnte ich mittragen.“","feedback":"Pragmatisch und beziehungswahrend, aber du lässt die Frage nach dem Beweis offen. Die zentrale Lehre aus „Natürlicher Krankheitsverlauf & Regression zur Mitte“ (ohne Kontrollgruppe weiß man es nicht) bleibt ungenannt.","score":1,"nextStepId":"step-5-struggle"}]},"step-4-struggle":{"id":"step-4-struggle","speaker":"Irma","speech":"„Ich bin jetzt ein bisschen verwirrt. Heinz ist gesund, das Gebet hat geholfen, und Sie sagen mal so und mal so. Was meinen Sie denn nun?“","options":[{"text":"„Du hast recht, ich habe dich verunsichert. Lass es mich klarer fragen: Wenn Heinz zwei Wochen lang nicht gebetet worden wäre, was hätte seine Erkältung dann wohl getan?“","style":"sokratisch","reaction":"„Ich nehme an, sie wäre auch irgendwann vorbeigegangen. Das tut sie ja immer. Aber das heißt doch nicht, dass das Gebet nichts gebracht hat!“","feedback":"Du holst den natürlichen Krankheitsverlauf mit einer klaren Gedankenprobe nach. Irma erkennt den Verlauf, hält aber an ihrem Dank fest, und das lässt sich im nächsten Schritt würdigen.","score":2,"nextStepId":"step-5"},{"text":"„Ich meine nur: Wir wissen nicht genau, was der Auslöser war. Behalte deine Dankbarkeit, aber lass uns beim Arzt offen bleiben, falls es wieder ernst wird.“","style":"ausstieg","reaction":"„Gut, so kann ich das annehmen. Danke, dass Sie mich nicht vor den Kopf stoßen.“","feedback":"Eine freundliche, beziehungswahrende Antwort, die aber die Frage nach dem Verlauf offen lässt. Die Brücke zum Arzt steht, der Kern von „Natürlicher Krankheitsverlauf & Regression zur Mitte“ bleibt unausgesprochen.","score":1,"nextStepId":"step-5-struggle"}]},"step-5":{"id":"step-5","speaker":"Irma","speech":"„Ich will aber nicht, dass mein Glaube nur ein Zufall sein soll. Das Gebet hat uns als Gemeinde zusammengebracht, und es hat Heinz und mir in dieser Nacht Kraft gegeben. Das war doch nicht umsonst, oder?“","options":[{"text":"„Nein, nicht umsonst. Zusammenstehen, nicht allein sein, Kraft schöpfen: Das ist echt und wertvoll. Ob das Gebet die Erkältung beendet hat, ist eine andere Frage als die, ob es euch getragen hat.“","style":"deeskalierend","reaction":"„*lächelt erleichtert* Das trennt es gut. Ich habe Ihnen all das über den Glauben erzählt und wollte nicht, dass er kleingeredet wird.“","feedback":"Sehr gut! Mitfühlende Empathie: Du würdigst Irmas Gefühl ausdrücklich und trennst das Erleben vom Beweisproblem. So verteidigt sie den Mythos nicht mehr, weil nichts angegriffen wird.","score":3,"nextStepId":"step-6"},{"text":"„Wenn du Kraft brauchst, bete ruhig weiter. Nur bei ernsten Krankheiten geh bitte immer zuerst zum Arzt, und warte nicht erst ab, ob das Gebet hilft.“","style":"deeskalierend","reaction":"„Ja, das mache ich. Wenn es wirklich ernst ist, gehe ich zum Arzt, versprochen.“","feedback":"Klar und freundlich. Du sicherst den wichtigsten Punkt, den Arztbesuch bei ernsten Krankheiten, aber ohne Irma beim Unterschied zwischen Trost und Wirkung abzuholen.","score":2,"nextStepId":"step-6"},{"text":"„Naja, irgendwie schon. Aber wenn du Heinz wirklich helfen willst, solltest du aufhören, so zu tun, als hätte nur das Gebet gewirkt, und das auch der Gemeinde sagen.“","style":"frontal","reaction":"„*kühl* Ich habe nie gesagt, dass nur das Gebet wirkt. Aber ich merke, dass Sie mir nicht wirklich zuhören.“","feedback":"Du lässt Irmas Gefühl unbeantwortet und rückst gleich zur Korrektur vor. Sie fühlt sich nicht gehört, und das Vertrauen leidet.","score":-1,"nextStepId":"step-fail"}]},"step-5-struggle":{"id":"step-5-struggle","speaker":"Irma","speech":"„Ich weiß noch nicht, ob ich das alles so sehe. Aber ich überlege mir das. Danke für das Gespräch, Frau Pfarrerin.“","options":[{"text":"„Gern, Irma. Ich bin froh, dass es Heinz gutgeht. Wenn du magst, trinken wir nächste Woche einen Kaffee und reden weiter. Und bitte: Wenn es Heinz mal schlechter geht, ruf auch den Arzt.“","style":"ausstieg","reaction":"„Das mache ich. Ein Kaffee wäre schön.“","feedback":"Ein freundlicher Ausstieg: Die Beziehung ist gesichert, die Tür bleibt offen und die Arzt-Grenze steht. Der Kern von „Natürlicher Krankheitsverlauf & Regression zur Mitte“ ist nur angedeutet.","score":1}]},"step-6":{"id":"step-6","speaker":"Irma","speech":"„Dann sagen Sie mir zum Schluss: Wann sollte ich nicht auf das Beten allein vertrauen? Ich möchte Heinz auf keinen Fall schaden.“","options":[{"text":"„Eine Erkältung geht meist von allein weg, da ist Beten und Abwarten unproblematisch. Bei langen, schweren oder immer schlimmer werdenden Beschwerden und bei ernsten Krankheiten bitte unbedingt zum Arzt. Gebet kann dich tragen, aber es ersetzt keine Behandlung.“","style":"sokratisch","reaction":"„Das merke ich mir. Und ich erzähle in der Gemeinde, dass Beten und der Arztbesuch zusammengehören.“","feedback":"Perfekt! Du ziehst die Grenze am Kipppunkt: Selbstlimitierende Krankheiten sind unproblematisch, bei ernsten Krankheiten darf Gebet die Behandlung nie ersetzen. Und das ohne Abwertung des Glaubens.","score":3},{"text":"„Beten ist immer gut, Irma. Mach dir da bitte keine Sorgen, du machst alles richtig. Dein Glaube trägt dich, und mehr braucht es bei so etwas nicht, auch wenn die Beschwerden einmal länger dauern oder schlimmer werden, glaub mir das.“","style":"affektiv","reaction":"„Ach, das beruhigt mich. Dann bleibe ich dabei.“","feedback":"Beruhigend, aber zu pauschal: Die Grenze, an der Gebet keine Behandlung ersetzen darf, bleibt unausgesprochen, und genau dort liegt der Kipppunkt.","score":0},{"text":"„Eigentlich solltest du bei jeder Krankheit zuerst zum Arzt und erst danach beten. Alles andere ist grob fahrlässig, und das gilt auch schon bei einem Schnupfen oder einer harmlosen Erkältung, die ohnehin von allein vergeht.“","style":"frontal","reaction":"„*zieht sich zurück* Dann bin ich wohl eine schlechte Ehefrau gewesen. Ich glaube, ich gehe jetzt besser.“","feedback":"Die Richtung stimmt, der Ton nicht. Mit „grob fahrlässig“ beschämst du Irma, obwohl sie nach der Grenze gefragt hat. Dabei liegt der Kipppunkt bei ernsten Krankheiten, nicht bei jeder Erkältung.","score":-1}]},"step-weak":{"id":"step-weak","speaker":"Irma","speech":"„Ich bin so froh, dass Sie das auch so sehen. Ich sage es nächsten Sonntag gleich der ganzen Gemeinde: Bei Krankheiten zuerst beten, den Arzt braucht man dann oft gar nicht.“","options":[{"text":"„Irma, bevor du das sagst: Kann es sein, dass Heinz' Erkältung auch ohne Gebet von allein besser geworden wäre? Überlegen wir kurz zusammen, wann man einen Arzt braucht.“","style":"sokratisch","reaction":"„*zögert* Hm... Eine Erkältung geht ja meistens von selbst weg. Aber bei etwas Ernstem würde ich schon zum Arzt gehen. Das sage ich dann eben dazu.“","feedback":"Eine späte, aber wichtige Korrektur: Du bringst den natürlichen Verlauf und die Arzt-Grenze noch ins Spiel, bevor der Mythos in die Gemeinde trägt.","score":1},{"text":"„Gut, dann sprechen wir Sonntag darüber. Ich unterstütze dich, und ich helfe dir auch gern bei den Worten, die du der Gemeinde sagen willst, und komme mit.“","style":"affektiv","reaction":"„Wunderbar! Ich wusste, dass Sie auf meiner Seite sind.“","feedback":"Ohne Korrektur trägt der Mythos jetzt in die Gemeinde. Wer bei ernsten Krankheiten aufs Gebet allein baut, riskiert echten Schaden (Kipppunkt).","score":-2}]},"step-fail":{"id":"step-fail","speaker":"Irma","speech":"„Ich merke, mit Ihnen kann ich darüber nicht reden. Ich frage lieber die anderen in der Gebetsrunde.“ *steht auf und geht*","options":[{"text":"Ende: Irma fühlte sich nicht gehört und wendet sich ab. Die Gemeinde wird den „Wunder“-Bericht ohne deine Fragen hören.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst Irmas Angst und Dankbarkeit ernst nehmen, dann erst über Verlauf und Zeitpunkt reden.","feedback":"Erst wenn das Gefühl gehört ist (Mitfühlende Empathie), kann die Frage nach dem natürlichen Verlauf ankommen. Rechthaben und Helfen sind zweierlei.","score":0}]}},"faktenRef":"C.4.6","status":"entwurf","familie":"was-waere-ohne","fertigkeit":"F2","stufe":4,"kurz":"Hilfe sucht man meist am Höhepunkt der Beschwerden, und von dort aus wird eine Erkältung ohnehin besser. Den Glauben muss niemand kleinreden: Wer sich gehört fühlt, erlebt die Frage nach dem natürlichen Verlauf eher als gemeinsame Neugier und nicht als Angriff.","prueffrage":"An welchem Tag der Erkältung wurde gebetet, und wie wären die Tage danach wohl verlaufen, wenn niemand gebetet hätte?","quellen":[{"typ":"url","kurz":"Morton, V.; Torgerson, D. J. (2003): Effect of regression to the mean on decision making in health care. BMJ 326(7398), 1083–1084 (PMC1125994)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1125994","abruf":"2026-10-12"},{"typ":"url","kurz":"CDC (2026): About Common Cold","oeffentlich":true,"url":"https://www.cdc.gov/common-cold/about/index.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Klimecki, O. M.; Leiberg, S.; Ricard, M.; Singer, T. (2014): Differential pattern of functional brain plasticity after compassion and empathy training. Social Cognitive and Affective Neuroscience 9(6), 873–879 (PMC4040103)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4040103/","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"scen-schulfreund-aufwachen","title":"Kevin und die rote Pille","subtitle":"„Ich habe die Wahrheit erkannt“, geübt mit dem Management emotionaler Kosten","character":"Kevin, alter Schulfreund","avatar":"💊","context":"Kevin, dein Freund aus Schulzeiten, meldet sich nach langer Funkstille und lädt dich auf ein Bier ein. Schnell wird klar: Er ist „aufgewacht“ und sieht jetzt, dass fast alle belogen werden, auch die Skeptiker unter ihnen. Du magst ihn und willst ihn nicht verlieren, aber du merkst, dass jede Gegenrede bei ihm wie eine Bestätigung ankommt.","goal":"Bring Kevin dazu, selbst zu benennen, was seine Überzeugung widerlegen würde, und entscheide klug, wie viel Energie dieses Gespräch dir wert ist.","bereich":"Freunde","laenge":"lang","ton":"ernst","bestehenAb":9,"lektion":"Ein Weltbild, in dem jede Gegenrede als Beweis für die eigene Erleuchtung zählt, ist wie Carl Sagans unsichtbarer Drache in der Garage, für den es auf jeden Test eine Ausrede gibt: immunisiert gegen jede Prüfung. Die Frage „Was müsste passieren, damit du dich irrst?“ macht das sichtbar. Und weil nicht jede Schlacht gekämpft werden muss, gehört die Triage deiner Energie von Anfang an dazu: Sie schützt dich vor dem Ausbrennen und die Freundschaft vor dem Sieg-oder-Niederlage-Denken.","toolRef":"H.1.2","faktenRef":"A.3","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Kevin","speech":"„Schön, dass du gekommen bist. Ich muss dir was erzählen: Ich bin aufgewacht. Seit ein paar Monaten sehe ich klar, wie das alles läuft. Die meisten laufen blind durchs Leben und merken es nicht. Du ja auch nicht, aber ich hoffe, du gehörst zu denen, die offen sind.“","options":[{"text":"„Aufgewacht? Kevin, das klingt nach Verschwörungsquatsch. Wer so redet, hat sich doch nur in irgendeine Internetblase verrannt. Komm, lass uns über was Vernünftiges reden.“","style":"frontal","reaction":"„Da haben wir’s. Genau so reden die, die noch schlafen. Ich hatte gehofft, du wärst anders.“ *lehnt sich zurück und verschränkt die Arme*","feedback":"Frontalangriff: Du etikettierst, statt zu fragen. Für Kevin ist die Reaktion der Beleg für seine Erzählung. Seziert wird die Behauptung, nicht der Mensch. Zudem verschwendest du Energie in einem Kampf, der nur Fronten verhärtet.","score":-2,"nextStepId":"step-fail"},{"text":"„Schön, dass du dich meldest, Kevin, ich hab dich vermisst. Was hat sich bei dir verändert? Erzähl mal, wie das für dich angefangen hat.“","style":"sokratisch","reaction":"„*entspannt sich merklich* Danke. Weißt du, es war eine schwierige Zeit. Job weg, Trennung, und ich habe angefangen, Videos zu schauen. Und plötzlich ergab alles einen Sinn.“","feedback":"Stark: Du öffnest mit echtem Interesse und holst die Geschichte hinter der Überzeugung ab. Das ist die Voraussetzung, dass Kevin überhaupt zuhört, und kostet dich kaum Energie (eine Schlacht, die man kämpfen kann).","score":3,"nextStepId":"step-2"},{"text":"„Aha. Na gut, wenn du meinst. Wollen wir bestellen? Ich nehme ein Helles.“","style":"ausstieg","reaction":"„Ja, klar... Aber ich merke schon, dass du dich nicht dafür interessierst. Das ist halt der Normalzustand: Man wird nicht gehört.“ *rührt in seinem Glas*","feedback":"Ein glatter Themenwechsel schützt deine Energie, lässt aber Kevins Bedürfnis nach Gehörtwerden ins Leere laufen. Als erste Reaktion ein vertretbarer, aber blasser Zug.","score":0,"nextStepId":"step-2"}]},"step-2":{"id":"step-2","speaker":"Kevin","speech":"„Es ist ganz einfach: Fast alles, was wir in den Nachrichten, in der Schule und im Alltag erzählt bekommen, ist gesteuert. Die meisten merken das nicht. Und selbst die, die skeptisch sind, wurden in Wahrheit nur in die nächste Falle gelockt. Wer dagegenredet, zeigt damit nur, wie tief er drinsteckt.“","options":[{"text":"„Wenn jeder, der dir widerspricht, damit beweist, dass er drinsteckt: Wie könntest du denn je herausfinden, dass du dich irrst?“","style":"sokratisch","reaction":"„*stutzt* Ich ... na ja, ich würde es merken. Ich bin ja nicht blöd. Aber ... hm. Eigentlich habe ich mir die Frage nie so gestellt.“","feedback":"Treffer: Du zeigst die Immunisierung, ohne Kevin anzugreifen. Aus „Falsifizierbarkeit“: Eine Aussage, die jede Gegenrede zum Beweis ihrer selbst macht, kann nicht widerlegt werden – wie der Drache in der Garage.","score":3,"nextStepId":"step-3"},{"text":"„Gesteuert von wem denn? Nenn mal einen konkreten Fall, wo du das nachgewiesen hast, mit Quelle.“","style":"frontal","reaction":"„Das ist ja das Perfide: Die Beweise werden ja gelöscht oder verdreht. Aber das sehe ich, weil ich offen dafür bin. Du verlangst Beweise von einem System, das genau das verhindert.“","feedback":"Eine berechtigte Nachfrage, aber Kevin hat längst eine Antwort darauf: Der Mangel an Beweisen wird zum Beweis für die perfekte Tarnung. Ohne vorher zu klären, was als Widerlegung zählen würde, läuft die Beleg-Forderung ins Leere.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Ja, krass! Dann sind wir ja alle total ahnungslos. Zeig mir mal, wo ich anfangen soll, ich schau mir das auch an.“","style":"affektiv","reaction":"„Stark, dass du das sagst! Ich schick dir gleich ein paar Links und eine Gruppe, da sitzen genau die richtigen Leute.“ *tippt schon auf dem Handy*","feedback":"Du täuschst Zustimmung vor und öffnest die Tür für die Gruppe, ohne die Behauptung je geprüft zu haben. Das stärkt Kevins Überzeugung, statt sie zu hinterfragen.","score":-2,"nextStepId":"step-fail"}]},"step-3":{"id":"step-3","speaker":"Kevin","speech":"„Okay, aber das ist doch bei jeder Wahrheit so: Wer sie erkannt hat, muss sich nicht ständig neu prüfen. Und wenn ich ein Beispiel brauche: Ich habe vorhergesagt, dass in diesem Jahr etwas Großes passiert. Es ist nicht eingetreten, aber das war nur, weil die Verantwortlichen Wind davon bekommen und ihre Pläne geändert haben.“","options":[{"text":"„Dann frag ich ganz offen: Was müsste denn passieren oder welches Ergebnis müsste vorliegen, damit du sagen würdest: ‚Okay, meine Annahme war falsch‘?“","style":"sokratisch","reaction":"„*lange Pause* Das ist eine fiese Frage... Weil ich auf jedes Ergebnis eine Erklärung habe. Wenn ich ehrlich bin: Mir fällt gerade nichts ein.“","feedback":"Das ist die Aktivierungs-Frage aus „Falsifizierbarkeit“ in Reinform. Kevin merkt selbst, dass seine Annahme gegen jedes Ergebnis geschützt ist – wie ein Drache, der jeder Prüfung ausweicht.","score":3,"nextStepId":"step-4"},{"text":"„Das ist eine klassische Ausrede: Wenn die Vorhersage nicht eintritt, haben die Gegner ihre Pläne geändert. Damit kannst du dich nie irren. Das ist unwissenschaftlich.“","style":"frontal","reaction":"„Siehst du, das ist genau der Ton, den die haben wollen, dass man alles ‚unwissenschaftlich‘ nennt. Dahinter steckt das System, das die Wissenschaft für sich eingespannt hat.“","feedback":"Inhaltlich richtig erkannt (Ad-hoc-Hypothese), aber als Urteil formuliert. Kevin muss nichts selbst entdecken und verteidigt stattdessen sein Weltbild.","score":0,"nextStepId":"step-4-struggle"},{"text":"„Interessant. Wenn die Verantwortlichen so mächtig sind, dass sie ihre Pläne ändern, sobald jemand Bescheid weiß: Wie hast dann ausgerechnet du das erkannt?“","style":"sarkastisch","reaction":"„*leicht beleidigt* Weil ich eben genauer hinsehe als andere. Willst du mir jetzt unterstellen, ich sei größenwahnsinnig?“","feedback":"Ein berechtigter Einwand, aber der sarkastische Unterton macht aus der Frage einen Stich. Seziert wird die Behauptung, nicht der Mensch. So kostet das Gespräch beide Seiten Energie, ohne dass Kevin etwas selbst entdeckt.","score":-1,"nextStepId":"step-4-struggle"}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Kevin","speech":"„Du willst alles belegt haben, aber das System lässt Belege verschwinden. Wie soll ich dir da etwas zeigen? Du verlangst von mir Unmögliches.“","options":[{"text":"„Das klingt, als würde dir das Gespräch gerade auch Energie kosten. Ich will dich nicht aushorchen, sondern verstehen. Was würde dich persönlich überzeugen, dass du dich in einem Punkt geirrt hast?“","style":"deeskalierend","reaction":"„*atmet durch* Okay. Das ist eine ehrliche Frage. Ich ... muss kurz nachdenken. Eigentlich hat mich noch nie jemand so gefragt.“","feedback":"Gut gerettet: Du nimmst Druck raus, ohne die Kernfrage aufzugeben. Die Frage nach dem eigenen Widerlegungskriterium kommt als Interesse an, nicht als Fangfrage.","score":2,"nextStepId":"step-4"},{"text":"„Fein, dann ist unser Gespräch hier ohnehin sinnlos. Wenn nichts zählt, was ich sage, brauchen wir nicht zu reden.“","style":"frontal","reaction":"„Siehst du, am Ende geht es immer darum, dass man nicht diskutieren darf. Das spricht ja für sich.“","feedback":"Genervter Ausstieg im Streit: Du verlässt das Gespräch im Ton der Niederlage und bestätigst Kevins Erzählung vom „Nicht-Gehört-Werden“. Wegzugehen ist erlaubt, aber nicht so.","score":-2,"nextStepId":"step-fail"},{"text":"„Okay, ich merke, dass wir uns gerade im Kreis drehen. Lass uns das Thema für heute ruhen lassen. Erzähl mir lieber, wie es dir sonst so geht: Job, Wohnung, alles okay?“","style":"ausstieg","reaction":"„*zögert, dann ein halbes Lächeln* Na ja... ehrlich gesagt ist es gerade nicht so einfach. Danke, dass du fragst.“","feedback":"Ein sauberer, mitmenschlicher Ausstieg (Beziehung geht vor Sieg). Die Sachfrage bleibt offen, aber Kevin spürt Interesse an ihm als Mensch.","score":1,"nextStepId":"step-5"}]},"step-4":{"id":"step-4","speaker":"Kevin","speech":"„Weißt du, was komisch ist? Ich habe in den letzten Monaten kaum noch Leute, mit denen ich reden kann. Meine Eltern sagen, ich soll aufhören. Meine Freunde melden sich nicht mehr. Nur in der Gruppe fühle ich mich verstanden. Und trotzdem sagst du jetzt ... dass ich mir da vielleicht etwas einrede?“","options":[{"text":"„Ich sage nicht, dass du dir etwas einredest. Ich sage nur: Bei einer Idee, die sich durch nichts prüfen lässt, können wir beide nie herausfinden, ob sie stimmt. Und ich bin hier, weil du mir als Mensch wichtig bist, nicht weil ich gewinnen will.“","style":"deeskalierend","reaction":"„*schluckt* Das ... tut gut zu hören. Ehrlich.“","feedback":"Sehr gut: Du trennst Sachfrage und Beziehung klar. Kevin hört, dass seine Person nicht verhandelt wird, die Behauptung aber schon (prüfbar oder nicht).","score":3,"nextStepId":"step-5"},{"text":"„Ich bin froh, dass du das sagst. Genau das ist das Muster: Die Gruppe gibt dir Zugehörigkeit, und dafür musst du alles andere abbrechen. Das ist wie bei einer Sekte.“","style":"frontal","reaction":"„Sekte? Jetzt wirst du beleidigend. Ich dachte, du verstehst mich.“ *steht halb auf*","feedback":"Die Beobachtung mag stimmen, aber das Wort ‚Sekte‘ ist ein Etikett statt eine Frage. Kevin hört Verachtung, nicht Sorge.","score":-2,"nextStepId":"step-fail"},{"text":"„Ich schlage vor, wir machen es so: Du suchst dir eine Behauptung aus deinem Weltbild aus, die du am besten belegt findest. Wir überlegen zusammen, was sie widerlegen würde, und schauen beide nach. Ohne Zeitdruck.“","style":"sokratisch","reaction":"„Hm, ja, das könnte ich machen. Aber was, wenn ich dir was zeige und du es einfach abtust?“","feedback":"Konkretes, gemeinsames Experiment (Werkbank): Du bietest Kevin Mitarbeit statt Belehrung an. Dass er Sorge hat, abgetan zu werden, ist ehrlich und ein Anknüpfungspunkt.","score":2,"nextStepId":"step-5"}]},"step-4-struggle":{"id":"step-4-struggle","speaker":"Kevin","speech":"„Weißt du was? Ich habe einfach keine Lust, mich ständig rechtfertigen zu müssen. Von dir, von meinen Eltern, von allen. Immer soll ich beweisen, dass ich recht habe.“","options":[{"text":"„Das verstehe ich. Ich will dir nichts beweisen müssen, und du mir auch nicht. Parken wir das Thema und essen einfach etwas? Meine Tür bleibt offen, falls du später reden willst.“","style":"ausstieg","reaction":"„*atmet auf* Ja ... das klingt gut. Danke. Das ist mehr, als die meisten zu mir sagen.“","feedback":"Klug: Du ziehst Druck aus der Situation, hältst die Beziehung offen und sparst Energie für ein späteres, aussichtsreicheres Gespräch.","score":2,"nextStepId":"step-5"},{"text":"„Dann hör auf, mir Märchen zu erzählen, die man gar nicht prüfen kann. Wer recht hat, kann das belegen, alles andere ist nur Behauptung, und damit kann ich nichts anfangen.“","style":"frontal","reaction":"„Siehst du? Das ist genau das, was ich meine. Ich geh jetzt.“ *nimmt seine Jacke*","feedback":"Die Kernaussage ist richtig, aber der Ton ist Konfrontation. Kevin fühlt sich bestätigt, dass dich nur das Gewinnen interessiert.","score":-2,"nextStepId":"step-fail"},{"text":"„Du hast recht, Rechtfertigen nervt. Ich frage dich nur einmal ganz ehrlich: Wenn du dich irren würdest, würdest du es dann wissen wollen?“","style":"sokratisch","reaction":"„*lange Pause* Ich ... weiß es nicht. Es wäre schon hart. Ich hab so viel dafür aufgegeben.“","feedback":"Eine ehrliche, ruhige Frage trifft den Kern: Der Preis des Irrtums (verlorene Freunde, Energie) hält Kevin im Weltbild. Dieses Eingeständnis ist wertvoll.","score":1,"nextStepId":"step-5"}]},"step-5":{"id":"step-5","speaker":"Kevin","speech":"„Okay, ich sag dir was: Ich brauche Zeit. Aber du bist nicht wie die anderen, die mich abgeschrieben haben. Willst du mir das nächste Mal was zeigen, woran ich noch zweifle? Oder ist dir das alles zu viel?“","options":[{"text":"„Gern, aber nicht jedes Mal. Ich kann nicht jeden Streit austragen, und du musst auch nicht jeden gewinnen. Wie wär’s mit einmal im Monat Bier, ein Thema, ohne Druck?“","style":"deeskalierend","reaction":"„*lächelt zum ersten Mal richtig* Einmal im Monat ... ja, das kriege ich hin. Danke, dass du das so ehrlich sagst.“","feedback":"Das ist Energiemanagement in Reinform: Du bleibst verlässlicher Ansprechpartner, setzt eine klare Grenze und bewahrst die Verbindung, statt dich zu verausgaben.","score":3},{"text":"„Klar, jederzeit! Schick mir einfach alles, was du findest, ich schau mir das jeden Abend an und diskutiere mit dir, so lange du willst.“","style":"affektiv","reaction":"„Wirklich? Das ist großartig! Ich schicke dir gleich die erste Ladung!“","feedback":"Großzügig gemeint, aber das ist der Weg ins Ausbrennen: Ohne Grenze wird die Freundschaft zum Dauerstreit und du verlierst die Kraft für wichtigere Schlachten.","score":-1},{"text":"„Ehrlich gesagt: Das ist mir zu viel. Wenn du dabei bleibst, sehen wir uns besser nicht mehr, denn ich will mir das nicht länger anhören.“","style":"frontal","reaction":"„*kalt* Dann weiß ich ja, woran ich bin. Danke für nichts.“","feedback":"Ein Ultimatum beendet die Beziehung, statt eine tragfähige Grenze zu setzen. Du hattest eine Alternative: Kontakt halten und das Thema dosieren.","score":-2}]},"step-fail":{"id":"step-fail","speaker":"Kevin","speech":"„Ich dachte, du verstehst mich. Aber du gehörst offenbar auch zu denen, die schlafen.“ *zahlt sein Bier, steht auf und geht*","options":[{"text":"Ende: Kevin fühlt sich nicht gehört und bleibt in seiner Gruppe. Du hast ein Gespräch verloren, aber noch keine Tür für immer geschlossen.","style":"ausstieg","reaction":"Beim nächsten Mal: erst zuhören, dann die Frage stellen, was seine Überzeugung widerlegen würde.","feedback":"Frage dich: Wollte ich Kevin überzeugen oder ihm helfen, selbst zu prüfen? Und wie viel Energie war dieses Gespräch mir wert?","score":0}]}},"status":"entwurf","familie":"widerlegung-benennen","fertigkeit":"F1","stufe":4,"kurz":"Eine Überzeugung, in der jeder Widerspruch als weiterer Beweis gilt, lässt sich durch nichts mehr prüfen. Die Frage, was sie widerlegen würde, macht das sichtbar; und weil nicht jedes Gespräch gewonnen werden muss, gehört dazu, die eigene Kraft klug einzuteilen.","prueffrage":"Was geschieht in Kevins Erzählung mit dem Widerspruch der Skeptiker und mit der Vorhersage, die nicht eintraf: Zählt irgendetwas davon gegen seine Sicht?","quellen":[{"typ":"url","kurz":"Thornton, S.: Karl Popper. Stanford Encyclopedia of Philosophy (überarbeitet 31.07.2026), Abschn. 2 und 12","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Sagan, C. (1995): The Demon-Haunted World. New York: Random House, Kap. 10 „The Dragon in My Garage“","oeffentlich":false,"seite":"S. 160–161 (brit. Ausg. London: Headline 1997, laut Landkarte und Register)"}],"thema":"Zusammenleben"},{"id":"scen-abnehm-detox-saft-freundin","title":"Carlas Entschlackungs-Wochenende","subtitle":"„Giftstoffe“ ausleiten, geübt mit aktivem Zuhören","character":"Carla, Freundin","avatar":"🥤","context":"Deine Freundin Carla kommt strahlend vom Wochenende zurück: Drei Tage lang hat sie eine teure „Detox“-Saftkur gemacht und nachts Fußpflaster getragen, die sich dunkel verfärbt haben. Sie fühlt sich „leichter und reiner“ und ist sicher, dass endlich all die Giftstoffe ihren Körper verlassen haben.","goal":"Höre Carla zuerst wirklich zu, damit sie selbst merkt, dass sie kein einziges „Toxin“ benennen kann, und lass dabei ihre Freude und eure Freundschaft heil.","bereich":"Gesundheit","laenge":"mittel","ton":"heiter","bestehenAb":6,"lektion":"Wer erst zuhört, bekommt den Bauplan der Überzeugung geliefert: Carla wollte sich vor allem wieder fit fühlen. Eine offene Frage nach dem konkreten „Toxin“ deckt die Leerstelle auf, ohne dass jemand das Gesicht verliert. Leber und Nieren entgiften ohnehin ständig. Aktives Zuhören: paraphrasieren, Gefühle benennen, klärend fragen – nicht belehren.","toolRef":"H.2.3","faktenRef":"G.3.1","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Carla","speech":"„Du, ich muss dir was erzählen! Ich habe drei Tage Saftkur gemacht und nachts diese Fußpflaster getragen, schau mal, die sind total schwarz geworden! Das waren alles Giftstoffe, die aus mir rausgekommen sind. Ich fühle mich so leicht und rein wie noch nie!“","options":[{"text":"„Carla, das ist Quatsch. Diese Pflaster färben sich durch Schweiß und Feuchtigkeit dunkel, und Saftkuren entgiften gar nichts. Da hast du Geld für nichts ausgegeben, und das tut mir ehrlich leid für dich.“","style":"frontal","reaction":"„Wow. Danke fürs Freuen. Ich erzähle dir was Schönes und du machst es mir madig. *verschränkt die Arme* Ich weiß, wie ich mich fühle!“","feedback":"Frontalangriff, bevor du verstanden hast, was Carla eigentlich meint. Sie hört „Du bist naiv“ und verteidigt jetzt ihr Gefühl statt ihre These. Zuhören kommt zuerst.","score":-2,"nextStepId":"step-fail"},{"text":"„Das klingt, als hättest du richtig was für dich getan. Wenn ich dich richtig verstehe, fühlst du dich nach den drei Tagen leichter und gereinigt. Stimmt das? Erzähl mal, wie kamst du auf die Kur?“","style":"deeskalierend","reaction":"„Ja, genau! *strahlt* Ich war vorher so schlapp und müde, den ganzen Winter schon. Und da habe ich bei Instagram diese Kur gesehen, da hieß es, mein Körper sei voller Schlacken und Umweltgifte.“","feedback":"Paraphrasieren plus offene Frage: Carla fühlt sich verstanden, und du erfährst ihre eigentliche Motivation – Müdigkeit, nicht Chemie. Ihre Aussage bestätigst du dabei nicht.","score":3,"nextStepId":"step-2"},{"text":"„Ach, ist ja schön für dich! Ich nehme heute lieber einen Kaffee und ein Stück Kuchen. Was gibt es sonst Neues bei dir? Wie läuft die Arbeit?“","style":"ausstieg","reaction":"„Äh, ja, okay... *etwas enttäuscht* Ich dachte, es interessiert dich. Aber gut, dann eben Kuchen.“","feedback":"Freundlich, aber du gehst dem Thema aus dem Weg. Carla fühlt sich nicht gehört, und ihre Überzeugung bleibt unberührt. Aktives Zuhören hätte dir gezeigt, was hinter ihrer Begeisterung steckt.","score":0,"nextStepId":"step-fail"}]},"step-2":{"id":"step-2","speaker":"Carla","speech":"„Jedenfalls hieß es, dass sich über die Jahre ganz viele Toxine in mir angesammelt haben, durch Stress, Abgase, Fastfood. Die Kur leitet die Schlacken aus, und die Pflaster ziehen sie über die Füße raus. Ich hab’s ja gesehen, die Pflaster sind schwarz!“","options":[{"text":"„Du hast also das Gefühl, dass sich über Monate etwas angestaut hat. Welches Gift genau steckte denn in deinem Körper, und wie hat man gemessen, dass es nach der Kur weg ist?“","style":"sokratisch","reaction":"„Welches Gift genau? *überlegt* Also... Toxine halt. Schwermetalle vielleicht? Das stand nicht dabei. Gemessen... eigentlich hat das niemand gemessen. Ich habe mich einfach besser gefühlt.“","feedback":"Treffer! Du paraphrasierst ihr Gefühl und stellst dann die klärende Frage, die Street Epistemology ausmacht. Carla stößt selbst auf die Leerstelle: Kein Stoff wurde je benannt oder gemessen.","score":3,"nextStepId":"step-3-success"},{"text":"„Dein Körper hat Leber und Nieren, die entgiften schon längst von allein. Die Kur bringt da null, und die Pflaster sind Betrug. Das weiß man.“","style":"frontal","reaction":"„Ach komm, das ist doch die Standardantwort von Leuten, die keine Ahnung von ganzheitlicher Gesundheit haben. Die Schulmedizin kennt vieles nicht!“","feedback":"Der Fakt stimmt, aber als Vortrag kommt er an wie ein Urteil. Carla geht in Verteidigung, und du hast ihr Argument nicht mal erfragt. Erst verstehen, dann prüfen.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Das klingt echt anstrengend, der ganze Winter so müde. Das tut mir leid. Hast du dich in dieser Zeit eigentlich mal durchchecken lassen oder genug geschlafen?“","style":"affektiv","reaction":"„Naja, ein bisschen Schlaf fehlt immer. Aber beim Arzt war ich nicht. Ich wollte erst mal was Natürliches probieren, bevor ich Pillen nehme.“","feedback":"Mitfühlend und nützlich: Du öffnest den Blick auf die wahrscheinlichere Ursache. Die „Toxin“-Behauptung selbst hast du aber noch nicht erfragt, das Gespräch bleibt ein Stück an der Oberfläche.","score":1,"nextStepId":"step-3-struggle"}]},"step-3-success":{"id":"step-3-success","speaker":"Carla","speech":"„Hm. Komisch, ich merke gerade, dass ich gar nicht sagen kann, was da eigentlich rausgegangen sein soll. Aber ich habe mich ja wirklich besser gefühlt. Heißt das, ich habe mir alles nur eingebildet?“","options":[{"text":"„Nein, das Gefühl war echt. Gut möglich, dass du mehr getrunken, weniger Fastfood gegessen und dir Zeit für dich genommen hast. Was davon könntest du ohne teure Pakete behalten?“","style":"humorvoll","reaction":"„*lacht* Okay, das klingt nach einem Plan! Zeit für mich war vermutlich wirklich das Beste daran. Und Gemüse esse ich ja auch gern, wenn es nicht nach Gras schmeckt.“","feedback":"Stark: Du würdigst ihr Wohlgefühl (Erwartung und Placebo reichen als Erklärung), lässt sie das Gesicht wahren und bietest eine gesunde Alternative an. Das ist aktives Zuhören im Abschluss.","score":3},{"text":"„Ja, im Grunde schon. Reines Placebo, mehr war das nicht. Du hast dir das alles nur eingebildet, und ich wollte es dir nur nicht so deutlich sagen.“","style":"sarkastisch","reaction":"„Ah. Also war ich einfach dumm und habe mich reinlegen lassen. Super, danke.“","feedback":"Inhaltlich nicht falsch, aber kalt formuliert. Carla hat den Aha-Moment gerade selbst gehabt, und du nimmst ihr die Würde dafür. Die Behauptung wird seziert, nicht der Mensch.","score":-1},{"text":"„Dann lass uns doch am Montag bei meiner Hausärztin nachfragen, was wirklich hinter deiner Müdigkeit steckt. Ich komme mit, wenn du magst.“","style":"deeskalierend","reaction":"„Du würdest mitkommen? *gerührt* Ja, das mache ich. Eigentlich hätte ich das schon im Winter abklären lassen sollen.“","feedback":"Fürsorglich und konkret: Du führst von der Scheinlösung zur echten Abklärung. Die Antwort ist gut, nutzt die Gelegenheit zur Reflexion über Placebo aber weniger als die erste Option.","score":2}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Carla","speech":"„Ich weiß nicht... Irgendwas muss doch dran sein, sonst würden das nicht so viele machen. Aber du klingst gerade so, als wäre ich blöd gewesen.“","options":[{"text":"„Das wollte ich nicht. Du hast dich müde gefühlt, etwas ausprobiert und dich danach besser gefühlt, und bei mir klang das wie ein Vorwurf. Das tut mir leid. Was war das Beste daran?“","style":"deeskalierend","reaction":"„*entspannt sich* Danke. Das Beste? Endlich Zeit für mich und keine Chips. Aber sag mal, welche Giftstoffe sollen das eigentlich gewesen sein? Das stand nirgends.“","feedback":"Reparatur geglückt: Du paraphrasierst, benennst die Verletzung und fragst offen nach (Deeskalation). Carla öffnet sich wieder und stellt die Toxin-Frage nun selbst.","score":2,"nextStepId":"step-3-success"},{"text":"„Ja, viele machen das, und viele fallen auch auf Marketing rein. Das ändert nichts daran, dass es Unsinn ist, und dabei bleibe ich auch, egal wie viele es machen.“","style":"frontal","reaction":"„Weißt du was, lassen wir das. Ich bin gerade viel zu glücklich, um mich mit dir zu streiten.“","feedback":"Die Wahrheit als Schlusswort, die Tür geht zu. Wer sich angegriffen fühlt, sucht keine Gründe zum Umdenken.","score":-2,"nextStepId":"step-fail"},{"text":"„Du hast recht, das Thema kann man auch einfach lassen. Wichtig ist, dass es dir gut geht. Gehen wir morgen zusammen eine Runde laufen, ganz ohne Detox?“","style":"ausstieg","reaction":"„Ja, gern! Laufen mit dir ist immer lustig. Danke, dass du mich nicht fertigmachst.“","feedback":"Ein freundlicher Rückzug: Die Freundschaft bleibt heil, und die Bewegung ist ein guter Anknüpfungspunkt. Die Sachfrage bleibt aber offen.","score":1,"nextStepId":"step-3-ausklang"}]},"step-3-ausklang":{"id":"step-3-ausklang","speaker":"Carla","speech":"„Weißt du, vielleicht probiere ich beim nächsten Mal einfach eine Woche lang früher ins Bett zu gehen. Das wäre billiger als die Saftkur, oder?“","options":[{"text":"„Das wäre mit Sicherheit billiger. Und ich glaube, das hilft deinem Körper wirklich. Erzähl mir nach der Woche, wie du dich fühlst!“","style":"humorvoll","reaction":"„Mach ich! Und du bringst mir einen Kaffee mit, damit ich die erste Woche überlebe.“","feedback":"Die gute Idee kam von Carla selbst, du hast sie nur freundlich bestätigt. So bleibt ihre Selbstwirksamkeit unangetastet.","score":2}]},"step-fail":{"id":"step-fail","speaker":"Carla","speech":"„Okay, ich merke schon, mit dir kann man über so etwas nicht reden. Ich frage lieber meine Instagram-Community, die verstehen mich wenigstens.“ *kramt ihr Handy hervor*","options":[{"text":"Ende: Carla fühlte sich nicht gehört und sucht jetzt Bestätigung dort, wo sie sie sicher bekommt. Wer zuerst zuhört, erfährt, was hinter der Behauptung steckt, und kann dann gezielt nachfragen.","style":"ausstieg","reaction":"Beim nächsten Mal: Erst paraphrasieren, dann offen fragen – nicht widerlegen.","feedback":"Frage dich: Wollte ich Carla überführen oder verstehen? Das Zuhören kommt vor jedem Gegenargument.","score":0}]}},"status":"entwurf","familie":"begriff-messbar-machen","fertigkeit":"F1","stufe":2,"kurz":"Wer erst zuhört und nachfragt, erfährt, was hinter einer Überzeugung steckt. Die offene Frage, welches Gift genau ausgeleitet wurde und wie man das gemessen hat, deckt die Leerstelle auf, ohne dass jemand das Gesicht verliert. Leber und Nieren entgiften ohnehin ständig.","prueffrage":"Welcher Stoff genau soll den Körper verlassen haben, und wer hat vorher und nachher gemessen, dass er weg ist?","quellen":[{"typ":"url","kurz":"British Dietetic Association (2025): Detox Diets (Food Fact Sheet)","oeffentlich":true,"url":"https://bda.uk.com/foodfacts/detoxdiets","abruf":"2026-10-12"},{"typ":"url","kurz":"NCCIH (2025): „Detoxes“ and „Cleanses“: What You Need To Know","oeffentlich":true,"url":"https://www.nccih.nih.gov/health/detoxes-and-cleanses-what-you-need-to-know","abruf":"2026-10-12"},{"typ":"url","kurz":"Kluger, A. N.; Itzchakov, G. (2022): The Power of Listening at Work. Annual Review of Organizational Psychology and Organizational Behavior 9 (Vorabfassung)","oeffentlich":true,"url":"https://leibniz-psychology.org/fileadmin/user_upload/pdf/il_Kluger-and-Itzchakov-OPOB-RR.pdf","seite":"PDF-S. 18 und 28 (Vorabfassung)","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"scen-oma-antibiotika","title":"Omas Antibiotika gegen Schnupfen","subtitle":"Viren vs. Bakterien, geübt mit der Deeskalations-Matrix","character":"Lotte, Oma","avatar":"👵","context":"Deine Oma Lotte liegt mit einer fetten Erkältung auf dem Sofa: Nase zu, Hals kratzt, Kopf schwer. Sie hat gerade bei ihrer Hausärztin angerufen und ist verärgert, weil sie dort kein Antibiotikum bekommen soll. Jetzt ruft sie dich an und will, dass du ihr dabei hilfst.","goal":"Nimm Omas Frust und Sorge ernst, ohne ihr zuzustimmen, und führe das Gespräch dahin, dass sie den Unterschied zwischen Viren und Bakterien nachvollziehen kann.","bereich":"Familie","laenge":"kurz","ton":"ernst","bestehenAb":7,"lektion":"Wer sich krank und nicht ernst genommen fühlt, hört keine Fakten, sondern nur den Tonfall. Erst wenn du das Gefühl validierst, kann die Unterscheidung ankommen: Bakterien sind eigenständige Lebewesen, und Antibiotika greifen an ihrem Aufbau und Stoffwechsel an. Viren haben keinen eigenen Stoffwechsel und vermehren sich nur in fremden Zellen, deshalb finden Antibiotika bei ihnen keinen Angriffspunkt. Eine Ich-Botschaft und eine gemeinsame Rückfrage öffnen dabei mehr Türen als jeder Vortrag.","toolRef":"H.2.1","faktenRef":"C.4.2","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Lotte","speech":"„Stell dir vor, die Ärztin will mir nichts aufschreiben! Ich bin richtig krank, mir läuft die Nase, der Hals tut weh, und ich fühle mich hundeelend. Bei einer richtigen Erkältung hilft nur ein Antibiotikum, das weiß doch jeder! Ruf du da mal an, auf dich hört sie.“","options":[{"text":"„Oma, das ist Quatsch. Antibiotika wirken gar nicht gegen Erkältungen, das weiß doch jeder, der mal was gelesen hat. Die Ärztin hat völlig recht.“","style":"frontal","reaction":"„Ach, jetzt stellst du dich auch noch gegen mich! Ich habe fünf Kinder großgezogen, ich weiß wohl, wann ich krank bin! Ihr jungen Leute wisst immer alles besser.“","feedback":"Der Inhalt stimmt, aber du reagierst nur auf die Behauptung und nicht auf Omas Gefühl. Sie fühlt sich abgekanzelt, und das Gespräch kippt in Verteidigung.","score":-2,"nextStepId":"step-fail"},{"text":"„Ich höre, wie elend du dich fühlst, und dass du dich von der Ärztin nicht ernst genommen fühlst. Das ärgert dich bestimmt. Erzähl mal, was genau hat sie dir gesagt?“","style":"deeskalierend","reaction":"„*seufzt* Ach, Kind... Sie hat nur gesagt, das sei ein Virus und ich solle viel trinken und mich schonen. Als ob mir das nicht wehtäte! Ich will doch einfach, dass es wieder weggeht.“","feedback":"Treffer! Du validierst das Gefühl, nicht den Inhalt (Technik 1). Omas Bedürfnis, gehört zu werden, ist erfüllt, und sie nennt von selbst das Stichwort „Virus“.","score":3,"nextStepId":"step-2"},{"text":"„Dann frag doch einfach einen anderen Arzt. Irgendeiner schreibt dir schon was auf, wenn du lange genug sagst, wie schlecht es dir geht.“","style":"ausstieg","reaction":"„Ja, das mache ich! Der Doktor Brandt gegenüber ist da nicht so zimperlich. Danke, Kind, du verstehst mich wenigstens.“","feedback":"Du weichst dem Konflikt aus und stützt dabei die falsche Annahme. Unnötige Antibiotika wirken nicht gegen Viren und können sogar schaden.","score":-2,"nextStepId":"step-fail-avoid"}]},"step-2":{"id":"step-2","speaker":"Lotte","speech":"„Virus, Bakterium, ist das nicht alles dasselbe? Irgendein Keim halt. Und wenn ich mich so schlecht fühle, muss man doch was dagegen tun! Ich verstehe nicht, warum das Antibiotikum nicht helfen soll.“","options":[{"text":"„Gute Frage, ich fand das früher auch verwirrend. Bakterien sind eigenständige Lebewesen, gegen die wirken Antibiotika. Ein Virus ist eher eine Bauanleitung, die Zellen kapert. Da greift ein Antibiotikum ins Leere. Soll ich mehr erzählen?“","style":"sokratisch","reaction":"„Ein Stück Bauanleitung, das Zellen kapert? Das klingt ja wie ein Dieb... Also ist ein Virus gar kein richtiges Lebewesen? Dann hat das Antibiotikum ja gar nichts, was es angreifen könnte.“","feedback":"Stark: Du beginnst mit einer Ich-Botschaft statt einer Belehrung (Technik 2), erklärst den Unterschied anschaulich nach „Viren & Bakterien“ und fragst nach, ob sie mehr hören will. Oma zieht den Schluss selbst.","score":3,"nextStepId":"step-3-success"},{"text":"„Genau darum geht es ja. Viren und Bakterien sind grundverschieden, das steht in jedem Lehrbuch. Wenn du das nicht kapierst, kann ich dir auch nicht helfen.“","style":"frontal","reaction":"„Na, dann kapier ich es eben nicht! Dann geh ich eben allein zum nächsten Arzt. Von dir lasse ich mir nicht den Mund verbieten!“","feedback":"Der Satz „wenn du das nicht kapierst“ ist eine Du-Botschaft und beschämt. Selbst richtige Fakten kommen so nicht an.","score":-2,"nextStepId":"step-fail"},{"text":"„Weißt du was, Oma, das ist eine ziemlich komplizierte Sache. Lass uns das ein andermal besprechen. Ruh dich jetzt aus, trink was Warmes, und ich schau am Wochenende bei dir vorbei, ja?“","style":"deeskalierend","reaction":"„Na gut... Aber ich verstehe es eigentlich immer noch nicht so richtig. Komm aber wirklich vorbei, ja?“","feedback":"Eine freundliche Auszeit hält die Beziehung heil (Technik 4), lässt aber die Sachfrage offen. Brauchbar, aber ohne Erklärung bleibt der Wunsch nach dem Antibiotikum bestehen.","score":1,"nextStepId":"step-3-struggle"}]},"step-3-success":{"id":"step-3-success","speaker":"Lotte","speech":"„Na, wenn das Ding gar nicht lebt, dann kann so ein Antibiotikum ihm ja auch nichts anhaben. Schon komisch. Und ich dachte, ich müsste unbedingt was haben... Dann hat die Ärztin wohl doch recht gehabt.“","options":[{"text":"„Genau, und sie hat sich bestimmt um dich gesorgt. Ich koche dir morgen eine Hühnersuppe, und wenn es in ein paar Tagen nicht besser wird, rufst du die Ärztin einfach noch mal an. Einverstanden?“","style":"deeskalierend","reaction":"„Hühnersuppe, das ist lieb von dir, Kind. Ich rufe sie noch mal an, wenn es nicht besser wird. Danke, dass du mir das erklärt hast, ohne dass ich mir dumm vorkomme.“","feedback":"Gelungener Abschluss: Du sicherst die Beziehung und eröffnest einen sinnvollen Plan, der die ärztliche Abklärung ausdrücklich offenhält. Omas Gesicht ist gewahrt, und die Einsicht stammt von ihr selbst.","score":3}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Lotte","speech":"„Du, ich liege hier und fühle mich einfach nur schlecht. Ich weiß nicht, was ich noch denken soll. Mir schwirrt der Kopf von all dem Gerede.“","options":[{"text":"„Das glaube ich dir, Oma. Du bist krank und musst dich ausruhen. Ich komme am Wochenende mit Suppe vorbei, und dann erkläre ich dir bei einer Tasse Tee in Ruhe den Unterschied zwischen Viren und Bakterien. Abgemacht?“","style":"deeskalierend","reaction":"„Ja, abgemacht. Das ist lieb von dir, Kind. Und die Suppe nehme ich gern.“","feedback":"Gute Auszeit: Du schützt die Beziehung und stellst die Sachklärung für einen ruhigeren Moment in Aussicht (Technik 4). Die Tür bleibt offen.","score":2}]},"step-fail":{"id":"step-fail","speaker":"Lotte","speech":"„Ich merke schon, du hörst mir gar nicht richtig zu. Dann gehe ich eben morgen zu einem anderen Arzt und lasse mir das Medikament dort verschreiben.“ *legt auf*","options":[{"text":"Ende: Oma Lotte fühlt sich nicht gehört und sucht sich jetzt einen Arzt, der ihr das Antibiotikum gibt. Fakten ohne Gehör kommen nicht an.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst das Gefühl validieren, dann den Inhalt klären.","feedback":"Frage dich: Wollte ich Recht haben oder das Gespräch retten? Die Deeskalations-Matrix ordnet die Reihenfolge: erst Gefühl, dann Sache. Und Antibiotika wirken nur gegen Bakterien, nicht gegen Viren.","score":0}]},"step-fail-avoid":{"id":"step-fail-avoid","speaker":"Lotte","speech":"„Dann gehe ich morgen gleich zu Doktor Brandt. Schön, dass wenigstens du auf meiner Seite bist.“ *legt zufrieden auf*","options":[{"text":"Ende: Oma bedankt sich und geht morgen zu Doktor Brandt. Du hast den Konflikt vermieden, aber die falsche Annahme gestützt.","style":"ausstieg","reaction":"Deeskalation ist keine Unterwerfung: Gefühle zu validieren heißt nicht, dem Inhalt zuzustimmen.","feedback":"Das ist der Kipppunkt der Deeskalation: Aus Friedenswunsch stimmst du einer falschen Annahme zu. Antibiotika wirken nur gegen Bakterien, nicht gegen Viren. Besser: Gefühl validieren und den Inhalt behutsam klären.","score":0}]}},"status":"entwurf","familie":"genau-unterscheiden","fertigkeit":"F1","stufe":1,"kurz":"Wer sich krank und übergangen fühlt, hört zuerst den Ton, nicht die Fakten. Erst wenn das Gefühl ernst genommen ist, kann ankommen, dass Antibiotika gegen Bakterien wirken, gegen Viren wie bei einer Erkältung aber nicht.","prueffrage":"Was hat die Ärztin als Ursache der Beschwerden genannt, und wogegen genau wirkt das Mittel, das Oma Lotte haben möchte?","quellen":[{"typ":"url","kurz":"CDC (2025): Healthy Habits: Antibiotic Do's and Don'ts","oeffentlich":true,"url":"https://www.cdc.gov/antibiotic-use/about/index.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kuhrt, N.; Oude-Aost, J.; Betsch, C. (2021): Fakten-Check Impfen. München: Gräfe und Unzer","oeffentlich":false}],"thema":"Gesundheit"},{"id":"scen-lernplatz-mozart","title":"Lukas und die Mozart-Wunderkur","subtitle":"Klassik macht angeblich schlau, geübt mit Street Epistemology","character":"Lukas, Mitschüler","avatar":"🎻","context":"In der Pause vor der Mathe-Klausur steckt dir Lukas einen Kopfhörer ins Ohr: Mozart! Er ist felsenfest überzeugt, dass man von klassischer Musik dauerhaft klüger wird und bessere Noten schreibt. Heute Morgen hat er sich extra eine Stunde Mozart gegönnt.","goal":"Bring Lukas mit freundlicher Neugier dazu, selbst zu prüfen, woher er das weiß, statt ihm seine Überzeugung auszureden.","bereich":"Schule","laenge":"kurz","ton":"heiter","bestehenAb":4,"lektion":"Wer sagt „Das ist Quatsch“, bekommt Verteidigung statt Nachdenken. Wer fragt „Woher weißt du das, und wie könnten wir es testen?“, lädt zum Prüfen ein. Ein Einzelbefund ist noch kein Beleg: Zu fragen ist, wie groß der Effekt ist und was in den Schubladen liegt.","toolRef":"H.2.2","faktenRef":"A.24","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Lukas","speech":"„Hör mal, Mozart vor der Klausur, das ist der absolute Gamechanger! Wer Klassik hört, wird dauerhaft klüger, das ist Fakt. Ich mach das jetzt jeden Morgen, und meine Noten gehen bestimmt durch die Decke!“","options":[{"text":"„Das ist doch ein längst widerlegter Mythos, Lukas. Von Musik wird niemand klüger. Du fällst da auf eine Internet-Legende rein, die jeder kennt.“","style":"frontal","reaction":"„Ach komm, du willst nur nicht, dass ich besser bin als du! Das steht überall, das weiß jeder!“","feedback":"Frontalangriff: Lukas fühlt sich belehrt und verteidigt jetzt seine Ehre statt seiner Methode. Street Epistemology untersucht das Wie des Wissens, nicht das Ergebnis.","score":-2,"nextStepId":"step-fail"},{"text":"„Cool, dass du so überzeugt bist! Darf ich dich was fragen? Auf einer Skala von 0 bis 100: Wie sicher bist du, dass Mozart dauerhaft klüger macht, und was ist dein Hauptgrund?“","style":"sokratisch","reaction":"„Hm, Skala? Ich sag mal 90! Mein Cousin hat das gesagt, und ich hab einen Artikel gelesen, da stand ‚Mozart macht schlau‘. Und neulich hatte ich nach Klassik eine Zwei in Bio!“","feedback":"Sehr gut: Sicherheitsgrad und Hauptgrund erfragt. Lukas legt offen, worauf seine 90 Prozent ruhen: Hörensagen, eine Überschrift und ein Einzelfall.","score":3,"nextStepId":"step-2"},{"text":"„Mozart, echt? Dann brauch ich ja gar nicht mehr zu lernen! Gib mir deine Playlist, ich hör sofort rein und bestehe dann alles von allein.“","style":"humorvoll","reaction":"„Siehst du, genau! Ich schick sie dir gleich. Wer braucht schon Matheaufgaben, wenn man Mozart hat!“","feedback":"Locker, aber du bestätigst den Mythos, statt ihn zu prüfen. Neugierige Fragen wären hier die bessere Brücke gewesen.","score":-1,"nextStepId":"step-fail"}]},"step-2":{"id":"step-2","speaker":"Lukas","speech":"„Na ja, im Artikel hieß es, da gab's mal eine Studie, und danach waren die Leute messbar schlauer! Und meine Zwei in Bio ist der Beweis. Was soll daran falsch sein?“","options":[{"text":"„Eine Zwei in Bio kann viele Gründe haben. Studien sind außerdem oft gekauft. Du solltest nicht alles glauben, was online steht.“","style":"frontal","reaction":"„Pff, alles bei dir ist immer gekauft oder Zufall. Dann glaub ich eben meinem Gefühl, das hat bisher gestimmt!“","feedback":"Pauschales Misstrauen („gekauft“) ersetzt keine Prüfung. Du belehrst, statt Lukas die Methode selbst bewerten zu lassen.","score":-1,"nextStepId":"step-fail"},{"text":"„Eine Studie, spannend! Wie groß war der Effekt eigentlich, und wie lange hielt er? Und wenn es noch andere Studien gab, die nichts fanden: Wüssten wir davon?“","style":"sokratisch","reaction":"„Hm... wie lange es hielt, stand nicht im Artikel. Und von anderen Studien stand da auch nichts. Wenn das nur kurz war, ist das ja nicht ‚dauerhaft‘.“","feedback":"Treffer: Du fragst nach der Größe und Dauer des Effekts (Effektstärke) und danach, was mit den übrigen Studien ist (Schublade). Lukas schlägt den Bogen zu „dauerhaft“ selbst.","score":3,"nextStepId":"step-3-success"},{"text":"„Kann sein, ich weiß es auch nicht genau. Hör einfach, was dir gefällt, ist ja kein Schaden. Wollen wir jetzt Matheaufgaben üben?“","style":"ausstieg","reaction":"„Ja klar, später! Aber ich bleib dabei: Mozart wirkt!“","feedback":"Freundlicher Ausstieg ohne Schaden, aber Lukas bleibt bei 90 Prozent. Ein sanfter Zweifel wäre noch drin gewesen.","score":1,"nextStepId":"step-3-struggle"}]},"step-3-success":{"id":"step-3-success","speaker":"Lukas","speech":"„Okay, vielleicht war da ein kleiner Effekt für kurze Zeit, aber ‚dauerhaft klüger‘ ist halt was anderes. Und meine Zwei in Bio ist vielleicht Zufall oder ich hab einfach gelernt! Wie sicher bin ich jetzt noch? Vielleicht 30 Prozent...“","options":[{"text":"„Das ist ehrlich gedacht. Und weißt du was? Lass uns heute Abend zusammen lernen. Mozart im Hintergrund darf trotzdem laufen, ist ja schön!“","style":"humorvoll","reaction":"„Haha, deal! Mozart bleibt im Hintergrund, die Formeln kommen in den Kopf. Danke fürs Zuhören!“","feedback":"Mission geglückt: Lukas hat seine Sicherheit selbst nach unten korrigiert, ohne Gesichtsverlust. Die Freundschaft ist heil, und der Spaß an der Musik bleibt.","score":3},{"text":"„Siehst du, ich hab's ja gleich gesagt: War alles Quatsch. Hab ich doch recht gehabt, und du wolltest mir ja nicht glauben.“","style":"sarkastisch","reaction":"„Ach, jetzt wirst du auch noch schlau, oder was? Dann glaub ich's eben wieder!“","feedback":"Triumph zerstört den Erfolg: Seziert wird die Behauptung, nicht der Mensch. Rechthaben-Wollen lässt Lukas zurückrudern.","score":-1}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Lukas","speech":"„Bis später dann! Aber ehrlich, du schaust so nachdenklich. Glaubst du etwa nicht, dass Mozart hilft?“","options":[{"text":"„Ich bin mir nicht sicher und würde das gern prüfen. Wie sollte man in einer Studie testen, dass es wirklich die Musik war und nicht Zufall?“","style":"sokratisch","reaction":"„Hm, gute Frage... Man müsste wohl viele Leute mit und ohne Mozart vergleichen? Und das mehrmals wiederholen. Ich schau mal, ob ich den Artikel finde, da stand bestimmt eine Quelle.“","feedback":"Gute zweite Chance: Mit einer offenen Frage kommt Lukas selbst auf Vergleichsgruppe und Wiederholung. Das sind die Grundlagen jeder Studie (Kapitel 1.3, vertieft in).","score":2},{"text":"„Nö, ich glaube nicht dran. Das ist alles Marketing von Klassik-Radios, die damit nur ihre Hörer halten wollen, und dafür bist du gerade der beste Beweis.“","style":"frontal","reaction":"„Marketing?! Jetzt sagst du, ich bin ein Opfer von Radiowerbung? Da lass ich mir von dir nichts erzählen!“","feedback":"Eine unbelegte Gegenbehauptung ersetzt keine Prüfung. Lukas verteidigt sich, die Methodenfrage bleibt unberührt.","score":-2}]},"step-fail":{"id":"step-fail","speaker":"Lukas","speech":"„Ich hab keine Lust mehr, darüber zu reden. Ich hör jetzt Mozart und schreib die Klausur, du wirst schon sehen!“ *setzt die Kopfhörer wieder auf*","options":[{"text":"Ende: Lukas ist nicht überzeugt, nur genervt. Frontale Belehrung oder Mitlachen klärt die Frage nicht.","style":"ausstieg","reaction":"Beim nächsten Mal: zuerst fragen, woher er das weiß, und wie sicher er sich ist.","feedback":"Street Epistemology prüft die Methode hinter der Überzeugung, nicht die Überzeugung selbst. Zwei Fragen genügen oft: „Wie sicher bist du?“ und „Woher weißt du das?“","score":0}]}},"status":"entwurf","familie":"befund-reichweite","fertigkeit":"F1","stufe":1,"kurz":"Ein Einzelbefund ist noch kein Beleg für eine dauerhafte Wirkung. Statt „Das ist Quatsch“ hilft die Frage, woher jemand etwas weiß, wie groß und wie dauerhaft der Effekt war und ob Studien, die nichts fanden, vielleicht unveröffentlicht blieben.","prueffrage":"Worauf stützt Lukas seine 90 Prozent Sicherheit, und welche dieser Quellen sagt etwas darüber, wie groß die Wirkung war und wie lange sie anhielt?","quellen":[{"typ":"url","kurz":"University of Vienna / ScienceDaily (2010): Mozart's music does not make you smarter, study finds","oeffentlich":true,"url":"https://www.sciencedaily.com/releases/2010/05/100510075415.htm","abruf":"2026-10-12"},{"typ":"doi","kurz":"Pietschnig, J.; Voracek, M.; Formann, A. K. (2010): Mozart effect–Shmozart effect: A meta-analysis. Intelligence 38(3), 314–323","oeffentlich":false,"doi":"10.1016/j.intell.2010.03.001"},{"typ":"url","kurz":"Street Epistemology International: Street Epistemology (Startseite)","oeffentlich":true,"url":"https://www.streetepistemology.com/","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"scen-influencer-detox","title":"Lisas Detox-Tee-Abo","subtitle":"Entgiften und Schlacken, geübt mit kognitiver Entkopplung","character":"Lisa, Freundin","avatar":"🍵","context":"Deine Freundin Lisa hat ein Abo für einen „Detox-Tee“ aus dem Shop einer Influencerin abgeschlossen und schwärmt dir beim Kaffee davon vor. Ihr Körper sei voller „Schlacken“, der Tee spüle sie aus. Als du nachfragst, merkst du: Das Thema ist für Lisa längst Teil ihres Selbstbilds geworden.","goal":"Bring Lisa mit freundlichen Rückfragen dazu, die Behauptung selbst zu prüfen, ohne dass sie sich angegriffen fühlt und ohne dass eure Freundschaft leidet.","bereich":"Freunde","laenge":"mittel","ton":"sarkastisch","bestehenAb":6,"lektion":"Der Begriff „Schlacken“ kommt aus der Metallurgie, nicht aus der Biologie, und ein Toxin, das nie beim Namen genannt wird, lässt sich weder messen noch ausleiten. Leber und Nieren entgiften den Körper ständig selbst, und eine Übersichtsarbeit fand keine überzeugende Evidenz, dass Detox-Diäten Toxine ausleiten. Wer die Behauptung seziert und nicht die Person, hilft dem anderen bei der kognitiven Entkopplung: Lisa darf eine Idee prüfen, ohne dass es ihr Selbstwert ist, der auf dem Prüfstand steht.","toolRef":"H.1.1","faktenRef":"G.3.1","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Lisa","speech":"„Du, ich muss dir was erzählen! Seit zwei Wochen trinke ich jeden Morgen diesen Detox-Tee, und ich fühle mich wie ein neuer Mensch! Mein Körper war ja komplett voller Schlacken. Wahnsinn, was sich da alles angesammelt hat, ohne dass man es merkt!“","options":[{"text":"„Lisa, ‚Schlacken‘ im Körper gibt es nicht. Das ist reiner Marketing-Quatsch. Wie kann man nur Geld für so einen Humbug ausgeben?“","style":"frontal","reaction":"„Wow. Danke fürs Gespräch. Ich fühle mich eben gut damit, und du erklärst mich gleich für dumm. *verschränkt die Arme* Dann sag ich dir halt gar nichts mehr.“","feedback":"Die Sachaussage stimmt zwar, aber Lisa hört: „Du bist dumm.“ Wer die Person statt die Behauptung angreift, verstärkt die Kopplung von Idee und Identität.","score":-2,"nextStepId":"step-fail"},{"text":"„Schön, dass es dir gut geht! Magst du mir erklären, woran du merkst, dass sich da Schlacken angesammelt hatten?“","style":"sokratisch","reaction":"„Naja... ich war ständig müde und aufgebläht, das ist doch ein klares Zeichen! Und jetzt bin ich viel leichter. Das sagt die Expertin im Video auch.“","feedback":"Gute Eröffnung! Die offene Frage nach dem Grund ihrer Überzeugung hält das Gespräch freundlich. Lisa breitet ihre Begründung selbst aus, und die Idee wird zu etwas, das man gemeinsam betrachten kann.","score":3,"nextStepId":"step-2"},{"text":"„Haha, klar, und morgen kaufst du dir wohl das magische Wasser dazu? Der Tee entschlackt dich, bis nur noch Seele übrig ist.“","style":"sarkastisch","reaction":"„Ha. Ha. Sehr lustig. Immer musst du dich über meine Sachen lustig machen. Ich wollte dir eigentlich was Gutes erzählen.“","feedback":"Sarkasmus gegen die Person gerichtet kippt schnell in Abwertung. Die Figur hört Spott über sich, nicht Zweifel an der Behauptung, und macht dicht.","score":-1,"nextStepId":"step-fail"}]},"step-2":{"id":"step-2","speaker":"Lisa","speech":"„Die Expertin sagt, unsere Leber und Nieren sind total überlastet von Umweltgiften und schlechtem Essen. Und der Tee unterstützt sie, die Schlacken endlich auszuleiten. Das leuchtet doch ein, oder?“","options":[{"text":"„Dass Leber und Nieren überlastet sind, ist eine Behauptung, die ich überprüfen würde. Lass uns zusammen schauen, ob es dafür überhaupt Belege gibt.“","style":"sokratisch","reaction":"„Hm, Belege... Sie hat halt gesagt, dass das jeder spürt. Aber ich weiß gar nicht, ob sie Studien genannt hat. Wollen wir mal ihre Seite durchgehen?“","feedback":"Stark! Du lädst Lisa zum gemeinsamen Prüfen ein, statt zu widerlegen. So wird die Idee zu einem Objekt, das man ansehen kann, ohne dass es um Lisas Selbstwert geht.","score":2,"nextStepId":"step-3"},{"text":"„Das stimmt einfach nicht. Leber und Nieren entgiften ständig von selbst, dafür brauchst du keinen Tee. Punkt.“","style":"frontal","reaction":"„Ach, du weißt es also besser als Leute, die sich damit beschäftigen? Du bist doch auch kein Arzt!“","feedback":"Die Information ist korrekt, kommt aber als Belehrung. Ohne eigene Entdeckung erlebt Lisa das als Angriff und verteidigt den Tee.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Welches Toxin genau soll der Tee denn rausholen? Wie heißt es chemisch, und wie hat man gemessen, dass es nach der Kur weg ist?“","style":"sokratisch","reaction":"„Äh... *stutzt* Das hat sie, glaube ich, nie genau gesagt. Es waren halt ‚Toxine‘. Wie ... heißt eins davon eigentlich? Hmm.“","feedback":"Treffer! Die Aktivierungsfrage aus „Toxine“ / „Schlacken“ / „Entgiften“ deckt auf, dass nie ein spezifisches Gift genannt wurde. Als echte Frage gestellt, statt als Anklage, ermöglicht sie Lisa einen eigenen Aha-Moment.","score":3,"nextStepId":"step-3-success"}]},"step-3":{"id":"step-3","speaker":"Lisa","speech":"„Okay, auf der Seite steht tatsächlich nichts Konkretes. Nur ‚Toxine‘ und ‚Schlacken‘. Aber ich fühle mich nun mal besser, und das kann ich mir ja nicht einbilden, oder?“","options":[{"text":"„Dein Gefühl nehme ich ernst, Lisa. Vielleicht fühlst du dich besser, weil du bewusster trinkst und isst. Ob der Tee selbst entscheidend ist, ist eine andere Frage.“","style":"deeskalierend","reaction":"„Stimmt, ich trinke jetzt auch viel mehr Wasser und esse weniger Junk. Vielleicht liegt es daran und nicht an den Schlacken... Hmm.“","feedback":"Stark: Das Gefühl bleibt gültig, die Erklärung wird sachlich offengehalten. Ein rein subjektiver Eindruck ist kein Beweis für eine „Entschlackung“; er kann etwa auf den Placebo-Effekt oder auf andere Veränderungen im Alltag zurückgehen.","score":2,"nextStepId":"step-4-success"},{"text":"„Dann hat sich das Placebo halt gelohnt, Lisa. Dein Gehirn macht aus Tee und Wunschdenken ein tolles Gefühl, mehr ist da nicht dahinter, das ist reine Einbildung.“","style":"frontal","reaction":"„Also bilde ich mir alles nur ein?! Das ist ziemlich gemein, finde ich.“","feedback":"Der Placebo-Effekt ist real und erklärt viel, aber so formuliert klingt es nach „Du spinnst“. Der Ton macht aus einer Erklärung eine Abwertung.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Ich verstehe, dass du deine Überzeugung verteidigst, Lisa. Dann bleib eben dabei und trink weiter deinen Tee, ich mische mich nicht mehr ein.“","style":"ausstieg","reaction":"„Ja, mache ich. Und danke, dass du das nicht schlechtredest.“","feedback":"Das ist ein vorschneller Rückzug. Du lässt Lisa mit der unbelegten Behauptung allein, obwohl sie gerade selbst ins Zweifeln kam. Freundschaft bleibt heil, aber eine Chance verpufft.","score":0,"nextStepId":"step-end-rueckzug"}]},"step-3-success":{"id":"step-3-success","speaker":"Lisa","speech":"„Moment mal... Wenn niemand ein einziges Gift benennen kann, was soll der Tee dann bitte ausleiten? *lacht verlegen* Ich hab da wohl einer ziemlich vagen Angst Geld hinterhergeworfen. Und Leber und Nieren machen das ja eh die ganze Zeit... Das ist ein bisschen peinlich.“","options":[{"text":"„Das ist kein bisschen peinlich, Lisa. Du hast gerade deine eigene Idee kritisch geprüft, und das können viele nicht. Und wenn du magst: Ich trinke gern einen normalen Kräutertee mit dir, einfach weil er schmeckt.“","style":"humorvoll","reaction":"„*grinst* Deal. Das Abo kündige ich noch heute. Und wenn mir wieder jemand ‚Schlacken‘ verkaufen will, frage ich erstmal nach dem Namen des Gifts!“","feedback":"Perfekt! Du würdigst die Fähigkeit zur Entkopplung: Lisa darf falsch gelegen haben, ohne dass es etwas über ihren Wert sagt. Genau so wird Meinungsänderung leicht.","score":3}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Lisa","speech":"„Ich weiß gerade nicht, was ich glauben soll. Irgendwie fühlt sich das jetzt so an, als hätte ich mich blamiert. Und ich mag den Tee doch eigentlich.“","options":[{"text":"„Du hast dich überhaupt nicht blamiert. Man kann den Tee mögen, ohne an Schlacken zu glauben. Das eine ist Geschmack, das andere eine Behauptung, die man prüfen kann.“","style":"deeskalierend","reaction":"„Okay, das ist ein guter Punkt. Ich muss das erstmal sacken lassen. Aber danke, dass du mich nicht auslachst.“","feedback":"Gelungene Entkopplung: Der Tee darf schmecken, die Schlacken-Behauptung bleibt davon getrennt prüfbar. Die Freundschaft ist geschützt, die Sachfrage bleibt offen.","score":2},{"text":"„Naja, wenn du weiterhin Geld für ein Placebo ausgeben willst, bitte schön. Dein Konto, deine Entscheidung, aber sag nachher nicht, es hätte dich keiner gewarnt.“","style":"sarkastisch","reaction":"„Gut, dann ist ja alles gesagt. Ich geh jetzt.“","feedback":"Die Spitze schließt das Gespräch, bevor Lisas Zweifel Raum bekommen. Wer abwertet, bremst die Entkopplung und verliert den Zugang.","score":-2}]},"step-4-success":{"id":"step-4-success","speaker":"Lisa","speech":"„Also eigentlich weiß ich gar nicht, ob es am Tee liegt. Vielleicht teste ich mal zwei Wochen ohne und schaue, ob sich was ändert. Was meinst du?“","options":[{"text":"„Finde ich eine tolle Idee! Du behandelst deine Annahme wie eine Hypothese und testest sie selbst. Lass uns danach vergleichen, wie du dich gefühlt hast.“","style":"humorvoll","reaction":"„Gemacht! Und falls es am Tee lag, gebe ich es zu, und falls nicht, dann nenne ich mich ab sofort ‚Schlacken-Skeptikerin‘.“","feedback":"Starker Abschluss: Lisa sieht ihre Idee als prüfbare Hypothese statt als Teil ihrer Identität. Das ist die Haltung, die dauerhaft vor leeren Versprechen schützt.","score":2}]},"step-end-rueckzug":{"id":"step-end-rueckzug","speaker":"Lisa","speech":"„Ach, ich bin froh, dass wir uns da nicht streiten. Ich trinke meinen Tee einfach weiter, und fertig. Sag mal, was gibt es bei dir Neues?“","options":[{"text":"Ende: Lisa bleibt beim Tee, die offene Frage verpufft. Die Freundschaft ist unbeschädigt, aber ihr Zweifel bekam keinen Raum.","style":"ausstieg","reaction":"Beim nächsten Mal lohnt es sich, dranzubleiben: Wer dem Gefühl Raum lässt und die Behauptung freundlich weiter prüft, hilft bei der Entkopplung.","feedback":"Ein Rückzug schützt zwar die Stimmung, lässt die unbelegte Behauptung aber unberührt. Die Idee bleibt Teil von Lisas Selbstbild.","score":0}]},"step-fail":{"id":"step-fail","speaker":"Lisa","speech":"„Weißt du was, lass es einfach. Ich trinke meinen Tee weiter, und du musst ihn ja nicht mögen.“ *wendet sich ab und schaut aufs Handy*","options":[{"text":"Ende: Lisa fühlte sich abgewertet und verteidigt den Tee jetzt erst recht. Wenn ein Angriff auf die Idee wie ein Angriff auf die Person klingt, wird die Idee zur Festung.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst fragen, dann prüfen: Die Behauptung wird seziert, nicht der Mensch.","feedback":"Wer Lisas Überzeugung als Teil von Lisa behandelt, löst Verteidigung statt Nachdenken aus. Kognitive Entkopplung gelingt nur, wenn Idee und Person getrennt bleiben.","score":0}]}},"status":"entwurf","familie":"begriff-messbar-machen","fertigkeit":"F1","stufe":2,"kurz":"„Schlacken“ ist ein Begriff aus der Metallurgie, und ein Gift, das nie beim Namen genannt wird, lässt sich weder messen noch ausleiten. Wer die Behauptung seziert statt die Person, lässt Raum, die eigene Idee zu prüfen, ohne dass der Selbstwert auf dem Spiel steht.","prueffrage":"Welches Gift genau soll der Tee ausleiten, und was hat sich in Lisas Alltag seit Beginn des Abos sonst noch verändert?","quellen":[{"typ":"url","kurz":"NCCIH (2025): „Detoxes“ and „Cleanses“: What You Need To Know","oeffentlich":true,"url":"https://www.nccih.nih.gov/health/detoxes-and-cleanses-what-you-need-to-know","abruf":"2026-10-12"},{"typ":"url","kurz":"British Dietetic Association (2025): Detox Diets (Food Fact Sheet)","oeffentlich":true,"url":"https://bda.uk.com/foodfacts/detoxdiets","abruf":"2026-10-12"},{"typ":"doi","kurz":"Klein, A. V.; Kiat, H. (2015): Detox Diets for Toxin Elimination and Weight Management: A Critical Review of the Evidence. Journal of Human Nutrition and Dietetics 28(6), 675–686","oeffentlich":false,"doi":"10.1111/jhn.12286"}],"thema":"Gesundheit"},{"id":"scen-wunderpille-gewicht","title":"Marcos Abnehm-Wunder","subtitle":"Anatomie einer Studie, geübt mit Street Epistemology","character":"Marco, Fitnessstudio-Kollege","avatar":"💪","context":"Im Fitnessstudio hält Marco dir strahlend eine Dose „SlimBurn Ultra“ entgegen. Er schwört, damit in sechs Wochen sieben Kilo verloren zu haben, und auf der Dose steht groß „klinisch getestet“. Er will dich überreden, die Kur ebenfalls zu starten, und kauft gleich drei Dosen auf Vorrat.","goal":"Bring Marco mit neugierigen Fragen (Street Epistemology) dazu, selbst zu prüfen, was „klinisch getestet“ eigentlich belegt, und stell dabei die Fragen aus der Anatomie einer Studie, ohne ihn bloßzustellen.","bereich":"Gesundheit","laenge":"mittel","ton":"heiter","bestehenAb":6,"lektion":"„Klinisch getestet“ ist keine Qualitätsangabe, solange nicht dasteht, wie genau die Zahl ist, wie groß der Effekt ist und ob die Hypothese vor den Daten festgelegt wurde. Mit Street Epistemology fragst du nicht „Du liegst falsch“, sondern „Woher weißt du es, und wie verlässlich ist diese Methode?“ So bleibt Marco ein Kumpel, der selbst nachdenkt, statt sich zu verteidigen.","toolRef":"H.2.2","faktenRef":"A.24","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Marco","speech":"„Bro, schau dir das an! SlimBurn Ultra! Sieben Kilo in sechs Wochen, und das Beste: Steht groß drauf, ‚klinisch getestet‘! Das ist wissenschaftlich bewiesen, da kann dir keiner mehr was erzählen. Ich hole mir gleich drei Dosen, willst du auch eine?“","options":[{"text":"„Marco, ‚klinisch getestet‘ ist reines Marketing-Geschwätz. Die verkaufen dir irgendein Pülverchen, und du fällst voll drauf rein. Hör auf, dein Geld zu verbrennen.“","style":"frontal","reaction":"„Ey, ich bin doch kein Idiot! Ich hab’s am eigenen Körper erlebt, sieben Kilo! Du bist nur neidisch, dass es bei mir klappt.“ *drückt die Dose an die Brust*","feedback":"Frontalangriff: Du greifst die Schlussfolgerung an und Marco fühlt sich dumm gemacht. Er verteidigt die Dose, statt über seine Methode nachzudenken.","score":-2,"nextStepId":"step-fail"},{"text":"„Sieben Kilo, das ist ja der Hammer! Du siehst wirklich fitter aus. Darf ich dich was fragen: Was genau heißt ‚klinisch getestet‘ für dich? Was steckt da dahinter?“","style":"sokratisch","reaction":"„Na ja, also... Wissenschaftler haben das halt untersucht, im Labor, mit Probanden und so. Das ist nicht nur irgendein Zeug aus dem Internet.“ *dreht die Dose in der Hand*","feedback":"Gut: Du würdigst Marcos Erfolg, klärst zuerst die Behauptung und fragst offen nach der Bedeutung des Begriffs, genau der Einstieg von Street Epistemology.","score":3,"nextStepId":"step-2"},{"text":"„Cool für dich! Ich nehme lieber ein Eiweißshake nach dem Training, das reicht mir. Viel Spaß mit den Dosen.“","style":"ausstieg","reaction":"„Schade, du verpasst was. Aber okay, mehr für mich!“ *grinst und geht zur Theke*","feedback":"Friedlich, aber du lässt die Gelegenheit liegen. Marco bleibt bei seiner Überzeugung, und die Dosen werden weiter gekauft. Als Ausstieg okay, als Training schwach.","score":0,"nextStepId":"step-2-soft"}]},"step-2":{"id":"step-2","speaker":"Marco","speech":"„Klinisch getestet heißt, dass es in einer Studie war, und da hat es gewirkt. Steht sogar in der Werbung: ‚Gewichtsverlust in klinischen Tests nachgewiesen‘. Wenn das nicht eindeutig ist, was dann?“","options":[{"text":"„Wenn du auf einer Skala von 0 bis 100 schätzt: Wie sicher bist du, dass das Mittel wirkt? Und was ist für dich der Hauptgrund für diese Sicherheit?“","style":"sokratisch","reaction":"„Puh, 90 Prozent, würde ich sagen. Der Hauptgrund? Erstens die Studie, zweitens ich selbst: Ich hab ja sieben Kilo verloren. Das kann kein Zufall sein.“","feedback":"Stark: Die 0-bis-100-Skala und die Frage nach dem Hauptgrund decken Marcos Methode auf: Studienwerbung plus eigene Erfahrung. Jetzt kannst du beides prüfen.","score":3,"nextStepId":"step-3"},{"text":"„Eine Studie sagt wenig. Die Hersteller veröffentlichen doch nur, was ihnen passt. Das weiß man doch, und deshalb kann man auch dieser Studie nicht trauen.“","style":"sarkastisch","reaction":"„Ach komm, jetzt kommst du mit Verschwörung! Dann ist ja alles gelogen, was gedruckt wird. Da kann man ja gleich nichts mehr glauben.“","feedback":"Ein richtiger Kern (Publikationsbias), aber als Pauschalverdacht und mit spitzem Ton dahergesagt. Marco hört „alles Lüge“ und blockt. Besser wäre, die Schublade als konkrete Frage zu stellen.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Kannst du mir die Studie mal zeigen? Wie viele Leute haben mitgemacht, und wer hat sie bezahlt? Das würde mich als Erstes interessieren.“","style":"sokratisch","reaction":"„Äh... also das steht nicht auf der Dose. Aber die haben das bestimmt gut gemacht, sonst dürften sie nicht damit werben.“ *kratzt sich am Kopf*","feedback":"Brauchbar: Die Frage nach der Studie und ihren Teilnehmern deckt auf, dass die Dose dazu nichts verrät. Sie kommt aber etwas direkt, ohne vorher Marcos Sicherheit und Methode zu klären. Marco merkt die Lücke, ist aber noch nicht reflektiert.","score":1,"nextStepId":"step-3-struggle"}]},"step-2-soft":{"id":"step-2-soft","speaker":"Marco","speech":"„Weißt du, ich versteh nicht, warum alle so skeptisch sind. Es steht doch drauf: klinisch getestet. Das ist doch ein Gütesiegel, oder nicht?“","options":[{"text":"„Gütesiegel hört sich gut an. Was würde sich für dich ändern, wenn die Studie nur 20 Leute gehabt hätte? Würde dich das stutzig machen?“","style":"sokratisch","reaction":"„Hm. 20 Leute? Das wäre schon wenig, ja. Aber das weiß ich ja nicht. Meinst du, das ist wirklich so?“","feedback":"Gute Hypothesenfrage: Du lässt Marco selbst prüfen, was ihm an einer Studie wichtig wäre, statt ihm eine Antwort zu liefern.","score":2,"nextStepId":"step-3"},{"text":"„Klar ist es ein Gütesiegel, ‚klinisch getestet‘ heißt ja, dass es geprüft wurde. Viel Erfolg weiterhin.“","style":"ausstieg","reaction":"„Siehste! Danke, Alter, ich dachte schon, ich bin hier der Einzige, der’s kapiert.“ *klopft dir auf die Schulter*","feedback":"Fraglich: Du stellst „klinisch getestet“ als Gütesiegel hin, ohne zu wissen, was dahintersteht. Ob Register, Vorab-Plan, Intervall und Effektstärke vorliegen, sagt das Etikett nicht. Damit verstärkst du Marcos Sicherheit, statt sie prüfen zu lassen.","score":-2,"nextStepId":"step-fail"},{"text":"„Ich bin mir nicht sicher, ob das ein Siegel ist. Woran würdest du erkennen, ob ein Test seriös war?“","style":"sokratisch","reaction":"„Gute Frage... Vielleicht, wenn es ein bekanntes Institut war? Oder die Ergebnisse veröffentlicht wurden? So genau weiß ich das gar nicht.“","feedback":"Passend: Offene Frage nach Marcos Maßstäben. Er merkt, dass er die Kriterien selbst nicht kennt.","score":2,"nextStepId":"step-3"}]},"step-3":{"id":"step-3","speaker":"Marco","speech":"„Okay, aber ich hab’s ja selbst erlebt: sieben Kilo! Das ist doch der beste Beweis, oder? Ich hab das Zeug genommen, und die Kilos sind runter. Was soll da noch dagegen sprechen?“","options":[{"text":"„Sieben Kilo sind eine Leistung. Was hast du in den sechs Wochen sonst noch geändert? Training, Essen, Schlaf? Wie könnte man herausfinden, ob es wirklich die Dose war?“","style":"sokratisch","reaction":"„Hmm... Ich hab mit dem Kraftraining angefangen, und seit der Dose zähle ich auch Kalorien, weil ich mir sonst blöd vorkomme. Und Süßes hab ich auch gestrichen... Moment, kann das auch daran liegen?“","feedback":"Meisterhaft: Du bietest eine alternative Erklärung an und fragst nach einer verlässlicheren Methode, statt zu belehren. Marco entdeckt selbst die Störfaktoren.","score":3,"nextStepId":"step-4"},{"text":"„Eine einzelne Person beweist gar nichts, das ist Anekdoten-Evidenz. Das Niveau liegt auf der untersten Stufe der Evidenzpyramide, mehr ist da nicht zu holen.“","style":"frontal","reaction":"„Anekdoten-was? Jetzt kommst du mir mit Fachbegriffen. Das ist mein Körper, das sind meine Ergebnisse! Du redest wie ein Lehrbuch.“","feedback":"Inhaltlich richtig, aber als Fremdwort-Keule vorgetragen. Marco fühlt sich belehrt und abgewertet, statt zum Nachdenken eingeladen zu werden.","score":-1,"nextStepId":"step-fail"},{"text":"„Und wenn du im Training ohnehin mehr Sport machst als früher? Ist das nicht auch ein möglicher Grund für die sieben Kilo, die du verloren hast?“","style":"sokratisch","reaction":"„Schon möglich. Aber ich hab ja auch die Dose genommen, also kann ich nicht sagen, was von beidem es war. Da müsste man ja beides trennen...“","feedback":"Brauchbar: Die Alternativerklärung steht im Raum, wird aber als rhetorische Frage gestellt statt als echte Neugier. Marco ahnt das Problem, ohne die Methode ganz zu sehen.","score":1,"nextStepId":"step-4"}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Marco","speech":"„Hm. Ich weiß nicht... Jetzt bringst du mich ganz durcheinander. Ich wollte mich doch einfach über meine sieben Kilo freuen.“","options":[{"text":"„Und das darfst du auch, die Arbeit im Studio hast du geleistet! Ich frage aus Neugier, weil ich lernen will, wie man eine Studie liest. Schauen wir uns zusammen die Dose an?“","style":"deeskalierend","reaction":"„Na gut. Wenn’s nicht dein Plan ist, mir den Spaß zu verderben, gern. Lass uns schauen, was auf der Verpackung noch steht.“ *dreht die Dose um*","feedback":"Gute Reparatur: Du entschärfst, würdigst Marcos Leistung und machst daraus ein gemeinsames Projekt. Marco bleibt beim Thema, ohne sein Gesicht zu verlieren.","score":2,"nextStepId":"step-4"},{"text":"„Dann lassen wir’s. Meine Meinung kennst du, und ich will dir nichts verbieten. Du musst am Ende selbst wissen, was du mit deinem Geld machst, das ist deine Sache.“","style":"ausstieg","reaction":"„Alles klar. Dann gehe ich jetzt die Dosen bezahlen.“ *geht*","feedback":"Rückzug ohne Brücke: Die Beziehung ist gerettet, aber das Thema ist abgeschlossen. Als Ausstieg legitim, als Lernerfolg ein Rückschritt.","score":0,"nextStepId":"step-fail"},{"text":"„Ach, wenn du so reagierst, dann glaub eben, was du willst. Ich kann dir nicht helfen, und ich habe auch keine Lust, es weiter zu versuchen.“","style":"sarkastisch","reaction":"„Ey, jetzt werd nicht pampig. Dann ist das Gespräch beendet.“ *wendet sich ab*","feedback":"Schwach: Der genervte Ton trifft den Menschen, nicht die Behauptung. Seziert wird die Behauptung, nicht der Mensch.","score":-2,"nextStepId":"step-fail"}]},"step-4":{"id":"step-4","speaker":"Marco","speech":"„Okay, vielleicht war’s nicht nur die Dose. Aber die Studie dahinter, die muss ja was belegen. Wenn da zum Beispiel stünde: ‚Im Schnitt 2 Kilo mehr verloren als die Kontrollgruppe‘, wäre das doch super, oder?“","options":[{"text":"„Das wäre eine konkrete Zahl, stimmt. Aber stell dir vor, die Studie hatte nur 20 Teilnehmer und das Intervall ginge von minus 1 bis plus 5 Kilo. Was würde das für die Aussage bedeuten?“","style":"sokratisch","reaction":"„Moment... minus 1 bis plus 5? Dann könnte es ja auch sein, dass die Leute mit dem Mittel sogar zugenommen hätten, im ungünstigen Fall? Also ist die 2 Kilo gar nicht sicher.“","feedback":"Gut: Du machst das Konfidenzintervall greifbar, indem du beide Enden in Worte übersetzt. Marco sieht selbst, dass die Zahl ohne ihre Unschärfe wenig sagt.","score":2,"nextStepId":"step-5-success"},{"text":"„Und wenn die Firma die Studie selbst bezahlt hat? Dann ist das Ergebnis doch eh gekauft.“","style":"sarkastisch","reaction":"„Jetzt unterstellst du denen was! Das weißt du doch gar nicht. Nur weil jemand zahlt, ist doch nicht gleich alles gefälscht.“","feedback":"Unbelegter Verdacht: Wer die Studie bezahlt, entscheidet nicht automatisch über das Ergebnis. Entscheidend sind Vorab-Plan, Registrierung und offene Zahlen.","score":-1,"nextStepId":"step-5-struggle"},{"text":"„Genau solche Angaben fehlen auf der Dose. Was würdest du bei einer Studie wissen wollen, bevor du ihr traust?“","style":"sokratisch","reaction":"„Puh... Wie viele Leute dabei waren, vielleicht? Und wie groß der Unterschied zur Gruppe ohne Mittel war? Und ob die Hypothese schon vorher feststand? Das klingt ja fast wie eine Checkliste.“","feedback":"Sehr gut: Marco entwickelt selbst Maßstäbe. Zwei davon entsprechen Fragen aus „Die Anatomie einer Studie, zweiter Blick“: wie groß der Unterschied ist (Effektstärke) und ob die Hypothese vorher feststand (Präregistrierung). So prüft er seine Methode selbst.","score":3,"nextStepId":"step-5-success"}]},"step-5-success":{"id":"step-5-success","speaker":"Marco","speech":"„Okay, ich glaube, ich hab da vorschnell was geglaubt. ‚Klinisch getestet‘ kann ja alles Mögliche heißen. Was mache ich jetzt, die Dosen sind schon im Korb...“","options":[{"text":"„Gar nichts musst du heute entscheiden! Lass uns daheim mal die Fragen auf einen Zettel schreiben: Wie viele Teilnehmer, wie groß der Effekt, ob vorab geplant. Wenn die Firma das offenlegt, sind wir schlauer. Dein Training hast du ja auch ohne Dose geschafft.“","style":"humorvoll","reaction":"„Haha, stimmt, die Kilos sind ja nicht von der Dose gelaufen. Gut, ich lege zwei zurück und teste die Fragen mal. Danke, dass du mich nicht belehrt hast, sondern gefragt.“","feedback":"Erfolg: Du lässt Marco die Entscheidung, gibst ihm eine Checkliste und würdigst seine eigene Leistung. Das ist Street Epistemology in Reinform.","score":3}]},"step-5-struggle":{"id":"step-5-struggle","speaker":"Marco","speech":"„Du machst mich hier zum Deppen, glaube ich. Ich geb mein Geld aus, wie ich will, das ist meine Sache.“","options":[{"text":"„Völlig richtig, das ist deine Entscheidung, und ich will dir nichts. Ich war nur neugierig, was hinter ‚klinisch getestet‘ steckt. Lass uns später beim Training weiterreden, ich muss eh noch Kreuzheben.“","style":"deeskalierend","reaction":"„Na gut. Aber nichts für ungut, ja? Ich werde mir die Dose nochmal genauer anschauen.“ *lächelt schief*","feedback":"Guter Ausstieg: Du entschärfst, respektierst Marcos Autonomie und lässt die Tür offen, wie „Street Epistemology“ es für den Gesprächsabschluss vorsieht. Die Sachfrage bleibt für ein andermal.","score":2}]},"step-fail":{"id":"step-fail","speaker":"Marco","speech":"„Ich sehe schon, du glaubst mir nicht. Egal, ich bleibe dabei: klinisch getestet, wissenschaftlich bewiesen.“ *geht mit den Dosen zur Kasse*","options":[{"text":"Ende: Marco hat sich nicht gehört gefühlt und bleibt bei seiner Überzeugung. Rechthaben und Weiterhelfen sind zweierlei.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst fragen, dann erst Fakten nennen: Was meint er mit „klinisch getestet“ und wie sicher ist er sich?","feedback":"Street Epistemology greift nicht die Schlussfolgerung an, sondern lädt ein, die eigene Methode zu prüfen. Die Fragen aus Schublade, Wette, Unschärfe, Größe, Aufteilung eignen sich dafür als Leitfaden.","score":0}]}},"status":"entwurf","familie":"befund-reichweite","fertigkeit":"F1","stufe":3,"kurz":"„Klinisch getestet“ sagt allein nichts über die Qualität: Entscheidend ist, wie viele teilgenommen haben, wie groß und wie genau der Effekt ist und ob die Hypothese vorher feststand. Wer fragt, woher jemand etwas weiß, regt Nachdenken statt Verteidigung an.","prueffrage":"Was verrät die Dose außer „klinisch getestet“ über Teilnehmerzahl, Vergleichsgruppe und Größe des Effekts, und was hat Marco in den sechs Wochen sonst geändert?","quellen":[{"typ":"url","kurz":"American Statistical Association (2016): American Statistical Association Releases Statement on Statistical Significance and P-Values (Pressemitteilung)","oeffentlich":true,"url":"https://www.amstat.org/asa/files/pdfs/p-valuestatement.pdf","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nosek, B. A.; Ebersole, C. R.; DeHaven, A. C.; Mellor, D. T. (2018): The preregistration revolution. PNAS 115(11), 2600–2606","oeffentlich":true,"doi":"10.1073/pnas.1708274114","abruf":"2026-10-12"},{"typ":"url","kurz":"Street Epistemology International: Street Epistemology (Startseite)","oeffentlich":true,"url":"https://www.streetepistemology.com/","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"scen-magnetarmband","title":"Thomas und das Magnetarmband","subtitle":"Regression zur Mitte, geübt mit Street Epistemology","character":"Thomas, Kollege im Vertrieb","avatar":"🧲","context":"In der Kaffeeküche zeigt dir Thomas stolz sein neues Armband. Vor drei Wochen hatte er einen Tag mit so schlimmen Rückenschmerzen, dass er kaum aus dem Bürostuhl kam. Am nächsten Tag hat er sich das Magnetarmband bestellt, und seitdem sind die Schmerzen weg.","goal":"Würdige Thomas' Erfahrung, ohne sie abzuwerten, und bring ihn mit neugierigen Fragen dazu, selbst über natürlichen Verlauf und Regression zur Mitte nachzudenken.","bereich":"Arbeit","laenge":"kurz","ton":"heiter","bestehenAb":4,"lektion":"Beschwerden schwanken, und nach einem Extremwert liegt der nächste Wert statistisch meist wieder näher am Durchschnitt (Regression zur Mitte). Wer genau am Tiefpunkt etwas Neues ausprobiert, schreibt die ohnehin fällige Besserung gern dem Neuen zu. Statt zu belehren, hilfst du mit Street Epistemology beim Nachdenken: Was ist die Methode hinter der Gewissheit, und wie ließe sich testen, ob es wirklich das Armband war?","toolRef":"H.2.2","faktenRef":"C.4.6","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Thomas","speech":"„Schau mal, mein Magnetarmband! Seit ich das trage, sind meine Rückenschmerzen komplett weg. Letzte Woche konnte ich sogar wieder den Umzugskarton von meiner Schwester schleppen. Das kann kein Zufall sein!“","options":[{"text":"„Thomas, das ist Placebo, nichts weiter. Magnete in Armbändern haben keine Wirkung auf Rückenschmerzen. Das ist Geldmacherei.“","style":"frontal","reaction":"„Na toll, danke fürs Madigmachen. Ich spüre den Unterschied doch selbst, da brauche ich keinen Besserwisser, der mir erklärt, was ich nicht gespürt habe!“ *schiebt den Ärmel über das Armband*","feedback":"Frontalangriff: Du wertest seine Erfahrung ab und er geht in die Defensive. Er fühlt sich angegriffen, das Gespräch ist praktisch beendet.","score":-2,"nextStepId":"step-fail"},{"text":"„Cool, dass es dir besser geht, das freut mich echt! Darf ich dich was fragen: Wie lange hattest du die Schmerzen, und was war das für ein Tag, als du dir das Armband bestellt hast?“","style":"sokratisch","reaction":"„Ach, die kommen und gehen schon seit Jahren. Aber vor drei Wochen war es der absolute Horror. Ich konnte kaum aufstehen, da habe ich gesagt: Jetzt reicht's, jetzt muss was passieren!“","feedback":"Sehr gut: Du würdigst seine Erfahrung und erfragst genau die Umstände, die für die Regression zur Mitte entscheidend sind (Beschwerden schwanken, Behandlung am Höhepunkt). Thomas liefert die Zutaten selbst.","score":3,"nextStepId":"step-2"},{"text":"„Ach so, ein Magnetarmband. Na ja, wenn du dich damit wohlfühlst, ist ja alles gut. Hast du schon den Kaffee probiert, den Sabine mitgebracht hat?“","style":"ausstieg","reaction":"„Ja, ist toll, oder? Ich sag's dir, jeder sollte so eins haben. Echt, das war heftig: Vor drei Wochen hatte ich den schlimmsten Tag seit Monaten, und seitdem geht es stetig bergauf!“","feedback":"Freundlich, aber du lässt die Gelegenheit verstreichen. Ein Themenwechsel ist legitim, hier hätte aber ein neugieriger Moment gut gepasst, und Thomas fühlt sich nun bestätigt.","score":0,"nextStepId":"step-2"}]},"step-2":{"id":"step-2","speaker":"Thomas","speech":"„Es war der schlimmste Tag seit Monaten. Und seitdem geht es stetig bergauf. Da muss das Armband doch der Grund sein, oder was soll es sonst gewesen sein?“","options":[{"text":"„Wie sicher bist du dir auf einer Skala von 0 bis 100, dass es das Armband war? Und was ist für dich der Hauptgrund, der dich so sicher macht?“","style":"sokratisch","reaction":"„Hm, so 90 vielleicht. Der Grund? Na ja, es war davor schlimm und danach gut. Das ist doch eigentlich ziemlich eindeutig.“","feedback":"Klassische Street Epistemology: Sicherheitsgrad klären und die Methode hinter der Gewissheit aufdecken. Aus „Ich weiß es“ wird „Ich schließe es aus der zeitlichen Abfolge“, und das lässt sich gemeinsam prüfen.","score":3,"nextStepId":"step-3-success"},{"text":"„Thomas, bei Rückenschmerzen schwankt es immer: Nach einem Extremtag kommt statistisch gesehen ein besserer, das nennt man Regression zur Mitte. Dein Armband hat damit nichts zu tun.“","style":"frontal","reaction":"„Regression, Statistik... na klar. Ich weiß, wie ich mich fühle. Du willst es mir nur ausreden, weil du es nicht verstehst!“","feedback":"Der Fachbegriff stimmt, aber als fertiges Urteil vorgesetzt wirkt er wie ein Vortrag. Thomas hat keine Gelegenheit, selbst auf den Gedanken zu kommen, und blockt ab.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Vielleicht hat es auch was mit deinem Bürostuhl zu tun, den du letzte Woche getauscht hast? Oder mit der Matratze? Ich wette, es lag an einem von beiden.“","style":"humorvoll","reaction":"„Ach komm, der Stuhl ist doch Quatsch. Das Armband ist das Einzige, was ich wirklich neu gemacht habe. Du suchst jetzt einfach irgendeine andere Erklärung.“","feedback":"Du erfindest eine Gegenursache, die du nicht belegen kannst. Das ist nur ein Gegenanspruch statt einer Frage. Die Methode fragt nach dem Weg zum Wissen, sie liefert keine eigene Behauptung.","score":-1,"nextStepId":"step-3-struggle"}]},"step-3-success":{"id":"step-3-success","speaker":"Thomas","speech":"„Hm... klingt, als wäre ‚vorher schlimm, nachher gut‘ mein einziger Beweis. Aber warte mal: Bei meinen Rückenschmerzen ist es ja immer rauf und runter gegangen. Der Tag davor war halt der Gipfel. Wie würde man denn überhaupt rausfinden, ob es wirklich das Armband war?“","options":[{"text":"„Gute Frage. Man müsste Leute mit echtem und mit wirkungslosem Armband vergleichen, ohne dass sie wissen, welches sie tragen, und Leute ganz ohne Armband nach so einem Tiefpunkt dazunehmen.“","style":"sokratisch","reaction":"„Ehrlich gesagt... eher 50 als 90. Verrückt, das hätte ich vor fünf Minuten nicht gedacht. Ich trage es erst mal weiter, aber ich schau mir mal an, wie es bei mir so schwankt. Danke für die Fragen!“","feedback":"Stark: Du bietest verlässlichere Methoden an (Vergleich mit einer unbehandelten Kontrollgruppe, und ein Scheinarmband gegen den Placebo-Effekt) und fragst nach dem neuen Sicherheitsgrad. Der Stein des Zweifels rollt, ohne dass Thomas sein Gesicht verliert.","score":3},{"text":"„Genau, wahrscheinlich war es also einfach Zufall. Gut, dass du das jetzt auch siehst, Thomas! Das Armband kannst du entsorgen, es hat dir ohnehin nichts gebracht und kostet nur Geld.“","style":"frontal","reaction":"„Moment, ich habe nur gesagt, dass ich es mir überlege. Jetzt klingst du schon wieder so, als wüsstest du alles besser.“ *lacht leicht gequält*","feedback":"Thomas war auf einem guten Weg, aber du überholst ihn mit einem fertigen Urteil. SE will einen Stein des Zweifels ins Rollen bringen, kein Geständnis erzwingen.","score":0},{"text":"„Ach, lass gut sein. Wenn es dir hilft, ist doch alles in Ordnung. Wir müssen ja nicht alles auseinandernehmen, und ich will dir die Freude an dem Armband nicht nehmen.“","style":"ausstieg","reaction":"„Stimmt auch wieder. Ich trag's einfach weiter. Danke, dass du mir zugehört hast!“","feedback":"Ein freundlicher Rückzug, aber Thomas' eigene Frage bleibt unbeantwortet. Bei einem harmlosen Armband ist das verschmerzbar, wichtig wird es, wenn Besserung gegen echte Therapie ausgespielt wird.","score":1}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Thomas","speech":"„Ich merke schon, du glaubst mir nicht. Aber ich habe es am eigenen Rücken erlebt, das kann mir keiner ausreden.“","options":[{"text":"„Doch, ich glaube dir, dass es dir besser geht, und das freut mich. Ich war nur neugierig, ob es bei deinen Schwankungen auch ohne Armband besser geworden wäre.“","style":"deeskalierend","reaction":"„Hm... ohne Armband? Ich habe es ja nie getestet. Ich müsste mal beobachten, wie es bei mir so schwankt. Na gut, du hast mich zum Nachdenken gebracht.“","feedback":"Gute Reparatur: Du würdigst die Erfahrung, nimmst den Druck raus und kehrst zur Methodenfrage zurück. Erst jetzt ist Thomas wieder offen.","score":2},{"text":"„Dann glaub eben weiter an deinen Magneten. Irgendwann merkst du schon, dass ich recht hatte, und dann reden wir noch einmal darüber, wenn du so weit bist.“","style":"sarkastisch","reaction":"„Danke, sehr freundlich. Ich lasse mir von dir sicher nichts mehr erzählen.“ *dreht sich um und geht*","feedback":"Sarkasmus trifft den Menschen, nicht die Behauptung. Die Tür für künftige Gespräche ist zu, und Thomas ist nun eher noch überzeugter.","score":-2}]},"step-fail":{"id":"step-fail","speaker":"Thomas","speech":"„Ich lass mir meine Erfahrung nicht kleinreden. Und jetzt entschuldige, ich muss zum Meeting.“ *geht, das Armband demonstrativ glattstreichend*","options":[{"text":"Ende: Thomas fühlte sich belehrt und hält an seinem Armband fester denn je. Seziert werden soll die Behauptung, nicht der Mensch.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst fragen: Wie lange schon? Wie schlimm war es? Wie sicher bist du? Der Rest ergibt sich.","feedback":"Street Epistemology fragt nach dem Weg zum Wissen, statt das Ergebnis zu bestreiten. Die Regression zur Mitte erkennt er am besten selbst.","score":0}]}},"status":"entwurf","familie":"was-waere-ohne","fertigkeit":"F2","stufe":3,"kurz":"Beschwerden schwanken, und nach einem besonders schlechten Tag folgt meist ein besserer. Wer genau am Tiefpunkt etwas Neues ausprobiert, schreibt die ohnehin zu erwartende Besserung leicht dem Neuen zu; erst ein fairer Vergleich kann zeigen, ob es wirklich daran lag.","prueffrage":"An welchem Punkt seines Schmerzverlaufs hat Thomas das Armband bestellt, und wie ging es ihm früher in den Tagen nach ähnlich schlimmen Tiefpunkten?","quellen":[{"typ":"doi","kurz":"Morton, V.; Torgerson, D. J. (2003): Effect of regression to the mean on decision making in health care. BMJ 326(7398), 1083–1084","oeffentlich":true,"doi":"10.1136/bmj.326.7398.1083","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1125994","abruf":"2026-10-12"},{"typ":"url","kurz":"Street Epistemology International: How to Do Street Epistemology? Steps to Follow","oeffentlich":true,"url":"https://streetepistemology.com/how-to-do-street-epistemology","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Boghossian, P. (2013): A Manual for Creating Atheists. Durham (NC): Pitchstone Publishing (prägt den Begriff Street Epistemology; nach Landkarte Fn. gl-h-4)","oeffentlich":false}],"thema":"Gesundheit"},{"id":"scen-kollege-kaffee-gesund","title":"Marcel und die Kaffee-Schlagzeile","subtitle":"Studie „Kaffee verlängert das Leben“, geübt mit der Deeskalations-Matrix","character":"Marcel, Kollege","avatar":"☕","context":"In der Teeküche steht Marcel vor seiner Maschine, die dritte Tasse des Vormittags in der Hand. Er hat eine Schlagzeile gelesen, nach der Kaffee das Leben verlängert, und trinkt seitdem acht Tassen am Tag. Als du neulich einen Zweifel angedeutet hast, wertete er das als Neid.","goal":"Bring Marcel dazu, selbst nach unsichtbaren dritten Faktoren zu fragen, ohne dass er sich angegriffen fühlt und das Gespräch dichtmacht.","bereich":"Arbeit","laenge":"kurz","ton":"sarkastisch","bestehenAb":4,"lektion":"Eine Schlagzeile, die eine Ursache behauptet, beruht oft nur auf einer Korrelation. Mit der Frage nach dem unsichtbaren Faktor C prüfst du die Behauptung, ohne den Menschen anzugreifen. Und wer sich zuerst verstanden fühlt, hört auch eher zu, wenn es um Zahlen geht.","toolRef":"H.2.1","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Marcel","speech":"„Na, wieder Wasser, wie? Ich sag's dir: Es steht schwarz auf weiß in der Zeitung, Kaffee verlängert das Leben. Ich arbeite quasi an meiner Unsterblichkeit. Acht Tassen am Tag, und die Maschine ist mein bester Freund. Und komm mir bloß nicht wieder mit Zweifeln, das ist doch nur Neid.“","options":[{"text":"„Marcel, das ist doch Quatsch. Eine Zeitungsschlagzeile ist kein Beweis, und acht Tassen am Tag sind ohnehin zu viel. Wie kann man nur so leichtgläubig sein?“","style":"frontal","reaction":"„Aha, da ist er ja wieder, der Herr Besserwisser! Ich wusste, dass das kommt. Neid, sag ich doch. Ich trinke jetzt demonstrativ eine neunte Tasse, nur dir zu Ehren.“","feedback":"Frontalangriff mit Abwertung („leichtgläubig“). Marcel sieht seine Neid-These bestätigt. Wie Reaktion A in der Deeskalations-Matrix zeigt: Ein Gegenangriff verhärtet die Positionen, das Gespräch ist tot.","score":-2,"nextStepId":"step-fail"},{"text":"„Klingt, als würde dich diese Meldung richtig freuen und als würde deine Kaffeegewohnheit sonst oft belächelt. Erzähl mal, was genau in dem Artikel stand?“","style":"deeskalierend","reaction":"„*stutzt, die Tasse auf halber Höhe* Na ja, das fragt sonst keiner. Also: Eine große Studie, Leute, die Kaffee trinken, leben im Schnitt länger. Das war die Schlagzeile, ziemlich groß sogar.“","feedback":"Gut! Du validierst das Gefühl, ohne dem Inhalt zuzustimmen (Technik 1). Marcels Bedürfnis, sich zu verteidigen, sinkt, und er erzählt freiwillig, worauf seine Überzeugung beruht.","score":3,"nextStepId":"step-2"},{"text":"„Jaja, Kaffee, das Lebenselixier. Ich bin sowieso gleich weg, die Besprechung beginnt. Trink dich ruhig unsterblich, ich habe dafür keine Zeit.“","style":"ausstieg","reaction":"„Siehst du, kein Gegenargument. Dann ist ja alles klar. Bis später, ich hole mir noch eine Tasse.“","feedback":"Ein Rückzug ohne Absicht zur Wiederaufnahme. Die strategische Auszeit (Technik 4) wirkt nur, wenn du das Thema ausdrücklich offenhältst, sonst bleibt Marcel mit seiner Schlagzeile allein.","score":-1,"nextStepId":"step-fail"}]},"step-2":{"id":"step-2","speaker":"Marcel","speech":"„Siehst du, genau das sage ich ja: Kaffeetrinker leben länger. Also macht der Kaffee das. Ist doch logisch! Was soll man da noch groß diskutieren?“","options":[{"text":"„Das ist ein klassischer Cum-hoc-Fehlschluss, Marcel. Korrelation ist nicht Kausalität. Das lernt man im ersten Semester Statistik, und du solltest es besser wissen.“","style":"frontal","reaction":"„Ah, jetzt kommen die Fachwörter. Typisch. Wenn man nicht weiterweiß, wirft man mit Latein um sich. Du willst mir doch nur den Spaß verderben.“","feedback":"Inhaltlich richtig, aber als Belehrung verpackt. Wer ein Fachwort wie eine Keule schwingt, löst Verteidigung aus, statt Nachdenken. Besser: den Gedanken als gemeinsame Frage anbieten.","score":0,"nextStepId":"step-3-struggle"},{"text":"„Mir fällt eine Frage ein: Eine Beobachtungsstudie sieht nur, wer Kaffee trinkt und wer wie lange lebt. Welche unsichtbaren Faktoren könnten beides beeinflussen?“","style":"sokratisch","reaction":"„Unsichtbare Faktoren... *kratzt sich am Kinn* Na ja, vielleicht, dass Leute, die viel Kaffee trinken, auch viel arbeiten? Oder ... hm, dass sie überhaupt fit genug sein müssen, um so viel zu trinken?“","feedback":"Treffer! Ich-Botschaft plus die Aktivierungsfrage aus „Korrelation vs. Kausalität“: Welcher dritte Faktor C könnte A und B verursachen? Marcel sucht selbst nach Störfaktoren, und das wirkt stärker als jedes fertige Gegenargument.","score":3,"nextStepId":"step-3-success"},{"text":"„Stimmt schon, bei der Menge Kaffee auf der Welt muss ja was dran sein. Ich trinke vielleicht auch mal eine Tasse mehr, wenn das so gesund ist.“","style":"humorvoll","reaction":"„Na endlich jemand mit Weitblick! Ich wusste, dass du auf meiner Seite stehst. Prost!“","feedback":"Du stimmst dem Inhalt zu, nur um die Stimmung zu retten. Genau das ist der Kipppunkt der Deeskalation: Gefühle validieren heißt nicht, falsche Kausalbehauptungen zu bestätigen.","score":-2,"nextStepId":"step-fail"}]},"step-3-success":{"id":"step-3-success","speaker":"Marcel","speech":"„Okay, okay, vielleicht ist es nicht ganz so einfach, wie die Schlagzeile klingt. Wer weiß, vielleicht trinken gesunde Leute einfach mehr Kaffee, und nicht der Kaffee macht sie gesund. Aber acht Tassen am Tag sind trotzdem gut für mich, oder?“","options":[{"text":"„Das weiß ich ehrlich nicht, und eine Schlagzeile verrät es auch nicht. Lass uns gemeinsam nachlesen, was die Studie wirklich gemessen hat. Ich lade dich auf einen Kaffee ein.“","style":"sokratisch","reaction":"„Gemeinsam nachlesen, na gut. Aber eine Tasse zahlst du, und ich nehme die zweite selbst. *grinst* Vielleicht stelle ich bis dahin mal von acht auf fünf um. Für die Wissenschaft.“","feedback":"Rund! Du gibst offen zu, was du nicht weißt, und machst aus dem Streit ein gemeinsames Projekt (Technik 3). Marcel behält sein Gesicht, die Beziehung bleibt heil, und der Weg zur Quelle ist offen.","score":3},{"text":"„Jetzt bist du auf dem richtigen Weg, Marcel! Wer hätte gedacht, dass du doch noch zur Vernunft kommst. Das hat ja lange genug gedauert, wirklich.“","style":"sarkastisch","reaction":"„Zur Vernunft kommen? Ich war immer vernünftig. Also, ich sage lieber nichts mehr. Ich hole mir einen Kaffee.“","feedback":"Das Lob kommt von oben herab: Du schreibst Marcel zu, bisher unvernünftig gewesen zu sein. Das ist eine verdeckte „Du“-Botschaft (Technik 2), und die eben geöffnete Tür geht wieder zu.","score":-1}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Marcel","speech":"„Ich hab keine Lust auf Seminar-Atmosphäre in der Teeküche. Entweder Kaffee ist gesund oder nicht, so kompliziert kann das nicht sein.“","options":[{"text":"„Stimmt, das ist zu viel Theorie, und das ist meine Schuld. Lass uns das Thema ruhen. Vielleicht schauen wir morgen beim Mittagessen mal in die Studie.“","style":"deeskalierend","reaction":"„Mittagessen, na gut. Aber du zahlst die Cola. Und ich rede jetzt nicht über Statistik, ich rede über Kaffee.“","feedback":"Eine saubere strategische Auszeit (Technik 4): Du übernimmst Verantwortung für den Ton, hältst das Thema aber ausdrücklich offen. Die Sachfrage bleibt für später, die Beziehung ist geschützt.","score":2},{"text":"„Ach komm, jetzt sei doch nicht gleich beleidigt, nur weil jemand mal nachfragt. Kritik gehört dazu, und wer austeilt, muss auch einstecken können.“","style":"frontal","reaction":"„Beleidigt? Ich bin nicht beleidigt, du bist besserwisserisch. Lass mich einfach in Ruhe meinen Kaffee trinken.“","feedback":"Eine „Du“-Botschaft in Verkleidung: Du schreibst Marcel einen Zustand zu („beleidigt“). Statt einer Ich-Botschaft (Technik 2) löst das Rechtfertigung aus.","score":-1}]},"step-fail":{"id":"step-fail","speaker":"Marcel","speech":"„Wir müssen das nicht vertiefen. Ich weiß, was ich weiß, und meine Tasse ist wieder voll. Schönen Tag noch.“ *dreht sich zur Maschine um*","options":[{"text":"Ende: Das Gespräch ist beendet, und Marcel hält seine Schlagzeile fester als zuvor. Rechthaben und Weiterkommen sind zweierlei.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst das Gefühl hören, dann die Quelle gemeinsam prüfen.","feedback":"Frag dich: Wollte ich Marcel überzeugen oder das Gespräch retten? Die Deeskalations-Matrix ordnet die Reihenfolge: erst Temperatur senken, dann die Frage nach dem unsichtbaren Faktor C.","score":0}]}},"faktenRef":"A.5","status":"entwurf","familie":"korrelation-und-ursache","fertigkeit":"F2","stufe":2,"kurz":"Eine Schlagzeile, die eine Ursache behauptet, beruht oft nur auf einem beobachteten Zusammenhang. Die Frage nach einem unsichtbaren dritten Faktor, der beides beeinflussen könnte, prüft die Behauptung, ohne den Menschen anzugreifen; wer sich verstanden fühlt, hört eher zu.","prueffrage":"Was hat die Studie hinter der Schlagzeile tatsächlich beobachtet, und worin könnten sich Kaffeetrinker sonst noch von Menschen unterscheiden, die wenig Kaffee trinken?","quellen":[{"typ":"doi","kurz":"Sumner, P. u. a. (2014): The association between exaggeration in health related science news and academic press releases: retrospective observational study. BMJ 349, g7015","oeffentlich":true,"doi":"10.1136/bmj.g7015","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4262123","abruf":"2026-10-12"},{"typ":"doi","kurz":"Itzchakov, G.; Navon, N.; Crawford, J. T.; Weinstein, N.; DeMarree, K. G. (2025): Harmony in Political Discourse? The Impact of High-Quality Listening on Speakers' Perceptions Following Political Conversations. Media and Communication 13","oeffentlich":true,"doi":"10.17645/mac.9871","url":"https://www.cogitatiopress.com/mediaandcommunication/article/view/9871","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"scen-video-ist-ki","title":"„Das Video ist doch KI!“","subtitle":"Lügner-Dividende, geübt mit Emotion und Motivation","character":"Nadine, Bekannte aus dem Sportverein","avatar":"📹","context":"In der Vereins-Chatgruppe kursiert ein Handyvideo: Ein Trainer aus dem Nachbarverein beschimpft in der Kabine einen Jugendspieler. Es wurde dem Vereinsvorstand zugespielt. Nadine, mit dem Trainer befreundet, schreibt dir privat: Das Video sei sicher „von einer KI gemacht“, so was gebe es ja heute, und man dürfe es niemandem glauben.","goal":"Nimm Nadines Sorge um ihren Bekannten ernst, ohne die Behauptung zu übernehmen, und lenke das Gespräch darauf, wie man die Echtheit des Videos über Quelle und Kontext prüfen kann.","bereich":"Online","laenge":"mittel","ton":"ernst","bestehenAb":6,"lektion":"Dass es Fälschungen gibt, beweist nicht, dass dieses Video gefälscht ist: Wer jede unbequeme Aufnahme pauschal als „KI“ abtut, nutzt die Lügner-Dividende. Und weil Nadines Loyalität ein echtes Gefühl ist, das ihr Urteil lenkt, hilft es mehr, dieses Gefühl anzuerkennen und dann gemeinsam die Quelle zu prüfen. Wer eine Fälschung behauptet, müsste dafür Gründe nennen; ob die Aufnahme echt ist, klärt man über Quelle und Kontext.","toolRef":"H.1.4","faktenRef":"E.4.4","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Nadine","speech":"„Hast du das Video aus der Gruppe gesehen? Das ist doch offensichtlich KI! Heute kann man alles fälschen. Ich kenne Thomas seit Jahren, der würde nie so mit einem Kind reden. Das glaubt doch hoffentlich keiner.“","options":[{"text":"„Nadine, jetzt mach dich nicht lächerlich. Das ist ganz klar echt. Du willst es nur nicht wahrhaben, weil er dein Kumpel ist, und das ist nicht fair ihm gegenüber.“","style":"frontal","reaction":"„Wow. Danke fürs Vertrauen. Dann bin ich also parteiisch und du der große Durchblicker? Ich dachte, du kennst mich besser.“","feedback":"Frontalangriff auf die Person statt Prüfung der Behauptung. Du unterstellst Befangenheit und behauptest zugleich Echtheit, ohne etwas zu belegen. Nadine geht in Abwehr.","score":-2,"nextStepId":"step-fail"},{"text":"„Ich merke, dass dir das nahegeht. Du kennst Thomas ja gut, und so ein Video trifft einen dann doppelt. Was ist dir daran aufgefallen, das dich an KI denken lässt?“","style":"sokratisch","reaction":"„*zögert* Ehrlich gesagt... gar nichts Konkretes. Ich habe es einmal gesehen und dachte nur: Das kann er nicht sein. Es hat mich echt aufgewühlt.“","feedback":"Stark! Du erkennst das Gefühl an (Emotionen lenken das Urteil) und fragst nach den tatsächlichen Gründen, statt zu widersprechen. Nadine merkt selbst, dass ihre Aussage vor allem aus Loyalität kommt.","score":3,"nextStepId":"step-2"},{"text":"„Stimmt, heute kann man wirklich alles fälschen. Am besten hält man sich da raus und sagt nichts dazu, dann kann man auch nichts falsch machen.“","style":"ausstieg","reaction":"„Genau! Siehst du, das sehe ich auch so. Ich schreibe in die Gruppe, dass man dem Video nicht trauen kann.“","feedback":"Du bestärkst die Lügner-Dividende: Allein dass es Fälschungen gibt, ist noch kein Grund, dieses Video abzutun. So hilfst du Nadine, eine Behauptung zu verbreiten, die sie nicht geprüft hat.","score":-2,"nextStepId":"step-fail"}]},"step-2":{"id":"step-2","speaker":"Nadine","speech":"„Na gut, aber trotzdem: Es gibt diese Deepfakes ja wirklich. Ich habe gelesen, dass man heute nicht mehr erkennen kann, was echt ist. Also kann es genauso gut gefälscht sein, oder?“","options":[{"text":"„Du hast recht, dass man Fälschungen oft nicht erkennt. Deshalb schauen wir weniger aufs Bild als auf die Quelle: Wer hat das Video zuerst gepostet, und wer bestätigt es unabhängig?“","style":"sokratisch","reaction":"„Hm, das stimmt. Ich weiß nur, dass es plötzlich in der Gruppe auftauchte. Woher es kommt, hat niemand gesagt.“","feedback":"Sehr gut! Du gibst den wahren Kern zu (Menschen erkennen Fälschungen kaum besser als der Zufall) und wechselst zur Quellenprüfung, die verlässlicher ist als der Blick aufs Bild.","score":3,"nextStepId":"step-3"},{"text":"„Quatsch, ein Deepfake sieht immer komisch aus. Man erkennt das am Blinzeln und an den Lippen, und bei dem Video stimmt alles. Also ist es echt.“","style":"frontal","reaction":"„Ach ja? Und woher weißt du das so genau? Im Internet steht, dass die Dinger inzwischen perfekt sind.“","feedback":"Falsche Sicherheit: Solche Merkmale verschwinden mit besserer Technik, und Menschen überschätzen ihre Trefferquote. Du gibst Nadine einen Grund, dir zu widersprechen.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Ja, es gibt Deepfakes. Aber dass es sie gibt, heißt nicht, dass dieses Video eins ist. Wer sagt, es sei gefälscht, müsste das ja auch zeigen können.“","style":"sokratisch","reaction":"„Hmm. Gefälscht beweisen kann ich es nicht, das stimmt. Ich habe es nur gehofft.“","feedback":"Treffend: Wer eine Fälschung behauptet, müsste dafür Gründe nennen; dass es Fälschungen gibt, reicht nicht (Lügner-Dividende). Etwas abstrakt, aber Nadine kommt ins Nachdenken.","score":2,"nextStepId":"step-3"}]},"step-3":{"id":"step-3","speaker":"Nadine","speech":"„Okay, aber wenn ich ehrlich bin: Ich will einfach nicht, dass es stimmt. Thomas hat mir geholfen, als es bei mir schwierig war. Und wenn das Video echt ist, was heißt das dann über ihn?“","options":[{"text":"„Das ist ein ehrlicher Gedanke, danke. Dass er dir geholfen hat, bleibt wahr, auch wenn das Video echt wäre. Klären wir erst, ob es echt ist.“","style":"deeskalierend","reaction":"„*atmet durch* Das hilft mir. Dann lass uns das prüfen. Wen könnte man fragen?“","feedback":"Sehr gut! Du erkennst an, dass ihr Wunsch („es soll nicht stimmen“) das Urteil färbt, und trennst Loyalität von der Sachfrage. Damit nimmst du Druck raus.","score":3,"nextStepId":"step-4-success"},{"text":"„Naja, wenn das Video echt ist, dann hast du dich eben in ihm getäuscht. Das passiert, und es ist besser, es jetzt zu erfahren als später.“","style":"frontal","reaction":"„*kühl* Das ist ja nett gesagt. Dann hat er mir vermutlich all die Jahre was vorgespielt, ja?“","feedback":"Zu hart und zu schnell: Du stellst ihre ganze Freundschaft infrage. Emotionen sind das Lenkrad, das die Wahl lenkt. Wer sie übergeht, löst Abwehr aus.","score":-1,"nextStepId":"step-3-struggle"},{"text":"„Ehrlich gesagt, ich weiß auch nicht, was ich davon halten soll. Lass uns das Thema einfach lassen, sonst streiten wir noch.“","style":"ausstieg","reaction":"„Ja, vielleicht ist das besser. Ich schreibe trotzdem in die Gruppe, dass das nur KI ist.“","feedback":"Der Ausstieg schützt das Gespräch, lässt aber die ungeprüfte Behauptung stehen. Nadine verbreitet sie weiter.","score":0,"nextStepId":"step-3-struggle"}]},"step-4-success":{"id":"step-4-success","speaker":"Nadine","speech":"„Zugespielt wurde es ja dem Vorstand. Vielleicht frage ich einfach dort, von wem das Video stammt und ob es jemand außer uns bestätigen kann. Ich schreibe nichts mehr in die Gruppe, bevor ich das weiß. Kommst du mit zum Training, wir reden dann weiter?“","options":[{"text":"„Gern. Und wenn sich herausstellt, dass es echt ist, bin ich da, falls du darüber reden willst. Und wenn es gefälscht ist, haben wir es dann wenigstens belegt.“","style":"deeskalierend","reaction":"„Danke, dass du mich nicht abgebügelt hast. Das war mir echt wichtig.“","feedback":"Perfekter Abschluss: Du bleibst offen für beide Ausgänge, hältst die Beziehung heil und hast die Prüfung über Quelle und Kontext verankert, nicht über Bauchgefühl oder Pauschalverdacht.","score":3}]},"step-3-struggle":{"id":"step-3-struggle","speaker":"Nadine","speech":"„Ich weiß nicht... das Ganze ist mir gerade zu viel. Ich habe einfach ein schlechtes Gefühl dabei.“","options":[{"text":"„Das verstehe ich, das ist ja auch ein unangenehmes Thema. Wie wäre es, wenn wir morgen kurz den Vorstand fragen, woher das Video stammt? Dann wissen wir mehr.“","style":"deeskalierend","reaction":"„Ja... das ist ein Plan. Ich schau mir das morgen in Ruhe an.“","feedback":"Guter Übergang: Du bietest einen konkreten, ruhigen nächsten Schritt an (Quelle klären) und lässt den Druck der Entscheidung weg.","score":2}]},"step-fail":{"id":"step-fail","speaker":"Nadine","speech":"„Ich schreibe jetzt in die Gruppe, dass das Video KI ist, und gut.“","options":[{"text":"Ende: Nadine fühlt sich nicht gehört oder wurde in ihrer ungeprüften Annahme bestärkt. Die Behauptung „ist KI“ geht ungeprüft in die Gruppe.","style":"ausstieg","reaction":"Beim nächsten Mal zuerst das Gefühl ernst nehmen, dann gemeinsam Quelle und Kontext prüfen.","feedback":"Frage dich: Wollte ich Nadine überzeugen oder gemeinsam mit ihr prüfen? Bei Loyalität wirkt Emotion als Lenkrad. Wer sie ignoriert, verliert den Zugang, wer ihr nachgibt, bestärkt die Lügner-Dividende.","score":0}]}},"status":"entwurf","familie":"bild-und-video-pruefen","fertigkeit":"F1","stufe":2,"kurz":"Dass es Fälschungen gibt, beweist nicht, dass eine bestimmte Aufnahme gefälscht ist. Wer die Fälschung behauptet, müsste sie belegen. Lenkt Loyalität das Urteil, hilft es, das Gefühl anzuerkennen und dann gemeinsam Quelle und Kontext zu prüfen.","prueffrage":"Welcher konkrete Hinweis auf eine Fälschung wurde genannt, und was ist darüber bekannt, wer das Video aufgenommen und weitergegeben hat?","quellen":[{"typ":"url","kurz":"Chesney, B.; Citron, D. (2019): Deep Fakes: A Looming Challenge for Privacy, Democracy, and National Security. California Law Review 107, 1753–1820","oeffentlich":true,"url":"https://www.californialawreview.org/print/deep-fakes-a-looming-challenge-for-privacy-democracy-and-national-security","abruf":"2026-10-12"},{"typ":"url","kurz":"Washington University in St. Louis, The Source (19.08.2024): Political deepfake videos no more deceptive than other fake news, research finds","oeffentlich":true,"url":"https://source.washu.edu/2024/08/political-deepfake-videos-no-more-deceptive-than-other-fake-news-research-finds/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Barari, S.; Lucas, C.; Munger, K. (2025): Political Deepfakes Are as Credible as Other Fake Media and (Sometimes) Real Media. The Journal of Politics 87(2), 510–526","oeffentlich":false,"seite":"S. 510"}],"thema":"Netz und Medien"},{"id":"scen-forum-sealioning","title":"Der höfliche Frager im Forum","subtitle":"Endlose „Nur-Fragen“, geübt mit der Ausstiegs-Strategie","character":"Nutzer „FrageNurHoeflich“","avatar":"🦭","context":"Du hast in einem Forum beiläufig geschrieben, dass du eine bestimmte Maßnahme sinnvoll findest. Seitdem meldet sich „FrageNurHoeflich“ unter jedem deiner Beiträge: stets freundlich, stets mit einer neuen Frage, nie mit einer Reaktion auf deine Antworten. Mehrere Leute lesen mit.","goal":"Erkenne die höfliche Belagerung, belege höchstens einmal, ziehe eine klare Grenze und steige ruhig aus, ohne die Person abzuwerten.","bereich":"Online","laenge":"lang","ton":"sarkastisch","bestehenAb":9,"lektion":"Wer behauptet, schuldet Belege, aber einmal und nicht endlos: Danach ist der Fragende am Zug, mit der Antwort zu arbeiten. Wer erkennt, dass jede Antwort nur die nächste Frage erzeugt, darf das Gespräch ruhig und begründet beenden. Das ist kein Rückzug, sondern ein Urteil über das Spiel. Seziert wird die Taktik, nicht der Mensch.","toolRef":"H.2.4","faktenRef":"D.3.9","startStepId":"step-1","steps":{"step-1":{"id":"step-1","speaker":"Nutzer „FrageNurHoeflich“","speech":"„Hallo! Ich frage nur ganz höflich nach: Du hast hier so selbstsicher geschrieben, die Maßnahme sei sinnvoll. Hast du dafür eine Quelle? Ich möchte das nur verstehen. Wer öffentlich etwas behauptet, kann das ja sicher belegen, oder?“","options":[{"text":"„Ich muss dir gar nichts belegen. Such dir selbst was, dafür gibt es Suchmaschinen.“","style":"frontal","reaction":"„Oh. Schade. Ich hatte eine ganz sachliche Frage gestellt. Aber wenn du sie nicht beantworten kannst, ist das ja auch eine Antwort. Die anderen Leser sehen das sicher auch so.“","feedback":"Schwach. Eine erste, vernünftig klingende Quellenfrage verdient eine Antwort, denn Nachfragen gehört zum Skeptizismus. Mit der Verweigerung lieferst du die Vorlage für „Sieh, er kann es nicht begründen“ (Red Flag aus).","score":-1,"nextStepId":"step-2-defensive"},{"text":"„Gern. Hier ist die Quelle, die mich überzeugt hat, und kurz, was sie aus meiner Sicht zeigt. Sag mir gern, was du davon hältst.“","style":"sokratisch","reaction":"„Danke für die Quelle! Interessant. Und hast du noch eine zweite? Eine einzige reicht ja nicht, finde ich.“","feedback":"Gut: Beim ersten Mal belegst du, ohne Druck. Das ist die Pflicht des Behauptenden, und du lädst zugleich zur Arbeit mit dem Beleg ein. Beobachte jetzt, was als Nächstes passiert: Geht er auf die Quelle ein oder kommt nur die nächste Forderung?","score":3,"nextStepId":"step-2-probe"},{"text":"„Natürlich habe ich Quellen, und zwar Dutzende! Ich liefere dir gleich zwanzig Studien nach, dann ist Ruhe.“","style":"affektiv","reaction":"„Zwanzig! Wunderbar, dann fang doch bitte gleich mit der ersten an und erkläre sie mir Punkt für Punkt. Ich habe Zeit.“","feedback":"Du lässt dich auf die Asymmetrie des Aufwands ein: Eine Frage kostet Sekunden, eine belegte Antwort Stunden. Wer jede Frage beantworten will, bezahlt immer mehr.","score":-2,"nextStepId":"step-2-overwhelm"}]},"step-2-probe":{"id":"step-2-probe","speaker":"Nutzer „FrageNurHoeflich“","speech":"„Noch eine Quelle bitte. Und was genau meinst du mit „sinnvoll“? Das ist doch ein sehr dehnbarer Begriff. Bevor ich darauf eingehe, müsste ich das präzise wissen.“","options":[{"text":"„Ich habe dir eine Quelle genannt. Was hat dich an ihr nicht überzeugt, und was wäre für dich ein ausreichender Beleg?“","style":"sokratisch","reaction":"„Hm. Das ist ja gerade die Frage an dich. Wir sollten nicht abschweifen. Also: zweite Quelle?“","feedback":"Treffend: die Rückfrage-Probe aus „Sealioning“. Ein ehrlicher Fragender kann beantworten, was ihn nicht überzeugt hat. Wer stattdessen ausweicht, zeigt das Muster: keine Arbeit mit der Antwort, nur die nächste Forderung.","score":3,"nextStepId":"step-3-evade"},{"text":"„Mit „sinnvoll“ meine ich, dass der Nutzen die Kosten überwiegt. Hier noch ein zweiter Link. Wenn du den auch durchgearbeitet hast, reden wir weiter.“","style":"deeskalierend","reaction":"„Oh, danke! Ich schaue mal. Aber was heißt „überwiegt“? Wer legt fest, wie man das misst? Das müsstest du mir schon erläutern.“","feedback":"Brauchbar: Du lieferst noch einmal und knüpfst eine Bedingung. Der Haken: Du gibst weitere Belege, bevor überhaupt jemand mit dem ersten gearbeitet hat. So füttert man die Belagerung.","score":1,"nextStepId":"step-3-evade"},{"text":"„Du spulst die immer gleiche Masche ab, oder? Ich sehe schon, wohin das führt: Du bist doch bloß ein Troll mit Höflichkeitsmaske.“","style":"sarkastisch","reaction":"„Ich bin erschüttert. Ich habe nur höflich gefragt, und du greifst mich persönlich an. Das sagt wohl alles über deine Gesprächskultur.“","feedback":"Schwach: Mit dem persönlichen Vorwurf wirst du zum „Unhöflichen“, und genau das ist der rhetorische Nebengewinn der Taktik. Benenne das Muster, nicht den Menschen.","score":-2,"nextStepId":"step-fail"}]},"step-2-defensive":{"id":"step-2-defensive","speaker":"Nutzer „FrageNurHoeflich“","speech":"„Ich will nur eine Quelle. Ist das zu viel verlangt? Offenbar kann man hier keine vernünftige Diskussion führen. Aber ich frage trotzdem weiter, bis jemand antwortet.“","options":[{"text":"„Fair genug, das war zu schroff von mir. Hier ist die Quelle, und ich sage dazu, was sie aus meiner Sicht zeigt. Welchen Teil siehst du anders?“","style":"deeskalierend","reaction":"„Na also, geht doch. Danke. Aber eine Quelle genügt mir nicht. Hast du noch eine, die das Gleiche sagt?“","feedback":"Gute Korrektur: Du holst den Beleg nach und lenkst auf den Inhalt. Mit der Frage, was er anders sieht, prüfst du, ob mit der Antwort gearbeitet wird.","score":2,"nextStepId":"step-3-evade"},{"text":"„Nein, ich beantworte nichts mehr. Wer so fragt, will keine Antwort, sondern Streit, und darauf habe ich keine Lust.“","style":"frontal","reaction":"„Wie bitte? Ich habe mich die ganze Zeit höflich verhalten! Sicher lesen das gerade einige Leute mit.“","feedback":"Der Impuls ist nachvollziehbar, aber du unterstellst Absicht, ohne die Rückfrage-Probe gemacht zu haben. Das hilft nur seinem Bild vom „unfairen Gegenüber“.","score":-1,"nextStepId":"step-fail"},{"text":"„Bevor ich eine Quelle suche: Sag mir erst, was für dich als Beleg zählt, sonst suche ich ins Blaue. Dann liefere ich dir gern etwas Passendes.“","style":"sokratisch","reaction":"„Ach, das ist doch jetzt Ausweichen. Ich frage, du antwortest, so läuft das normalerweise. Also bitte: die Quelle.“","feedback":"Im Ansatz richtig, die Rückfrage-Probe. Nach deiner schroffen ersten Reaktion wirkt sie aber wie Ausweichen. Besser: erst einmal belegen, dann zurückfragen.","score":1,"nextStepId":"step-3-evade"}]},"step-2-overwhelm":{"id":"step-2-overwhelm","speaker":"Nutzer „FrageNurHoeflich“","speech":"„Hm, deine erste Studie. Wie genau wurde da gemessen? Und was bedeutet das Wort dort in der Zusammenfassung? Und wo sind die anderen neunzehn? Ich warte geduldig.“","options":[{"text":"„Moment. Ich habe dir etwas geliefert, du hast nicht gesagt, was du davon hältst. Wo stehen wir? Was in meiner Antwort hat dich nicht überzeugt?“","style":"sokratisch","reaction":"„Das lässt sich ja gar nicht so leicht beantworten. Ich möchte zunächst alle Studien sehen, ehe ich mich festlege.“","feedback":"Gute Wende: Du holst dir den Rahmen zurück. Wer „erst alles sehen will“, bevor er Stellung nimmt, arbeitet nicht mit der Antwort.","score":3,"nextStepId":"step-3-evade"},{"text":"„Okay, ich schreibe dir zu jeder Studie einen ausführlichen Absatz. Das dauert ein paar Stunden, ist aber kein Problem.“","style":"affektiv","reaction":"„Wunderbar, ich freue mich! Und danach habe ich noch ein paar Rückfragen.“","feedback":"Du investierst Stunden in ein Spiel ohne Gegenleistung. Genau diese Asymmetrie macht die Belagerung billig für den Angreifer und teuer für dich.","score":-2,"nextStepId":"step-fail"},{"text":"„Das war überzogen von mir, ich habe zu viel versprochen. Lass uns bei der einen Studie bleiben: Was zeigt sie deiner Meinung nach, was nicht?“","style":"deeskalierend","reaction":"„Sehr schön, dass du zurückrudern kannst. Aber ich bin ja nur der Fragende. Wie ist denn deine Position genau zu dem, was ich eben gefragt habe?“","feedback":"Brauchbar: Du verkleinerst den Umfang und lenkst zurück auf eine Quelle. Wieder prüfst du, ob er mit der Antwort arbeitet.","score":1,"nextStepId":"step-3-evade"}]},"step-3-evade":{"id":"step-3-evade","speaker":"Nutzer „FrageNurHoeflich“","speech":"„Ich bin da offen für alles. Aber noch eine Frage zuvor: Warum bist du plötzlich so ausweichend? Man könnte fast meinen, du hast Angst vor meinen Fragen. Wer sich sicher ist, antwortet doch gern, oder?“","options":[{"text":"„Ich habe geantwortet und belegt, du bist auf nichts davon eingegangen. Wir können weitermachen, sobald du sagst, was an meiner Antwort nicht überzeugt.“","style":"sokratisch","reaction":"„Das ist doch wieder nur ein Ausweichmanöver. Ich stelle die Fragen, du beantwortest sie. So funktioniert eine offene Diskussion, finde ich.“","feedback":"Klar und ruhig: Du erinnerst an die Spielregel „Wer fragt, arbeitet mit der Antwort“. Die Reaktion zeigt, dass das Gegenüber diese Regel nicht mitspielt.","score":2,"nextStepId":"step-4"},{"text":"„Ich habe keine Angst, ich habe nur keinen Bock mehr, mich von dir ausfragen zu lassen wie vor Gericht.“","style":"affektiv","reaction":"„Siehst du, genau das meine ich: Sobald es unbequem wird, wird es persönlich. Dabei möchte ich doch nur lernen.“","feedback":"Verständlich, aber du gibst ihm das Bild vom „Gereizten“. Ohne Bezug auf das Muster bleibt es ein Gefühlsausbruch statt eines Grenzsatzes.","score":-1,"nextStepId":"step-4"},{"text":"„Wenn ich mich sicher fühle, muss ich nicht jede Frage beantworten. Dass du das Muster hier fährst, fällt auch anderen Mitlesern auf.“","style":"frontal","reaction":"„Welches Muster denn? Ich frage nur. Du bist offenbar nicht bereit zur Diskussion, das ist schade, aber ich lasse dich nicht vom Haken.“","feedback":"In der Sache gar nicht falsch, aber der Hinweis auf „andere Mitleser“ wirkt wie ein Publikumsspiel. Benenne das Muster direkt und sachlich, wie im Spiegel-Skript (Skript 2).","score":0,"nextStepId":"step-4"}]},"step-4":{"id":"step-4","speaker":"Nutzer „FrageNurHoeflich“","speech":"„Ich sehe, wir sind nicht auf einer Linie. Trotzdem: Noch eine einzige Rückfrage. Wer legt eigentlich fest, was eine „gute Quelle“ ist? Das müsstest du mir bitte erst klären, bevor ich dir irgendetwas zugestehe.“","options":[{"text":"„Ich habe deine Frage belegt beantwortet und gefragt, was dich nicht überzeugt. Darauf gingst du nicht ein, es kam nur die nächste Frage. Das ist kein Gespräch, sondern Belagerung. Ich steige aus.“","style":"ausstieg","reaction":"„Wie bitte? Du läufst also weg? Ich wollte doch nur ... naja. Sicher kannst du es einfach nicht begründen.“","feedback":"Treffer: Der Spiegel (Skript 2) benennt die Taktik ohne Beleidigung, und der Ausstieg braucht keine Rechtfertigung. Ein Gespräch zu beenden, das keines ist, ist kein Rückzug, sondern ein Urteil.","score":3,"nextStepId":"step-success"},{"text":"„Klar, ich schreibe dir gleich ein ganzes Seminar ‚Quellenkunde für Fortgeschrittene‘, mit Abschlussprüfung und Zertifikat, natürlich auf meine Kosten und in meiner Freizeit.“","style":"humorvoll","reaction":"„Fabelhaft, ich bin gespannt! Und danach schauen wir, ob ich damit einverstanden bin.“","feedback":"Humor hilft nicht, wenn die nächste Frage ohnehin kommt. Du kündigst Aufwand an für jemanden, der mit keiner Antwort arbeitet.","score":-1,"nextStepId":"step-struggle"},{"text":"„Ich antworte dir noch einmal in einem Satz und mache dann eine Pause. Sag mir bitte, ob mein letzter Satz zu einer Zustimmung oder einem konkreten Einwand führt.“","style":"deeskalierend","reaction":"„Ich bin offen für alles. Aber zuerst brauche ich noch eine Klarstellung, was du mit „Pause“ meinst. Das Ganze wirkt ein bisschen ausweichend.“","feedback":"Ein letzter Versuch mit Rahmen ist nachvollziehbar, aber die Reaktion zeigt wieder das Muster. Der Moment für klare Grenzziehung ist erreicht.","score":1,"nextStepId":"step-struggle"}]},"step-success":{"id":"step-success","speaker":"Nutzer „FrageNurHoeflich“","speech":"„Nun gut. Ich lasse den Strang trotzdem offen, falls du doch noch antworten möchtest. Die Fragen stehen ja noch im Raum.“","options":[{"text":"„Tu das. Ich habe belegt, was ich belegen wollte, und bin bei Gesprächen mit echter Auseinandersetzung jederzeit wieder dabei. Hier bin ich fertig.“","style":"ausstieg","reaction":"*Der Strang bleibt offen, deine Antwort ist die letzte sichtbare. Keine Rechtfertigung, kein Streit, kein Schlammkampf.*","feedback":"Elegant: ruhig, begründet, ohne Abwertung. Du hast einmal belegt, die Taktik benannt und die Energie geschützt, ohne dass du dich vor Zuschauern rechtfertigen musstest.","score":3}]},"step-struggle":{"id":"step-struggle","speaker":"Nutzer „FrageNurHoeflich“","speech":"„Noch eine Frage, nur eine: Wie definierst du „ausweichend“? Ich möchte sichergehen, dass wir dieselben Begriffe verwenden, bevor wir fortfahren.“","options":[{"text":"„Ich habe genug Zeit investiert. Ich beende das Gespräch hier und lasse den Strang so stehen. Ich bin gern wieder dabei, wenn echter Austausch möglich ist.“","style":"ausstieg","reaction":"„Schade, ich hätte gern weitergemacht. Vielleicht ein anderes Mal.“ *Die Fragen bleiben unbeantwortet im Strang stehen.*","feedback":"Gut, wenn auch spät: Du ziehst die Grenze, ohne die Person abzuwerten. Früher wäre es leichter gewesen, aber der Ausstieg ist nie falsch, sobald das Muster klar ist.","score":2}]},"step-fail":{"id":"step-fail","speaker":"Nutzer „FrageNurHoeflich“","speech":"„Ich bin wirklich bestürzt, wie schnell hier die Fassung verloren wird. Ich habe nur höflich gefragt. Aber vielleicht ist das hier einfach kein Ort für offene Fragen.“","options":[{"text":"Ende: Das Gespräch endet im Streit. Du stehst als der Gereizte da, und die Taktik ist aufgegangen.","style":"ausstieg","reaction":"*Der Strang endet mit seinem letzten Beitrag. Mehrere Mitleser markieren ihn mit „gefällt mir“.*","feedback":"Der Schaden entsteht, wenn du dich in Rechtfertigung oder Angriff ziehen lässt. Beim nächsten Mal: einmal belegen, dann die Rückfrage-Probe, dann ruhig und begründet aussteigen, ohne die Person abzuwerten.","score":0}]}},"status":"entwurf","familie":"kraefte-und-ausstieg","fertigkeit":"F3","stufe":3,"kurz":"Wer etwas behauptet, schuldet einen Beleg, aber einmal und nicht endlos: Danach ist der Fragende am Zug, auf die Antwort einzugehen. Erzeugt jede Antwort nur die nächste Frage, darf man das Gespräch ruhig und begründet beenden, ohne die Person abzuwerten.","prueffrage":"Auf wie viele der gelieferten Antworten und Belege ist der Fragende tatsächlich eingegangen, und wie viele neue Fragen kamen stattdessen?","quellen":[{"typ":"url","kurz":"Johnson, A. (2017): The Multiple Harms of Sea Lions. In: Perspectives on Harmful Speech Online. Berkman Klein Center for Internet & Society, Harvard University","oeffentlich":true,"url":"https://cyber.harvard.edu/sites/cyber.harvard.edu/files/2017-08_harmfulspeech.pdf","seite":"S. 13","abruf":"2026-10-12"},{"typ":"url","kurz":"Malki, D. (2014): The Terrible Sea Lion. Wondermark Nr. 1062, 19.09.2014","oeffentlich":true,"url":"https://wondermark.com/c/1062/","abruf":"2026-10-12"}],"thema":"Netz und Medien"}]`);export{e as t};